INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/05/IYKF3INYPRG55F2QXZT7NJ3THU/', 'https://www.chosun.com/politics/politics_general/2026/07/05/IYKF3INYPRG55F2QXZT7NJ3THU/', '정치', '靑 “반도체 추가세수로 ‘미래 대응 기금’ 신설 추진”', '', '강훈식 대통령 비서실장은 5일 “이재명 정부는 추가 세수를 미래 세대를 위한 투자 재원으로 활용하기 위해 미래 대응 기금 신설을 추진하고자 한다”고 했다. 강 실장은 이날 총리 공관에서 열린 고위 당정 협의회에서 “추가 세수로 기금을 조성해 3대 메가 프로젝트 지원을 포함한 미래 성장 동력 창출, K자형 양극화 대응, 2030 청년을 위한 주거와 창업·일자리 지원 등 대한민국의 미래에 과감한 투자를 하고자 한다”며 이같이 말했다. 강 실장은 “미래 대응 기금 신설은 ‘대체 불가 대한민국’ 실현의 초석이 될 것”이라면서 “속도감 있게 추진될 수 있도록 당정의 협력을 당부드린다”고 했다. 반도체 호황으로 내년까지 더 걷힐 것으로 예상되는 세금은 최대 100조원 안팎에 이를 것이라는 전망이 나온다. 이 돈을 가장 효과적으로 활용하기 위한 방안에 대한 여러 의견이 나왔다. 청와대 내에서 ‘국민 배당금’ 언급이 나왔고, 경제계 일각에서는 나라 빚을 갚는 데 일부를 활용해야 한다는 의견도 있었다. 그런 가운데 강 실장이 새로운 기금 신설 추진 방침을 밝힌 것이다. 강 실장은 “대한민국의 미래를 좌우할 절체절명의 시기에 반도체 호황 등으로 발생한 추가 세수를 허투루 써서는 안 될 것”이라고 했다. 이날 고위 당정에서는 이재명 대통령이 지난달 29일 청와대에서 발표한 반도체, 인공지능(AI) 데이터센터, 피지컬AI 등 ‘3대 메가 프로젝트’ 추진 방안이 집중 논의됐다. 강 실장은 3대 메가 프로젝트에 대해 “대한민국의 20∼30년 미래를 결정할 새로운 성장 동력을 설계하는 일”이라며 “집권 2년 차는 ‘대체 불가 대한민국’을 속도감 있게 구현해 국민이 체감할 성과를 창출할 시점이고, 3대 메가 프로젝트가 그 역사적 시발점이 될 것”이라고 했다. 한병도 더불어민주당 대표 직무대행 겸 원내대표는 3대 메가 프로젝트 조기 현실화에 “당정이 모든 역량을 쏟아야 한다”며 “필요한 입법과 예산을 촘촘히 지원하겠다”고 했다. 한 직무대행은 야당에서 반대하는 패스트트랙(신속 처리 안건) 기간 단축, 필리버스터 요건 강화은 강행 의사를 거듭 밝혔다.', 'crawl', '조선일보', '2026-07-05 08:05:51', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MF245DP33ZO3JJLLBT4UJB6BUI.jpg', '2026-07-05 10:45:05', '2026-07-05 20:01:58.700737', '미래 대응 기금 신설 추진 발표');
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/05/P5PKXXVVQZFPTG25E65IHRHTCQ/', 'https://www.chosun.com/politics/assembly/2026/07/05/P5PKXXVVQZFPTG25E65IHRHTCQ/', '정치', '당정 “AI센터 전력·인허가 전폭 지원…‘추가’ 세수 활용”', '', '당정은 반도체·인공지능(AI) 데이터센터·피지컬 AI를 전략사업으로 집중 육성하는 ‘대한민국 대도약 3대 메가프로젝트’를 위해 ‘미래대응기금’을 신설하겠다고 5일 밝혔다. 이날 서울 국무총리 공관에서 열린 고위당정협의회에서 3대 메가프로젝트 추진 방향과 하반기 국정 운영 방향 및 중점 추진 법안 입법 전략이 논의됐다. 회의가 끝난 뒤 강준현 더불어민주당 수석대변인은 “추가 세수를 미래세대와 대한민국 성장동력 양극화 대응 등에 사용하겠다는 정부 입장에 공감한다”며 “당정청은 3대 메가 프로젝트 지원과 미래 대응 기금 신설 등을 긴밀히 협력해나갈 것”이라고 했다. 이날 회의에서 기획예산처는 ‘초과 세수’ 대신 ‘추가 세수’라는 표현을 썼다고 한다. 기금에서 운용하는 액수 등은 아직 확정되지 않았다. 강 수석대변인은 이날 “AI데이터센터 구축에 차질이 발생하지 않도록 전력 부지 인허가를 전폭적으로 지원하고, AI 데이터센터 및 피지컬AI를 독보적인 수출산업으로 육성하기 위한 지원사업도 적극 추진 예정”이라고 했다. 또 “대규모 전력 수요 대응위해 전력 인프라를 선제적 확충하고 용수를 안정적으로 공급하기 위해 다중 수원체계를 구축하기로 했다”고도 했다.', 'crawl', '조선일보', '2026-07-05 09:46:30', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GY2TQZTEHBSDIMLDMEYWGZTFGY.jpg', '2026-07-05 10:45:05', '2026-07-05 20:02:47.651147', '미래대응기금 신설 발표');
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/05/MK3GNC3NFBA3DIGA47EWPZONDA/', 'https://www.chosun.com/politics/assembly/2026/07/05/MK3GNC3NFBA3DIGA47EWPZONDA/', '정치', '윤상현 “올림픽공원 개표소 투표지 247만장 공개 재검표 추진”', '', '국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 위원장인 국민의힘 윤상현 의원은 5일 6·3 지방선거 투표용지 부족 사태와 관련해, 서울 올림픽공원 핸드볼경기장에 보관 중인 247만표에 대한 ‘공개 재검표’를 추진할 계획이라고 밝혔다. 윤 의원은 이날 국회 기자회견에서 “지지난주부터 위철환 중앙선거관리위원장 직무대행에게 247만표 유·무효표에 대해 공개적으로 재검증하자고 했다”며 “선관위 입장에서도 그것에 대해 잘못된 투·개표가 없다는 것을 보여줘야 하지 않느냐”고 했다. 윤 의원은 “(선관위가 경기장을) 임차하는 비용이 7월 10일까지 약 2억원이 든다고 하는데, 사람들을 동원해 재검표하는 데 5000만원 정도가 들 것으로 예상된다”며 “계속해서 임차하면서 비용이 드는 것보다 한 번에 정확히 재검표하는 것이 그것(봉쇄된 투표함)을 옮길 명분도 생기는 게 아닌가 생각한다”고 했다. 윤 의원은 이 같은 제안을 특위 여야 간사에게 협의해 달라고 요청했다고 밝혔다. 그는 “여야 간사 간 협의를 해 달라고 요청해 곧 결론이 나올 것으로 본다”며 “지난주 중앙선관위 기관 보고에서 강동완 사무총장 대행도 ‘좋다, 하겠다’는 의견을 제시했다”고 했다. 한편 윤 의원은 오는 7일 예정된 중앙선관위·서울시선관위 현장 조사에서는 ‘본투표 50% 인쇄 축소 결정 과정’과 ‘지휘·보고 체계 누락’ 문제를 집중적으로 들여다보겠다고 밝혔다. 윤 의원은 “인쇄 축소 결정 과정이 작년 11월 노태악 선관위원장을 필두로 전체 회의가 있었고 40페이지 분량의 보고서에 적시돼 있었는데, 이를 기억하는 사람은 2명뿐이고 나머지 7명은 보고받은 기억조차 못 한다”고 했다. 그러면서 “투표지에 관한 것을 중앙선관위 규칙으로 제정하지 않고 위임 전결 규정으로 한 문제 등을 살필 것”이라고 했다.', 'crawl', '조선일보', '2026-07-05 08:48:48', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MNSTMMJSGA3GIMRVMMZWEM3CGI.jpg', '2026-07-05 10:45:05', '2026-07-05 20:02:16.448444', '올림픽공원 개표소 투표지 공개 재검표 추진');
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (9, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/05/DNMDVA2QDNH2ZK6UTRZZ5EL6LQ/', 'https://www.chosun.com/politics/politics_general/2026/07/05/DNMDVA2QDNH2ZK6UTRZZ5EL6LQ/', '정치', '‘5·18 몰이해’ 청년 세대에 가차 없는 여권', '', '고교야구 배재고의 ‘스타벅스 야유 응원’을 둘러싼 논란이 계속 커지고 있습니다. 배재고 선수들은 지난달 29일 청룡기 고교 야구 대회에서 광주제일고와 경기 중 덕아웃에서 ‘가야지 가야지 스타벅스 가야지’라는 야유성 응원 구호를 외쳤습니다. 광주제일고 측의 거듭된 항의로 뒤늦게 야유를 멈췄지만 ‘광주와 5·18을 비하했다’는 호된 비판을 받았습니다. 호남 지역 사회와 여권에선 “5·18 비하는 용납할 수 없는 일”이라며 일벌백계를 외쳤습니다. 민주당 의원들은 “철저한 진상조사와 처벌”을 요구했고, “배재고 야구팀을 해체하라”고도 했습니다. 대한야구소프트볼협회는 지난 1일 ‘6개월 출전 정지’라는 중징계 결정을 내렸습니다. 하지만 야구계와 야권에선 “어린 선수들이 한번 실수로 선수 생명이 끝날 수 있다”며 너무 가혹한 징계 아니냐는 동정론이 나오고 있습니다. 6개월 출전 정지 징계를 받으면 올해 고교 야구 대회 출전은 어려워집니다. 사실상 시즌 아웃입니다. 고3 선수들은 대학 진학이나 프로팀 진출 길이 막힐 수 있습니다. 국민의힘 의원들은 “배재고 선수들의 행동은 분명 잘못된 일이고 징계를 받아야 하지만 어린 학생들의 선수 생명을 끊는 건 너무 가혹하다”며 재고를 요구하고 있습니다. 배재고 교장과 감독도 광주제일고에 사과의 뜻을 밝히며 선처를 호소했고, 배재학당 총동창회도 대한야구소프트볼협회에 탄원서를 제출했습니다. 협회 측은 “원칙대로 결정한 일”이라는 입장입니다. 여권과 호남 지역 여론도 “5·18 폄하는 용서할 수 없는 일”이라며 완강합니다. 이병태 규제합리화위 부위원장이 “5·18이 성역화됐다”고 비판했지만, 청와대는 “부적절한 처신”이라며 엄중 경고했습니다. 지난 5월 스타벅스의 ‘5·18 탱크데이’ 마케팅 논란에 이어 이번에 또 5·18 비하 사건이 터진 만큼 재발 방지를 위해서도 그냥 넘어갈 수 없다는 것입니다. 지난달 29일 목동 야구장에서 열린 배재고와 광주일고 간 경기에서 일어난 상황은 이랬습니다. 경기 도중 배재고 선수들이 덕아웃에서 갑자기 ‘가야지 가야지 스타벅스 가야지’라는 야유성 응원을 시작했습니다. 이는 야구장에서 가끔씩 나오는 응원 구호를 변형한 건데요. 우리 편에 대해선 ‘가야지 안타 치고 가야지’라고 합니다. 반면 상대 팀에는 ‘가야지 집에 가야지’라고 합니다. 경기 질 테니 빨리 집에 가라는 뜻입니다. 일부 학생은 “탱크데이”라고 외치기도 했습니다. 스타벅스가 ‘5·18 탱크데이’ 홍보로 사회적 논란을 빚었잖습니까. 그래서 광주일고 선수들에게 ‘경기 지고 스타벅스나 가라’고 야유한 겁니다. 광주일고 측에서 “지금 뭐 하는 거냐”고 강하게 항의했고 배재고 선수들은 뒤늦게 구호를 중단했습니다. 하지만 광주일고는 이를 대한야구소프트볼협회에 제소했습니다. 사태가 커지자 배재고 교장과 감독, 선수들이 광주일고를 찾아가 사과하겠다고 했습니다. 하지만 광주일고 측은 “학생들이 받은 상처가 크다”며 거절했습니다. 6개월 출전 정지 중징계가 내려진 후 배제고 야구부 선수들은 오는 6일 광주제일고를 찾아가 정식으로 사과한 뒤 5·18 민주묘지에 참배하기로 했습니다. 이번 배재고 야유 응원 사태는 여야 정치권이 나서면서 불길이 더 커졌습니다. 여당 의원들은 사건 초반부터 진상 조사와 처벌을 요구했는데요. “스타벅스 마케팅과 똑같다” “학폭으로 다뤄 엄벌해야 한다”고 했고요. “야구팀을 해체하라”고도 했습니다. “10대의 극우화, 일베화 현상이 위험수위다” “특별 역사 교육을 실시하라”고도 했죠. 이에 대해 야당은 “배재고 선수들 행동이 부적절했지만 선수 생명까지 끊을 일이냐”고 했는데요. “스타벅스도 영업 정지를 당하지 않았다” “배재고 선수들이 모두 야유 응원에 참여한 것도 아니지 않느냐” “탱크로 밀어버려야 한다고 말한 좌파 유튜버도 계속 방송 중인데 왜 학생들만 가혹하게 중징계하느냐”고 했습니다. 아이들 싸움이 어른 싸움 된다는 말이 있죠. 정치권이 싸움을 더 키운 것입니다. 배재고 선수들뿐 아니라 배재고 감독과 코칭 스태프, 학교, 협회 측의 책임도 크다는 지적이 나옵니다. 고교 야구에선 경기 중 상대 신경을 긁는 구호를 외치는 경우가 종종 있는데요. 감독과 코칭 스태프가 학생들의 잘못된 행동을 선제적으로 제지했어야 합니다. 그런데 그러지 못했습니다. 어린 선수들이 5·18의 역사적 의미나 무게를 온전히 알았는지는 의문입니다. 그런 상태에서 선거 때 일었던 스벅 논란을 무작정 상대 야유에 이용했을 가능성이 큽니다. 여기엔 스포츠맨십과 인성·역사 교육을 하지 못한 학교와 협회의 책임도 있습니다. 그런데 선수들에게만 책임을 지웠다는 지적이 나옵니다. 선수들 행동이 분명 잘못됐지만 징계 6개월은 흔치 않은 중징계라고 야구계에선 얘기합니다. 최근 들어 5·18 역사 갈등이 되풀이되고 있지만, 이를 해소할 대응책은 보이지 않습니다. 1차 스타벅스 논란 때 정부와 여권에선 “기업의 역사 인식 부족과 상업주의”를 탓하는 목소리가 컸습니다. 하지만 스타벅스에 대한 과도한 비판과 불매 운동이 이어지자 2030 세대들 사이에선 “스타벅스를 악마화한다” “너무 심한 것 아니냐”는 반발 목소리가 나왔습니다. 지방선거에서 스벅 역풍이 불었다는 평가도 있었죠. 이번에도 인터넷과 SNS상에선 “선수들 행태가 심했다”는 비판과 “징계가 과도하다”는 목소리가 맞서 있습니다. 그런데 여야가 이런 갈등을 해결하기는커녕 오히려 정치적으로 증폭시키고 있는데요. 지나친 정치화는 역풍을 부를 수 있습니다. 이런 상황에서 대통령 직속 규제합리화위원회 이병태 부위원장이 “5·18이 성역화됐다”고 말하면서 파문은 더 커지고 있습니다. 이재명 대통령이 임명한 이 부위원장은 “고교 야구 라이벌전에서 스타벅스 논란을 경쟁팀 조롱에 활용했다는 학생들의 일탈을 처리하는 우리 사회의 모습은 무엇인가”라면서 “역사의 성역화로 어린 학생들의 장난에 가까운 일탈도 수용이 안 되고 어른들의 정치가 됐다”고 했습니다. 이 부위원장은 “이 모습은 대한민국보다 김일성 사진이 나온 신문이 비에 젖는 것을 보고 울부짖는 북한의 모습”이라고도 했습니다. 스타벅스 사태에 이어 배재고 사건에 대한 여권의 대응 방식을 비판한 것입니다. 이에 대해 청와대는 “정부 소속 기관의 책임 있는 위치의 사람으로서 부적절한 처신”이라며 ‘엄중 경고’ 조치했습니다. 강유정 대변인은 “이 부위원장이 개인적 의견을 SNS에 게시했는데, 이는 혐오와 조롱에 대한 정부의 단호한 거부 기조와 달리 오해의 소지가 있다”고 했습니다. 민주당 최민희 의원은 이 부위원장의 ‘5·18 성역화’ 발언에 “성역이 맞다”고 했습니다. 청와대와 여권이 이번엔 이 부위원장에게 화살을 겨눈 것입니다. 잦아들 것 같던 배재고 사태가 여권 내부 갈등과 좌우 논쟁으로 번질 조짐입니다. 연이은 5·18 비하 논란에 많은 광주시민이 깊은 마음의 상처를 받았을 것입니다. 비도덕적인 상대 폄하 행위가 재발되는 것도 막아야 합니다. 그런 측면에서 여권이 일벌백계를 요구하며 강하게 반응하는 것은 이해할 만한 일입니다. 다만 잘못을 저지른 사람이 10대 고교생이라는 점은 감안할 필요가 있습니다. 배재고 선수들이 5·18의 역사적 의미와 무게를 제대로 인식하지 못한 상태에서 시중에 떠도는 스타벅스 논란을 패러디했을 가능성이 적잖습니다. 자칫 선수 생명이 끝날 수 있는 6개월 출전 정지 징계는 가혹하게 여겨질 수 있습니다. 야구계에선 어린 학생들이 우발적으로 잘못을 저질렀다는 점, 야유 응원에 가담하지 않은 선의의 피해 학생도 있을 수 있다는 점을 고려해 선처해 주는 것이 어떠냐는 얘기가 나옵니다. 학생들을 엄하게 계도하되 징계 수위는 낮춰줄 필요가 있다는 것입니다. 지난 ‘5·18 탱크데이’ 논란 때 여권은 스타벅스를 ‘5·18 역사 의식도 없는 저질 장사치’로 몰아붙였습니다. 이 대통령은 “비인간적 막장 행태”라고 했습니다. 세월호 10주기에 스타벅스가 ‘사이렌 머그 마케팅’한 것까지 비판하면서 “(강성 보수 사이트) 일베 폐쇄도 검토할 필요가 있다”고 했습니다. 민주당도 스타벅스에 몰매에 가까운 비판을 쏟아내며 ‘스타벅스 자제령’을 내렸고, 지지자들은 불매 운동에 나섰습니다. 이번에도 여권 인사들은 배재고 선수들에 대한 중징계와 무관용을 주장하고 있습니다. 2030의 역사 인식 부족을 지적하면서 ‘특별 역사 교육’ 필요성도 얘기합니다. 하지만 국민의힘에선 “여권이 스타벅스엔 몰매를 가하고, 배재고엔 일벌백계를 요구하면서 2030은 극우로 몰고 있다”고 비판합니다. 여권의 말대로 5·18에 대해 청년층의 이해가 부족한 것은 맞습니다. 1990년대 이후 태어난 청년 세대 상당수는 5·18 민주화 운동의 의미와 학살 피해자들의 아픔을 제대로 알지 못합니다. 하지만 전문가들은 “MZ 청년 세대가 5·18을 제대로 이해하지 못하는 것은 586 운동권 세대가 6·25의 아픔과 참상을 잘 알지 못했던 것과 유사하다”고 지적합니다. 586 세대도 6·25의 비극과 가난한 시절 보릿고개를 얘기하는 산업화 부모 세대를 제대로 이해하지 못하고 공감하지 못했다는 것입니다. 그런데 지금 와서 젊은 세대가 586 운동권의 핵심 가치인 5·18 정신을 가볍게 여긴다고 화만 낼 일은 아니라는 것입니다. 청년 세대들의 ‘5·18 몰이해’가 문제이긴 하지만, 그렇다고 가차 없는 잣대를 들이대며 ‘무관용’을 외치는 것은 현명한 대응 방식이 아니라는 것입니다. 5·18을 폄하하는 일부 MZ 세대들의 행태를 꾸짖되 그들이 역사적 의미를 제대로 이해하게끔 계도하고 교육하는 노력이 필요합니다. 무조건 일벌백계를 외치고 무관용 노선으로 나간다고 문제가 해결되지는 않습니다. 586 세대의 운동권적 시각으로 청년층을 재단한다면 오히려 단절과 갈등만 커질 수 있습니다. 여권의 과도한 스타벅스 때리기가 오히려 2030 세대의 반발을 부른 측면도 있습니다. 일부 2030 세대는 “왜 내 커피 취향까지 정치권이 관여하느냐”고 말합니다. 이로 인해 지방선거에서 역풍이 불었다는 평가도 없지 않습니다. 과도한 처벌과 대응이 항상 좋은 결과로 이어지는 것은 아닙니다. 스타벅스의 탱크데이 마케팅으로 촉발된 이념·세대 갈등이 배재고 사태로 또다시 증폭될 수 있습니다. 이것이 ‘제3, 제4의 스타벅스’ 논란으로 이어져선 안 됩니다. 국민 통합을 위해 과도한 공방보다는 학생들을 계도하고 갈등을 완화하는 노력이 필요한 시점입니다.', 'crawl', '조선일보', '2026-07-04 18:00:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MI3WKZTBGI3TGY3FGRSDANTFMI.jpg', '2026-07-05 10:45:05', '2026-07-05 19:59:30.522921', '배재고 야구팀 6개월 출전 정지 징계');
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (12, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/05/SZ6ZLBPAVRCU7CEVDABIHHQSNE/', 'https://www.chosun.com/politics/assembly/2026/07/05/SZ6ZLBPAVRCU7CEVDABIHHQSNE/', '정치', '與 “이번 주 선관위 특검법 제출…특검, 제3자 추천이 공정”', '', '더불어민주당 한병도 대표 직무대행은 5일 “이번 주 선관위 특검법을 제출하겠다”며 “실체적 진실을 밝히고 책임자를 처벌해 선거 사무에 대한 국민의 신뢰를 회복하는 데 집중하겠다”고 했다. 한 대행은 이날 페이스북에서 “국민 참정권을 침해한 투표용지 부족은 그 어떤 변명으로도 용납할 수 없는 헌정사상 초유의 사태”라며 이같이 밝혔다. 한 대행은 “단 한 점의 의혹도 남기지 않기 위해 전방위적인 수사가 필요하다”며 “투표용지 인쇄 물량 축소 경위, 선거일 지휘부 보고 누락 및 지연, 선관위 내부 부패와 무능까지 수사 대상에 포함하겠다. 지위 고하를 막론하고 책임자는 모두 법의 심판대에 세우겠다”고 했다. 국민의힘은 선관위 특검 추천권에서 여당을 배제해야 한다고 주장하고 있다. 이에 대해 한 대행은 “일고의 가치도 없는 정략적 선동이자 어불성설”이라며 “통상 특검은 여당과 야당 그리고 제3자가 추천하고, 그중 1인을 대통령이 임명한다”고 했다. 그는 그러면서 “선관위는 헌법상 독립기관이다. 여야를 막론하고 진상규명에 함께해야 한다”며 “정치적 유불리를 배제한 특검이라면, 오히려 독립성과 중립성이라는 선관위의 특수성을 고려해 대한변협 등 제3자 추천이 더 현실적이고 공정할 것”이라고 했다. 한 대행은 “특검 추천권을 놓고 입씨름할 때가 아니다”라며 “국민의힘은 이번 사태를 정치적으로 활용할 생각이 없다면 더는 무책임한 몽니를 부리지 말아야 할 것”이라고 했다.', 'crawl', '조선일보', '2026-07-05 02:32:31', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/A7Z6WDDJYNJBBKH3BMSPWIA6SU.jpg', '2026-07-05 10:45:05', '2026-07-05 20:00:20.602608', '선관위 특검법 제출 발표');
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (106, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/economy_general/2026/07/05/MJTDGNJVGE3TOYTEMUZGINRQGE/', 'https://www.chosun.com/economy/economy_general/2026/07/05/MJTDGNJVGE3TOYTEMUZGINRQGE/', '경제', '[정책 인사이트] 靑 ‘미래대응기금’ 추진 공식화... 미국은 사용 요건 제한하고 의회 동의 절차 둬', '강훈식 대통령비서실장이 5일 “반도체 호황 등으로 발생한 추가 세수를 미래 세대를 위한 투자 재원으로 활용하기 위해 ‘미래대응기금’ 신설을 추진한다”고 밝혔다. 초과 세수를 재원으로 한 기금 신설을 공식화한 것이다. 세수 일정 비율을 적립해두는 제도는 미국이 ‘불황대비기금(Rainy day fund)’이란 이름으로 먼저 도입했다. 미국은 50개 주가 저마다', '강훈식 대통령비서실장이 5일 “반도체 호황 등으로 발생한 추가 세수를 미래 세대를 위한 투자 재원으로 활용하기 위해 ‘미래대응기금’ 신설을 추진한다”고 밝혔다. 초과 세수를 재원으로 한 기금 신설을 공식화한 것이다. 세수 일정 비율을 적립해두는 제도는 미국이 ‘불황대비기금(Rainy day fund)’이란 이름으로 먼저 도입했다. 미국은 50개 주가 저마다의 이름과 방식으로 기금을 운용한다. 재원은 예산 일정 비율을 자동 적립하는 곳도 있고, 초과 세수가 발생할 때만 쌓는 경우가 있다. 상당수의 주가 주지사의 선심성 지출을 막기 위해 기금 사용 요건을 제한하고, 일부는 의회 동의를 받도록 한 경우도 있다. ◇ 수십조 초과 세수...정해진 용처 外 미래 투자 강 실장은 이날 고위당정협의회에서 “추가 세수로 기금을 조성해 3대 메가 프로젝트 지원을 포함한 미래 성장 동력 창출, K자형 양극화 대응, 2030 청년을 위한 주거·창업·일자리 지원 등 대한민국 미래에 과감한 투자를 하고자 한다”고 했다. 재정경제부에 따르면 1~5월 국세수입은 199조9000억원으로 전년 대비 16%(27조5000억원) 증가했다. 연말까지 이런 증가율이 유지된다고 가정하면, 연말 국세 수입은 약 434조원 규모로 증가할 수 있다. 현실화되면 올해 정부의 국세수입 전망치(415조4000억원)보다 20조원 가까이 많게 된다. 미래대응기금 구상은 예상치 못한 반도체 호황으로 늘어난 세수를 국가재정법상 정해진 용처에 쓰기보다 미래 세대를 위한 재원으로 떼어 두겠다는 취지로 해석된다. 국가재정법에 따르면, 초과 세수로 발생한 세계잉여금은 ▲지방교부세·지방교육재정교부금 정산 ▲공적자금 상환 ▲국채 상환 순으로 사용해야 한다. 이재명 대통령은 지난달 취임 1주년 기자회견에서 초과 세수 활용과 관련해 “미래 세대를 위한, 또 대한민국의 성장 잠재력을 키우는 방향에 투자해야 하겠다. 그렇게 생각하고 있다”고 했다. 미래대응기금 신설을 위해선 국가재정법 개정이 필요할 전망이다. ◇ 美 불황대비기금 266兆 규모...사용 요건 엄격하게 제한 세수를 미래를 위해 적립해두는 제도는 미국 플로리다주가 1959년 처음 시작했다. 이후 1980년대 미국 경기 침체로 다른 주들로 확산됐다. 현재는 50개 주 모두 이름은 다르지만 불황대비기금 성격의 기금이나 계정을 두고 있다고 한다. 미국 주(州) 예산협의체인 ‘전미주예산관리협회(National Association of State Budget Officers·NASB)’에 따르면, 50개 주의 불황대비기금 규모는 2025회계연도(2024년 10월 1일~2025년 9월 30일) 기준 1740억달러(약 266조2000억원)다. 각 주는 경제 구조에 따라 제각기 다른 기금 적립 및 사용 방식을 규정하고 있다. 가령 텍사스는 석유와 천연가스 생산 세수가 기준치를 초과하면 초과분 75%를 경제안정기금에 자동 적립하게 하고 있다. 기금 적립금을 쓸 때는 주 의회 동의를 받아야 한다. 세수 결손이 발생한 경우에는 출석 의원 60% 동의를 받아야 하고, 그렇지 않은 경우에는 67% 동의를 받아야 한다. 캘리포니아는 일반회계 예상 세입 1.5%와 자본소득세가 세입 8%를 초과하면 초과분을 예산안정계정에 적립하게 하고 있다. 이 계정 적립금은 주지사가 예산 비상사태를 선포해야 쓸 수 있다. 예산 비상사태는 올해나 내년 예상 세수가 최근 3개년도 지출 수준에 못 미치거나 대형 산불 등 재난이 발생했을 때 선포할 수 있다. 주지사가 비상사태를 선포해도 주 의회가 예산 법안을 통과해야 최종 지출할 수 있다. 코네티컷은 소득세가 일정 한도를 초과하면 초과분 전액을 예산안정기금에 적립하도록 한다. 적립금은 기본적으로 재정 적자가 발생했을 때 써야 한다. 이외에 상황에서 쓰려면 주지사가 재정 비상사태를 선포하고, 주 의회에서 60% 이상 동의를 받아야 한다.', 'crawl', '조선일보', '2026-07-05 09:07:35', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GE4GIMBSMVSDIMLEGI4WGMTEME.jpg', '2026-07-05 10:45:06', '2026-07-05 20:02:38.353437', '미래대응기금 신설 추진 공식화');
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (118, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/economy_general/2026/07/05/MM4DSMJVGU2GEZTCGI3WEZJXHA/', 'https://www.chosun.com/economy/economy_general/2026/07/05/MM4DSMJVGU2GEZTCGI3WEZJXHA/', '경제', '강훈식 “반도체 추가 세수로 미래대응기금 신설”', '강훈식 대통령비서실장이 5일 고위당정협의회에서 “이재명 정부는 반도체 호황 등으로 발생한 추가 세수를 미래 세대를 위한 투자 재원으로 활용하기 위해 ‘미래대응기금’ 신설을 추진한다”고 밝혔다. 강 실장은 이날 국무총리 서울공관에서 열린 제9차 고위당정협의회에서 “대한민국의 미래를 좌우할 절체절명의 시기에 반도체 호황 등으로 발생한 추가 세수를 허투루 써서', '강훈식 대통령비서실장이 5일 고위당정협의회에서 “이재명 정부는 반도체 호황 등으로 발생한 추가 세수를 미래 세대를 위한 투자 재원으로 활용하기 위해 ‘미래대응기금’ 신설을 추진한다”고 밝혔다. 강 실장은 이날 국무총리 서울공관에서 열린 제9차 고위당정협의회에서 “대한민국의 미래를 좌우할 절체절명의 시기에 반도체 호황 등으로 발생한 추가 세수를 허투루 써서는 안 될 것”이라고 했다. 그러면서 “추가 세수로 기금을 조성해 3대 메가 프로젝트 지원을 포함한 미래 성장 동력 창출, K자형 양극화 대응, 2030 청년을 위한 주거·창업·일자리 지원 등 대한민국 미래에 과감한 투자를 하고자 한다”고 했다. 이어 “미래대응기금 신설은 대체 불가 대한민국 실현의 초석이 될 것”이라며 “속도감 있게 추진될 수 있도록 당정 협력을 당부드린다”고 했다.', 'crawl', '조선일보', '2026-07-05 07:26:29', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/G5TDGZTDGYZWIYZYHEYGGZLBGQ.jpg', '2026-07-05 10:45:06', '2026-07-05 20:01:44.53681', '미래대응기금 신설 추진 발표');
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2286, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/07/OKS6BNB2YZDGRMVSTGNDM4PM7U/', 'https://www.chosun.com/politics/assembly/2026/07/07/OKS6BNB2YZDGRMVSTGNDM4PM7U/', '정치', '與 내부서도 보완수사권 폐지 신중론…“피해자 보호 장치 따져야”', '', '더불어민주당 지도부가 검찰의 보완수사권 완전 폐지를 담은 형사소송법 개정안을 이번 주 발의하겠다고 밝히며 검찰개혁 입법에 속도를 내고 있다. 다만 당내 일각에서는 경찰 부실수사와 피해자 보호 공백을 우려하며 보완수사권 폐지 이후의 제도적 장치를 더 신중히 검토해야 한다는 목소리도 나오고 있다. 최근 민주당 의원들이 참여한 단체 텔레그램방에서도 일부 의원들이 경찰 부실수사와 피해자 보호 공백을 우려하며 보완수사권 폐지에 신중해야 한다는 의견을 낸 것으로 알려졌다. 한병도 민주당 대표 직무대행 겸 원내대표는 7일 국회에서 열린 원내대책회의에서 “이번 주 내 형사소송법 개정안 발의를 목표로 밀도 높고 내실 있는 논의에 속도를 높이겠다”고 밝혔다. 한 대행은 “보완수사권 완전 폐지는 민주당의 확고부동한 원칙이며 당내 이견이 없다”며 “오는 10월 공소청과 중대범죄수사청 출범에 차질이 없도록 하겠다”고 했다. 민주당은 검찰청을 폐지하고 기소를 전담하는 공소청과 수사를 맡는 중대범죄수사청을 설치하는 방향으로 검찰개혁 입법을 추진해 왔다. 남은 쟁점은 경찰이나 중수청이 송치한 사건에 대해 공소청 검사가 직접 보완수사를 할 수 있도록 할지 여부다. 민주당 지도부는 검찰의 수사권을 남겨둘 경우 수사·기소 분리라는 개혁 취지가 훼손될 수 있다는 입장이다. 그러나 당내에서는 보완수사권 전면 폐지가 형사사법 절차의 공백으로 이어질 수 있다는 우려도 제기된다. 홍기원 의원은 지난달 26일 페이스북에 올린 글에서 “보완수사권 남용 여지를 원천 차단하는 것이 검찰개혁의 화룡점정이라는 입장과, 피해자 보호와 수사권을 사실상 독점하게 된 경찰권력 견제를 위해 최소한의 보완수사권은 필요하다는 입장이 맞서고 있다”고 밝혔다. 홍 의원은 검찰의 수사·기소권 분리 필요성에 동의한다면서도 “검사의 보완수사권 없이도 힘없는 서민, 힘없는 피해자 보호에 부족함은 없는지, 수사권을 독점하게 된 경찰권력 견제가 가능한지 따져봐야 한다”고 했다. 그는 “일단 보완수사권을 완전 폐지하고 혹시 부작용이 있다면 그때 되살리면 된다는 주장도 있지만, 국정에 무한 책임을 가진 정부와 여당 국회의원으로서는 신중해야 할 일”이라고 했다. 당내 비공개 논의에서도 비슷한 문제 제기가 나온 것으로 전해졌다. 최근 민주당 의원 단체 대화방에서는 일부 의원들이 보완수사권 완전 폐지의 부작용을 우려하며 조건부 예외나 보완 장치를 검토할 필요가 있다는 취지의 의견을 낸 것으로 알려졌다. 경찰이 기소 의견으로 송치한 사건, 증거인멸 위험이 큰 사건, 공소시효가 임박한 사건 등에서 예외를 둘 수 있는지 따져봐야 한다는 문제의식이다. 광주 여고생 살해 사건 피의자 장윤기 사건도 당내 논의에 영향을 주는 분위기다. 경찰은 당초 장씨를 살인 등 혐의로 송치했지만, 검찰은 보완수사 과정에서 성범죄 목적과 관련한 정황을 추가로 확인해 강간 등 살인 혐의를 적용했다. 여기에 장씨의 부친인 현직 경찰관이 증거를 인멸했다는 의혹까지 불거지면서 경찰 수사에 대한 견제 장치를 어떻게 둘 것인지가 쟁점으로 떠올랐다. 민주당 법제사법위원인 김기표 의원도 이날 라디오 인터뷰에서 검찰의 보완수사권을 폐지하더라도 보완수사 요구권은 유지해야 한다는 입장을 밝혔다. 김 의원은 검사가 경찰에 추가 수사를 요구할 수 있는 장치까지 없애면 “경찰이 수사한 대로 검사가 기소·불기소하게 된다”며 “수사와 기소가 붙어버리게 된다”고 말했다. 국민의힘은 민주당의 보완수사권 폐지 추진에 반발하고 있다. 경찰 부실수사 우려가 현실화할 수 있다며 폐지 논의를 중단하고 여야정 협의체를 구성해 수사체계 전반을 다시 논의해야 한다는 주장이다. 민주당으로서는 검찰개혁의 완결성과 형사사법 절차의 안정성을 동시에 고려해야 하는 상황이 됐다. 보완수사권을 남기면 검찰 권한이 되살아날 수 있다는 우려가 있고, 전면 폐지하면 부실 수사와 피해자 보호 공백을 어떻게 막을지가 숙제로 남는다. 향후 형사소송법 개정 논의는 보완수사권의 존폐뿐 아니라 폐지 이후 견제 장치와 예외 규정을 어디까지 둘지를 둘러싼 당내 조율이 핵심이 될 전망이다.', 'crawl', '조선일보', '2026-07-07 05:29:29', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/CZY5IBJOCVLRPJIVOAVDG5JQ3M.jpg', '2026-07-07 06:04:16', '2026-07-07 15:04:58.107038', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2291, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/07/H4IIYD22KJGLHNCMMDKO2KQDLQ/', 'https://www.chosun.com/politics/assembly/2026/07/07/H4IIYD22KJGLHNCMMDKO2KQDLQ/', '정치', '보완수사권 폐지 속도 내는 與...“이번 주 소위 논의 시작, 8·17 넘기기 어려울 것"', '', '더불어민주당이 검찰 보완수사권 폐지 논의에 속도를 내고 있다. 국회 법제사법위원회를 중심으로 8월 17일 전당대회 이전까지 입법 절차를 마무리해야 한다는 목소리가 커지고 있다. 민주당 소속 서영교 법사위원장은 7일 KBS라디오 ‘전격시사’에서 보완수사권 폐지를 골자로 한 형사소송법 개정안 처리 시점에 대해 “전당대회 이후로 넘어가기는 어렵지 않을까 생각한다”고 밝혔다. 서 위원장은 “중대범죄수사청(중수청)과 공소청이라는 조직이 10월 2일에 출범한다면 이로부터 6개월 전 정도에 절차법인 형사소송법 입법은 거의 완료됐어야 한다”면서 “(10월 2일까지) 남은 게 2개월 반 정도 되기 때문에 최대한 빠르게 해나갈 것”이라고 말했다. 서 위원장은 기발의된 보완수사권 폐지 법안과 관련해서도 “내일 그 법안을 다 (전체회의에) 상정하게 된다. 바로 이번 주부터 소위로 넘겨 소위가 활동한다면, 아주 할 수 있는 한 빠르게 (처리를) 할 예정”이라고 했다. 서 위원장은 보완수사권 폐지에 따른 수사권 공백은 보완수사요구권의 실질화를 통해 최소화하겠다는 입장도 밝혔다. 서 위원장은 “그동안은 보완 수사(요구)가 일정이 조금 만연해 있었다면 이번에는 보완 수사를 요구했을 때 구체적으로 내려 달라(는 취지로 개정할 것)”라면서 “경찰의 보완수사 시기도 정하려고 한다. 한 달이면 한 달, 더 걸리면 연장을 하더라도 기본적으로 빠르게 갔다 올 수 있게 할 것”이라고 했다. 또 인권보호국 설치, 경찰 수사심의위원회 실질화 등을 통해 경찰을 견제하겠다는 입장도 밝혔다. 법사위 소속 김기표 민주당 의원도 이날 SBS라디오 ‘김태현의 정치쇼’에서 “당과 정부의 입장은 보완수사권 폐지로 정리한 상태여서 더 이상 폐지냐 아니냐를 논의하는 것은 무의미하다”고 말했다. 김 의원은 최근 장윤기 사건을 계기로 보완수사권 존치 필요성이 언급되는 상황에 대해서도 “폐지 논의를 할 때 이런 점들에 대해서도 당연히 얘기가 됐고, 제도적 보완을 해야 한다는 건 이미 당이나 정부에서 논의됐다”고 했다. 김 의원은 “보완수사권이 폐지되면 보완수사요구권은 당연히 존치해야 된다고 생각한다”고 했다. 법안 처리 시기에 대해서는 “전당대회 전에 가능할지는 저희가 굉장히 촉박하게, 열심히 노력해야 할 것”이라면서도 “전당대회 후에 된다 하더라도 10월 2일 공소청이 출범할 때까지는 문제없도록 하는 것이 목표”라고 했다.', 'crawl', '조선일보', '2026-07-07 02:19:56', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MFRDOZJZGMYTOYZWGVTDGOLGGM.jpg', '2026-07-07 06:04:16', '2026-07-07 15:05:17.6252', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2296, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/07/KC3JHX4MNJCHFJHHBNJ4ZMVSDQ/', 'https://www.chosun.com/politics/assembly/2026/07/07/KC3JHX4MNJCHFJHHBNJ4ZMVSDQ/', '정치', '한병도 “올림픽공원 투표지 247만장, 재검표·수개표 추진 적극 검토”', '', '한병도 더불어민주당 당대표 직무대행 겸 원내대표는 올림픽공원 핸드볼 경기장에 보관된 6·3 지방선거 투표용지 247만장에 대해 “재검표와 수개표를 여야 협의로 국정조사 특별위원회(국조특위)에서 추진하는 방안을 적극 검토하겠다”고 7일 밝혔다. 한 원내대표는 국조특위의 선관위 대상 2차 현장조사가 예정된 이날 원내대책회의에서 “투표지 인쇄 물량 축소 과정과 의사결정 체계, 선거 당일 지휘 체계를 면밀히 점검해 사태의 실체를 규명하고 책임 소재를 명확히 밝히겠다”면서 이같이 밝혔다. 한 원내대표는 투표용지 부족 사태 특검과 관련해 “민주당은 이미 당론으로 특검법을 추진하기로 정했고, 정치적 논란을 최소화할 수 있도록 제3자 추천 방식을 제안했다”면서 “그런데도 국민의힘은 정치적 유불리를 따지며 야당 단독 추천을 고집하고 있다”고 지적했다. 이어 “중요한 것은 국민참정권 침해의 진상을 밝히고, 책임자 처벌을 통해 선거사무에 대한 국민 신뢰를 회복하는 일”이라면서 “국민의힘도 국민 참정권을 정쟁으로 몰아가려는 시도를 그만두고, 실체적 진실을 밝혀내는 데 온 힘을 모아달라”고 했다. 한 원내대표는 국민의힘의 ‘상임위 보이콧’에 대해서는 “국민의힘에 엄중히 경고한다. 일 하라”면서 “국민이 부여한 국회의원의 의무를 다할 것을 촉구한다”고 했다. 한 원내대표는 “현재 상임위와 법사위를 통과했지만 국민의힘의 반대로 본회의 문턱에서 잠들어 있는 법안이 59건에 달한다”고 말했다. 이어 “오는 9일 민생법안 처리를 위한 본회의 개최가 필요하다”면서 “오늘 조정식 국회의장을 찾아뵙고 본회의 개최를 요청드리겠다. 국민의힘도 일말의 책임감이라도 있다면 민생법안 처리에 협조하라”고 했다.', 'crawl', '조선일보', '2026-07-07 01:30:05', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/NCXG336PCRJLPNWH6TGRUX6ORE.jpg', '2026-07-07 06:04:16', '2026-07-07 15:05:26.737699', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2297, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/07/NCFXT2BAEFCWVIRX2VAVLI7P6Q/', 'https://www.chosun.com/politics/politics_general/2026/07/07/NCFXT2BAEFCWVIRX2VAVLI7P6Q/', '정치', '선관위 “올림픽공원 투표용지 재검표 검토” 5000만원은 선관위가 부담', '', '중앙선거관리위원회가 7일 올림픽공원 핸드볼경기장 내 투표용지에 대한 재검표 추진을 검토하겠다고 국회 ‘6·3 지방선거 투표용지 부족 사태 등 국민 참정권 침해 진상 규명 및 선거관리 개혁을 위한 국정조사특별위원회’에 보고했다. 앞서 국조특위 위원장인 국민의힘 윤상현 의원은 서울 올림픽공원 핸드볼경기장에 보관 중인 247만표에 대한 ‘공개 재검표’를 추진할 계획이라고 했었다. 중앙선관위가 국민의힘 김은혜 의원실에 제출한 ‘제2차 현장 조사 업무 보고’ 자료에 따르면, 선관위는 “현행 법규상 선관위 자체 직권 재검표는 법적 근거가 없다”면서도 “국조특위 의결을 거쳐 투표지 등 검증 형식으로 진행하는 방안을 대안으로 검토할 필요가 있다”고 보고했다. 재검표를 의결하는 경우 투표용지 재검표에 들어가는 비용 약 5000만원은 선관위가 직접 부담할 방침이다. 선관위는 올림픽공원에 보관 중인 투표용지 총 247만표 전부를 검증하는 경우 440명의 인력이 투입돼 9시간이 걸릴 것으로 추정했다. 투표지 육안 재확인 및 정당·후보자별 분류·확인 후, 심사 계수기로 매수를 확인해 검증 결과표를 작성하는 등 방식이다. 247만표 중 서울시장 선거에 해당하는 투표용지 37만표만 검증하는 경우 5시간, 2200만원이 들고 송파구의회 선거(마 선거구)에 해당하는 투표용지 25만표만 검증하는 경우에는 4시간, 2200만원이 든다. 중앙선관위는 또 국조특위 위원과 정당·후보자 추천 참관인, 언론 등에도 과정을 공개하겠다고 설명했다. 앞서 국조특위위원장인 윤상현 의원은 5일 국회에서 기자회견을 열고 서울 올림픽공원 핸드볼경기장에 보관 중인 247만표에 대한 ‘공개 재검표’를 추진할 계획이라고 밝혔다. 윤 의원은 당시 “위철환 중앙선거관리위원장 직무대행에게 247만표 유·무효표에 대해 공개적으로 재검증하자고 했다”며 “선관위 입장에서도 그것에 대해 잘못된 투·개표가 없다는 것을 보여줘야 하지 않느냐”고 했다. 한편 국회 국정조사특위는 이날 오전 중앙선거관리위원회와 서울시선거관리위원회를 직접 찾아 현장 조사에 나섰다. 국조특위 위원장인 국민의힘 윤상현 의원을 비롯한 여야 특위 위원들은 이날 오전 경기 중앙선관위 과천청사를 살핀 뒤 오후에는 서울 종로구 서울선관위 사무소로 이동해 현장 조사를 이어갈 예정이다.', 'crawl', '조선일보', '2026-07-07 01:45:33', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MMYDCZDDMFSTKZRQMU3GIYLEGE.jpg', '2026-07-07 06:04:16', '2026-07-07 15:05:28.352138', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2302, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/07/HUM5SFPYSVGCRKTQQLSG2UMRTQ/', 'https://www.chosun.com/politics/assembly/2026/07/07/HUM5SFPYSVGCRKTQQLSG2UMRTQ/', '정치', '김민석, 친청계 ‘감기약 발언’에 “대장동 보는 듯...허위사실 유포 책임져야”', '', '더불어민주당 당대표 선거에 출마한 김민석 전 국무총리는 7일 친청(친정청래)계의 ‘계엄 해제 표결 불참’ 의혹 제기에 대해 “무슨 대장동 때를 보는 것 같다”고 반박했다. 김 전 총리는 이날 KBS라디오 ‘전격시사’에서 “이성윤 최고위원이 말씀하셨던데 저는 ‘국민의힘에서 누가 얘기하나’ 생각했다”면서 이같이 밝혔다. 이 의원은 전날 김 전 총리의 출마 선언 직후 “계엄 해제 국회 표결에 왜 불참했나, 감기약 먹고 잤다는데 그 감기약 성분이 무엇인가, 민주당 의원과 계엄 선포 직전 통화했다는데 그럼 즉시 국회로 달려와야 하지 않았는가”라며 의혹을 제기한 바 있다. 이에 대해 김 전 총리는 “제가 표결 시점에 국회 안에 있었고, 또 표결 직후에 본회의장에 착석했고, 그 과정도 이미 여러 자리에서 이야기를 다 했다”고 했다. 또 “일단 이 의원이 말씀하신 게 허위사실”이라면서 “‘계엄 관련 전화를 듣고 왜 거기 안 왔냐’ (이런 얘기는) 허위사실에 의한 명예훼손”이라고 했다.이어 “이 시점에서 그렇게 얘기하셔서 걱정하고 있다”면서 “‘저런 식으로 정치를 하면 좀 어려워질 텐데’ 이렇게 생각하고 있다”고 했다. 전날 김 전 총리의 출마 선언 직후 친청계로 분류되는 이성윤·한민수·최민희 의원이 연달아 김 전 총리를 저격했다. 반면 친명계 강득구·이건태 의원 등은 김 전 총리 엄호에 나섰다.', 'crawl', '조선일보', '2026-07-07 00:26:05', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GZRWMYTEGAZDKZTBGUZTONRTG4.jpg', '2026-07-07 06:04:16', '2026-07-07 15:05:37.897349', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2303, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/blue_house/2026/07/07/VU5JUHIKXFCONOUVQEWWDSUDIA/', 'https://www.chosun.com/politics/blue_house/2026/07/07/VU5JUHIKXFCONOUVQEWWDSUDIA/', '정치', '李대통령, 나토회의 참석 차 출국... 튀르키예서 트럼프 대면할까', '', '이재명 대통령이 7일 서울공항을 통해 북대서양조약기구(NATO·나토) 정상회의가 열리는 튀르키예 앙카라를 향해 출국했다. 이 대통령 취임 후 첫 나토 정상회의 참석이다. 3박 5일 간의 이번 일정은 마르크 뤼터 나토 사무총장의 초청으로 성사됐다. 이 대통령의 출국길엔 강훈식 대통령 비서실장, 홍익표 정무수석, 한병도 더불어민주당 당대표 직무대행 겸 원내대표, 윤호중 행정안전부 장관 등이 참석했다. 이 대통령은 이날 오후 앙카라에 도착, 뤼터 사무총장과 함께 일본, 호주, 뉴질랜드 등 인도·태평양 파트너국, 이른바 IP4 국가 대표들과의 소인수회담에 참석한다. 이후 이 대통령은 정상회의 공식 행사 중 하나인 나토 방위산업포럼에 참석, ‘공동의 가치, 더욱 강한 산업기반’을 주제로 한 세션에서 기조발언을 한다. 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 참석한다. 특히 도널드 트럼프 미국 대통령 역시 나토 정상회의 참석을 위해 튀르키예를 방문할 예정인 만큼, 이 대통령과 현지에서 대면할 것인지에도 관심이 쏠리고 있다.이 대통령은 8일까지 튀르키예에 머무른 뒤 9일부터는 몽골에서 국빈방문 일정을 소화한다. 이 대통령은 이날 X에 “이번에는 북대서양조약기구(NATO·나토) 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다”며 “전쟁의 폐허를 딛고 나라를 지키기 위해 흘린 수많은 땀방울이 오늘날 세계가 인정하는 경쟁력이 되었다는 것이 참으로 자랑스럽다”고 했다. 이어 “오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계평화와 안보에 책임 있게 기여하는 나라가 되었다”며 “국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다”고 했다.', 'crawl', '조선일보', '2026-07-06 23:57:47', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/VPS3CWDMAZMNXIEK3ASVES32QQ.JPG', '2026-07-07 06:04:16', '2026-07-07 15:05:39.779048', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2305, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/diplomacy-defense/2026/07/07/IPLTSYMSHNHQDHNLFCV3S47DSA/', 'https://www.chosun.com/politics/diplomacy-defense/2026/07/07/IPLTSYMSHNHQDHNLFCV3S47DSA/', '정치', '李, 나토 회의서 트럼프 만난다', '', '이재명 대통령과 도널드 트럼프 미 대통령이 7~8일 튀르키예 앙카라에서 열리는 나토(NATO·북대서양조약기구) 정상회의에 나란히 참석한다. 최근 한미 간 쟁점으로 떠오른 쿠팡 문제와 2차 회의 일정을 정하지 못하고 있는 한미 조인트 팩트시트 안보 분야 후속 협의 등의 현안이 두 정상 간에 논의될지 주목된다. 5일(현지 시각) 백악관에 따르면 트럼프 대통령은 7일 오후 앙카라에 도착해 개최국인 튀르키예와 정상회담을 하고, 8일 나토 정상 공식 환영 행사 등에 참석한다. 이 대통령도 취임 후 첫 나토 정상회의 참석을 위해 7일 튀르키예로 출국한다. 지난달 16~17일 프랑스 에비앙에서 열린 주요 7국(G7) 정상회의에 이어 약 20일 만에 다시 조우할 기회다. 그사이 한미 양국 간에는 쿠팡 문제를 놓고 공방이 이어졌다. 지난 1일 미 하원 법사위에 이어 2일 백악관이 ‘한국 정부가 쿠팡을 차별 대우했다’는 취지의 보고서와 입장을 잇달아 발표했다. 이에 우리 외교부와 청와대는 “보고서에 쿠팡 측 주장만 일방적으로 반영됐다”며 “쿠팡에 대한 개인정보 유출 수사는 차별 없이 법과 원칙에 따라 진행되고 있다”고 반박했다. 이 대통령이 취임 후 처음 참석하는 이번 나토 정상회의는 애초 나토 동맹국들과의 ‘방산 협력 본격화’에 방점이 있었다. 하지만 쿠팡 문제가 한미 관계에 악재로 작용하면서 대응이 시급해진 상황이다. 외교 소식통은 “그간 한미 정상이 ‘톱다운’ 방식으로 굵직한 현안을 풀어왔던 만큼 이번에 정상 간 직접 소통이 이뤄지면 갈등 해결의 실마리가 될 수도 있을 것”이라고 말했다. 순방에 동행하는 조현 외교부 장관 등 정부 고위 인사들이 미국 측 핵심 인사들과 별도 접촉에 나설 가능성도 제기된다. 미국은 쿠팡 문제를 ‘미국 기업이 차별당하지 않도록 보장’한다는 한미 조인트 팩트시트 상의 합의 위반으로 보고 있다. 이 때문에 한국의 원자력 추진 잠수함 도입과 우라늄 농축, 사용후핵연료 재처리 권한 확보 등의 안보 합의 후속 진전에 걸림돌이 될 수 있다. 실제 한미 간 2차 안보 협의 일정은 지난달 2~3일 1차 협의 후 한 달이 지난 6일까지 확정되지 않았다.', 'crawl', '조선일보', '2026-07-06 15:49:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/PPRGQCZMMRIENEOC73ZQRA47ZU.JPG', '2026-07-07 06:04:16', '2026-07-07 15:05:43.627115', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2313, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/07/6IFMCCR75VF45ICDMGT6LEFEYU/', 'https://www.chosun.com/politics/politics_general/2026/07/07/6IFMCCR75VF45ICDMGT6LEFEYU/', '정치', '여의도 3배 평지, KTX 역과 인접… 국유지라 토지보상 문제 없어', '', '6일 청와대가 낙점한 광주 군 공항 부지는 국유지라 토지 보상 문제가 사실상 없다는 점이 장점으로 꼽힌다. KTX가 다니는 광주 송정역과 직선거리로 2㎞ 이내이고, 호남고속도로 등도 가까운 편이다. 다만 군 공항을 전남 무안공항으로 이전해야 하는데, 무안군 주민 동의를 얻어야 하는 게 난관이다. ◇정부, 삼성전자, SK하이닉스 함께 논의해 결정 삼성전자와 SK하이닉스 실무진은 첨단 3지구와 군 공항 부지 등을 둘러보고 부지 규모와 용수·전기 공급 여건 등을 검토했고, 정부와 논의 끝에 광주 군 공항을 낙점한 것으로 알려졌다. 강훈식 대통령비서실장은 이날 청와대 브리핑에서 “기업들은 호남권 입지 후보지 중 광주 군 공항이 가장 적합한 부지라는 의견을 제시했다”며 “광주 군 공항 부지에 호남권 반도체 산단을 조성하기로 결정했다”고 밝혔다. 이곳의 가장 큰 장점은 대규모 평탄화 부지라 부지 조성 기간을 줄일 수 있다는 점이다. 전남광주 광산구의 군 공항 이전 부지는 820만㎡(약 250만평)로 여의도의 약 3배 크기다. 반도체 공장은 노광기·계측 장비 등 정밀 장비가 나노미터 단위로 작동하는 만큼 지반 안정성이 핵심이다. 경사가 지거나 지형이 복잡한 부지는 지반 개량, 기초 공사에 더 많은 시간과 비용이 든다. 고도 정수 처리가 가능한 무등산 인근 용연정수장이 가까운 것도 용수 확보에 유리하다. 반도체 업계 관계자는 “공장을 조성하다가 문화재만 발견돼도 사업 일정이 지연될 수 있는데, 이미 개발된 곳이어서 그런 리스크가 상대적으로 적다”며 “전력과 용수만 문제없이 끌어올 수 있다면, 번거로운 행정 절차를 비교적 빠르게 넘길 수 있는 부지”라고 설명했다. 광주과학기술원(GIST), 전남대, 조선대, 한국에너지공대, 전북대와 지역 마이스터고를 중심으로 연간 2000명 이상 규모의 AI·반도체 전문 인력을 양성할 수 있는 기반도 갖추고 있다. ◇공항 이전 10년 예상, 무안 반발도 변수 문제는 광주 군 공항 이전 작업이다. 광주 군 공항 부지 자체는 국유지라 토지 보상이나 주민 이주 등 절차가 사실상 필요 없다. 현재 무안국제공항으로 통합 이전하는 작업이 이미 진행 중이지만, 무안군은 전투기 소음 피해를 이유로 반대하고 있다. 지난달 30일 국방부에서 열릴 예정이었던 군 공항 부지 선정 위원회 6자 회담은 김산 무안군수의 불참으로 취소됐다. 이르면 이달 말 이전 부지 선정 위원회를 다시 열고 무안공항을 이전 후보지로 최종 선정할 가능성이 높다. 하지만 이후에도 주민투표 등을 거쳐야 하고 무안군수가 군 공항 유치를 신청해야 한다. 주민투표는 총유권자의 3분의 1 이상 투표에 유효 투표 과반 시 가결된다. 김 군수는 “3대 요구 조건에 대한 이행은 소홀한 채 이전 부지 선정에만 급급하다”는 입장이다. 무안군의 3대 조건은 광주 민간 공항의 무안국제공항 선(先) 이전, 전남광주특별시와 정부의 1조원 규모 지원, 국가 차원의 획기적 인센티브 제공이다. 군 공항 이전 기간도 문제다. 작년 12월 정부와 광주·전남·무안이 광주 군 공항을 무안으로 옮기기로 합의할 당시, 광주시 관계자는 “무안에 이전 부지를 조성하는 데 약 10년이 걸릴 것”이라고 했다. 국방부는 “구체적인 이전 시기는 정해진 바 없다”면서도 “현재 판단으로는 이전 부지 선정은 2026년 내에 완료하고, 부지 조성과 군 공항 건설 등은 2030년대 초·중반경에 완료될 것으로 예상한다”고 했다. 민형배 전남광주특별시장은 “군 공항 건설 기간은 최대한 단축하면 5년, 비용은 8~9조원으로 예상된다”고 했다. 전남광주 서구 마륵동·금호동 탄약고를 광주 군 공항 옆으로 이전하는 사업도 반도체 단지가 조성되면 중단될 수밖에 없다. 군 공항 관련 탄약고로 일대가 군사시설 보호구역으로 묶여 주민들의 이전 요구가 많았고 2005년부터 사업이 추진돼 작년까지 부지 매입, 평탄화 등에 2681억원이 집행됐다. 국방부 관계자는 “해당 부지가 탄약고가 아닌, 반도체 산단부지 등 다른 용도로 사용될 경우에도, 토지 가치와 기반 공사 가치를 인정받을 수 있으므로 예산을 낭비한 것이 아니다”라고 했다. ◇미군 전시 증원 기지도 옮겨야 현재 광주 군 공항에 미국의 전시 증원 기지(COB·Contingency Operating Base)가 있는 점도 변수다. COB는 미군이 평소에는 관리 인력만 두고, 전시에 자산과 물자를 전개해서 쓰는 기지다. 군 공항이 무안공항으로 이전하면 COB도 이곳으로 옮겨가는데, 무안군에서는 과거 이전론이 나왔을 때 “무안이 대(對)중국 전초 기지가 될 수 없다”는 반대가 나오기도 했다.', 'crawl', '조선일보', '2026-07-06 15:53:34', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/A3SWA3FKLRDRXOCM67AXNJVFHU.jpg', '2026-07-07 06:04:16', '2026-07-07 15:06:42.831789', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2314, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/07/7RG4WJK4LFEMHAH7LQ5UWUDU7Y/', 'https://www.chosun.com/politics/politics_general/2026/07/07/7RG4WJK4LFEMHAH7LQ5UWUDU7Y/', '정치', '호남 반도체, 광주 군공항에 짓는다', '', '청와대는 6일 ‘3대 메가 프로젝트’의 핵심 사업으로 추진하는 호남권 반도체 클러스터 조성과 관련해 “광주 군 공항 부지에 반도체 산업단지를 조성하기로 결정했다”고 밝혔다. 삼성전자와 SK하이닉스가 총 800조원을 투자해 만드는 반도체 팹(fab·공장) 4기를 광주 군 공항 부지에 짓겠다는 것이다. 청와대는 이날 이재명 대통령 주재로 메가 프로젝트 민관 합동 점검 회의를 진행한 뒤 부지 선정 결과를 공개했다. 강훈식 대통령 비서실장은 브리핑에서 “광주 군 공항 지역은 약 250만평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료돼 있어 부지 공사 기간을 최소화할 수 있다는 장점이 있다”며 광주 도심, KTX역과의 인접성, 도로·공항·항만과 연계한 물류 접근성이 우수한 점도 감안했다고 밝혔다. 하지만 이 지역에 반도체 공장을 지으려면 광주 군 공항 이전이 우선 이뤄져야 한다. 현재 군 공항과 민간 공항의 무안공항 통합 이전이 추진 중이지만 무안군 동의가 필요하다. 정부는 이 대통령 임기 내에 반도체 공장 건설을 마치겠다는 입장인데, 국방부 측은 “군 공항 이전은 2030년대 초중반쯤 완료될 수 있을 것”이라고 했다. 민형배 전남광주특별시장은 “공장 건설과 군 공항 이전을 동시에 할 수 있는 방안을 정부가 내놓을 것”이라고 했다. 청와대는 안보 공백을 최소화하는 범위 내에서 군 공항 조기 이전 방법을 다각적으로 검토한다는 방침이다. 청와대는 반도체 공정에 필수인 전력과 용수 등 인프라 구축 방안에 대해서는 다음 회의 뒤 밝히겠다고 했다. 여권 관계자는 “군 공항만 비우면 부지 문제는 어느 정도 해결되겠지만 용수나 전력 문제는 여전히 풀어야 할 숙제”라고 했다. 앞서 이 대통령은 기업들이 용인 반도체 클러스터 조성을 끝낸 뒤에 호남의 팹 공사를 시작할 예정이었지만 이재용 삼성전자 회장, 최태원 SK그룹 회장을 직접 설득해 ‘용인·호남 동시 실행’을 약속받았다고 했다. 강 실장은 이날 “용인에 대해서는 기업들 요청에 따라 당초 계획된 팹 10기 투자가 훨씬 빠른 속도로 추진될 수 있도록 토지 보상부터 전력·용수 공급까지 전반적인 일정을 최대한 앞당기기로 했다”고 밝혔다. 이 대통령은 이날 “누가 더 빠르냐로 결판이 난다. 그야말로 오직 속도전이 중요하다”며 “정부는 할 수 있는 최대치를 할 것”이라고 했다.', 'crawl', '조선일보', '2026-07-06 16:00:02', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MRQN7PRODNGCFG5WS4KUHUZ6SQ.png', '2026-07-07 06:04:16', '2026-07-07 15:06:44.085343', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2319, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/06/EGXSOATUF5DR3LG5O6RQBSFZKQ/', 'https://www.chosun.com/politics/politics_general/2026/07/06/EGXSOATUF5DR3LG5O6RQBSFZKQ/', '정치', '靑 “호남 반도체 클러스터, 광주 군공항 부지에 조성”', '', '강훈식 대통령 비서실장은 6일 ‘3대 메가 프로젝트’ 일환으로 추진하는 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다고 밝혔다. 강 실장은 이날 청와대에서 3대 메가 프로젝트 추진을 위한 민관 합동 점검 회의를 가진 뒤 브리핑에서 “호남권 반도체 투자와 관련해 그 첫 단계인 부지 관련해 논의했다”며 “기업들은 호남권 입지 후보지 중에 광주 군공항 지역이 가장 적합하다는 의견을 제시했다”고 말했다. 앞서 삼성전자와 SK하이닉스는 800조원을 투자해 호남에 반도체 팹(fab·공장) 4기를 건설하겠다고 밝혔다. 강 실장은 “광주 군공항 지역은 약 250만평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있는 장점이 있다”고 했다. 이어 “광주 도심, KTX 역에 인접해 있어 인력 확보와 정주 여건 측면에서 강점이 있고 도로, 공항, 항만 등과 연계한 물류 접근성도 우수하다”며 “이에 따라 오늘 회의에서 광주 군공항 부지에 호남권 반도체 산단을 조성하기로 결정했다”고 말했다. 강 실장은 “정부는 관계 부처 협의를 거쳐 조속히 후보지 선정 절차를 마무리하고 산단 개발을 위한 후속 절차에 착수하겠다”고 했다.', 'crawl', '조선일보', '2026-07-06 05:07:04', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/XDAPVE4B4RMD3PUEAOPVLHLWMY.jpg', '2026-07-07 06:04:16', '2026-07-07 15:07:04.203681', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2332, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/goverment/2026/07/06/VED76AQASVFD5IQX7L5P4A5TPU/', 'https://www.chosun.com/politics/goverment/2026/07/06/VED76AQASVFD5IQX7L5P4A5TPU/', '정치', '감사원, 선관위 현장 감사 착수… 투표용지 인쇄 예산, 선관위 직원 해외 출장, 재외선거관 파견 들여다본다', '', '감사원이 6일 선거관리위원회에 대한 감사를 시작했다. 감사원은 지난해 2월 헌법재판소 결정으로 선관위를 직무 감찰할 수 없게 됐지만, 회계 검사는 할 수 있고, 지난달 24일 선관위를 회계 검사하겠다고 밝힌 바 있다. 감사원에 따르면, 감사원 행정·안전감사국 감사관 42명이 이날부터 중앙선관위와 서울·경기·부산선관위, 산하 송파구선관위 등 구·시·군선관위로 나가 실지감사(현장 조사)를 시작한다. 실지감사는 오는 24일까지 근무일 14일을 포함해 19일간 1차로 진행되고, 다음 달에 근무일 14일간 2차로 진행된다. 감사원은 1차 실지감사 결과에 따라 필요한 경우, 감사 범위를 넓히거나 실지감사를 추가로 할 수도 있다고 했다. 이는 통상적인 감사보다 인력과 시간을 3~4배 투입하는 것이다. 감사원은 이를 통해 12가지 사항을 중점적으로 들여다보겠다고 했다. 감사원은 “투표용지 인쇄와 계약이 포함된 선거 관련 예산·편성 집행 실태와 국민적 의혹이 큰 사항, 선관위 자정 노력 검증에 필요한 사항 등을 점검해, 선관위에 대한 국민 의혹의 해소 방안을 마련하겠다”고 했다. 6·3지방선거 투표용지 부족 사태와 관련해서는 ▲투표용지 인쇄 예산 편성·집행과 ▲투표용지 인쇄 계약이 적정하게 이뤄졌는지를 살펴보겠다고 했다. ▲선거 물품 구매·관리와 건물 임차는 적정한지, ▲인건비 등의 선거 경비소요 추계와 예산 조정은 적정한지도 확인하겠다고 했다. 다만 헌재 결정으로 선관위에 대한 직무 감찰이 금지돼, 6·3지방선거 선거인명부 관리나 선거 인력 배치, 선거 관리, 투표용지 재배분 등은 직접 조사가 불가하다. 감사원은 ▲출석 수당, 특별정려금, 교육 수당, 안건 검토 수당, 관리 수당, 격려금 등 선관위가 위원과 직원에게 주는 각종 수당도 적정한지 살펴보겠다고 했다. 선관위 직원들이 해외 선거 참관을 명목으로 몰디브 등 지역에 외유성 출장을 다녀온 것으로 드러나 논란이 된 가운데, ▲공무 국외 출장과 여비 집행도 들여다보겠다고 했다. 선관위가 재외국민 투표 관리를 명목으로 재외공관에 파견하는 재외선거관 관련 문제는 ▲재외국민 선거 관리 경비와 수당 지급 검사를 통해 살펴보겠다고 했다. 선관위가 국가계약법을 어기고 대다수 계약을 수의계약으로 체결했다는 의혹과 관련해서는 ▲수의계약 단가 산정은 적정한지, 일감 몰아주기나 쪼개기 계약, 특수관계자와의 계약, 특혜 등은 없었는지를 살펴보기로 했다. 감사원은 또 선관위의 ▲공정선거지원단 운영과 기간제 근로자 일용임금 집행 ▲업무추진비와 특근매식비 집행도 점검하고, ▲감사원이 과거 감사에서 고치라고 지적한 사항들을 제대로 고치고 있는지도 살피겠다고 했다. ▲당선이 무효가 된 후보자에게 지급했던 선거비용을 돌려받고 있는지도 점검하겠다고 했다.', 'crawl', '조선일보', '2026-07-06 00:00:24', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MYZDKOJSMY4WENTCMZRWKNRYGU.jpg', '2026-07-07 06:04:16', '2026-07-07 15:07:48.007287', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2335, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/06/2IHPZK44UNA75A4WWZM3274GQM/', 'https://www.chosun.com/politics/politics_general/2026/07/06/2IHPZK44UNA75A4WWZM3274GQM/', '정치', '靑 “반도체 추가 세수로 미래 대응 기금 신설”', '', '강훈식 대통령 비서실장은 5일 반도체 호황에 따른 추가 세수를 ‘호남 반도체’ 등 3대 메가 프로젝트, 청년 세대를 위한 투자 재원 등에 활용하기 위한 ‘미래 대응 기금’ 신설을 추진하겠다고 밝혔다. 정부 안팎에선 반도체 호황으로 내년까지 최대 100조원 안팎의 세금이 더 걷힐 것으로 예측하고 있다. 이 돈을 정부 부채를 갚는 데 써야 한다는 의견이 있지만, 이재명 대통령이 지난달 29일 발표한 반도체와 AI데이터센터 등 3대 메가 프로젝트에 활용하겠다는 입장을 공식화한 것이다. 강 실장은 이날 서울 삼청동 총리 공관에서 열린 고위 당정 협의회에서 “추가 세수로 기금을 조성해 ‘3대 메가 프로젝트’ 지원을 포함한 미래 성장 동력 창출, K자형 양극화 대응, 2030 청년을 위한 주거와 창업·일자리 지원 등 대한민국의 미래에 과감한 투자를 하고자 한다”고 말했다. 더불어민주당도 “추가 세수를 미래 세대와 대한민국 성장 동력 확충, 양극화 대응 등에 사용하겠다는 정부의 입장에 공감했다”며 속도감 있는 당정 협력에 나서겠다고 했다. 이날 회의에 참석한 한병도 민주당 대표 직무대행 겸 원내대표는 “당정이 모든 역량을 쏟아야 한다”며 “필요한 입법과 예산을 촘촘히 지원하겠다”고 했다. 다만 이날 당정은 기금 규모 등 세부 사안에 대해선 언급하지 않았다.', 'crawl', '조선일보', '2026-07-05 15:58:35', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/F6N3V7DL4BGYDMB6AIF7ESSWVQ.jpg', '2026-07-07 06:04:16', '2026-07-07 15:07:55.300253', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2339, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/06/XDJTTU7EABE7VI7LPN3FPOGPUE/', 'https://www.chosun.com/politics/assembly/2026/07/06/XDJTTU7EABE7VI7LPN3FPOGPUE/', '정치', '선관위 특검, 與 “제3자 추천”… 국힘 “野가 추천해야 공정 수사”', '', '더불어민주당은 5일 6·3 지방선거 투표 용지 부족 사태와 관련해 “이번 주 선거관리위원회 특검법을 제출하겠다”고 했다. 그러면서 특검 추천권을 제3자에게 주겠다고 했다. 하지만 국민의힘은 재차 “특검 수사의 실효성을 위해 야당에 추천권을 줘야 한다”며 강력 반발했다. 민주당이 뒤늦게 선관위 특검을 추진하겠다고 밝혔지만 여야 간 입장 차가 큰 만큼 특검법 처리 합의까지는 시간이 걸릴 전망이다. 한병도 민주당 대표 직무대행 겸 원내대표는 이날 페이스북에서 “정치적 유불리를 배제한 특검이라면, 오히려 독립성과 중립성이라는 선관위의 특수성을 고려해 대한변호사협회 등 제3자 추천이 더 현실적이고 공정할 것”이라며 이같이 밝혔다. 국민의힘의 ‘야당 추천 특검’ 주장에는 “진상 규명은 외면한 채 이번 사태를 정쟁으로 몰고 가기 위한 방해 공작이 아닌지 의심된다”고 했다. 민주당은 이번 주 발의하는 특검법 수사 범위에 ‘투표용지 인쇄 물량 축소 경위’ ‘선거일 지휘부 보고 누락 및 지연’ ‘선관위 내부 부패와 무능’ 등을 포함시킬 예정이다. 민주당 관계자는 “7월 임시국회 중에 처리할 것”이라며 “최대한 국민의힘을 설득하겠지만 안 되면 단독 처리 가능성도 있다”고 했다. 국민의힘 김승수 원내운영수석부대표는 이날 본지 통화에서 “공정한 수사를 위해 특검은 야당이 추천해야 한다”고 거듭 주장했다. 앞서 국민의힘은 지난달 9일 국민의힘이 특검 후보자를 2명 추천하고, 대통령이 그중 1명을 임명하도록 하는 특검법을 발의한 바 있다. 수사 범위에는 올림픽공원 집회 등에 대한 과도한 공권력 행사와 일부 지역 ‘쌍둥이 득표’ 논란 등도 넣었다. 국민의힘은 제3자 추천 특검의 경우에도 민주당의 압력이 들어갈 가능성이 높다고 보고 야당 추천을 주장 중이다. 이런 가운데, 국회 선관위 국정조사 특위 위원장인 국민의힘 윤상현 의원은 이날 국회 기자회견에서 올림픽공원 핸드볼경기장 개표소 내에 남아 있는 투표지 247만장에 대한 공개 재검표를 추진할 계획이라고 밝혔다.', 'crawl', '조선일보', '2026-07-05 15:48:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MEZDINBXGUYWMZDGMUZTGN3GG4.jpg', '2026-07-07 06:04:16', '2026-07-07 15:08:29.401972', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2342, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/05/CZS3Z2XDGBCGRN524QKXWZOTZM/', 'https://www.chosun.com/politics/assembly/2026/07/05/CZS3Z2XDGBCGRN524QKXWZOTZM/', '정치', '이진숙, 배재고에 응원 화환... “李 정권, 생각에 수갑 채우나”', '', '국민의힘 이진숙 의원이 이른바 ‘스타벅스 응원 구호’ 논란을 빚은 배재고등학교에 응원 화환을 보냈다. 이 의원은 배재고 야구부가 광주제일고등학교를 찾아 공식 사과하기 하루 전인 5일 자신의 페이스북에 “배재고에 화환을 보냈다”면서 화환 사진을 공유했다. 이 의원이 공개한 화환 리본에는 “스타벅스가 5·18과 무슨 관계가 있나”, “배재고 학생들과 함께 합니다”라는 문구가 적혔다. 이 의원은 해당 글에서 “이재명 정권은 생각에도 ‘수갑’을 채울 것인가”라고 했다. 이어 “스타벅스가 5·18과 광주에 대한 모욕을 상징한다면 스타벅스는 더 이상 영업을 해서는 안 될 것”이라며, 문제의 구호를 5·18과 광주에 대한 모욕으로 단정해 학생들을 징계하는 것은 “생각에 수갑을 채우는 짓”이라고 했다. 그는 또 “학생들이 그렇게 생각했다는 것이 아니다”라며 “‘스타벅스 가야지’라고 말한 것이 5·18과 광주를 모욕할 생각이었다고 판정 내린다는 것”이라고 했다. 이 의원은 “공포에 질려 있을지도 모를 배재고 학생들에게 조금이나마 힘을 주고 싶어 화환을 보냈다”고 했다. 이번 논란은 지난달 29일 서울 목동구장에서 열린 청룡기 전국고교야구선수권대회 배재고와 광주일고 경기에서 불거졌다. 배재고 학생들이 경기 도중 “스타벅스 가야지”라고 외쳤고, 일부 학생이 “탱크데이”라고 말한 장면이 알려지면서 5·18 민주화운동을 희화화했다는 비판이 제기됐다. 대한야구소프트볼협회는 지난 1일 스포츠공정위원회를 열고 배재고 야구부에 전국대회 6개월 출전 정지 징계를 의결했다. 배재고도 관련 학생들에 대한 생활교육위원회 회부 등 자체 징계 절차에 들어갔다. 배재고 야구부원과 학부모, 교직원 등은 6일 광주일고를 방문해 사과할 예정이다. 이후 광주일고 측과 함께 국립 5·18민주묘지를 참배할 계획이다. 배재고에는 최근 화환이 쇄도한 것으로 알려졌다. 학교 앞에는 배재고 야구부를 응원하는 화환과 비판 문구를 담은 근조 화환이 함께 놓였다고 한다. 일부 화환에는 “기죽지 마라”는 취지의 응원 문구가 적혔고, 다른 화환에는 5·18을 모욕했다는 비판 문구가 적혔다고 한다.', 'crawl', '조선일보', '2026-07-05 12:50:30', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/KAHWVW7CTRDVHBZWIDJKMEPCFU.jpg', '2026-07-07 06:04:16', '2026-07-07 15:08:34.982041', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2348, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/assembly/2026/07/04/QENCMZBPXFCVVDEBFTO2ERT4GY/', 'https://www.chosun.com/politics/assembly/2026/07/04/QENCMZBPXFCVVDEBFTO2ERT4GY/', '정치', '與 보완수사권 폐지 속도전에… 내부서도 “부작용 커”', '', '검찰청이 오는 10월 폐지되고 공소청과 중대범죄수사청(중수청)이 출범하는 가운데, 더불어민주당이 ‘검찰 보완수사권 전면 폐지’ 입법에 속도를 내고 있다. 하지만 야권과 법조계는 물론 여권 일각에서도 “형사사법체계 개편에 따른 부작용을 충분히 고려하지 않은 채 속도전에만 몰두할 경우 국민이 제도 공백에 따른 피해를 볼 수 있다”는 우려가 나오고 있다. 한병도 민주당 당대표 직무대행 겸 원내대표는 3일 당 회의에서 “검찰 개혁의 화룡점정이 될 형사소송법 개정은 원내, 정책위원회, 법제사법위원회가 힘을 합쳐 내용은 충실하게, 처리는 쾌속으로 진행하겠다”고 말했다. 형사소송법 개정안에는 검찰의 보완수사권을 전면 폐지하는 내용이 담길 예정이다. 이와 관련, 민주당은 전날 형사소송법 개정 TF를 꾸리고 본격적인 법 개정 절차에 돌입했다. 이를 위해 국민의힘이 민주당의 일방적인 상임위원장 선출 강행에 반발하며 국회 일정을 전면 보이콧하고 있는 상황에서도 민주당은 전날 야당 없이 22대 국회 후반기 첫 법사위를 열었다. 여권 강경파는 형사소송법 개정을 7월 내에 마무리해야 한다고 주장하고 있다. 정청래 전 대표는 “제헌절(17일) 전에 끝내자”고 했고, 김용민 의원도 “7월 내에 반드시 통과시켜야 한다”고 했다. 조국혁신당도 전날 “제헌절까지 입법을 마무리하자”고 요구했다. 지난달 민주당 서영교·김용민 의원, 조국혁신당 박은정 의원 등 강경파는 검사의 수사권과 수사지휘권을 전면 폐지하는 자체 개정안을 발의했는데, 법무부는 이 개정안과 관련해 대검찰청에 “검찰 의견을 달라”고 요청하기도 했다. 민주당 일각에서도 “충분한 숙의 없이 보완수사권을 폐지하면 부작용이 상당할 것”이란 우려가 나오고 있다. 증거인멸 우려가 크거나 공소시효가 임박한 사건 등 보완수사가 시급한 사건에서 수사 공백이 발생할 수 있고, 경찰의 무리한 수사를 견제할 수단도 사라질 것이란 것이다. 최근 민주당 의원 단체 대화방에서도 이 같은 지적이 이어졌다고 한다. 법조인 출신인 수도권 초선 의원은 “경찰이 ‘기소 의견 송치’한 사건에 한해 조건부로 보완수사권을 인정하자”면서 예외적 보완수사권을 허용하자고 했다. 다른 수도권 재선 의원도 “보완수사권이 사라질 경우 피해자 보호에 부족함이 없는지, 경찰 권력 견제가 가능한지 따져봐야 한다”는 취지의 글을 올렸다고 한다. 보완수사권의 필요성을 주장해온 정성호 법무부 장관도 이날 기자들과 만나 “정부의 입장이 있다고 하더라도 저기 계신 분(민주당 의원)이 입법권은 국회에 있다고 말하지 않는가”라며 “훌륭하신 의원들이 잘 논의하지 않겠나”라고 했다. 이재명 대통령도 필요하다는 입장을 고수해 왔지만 민주당 당대표 선거를 앞두고 친명·친청 간 선명성 경쟁이 벌어지자 최근 ‘부작용에 대한 책임도 국회가 질 것’이라며 강경파 손을 들어줬다. 당권 주자인 김민석 전 총리도 총리로서의 마지막 기자회견에서 “정부의 입장은 보완수사권 폐지”라고 못을 박은 바 있다. 민주당 지도부는 강경파의 입법 속도전에는 부정적이지만 이르면 다음 주 원내지도부 주도의 형사소송법 개정안을 발의할 것으로 알려졌다. 민주당 관계자는 “형사소송법을 최대한 빨리 법사위에서 논의하려고 한다”고 했다. 다만 원내지도부 핵심 관계자는 “고려해야 할 문제가 많아 8·17 전당대회 이전에는 법안 처리가 쉽지 않을 것”이라고 했다. 대안으로는 검사의 보완수사요구권을 실질화하고, 경찰 수사심의위원회를 상설화해 경찰 수사를 견제하는 방법 등이 검토되고 있다. 또 경찰이 검사의 정당한 보완수사 요구를 따르지 않을 경우 검사가 수사팀 교체를 요구하게 하는 방안도 거론되고 있다. 민주당 법사위원들은 경찰이 불송치한 사건에서 고발인의 이의 신청권을 허용할지 여부에 대해서도 논의 중이다. 앞서 민주당은 지난 2월 이 문제로 당청 간 갈등설이 나왔을 때 의원총회를 열고 보완수사권은 폐지하되 보완수사요구권은 유지하기로 당론을 정했었다. 국민의힘은 “사법 시스템 난도질”이라고 비판했다. 정점식 원내대표는 “민주당이 장악한 법사위는 죽을 사(死) 자를 써서, 법치주의가 사망한 법사(死)위로 전락했다”면서 “강성 지지층 환호에 도취된 민주당 법사위원들은 권력의 칼날로 법치주의를 난자할 것”이라고 했다. 이어 “수사와 기소를 완전히 분리하고 보완수사권마저 없앤다면 수사기관 사이의 사건 핑퐁이 무한정 늘어나게 된다”며 “이는 고스란히 피해자 고통으로 전가될 것”이라고 했다.', 'crawl', '조선일보', '2026-07-03 15:49:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MRTGEOLGGRSTKMZXHBTGGMRRGY.jpg', '2026-07-07 06:04:16', '2026-07-07 15:08:52.247008', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2356, 'https://www.chosun.com/arc/outboundfeeds/rss/category/politics/?outputType=xml', 'https://www.chosun.com/politics/politics_general/2026/07/03/HLLWZTIO7VGRTJBXOXKTRNYRQ4/', 'https://www.chosun.com/politics/politics_general/2026/07/03/HLLWZTIO7VGRTJBXOXKTRNYRQ4/', '정치', '李대통령, 7일 NATO 정상회의·9일 몽골 국빈 방문', '', '이재명 대통령이 7일부터 11일까지 튀르키예에서 열리는 북대서양조약기구(NATO·나토) 정상회의 참석 및 몽골 국빈 방문 일정을 소화한다. 위성락 청와대 국가안보실장은 3일 청와대 브리핑을 통해 “이재명 대통령이 마크 루터 나토 사무총장의 초청으로 7월 7~8일 튀르키예 앙카라에서 열리는 ‘2026 나토 정상회의’에 참석한 뒤, 이어 9~11일 오흐나 후렐수흐 몽골 대통령의 초청으로 몽골을 국빈 방문한다”고 발표했다. 지난달 G7 정상회의에 이어 한 달 만에 재개되는 이번 유라시아 외교 행보는 글로벌 책임 강국으로서의 위상 제고와 함께 실리적 경제 안보 영토를 확장하겠다는 이 대통령의 강력한 의지가 반영됐다는 설명이다. 순방의 첫 행선지는 튀르키예 앙카라다. 이 대통령은 7일 오후 도착 직후 마크 루터 나토 사무총장과 면담하고 한·나토 안보 협력 강화 방안을 논의한다. 이어 일본, 호주, 뉴질랜드 등 인도·태평양 파트너국(IP4) 대표들과 함께 최고위급 플랫폼인 ‘소인수 회담’에 참석해 역내 안보 공조를 다질 예정이다. 이번 나토 행보의 핵심 분수령은 올해 정상회의의 메인 이벤트인 ‘나토 방산 포럼’ 참석이다. 이 대통령은 약 1000명의 글로벌 방산 관계자가 집결한 자리에서 ‘공동의 가치, 더욱 강한 산업 기반’을 주제로 기조 발언하고 패널 토론을 주도한다. 위 실장은 “세계 국방비의 55%를 차지하는 나토 시장을 상대로 K방산의 신속한 조달 능력을 각인시킬 것”이라며 “정상 차원의 신뢰를 바탕으로 우리 기업들이 나토 공급망에 안정적으로 편입되도록 하겠다”고 했다. 8일에는 에르도안 튀르키예 대통령이 주최하는 공식 만찬을 비롯해 주요 방산 수요국들과의 연쇄 양자 회담이 긴밀히 조율 중이다. 이어 이 대통령은 9일 몽골 울란바타르로 이동해 경제 안보와 외교 다변화를 위한 국빈 방문 일정을 소화한다. 역대 정부 중 가장 이른 시기인 취임 1년 만에 성사된 국빈 방문으로, 양국 정상은 첫 회담을 통해 수교 40주년이 되는 2030년까지 인적 교류 50만명 시대를 여는 ‘한몽관계의 황금시대’ 공동선언을 발표한다. 풍부한 자원을 보유한 몽골과의 핵심 광물 공급망 협력, 식량 안보, 황사 대응 네트워크 다변화가 집중 논의된다. 이 대통령은 당일 저녁 양국 경제인들이 모이는 ‘한몽 비즈니스 포럼’에서 기조연설을 한다. 10일에는 몽골 독립운동을 도운 이태준 열사 기념관 방문, 교민 오찬, 국회의장·총리 접견 등을 거쳐 국빈 만찬에 임한다. 특히 순방 마지막 날인 11일에는 한국 정상 최초로 몽골 최대 명절인 ‘나담축제’ 개막식에 최고 주빈(主賓)으로 참석한다. 안보 측면에서는 대북 대화 재개를 위한 외교적 자산 활용이 기대된다. 위 실장은 “몽골은 과거 소련에 이은 북한의 두 번째 수교국으로 전통적 우호 관계를 유지하고 있다”며 “매년 개최되는 ‘울란바타르 대화’ 등 몽골의 외교적 자산과 긴밀히 공조해 한반도 평화 정착을 위한 실현 가능한 대화 재개 여건을 조성하겠다”고 설명했다.', 'crawl', '조선일보', '2026-07-03 05:30:28', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/RHEIG3JVNJIBRFYCEEBHDNEBYE.JPG', '2026-07-07 06:04:16', '2026-07-07 15:09:09.116774', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2374, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/economy_general/2026/07/07/RHZ7DR6W5NA7DE5JETHEBB4WSQ/', 'https://www.chosun.com/economy/economy_general/2026/07/07/RHZ7DR6W5NA7DE5JETHEBB4WSQ/', '경제', '아파트 20억에 팔고 양도세 0원... 고가 주택 탈세자들 318억 추징', '', '2주택자인 A씨는 양도차익이 큰 서울 고가아파트를 양도하기 전 본인이 거주하는 저가아파트를 모친의 지인 B씨에게 이전했다. 이후 A씨는 고가아파트를 제3자에게 약 20억원에 양도하면서 1세대 1주택자로 비과세 적용해 양도세를 신고했다. 하지만, A씨와 B씨의 거래는 허위였다. A씨는 양도 후 허위 전세계약을 맺어 계속 같은 집에 거주했고, 나중에 명의를 돌려받기까지 탈세 협조 대가로 매월 수십만원의 사례비도 지원했다. A씨는 국세청에 적발돼 중과세율을 적용한 양도세 10억원을 추징당했다. 여기에 본인과 허위 거래를 주도한 모친, B씨까지 조세포탈 혐의로 검찰 수사를 받게 됐다. 국세청이 지난해 10월 A씨를 비롯해 30억원 이상 초고가 주택 등 부동산 탈세 혐의자 104명을 동시조사해 7일까지 총 731억원의 탈루금액을 적발했다고 밝혔다. 추징 세금만 318억원이다. 국세청에 따르면, 이번 조사에서는 부모로부터 몰래 증여받은 자금으로 고가 아파트를 취득해 증여세를 탈루한 사례가 적발됐다. 또한 가장매매로 부당하게 1세대 1주택 비과세를 적용받아 양도소득세를 회피한 사례가 다수 적발됐다. 가장매매란 A씨처럼 다주택자가 친척·지인 등에게 저가주택을 명의만 허위 이전한 후, 양도차익이 큰 고가주택을 양도하면서 1세대 1주택 비과세를 부당 적용하거나 중과세율을 회피하는 행위를 말한다. 또한 국세청은 부동산 거래 과정에서 드러난 양도세･증여세 탈루 뿐만 아니라, 자금원천이 사업소득 누락 및 법인자금 유출과 관련된 경우 사업체까지 조사범위를 확대해 법인세･소득세 등 누락된 세금을 추징했다. 국세청은 조사과정에서 사기나 그 밖의 부정한 방법으로 조세를 포탈한 사실이 확인된 건은 40%에 상당하는 부당 과소신고가산세를 부과했다. 조세범처벌법에 따라 6명은 검찰에 고발하고 4명은 벌금 상당액 7억원을 통고처분했다고 했다. 명의신탁 등 부동산실명법 위반행위가 확인된 20명에 대해서도 과징금 부과 및 형사처벌 등 조치될 수 있도록 관할 지방자치단체에 통보했다.', 'crawl', '조선일보', '2026-07-07 04:35:37', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GMZTCNRXMRRDKNLFGUZWINZUGA.jpg', '2026-07-07 06:04:17', '2026-07-07 15:09:44.973825', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2375, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/money/2026/07/07/HRWMPZVVUJDH3LYKAZQ5GMR6KE/', 'https://www.chosun.com/economy/money/2026/07/07/HRWMPZVVUJDH3LYKAZQ5GMR6KE/', '경제', '코스피 반도체 관련주 ‘S7’도 무더기 급락', '', '코스피 시가총액 상위 ‘에스(S)’ 계열 대형주가 7일 일제히 급락했다. 삼성전자의 2분기 잠정 실적이 사상 최대치를 새로 썼는데도 시장의 높아진 기대에는 미치지 못한 것이 방아쇠가 됐다. 이날 낮 12시 54분 현재 삼성전자는 전 거래일 대비 8.73% 하락 중이다. SK하이닉스(-9.22%), SK스퀘어(-12.78%), 삼성전자우(-7.81%), 삼성전기(-10.50%), 삼성생명(-7.50%), 삼성물산(-6.45%)도 동반 급락했다. 이들은 이른바 ‘S7’으로 묶인다. 코스피 시총 1% 이상 종목 가운데 종목명 이니셜이 에스(S)로 시작하는 7개 종목으로, 대장주 삼성전자·SK하이닉스와 지분·업무 등에서 직간접적으로 연관돼 있다. 특히 SK스퀘어는 SK하이닉스 지분을 보유한 중간지주사여서 반도체 대장주 주가에 연동되는 구조다. 이날 삼성 대장주가 흔들리자 나머지 계열주가 무더기로 끌려 내려간 셈이다. 삼성전자는 이날 연결 기준 2분기 잠정 실적으로 매출 171조원, 영업이익 89조4000억원을 공시했다. 전년 동기 대비 매출은 129.31%, 영업이익은 1810.26% 급증한 사상 최대치다. 지난해 4분기 이후 3개 분기 연속 최대 실적 행진이다. 표면적으로는 ‘어닝 서프라이즈’다. 금융정보업체 에프앤가이드가 집계한 영업이익 컨센서스(증권사 평균 전망치) 84조9787억원을 4조원 이상 웃돌았다. 문제는 시장 일각의 눈높이가 이미 그 위에 있었다는 점이다. 메모리 수퍼사이클(장기 호황)과 고대역폭메모리(HBM·High Bandwidth Memory) 수요 확대 기대가 커지면서 영업이익이 90조~100조원에 이를 것이란 전망까지 나왔던 터라, 기록적 실적에도 ‘기대 대비 미스’로 받아들여졌다. 증권가에서는 실적 개선 기대감으로 주가가 먼저 오른 뒤 발표를 계기로 차익 실현이 몰리는 전형적 ‘Sell the News(뉴스에 판다)’ 패턴으로 해석한다. 실제 삼성전자는 최근 2년간 잠정 실적 발표일에 주가가 하락한 사례가 반복돼 왔다. 다만 이번 조정을 하락 추세 전환으로 보긴 이르다는 시각도 있다. 인공지능(AI) 서버 투자 확대와 HBM 수요 증가, 메모리 업황 개선이라는 큰 흐름이 훼손된 것은 아니기 때문이다. 이번 분기에 약 20조원으로 추정되는 성과급 충당금을 반영한 점을 감안하면 실질 영업이익은 100조원을 넘었을 것이란 추정도 나온다. 향후 주가 방향은 3분기 실적 개선 폭과 HBM 경쟁력, AI 반도체 수익성 확대 여부가 좌우할 전망이다.', 'crawl', '조선일보', '2026-07-07 04:22:30', '보수', 'ready', 'https://www.chosun.com/pf/resources/images/thumb_meta.png?d=2276', '2026-07-07 06:04:17', '2026-07-07 15:09:47.019696', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2380, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/economy_general/2026/07/07/IDYMLRR6Y5DN7BEOCNVGJB7BFA/', 'https://www.chosun.com/economy/economy_general/2026/07/07/IDYMLRR6Y5DN7BEOCNVGJB7BFA/', '경제', '공정위, 물엿·포도당 등 전분당 가격 담합한 제당사 4곳에 과징금 7476억원 부과...담합 과징금 역대 최대 규모', '', '공정거래위원회가 대상, 사조CPK, 삼양사, CJ제일제당 등 4개 제당사들이 지난 2018년부터 7년여간 식품업체와 제지사 등 사업자 간 거래에 적용되는 전분 및 전분당 가격을 담합한 혐의에 대해 과징금 7476억원을 부과했다고 7일 밝혔다. 공정위가 담합 사건에 부과한 과징금 중 역대 최대 금액이다. 전분당은 옥수수를 분쇄해 만드는 전분과 이를 분해해 생산하는 물엿·포도당·액상과당 등을 통칭한다. 라면, 빵, 과자 등 식품 원재료나 제지·철강 등 산업용 접착·코팅 소재로도 사용돼 가공식품 가격을 결정하는 주재료로 꼽힌다. 이들 업체들은 국내 B2B(기업간 거래) 전분당 시장에서 매우 높은 점유율(전분 95.7%, 전분당 86.4%)을 차지하고 있다. ◇7년 5개월간 전분당 가격 담합...합의대로 거래처에 공문 잘 보냈나 확인도 공정위에 따르면, 이들은 지난 2018년 5월부터 2025년 10월까지 7년 5개월의 장기간 동안 총 13차례에 걸쳐 판매가격의 인상·인하 폭과 시기 등을 합의하고 이를 실행한 것으로 드러났다. 구체적으로 제당사들은 담합 기간 동안 전분당의 원재료인 옥수수 가격이 인상되는 시기에는 원가 상승분을 신속히 거래상대방에게 전가하기 위해 전체 B2B 거래처를 대상으로 8차례에 걸쳐 판매가격 인상을 합의했다. 옥수수 가격이 떨어지는 시기에는 5차례에 걸쳐 거래처의 가격 인하 요구에 대응해 인하 폭을 최소화하고 인하 시기를 최대한 늦줬다. 이들 업체는 전분당 가격을 변경할 때 거래처의 저항을 최소화하기 위해 가격변경의 폭과 시기뿐만 아니라, 가격변경의 근거(환율, 원료가 등)와 공문 발송 시기 등도 구체적으로 합의했다. 이 과정에서 제당사들은 전분당 품목별 목표가격을 합의한 뒤, 회사사별로 그보다 높은 금액을 순차적으로 거래처에 통보함으로써 거래처가 이 목표 가격을 최대한 수용하도록 압박·유도했다. 또한 이들은 실제 합의 내용대로 거래처에 공문을 발송하면서 이행 여부를 매우 철저하게 점검하기도 했다. ◇원료인 옥수수값 상승에도 답합으로 영업이익 하락 최소화 공정위는 이같은 담합으로 제당사들이 옥수수 가격 상승기에는 영업이익 하락을 최소화하고, 가격이 하락하는 동안에는 영업이익이 개선됐다고 판단했다. 일례로, 우크라이나-러시아 전쟁으로 국제 옥수수 가격이 급등한 2022년 11월 전분당 판매가격은 담합 시작 시기(2018년 5월)에 비해 최대 73% 높았고, 그 결과 전분사들은 옥수수 가격이 상승하는 동안에도 영업이익의 하락을 최소화할 수 있었다는 것이다. 공정위는 4개 제당사에 대해 총 7475억 7800만원의 과징금을 부과했다. 업체별로는 대상이 2341억4100만원, 사조씨피케이 2001억3200만원, 삼양사 2103억4000만원, CJ제일제당 1029억6500만원이 부과됐다. 공정위는 이외에도 법위반행위 금지명령과 독자적 가격 재결정 명령도 내렸다. 제당사들은 국내에서 판매하는 전분당 제품에 대해 담합 전 경쟁을 회복하는 수준으로 가격을 독자적으로 재결정하고, 향후 3년간 반기마다 공정위에 변경 내역을 보고해야 한다. 공정위의 가격 재결정명령은 밀가루·인쇄용지 담합에 이어 네번째로 부과됐다. 한편, 공정위는 전분당 입찰 시장에서 가격 담합을 한 혐의를 받는 4개 제당사와 전분당 부산물(단백피, 글루텐 등) 분야에서 가격담합을 한 혐의의 3개 제당사(대상·사조CPK·삼양사)에 대한 제재 절차에 착수했다고도 했다. 공정위는 이들 업체에 검찰의 공소장 격인 심사보고서를 송부하고 제재 여부를 결정하기 위한 심의 절차에 착수했다는 것이다. 전분당 입찰 시장에서의 담합 관련매출액은 9400억원, 전분당 부산물 판매가 담합 관련매출액은 1조5500억원에 달하는 것으로 조사됐다. 관련 매출액의 최대 20%까지 과징금을 부과할 수 있는 점을 고려하면, 제당사들의 과징금 부담은 향후에도 더 커질 것으로 보인다.', 'crawl', '조선일보', '2026-07-07 03:00:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MZRGGNBVMYZWGYJZGJRGGZJQMU.jpg', '2026-07-07 06:04:17', '2026-07-07 15:09:56.425183', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2383, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/money/2026/07/07/BGAAKRJLGBHUHI74RZSIPHC4AE/', 'https://www.chosun.com/economy/money/2026/07/07/BGAAKRJLGBHUHI74RZSIPHC4AE/', '경제', '삼성전자 최대 실적에도 주가 29만원 깨졌다, 왜?', '', '7일 삼성전자 주가는 전날 대비 2.83% 하락한 30만9000원에 출발했다. 오후 1시 44분 현재는 9.43%까지 빠지며 28만8000원으로 29만원선도 무너졌다. 앞서 삼성전자는 2026년 2분기 잠정 실적을 발표했지만, 시장 예상치에 조금 못 미치는 ‘어닝 미스(실적이 기대에 못 미치는 것)’라는 분석이 나온다. 이날 삼성전자는 연결 기준 매출 171조원, 영업이익 89조4000억원이라는 사상 최대 실적을 발표했다. 현재 SK하이닉스도 10.07% 하락한 210만7000원에 거래 중이다. 간밤 SK하이닉스의 ADR이 수요 조사에서 초과 청약됐다는 외신이 나왔지만, 삼성전자의 어닝 미스가 반영된 것으로 보인다. 코스피는 7.51% 하락한 7446.86를 나타내고 있다. 오전 한때 5% 이상 하락이 1분 이상 지속되며 프로그램 매매가 일시 중단되는 매도 사이드카가 발동되기도 했다. 삼성전자 어닝 미스 영향으로 일본 키옥시아 주가도 11.26% 하락한 7만2400엔에 거래 중이다. 간밤 미국 시장에서도 반도체 기업의 주가는 좋지 않았다. 메모리반도체 기업인 마이크론은 0.91% 오른 984.31달러로 마감했지만, 폐장 후 삼성전자의 ‘어닝 미스’를 반영해 폐장후 -2.85% 하락된 가격에 거래되고 있다. 샌디스크 주가도 0.0033% 마감한 1744.43달러에 마감했지만 폐장 후 3.29% 하락했다. 모건스탠리는 “반도체 랠리가 속도 조절에 들어간 것”이라고 블룸버그TV에서 말했다. 증권가는 이번 실적을 ‘어닝 미스’로 평가했다. 영업이익 89조4000억원은 시장 컨센서스(전망치 평균·약 85조원)를 웃돌았지만, 90조~100조원을 내다봤던 일부 눈높이에는 미치지 못했다. 메모리 수퍼사이클과 고대역폭메모리(HBM) 판매 확대로 실적 자체는 기록을 갈아치웠지만, 기대가 워낙 앞서 있었던 탓에 ‘재료’로서의 힘은 반감됐다는 분석이다. 이런 흐름은 낯설지 않다. 최근 2년(2024년 2분기~2026년 1분기) 여덟 차례 잠정실적 발표를 되짚어 보면, 발표 당일 주가가 하락한 경우가 3번, 다음날까지 내린 경우가 4번이었다. 실적이 좋았던 분기도 예외가 아니었다. 영업이익이 전 분기의 2.6배로 뛴 2025년 3분기(12조1000억원)에도 발표 당일 주가는 1.82% 내렸고, 국내 기업 최초로 분기 영업이익 20조원을 넘긴 2025년 4분기 발표날에도 1.56% 하락했다. 호재가 주가에 미리 반영된 뒤 발표를 계기로 차익 실현 매물이 나오는, 이른바 ‘재료 소멸’ 패턴이다. 반대의 경우도 있었다. 영업이익 57조2000억원으로 시장을 놀라게 한 2026년 1분기에는 발표 당일 1.76%, 다음날 7.12% 뛰었다.', 'crawl', '조선일보', '2026-07-07 00:09:21', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GRSTKNZSGUZTCYJWGZTDCMLGHA.jpg', '2026-07-07 06:04:17', '2026-07-07 15:10:03.764288', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2385, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/economy_general/2026/07/07/GBQWCODDMU3TGMJRHAZDAMBUMI/', 'https://www.chosun.com/economy/economy_general/2026/07/07/GBQWCODDMU3TGMJRHAZDAMBUMI/', '경제', '구윤철 “지방 근로자 소득세 서울보다 더 감면”', '구윤철 부총리 겸 재정경제부 장관이 지방 근로자에 대한 소득세 감면 등을 검토하겠다고 밝혔다. 구 부총리는 7일 MBC 라디오 ‘김종배의 시선집중’에 출연해 “지방에서 근무하면 여러 환경이 열악한 부분을 감안해 서울의 소득세보다는 조금 더 감면을 해주겠다”고 밝혔다. 그는 “소득공제나 세액공제 등 방법은 지역에 있는 근로자들의 희망 사항을 감안해 검토 중', '구윤철 부총리 겸 재정경제부 장관이 지방 근로자에 대한 소득세 감면 등을 검토하겠다고 밝혔다. 구 부총리는 7일 MBC 라디오 ‘김종배의 시선집중’에 출연해 “지방에서 근무하면 여러 환경이 열악한 부분을 감안해 서울의 소득세보다는 조금 더 감면을 해주겠다”고 밝혔다. 그는 “소득공제나 세액공제 등 방법은 지역에 있는 근로자들의 희망 사항을 감안해 검토 중”이라고 했다. 나아가 지방 근로자의 자녀 교육비 지원 가능성이 있다는 점도 내비쳤다. 인공지능(AI)·반도체 산업 지원과 관련해선 연구·개발(R&amp;D), 투자에 대한 세제 지원 확대, 이월공제 등을 거론했다. 구 부총리는 “이익이 생겨서 지금은 세금을 내더라도 나중에 세금을 못 내는 시기가 있을 수 있다. 그때 이월공제까지 해주려고 생각한다”며 “정부는 기업이 투자하는 데 필요한 인프라, 인력, 규제, 재정, 세제 등을 총력 대응해 지원할 계획”이라고 했다. 반도체 호황에 따른 초과 세수와 관련해선 “에프앤가이드의 올해 영업이익 전망을 보면 삼성전자와 SK하이닉스 두 곳만 600조원 영업이익이 예상되고 평균 20%만 잡아도 어마어마한 돈(120조원)이 된다”며 “두 기업이 그동안의 법인세를 다 내는 구도”라고 했다. 그러면서 “(초과 세수를) 추가 세수라고 말하고 싶다”며 “신설 ‘미래대응기금’을 통해 대체 불가능한 대한민국을 위한 미래 작업을 위해 쓰기 위해 내부적으로 검토 중이다. 관련 법안은 정기 국회(9월) 전에 할 수 있다면 해야 할 정도로 속도가 필요하다”고 했다. 구 부총리는 지역별 산업 육성 전략에 대해선 “호남권을 반도체 제2 생산기지, 충청권을 패키징 중심지, 영남권을 AI 관련 소재·부품·장비(소부장) 중심으로 특화하겠다”며 “한반도 전체가 하나의 AI 반도체 에코 시스템이라고 판단하고, 전국의 운동장을 골고루 잘 활용할 계획”이라고 했다. 구 부총리는 부동산세 개편 방향에 대해선 “보유세와 거래세 두 가지가 밸런스(균형)를 이뤄야 한다는 차원에서 함께 보고 있다”며 “기본적으로 집은 ‘바잉’(buying·매수)이 아닌 ‘리빙’(living·거주)’이라는 원칙하에 실거주자 중심으로 주택 시장이 확립될 수 있도록 하겠다”고 했다. 정부는 이달 말 세제 개편안을 발표할 예정이다.', 'crawl', '조선일보', '2026-07-07 05:04:40', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MEYWMY3EGU4GGZRSHAZTSYJXGI.jpg', '2026-07-07 06:04:17', '2026-07-07 15:10:07.604469', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2386, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/stock-finance/2026/07/07/UMDSYVBGIBGQ7GC73IUDPQJINE/', 'https://www.chosun.com/economy/stock-finance/2026/07/07/UMDSYVBGIBGQ7GC73IUDPQJINE/', '경제', 'SK하이닉스 미국 상장, 전직 오픈AI 연구원도 투자', '', 'SK하이닉스의 미국 나스닥 상장이 10일(이하 현지시각)로 다가온 가운데, 현지에서 흥행 조짐이 나타나고 있다. 6일 파이낸셜타임스(FT)에 따르면, 전직 오픈AI 연구원 레오폴드 아셴브레너가 세운 헤지펀드 시추에이셔널 어웨어니스, 영국계 장기 투자 운용사 베일리기포드, 기술주 투자사 코튜가 SK하이닉스가 발행하는 미국예탁주식(ADS) 가운데 최대 70억달러어치를 인수하겠다는 뜻을 밝혔다. 시추에이셔널 어웨어니스는 AI 관련주 투자로 이름이 알려져 있다. ADS는 ‘주식’이고, ADR은 그 주식의 ‘보관증’으로 사실상 동일하다. 미국 예탁기관이 한국 원주를 대신 보관하고, 그 원주를 잘게 나눈 지분을 미국 시장에 내놓는다. 이 지분 한 조각이 ADS다. ADR은 금을 창고에 맡기고 받는 보관증서와 같다. SK하이닉스는 6일부터 9일까지 글로벌 기관투자가를 상대로 로드쇼(투자 설명회)를 진행한다. 10일 공모가를 확정하고 나스닥에서 거래를 시작한다. ◇외국기업 기준 최대 규모 이번 상장은 미국에 상장하는 외국 기업으로는 사상 최대 규모다. SK하이닉스는 전체 발행주식의 약 2.5%인 1779만 주를 신주로 발행해 ADR 형태로 내놓는다. 조달 규모는 281억달러, 약 43조1400억원으로 추산된다. 이는 2014년 중국 알리바바의 250억달러, 2019년 사우디 아람코의 256억달러를 넘어서는 액수다. 아시아 기업의 뉴욕 증시 상장을 통틀어도 최대 사례로 꼽힌다. 당초 조달 규모는 45조4500억원으로 제시됐다. 지난달 24일 이사회 결의 전일 종가가 기준이었다. 이후 주가가 하락하면서 43조원대로 줄었다. 최종 금액은 수요예측 결과에 따라 다시 달라진다. 조달 자금은 전액 국내 생산설비에 투입된다. 용인 반도체 클러스터 첫 팹과 청주 첨단 패키징 공장 건설, 네덜란드 ASML의 극자외선(EUV) 노광장비 구매가 핵심 사용처다. SK하이닉스는 3분기 순현금이 100조원에 이를 것으로 예상돼 당장 돈이 급한 상황은 아니다. 상장의 방점은 자금 조달보다 기업가치 재평가에 찍혀 있다. ◇마이크론 가치 따라잡을까 상장의 최대 관전 포인트는 미국 경쟁사 마이크론 수준의 밸류에이션을 인정받느냐다. 6일 종가 기준 SK하이닉스의 2026년 선행 주가수익비율(PER)은 7.42배다. 마이크론은 9.44배다. 마이크론은 HBM 시장에서 SK하이닉스와 삼성전자에 밀린 3위 업체다. 그런데도 SK하이닉스가 더 낮게 거래된다. 한국 증시에 묶여 해외 투자자의 접근이 제한된 탓이라는 분석이 많다. 저평가 요인을 상장으로 걷어내겠다는 것이다. 마이크론의 가치를 그대로 대입하면 산술적으로 약 27%의 상승 여력이 나온다. 여기에 나스닥 100 등 주요 지수 편입 자격을 확보하면 이를 추종하는 상장지수펀드(ETF)의 기계적 매수 수요도 기대된다. ◇신주 발행 지분희석 위험 하지만 미 주식시장에 상장되더라도 펀드들이 바로 투자하지 않을 수 있다는 지적도 나온다. 미래에셋증권은 ETF·펀드가 관찰 기간을 거쳐 순차적으로 담기 때문에 재평가가 장기에 걸쳐 이뤄질 수 있다고 봤다. 발행주식의 2.5%만큼 신주가 발행되며 기존 주주 몫이 그만큼 줄어드는 지분 희석 위험이 있다. ADR만 오르고 본주는 안 따라올 수도 있다. 대만 TSMC의 경우 미국 ADR과 본토 주식 간 가격 괴리가 10% 이상 벌어지는 경우가 잦다. 다만 여기엔 한국은 대만보다 시장이 개방적이어서 우려가 덜하다는 반론도 나온다. 예탁결제원을 통한 원주와 ADR 간 교환이 대만보다 수월하고, 외국인통합계좌 등 우회로도 마련돼 있다는 것이다. 삼성전자의 추격도 변수다. 삼성전자는 2월 업계 최초로 HBM4 양산 출하에 성공했고, AMD는 차세대 AI 칩의 HBM4 주공급사로 삼성전자를 지명했다. SK하이닉스의 엔비디아 독점 공급 구도가 흔들릴 수 있다. 가장 근본적인 위험은 메모리 사이클이다. SK하이닉스는 매출의 90% 이상이 메모리에 쏠려 있다. AI 데이터센터 투자가 둔화되거나 HBM 계약 단가가 꺾이면, 다각화된 삼성전자보다 훨씬 가파른 실적 충격을 받는다. 미국 자본시장에 편입되는 만큼 중국 우시·다롄 공장을 겨냥한 미국의 수출통제 감시도 더 직접적으로 받게 된다. ◇ADR 10대1, 왜 이렇게 쪼갰나 이번 상장에서 SK하이닉스는 보통주 1주에 ADR 10주를 대응시켰다. ADR 1주 가격이 원주 1주의 10분의 1이 되는 구조다. 정확히는 ‘분할 상장’이 아니라 ADR 예탁비율(ADR ratio)을 10대 1로 설계한 것이다. 한국 원주는 그대로 있다. 그 원주를 미국 예탁기관에 맡기고, 원주 1주 위에 ADR 10주를 얹어 발행한다. 원주 발행주식 수는 그대로이고 ADR이라는 별도 증서의 단위만 잘게 나눈 것이다. ADR은 원주와 1대 1로 묶을 의무가 없다. 발행 기업이 비율을 자유롭게 정한다. SK하이닉스는 10주를 택했다. 이유는 초고가주를 피하기 위해서다. 원주 1주를 달러로 환산하면 1600달러에 달한다. 쪼개지 않고 그대로 ADR로 올리면 SK하이닉스는 나스닥에서 손에 꼽히는 초고가주가 된다. 미국은 주당 1000달러가 넘는 종목을 ‘초고가주(four-digit stock)’로 분류한다. 개인은 물론 기관도 매수 부담이 커지는 구간이다. 10대 1로 나누면 주당 150달러 대로 내려간다. 엔비디아(195달러)와 비슷한 가격대다. 접근성과 유동성이 좋아지고, 비교 대상과 나란히 놓고 평가받기도 쉬워진다.', 'crawl', '조선일보', '2026-07-06 23:56:24', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/UNT2JZ6BOVEE5K6XVLDBMORNGQ.jpg', '2026-07-07 06:04:17', '2026-07-07 15:10:09.508534', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2404, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/economy_general/2026/07/07/HAZGGYTGMYYTEMJZMZTDSYLGME/', 'https://www.chosun.com/economy/economy_general/2026/07/07/HAZGGYTGMYYTEMJZMZTDSYLGME/', '경제', '아파트 20억에 팔고 양도세 0원...다른 집 지인에 넘긴 척 세금 탈루', 'A씨는 보유한 아파트 2채 중 1채를 20억원에 팔면서 양도세를 한 푼도 내지 않았다. A씨의 경우 다주택자 중과세율이 적용돼 10억원의 양도세를 내야 했다. 그런데 아파트 매도 전 본인 명의 다른 집을 지인에게 넘겨 1주택자가 됐다고 신고해 양도세 비과세 혜택을 받은 것이다. 국세청 조사 결과, A씨는 지인에게 넘겼다는 아파트에 계속 거주한 것으로 나타났', 'A씨는 보유한 아파트 2채 중 1채를 20억원에 팔면서 양도세를 한 푼도 내지 않았다. A씨의 경우 다주택자 중과세율이 적용돼 10억원의 양도세를 내야 했다. 그런데 아파트 매도 전 본인 명의 다른 집을 지인에게 넘겨 1주택자가 됐다고 신고해 양도세 비과세 혜택을 받은 것이다. 국세청 조사 결과, A씨는 지인에게 넘겼다는 아파트에 계속 거주한 것으로 나타났다. 또 지인의 취득세·재산세를 대신 내주고 지인에게 매월 수십만원씩 준 것으로도 조사됐다. 국세청은 A씨가 안 낸 양도세를 추징하고, A씨와 지인을 조세포탈 혐의로 검찰에 고발했다. 국세청은 부동산 탈세 혐의자 80여명이 안 낸 세금 318억원을 추징했다고 7일 밝혔다. 이중 6명은 조세포탈 혐의로 검찰에 고발했다. 앞서 작년 10월 서울 강남과 마·용·성(마포 용산 성동) 등 초고가주택 부동산 탈세 혐의자 104명에 대한 동시 세무조사에 착수한 결과다. 국세청 관계자는 “이들의 탈루 규모는 731억원에 달한다”고 밝혔다. 이번 조사에서는 다주택자이면서 1주택자로 가장해 양도세 비과세를 적용받은 사례가 여러 건 적발됐다. 2주택자인 B씨는 보유한 수도권 아파트를 지인에게 명의만 이전하고 단독주택을 15억원에 팔면서 비과세 혜택을 받았다. 국세청에 따르면, B씨는 지인이 실제 아파트를 산 것처럼 보이려고 친구와 회사동료 등을 통해 지인에게 아파트 거래대금을 몰래 전달했다고 한다. 또 부모에게 증여받은 돈으로 고가 아파트에 살면서 증여세를 내지 않은 사례도 적발됐다. 40대인 C씨는 무직 상태로 월세가 700만원이 넘는 서울 강남 소재 아파트에 거주했다. 또 매년 생활비로 수억원을 쓰고 수십억원 어치 주식을 산 것으로도 나타났다. 국세청 조사 결과 C씨는 임대업자인 부모에게 월세, 주식 투자자금, 생활비 등 총 20여억원을 지원받으면서 증여세를 내지 않은 것으로 조사됐다. 국세청은 C씨에게 증여세 13억원을 추징했다. 국세청은 “다주택자 중과 재개 후 증여 거래가 늘어날 우려가 있는 만큼 증여 재산을 저가 평가하거나 증여세를 대납하는 등 편법 증여가 없는지 검증할 예정”이라고 했다.', 'crawl', '조선일보', '2026-07-07 03:00:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GQZDANZRMUZWGMRYGVQTONTDGM.jpg', '2026-07-07 06:04:17', '2026-07-07 15:10:45.397445', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2405, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/economy_general/2026/07/07/MFQTONZYHE4DIM3FMM2DQODFHE/', 'https://www.chosun.com/economy/economy_general/2026/07/07/MFQTONZYHE4DIM3FMM2DQODFHE/', '경제', '공정위, 전분당 가격 담합 ‘대상·사조·삼양·CJ’에 과징금 총 7476억원', '공정거래위원회는 전분당 가격을 담합한 대상(약 2341억원), 사조CPK(약 2001억원), 삼양사(약 2103억원), CJ제일제당(약 1030억원) 등 4개 기업에 역대 최대 규모인 과징금 총 7476억원을 부과했다고 7일 밝혔다. 공정위는 이들에게 독자적으로 가격을 재결정하고, 3년간 반기마다 변경 내용을 보고하도록 했다. 공정위에 따르면, 가격 담합에', '공정거래위원회는 전분당 가격을 담합한 대상(약 2341억원), 사조CPK(약 2001억원), 삼양사(약 2103억원), CJ제일제당(약 1030억원) 등 4개 기업에 역대 최대 규모인 과징금 총 7476억원을 부과했다고 7일 밝혔다. 공정위는 이들에게 독자적으로 가격을 재결정하고, 3년간 반기마다 변경 내용을 보고하도록 했다. 공정위에 따르면, 가격 담합에 가담한 4개 기업은 2018년 5월부터 2025년 10월까지 총 13차례에 걸쳐 판매가격의 인상·인하 폭과 시기 등을 합의했다. 이들은 국내 전분 시장에서 95.7%, 전분당 시장에서는 86.4%의 점유율을 차지하는 독과점 사업자로, 공정위는 가격 담합으로 판매 가격이 73% 인상됐다고 판단했다. 공정위가 산정한 관련 매출액은 6조525억원이다. 남동일 공정위 부위원장은 “이번 가격 담합을 매우 중대한 사안으로 보고 과징금 부과기준율은 15%로 정했다”고 했다. 공정위는 이들의 가격 담합이 공정거래법 제40조 제1항 제1호를 위반했다고 봤다. 이는 사업자들이 공동으로 상품이나 서비스의 가격을 담합하는 것을 금지하도록 규정하고 있다. 한편, 이날 공정위는 이들에게 전분당 입찰담합 혐의도 있다고 판단해, 이에 대한 조사를 마치고 위원회 심의에 넘겼다고 밝혔다. 공정위는 이들이 2016년 9월부터 2025년 6월까지 입찰 가격을 협의하고, 낙찰 물량을 배분하는 방식으로 담합한 혐의가 있다고 봤다. 공정위는 관련 매출액이 9400억원에 이를 것이라고 했다. 또 대상, 사조CPK, 삼양사는 전분당 부산물 가격을 담합한 혐의가 있다고 판단했다. 공정위는 2017년 8월부터 2025년 10월까지 매월 전분당 부산물 제품의 판매 가격을 담합한 혐의가 있다고 보고, 관련 매출액이 1조5500억원에 이를 것이라고 했다.', 'crawl', '조선일보', '2026-07-07 03:00:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HEYDMZLBHA2WCYRRMZRTIMLDHE.jpg', '2026-07-07 06:04:17', '2026-07-07 15:10:47.365705', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2411, 'https://www.chosun.com/arc/outboundfeeds/rss/category/economy/?outputType=xml', 'https://www.chosun.com/economy/realty/realestate_news/2026/07/07/MU2GEZRXHEZWGMTCGVSWCZDGGI/', 'https://www.chosun.com/economy/realty/realestate_news/2026/07/07/MU2GEZRXHEZWGMTCGVSWCZDGGI/', '경제', '"보유세는 올리고 거래세는 낮추나"…이달 말 부동산 세제 개편 발표', '[땅집고] 구윤철 부총리 겸 재정경제부 장관이 이달 말로 예정된 내년도 세제 개편안에서 부동산 보유세와 거래세를 함께 개편할 것임을 예고했다. 구 부총리는 7일 MBC 라디오 ''김종배의 시선집중'' 전화 인터뷰에서 "7월 말 정도 (발표를) 생각으로 준비 중"이라며 "부동산 보유세와 거래세 두 가지가 밸런스(균형)를 이뤄야 한다"고 말했다. 구 부총리', '[땅집고] 구윤철 부총리 겸 재정경제부 장관이 이달 말로 예정된 내년도 세제 개편안에서 부동산 보유세와 거래세를 함께 개편할 것임을 예고했다. 구 부총리는 7일 MBC 라디오 ''김종배의 시선집중'' 전화 인터뷰에서 "7월 말 정도 (발표를) 생각으로 준비 중"이라며 "부동산 보유세와 거래세 두 가지가 밸런스(균형)를 이뤄야 한다"고 말했다. 구 부총리는 이날 "기본적으로 집은 ''바잉(buying·매수)이 아닌 리빙(living·거주)''이라는 원칙하에 실거주자 중심으로 주택 시장이 확립될 수 있도록 보고 있다"며 "정부가 일방적으로 결정하는 것이 아니라 조만간 제가 국민 의견, 현장 목소리를 듣고 최종 정부 방침을 결정할 것"이라고 설명했다. 구 부총리는 공정시장가액비율 조정, 비거주 장기보유특별공제 혜택 축소 등 부동산세 개편 방향에 관한 여러 보도에 관한 질문에는 "그 부분도 국민의 한 의견인 만큼 살펴보겠다"며 즉답을 피했다. 앞서 이재명 대통령과 정부가 다주택자나 비거주 1주택자에 대한 보유세 강화를 사실상 공식화한 만큼, 구 부총리의 발언은 보유세를 높이는 대신 다주택자에 대한 거래세(양도소득세 등)을 낮춰 퇴로를 열어주는 것을 검토하겠다는 의도로 풀이된다. 부동산 전문가들은 보유세만 올리면 집값 안정 효과가 제한적이며, 거래세를 낮춰야 주택 거래가 늘어날 것이라고 전망한다. 주택 수와 규제지역 여부에 따라 중과되는 취득세와 양도세 체계를 폐지하거나 일부 완화해야 한다는 주장이다. ◇보유세 개편, 이 대통령 반전 카드 될까 이재명 정부는 출범 직후 집값을 잡기 위한 규제나 과세보다는 공급 중심으로 부동산 시장을 관리할 것임을 예고했다. 그러나 서울 전역과 경기도 인접지를 대거 토지거래허가구역으로 지정한 10·15 부동산 대책을 비롯해 1년만에 세 차례에 걸친 초강력 부동산 규제 대책을 내놨다. 그럼에도 집값이 잡힐 기미를 보이지 않자 보유세 강화를 예고하고 있다. 서울 아파트값은 정부의 규제 강화에도 지난 1년간 15% 이상 폭등했다. 부동산114 시세 조사에 따르면 이재명 정부 출범 이후 1년 동안 서울 아파트 가격은 누적으로 15% 이상 급등한 것으로 나타났다. 특히 서울 광진구와 동작, 중구, 강동, 성동 등 비강남 지역에서 20% 이상 급등했다. 경기도에서는 성남, 광명, 하남, 안양, 용인, 과천 등에서 10% 이상 아파트 가격이 튀었다. 부동산 시장 불안은 주거비 부담에 직접적 영향을 받는 20·30대와 주택 보유에 따른 세금 부담을 느끼는 40·50대 등 전방위에 걸쳐 이 대통령 지지도에 악영향을 미치고 있다는 평가다. 올 들어 국회가 종합부동산세·재산세 등 보유세율을 아직 높이지 않았음에도 공시 가격 상승의 영향으로 보유세는 증가하는 추세다. 과세 기준이 되는 전국 표준주택가격(공시가격)은 2025년 1.97%, 올해는 2.51% 상승했다. 공동주택가격(공시가격) 역시 2025년 3.65%, 올해 9.13% 오르며 상승 폭을 키웠다. 이런 가운데 정부가 주택 보유자들의 매도를 유도하기 위해 재산세율이나 종합부동산세 공정시장가액비율 등을 조절해 보유세를 증세할 경우 집값을 잡지도 못하고 납세자들의 부담만 높인다는 비판에 직면할 수 있다. 이재명 대통령은 역시 지난달 8일 열린 취임 1주년 기자회견에서 "여러 채를 가지고 있는 건 상관없다"면서 "그에 상응하는 부담은 하게 하자"며 실수요가 아닌 주택의 보유세를 강화할 가능성을 거론했다. /sh0293@chosun.com', 'crawl', '조선일보', '2026-07-07 02:19:46', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HAYGMYJQMM3TGNRTGIYDIMTFHE.jpg', '2026-07-07 06:04:17', '2026-07-07 15:10:58.778878', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2470, 'https://www.chosun.com/arc/outboundfeeds/rss/category/national/?outputType=xml', 'https://www.chosun.com/national/transport-environment/2026/07/07/JMYXX437CNDSZBPWSVK5KDOTJY/', 'https://www.chosun.com/national/transport-environment/2026/07/07/JMYXX437CNDSZBPWSVK5KDOTJY/', '사회', '수도권 때리는 장맛비...8~9일 서울 최대 100㎜', '', '정체전선(장마전선)의 영향으로 9일까지 전국에 많은 장맛비가 예고됐다. 8~9일 수도권을 비롯한 중부지방엔 이번 장마 들어 가장 많은 비가 내릴 전망이다. 7일 기상청에 따르면, 남쪽에 있던 정체전선이 이날 중부지방 부근까지 북상할 것으로 보인다. 7일 예상 강수량은 중부지방 20~60㎜, 전북 5~40㎜, 전남광주 5~10㎜, 영남 5~40㎜ 등이다. 8~9일에는 비가 더 거세질 전망이다. 8~9일 예상 강수량은 수도권·강원·충청 50~150㎜, 전북 30~120㎜, 전남광주 5~40㎜, 경북 20~120㎜, 대구 20~60㎜, 경남 5~40㎜, 제주 5㎜ 등으로 예보됐다. 8일은 중부, 9일은 남부에 각각 시간당 30㎜ 내외의 강한 비가 쏟아지겠다. ‘시간당 30㎜ 이상’은 ‘매우 많은 비’의 기준이 되는 강수량으로, 운전 시 와이퍼를 최대로 켜도 앞이 잘 보이지 않는 정도다. 9일 남부 일부 지역에선 이보다 거센 시간당 50㎜ 내외의 비가 쏟아지는 곳도 있겠다. 폭염도 이어질 전망이다. 7~8일 낮 최고기온은 34도까지 오르겠고, 9일에는 35도까지 기온이 더 오를 것으로 예상된다. 비로 인해 습도가 높아지면서 실제 기온보다 체감온도는 더 높을 수 있다.', 'crawl', '조선일보', '2026-07-07 01:27:58', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/INXHDFMLNBLJ5HSFFDQDXM4W2A.jpg', '2026-07-07 06:04:18', '2026-07-07 15:14:32.925748', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2481, 'https://www.chosun.com/arc/outboundfeeds/rss/category/national/?outputType=xml', 'https://www.chosun.com/national/regional/2026/07/07/5YJC3DAOT5HXDIOIHLF2EXHHEU/', 'https://www.chosun.com/national/regional/2026/07/07/5YJC3DAOT5HXDIOIHLF2EXHHEU/', '사회', '경찰, ‘피습 자작극 의혹’ 정이한 구속영장 청구', '', '경찰이 지난 6·3 지방선거 선거운동 기간 발생한 ‘음료 컵 피습’ 사건의 자작극 의혹과 관련해 정이한(38) 전 개혁신당 부산시장 후보에 대해 구속영장을 청구했다고 7일 밝혔다. 부산 금정경찰서는 이날 위계에 의한 공무집행방해와 공직선거법 위반 등 혐의로 정 전 후보와 음료를 던진 30대 남성 A씨에 대한 구속영장을 신청해 검찰이 청구했다고 밝혔다. 경찰은 지난 1일 정 전 후보에 대한 구속영장을 신청했으며, 검찰은 지난 3일 이를 법원에 청구했다. 이번 구속영장 신청은 사건 발생 67일, 선거가 끝난 지 한 달여 만에 이뤄진 것이다. 경찰 관계자는 “증거 인멸과 도주 우려 등의 이유로 구속영장을 신청했다”면서 “다만 피습 자작극 의혹 사건에 한해 신청한 것”이라고 했다. 정 전 후보에 대한 구속 전 피의자 심문(영장실질심사)은 오는 8일 오후 2시 부산지법에서 열린다. 정 전 후보는 지난 6·3 지방선거 선거운동 과정에서 자신이 음료 컵에 맞아 피습당한 것처럼 꾸민 이른바 ‘음료 컵 피습 자작극’ 의혹과 관련해 수사를 받아왔다. 경찰은 정 전 후보의 범행 경위와 사건 전반에 대한 수사를 벌인 끝에 위계에 의한 공무집행방해와 공직선거법 위반 등의 혐의가 인정된다고 판단해 구속영장을 신청했다. 경찰은 정 전 후보 부친이 운영하는 온그룹 계열사 직원들이 선거운동에 동원됐다는 의혹과 정 전 후보 관련 여론조사기관의 공정성 의혹 등도 수사하고 있다. 정 전 후보는 6·3 지방선거 부산시장 선거에서 2만7418표를 얻어 득표율 1.56%로 3위를 했다. 개혁신당은 앞서 정 전 후보가 탈당한 상태라며 수사에 적극 협조하겠다는 입장을 밝혔다. 경찰 관계자는 “이번 구속영장 청구는 테러 자작극 의혹에 한정된 것”이라면서 “나머지 혐의에 대해서는 수사하고 있다”고 말했다.', 'crawl', '조선일보', '2026-07-07 02:09:42', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MY2TGZJYGA3DIYJXMJRDQOJTGA.jpg', '2026-07-07 06:04:18', '2026-07-07 15:14:55.503492', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2509, 'https://www.chosun.com/arc/outboundfeeds/rss/category/national/?outputType=xml', 'https://www.chosun.com/national/national_general/2026/07/07/63ACDD36JBBE5NQ5L74LO3BCEI/', 'https://www.chosun.com/national/national_general/2026/07/07/63ACDD36JBBE5NQ5L74LO3BCEI/', '사회', '광주 찾은 배재고 학생들 “깊이 반성하고 사과”', '', '서울 배재고 야구부 학생들이 6일 전남광주 광주제일고(광주일고)를 찾아 고개를 숙였다. 국립5·18민주묘지도 찾아 참배했다. 지난달 29일 광주일고와 야구 경기 도중 일부 선수가 “스타벅스 가야지”라고 외쳐 논란을 빚은 지 일주일 만이다. 배재고 야구부 선수단과 교직원, 학부모 등 86명은 이날 오후 광주일고를 찾아 사과했다. 배재고 야구부 주장 A군은 직접 손으로 쓴 사과문을 읽었다. A군은 “저희가 광주에 발을 딛는 것만으로도 불편하셨을 텐데 귀한 시간 마련해주신 광주일고에 감사드린다”면서 “부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주일고 선수들과 학부모님, 광주 시민분들께 진심으로 사과드린다”고 했다. 이어 “모든 선수가 진심으로 깊이 반성하고 있으며 야구를 떠나서 인성이나 태도가 인생에서 얼마나 중요한지 깨닫고 다시 한번 배우게 됐다”며 “같은 선수로서 정말 하면 안 되는 행동이었고 일어나면 안 되는 상황이었다”고 했다. 감독 B씨도 “학생들을 잘 이끌고 가르쳐야 할 지도자로서 책임이 가장 크기에 진심으로 사죄드린다”고 했다. ◇배재고 “야구 떠나서 인성 중요성 깨달아” 광주일고 “운동장서 멋진 승부를 펼치자” 배재고 야구부 감독 B씨는 “깨끗하고 정정당당해야 할 경기에서 상대에 대한 존중과 동업자 정신, 선수로서 가져야 할 태도에 대해 제대로 가르치고 인도하지 못했다”며 “이기는 것보다 더 중요한 것이 있음을 저도 모르게 잊고 있었고, 저의 언행과 지도 방식이 올바른 본보기가 되지 못한 듯해 더욱 깊이 자책하며 부끄러울 뿐”이라고도 했다. 이효준 배재고 교장은 “이번 사태를 단순한 일탈이나 실수가 아닌 윤리 의식과 역사 인식에 대한 총체적인 붕괴에서 비롯된 사례로 보고 심각하게 사안을 받아들이고 있다. 참담하고 부끄러운 마음”이라고 했다. 이어 “자체 진상조사와 징계 절차를 진행하고 있다”며 “여러 기관의 조사에도 성실히 응하겠다”고 했다. 이 교장은 사과하며 눈물을 흘리기도 했다. 강당 뒤편에 앉아 있던 배재고 학부모들도 손수건으로 눈물을 닦았다. 이에 광주일고 야구부 주장 C군은 “우리도 혹시 다른 팀에 상처를 주는 원인이 있진 않았는지 돌아보는 계기가 됐다”며 “다시는 이런 일이 발생하지 않도록 환경이 조성됐으면 좋겠다”고 했다. 광주일고 야구부 감독 D씨는 “누구나 실수는 한다. 반성하고 화해하는 것이 더 성숙한 길”이라며 “나중에 운동장에서 만나면 정정당당하게 멋진 승부를 펼치자”고 했다. 이규연 광주일고 교장은 “어머님들이 들어오실 때부터 눈물을 흘리고 계시고, 학생들도 울먹이는 모습을 보니 준비했던 말이 순간 다 사라져 버렸다”며 “아이들을 제대로 이끌지 못한 것은 온전히 우리 어른들의 책임”이라고 했다. 두 학교 선수 등은 면담을 마친 뒤 함께 광주일고 학생독립운동기념탑과 국립5·18민주묘지를 찾았다. 정근식 서울시교육감과 김대중 전남광주통합특별시교육감도 동행했다. 배재고 선수들은 추모탑 앞에서 묵념했다. 앞서 지난달 29일 서울 목동야구장에서 열린 청룡기 전국고교야구선수권대회에서 배재고 일부 선수들이 상대 팀인 광주일고 더그아웃을 향해 “가야지, 가야지, 스타벅스 가야지” “탱크 데이”라고 외쳤다. 스타벅스 코리아가 5·18민주화운동 기념일에 ‘5/18 탱크데이’ 이벤트를 한 사건과 맞물려 논란이 일었다. 대한야구소프트볼협회는 지난 1일 배재고 야구부에 전국대회 6개월 출전 정지와 청룡기 몰수패란 중징계를 내렸다. 같은 날 배재고 선수 등은 광주일고를 찾아가 사과하려 했지만 광주일고 측이 “나중에 사과를 받겠다”고 해 무산됐다. 배재고는 2일 “스타벅스 가야지” “탱크 데이”라고 소리친 선수 2명을 생활교육위원회 회부하고 징계를 내리기로 했다. 대한야구소프트볼협회의 징계를 두고선 “대학 진학과 프로 진출을 꿈꾸는 학생 선수에게 과도하다”는 의견도 나왔다. 지난 4일에는 온라인 커뮤니티에 ‘광주일고에 폭발물을 설치했다’는 글이 올라와 경찰이 수색에 나서기도 했다.', 'crawl', '조선일보', '2026-07-06 15:55:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/XQR7YGMD7NMITJ2724ZQFGF6GM.jpg', '2026-07-07 06:04:18', '2026-07-07 15:15:52.004209', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2529, 'https://www.chosun.com/arc/outboundfeeds/rss/category/national/?outputType=xml', 'https://www.chosun.com/national/2026/07/06/BMPM6QDEQBAQ7PT7RPR6S3RWS4/', 'https://www.chosun.com/national/2026/07/06/BMPM6QDEQBAQ7PT7RPR6S3RWS4/', '사회', '광주일고 앞에 선 배재고 선수들… “하면 안 되는 행동이었다” 반성', '', '광주일고와의 경기 도중 ‘스타벅스 가야지’ 등의 응원 구호를 외쳐 지역 비하 논란을 일으킨 서울 배재고 야구부 학생들이 광주를 찾아 직접 사과했다. 논란이 불거진 지 일주일 만이다. 광주일고 학생들은 “누구나 실수할 수 있다”며 사과를 받아들였다. 6일 서울시교육청에 따르면, 배재고 야구부원 36명 전원과 학부모 일부, 교직원 등 총 86명은 이날 오후 3시쯤 광주일고를 방문했다. 이들은 피해 학생들과 학부모, 광주 시민을 향해 고개를 숙였다. 배재고 야구부 주장 A군은 이날 사과문을 낭독하며 “저희가 광주에 발을 딛는 것만으로도 불편하셨을 텐데, 귀한 시간 마련해주신 광주일고에 감사드린다”고 말했다. 이어 “부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주일고 선수들과 학부모님, 광주 시민분들께 진심으로 사과드린다”고 밝혔다. A군은 “모든 선수가 진심으로 깊이 반성하고 있으며, 야구를 떠나서 인성이나 태도가 인생에서 얼마나 중요한지 깨닫고 다시 한번 배우게 됐다”면서 “같은 선수로서 정말 하면 안 되는 행동이었고 일어나면 안 되는 상황이었다”고 했다. 그러면서 “저희 선수들의 좋지 못한 발언, 행동으로 인해 많은 분이 마음의 상처와 고통을 받고 계신다. 항상 마음속 깊이 반성하는 마음과 자세로 살아가겠다”고 덧붙였다. 배재고 야구부 감독 B씨도 지도자로서 책임을 인정했다. B씨는 “선수들의 지역 비하 응원은 무엇으로도 변명할 수 없는 잘못임을 인정하며, 학생들을 잘 이끌고 가르쳐야 할 지도자로서 책임이 가장 크기에 진심으로 사죄드린다”고 말했다. 그는 “깨끗하고 정정당당해야 할 경기에서 상대에 대한 존중과 동업자 정신, 선수로서 가져야 할 태도에 대해 제대로 가르치고 인도하지 못했다”며 “이기는 것보다 더 중요한 것이 있음을 저도 모르게 잊고 있었고, 저의 언행과 지도 방식이 올바른 본보기가 되지 못한 듯해 더욱 깊이 자책하며 부끄러울 뿐”이라고 했다. 배재고 교직원들도 사안을 무겁게 받아들이고 있다고 밝혔다. 교장 등 교직원들은 “이번 사태를 단순한 일탈이나 실수가 아닌 윤리 의식과 역사 인식에 대한 총체적인 붕괴에서 비롯된 사례로 보고 심각하게 사안을 받아들이고 있다. 참담하고 부끄러운 마음”이라고 했다. 이어 “사태에 대한 자체 진상조사 및 징계 절차를 진행 중이다. 여러 기관의 조사에도 성실히 응하겠다”고 밝혔다. 배재고의 사과문 낭독 이후 광주제일고측 선수 대표는 “이번 일을 통해 광주일고 야구도 상처주는 언행을 하지 않았는지 돌아보는 계기가 됐다. 다시는 이런 일이 발생하지 않길 바란다”고 답했다. 광주제일고 야구부 감독도 “사람은 누구나 실수를 한다. 실수는 반성하고 서로 화해하는 것이 더 성숙된 사람으로 성장하는 것 같다”며 “다시 배재고와 그라운드에서 경기를 하게 된다면 정정당당하게 멋진 승부 펼치는 날을 기대해본다”고 했다. 이규연 광주제일고 교장도 “들어오실 때 어머니들께서 눈물 흘리고 계셔서 제가 마음이 아팠다. 그래서 원래 하려던 말을 잊어버렸다”며 “배재고 학생들 고개 드시라. 어깨 펴고, 여러분들 미래 아직 끝나지 않았다”며 “사과도 중요하고 실천도 중요한데 더 중요한 건 앞으로 더 잘 사는 것”이라고 당부했다. 배재고 학생들은 사과 이후 광주제일고 인근의 광주학생독립운동기념탑을 함께 참배했다. 이어 국립 5·18민주묘지를 함께 참배한다. 한편, 이번 논란은 배재고 야구부 일부 학생 선수들이 지난달 29일 서울 목동구장에서 열린 경기 도중 광주일고 더그아웃을 향해 “가야지, 가야지, 스타벅스 가야지”, “탱크 데이”라고 외친 것이 발단이 됐다. 해당 구호는 지난 5월 스타벅스 코리아가 5·18민주화운동 기념일에 맞춰 텀블러 할인 이벤트를 진행하면서 ‘5·18탱크데이’, ‘책상에 탁’이라는 문구를 사용해 논란이 됐던 일과 맞물리며 거센 비판을 받았다. 배재고는 구호를 선창한 학생과 ‘탱크 데이’라고 외친 학생 등 2명을 생활교육위원회에 회부하고 징계하기로 했다. 서울시교육청도 정확한 경위를 파악하고 있다. 조사 결과에 따라 교장과 교감 등 학교 관리자에게도 책임을 물을지 검토할 방침이다. 학교와 교육청의 조치와 별개로 대한야구소프트볼협회 스포츠공정위원회는 배재고에 6개월 출전 정지 징계를 내렸다. 또 제81회 청룡기 전국고교야구선수권대회 남은 경기의 몰수패도 의결했다.', 'crawl', '조선일보', '2026-07-06 06:35:29', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/3U2CWO3WYBBOTPWM6BCEREIZHY.jpg', '2026-07-07 06:04:18', '2026-07-07 15:16:32.340117', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2533, 'https://www.chosun.com/arc/outboundfeeds/rss/category/national/?outputType=xml', 'https://www.chosun.com/national/national_general/2026/07/06/QKNAMX7AYRB57DT5J7JE2GHG3U/', 'https://www.chosun.com/national/national_general/2026/07/06/QKNAMX7AYRB57DT5J7JE2GHG3U/', '사회', '민형배 전남광주시장 “광주 군공항은 반도체 공장 최적지”', '', '민형배 전남광주특별시장이 청와대의 서남권 반도체 산단 조성 부지 발표에 대해 “광주 군 공항은 반도체 공장 최적지”라는 환영의 뜻을 밝혔다. 민형배 시장은 6일 광주청사에서 기자회견을 열고 “공항만 이전하면 광주 군 공항 부지는 반도체 공장 부지로 최적지”라며 “오늘 정부 발표는 호남 반도체 클러스터와 관련 조성 여건까지 대통령이 직접 챙기는 ‘실행 단계’로 들어섰다는 분명한 신호”라 말했다. 광주 군 공항은 현재 248만평(819만8000㎡) 규모로 1964년 현재 위치인 광주 광산구 부지에 세워졌을 당시 광주시 외곽에 자리 잡았지만 도심이 성장하면서 민가가 인접한 위치가 됐다. 현재 김포와 제주를 오가는 국내선이 있는 민간 공항과 같은 부지를 쓴다. 여객기와 전투기가 함께 뜨고 내리는 공항이다. KTX 호남선이 오가는 광주 송정역이 약 4㎞ 거리에 있어 정주 여건이 뛰어나다는 평가를 받는다. 전투기 소음 문제 때문에 주민들이 불편을 호소해 2013년 ‘군 공항 이전 및 지원에 관한 특별법’이 제정된 이후부터 본격적인 이전 사업이 시작됐다. 민 시장은 “정부의 군 공항 이전, 산단 조성에 발맞춰 우리 통합특별시는 전력·용수 공급, 교통·물류망, 인재 양성, 정주 여건까지 빠르게 준비하겠다”고 말했다. 다만 광주 군 공항에 반도체 공장을 건설하려면 대체 군 공항을 마련해야 하는 숙제가 있다. 민 시장은 “군 공항이 있는 상태에서 반도체 공장을 짓는 것은 불가능하다”며 “공장 건설과 군 공항 이전을 동시에 할 수 있는 방안을 정부가 내놓을 것으로 보인다”고 말했다. 이어 “군 공항 건설 기간은 최대한 단축하면 5년, 비용은 8~9조원으로 예상된다”고 말했다.', 'crawl', '조선일보', '2026-07-06 09:31:15', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/ME2DSNRQG42GKODGMU2TSYRTGA.jpg', '2026-07-07 06:04:18', '2026-07-07 15:16:40.027778', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2534, 'https://www.chosun.com/arc/outboundfeeds/rss/category/national/?outputType=xml', 'https://www.chosun.com/national/court_law/2026/07/06/3R7UDISUNBHUVIEC655GP7H42E/', 'https://www.chosun.com/national/court_law/2026/07/06/3R7UDISUNBHUVIEC655GP7H42E/', '사회', '중동 전쟁에 “트럼프 만세”...檢, ‘14조 유가 담합’ 정유 4사·임직원 기소', '', '“오늘 가격 100원 더 올린다. 우리 올해 2조 벌 듯” “역시 전쟁으로 먹고사는 회사. 트럼프 만세” 미국·이란 전쟁 발발 나흘 후인 지난 3월 4일 국내 4대 정유사 중 한 곳의 가격결정부서 직원들은 위와 같은 대화를 나누며 환호했다. 같은 날 서울 휘발유 평균 가격은 리터당 1800원을 넘어섰다. 이같은 유가 폭등은 국제 정세 때문만이 아니라 정유사들의 가격 담합과 주유소 상대 불공정 계약 구조가 맞물린 결과라는 검찰 수사 결과가 나왔다. 서울중앙지검 공정거래조사부(부장 나희석)는 6일 국내 4대 정유사(HD현대오일뱅크·SK에너지·GS칼텍스·에쓰오일) 법인과 HD현대오일뱅크 임직원 3명, GS칼텍스 임직원 1명 등 4명을 공정거래법 위반 등 혐의로 기소했다고 밝혔다. HD현대오일뱅크 가격결정부서 부서장 A씨는 구속기소됐다. 검찰에 따르면, HD현대오일뱅크 임직원 등은 2024년 7월부터 올해 2월까지 SK에너지와 석유제품 가격 정보를 주고받은 혐의를 받는다. 이들은 올해 3월 미·이란 전쟁이 발생한 이후 SK에너지가 HD현대오일뱅크보다 리터당 30~40원 높은 수준으로 가격을 올리는 방식으로 가격 급등을 합의한 것으로 조사됐다. GS칼텍스와 에쓰오일은 두 회사의 가격 흐름을 따라가며 시장 전체 가격 상승을 키운 것으로 나타났다. 검찰은 전쟁 발발 당시 4대 정유사가 상당량의 원유를 이미 비축하고 있어 가격을 급격히 올릴 필연적 사유가 없었다고 봤다. 검찰이 2022년 러시아·우크라이나 전쟁 당시와 이번 미·이란 전쟁 발발 이후의 유가 추이를 분석한 결과, 2022년엔 전쟁 첫날 가격이 떨어진 뒤 일주일 간 주목할 만한 가격 변동이 없던 것과 달리 지난 3월엔 전쟁 발발 직후 첫 영업일부터 4개 회사의 유가가 비슷한 수준으로 상승했던 것으로 나타났다. 이번 사건의 직접 담합 규모는 14조2000억원으로 추산됐다. 검찰이 수사한 담합 사건 중 역대 최대 규모다. GS칼텍스와 에쓰오일의 가격 추종 효과까지 감안하면 경쟁 제한 효과는 약 26조원에 이른다고 한다. 유가 담합이 가능했던 원인으로는 주유소가 대형 정유사 측 결정에 완전히 종속되는 유통 구조가 꼽힌다. 4대 정유사는 2021년 1월부터 올해 6월까지 자영 주유소와 전량구매계약을 체결함으로써 공급 가격을 일방적으로 통보한 혐의도 받는다. 전량구매계약이란 주유소가 특정 정유사로부터만 석유 제품을 구입하도록 하는 계약 방식이다. 다른 정유사의 기름을 구매할 수 없도록 한 독점 계약이다보니, 정유사가 일방적으로 석유 제품의 공급 가격을 통지하면 주유소는 따를 수밖에 없다. 2009년 공정거래위원회가 시정명령을 통해 이미 한 차례 제재한 거래 방식이지만, 이들 정유사는 “전량구매계약을 맺지 않을 경우 불이익을 얻을 수 있다”는 취지로 대다수의 주유소에 전량구매계약 방식을 강제한 것으로 드러났다. 정유사들은 타사 제품을 공급받은 주유소에는 손해배상 청구, 비용 회수, 보너스카드 중단 등 불이익을 준 것으로 조사됐다. 검찰은 HD현대오일뱅크와 GS칼텍스 임원이 공정거래위원회 현장조사 전 관련 자료와 사내 메신저 대화를 삭제한 정황도 확인했다고 밝혔다. 또 SK에너지, GS칼텍스, 에쓰오일 등 정유사 3곳이 산업통상부에 실제보다 낮은 공급가를 허위 보고한 사실도 파악해 관련 자료를 공유하기로 했다.', 'crawl', '조선일보', '2026-07-06 01:01:40', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MZSDAYTGGZTDKNLGHEZWMZBSGA.jpg', '2026-07-07 06:04:18', '2026-07-07 15:16:55.865486', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2589, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/07/HFSTENJQMJSDAOJUHE4WCMJUHA/', 'https://www.chosun.com/international/international_general/2026/07/07/HFSTENJQMJSDAOJUHE4WCMJUHA/', '국제', '나토 사무총장 “7일 수백억 달러 방산 계약 발표”', '마르크 뤼터 북대서양조약기구(NATO·나토) 사무총장은 7일(현지 시각) 튀르키예 수도 앙카라에서 열리는 나토 정상회의에서 대규모 신규 방위산업 계약을 발표할 예정이라고 6일 밝혔다. 로이터 통신에 따르면 뤼터 사무총장은 앙카라에서 기자회견을 열고 “억지와 방어에 필요한 핵심 장비를 제공할 수백억 달러 규모의 새로운 계약을 발표하겠다”고 말했다. 나토 회', '마르크 뤼터 북대서양조약기구(NATO·나토) 사무총장은 7일(현지 시각) 튀르키예 수도 앙카라에서 열리는 나토 정상회의에서 대규모 신규 방위산업 계약을 발표할 예정이라고 6일 밝혔다. 로이터 통신에 따르면 뤼터 사무총장은 앙카라에서 기자회견을 열고 “억지와 방어에 필요한 핵심 장비를 제공할 수백억 달러 규모의 새로운 계약을 발표하겠다”고 말했다. 나토 회원국들은 지난해 6월 네덜란드 헤이그에서 열린 나토 정상회의에서 도널드 트럼프 미국 대통령의 요구대로 2035년까지 국내총생산(GDP) 대비 5%를 국방 분야에 지출하겠다고 합의한 바 있다. 뤼터 사무총장은 “유럽의 나토 동맹국들과 캐나다가 이미 GDP의 약 4%를 국방·안보 분야에 투자하고 있다”며 “미국과의 국방비 지출 격차를 줄이는 방향으로 나아가고 있다”고 강조했다. 이어 “정상회의에서 5% 목표 달성을 위한 명확하고 구체적이며 신뢰할 수 있는 계획을 제시할 것으로 기대한다”고 말했다. 지난 5일 매슈 휘터커 나토 주재 미국 대사는 미국 측 주요 의제와 관련해 “이번 나토 정상회의에서 헤이그 국방 공약에 대한 진척 상황을 점검할 것”이라고 말한 바 있다.', 'crawl', '조선일보', '2026-07-06 17:01:18', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/SYBGLFWBOLG2HB5BH6TCGBAJEQ.jpg', '2026-07-07 06:04:19', '2026-07-07 15:18:44.331065', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2590, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/07/GMYTKOJUMZRTQNTFG44TEMBYGI/', 'https://www.chosun.com/international/international_general/2026/07/07/GMYTKOJUMZRTQNTFG44TEMBYGI/', '국제', '베네수엘라 지진 후 11일 버텼다…어린이 등 4명 구조', '베네수엘라 일간지 엘나시오날은 연쇄 지진 발생 11일 만에 생존자 4명이 극적으로 구조됐다고 6일(현지 시각) 보도했다. 보도에 따르면, 구조 당국은 지난 5일 밤 9시쯤 라과이라주 카라바예다 지역의 건물 잔해에서 생존자 4명을 구조했다. 지난달 24일 발생한 지진은 수도 카라카스를 비롯한 북부 6개 주를 강타했으며 해안가에 있는 라과이라주가 가장 큰 타', '베네수엘라 일간지 엘나시오날은 연쇄 지진 발생 11일 만에 생존자 4명이 극적으로 구조됐다고 6일(현지 시각) 보도했다. 보도에 따르면, 구조 당국은 지난 5일 밤 9시쯤 라과이라주 카라바예다 지역의 건물 잔해에서 생존자 4명을 구조했다. 지난달 24일 발생한 지진은 수도 카라카스를 비롯한 북부 6개 주를 강타했으며 해안가에 있는 라과이라주가 가장 큰 타격을 입었다. 생존자들은 지진 발생 후 무려 267시간 만에 구조됐다. 일반적으로 재난 의학에서 생존 마지노선으로 보는 골든타임(72시간)의 거의 4배에 달하는 시간이다. 젊은 남성 1명과 젊은 여성 1명, 어린이 2명으로 확인된 생존자들은 현장에서 응급처치를 받은 후 바로 구급차에 실려 병원으로 이송됐다. 이런 극적인 구조 소식에도 불구하고 사상자는 계속 늘고 있다. 베네수엘라 정부 발표에 따르면, 이번 연쇄 지진으로 최소 3342명이 사망하고, 1만6700명이 부상했다.', 'crawl', '조선일보', '2026-07-06 16:39:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/G42DKYJXGZTGCZBSMQ2TINZYMQ.jpg', '2026-07-07 06:04:20', '2026-07-07 15:18:46.058078', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2604, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/06/MY2DAOBXMFQTONBVGRRDGYJWMI/', 'https://www.chosun.com/international/international_general/2026/07/06/MY2DAOBXMFQTONBVGRRDGYJWMI/', '국제', '‘돈 더 냈지만, 참전은 안했다’… 美 트럼프, 나토 정상에 이란戰 불참 추궁', '도널드 트럼프 미국 대통령이 오는 7일 튀르키예 앙카라에서 개막하는 북대서양조약기구(NATO·나토) 정상회의를 앞두고 일부 유럽 동맹국이 최근 이란전쟁에 직접 참전하지 않은 일을 꺼내며 동맹에 ‘충성’을 추궁하고 나섰다. 지난해 나토 회원국들 트럼프 요구를 받아들여 2035년까지 국내총생산(GDP)의 5%를 국방·안보 분야에 투자하기로 합의했다. 그러나 트', '도널드 트럼프 미국 대통령이 오는 7일 튀르키예 앙카라에서 개막하는 북대서양조약기구(NATO·나토) 정상회의를 앞두고 일부 유럽 동맹국이 최근 이란전쟁에 직접 참전하지 않은 일을 꺼내며 동맹에 ‘충성’을 추궁하고 나섰다. 지난해 나토 회원국들 트럼프 요구를 받아들여 2035년까지 국내총생산(GDP)의 5%를 국방·안보 분야에 투자하기로 합의했다. 그러나 트럼프는 최근 마르크 뤼터 나토 사무총장을 만난 자리에서 “돈은 필요 없다. 그저 충성(loyalty)을 원한다”며 미국이 전쟁할 때 충분히 돕지 않은 국가를 진정한 동맹으로 볼 수 있느냐고 되물었다. 유럽이 방위비 증액 요구를 받아들이자, 트럼프는 그 다음 단계로 미국이 독자적으로 시작한 전쟁에 얼마나 협조했는지를 동맹 자격을 가르는 새 기준으로 추가했다. 5일 독일 도이체벨레와 워싱턴포스트(WP)는 나토가 유럽·캐나다 국방비 증액과 미국산 무기 구매 확대를 트럼프 행정부 성과로 부각하면서 미국과 정면충돌을 피하고 있다고 전했다. 정상들이 참여하는 회담 일정과 공동선언도 핵심 의제만 남겨 두고 최대한 얼굴 마주칠 일을 줄였다. 로이터에 따르면 이번 정상회의 공동선언 초안에는 나토 조약 5조에 대한 ‘철통 같은(ironclad)’ 공약과 러시아를 장기 위협으로 규정하는 문구, 우크라이나에 올해 700억유로를 지원하고 내년에도 최소 같은 수준을 유지한다는 계획이 담겼다. 이란과 관련해서는 핵무기 보유 불용과 호르무즈해협 항행 자유를 요구하는 원칙 문구만 넣어 미국 전쟁을 나토가 공식 추인하는 형식을 피했다. 트럼프는 회의 기간 레제프 타이이프 에르도안 튀르키예 대통령, 볼로디미르 젤렌스키 우크라이나 대통령, 아흐메드 알샤라 시리아 대통령과 잇달아 회담한다. 이재명 대통령도 정상회의에 참석해 방위산업포럼에서 연설한다. 나토 회원국들이 2014년 세운 국방비 목표는 GDP의 2%였다. 트럼프는 집권 1기부터 유럽이 미국 군사력에 기대면서 국방비를 아낀다고 비판해왔다. 회원국들은 결국 지난해 헤이그 정상회의에서 2035년까지 핵심 국방비 3.5%에 군사 인프라·사이버안보 등 1.5%를 더해 GDP의 5%를 투자하기로 약속했다. 나토는 유럽·캐나다의 핵심 국방 투자가 2025년 한 해에만 1390억달러(약 212조원) 늘었다고 집계했다. AP에 따르면 뤼터 사무총장은 지난달 24일 백악관 집무실에서 트럼프를 만나 2017년 이후 유럽·캐나다가 추가로 지출한 국방비 1조2000억달러(약 1832조원)를 금색 글씨로 ‘트럼프 트릴리언(The Trump Trillion)’이라고 적은 도표로 제시했다. 유럽이 미국산 무기 약 3000억달러(약 458조원)어치를 주문해 미국 안에 수만개 일자리를 만들고 있다는 설명도 곁들였다. 그러나 트럼프는 그 자리에서 “스페인은 공포 그 자체(horror show)다. 이탈리아에 실망했고 영국에도 실망했다”며 이란전에 직접 참전하지 않거나, 기지 대여에 소극적이었던 동맹국을 하나씩 거명했다. 이어 “그들은 우리를 실망시켰다”고 다그쳤다. 미국은 지난 2월 28일 이스라엘과 나토 동맹국과 사전 협의 없이 이란 공습을 시작했다. 스페인·이탈리아 등 일부 회원국은 이 전쟁에 직접 참전하거나 호르무즈 해협 봉쇄 작전에 참여하기를 거부했다. 이들은 이란 공격에 쓰이는 공동기지와 영공 사용에도 제한을 뒀다. 대다수 회원국은 그러면서도 기존 합의에 따라 미군의 기지 사용과 영공 통과, 병력·장비 이동을 지원했다. 뤼터는 트럼프에게 “6주간 이어진 이 전쟁에서 미군 항공기 4000~5000대가 유럽 기지에서 이륙했다”고 반박했다고 AP는 전했다. 다만 유럽은 군수·후방지원을 제공하면서도 미국이 시작한 전쟁에 교전국으로 뛰어드는 데는 선을 그었다. 나토 조약 5조는 유럽이나 북미의 회원국 한 곳이 무력공격을 받으면 이를 전체 회원국에 대한 공격으로 간주한다. 이후 ‘각국은 판단 하에 필요한 조치를 취하라’고 규정한다. 미국이 먼저 시작한 역외 군사작전에 다른 회원국이 자동으로 병력을 보내야 한다는 조항은 없다. 이란전쟁도 지난달 이후 전면 교전이 멈춘 휴전 상태라 미국이 지금 새 전쟁에 참전을 요구하는 국면은 아니다. 미 국방부는 지난달 유럽 회원국이 공격받을 때 제공하기로 약속했던 병력과 군함·항공기·무인기 규모를 줄이겠다고 발표했다. 피트 헤그세스 미 국방장관은 유럽 주둔 미군과 전력 배치를 6개월간 재검토하면서 공동기지 사용과 영공 통과, 위기 시 병력 이동 권한을 명확히 보장받겠다고 밝혔다. 이란전쟁 당시 일부 국가가 공격작전용 기지·영공 사용을 제한한 경험이 재검토 배경으로 꼽힌다. 다만 미 국방부는 어느 국가의 주둔 전력을 줄일지 아직 확정하지 않았다. 방위비는 GDP 대비 3.5%나 5%처럼 숫자로 잴 수 있지만 충성에는 합의된 기준이 없다. 기지와 영공을 내주면 충분한지, 미국의 군사행동을 공개 지지해야 하는지, 병력까지 보내야 하는지에 따라 평가가 갈린다. 미국 대통령이 회원국별 충성도를 자의적으로 판단해 집단방위 공약과 연결하면 러시아가 나토의 대응 의지를 시험할 가능성이 커진다는 지적이 나온다. 이 때문에 전문가들은 이번 회담에서 이란전처럼 미국이 주도한 전쟁에 유럽이 어디까지 협력해야 하는지, 앞으로 미국이 어떤 조건 하에서 유럽 방어에 나설지에 대한 답을 도출하기 어렵다고 내다봤다. 뤼터 사무총장 지난달 백악관 회동 뒤 기자들에게 트럼프가 나토 동맹에 “전적으로 전념하고 있다(completely committed)”며 유럽이 공격받으면 미국이 “반드시” 방어에 나설 것이라고 말했다. 반면 옌스 스톨텐베르그 전 나토 사무총장은 회고록에서 트럼프와 충돌했던 2018년 정상회의를 돌아보며 “미국 대통령이 더는 다른 동맹국을 방어할 뜻이 없다고 말하고 항의 표시로 나토 정상회의장을 떠난다면, 나토 조약과 그 안전보장은 별다른 가치가 없다”고 썼다.', 'crawl', '조선일보', '2026-07-06 06:47:46', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GRRWCM3FMJRGMYZXGQ3TCMJZGA.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:14.559008', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2611, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/06/VBKYWZRPKZGSHDMPPGI6SN733M/', 'https://www.chosun.com/international/international_general/2026/07/06/VBKYWZRPKZGSHDMPPGI6SN733M/', '국제', '“미국에 죽음을” “피의 복수”… 반미 집회 방불케 한 하메네이 장례식', '', '미국·이스라엘의 공습 첫날인 지난 2월 28일 사망한 이란 제2대 최고지도자 알리 하메네이의 국장(國葬)이 4일(현지 시각) 엿새 일정으로 시작됐다. 수도 테헤란에서만 조문객 2000만명이 운집한 것으로 추산되는 가운데, 행사장에 모인 테헤란 시민들이 “미국에 죽음을” “피의 복수” 같은 구호를 외치며 진행된 장례식은 거대한 반미 집회를 방불케 했다. 장례식은 테헤란 시내의 대형 예배 공간인 이맘 호메이니 대(大)모살라 광장에서 열렸다. 단상엔 이란 국기로 감싼 관이 5개 놓였다. 하메네이와 함께 숨진 딸, 사위, 며느리의 관은 같은 크기였지만 나머지 1개는 가방 크기로 작았다. 사망 당시 생후 14개월이었던 하메네이 외손녀의 관이었다. 가장 높은 자리에 놓인 하메네이의 관 위에는 예언자 무함마드의 직계 후손을 상징하는 검은 터번이 놓였다. 진행자가 “아야톨라 하메네이와 그의 가족이 무방비로 사탄에게 잔인하고 억울하게 암살당했다”고 하자 검은 상복을 입은 참가자들은 “암살자에게 피의 죽음을” “미국에 죽음을” “피의 복수, 복수” 같은 구호를 외쳤다. 하메네이의 사진을 든 여성들이 울부짖으며 가슴을 쳤다. 이들은 영어로 ‘트럼프를 죽여라(Kill Trump)’라고 적힌 팻말을 들고 반미 구호가 적힌 붉은 깃발, 이란 국기를 연신 흔들었다. 하메네이 일가의 관이 전시된 단상 아래로 그가 생전 테헤란 도심 관저 내 호세이니예(시아파 종교 시설)에서 연설하던 의자와 탁자가 주인을 잃은 채 전시돼 있었다. 최고지도자의 부재(不在)가 주는 비통함을 극대화하려는 연출로 해석됐다. 무대엔 남녀 어린이들이 올라와 하메네이를 추모하는 노래를 부르며 군무를 추기도 했다. 87세의 고령이었던 하메네이는 전쟁 직전까진 경제 파탄과 반(反)정부 시위 유혈 진압 등으로 인기가 없었다. 하지만 이란이 ‘사탄’이라고 부르는 미국·이스라엘의 공습에 숨지자 초대 최고지도자 호메이니도 얻지 못했던 ‘순교자’ 칭호로 불리고 있다. 특히 이란 당국이 장례 일정을 시작한 7월 4일은 이슬람 시아파에서 추앙하는 순교자 이맘 후세인(626~680) 추모 기간 직후이자 미국 250주년 독립기념일이다. 모하마드 에슬라미 테헤란대 연구원은 “하메네이가 이맘 후세인 순교의 연장선에 있다는 것”이라고 했다. 7세기 말 수니파 왕조에 맞서 온몸에 화살을 수십 발 맞고 일가족도 몰살당한 이맘 후세인의 비극적 서사를 하메네이 일가에 투영해 국민적 결집을 도모하겠다는 것이다. 하메네이의 아들이자 후계자인 최고지도자 모즈타바는 이날 모습을 드러내지 않았다. 지난 3월 아버지의 뒤를 이어 최고지도자가 된 모즈타바는 5개월째 모습을 드러내지 않고 있다. 테헤란 시민들도 그의 실제 모습을 보고 싶어 하지만, 혁명수비대가 이스라엘의 암살 위협 등을 이유로 모즈타바의 공개 활동을 거부했다고 뉴욕타임스(NYT)가 보도했다. 다만 모즈타바는 장례 마지막 날인 9일 하메네이의 고향 마슈하드에서 열릴 안장식에서 기도문을 낭독하고 싶어 하는 것으로 전해졌다. 장례식에는 중국·파키스탄·이라크·튀르키예·오만 등 30여 국이 조문단을 보냈다. 미국과의 종전 협상을 중재한 파키스탄의 셰바즈 샤리프 총리와 아심 무니르 육군참모총장, 러시아 드미트리 메드베데프 국가안보회의 부의장, 중국 허웨이 전국인민대표회의 상무위원회 부위원장이 조문했다. 하메네이 일가의 유해는 6일 이란 중부 종교 도시 곰으로 운구되고 7일엔 이라크의 시아파 성지 카르발라를 비롯해 바그다드, 나자프에서 장례식을 이어 간다.', 'crawl', '조선일보', '2026-07-05 15:44:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/DQXEO6PMSVINDKCA2YE73RAYTM.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:27.256644', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2612, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/06/4XWZ6J7QPRFRDIEH7BDLT63JIQ/', 'https://www.chosun.com/international/international_general/2026/07/06/4XWZ6J7QPRFRDIEH7BDLT63JIQ/', '국제', '“공산주의는 암, 도려내야”… 건국 250주년에 이념 전쟁 나선 트럼프', '', '“공산주의는 패배자이며 앞으로도 그럴 것입니다. 그것은 암과 같아서 시작되기 전에 아주 빨리 도려내야 합니다.” 4일(현지 시각) 미국 워싱턴 DC 도심 ‘내셔널 몰’에서 건국 250주년 기념 연설에 나선 도널드 트럼프 대통령이 공산주의를 향해 포문을 열었다. 연설 초반 “우리 모두는 하나님의 형상대로 창조됐다”는 말에 청중이 환호하자 트럼프는 “공산주의자는 절대 그런 말을 하지 않을 것”이라며 웃음을 유도하기도 했다. 트럼프는 전날 다른 행사에서도 공산주의를 비판했고, 뉴욕에서 열린 건국 250주년 기념 국제 관함식에 참석한 JD 밴스 부통령도 민주사회주의 비판 발언을 내놨다. 트럼프 행정부의 1·2인자가 건국 250주년을 기념하는 자리에서 연달아 ‘이념 프레임’을 내세운 것이다. 11월 중간선거를 앞두고 민주사회주의를 비롯한 좌파가 세력을 확장하자 국민적 관심이 쏠린 무대를 활용해 차단에 나섰다는 분석이 나온다. ◇‘이념 프레임’ 들고나온 트럼프 트럼프는 35분간 이어진 이날 연설에서 “공산주의가 다시 미국에서 고개를 들었다”고 주장했다. 그는 “공산주의자들이 무슨 말을 하든 그들에게는 가능성이 전혀 없다. 우리나라에 공산주의자들이 들어오지 않기를 바란다”고 했다. 전날 조지 워싱턴을 비롯한 역대 대통령 4명의 얼굴이 새겨진 사우스다코타주 러시모어산에서 한 연설에서는 “공산주의는 진주만 공격이나 9·11 테러보다 더 큰 위협”이라며 미국이 현재 공산주의의 위협을 받고 있다고 주장했다. 트럼프는 민주당을 “공산당”이라고 부르기도 했다. JD 밴스 부통령도 뉴욕에서 열린 관함식에 참석해 “국가의 위대함은 보지 못하고 오직 죄악에만 집중하는 국가관은 반대하라”고 했다. 민주사회주의자 조란 맘다니 뉴욕시장이 행사에 앞서 “애국심은 우리나라에 결함이 없다고 가장하는 것이 아니다”라며 미국의 열악한 노동 조건 등을 비판한 발언을 겨냥했다는 해석이 나왔다. 공화당 주요 인사들도 폭염 속에서 에어컨 온도를 25.6도로 맞추라고 권고한 맘다니의 조치를 가리켜 공산주의·사회주의적 처사라고 비판했다. 트럼프와 밴스가 ‘공산주의 경계령’을 내린 것은 미 정치권에서 민주사회주의가 세력을 키우는 상황과 무관하지 않다는 분석이 나온다. 지난해 무명의 맘다니가 뉴욕시장에 당선된 일을 신호탄으로, 올해 11월 중간선거를 앞두고 뉴욕·콜로라도주 민주당 예비경선 등에서 민주사회주의 진영 후보들이 잇따라 승리를 거두고 있다. 민주사회주의자들은 민주주의와 시장경제를 인정하면서도 복지 등을 국가가 전적으로 보장해야 한다는 주장을 편다. 민주사회주의가 공산주의와 정확히 같은 개념은 아니지만, 트럼프·밴스의 발언은 공산주의 프레임으로 이념 대결 구도를 만들어 민주사회주의를 견제하기 위한 것이라는 분석이 나온다. 정치 매체 더힐은 “트럼프와 공화당은 극좌 성향 후보들을 민주당의 중심이자 미국에 대한 위협으로 부각하고 있다”고 했다. ◇악천후 아랑곳하지 않고 연설 트럼프는 이날 연설에서 공산주의를 비판하는 한편으로 미국은 세계에 유례가 없는 특별한 국가라는 ‘미국 예외주의’와 애국주의를 전면에 내세웠다. 독립전쟁부터 남북전쟁, 2차 세계대전, 6·25전쟁, 냉전에 이르는 250년 역사를 되짚으며 트럼프는 “미국의 황금시대는 이제 막 시작됐을 뿐”이라고 했다. 무대에는 1777년 제작된 초기 성조기를 비롯해 노르망디 상륙작전과 이오지마 전투, 베를린 장벽의 미군 검문소, 라이트 형제의 비행기 등 미국사의 주요 장면을 상징하는 역사적 성조기가 차례로 등장했다. 트럼프는 연설 후반부에 자신의 국정 성과와 정치 현안도 언급했다. “베네수엘라를 보라. 이란을 보라. 우리는 그들의 군대를 궤멸시켰다”고 주장했고, 공화당이 추진 중인 선거법을 언급하며 유권자 등록 시 시민권 증명 의무화, 투표 시 신분 확인 강화 등의 필요성을 강조했다. 이날 행사는 섭씨 40도에 육박하는 기록적 폭염과 강한 뇌우가 잇따라 덮치며 한때 차질을 빚었다. 관람객 수천 명이 뇌우 예보로 대피했고, 비밀경호국은 행사장 입장을 위한 보안 검색을 일시 중단했다가 밤 9시 45분 재개했다. 트럼프는 대피 도중 트루스소셜에 “새벽 2시도 상관없다. 비 때문에 건국 250주년 행사를 멈추게 두지 않겠다”고 적었다. 오후 11시 15분 예정보다 약 1시간 30분 늦게 시작한 연설에서도 “새벽 4시에 단 한 사람 앞에서 연설해야 한다고 해도 나는 이 자리에 왔을 것”이라며 “번개가 우리를 멈추지는 못할 것”이라고 했다. 이후 자정쯤 약 85만 발의 불꽃을 40분간 쏘아 올리는 역대 최대 불꽃놀이가 펼쳐졌다. 밤하늘에 때때로 번개가 치는 가운데 내셔널 몰을 가득 메운 관람객들이 저마다 스마트폰으로 불꽃놀이를 촬영하며 건국 250주년을 기념했다. ☞민주사회주의 19세기 유럽에서 나타난 사회주의의 한 갈래. 폭력적 혁명을 꾀하기보다 정당 정치의 틀 안에서 민주적 절차로 사회주의 이념을 실현하려 한다. 생산 수단의 공유와 국가를 비롯한 지배 구조의 소멸을 지향하는 공산주의와도 구별된다.', 'crawl', '조선일보', '2026-07-05 15:44:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/UP3L3R6ZLZNWHPWHPOHUN2IWIA.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:30.839013', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2617, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/us/2026/07/05/DLNPSA2GSJDSBLDNS5UGOUXJUE/', 'https://www.chosun.com/international/us/2026/07/05/DLNPSA2GSJDSBLDNS5UGOUXJUE/', '국제', '트럼프, 독립 250주년 연설에서 ‘장진호 전투’ 참전용사 호명… “정말 치열했다”', '', '도널드 트럼프 미국 대통령은 4일 워싱턴 DC의 내셔널 몰에서 열린 독립 250주년 기념행사에서 무대에 올라 6·25 전쟁 참전용사인 해병대 팻 핀 상병과 루디 미킨스 일병을 호명했다. 트럼프는 “그 공산주의와의 전투는 정말 치열했다(rough one)”며 “감사하다”고 했다. 미 해병대는 ‘장진호 전투(Battle of Chosin Reservoir·1950년 11월 26일~12월 13일)’를 사상 최악의 전투로 기록하고 있다. 중공군 포위망을 뚫는 과정에서 2500명이 전사하고, 8000명이 동상(凍傷)을 입는 등 1만8000명에 가까운 사상자가 났다. 시사 주간지 뉴스위크는 “진주만 이후 미군 최악의 패전”이라고 했는데, 참전용사인 헨리 셰이퍼씨는 2020년 본지 인터뷰에서 “영하 30도에 육박하는 살을 에는 추위가 중공군보다 무서웠다”고 했다. 도처에 매복하고 있던 중공군의 공격으로 1㎞를 이동하는 데 3시간이 넘게 걸렸다. 장진호에서 미군이 버틴 덕분에 피란민 20만명을 구출시킨 ‘흥남 철수 작전’이 가능했다. 장진호 전투 생존자는 그 수가 워낙 적어 미국에선 ‘Chosin Few’라고 불린다. ‘Chosin’은 장진(長津)의 일본어 발음을 영어로 표기한 것이고, 살아남은 사람이 몇 안 된다고 하여 ‘Few’라는 단어가 붙었다. 트럼프는 “팻은 적과 백병전을 벌였지만 지금 그 이야기를 직접 들려줄 수 있을 만큼 (건강하게) 살아 남았다”고 했다. 또 “루디는 네 번이나 부상을 입었지만 사격을 멈추지 않았고 전진하는 것을 멈추지 않았다”며 “훌륭한 여러분께 감사하고, 함께 할 수 있어서 영광”이라고 했다. 민주당에서 조란 맘다니 뉴욕시장을 비롯한 이른바 ‘민주사회주의자’가 약진하고 있는 가운데, 트럼프는 “미국은 결코 공산주의 국가가 되지 않을 것”이라며 반(反)트럼프 진영을 향한 이념 공세의 고삐를 당겼다. 그는 “공산주의 체제는 미국 체제의 정반대이며, 그 체제는 제대로 작동한 적이 없다”며 “우리의 전사들은 전세계에서 공산주의와 싸웠다”고 했다. 이어 “공산주의는 암(癌)과 같다”며 “빨리 잘라내야 한다. 우리나라에 공산주의자들을 결코 원하지 않는다”고 했다. 트럼프는 독립 250주년 전야인 3일에도 사우스다코타주(州)의 러시모어산을 찾아 “미국의 정체성이 공격을 받고 있다”며 반공산주의 메시지를 발신했다. 트럼프는 “참전용사들이 지옥(hell) 같은 시간을 겪으면서도 살아한 나라를 위해 희생하고 모든 것을 바쳤다”며 “1776년부터 오늘날까지 성조기가 휘날린 모든 곳에서 그것은 힘과 정의, 희망의 상징이었다. 2세기 반이 지난 지금 미 공화국은 여전히 당당하고 굳건하게 서 있다”고 했다. 이어 “250년의 역사를 가진 미국은 지구상에서 가장 오래된 공화국일지 모르지만, 최고의 시대는 아직 오지 않았다”며 “이건 황금시대의 서막에 불과하다. 2세기 반 우리 선조들이 그랬던 것처럼 우리 나라를 아직 도달하지 못한 새로운 차원으로 끌어 나갈 것임을 선언한다”고 했다. 이날 워싱턴 DC에 기록적인 폭염, 뇌우 등이 겹쳤지만 트럼프는 “무슨 일이 있어도 갈 것”이라며 오후 11시쯤 약 30분 동안 야외 연설을 강행했다.', 'crawl', '조선일보', '2026-07-05 04:10:45', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/2OS2EJRNVFNTPC6KQAAH4FXJDQ.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:41.08235', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2618, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/06/G44TIMZSGU2WKOBXMQZTKNDFME/', 'https://www.chosun.com/international/international_general/2026/07/06/G44TIMZSGU2WKOBXMQZTKNDFME/', '국제', '하메네이 장례 이틀째인데… 후계자 모즈타바 불참', '이란 최고지도자 알리 하메네이의 장례식이 이틀째 이어지고 있지만, 후계자로 선출된 모즈타바 하메네이는 아직 공식 석상에 모습을 드러내지 않고 있다. 5일(현지 시각) AFP통신 등 외신에 따르면 이날 테헤란에서 열린 아야톨라 세예드 알리 하메네이 전 최고지도자의 장례 기도에는 모스타파, 마수드, 메이삼 등 하메네이의 다른 세 아들이 참석했지만, 최고지도자', '이란 최고지도자 알리 하메네이의 장례식이 이틀째 이어지고 있지만, 후계자로 선출된 모즈타바 하메네이는 아직 공식 석상에 모습을 드러내지 않고 있다. 5일(현지 시각) AFP통신 등 외신에 따르면 이날 테헤란에서 열린 아야톨라 세예드 알리 하메네이 전 최고지도자의 장례 기도에는 모스타파, 마수드, 메이삼 등 하메네이의 다른 세 아들이 참석했지만, 최고지도자직을 승계한 차남 모즈타바는 모습을 보이지 않았다. 모즈타바는 지난 2월 28일 미국과 이스라엘의 공습으로 얼굴을 다치고 다리에 중상을 입은 것으로 알려졌다. 이후 지금까지 공개 행사에는 한 차례도 참석하지 않았으며, 최고지도자로 선출된 뒤에도 서면 성명만 발표한 상태다. 이번 장례식은 35년 넘게 이란을 통치한 하메네이를 추모하는 자리인 동시에, 이스라엘과 미국을 상대로 5주간 전쟁을 치른 뒤 정권의 건재함과 결속을 대내외에 과시하려는 의미도 담고 있다. 그러나 새 최고지도자가 모습을 드러내지 않으면서 일부 추모객들 사이에서는 아쉬움을 나타내는 목소리도 나왔다. 한 참석자는 이란 타스님 통신에 “기도가 시작되기 직전까지도 모즈타바가 직접 나오기를 바랐다. 그것이 우리의 유일한 소원이었다”고 말했다. 장례식장에서는 미국과 이스라엘에 대한 보복을 촉구하는 발언도 이어졌다. 시인 모하마드 라술리는 송별 기도 직전 열린 시 낭송에서 “이제 세상은 트럼프에게 더 이상 좋은 곳이 아니다”라며 “우리 이맘(최고지도자)을 죽인 사람을 왜 우리가 죽이지 말아야 하는가. 그렇게 하지 않는다면 그것이야말로 수치일 것”이라고 말했다. 장례 일정은 오는 9일까지 이어진다. 6일에는 테헤란 시내에서 장례 행진이 진행되고, 7일에는 이란 중부 종교도시 곰에서 시아파 고위 성직자들이 참석하는 장례 예배가 열린다. 이어 8일에는 이라크 시아파 성지인 카르발라와 나자프로 시신을 운구해 장례식을 치른 뒤, 9일 하메네이의 고향이자 시아파 성지인 이란 북동부 마슈하드에서 안장될 예정이다.', 'crawl', '조선일보', '2026-07-06 01:35:11', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/G5QTSNZXMI3TMZTDMUYDCNTDME.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:42.995885', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2619, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/05/2HHC74C6WBENHGS6J3RF7SUJI4/', 'https://www.chosun.com/international/international_general/2026/07/05/2HHC74C6WBENHGS6J3RF7SUJI4/', '국제', '‘폭염 견디니 뇌우’ 美 건국 250주년 행사 대피 명령...트럼프 “새벽 2시라도 연설”', '', '미국 건국 250주년을 맞아 도널드 트럼프 대통령이 역대 최대 규모로 준비한 독립기념일 행사가 기록적인 폭염에 이어 뇌우까지 겹치며 큰 차질을 빚고 있다. 미 연방 당국은 4일(현지 시각) 저녁 강한 뇌우가 워싱턴DC로 접근하자 트럼프 대통령 연설과 불꽃놀이를 기다리던 내셔널몰 관람객 수천 명에게 긴급 대피 명령을 내렸다. 참가자들은 인근 스미스소니언 박물관과 연방정부 건물 등으로 이동하라는 안내를 받았지만, 이날 40도에 육박하는 폭염 속에서 5시간 가까이 줄을 서 보안 검색을 마치고 입장한 일부 시민들은 항의하며 대피를 거부하기도 했다. 비밀경호국은 보안 검색 운영을 전면 중단하고 추가 입장을 막았다. 당국은 이번 조치가 “공공 안전을 위한 것”이라며 “보안 검색 재개 시점은 알 수 없다”고 밝혔다. 그러나 지정된 일부 대피 건물은 이미 수용 인원을 채웠거나 문이 잠겨 있어 현장에서는 혼란도 빚어졌다. 행사장을 찾은 시민들은 이미 기록적인 폭염 속에서 수시간 동안 보안 검색을 기다린 뒤 입장한 상태였다. 하지만 악천후가 닥치면서 대피해야 하는 상황이 되자 불만도 터져 나왔다. 일부 참석자는 “무더위 속에서 몇 시간씩 기다릴 때는 안전 문제를 제기하지 않더니 이제 와서 대피시키고 있다”고 항의했다. 미 국립기상청(NWS)은 워싱턴DC 일대에 오후 10시까지 심각한 뇌우 주의보를 발령했다. 이는 당초 트럼프 대통령 연설이 예정됐던 시간대와 겹친다. 백악관은 기상 상황에 따라 연설 시간이 조정될 수 있지만 행사는 예정대로 진행할 계획이라고 밝혔다. 트럼프 대통령도 대피가 진행되는 와중에 자신의 소셜미디어 트루스소셜에 글을 올려 행사 강행 의지를 밝혔다. 그는 “폭풍은 어떤 행사에든 행운을 가져다주고 행사를 더 흥미롭게 만든다”며 “새벽 2시가 되든 한 시간 뒤가 되든 날씨가 지나갈 때까지 기다리겠다”고 적었다. 이어 “지금은 오후 11시쯤 연설을 한다고들 하는데 그게 무슨 대수냐”며 “비 때문에 미국 건국 250주년 행사를 멈추게 두지 않겠다”고 강조했다. 또 “2주 전 UFC 행사도 일주일 내내 폭우 예보가 있었지만 경기 시작 직전 비가 그쳤다”며 “우리의 위대한 참전용사들은 포화 속에서도 멈추지 않았다. 비도 우리를 막지 못할 것”이라고 말했다. 주최 측은 이후 기상 상황이 호전되면서 오후 9시 45분부터 내셔널몰 출입을 재개한다고 발표했다. 트럼프 대통령은 오후 11시 연설을 한 뒤, 약 85만 발의 불꽃을 40분 동안 쏘아 올리는 ‘역사상 최대 규모’의 불꽃놀이​가 이어질 예정이다.', 'crawl', '조선일보', '2026-07-05 01:17:27', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/SYMAVISBCVPCNH2OIUBB7WVMSI.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:44.987156', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2624, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/04/V2YNJ5N5KNB3NCUUZIVZSFU7JY/', 'https://www.chosun.com/international/international_general/2026/07/04/V2YNJ5N5KNB3NCUUZIVZSFU7JY/', '국제', '엿새간 역대급 ‘하메네이 장례’… 주민들 “살기 힘든데 세금 퍼붓나”', '', '지난 2월 28일 미국과 이스라엘의 공습으로 사망한 알리 하메네이 전 이란 최고지도자의 장례식이 4일 시작된다. 당국은 국경 검문을 강화하고 주요 도시 상공의 비행을 제한하는 등 최고 수준의 경비 태세를 이란 전역에 발동했다. 1989년 루홀라 호메이니 초대 최고지도자 장례식, 2020년 가셈 솔레이마니 혁명수비대 최고 사령관 장례식에 이어 역대 최대 규모로 치러지는 이번 행사에는 최대 3500만명이 참석할 것으로 예상된다. 미국과의 휴전이 위태롭게 이어지는 가운데 당국은 이번 장례식을 통해 국민적 결속을 다지고 ‘항전’ 의지를 고취할 것으로 예상된다. 그러나 본지가 서면으로 접촉한 시민들은 극심한 경제난 속에서 치러지는 대규모 행사에 곱지 않은 시선을 보내고 있다. ◇당국, 애도 분위기 조성에 총력 하메네이의 시신은 사망 약 4개월 만인 이달 2일 테헤란 이맘 호메이니 모살라(대사원)에 안치됐다. 4~5일 일반 참배객 조문을 시작으로 6일 테헤란 시내 장례 행렬, 7일 종교 도시 곰에서 열리는 추모 행사를 거쳐 9일 하메네이의 고향 마슈하드에 안장될 예정이다. 하메네이의 시신이 담긴 관은 함께 사망한 사위, 장녀, 며느리 등 가족들의 관과 함께 놓였다. 생후 14개월 손녀의 관도 포함됐다. 공습으로 일가족이 함께 사망한 사실을 상기시키며 국민의 슬픔과 분노를 자극하려는 연출이라는 분석이 나온다. 1989년 호메이니 장례 당시에는 시신을 보려는 인파가 몰려 투명 관이 부서지고 시신이 노출되는 사고가 있었다. 반면 하메네이의 관은 이란 국기로 단단히 싸여 시신이 드러나지 않는다. 폭격으로 사망한 시신의 상태를 가리고 대중의 돌발 행동을 통제하려는 의도로 풀이된다. 마슈하드에 사는 대학생은 “진심으로 애도하는 이들도 있겠지만 우리는 그들을 같은 국민으로 생각하지 않는다”며 “우리와 그들 사이에 완전히 다른 세상이 존재한다고 느낀다”고 했다. 하메네이의 아들이자 후임 최고지도자인 모즈타바 하메네이가 장례식을 집전할지에 관심이 쏠린다. 3월 선출된 모즈타바가 지금껏 한 차례도 공개 석상에 모습을 드러내지 않아 사망설·망명설 등이 제기된 가운데, 모즈타바가 이번에도 나타나지 않는다면 그의 건재에 의문이 제기되고 권위가 떨어질 수 있다는 전망이 나온다. 일반 조문에 앞서 국영 매체가 배포한 사진에는 전쟁 기간 공개적으로 모습을 드러내지 않았던 아흐마드 바히디 혁명수비대 총사령관이 하메네이의 관 옆에 앉은 모습이 담겼다. 정권의 초강경파를 대표하는 바히디는 미국·이스라엘과의 전쟁을 지휘하며 종전 협상도 막후에서 좌우하는 것으로 알려진 인물이다. 당국은 애도 분위기 조성에 총력을 기울이고 있다. 장례식을 앞두고 이란 정부는 평소 철저히 통제했던 외신을 초청해 선별적으로 취재 비자를 발급하는 등 국가 차원에서 대대적인 선전에 나섰다는 평가다. 모하마드 바게르 갈리바프 의회 의장은 2일 성명에서 “역사상 가장 중대한 장면 중 하나를 앞두고 있다”며 “이란 국민은 장례 행렬에 참여해 복수의 외침을 세계에 전해야 한다”고 했다. 하탐 알안비야 중앙사령부 알리 압돌라히 사령관도 같은 날 미국과 이스라엘을 향해 “어떠한 오판도 하지 말라”며 “이란에 대한 모든 위협과 침략에는 가혹한 보복이 따를 것”이라고 경고했다. ◇주민들 “세금 쓰는 행사 달갑지 않아” 이란 주민들의 목소리에서는 당국의 이러한 의도와는 다른 분위기가 감지된다. 이란은 올해 초 대대적인 반정부 시위 이후 인터넷을 전면 차단했으나, 지난달 미국·이스라엘과 휴전에 합의한 뒤 제한적인 접속이 가능해진 상태다. 이란 남부에 사는 20대 메이크업 아티스트는 “지금 시민들은 일상을 살아가고 있다. 결혼식이 열리고 축하 모임도 한다. 대부분은 하메네이의 사망을 슬퍼하지 않는다”고 했다. 그는 “먹고 마실 것을 주니까 (당국의) 행사에 참여하는 이도 많다. 막대한 세금을 장례식에 쏟아붓는 걸 달가워할 사람은 많지 않을 것”이라고 했다. 테헤란에 사는 20대 대학생은 “우리는 더 나은 삶과 희망을 원했지만 여전히 가난에 허덕이고 있다. 이 무더위에 에어컨 틀기도 두렵다”고 했다. 이어 “국민들은 아직도 지난 1월 대규모 유혈 시위 진압의 트라우마에서 벗어나지 못하고 있다”며 “최고지도자의 명령이 없었다면 일어나지 않았을 일”이라고 했다. 이들은 공무원과 학생, 심지어 수감자까지 행사에 동원하는 실태도 증언했다. 테헤란의 40대 자동차 판매원은 “정부 기관에서 일하는 여동생은 행사에 참석하지 않으면 직장을 그만둬야 한다는 경고를 받았다”고 했다. 신변 위협을 우려해 거주지를 공개하지 않은 50대 해직 교수는 “수감자들도 GPS 발찌를 착용한 채 장례식에 참가해야 하며, 거부하면 고문과 처형 위협을 받았다고 들었다”며 “공립학교 교장인 지인은 교사들의 참석을 독려하라는 지시를 받았다”고 했다. 이들은 휴전 이후에도 희망이 보이지 않는다고 입을 모았다. 테헤란의 한 대학생은 “매일 모든 것이 어제보다 비싸진다. 많은 사람이 지쳤고 우울감에 시달린다”고 했다.', 'crawl', '조선일보', '2026-07-03 15:46:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/6CBQCXUXERMD7KUKW3AVGV6EK4.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:54.068807', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2625, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/04/DLSC7O43UZGPLJ4MMJSEUKCJEY/', 'https://www.chosun.com/international/international_general/2026/07/04/DLSC7O43UZGPLJ4MMJSEUKCJEY/', '국제', '40도 넘는 폭염에도… 80세 트럼프 “아주 긴 연설 할 것”', '', '미국에서는 건국 250주년 기념 행사가 열리는 동부 지역을 중심으로 역대급 폭염이 예보되면서 흥행에 비상이 걸렸다. 도널드 트럼프 대통령이 더위에 아랑곳하지 않고 의욕적인 연설을 예고하며 분위기 띄우기에 나섰지만 호응이 기대에 미치지 못할 수 있다는 지적이 나오고 있다. 트럼프는 1일 “(독립기념일 당일인) 4일 기온이 107도(섭씨 41.7도)까지 오르겠지만 내가 무엇이든 할 수 있다는 사실을 보여주기 위해 아주 긴 연설을 할 것”이라고 말했다. 미 당국은 트럼프의 연설을 기념 행사의 ‘하이라이트’로 강조하고 있다. 이 밖에도 4일 오후 워싱턴 DC 링컨 기념관과 워싱턴 기념탑을 잇는 잔디 광장 ‘내셔널 몰’ 일대에서 군용기의 에어쇼와 퇴역 군인들의 퍼레이드, 음악 공연 등이 예정돼 있다. 밤에는 약 40분에 걸쳐 폭죽 85만발을 발사하는 불꽃놀이가 펼쳐진다. 기네스 기록에 도전하는 사상 최대 규모의 불꽃놀이다. 문제는 워싱턴 DC를 비롯한 미 동북부에 폭염이 이어지고 있다는 점이다. 미국 국립기상청에 따르면 폭염 경보가 발령된 워싱턴 DC의 1일 낮 기온이 1898년 기록한 역대 최고 기온 수준인 섭씨 38도 이상까지 치솟았다. 트럼프 연설이 예정된 4일엔 섭씨 40도 안팎까지 오를 것으로 예상된다. 지난달 80세 생일을 맞은 트럼프가 건재를 과시하기 위해 긴 연설을 예고했지만 쉽지 않을 수 있다는 지적이 나온다. 백악관 내부에서도 청중이 기대보다 적을 수 있다고 우려하는 것으로 알려졌다. 미국은 10여 년에 걸쳐 건국 250주년 행사를 준비해 왔지만 현재까지 흥행은 기대에 미치지 못하고 있다. 지난달 26일부터 워싱턴 DC에서 열리고 있는 ‘위대한 미국의 주 박람회’는 민주당 주지사가 이끄는 ‘블루 스테이트(blue state)’ 10여 곳이 불참하면서 찬물을 끼얹었다. 트럼프는 50주와 자치령의 특색 있는 문화 행사와 명산물을 한 자리에 모아 ‘국민 통합’의 메시지를 전하겠다는 계획이었지만, 플로리다 등 일부 주를 제외한 대부분의 전시관이 대기 없이 입장할 수 있을 만큼 한산한 것으로 전해졌다. 여기에 더위까지 겹치면서 박람회를 찾은 관람객은 연신 종이 부채를 흔들며 에어컨이 가동되는 부스로 몰리고 있다. 개장 초기에 전기 공급이 원활하지 않아 아이스크림 판매나 대관람차 탑승이 제한되고 텍사스주 부스가 정전으로 한때 문을 닫는 등 운영상의 미숙함도 이어졌다. 박람회장에서 판매하는 음식 가격도 터무니없이 높아 원성이 자자하다. 프레젤 하나에 25달러(약 3만8000원), 레모네이드 한 잔에 9달러 수준으로 전해졌다.', 'crawl', '조선일보', '2026-07-03 15:46:00', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/ZDNUL2VMMJPVFHQYU2WZXB6GCI.jpg', '2026-07-07 06:04:20', '2026-07-07 15:19:56.215616', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2628, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/04/2Z32E55HCNDGXIXTXJRNWI4AKU/', 'https://www.chosun.com/international/international_general/2026/07/04/2Z32E55HCNDGXIXTXJRNWI4AKU/', '국제', '이란 하메네이 장례식 시작... 조문객 최대 2000만명 몰릴 듯', '', '지난 2월 28일 미국과 이스라엘의 공습으로 사망한 알리 하메네이 전 이란 최고지도자의 장례식이 4일(현지 시각)부터 일주일간 열린다. 하메네이가 사망한 지 126일 만이다. 하메네이의 시신은 사망 약 4개월 만인 지난 2일 테헤란 이맘 호메이니 모살라(대사원)에 안치됐다. 4~5일 일반 참배객 조문을 시작으로 6일 테헤란 시내 장례 행렬, 7일 종교 도시 곰에서 열리는 추모 행사를 거쳐 9일 하메네이의 고향 마슈하드에 안장될 예정이다. 하메네이의 시신이 담긴 관은 함께 사망한 사위, 장녀, 며느리 등 가족들의 관과 함께 놓였다. 생후 14개월 손녀의 관도 포함됐다. 이란 국영방송은 단상에 놓인 하메네이와 그 일가의 관을 보고 울부짖는 시민들의 모습을 방영했다. 공습으로 일가족이 함께 사망한 사실을 상기시키며 국민의 슬픔과 분노를 자극하려는 연출이라는 분석이 나온다. 약 40개국의 대표단과 100여 개의 국제 문화·종교 단체가 장례식에 참석하기 위해 이날 이란에 도착했다고 이란 국영 ISNA 통신, AFP 통신 등이 보도했다. 블라디미르 푸틴 러시아 대통령의 최측근인 드미트리 메드베데프 러시아 국가안보회의 부의장은 러시아 조문단을 이끌고 테헤란에 도착해 하메네이의 관이 안치된 기도원 이맘 호메이니 그랜드 모살라를 찾아 조문했다. 셰바즈 샤리프 파키스탄 총리는 아심 무니르 파키스탄군 참모총장과 함께 조문했다. 파키스탄은 이란과 미국의 종전 협상 과정에서 중재 역할을 했다. 아프가니스탄에서는 탈레반 정권의 아미르 칸 무타키 외무장관이 조문단을 대표했다. 아프간 내 반(反)탈레반 전선을 이끄는 아마드 마수드도 장례식장을 찾아 조문했다. 마수드의 부친인 아마드 샤 마수드가 1990년대 이란의 후원을 받았다고 한다. 니콜 파시냔 아르메니아 총리, 네치르반 바르자니 이라크 쿠르드 자치정부 수반, 왈리드 알쿠라이지 사우디아라비아 외무차관 등이 조문했다. 중국에선 허웨이 전인대 상무위원회 부위원장을 대표로 파견했고, 팔레스타인 무장정파 하마스와 레바논 친이란 무장정파 헤즈볼라 조문단도 이날 테헤란에 도착했다. 이란 정부는 4∼5일 테헤란에서 열리는 조문 행사에 이란 인구의 20%가 넘는 최대 2000만명이 모일 것으로 예상했다. 1989년 6월에 치러진 초대 최고지도자 아야톨라 루홀라 호메이니의 장례식 당시 테헤란에 1020만명이 조문한 바 있다. 이란 당국은 국경 검문을 강화하고 주요 도시 상공의 비행을 제한하는 등 최고 수준의 경비 태세를 이란 전역에 발동했다. 또한 당국은 애도 분위기 조성에 총력을 기울이고 있다. 장례식을 앞두고 이란 정부는 평소 철저히 통제했던 외신을 초청해 선별적으로 취재 비자를 발급하는 등 국가 차원에서 대대적인 선전에 나섰다는 평가다.', 'crawl', '조선일보', '2026-07-04 00:52:27', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/QJKXOPOQDRMVXGO3E5AYOXJDFU.jpg', '2026-07-07 06:04:20', '2026-07-07 15:20:02.959369', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2630, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/04/YDJTNSRPCZA5DNRXTY6ZCMIUB4/', 'https://www.chosun.com/international/international_general/2026/07/04/YDJTNSRPCZA5DNRXTY6ZCMIUB4/', '국제', '‘대통령 큰바위 얼굴’ 앞에서... 트럼프, 反공산주의 외쳤다', '', '도널드 트럼프 미국 대통령이 250주년 미국 독립기념일을 하루 앞둔 3일(현지 시각) 조지 워싱턴, 토머스 제퍼슨, 에이브러햄 링컨, 시어도어 루스벨트 등 미국을 대표하는 대통령 4명의 얼굴이 새겨진 사우스다코타주 러시모어산을 찾았다. 그는 독립기념일 당일인 4일에는 워싱턴 DC에서 기념 연설을 할 예정이다. 트럼프 대통령은 이날 기념행사에 참석해 연설에서 미국이 지구상에서 “가장 오래된 공화국”이라며 “인류 역사상 존재했던 그 어떤 나라보다 가장 성공적이고 가장 뛰어난 성과를 거뒀으며, 가장 탁월한 국가”라고 말했다. 이어 트럼프 대통령은 민주당 내 일각의 강성 진보 진영인 민주사회주의를 ‘공산주의’로 규정했다. 그는 “우리는 지금 우리 미국의 정체성이 새롭게 공격받고 있음을 본다”며 “공산주의 위협에 맞서 냉전을 치르고 승리한 지 1세대가 지났는데도 우리 땅에서 이제 공산주의자의 위협이 부상하고 있다”고 했다. 트럼프 대통령은 “여기엔 우리 생활 방식과 위대한 성공에 완전히 반대하는 사상을 받아들이는 이민자도 포함된다”며 “우리는 그들이 승리하도록 내버려두지 않을 것이다. 그들은 우리에게 이길 수 없다”고 했다. 트럼프 대통령은 “미국은 결코 공산주의 국가가 되지 않을 것”이라며 “우리가 중간선거에서 지는 것은 오직 우리가 스스로 지도록 허용할, 우리가 어리석고 멍청하며 현명하지 않을 때뿐”이라고 했다. 오는 11월 중간선거를 앞두고 지지세 결집에 나섰다는 분석이다. 트럼프 대통령은 종전 양해각서(MOU) 체결 이후 후속 협상을 이어가는 중인 이란에 대해 “그들은 간절히 협상을 원한다”면서 “우리는 (알리 하메네이 전 이란 최고지도자) 장례식을 치르라고 일주일의 휴가를 줬다. 우리는 250년 동안 친절해왔기 때문”이라도 말했다. 트럼프 대통령은 이날 백악관이 있는 워싱턴DC에서 러시모어산으로 이동하는 도중에 자신의 소셜미디어 트루스소셜에서 주식시장 급등, 감세 정책, 무역적자 감소, 신규 투자 유치 등 정부 성과를 올린 뒤 “이것이 바로 승리다. 미국의 황금기가 시작되고 있다”고 적었다. 트럼프 대통령이 탄 전용기인 에어포스원은 러시모어산 상공을 기념 비행했다. 트럼프 대통령의 러시모어산 방문은 집권 1기 때인 2020년 독립기념일 전날에 찾았던 것에 이어 6년 만이다. 당시 재선을 노리던 트럼프 대통령은 코로나 확진자가 급증하는 상황에서도 지지층이 군집하는 기념행사를 강행했다는 등의 이유로 비판을 받기도 했다.', 'crawl', '조선일보', '2026-07-04 04:46:29', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/2QRVML7NZBBQJLC5GJNVIKCBWU.gif', '2026-07-07 06:04:20', '2026-07-07 15:20:06.894976', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2640, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/06/HA2GCOBSGE2GKMLDGI4GCYTEGQ/', 'https://www.chosun.com/international/international_general/2026/07/06/HA2GCOBSGE2GKMLDGI4GCYTEGQ/', '국제', '트럼프 “폭풍우에 독립기념일 행사 취소됐다가 내가 뒤집어”', '도널드 트럼프 미국 대통령은 미국 독립 250주년 기념행사가 폭풍우로 한때 취소됐다가 자신의 결정으로 재개될 수 있었다고 5일(현지 시각) 밝혔다. 트럼프 대통령은 이날 소셜미디어(SNS) 트루스소셜을 통해 독립기념일인 전날 오후 7시 5분 기준 워싱턴DC 내셔널몰 일대에 42만4000명의 인파가 모였지만, 악천후로 행사가 취소되면서 모두 대피했다고 설명', '도널드 트럼프 미국 대통령은 미국 독립 250주년 기념행사가 폭풍우로 한때 취소됐다가 자신의 결정으로 재개될 수 있었다고 5일(현지 시각) 밝혔다. 트럼프 대통령은 이날 소셜미디어(SNS) 트루스소셜을 통해 독립기념일인 전날 오후 7시 5분 기준 워싱턴DC 내셔널몰 일대에 42만4000명의 인파가 모였지만, 악천후로 행사가 취소되면서 모두 대피했다고 설명했다. 이어 “행사가 취소됐다는 소식을 듣자 나는 즉시 그 결정을 뒤집었고, 사람들이 다시 돌아올 시간을 주기 위해 잠시 기다렸다”며 “믿기 어려울 정도로 최소 15만명이 돌아왔고, 그 덕분에 행사는 원래 예정대로 진행됐을 때보다도 더 장관을 이뤘다”고 말했다. 트럼프 대통령은 관람객들의 대피와 신속한 재입장을 지원한 비밀경호국(SS)과 법 집행기관을 치하하며 “정말 놀라운 밤이었다. 불꽃놀이가 끝난 직후부터 폭우가 쏟아져 더욱 극적인 마무리를 장식했다”고 덧붙였다. 전날 워싱턴DC에서 열린 미국 건국 250주년 기념행사는 폭염과 뇌우 예보가 겹치면서 한때 중단됐다. 야외 행사장에 모여 있던 관람객들은 인근 건물 등으로 대피했다가 오후 9시가 넘어서 다시 행사장으로 돌아왔다. 행사 재개 결정으로 일정이 지연되면서 트럼프 대통령의 연설은 예정보다 약 1시간 30분 늦은 오후 11시 15분쯤 시작됐다. 이어 세계 최대 규모 기록 경신에 도전한 불꽃놀이는 연설 직후인 자정 무렵 막을 올렸다. 미국 일간지 워싱턴포스트(WP)는 “자정 직전에 시작된 40분간의 불꽃놀이는 극심한 폭염과 낙뢰, 대피령, 그리고 곳곳에서 벌어진 혼란으로 얼룩진 하루의 마지막을 장식했다”고 전했다.', 'crawl', '조선일보', '2026-07-05 21:20:23', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GVRDQYZSMVRDGM3EHFSTKNRUMI.jpg', '2026-07-07 06:04:20', '2026-07-07 15:20:25.98636', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2641, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/us/2026/07/05/SKAOVPXXNBFAXP6TDSIKRKOHQI/', 'https://www.chosun.com/international/us/2026/07/05/SKAOVPXXNBFAXP6TDSIKRKOHQI/', '국제', '폭염·뇌우·강풍에도 ‘건국 250주년’ 美 축제... 트럼프는 이틀째 “멸공”', '', '건국 250주년을 맞은 미국의 독립기념일 행사가 4일(현지 시각) 폭염·뇌우·강풍 등 악천후에도 불구하고 성대하게 열렸다. 도널드 트럼프 대통령은 건국 250주년을 두고 “역사상 가장 기쁘고 영광스러운 이정표 중 하나”라면서도, “공산주의 세력을 잘라내야 한다”며 목소리를 높였다. 트럼프는 역대 최대 규모로 이날 행사를 준비했지만, 관람객들은 워싱턴 DC를 비롯한 미 동부 지역을 덮친 폭염 탓에 그늘진 풀밭 등에 앉아 입장을 기다려야 했다. 38도를 넘는 폭염으로 인해 예정된 퍼레이드는 취소됐다. 이른 저녁 강한 폭풍우 예보와 함께 행사장엔 모래가 섞인 강풍까지 불었다. 결국 행사를 주최한 ‘프리덤 250’ 측은 트럼프의 연설과 불꽃쇼를 기다리던 관람객 수천 명에게 긴급 대피 명령을 내리고 행사 시작을 미뤘다. 사람들이 대피를 거부하자 군복을 입은 주방위군 병력들과 경찰이 나서 행사장 밖으로 사람들을 내보내기도 했다. 많은 사람들은 악천후에도 불구하고 독립기념일을 즐기는 모습이었다. 워싱턴 DC 링컨 기념관과 워싱턴 기념탑을 잇는 잔디 광장 ‘내셔널 몰’ 일대에는 성조기 무늬의 앞치마를 두르고, 모자를 쓴 시민들이 행사장 일대를 누볐다. 미 공군 특수비행팀 ‘선더버드’와 해군 특수비행팀 ‘블루엔젤스’는 워싱턴 상공을 비행하며 축하 비행을 선보였고, 트럼프의 새 전용기 ‘에어포스 원’과 현존 최강의 전투기로 꼽히는 F-22 랩터 4기가 편대를 이뤄 비행했다. 미국의 핵심 전략 자산인 스텔스 폭격기 B-2와 B-1B, B-52 등 폭격기도 사람들의 환호를 받으며 워싱턴 DC 상공을 날았다. 손주 3명과 함께 행사를 보러 온 티나 헤일은 군용기들의 비행 모습을 보며 “이것만으로도 미국인이라는 사실이 자랑스럽지 않냐”고 말했다. 밤이 되며 날씨가 개자 트럼프는 미뤘던 연설을 시작했다. 트럼프는 참전 용사와 우주비행사들, 전사한 군인들의 가족을 무대에서 맞이했고, 2차 세계대전과 베트남전에 파병됐던 참전 용사들을 추모했다. 그는 6·25전쟁 참전 용사인 해병대 팻 핀 상병과 루디 미킨스 일병을 호명하며 “훌륭한 여러분께 감사하고, 함께할 수 있어서 영광”이라고 했다. 다만 트럼프는 이례적으로 “미국은 결코 공산주의 국가가 되지 않을 것”이라며 반(反)트럼프 진영을 비판했다. 트럼프는 “공산주의 체제는 미국 체제의 정반대이며, 그 체제는 제대로 작동한 적이 없다”며 “우리의 전사들은 전 세계에서 공산주의와 싸웠다”고 했다. 이어 “공산주의는 암(癌)과 같다”며 “빨리 잘라내야 한다. 우리나라에 공산주의자들을 결코 원하지 않는다”고 했다. 트럼프의 연설이 끝나자 곧바로 성대한 불꽃놀이가 시작되며 행사의 대미를 장식했다. 주최 측은 이날 86만여 발의 폭죽을 준비했다. 트럼프는 내셔널 몰에 마련된 특별 관람석에서 불꽃놀이를 지켜봤다. 그는 행사가 끝난 뒤 자신의 소셜 미디어 ‘트루스소셜’에 “역대 최고의 불꽃놀이였다”고 했다.', 'crawl', '조선일보', '2026-07-05 05:36:48', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/BKHFPH7CK5AYLPBA5VDCCMJ27I.gif', '2026-07-07 06:04:20', '2026-07-07 15:20:27.802638', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2644, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/05/GVRDEZJUMM3GIMTCGAYWCMZZMU/', 'https://www.chosun.com/international/international_general/2026/07/05/GVRDEZJUMM3GIMTCGAYWCMZZMU/', '국제', '美 건국 250주년 수놓은 85만발 불꽃놀이… 기네스 기록 도전', '악천후와 간헐적인 낙뢰에도 미국 워싱턴DC에서 열린 건국 250주년 기념행사의 대규모 불꽃놀이가 예정대로 진행됐다. 5일(현지시각) CNN에 따르면 전날 밤늦게 열린 ‘미국에 바치는 헌사(Salute to America)’ 행사에서는 약 40분간 불꽃놀이가 이어졌다. 이번 행사는 예년 미국 독립기념일 불꽃놀이보다 규모를 대폭 키운 것이 특징이다. 행사 주', '악천후와 간헐적인 낙뢰에도 미국 워싱턴DC에서 열린 건국 250주년 기념행사의 대규모 불꽃놀이가 예정대로 진행됐다. 5일(현지시각) CNN에 따르면 전날 밤늦게 열린 ‘미국에 바치는 헌사(Salute to America)’ 행사에서는 약 40분간 불꽃놀이가 이어졌다. 이번 행사는 예년 미국 독립기념일 불꽃놀이보다 규모를 대폭 키운 것이 특징이다. 행사 주최 측은 링컨기념관 반사연못과 포토맥강 바지선, 웨스트 포토맥 공원 등 워싱턴DC 일대 10곳에서 약 85만발의 폭죽을 쏘아 올렸다. 이번 불꽃놀이는 사상 최대 규모의 불꽃놀이로 기네스 세계기록을 경신했을 가능성도 제기된다. 도널드 트럼프 미국 대통령은 자신의 소셜미디어 트루스소셜에 “역대 최고의 불꽃놀이였다(Best fireworks show, EVER!)”며 만족감을 나타냈다. 트럼프 대통령은 불꽃놀이를 직접 주최하지는 않았지만, 건국 250주년 기념행사의 핵심 행사인 ‘미국에 바치는 헌사’에서 기념 연설을 했다. CNN은 이번 불꽃놀이 비용이 약 85만달러(13억원)로 추산된다고 전했다.', 'crawl', '조선일보', '2026-07-05 06:16:10', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GNSTAYJVGY2DMMRUG43DQMBWGQ.jpg', '2026-07-07 06:04:20', '2026-07-07 15:20:35.308095', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2645, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/05/MZRTKZBWGJTGEMBUGU4DQMBWMY/', 'https://www.chosun.com/international/international_general/2026/07/05/MZRTKZBWGJTGEMBUGU4DQMBWMY/', '국제', '트럼프 “공산주의는 암”… 6·25 참전용사 소개하며 반공 메시지', '도널드 트럼프 미국 대통령이 미국 건국 250주년 기념 연설에서 “미국은 결코 공산주의 국가가 되지 않을 것”이라고 강조했다. 트럼프 대통령은 4일(현지시각) 워싱턴DC 내셔널몰에서 열린 건국 250주년 기념식 연설에서 1776년 독립선언 이후 미국의 역사를 되짚으며 “공산주의는 패배자이며 앞으로도 늘 그럴 것”이라고 말했다. 그는 “공산주의 체제는 미국', '도널드 트럼프 미국 대통령이 미국 건국 250주년 기념 연설에서 “미국은 결코 공산주의 국가가 되지 않을 것”이라고 강조했다. 트럼프 대통령은 4일(현지시각) 워싱턴DC 내셔널몰에서 열린 건국 250주년 기념식 연설에서 1776년 독립선언 이후 미국의 역사를 되짚으며 “공산주의는 패배자이며 앞으로도 늘 그럴 것”이라고 말했다. 그는 “공산주의 체제는 미국 체제의 정반대이며 제대로 작동한 적이 없다”며 “미국의 전사들은 전 세계 전장에서 공산주의와 싸워왔다”고 강조했다. 이어 “공산주의와의 전쟁에 참전했던 용사들에게 자랑스럽게 감사를 표한다”며 6·25전쟁 당시 장진호 전투에 참전한 패트릭 핀 해병대 병장과 루디 미킨스 일병을 소개했다. 트럼프 대통령은 “공산주의는 암과 같다. 빨리 잘라내야 한다”며 “우리는 미국에 공산주의자들을 결코 원하지 않는다”고 말했다. 이어 “그런 위협은 시작되기 전에 막아야 한다”고 덧붙였다. 연설에서는 오는 11월 중간선거를 앞두고 처리를 촉구해 온 ‘SAVE 법’도 언급했다. 트럼프 대통령은 “미국이 돌아왔다”며 “우리는 미국을 계속 위대하게 유지할 것이고, SAVE 법을 통과시킴으로써 그렇게 할 것”이라고 말했다. ‘SAVE 법’은 유권자의 신분증 제시와 시민권 증명 의무화, 우편투표 제한 등을 담은 유권자 신분 강화 법안이다. 트럼프 대통령은 군사력도 강조했다. 그는 “미국은 세계 최강의 군대를 보유하고 있으며, 우리는 이를 사용해 엄청난 성공을 거뒀다”며 “베네수엘라를 보라. 이란을 보라. 우리는 그들의 군대를 궤멸시켰다”고 주장했다. 이어 “미국 국민보다 더 많은 선을 행하고, 더 큰 용기를 보이며, 더 많은 발전을 이룬 국민은 없다”며 “250년 동안 미국은 전 세계의 희망이자 약속, 빛이었다”고 말했다. 또 “거대한 제국과 왕국, 강대국과 폭군은 나타났다가 사라졌지만 250년이 지난 지금도 미국 공화국은 여전히 굳건히 서 있다”고 강조했다. AP통신은 이번 연설에 대해 “당파적 정치와 애국주의적 호소를 뒤섞었다”며 “역대 대통령들이 독립기념일 연설을 국민 통합의 계기로 활용해 온 것과 달리 이례적으로 당파적 성격을 드러냈다”고 평가했다.', 'crawl', '조선일보', '2026-07-05 05:04:04', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GE3TMMZUMU3TEOLBGAZTQYLCGA.jpg', '2026-07-07 06:04:20', '2026-07-07 15:20:37.146191', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2648, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/05/HA4DKYLFG5SDMMBYGU4DIMLCGI/', 'https://www.chosun.com/international/international_general/2026/07/05/HA4DKYLFG5SDMMBYGU4DIMLCGI/', '국제', '트럼프 “비가 건국 250주년 막지 못해”… 기념 연설 강행 의지', '폭염과 폭풍우 예보로 미국 건국 250주년 기념행사가 차질을 빚는 가운데 도널드 트럼프 미국 대통령이 예정된 기념 연설을 강행하겠다고 밝혔다. 트럼프 대통령은 4일(현지시각) 자신의 소셜미디어 트루스소셜에 “폭풍은 어떤 상황에서든 행운을 가져오며 행사를 더 흥미롭게 만들기도 한다”고 적었다. 이어 “폭풍이 지나가기를 기다릴 것이다. 새벽 2시가 되든, 지', '폭염과 폭풍우 예보로 미국 건국 250주년 기념행사가 차질을 빚는 가운데 도널드 트럼프 미국 대통령이 예정된 기념 연설을 강행하겠다고 밝혔다. 트럼프 대통령은 4일(현지시각) 자신의 소셜미디어 트루스소셜에 “폭풍은 어떤 상황에서든 행운을 가져오며 행사를 더 흥미롭게 만들기도 한다”고 적었다. 이어 “폭풍이 지나가기를 기다릴 것이다. 새벽 2시가 되든, 지금부터 한 시간 뒤가 되든 상관없다”고 말했다. 이는 폭풍우 예보로 연기된 워싱턴DC 내셔널몰의 건국 250주년 기념 연설과 불꽃놀이 행사를 기상 여건이 나아지는 대로 진행하겠다는 뜻으로 풀이된다. 트럼프 대통령은 “오늘은 토요일 밤이다. 늦게까지 밖에 있더라도 즐기자”며 “약간의 비가 미국 건국 250주년 기념행사를 막도록 두지 않을 것이다. 곧 백악관을 떠날 것”이라고 밝혔다. 또 “연설 시간이 밤 11시가 된다고 하지만 누가 신경 쓰겠느냐”며 지난달 14일 백악관 앞에서 열린 이종격투기(UFC) 행사 당시에도 강수 확률이 100%로 예보됐지만 실제로는 비가 내리지 않았다고 언급했다. 행사 주최 측인 ‘프리덤 250’에 따르면 당초 트럼프 대통령의 연설은 오후 9시 45분, 불꽃놀이는 오후 10시 30분으로 예정돼 있었지만, 기상 상황에 따라 행사 시작이 예정보다 크게 늦어질 가능성이 제기되고 있다.', 'crawl', '조선일보', '2026-07-05 01:41:13', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MI2TANBWGYZWEYJQMUZGGN3FMI.jpg', '2026-07-07 06:04:20', '2026-07-07 15:20:42.827341', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2650, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/05/ME3DCYTCGEYTMOBWGM2DMMBXHE/', 'https://www.chosun.com/international/international_general/2026/07/05/ME3DCYTCGEYTMOBWGM2DMMBXHE/', '국제', '美 폭염 이어 폭풍우 예보… 건국 250주년 기념행사 차질', '미국 동부를 강타한 폭염에 이어 폭풍우와 뇌우까지 예보되면서 미국 건국 250주년 기념행사에 차질이 빚어졌다. 4일(현지시각) CNN에 따르면 이날 워싱턴DC 내셔널몰에서 열릴 예정이던 ‘미국에 바치는 헌사(Tribute to America)’ 행사와 일대에서 진행 중인 ‘위대한 미국 박람회’는 악천후가 지나갈 때까지 연기됐다. 이번 행사에서는 도널드 트', '미국 동부를 강타한 폭염에 이어 폭풍우와 뇌우까지 예보되면서 미국 건국 250주년 기념행사에 차질이 빚어졌다. 4일(현지시각) CNN에 따르면 이날 워싱턴DC 내셔널몰에서 열릴 예정이던 ‘미국에 바치는 헌사(Tribute to America)’ 행사와 일대에서 진행 중인 ‘위대한 미국 박람회’는 악천후가 지나갈 때까지 연기됐다. 이번 행사에서는 도널드 트럼프 미국 대통령의 기념 연설과 대규모 불꽃놀이가 예정돼 있었다. 다만 백악관 고위 당국자는 기상 상황에 따라 연설 시간이 다소 변경될 수 있지만, 트럼프 대통령은 예정대로 연설에 나설 것이라고 밝혔다. 행사 참가자들은 오후 늦게 강한 돌풍과 뇌우가 예보되자 행사장을 떠나 주변 박물관과 관공서 등으로 대피하라는 안내를 받았다. 행사 주최 측인 ‘프리덤 250’은 폭풍우와 낙뢰가 발생할 경우 폭염 속에서 장시간 대기하던 대규모 인파가 안전사고에 노출될 수 있어 이 같은 조치를 취했다고 설명했다. 비구름이 미국 동부 전역으로 확산하면서 보스턴에서 예정됐던 건국 250주년 기념 불꽃놀이 행사도 연기됐다고 CNN은 전했다.', 'crawl', '조선일보', '2026-07-05 00:13:07', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GUZWGN3BG5QWEZDFGM3DEYLEMM.jpg', '2026-07-07 06:04:20', '2026-07-07 15:20:46.7556', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2652, 'https://www.chosun.com/arc/outboundfeeds/rss/category/international/?outputType=xml', 'https://www.chosun.com/international/international_general/2026/07/05/HEZWKYZWGY2GCNJUMQYTKZRXGQ/', 'https://www.chosun.com/international/international_general/2026/07/05/HEZWKYZWGY2GCNJUMQYTKZRXGQ/', '국제', '美 독립 250주년 대규모 기념행사… 트럼프 연설·기네스 불꽃놀이', '미국이 4일(현지시각) 독립 및 건국 250주년을 맞아 워싱턴DC에서 대규모 기념행사를 개최한다. 도널드 트럼프 미국 대통령은 기념 연설을 통해 미국의 성과를 강조하고 자신의 국정 방향을 제시할 예정이다. 미국은 1776년 7월 4일 영국으로부터 독립을 선언한 독립선언서를 채택한 날을 독립기념일로 기념해 왔다. 독립선언서에는 모든 인간의 평등과 자유, 행', '미국이 4일(현지시각) 독립 및 건국 250주년을 맞아 워싱턴DC에서 대규모 기념행사를 개최한다. 도널드 트럼프 미국 대통령은 기념 연설을 통해 미국의 성과를 강조하고 자신의 국정 방향을 제시할 예정이다. 미국은 1776년 7월 4일 영국으로부터 독립을 선언한 독립선언서를 채택한 날을 독립기념일로 기념해 왔다. 독립선언서에는 모든 인간의 평등과 자유, 행복추구권, 국민의 동의에 기반한 정부 등 미국의 건국 이념이 담겼다. 이번 250주년 기념행사는 워싱턴DC 내셔널몰에서 열린다. 행사에서는 미 공군 편대 비행과 에어쇼, 군악대·의장대 공연 등이 진행되며, 트럼프 대통령은 오후 9시 45분쯤 기조연설에 나설 예정이다. 트럼프 대통령은 연설에서 미국 건국 250주년의 의미를 조명하는 한편 정치·경제·군사 분야의 성과와 자신의 국정 성과를 강조할 것으로 예상된다. 또한 미국의 미래 비전과 국가 정체성에 대한 메시지를 내놓을 것으로 전망된다. 행사 마지막에는 약 40분간 85만발의 폭죽을 쏘아 올리는 대규모 불꽃놀이가 예정돼 있다. 주최 측은 이번 행사를 통해 불꽃놀이 부문 기네스 세계기록 경신을 추진하고 있다. 다만 미국 동부를 강타한 폭염은 변수로 꼽힌다. 이날 오전 예정됐던 워싱턴DC 독립기념일 퍼레이드는 무더위로 취소됐다. 한편, 미국 사회는 이번 행사에서도 정치적 분열도 드러났다. 코네티컷, 일리노이, 매사추세츠, 오리건 등 민주당 성향이 강한 일부 주는 워싱턴DC에서 열린 ‘위대한 미국 박람회’에 불참했다. JD 밴스 미국 부통령은 이날 뉴욕에 정박한 함정에서 열린 행사 연설에서 “오늘 일부 사람들은 미국의 위대함보다 결점만을 이야기할 것”이라며 국가 통합을 강조했다.', 'crawl', '조선일보', '2026-07-04 22:19:06', '보수', 'ready', 'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GAYTKMJTMNRDKY3GMU3DIZDCGU.jpg', '2026-07-07 06:04:20', '2026-07-07 15:20:50.671377', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2663, 'https://www.yonhapnewstv.co.kr/category/news/politics/feed/', 'AKR20260707142343O3w', 'https://www.yonhapnewstv.co.kr/news/AKR20260707142343O3w', '정치', '선관위 국조특위, 위철환 등 1차 청문회 증인 97명 채택', '의사봉 두드리는 윤상현 선관위 국조특위 위원장(과천=연합뉴스) 류영석 기자 = 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 윤상현 위원장이 7일 경기 과천 중앙선거관리위원회에서 열린 현장조사 및 전체회의에서 의사봉을 두드리고 있다. 2026.7.7 ondol@yna.co.kr(과천=연합뉴스) 류영석 기자 = 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 윤상현 위원장이 7일 경기 과천 중앙선거관리위원회에서 열린 현장조사 및...', '국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 윤상현 위원장이 7일 경기 과천 중앙선거관리위원회에서 열린 현장조사 및 전체회의에서 의사봉을 두드리고 있다. 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 오는 14일 1차 청문회에 중앙선거관리위원 전원을 포함해 행정안전부·경찰 관계자 등 모두 97명을 증인으로 부릅니다. 국조특위는 오늘(7일) 경기도 과천시 중앙선관위에서 열린 현장조사에서 위철환 중앙선관위원장 직무대행과 노태악 전 중앙선관위원장 등 전·현직 중앙선관위원 9명을 비롯해 증인 97명과 참고인 15명에게 1차 청문회 출석을 요구하기로 의결했습니다. 증인 명단에는 2023년 자녀 채용 비리 문제가 불거졌던 박찬진 전 사무총장과 송봉섭 전 사무차장 등이 포함됐습니다. 또 2022년 제8회 지방선거 당시 발생한 서울 구로구 개표 오류 사건과 관련해 김필곤·김창보·이승택·정은숙 당시 중앙선관위 상임위원이 포함됐고, 행정안전부 선거사무 실무자 2명을 비롯해 군 거소투표 이중투표 사건과 관련해 국방부 실무자 1명도 증인으로 채택했습니다. 잠실 올림픽공원 핸드볼경기장 내 투표함 반출 과정에서 발생한 시위대와의 충돌과 관련해선 유재성 경찰청장 직무대행과 현장 경찰관 등이 증인으로 채택됐으며, 김태훈 검경합동수사본부장과 선관위 수의계약 업체 관계자 등도 증인 명단에 올랐습니다. 국민의힘은 윤호중 행정안전부 장관, 안규백 국방부 장관에 대한 증인 채택도 요구했지만 여당의 반발로 간사 간 협의를 거쳐 결정하기로 했습니다.', 'crawl', '연합뉴스TV', '2026-07-07 14:23:44', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/AKR/20260707/AKR20260707142343O3w_01_i.jpg', '2026-07-07 06:04:20', '2026-07-07 15:21:41.928506', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2666, 'https://www.yonhapnewstv.co.kr/category/news/politics/feed/', 'AKR202607071338159GX', 'https://www.yonhapnewstv.co.kr/news/AKR202607071338159GX', '정치', '靑 "미래대응기금으로 양극화·청년·균형발전 지원…8월 구체화"', '[유튜브 캡쳐][유튜브 캡쳐] 청와대가 반도체 산업 호황으로 발생하는 추가 세수를 활용하는 ''미래대응기금''의 주요 사용처로 양극화 완화와 지방균형발전, 청년 정책, 교육 등을 제시했습니다. 류덕현 청와대 재정기획보좌관은 오늘(7일) 성기홍 홍보소통수석이 진행한 유튜브 방송 ''청와대 팩트방앗간''에 출연해 잠재성장률 반등과 K자 양극화 완화, 지방균형발전, 청년과 교육 문제 해결을 위해 미래대응기금을 준비하고 있다고 밝혔습니다. 특히 청년 정...', '청와대가 반도체 산업 호황으로 발생하는 추가 세수를 활용하는 ''미래대응기금''의 주요 사용처로 양극화 완화와 지방균형발전, 청년 정책, 교육 등을 제시했습니다. 류덕현 청와대 재정기획보좌관은 오늘(7일) 성기홍 홍보소통수석이 진행한 유튜브 방송 ''청와대 팩트방앗간''에 출연해 잠재성장률 반등과 K자 양극화 완화, 지방균형발전, 청년과 교육 문제 해결을 위해 미래대응기금을 준비하고 있다고 밝혔습니다. 특히 청년 정책과 관련해 주거와 일자리, 청년들의 미래 비전을 담은 대대적인 정책을 준비 중이라며 기금을 이를 위한 재원으로 활용할 계획이라고 설명했습니다. 또 정부의 3대 메가프로젝트 인프라 투자도 주요 용처가 될 것이라고 밝혔습니다. 기금은 특별법을 통해 신설할 예정이며, 오는 8월 정부 예산안 편성 시기에 맞춰 구체적인 내용을 공개하는 것이 목표라고 덧붙였습니다.', 'crawl', '연합뉴스TV', '2026-07-07 13:38:18', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/AKR/20260707/AKR202607071338159GX_01_i.jpg', '2026-07-07 06:04:20', '2026-07-07 15:22:09.993809', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2667, 'https://www.yonhapnewstv.co.kr/category/news/politics/feed/', 'AKR2026070713373505Y', 'https://www.yonhapnewstv.co.kr/news/AKR2026070713373505Y', '정치', '국조특위, 중앙선관위 현장조사서 "상황실 늑장 대응" 질타', '의사봉 두드리는 윤상현 선관위 국조특위 위원장(과천=연합뉴스) 류영석 기자 = 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 윤상현 위원장이 7일 경기 과천 중앙선거관리위원회에서 열린 현장조사 및 전체회의에서 의사봉을 두드리고 있다. 2026.7.7 ondol@yna.co.kr (끝)(과천=연합뉴스) 류영석 기자 = 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 윤상현 위원장이 7일 경기 과천 중앙선거관리위원회에서 열린 현장...', '의사봉 두드리는 윤상현 선관위 국조특위 위원장 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 윤상현 위원장이 7일 경기 과천 중앙선거관리위원회에서 열린 현장조사 및 전체회의에서 의사봉을 두드리고 있다. 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 오늘(7일) 중앙선거관리위원회 현장조사에서 투표용지 부족 사태 발생 직후 상황실의 늑장 대응과 고질적인 업무 태만을 질타했습니다. 더불어민주당 이해식 의원은 "비상상황 대응체계 개선안과 관련해, 선보고 후조치 체계로 개편하겠다고 보고했는데 기존에도 보고 시스템이 있는데 보고 자체를 안 해버리니 문제가 생긴 것"이라며 "면피성 대책이 아니냐"고 지적했습니다. 민주당 이기헌 의원도 "최초 사태 인지 시점이 오후 4시 25분인데 투표관리관들에게 문자 안내까지는 총 1시간 반 이상이 걸렸다"며 "선거를 총괄하는 상황실이 느슨하게 운영돼 사태를 키웠다"고 비판했습니다. 국민의힘 주진우 의원은 위철환 중앙선관위원장 직무대행을 향해 "선거일 가장 기민하게 움직여야 하는 곳이 중앙선관위 상황실인데 투표가 끝난 시점에 위 대행에게 보고됐다"며 "국민들이 수사를 원하기 때문에 특검을 받아야 한다"고 강조했습니다. 현장조사에선 송파구 잠실 올림픽공원 핸드볼경기장에 보관된 투표용지를 이송하기 전 ''검증''을 둘러싼 논의도 이어졌다. 강동완 중앙선관위 사무총장 직무대리는 최대한 이른 시일 내 국조특위에서 의결해주면 투표용지 이송 전 핸드볼경기장 내 공개 재검표에 바로 응하겠다고 보고했습니다. 이에 개혁신당 이준석 의원이 "투표용지의 무결성은 봉인 상태 등을 보면 어느 정도 검증될 것 같다. 정치적인 재검표 절차를 진행한다면 왜 했냐는 지적이 또 나올 수 있다"고 우려하자 윤상현 위원장은 여야 간사 협의를 요청했습니다. 여야는 조사 초반 국방부 장관과 행안부 장관 등 국무위원을 증인으로 채택하는 문제를 놓고 공방을 벌이기도 했습니다. 국민의힘 간사 서범수 의원은 "민주당 쪽에선 선관위에만 초점을 맞추고 그 외 선거 지원 부서와 청와대에 대해선 ''노터치'' 자세로 일관한다"며 "행안부나 청와대가 사태 발생 즉시 인지했다면 참정권 침해 사달이 났겠느냐"고 강조했습니다. 반면, 민주당 간사 윤건영 의원은 "지난번 기관 보고에서 행안부 장관을 불러 질의했지만, 드러난 건 선관위 요청 없인 행안부가 움직일 수 없다는 것 아니었나. 청와대와 선관위도 엄연히 분리된 헌법기관"이라며 "국조에 정쟁은 없어야 한다"고 반박했습니다.', 'crawl', '연합뉴스TV', '2026-07-07 13:37:36', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/AKR/20260707/AKR2026070713373505Y_01_i.jpg', '2026-07-07 06:04:20', '2026-07-07 15:22:19.514711', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2669, 'https://www.yonhapnewstv.co.kr/category/news/economy/feed/', 'MYH20260707143530VAz', 'https://www.yonhapnewstv.co.kr/news/MYH20260707143530VAz', '경제', '전분당 ''가격 담합'' 4개사에 과징금 7,476억…역대 최대', '[앵커] 7년 넘도록 가격을 담합한 혐의로 주요 전분사 4곳이 역대 최대인 7천억 원대 과징금을 받게 됐습니다. 이런 가운데 또다른 담합 의혹이 제기되면서 공정거래위원회의 추가 조사가 이뤄지고 있습니다. 이지현 기자가 보도합니다. [기자] 과자와 음료 등의 원재료일뿐 아니라 제조업에도 활용되는 전분과 전분당. 이 필수 원료 시장을 독과점하고 있는 대기업 4곳은 지난 2018년 5월부터 7년 5개월 동안, 13차례에 걸쳐 가격을 담합한 것으...', '7년 넘도록 가격을 담합한 혐의로 주요 전분사 4곳이 역대 최대인 7천억 원대 과징금을 받게 됐습니다. 이런 가운데 또다른 담합 의혹이 제기되면서 공정거래위원회의 추가 조사가 이뤄지고 있습니다. 과자와 음료 등의 원재료일뿐 아니라 제조업에도 활용되는 전분과 전분당. 이 필수 원료 시장을 독과점하고 있는 대기업 4곳은 지난 2018년 5월부터 7년 5개월 동안, 13차례에 걸쳐 가격을 담합한 것으로 조사됐습니다. 수입 옥수수를 들여와 전분과 전분당으로 만들어 파는 과정에서 원가, 즉 옥수수 가격을 구실로 거래처 납품가를 조정한 겁니다. 옥수수 가격이 오르면 재빨리 올리고 내리면 최대한 가격을 유지해 6조 원 넘는 관련 매출액을 올렸습니다. 납품가를 협상할 때도 사전에 목표가격을 정한 뒤 협상 주관사가 해당 금액을 거래처에 제시하면, 나머지 3사가 차례로 더 비싼 금액을 제안해 목표가격을 선택할 수밖에 없도록 압박했습니다. 이런 방식으로 담합 초기 1kg당 559원이었던 전분당 평균 가격은 한때 971원까지, 최대 73% 넘게 오르기도 했습니다. 불경기에 장기간에 걸쳐 부당이득을 극대화한 건데, 결국 7,476억 원에 달하는 역대 최대 과징금이 부과됐습니다. 전분당 가격이 인상될 경우 전후방 산업에 대한 연쇄적 파급 효과가 매우 큽니다. 결국 담합으로 인한 피해는 후방산업을 영위하는 실수요처와 대리점, 나아가 최종 소비자에게 전가되었습니다. 이런 가운데 또다른 담합 정황까지 포착됐습니다. 공정거래위원회는 가격을 담합한 4개사가 대형 실수요처 입찰 과정에서도 투찰가와 물량 등을 합의한 것으로 보고 새로운 심의에 들어갔습니다. 여기에 대상과 사조CPK, 삼양사 등 3사는 전분당 부산물 판매 가격도 짬짜미한 혐의를 받고 있습니다. 관련 매출액이 1조 5,500억 원에 이르는 것으로 추산되는데, 역시 심의를 거쳐 최대 20%까지 과징금을 부과할 수 있습니다.', 'crawl', '연합뉴스TV', '2026-07-07 14:35:33', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/MYH/20260707/MYH20260707143530VAz.jpg', '2026-07-07 06:04:20', '2026-07-07 15:22:31.932527', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2672, 'https://www.yonhapnewstv.co.kr/category/news/economy/feed/', 'AKR20260707141505Euc', 'https://www.yonhapnewstv.co.kr/news/AKR20260707141505Euc', '경제', '홈플러스, 익스프레스 매각에도 공익채권 1조원대', '홈플러스 강서점 본사[연합뉴스 자료사진][연합뉴스 자료사진] 홈플러스가 기업형 슈퍼마켓(SSM)인 홈플러스 익스프레스 매각으로 1,206억원의 현금을 확보했으나, 공익채권 규모는 여전히 1조원을 웃도는 것으로 나타났습니다. 오늘(7일) 유통업계에 따르면 최근 홈플러스 채권자협의회에 보고된 지난 5월 말 기준 홈플러스의 공익채권 규모는 1조999억원입니다. 이는 지난해 3월 회생절차 개시 당시의 3,328억원과 비교해 1년 2개월 만에 7,...', '홈플러스가 기업형 슈퍼마켓(SSM)인 홈플러스 익스프레스 매각으로 1,206억원의 현금을 확보했으나, 공익채권 규모는 여전히 1조원을 웃도는 것으로 나타났습니다. 오늘(7일) 유통업계에 따르면 최근 홈플러스 채권자협의회에 보고된 지난 5월 말 기준 홈플러스의 공익채권 규모는 1조999억원입니다. 이는 지난해 3월 회생절차 개시 당시의 3,328억원과 비교해 1년 2개월 만에 7,671억원 증가한 수치입니다. 세부적으로는 미지급 납품 대금 등 상거래채권이 7,940억원, 긴급운영자금(DIP) 채권이 1,614억원, 제세공과금 채권이 820억원, 미지급 급여가 625억원 포함됐습니다. 홈플러스는 지난달 22일 익스프레스 매각대금 1,206억원을 수령했지만 자금 여력 개선 효과는 제한적이었습니다. 매수자인 NS쇼핑이 지방세 미납 등을 이유로 450억원에 질권을 설정하면서 실제 활용 가능한 자금은 756억원 수준에 그쳤습니다. 이 중 650억원이 4~5월 미지급 급여 등에 쓰였으나 6월 급여 250억원이 새로 발생하면서 6월 말 기준 공익채권은 여전히 1조800억원 수준으로 추산됩니다. 매각대금 유입에도 공익채권 규모가 약 200억원 줄어드는 데 그치면서, 현재 논의 중인 2천억원 규모의 신규 자금 조달만으로는 유동성 위기를 해소하기 어렵다는 분석이 나옵니다. 공익채권은 회생절차에서 일반 회생채권보다 우선 변제해야 하는 채권인 만큼, 신규 자금을 조달하더라도 상당 부분이 기존 채권 상환에 투입될 가능성이 크기 때문입니다. 한 업계 관계자는 신규 자금 조달의 실효성이 크지 않은 상황이라며, 대주주인 MBK파트너스가 직접 나서서 임금 체불과 협력업체 피해를 최소화할 방안을 마련해야 한다고 지적했습니다.', 'crawl', '연합뉴스TV', '2026-07-07 14:15:08', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/AKR/20260707/AKR20260707141505Euc_01_i.jpg', '2026-07-07 06:04:20', '2026-07-07 15:22:51.227945', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2679, 'https://www.yonhapnewstv.co.kr/category/news/economy/feed/', 'AKR20260707114812zQQ', 'https://www.yonhapnewstv.co.kr/news/AKR20260707114812zQQ', '경제', '''한강 벨트'' 초고가 부동산 거래서 730억 탈루 드러나…318억 추징', '[연합뉴스TV 자료사진] 국세청이 초고가 주택 거래 등 부동산 탈세에 대한 세무조사를 벌여 총 318억 원의 세금을 추징했습니다. 국세청은 지난 10월부터 부동산 탈세가 의심되는 104여명에 대한 조사를 벌인 결과, 80여명에 대한 탈루 사례를 확인했다고 오늘(7일) 밝혔습니다. 누락된 세금 규모는 총 731억원에 달합니다. 이번 세무조사는 국세청이 지난 10월 강남 4구(강남·서초·송파·강동구)와 마·용·성(마포·용산·성동구) 등 이른바...', '국세청이 초고가 주택 거래 등 부동산 탈세에 대한 세무조사를 벌여 총 318억 원의 세금을 추징했습니다. 국세청은 지난 10월부터 부동산 탈세가 의심되는 104여명에 대한 조사를 벌인 결과, 80여명에 대한 탈루 사례를 확인했다고 오늘(7일) 밝혔습니다. 누락된 세금 규모는 총 731억원에 달합니다. 이번 세무조사는 국세청이 지난 10월 강남 4구(강남·서초·송파·강동구)와 마·용·성(마포·용산·성동구) 등 이른바 ''한강 벨트''의 30억 원 이상 주택 거래를 전수 검증한 데 따른 조치입니다. 이들은 부모로부터 몰래 증여받은 자금으로 고가 아파트를 취득하거나, 가장 매매로 1세대 1주택 비과세를 적용받아 양도소득세를 회피하는 등의 방법을 통해 세금을 회피한 것으로 드러났습니다. 탈루 방법 가운데 자금 출처와 관련된 부분이 60여건으로 가장 많았고, 가장 매매가 40여건으로 나타났습니다. 부동산 거래 자금이 사업소득 누락이나 법인 자금 유출과 관련된 경우, 사업체까지 조사 범위를 확대해 법인세·소득세 등 누락된 세금을 모두 추징했다고 국세청은 밝혔습니다. 국세청은 탈루 사실이 확인된 건에 대해 40%에 상당하는 부당 과소신고가산세를 부과했다고 밝혔습니다. 이외에도 조세범처벌법에 따라 검찰 고발(6명)과 7억원의 벌금 상당액 통고처분(4명)이 이뤄졌습니다. 국세청은 앞으로도 부동산 취득·보유·양도 등 거래 전 과정에서 발생하는 탈세 행위에 대한 강도 높은 세무조사를 실시할 방침입니다. 아울러, 부동산 탈세 신고센터 제보자에 대한 포상금도 신속하게 지급할 계획이라고 밝혔습니다.', 'crawl', '연합뉴스TV', '2026-07-07 12:00:04', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/AKR/20260707/AKR20260707114812zQQ_01_i.jpg', '2026-07-07 06:04:20', '2026-07-07 15:23:30.639815', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2682, 'https://www.yonhapnewstv.co.kr/category/news/society/feed/', 'MYH20260707144229JHH', 'https://www.yonhapnewstv.co.kr/news/MYH20260707144229JHH', '사회', '[사건현장] 검찰, 강제수사 착수…''유착 의혹'' 정조준', '&lt;출연 : 서정빈 변호사&gt; 장윤기 부실 수사 의혹과 관련해 강제수사에 착수한 검찰이, 수사를 담당했던 광주 광산경찰서 형사들의 주거지 압수수색에 나섰습니다. 한편, 경남 거제와 제주 등의 주요 관광지에서 고의로 교통사고를 유발해 억대 보험금을 챙긴 일당이 경찰에 붙잡혔는데요. 이 시각 주요 사건 사고 소식을 서정빈 변호사와 함께 짚어보겠습니다. &lt;질문 1&gt; 장윤기 아버지와 담당 경찰 수사팀 간의 유착 의혹이 커지고 있...', '장윤기 부실 수사 의혹과 관련해 강제수사에 착수한 검찰이, 수사를 담당했던 광주 광산경찰서 형사들의 주거지 압수수색에 나섰습니다. 한편, 경남 거제와 제주 등의 주요 관광지에서 고의로 교통사고를 유발해 억대 보험금을 챙긴 일당이 경찰에 붙잡혔는데요. 이 시각 주요 사건 사고 소식을 서정빈 변호사와 함께 짚어보겠습니다. <질문 1> 장윤기 아버지와 담당 경찰 수사팀 간의 유착 의혹이 커지고 있는데요. 결국 검찰이 오늘 강제수사에 착수했습니다. 검찰이 유착 의혹 등에 대해 별도로 직접 수사에 나선 건, 경찰관의 비위 사건에 대한 직접 수사권을 갖고 있기 때문인 거죠? <질문 2> 그런데 앞서 수사팀장을 긴급체포한 건 경찰청이었지 않습니까? 하지만 이후 수사 담당을 광주경찰청에서 경찰청 수사인권담당관으로 하루 만에 교체됐는데요. 특별수사팀으로 확대된 건, 그만큼 사안이 중대하다는 판단인 걸까요? <질문 3> 특히 검찰은 강제수사에 착수한 후, 곧바로 담당 형사들의 주거지 압수수색부터 단행했는데요. 현재 유착 의혹 형사들에 대해 공무상비밀누설과 증거인멸 혐의 등을 적용했거든요? 실제 법적으로 유착이 인정되려면 압수수색 과정에서 어떤 객관적 증거나 정황이 입증돼야 하는 건가요? <질문 4> 이러한 가운데, 특별수사팀이 증거인멸 의혹을 받는 광산경찰서 수사팀장에 대한 구속영장을 신청했는데요, 수사팀장이 증거인멸 혐의로 입건된 이유는 수사 초기 발견됐던 결박 도구가 흔적도 없이 사라졌기 때문이지 않습니까? 특히 사라진 케이블 타이가 있느냐 없느냐는 장윤기에게 강간 살인죄를 적용하느냐, 마느냐의 문제가 될 수도 있다고 하는데 어떤 이유 때문인가요? <질문 5> 현재 검찰은 보완수사를 통해 장윤기의 진행 범행 목적이 여학생 남치 빛 강간이었다고 규정하긴 했지만, 제압에 필요한 결박 도구는 현재까지 단 1점도 확보되지 않은 상황인데요. 하지만 당초 현장 수색 당시엔 있었다는 사실은 여러 기록으로는 확인이 되고 있는데요. 이래도 증거 효력이 없는 건가요? <질문 6> 결국 케이블 타이를 왜 증거물로 따로 챙기지 않았는지, 이것도 핵심 쟁점이 될 텐데요. 수사팀장에게 증거인멸 혐의가 적용된 건, 수사팀장이 직접 이 케이블 타이를 인멸하는 데에 결정적 역할을 했다고 의심하고 있는 걸까요? <질문 6-1> 특히 장윤기 사건 수사 초기에 강간살인 혐의를 검토했고, 프로파일러 역시 강간살인 의심 소견을 제기했지만 수사 지휘 체계를 거치는 과정에서 반영되지 않은 것으로 확인됐는데요. 이러한 결정 과정도 유착 의혹 수사 대상이 된다고 보십니까? <질문 7> 핵심 증거가 사라지는 과정에 경찰 간부 출신의 장윤기 아버지가 과연 어떤 역할을 했느냐도 중요한 쟁점인데요. 경찰청이 장윤기 아버지의 증거인멸 정황에 대해 친족 특례 형사처벌 제외라도 징계가 가능하다고 밝혔습니다. 여기서 의미하는 징계 책임은 형사 처벌과는 어떻게 다른 건가요? <질문 7-1> 공무원 중에서도 경찰 공무원 신분이었다는 점은 징계 수위에 어떤 영향을 미칠까요? <질문 8> 그런데 사안의 중대성에 비해 과연 경찰청의 징계만으로 국민들의 법감정에 부합할지 의문도 드는데요. 최고 수준의 징계는 어떤 것이고, 실제로 내려질 가능성은 어떻게 보십니까? <질문 9> 특히 이번 사건을 계기로 경찰 내부에서조차 검찰의 보완수사권이 필요하다는 목소리가 나오고 있습니다. 이번 사례는 검찰의 보완수사 개혁에 어떤 영향을 미치게 될 거라고 보십니까? <질문 10> 다음은, 이제 곧 여름 휴가철이 시작될 텐데요. 관광지에서 특히 조심해야할 사건입니다. 제주와 거제 관광지 등을 뒤흔든 이른바, 사고 각본단이 경찰에 붙잡혔는데요. 어떤 인물들이었던 겁니까? <질문 11> 음주운전 사실을 신고하겠다며 합의를 유도했다고 하는데, 이런 경우 보험사기 뿐 아니라 공갈죄까지 적용될 수 있는 건가요? <질문 11-1> 음주운전 사실이 들통날까봐 신고조차 하지 못한 피해자들은 음주운전을 했다고 하더라도 협박이나 금품 갈취를 당했다면 별도로 보호받을 수 있는 권리가 있는 건가요? <질문 12> 특히 이번 사건은 관광지에서 조직적으로 범행을 반복해 2억 원가량이나 뜯어낸 것으로 조사됐는데요. 여러 명이 역할을 나눠 범행을 저질렀다면 형량은 일반적인 보험사기나 공갈 사건보다 더 무거워질 가능성도 있는 건가요? <질문 13> 며칠간 스포츠계는 물론이고 교육계에까지 후폭풍이 상당했던 배재고 사태가, 일단 사과 방문으로 일단락된 모습인데요. 이제 관심은 징계 수위 변화와 수사 향방입니다. 먼저, 내일까지가 협회 재심 청구 기간인데요. 재심 청구를 한다면, 누가 주체가 되어야 하는 건가요? <질문 13-1> 배재고 학생들의 사과를 받아들인 광주제일고에서 과연 선처를 요청할 지도 관심인데요. 만약 선처를 요청한다면, 그게 재심에도 영향을 미칠까요? <질문 14> 그런데 이번 사건은 특정 개인이 아닌 상대 학교 선수들을 향한 집단적인 구호였는데요. 이처럼 집단을 향한 발언도 피해자가 특정된다면 모욕죄가 인정될 수 있는 건가요?', 'crawl', '연합뉴스TV', '2026-07-07 14:42:30', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/MYH/20260707/MYH20260707144229JHH.jpg', '2026-07-07 06:04:21', '2026-07-07 15:24:03.833128', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2690, 'https://www.yonhapnewstv.co.kr/category/news/society/feed/', 'MYH20260707133447lkO', 'https://www.yonhapnewstv.co.kr/news/MYH20260707133447lkO', '사회', '[단독] 검찰, 장윤기 수사팀장 압수수색…팀원 1명도 대상', '[앵커] 검찰이 장윤기를 수사했던 경찰을 상대로 압수수색에 착수했습니다. 장윤기 아버지와의 유착 정황, 증거를 인멸한 의혹과 관련해 검찰이 정식 수사에 돌입한 건데요. 압수수색 대상에는 수사팀장과 함께 팀원 1명이 포함된 것으로 확인됐습니다. 한채희 기자입니다. [기자] 광주지검이 오늘 오전부터 ''장윤기 사건 부실 수사'' 의혹이 불거진 광주 광산경찰서에 대한 강제수사에 착수했습니다. 광주광산경찰서와 당시 사건을 담당했던 수사팀 관계자들 주...', '검찰이 장윤기를 수사했던 경찰을 상대로 압수수색에 착수했습니다. 장윤기 아버지와의 유착 정황, 증거를 인멸한 의혹과 관련해 검찰이 정식 수사에 돌입한 건데요. 압수수색 대상에는 수사팀장과 함께 팀원 1명이 포함된 것으로 확인됐습니다. 광주지검이 오늘 오전부터 ''장윤기 사건 부실 수사'' 의혹이 불거진 광주 광산경찰서에 대한 강제수사에 착수했습니다. 광주광산경찰서와 당시 사건을 담당했던 수사팀 관계자들 주거지 등에 대한 압수수색 영장을 집행 중입니다. 혐의는 공무상비밀누설 및 증거인멸 등입니다. 이번 압수수색 대상에는 수사팀장이었던 박 모 경감과 수사팀원 1명이 포함된 것으로 파악됐습니다. 검찰은 이들이 장윤기 아버지에게 장윤기의 자취방 비밀번호는 물론 더 많은 수사 상황을 유출했다고 보고, 공무상비밀누설 혐의도 적시한 것으로 확인됐습니다. 어제 경찰청 국가수사본부는 박 경감을 장윤기의 범행을 입증할 핵심 증거를 인멸한 혐의 등으로 긴급체포했고 오늘 구속영장을 신청했습니다. 이 과정에서 장윤기 차량에 있던 포박 도구 ''케이블타이''가 증거 목록에서 누락되고, 현장검증 영상도 검찰로 송치되지 않은 사실이 확인됐습니다. 박 경감이 핵심 증거를 인멸한 정황이 구체적으로 드러나면서 강제수사에 착수한 것으로 보입니다. 장윤기 사건은 광주지검 형사3부에서 수사 및 공소 유지 중인데, 광주지검은 사안의 긴급성과 심각성을 고려해 전담수사팀을 꾸리고 증거인멸 의혹 수사에 착수했습니다. 박 경감의 경우 경찰에서 수사가 진행 중이지만 10월 전까지 경찰에 대한 범죄 수사권이 검찰에 있는 만큼 검찰은 법령상 문제가 없다는 입장입니다. 검찰은 압수물을 확보하는 대로 분석과 동시에 관련자들 소환에 나설 것으로 보입니다. 경찰과 검찰이 동시에 수사를 본격화하면서 이번 유착 의혹은 검경 간 수사 경쟁으로도 확대되는 모양새입니다.', 'crawl', '연합뉴스TV', '2026-07-07 13:34:50', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/MYH/20260707/MYH20260707133447lkO.jpg', '2026-07-07 06:04:21', '2026-07-07 15:25:00.213157', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2698, 'https://www.yonhapnewstv.co.kr/category/news/international/feed/', 'MYH20260707124127Amn', 'https://www.yonhapnewstv.co.kr/news/MYH20260707124127Amn', '국제', '베네수 사망 3,500여명…절박감 속 구조 오보도', '[앵커] 연쇄 강진이 베네수엘라를 강타한 지 11일이 지나면서 매몰자들의 생환 소식이 뜸해지고 있습니다. 골든타임의 4배에 달하는 시간을 버틴 어린이 등 4명을 구조했다는 소식이 전해졌지만, 현지 언론의 오보인 것으로 드러났습니다. 보도에 장효인 기자입니다. [기자] 현지시간 5일 베네수엘라 라과이라 항구. 임시 영안실에 희생자들의 관이 쌓여가고 있습니다. 국제 구조대가 수색 작업을 속속 중단하는 분위기 속에, 가족을 찾지 못한 생존자들은...', '연쇄 강진이 베네수엘라를 강타한 지 11일이 지나면서 매몰자들의 생환 소식이 뜸해지고 있습니다. 골든타임의 4배에 달하는 시간을 버틴 어린이 등 4명을 구조했다는 소식이 전해졌지만, 현지 언론의 오보인 것으로 드러났습니다. 현지시간 5일 베네수엘라 라과이라 항구. 임시 영안실에 희생자들의 관이 쌓여가고 있습니다. 국제 구조대가 수색 작업을 속속 중단하는 분위기 속에, 가족을 찾지 못한 생존자들은 여전히 실낱같은 희망을 놓지 못하고 있습니다. <엘리자베스 레온 / 라과이라 주민> "4층으로 들어가기 위해 콘크리트 바닥판을 뚫는 중입니다. (지금까지 6개를 뚫은 건가요?) 네 번에 걸쳐서요. 맨손으로요." 가족들의 시신만이라도 수습하고 싶다는 마음으로 애써 담담하게 수색을 이어가고 있지만. <노엘 마르케스 / 라과이라 주민> "어머니와 할머니가 돌아가셨고, 할아버지와 형, 임신 8개월이었던 여동생도… 아직 그녀를 찾지 못했습니다." 12살 딸의 시신을 발견한 아버지는 끝내 눈물을 쏟아냈습니다. 연쇄 강진으로 인한 사망자는 3천 명을 넘겼습니다. 실종자가 최대 5만 명으로 추정되는 만큼, 피해는 더 커질 전망입니다. 매몰자들의 생환 가능성은 희박해졌습니다. 소셜미디어 등을 통해 지진 발생 11일만에 어린이 등 4명을 극적으로 구조하는 장면이 알려졌지만, 현지 언론의 오보인 것으로 확인됐습니다. 이 소식을 보도한 현지 매체는, 최근이 아닌 이전에 이뤄진 구조 장면이었다고 설명했습니다.', 'crawl', '연합뉴스TV', '2026-07-07 12:41:27', '중도', 'ready', 'https://media.yonhapnewstv.co.kr/article/MYH/20260707/MYH20260707124127Amn.jpg', '2026-07-07 06:04:21', '2026-07-07 15:25:46.200784', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2805, 'https://www.mk.co.kr/rss/50400012/', NULL, 'https://www.mk.co.kr/news/politics/12092281', '경제', '반도체 산단 확정에도 무안 “3대 조건은 그대로”…군공항 이전 협의 최대 변수', '군공항 이전 협의가 변수 무안 “3대 조건” 재확인 5자 협의체 재편 추진정부가 호남권 반도체 산업단지 입지를 광주 군공항 부지로 확정하면서 군공항 이전 사업에도 속도가 붙을 것이..', '군공항 이전 협의가 변수 무안 “3대 조건” 재확인 5자 협의체 재편 추진 사진 확대 김산 무안군수. [연합뉴스] 정부가 호남권 반도체 산업단지 입지를 광주 군공항 부지로 확정하면서 군공항 이전 사업에도 속도가 붙을 것이라는 기대가 나오고 있다. 다만 군공항 이전이 반도체 산단 조성의 선결 과제로 떠오른 가운데, 무안군은 기존 3대 요구조건을 재확인하며 정부의 구체적인 이행 방안을 요구했다. 7일 전남광주통합특별시 등에 따르면 현재 광주 군공항 이전은 무안군 망운면 일대를 중심으로 절차가 진행되고 있다. 국방부는 지난 4월 망운면을 예비이전후보지로 선정했으며, 이전후보지 지정을 위한 후속 절차를 밟고 있다. 당초 지난달 말 열릴 예정이던 이전후보지 선정위원회 2차 회의는 반도체 메가프로젝트 발표와 전남광주통합특별시 출범 일정 등이 겹치면서 연기됐다. 광주시와 전남도가 통합해 전남광주통합특별시가 출범하면서 기존 광주시장과 전남지사가 참여하던 6자 협의체도 민형배 특별시장이 양 지자체를 대표하는 5자 협의체로 재편될 예정이다. 협의체 논의가 마무리되면 국방부는 이전후보지를 공식 지정하고, 이후 무안지역 지원계획 수립과 주민투표 등을 거쳐 최종 이전지를 확정하게 된다. 정부도 군공항 이전이 반도체 프로젝트의 핵심 변수라는 점을 인정하고 있다. 강훈식 대통령 비서실장은 6일 브리핑에서 “안보 공백이 발생하지 않는 범위 안에서 군공항을 조기에 이전하는 것을 전제로 한다”고 밝힌 바 있다. 무안군은 반도체 클러스터 조성 자체에는 환영의 뜻을 밝혔다. 무안군은 7일 입장문을 내고 “호남권 반도체 클러스터 조성은 수도권에 집중된 첨단산업 기반을 분산하고 국가균형발전을 실현하는 의미 있는 국가 프로젝트”라며 “광주 군공항 부지를 중심으로 반도체 산업 생태계가 조성되면 전남광주특별시는 물론 서남권 전체의 산업 경쟁력을 높이는 계기가 될 것”이라고 밝혔다. 다만 군공항 이전과 관련해서는 기존 입장을 유지했다. 무안군은 △광주 민간공항의 무안국제공항 선 이전 △전남광주특별시와 정부의 1조원 규모 지원 △국가 차원의 획기적인 인센티브 제공 등 기존 3대 요구조건에 대한 구체적인 이행 방안이 마련돼야 한다고 강조했다. 김산 무안군수는 “광주 군공항 이전 문제 역시 이번 국가사업과 함께 상생의 원칙 속에서 속도감 있게 추진되기를 바란다”며 “무안군이 제시한 광주 민간공항 선 이전과 1조원 규모 지원, 국가 차원의 획기적인 인센티브 등 3대 요구조건에 대한 구체적인 이행 방안이 조속히 마련되기를 기대한다”고 밝혔다.', 'crawl', '매일경제', '2026-07-07 14:17:37', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/news-p.v1.20260707.fd4b21153c4d4714a2ef7539d90ed4b0_P1.jpg', '2026-07-07 06:04:22', '2026-07-07 15:30:27.675434', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2806, 'https://www.mk.co.kr/rss/50400012/', NULL, 'https://www.mk.co.kr/news/society/12092269', '경제', '“내일 출근길, 우산으로 안되겠네”…중부지방 최대 150mm 물폭탄 예고', '경기·강원 9일까지 폭우 예고 북부는 오전, 남부는 저녁에 집중 충청·전라·경상권 9일 집중 호우수요일인 8일 새벽부터 중부지방을 중심으로 강한 비가 이어지겠다. 경기 북부와 강원..', '경기·강원 9일까지 폭우 예고 북부는 오전, 남부는 저녁에 집중 충청·전라·경상권 9일 집중 호우 사진 확대 지난 5일 서울 종로구 광화문역 인근 버스정류장에서 시민들이 소나기를 피하고 있다. [뉴스1] 수요일인 8일 새벽부터 중부지방을 중심으로 강한 비가 이어지겠다. 경기 북부와 강원 북부 내륙은 오전에, 경기 남부와 강원 중·남부 내륙은 늦은 오후에 집중적인 폭우가 내릴 전망이다. 강한 비는 목요일인 9일까지 최대 150㎜가 넘게 내리며 곳곳에 수해를 일으킬 수 있다. 7일 기상청에 따르면 8~9일 전국 대부분 지역에 많은 비가 내리겠다. 비는 8일 수도권과 강원 내륙을 중심으로 강하게 쏟아진 뒤 9일에는 충청권과 전라권, 경상권 내륙으로 범위를 넓힐 전망이다. 8일 강한 비가 가장 먼저 내리는 곳은 경기 북부와 강원 북부 내륙이다. 이들 지역에는 8일 이른 새벽부터 낮 사이엔 우산을 써도 몸이 흠뻑 젖는 수준인 시간당 20~30㎜의 강한 비가 내릴 전망이다. 출근 시간대에 비가 강하게 쏟아지며 일부 저지대는 침수 위험이 있으니 차량 운행과 보행 안전에 각별히 유의해야 한다. 강한 비의 중심은 8일 저녁부터 경기 남부와 강원 중·남부로 옮겨가겠다. 이들 지역은 8일 저녁부터 9일 새벽 사이 시간당 20~30㎜의 비가 예상된다. 특히 퇴근길부터 늦은 밤사이 빗줄기가 더욱 강해질 수 있으니 지하차도나 하천 인근 통행에 주의해야겠다. 충청권과 전북·경북은 목요일인 9일 집중호우가 발생할 위험이 크다. 충청권과 전북 북부는 9일 오전 시간당 30~50㎜의 강한 비가 내리며 일부 도로가 통제될 수 있다. 같은 시간대에 경북 북부내륙도 시간당 20~30㎜의 비가 예고됐다. 8~9일 예상 강수량은 △서울·인천·경기, 서해5도 50~100㎜(많은 곳 경기 남부 150㎜ 이상 △강원 내륙·산지 50~100㎜(많은 곳 강원 중·남부 내륙은 150㎜ 이상 △대전·세종·충남·충북 50~100㎜(많은 곳 충남권, 충북 중·북부 150㎜ 이상) △전북은 30~80㎜(많은 곳 전북 북서부는 120㎜ 이상) △경북 북부 내륙도 30~80㎜(많은 곳 120㎜ 이상 △대구·경북 20~60㎜ △경남 서부 내륙 5~40㎜ △제주도 5㎜ 안팎이다. 이에 중부지방을 중심으로는 호우특보가 내려질 수 있다. 비가 내리는 지역에서는 돌풍과 함께 천둥·번개가 치겠다. 짧은 시간에 강한 비가 내리는 만큼 하천변 산책로와 지하차도는 고립 위험이 있어 출입하지 않는 것이 안전하다. 비가 내리는 산지에서는 토사 유출, 산사태, 낙석, 축대 붕괴가 발생할 수 있다. 도로가 미끄럽거나 갑자기 침수될 수 있으니 출퇴근길 차량 운행 시 감속 운전이 필수다. 많은 비에 찜통 더위는 한층 심해질 전망이다. 8일 아침 최저기온은 21~25도, 낮 최고기온은 26~34도로 평년을 크게 웃돌겠다. 공기가 물기를 머금어 밤사이에도 열기가 빠지지 않는 탓에 당분간 오후 6시부터 다음날 오전 9시까지 기온이 25도 이상을 유지하는 열대야가 나타날 수도 있다.', 'crawl', '매일경제', '2026-07-07 14:12:21', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/rcv.NEWS1.NEWS1.20260705.2026-07-05T182347_1007992793_SOCIETY_I_P1.jpg', '2026-07-07 06:04:22', '2026-07-07 15:30:29.811175', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2809, 'https://www.mk.co.kr/rss/50400012/', NULL, 'https://www.mk.co.kr/news/politics/12092249', '경제', '정이한 전 부산시장 후보 구속영장 청구…‘피습 자작극’ 의혹', '지난 6·3 지방선거 당시 선거운동 중 피습당했다고 주장했다가 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보에 대한 구속영장이 청구됐다. 7일 부산 금정경찰서에 따르면 경..', '사진 확대 정이한 전 개혁신당 부산시장 후보가 지난 4월 16일 부산 부산진구 캠프에서 열린 현장 최고위원회의에서 발언하고 있다. [연합뉴스] 지난 6·3 지방선거 당시 선거운동 중 피습당했다고 주장했다가 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보에 대한 구속영장이 청구됐다. 7일 부산 금정경찰서에 따르면 경찰은 위계공무집행방해와 공직선거법 위반 등 혐의로 정 전 후보와 음료를 던진 A씨에 대한 구속영장을 지난 1일 신청했다. 이틀 뒤인 이달 3일 검찰이 부산지법에 영장을 청구했다. 경찰은 증거인멸과 도주 우려 등을 이유로 구속영장을 신청한 것으로 전해졌다. 이번 구속영장 신청은 사건 발생 67일, 선거가 끝난 지 한 달여 만에 이뤄졌다. 앞서 정 전 후보는 지난 4월 27일 부산 금정구 구서 나들목 인근에서 유세하던 중 지나가던 차량 운전자가 차창 밖으로 던진 음료에 맞아 쓰러졌다고 주장한 바 있다. 당시 캠프는 정 전 후보가 음료를 피하려다 넘어져 의식을 잃고 병원으로 옮겨졌으며, 뇌진탕과 근좌상 진단을 받았다고 발표했다. 그러나 경찰은 사건 경위에 석연치 않은 점이 있다고 판단해 정 전 후보와 A씨의 관계, 사건 전후 연락 여부, 공모 가능성 등을 수사해왔다. 사진 확대 정이한 전 개혁신당 부산시장 후보가 지난 4월 27일 유세 활동 중 한 운전자가 던진 음료수에 얼굴을 맞아 넘어지는 과정에서 땅에 머리를 부딪혔다고 주장했다. 정 전 후보가 병원으로 옮겨져 치료받는 모습. [개혁신당 제공] A씨는 정 전 후보와 친분이 있던 헬스장 트레이너 겸 관장으로 알려졌다. 경찰은 두 사람이 사건 전 연락한 정황 등을 토대로 사전 공모 여부를 확인해온 것으로 전해졌다. 경찰은 선거 다음 날 정 전 후보 캠프로 사용된 사무실을 압수수색했다. 또 캠프 관계자들을 참고인으로 소환해 사건 당시 정 전 후보의 상태와 언론 대응 경위 등을 조사했다. 정 전 후보 등 2명에 대한 구속 전 피의자 심문은 오는 8일 오후 2시 부산지법에서 열릴 예정이다. 경찰은 이와 별개로 정 전 후보 부친이 운영하는 온그룹 계열사 직원들이 선거운동에 동원됐다는 의혹, 정 전 후보 관련 여론조사기관의 공정성 의혹 등도 수사 중이다. 정 전 후보는 6·3 지방선거 부산시장 선거에서 2만7418표를 얻어 득표율 1.56%로 3위를 기록했다. 개혁신당은 그가 탈당한 상태라며 수사에 적극 협조하겠다는 입장이다. 경찰 관계자는 “이번 구속영장 청구는 테러 자작극 의혹에 한정된 것”이라며 “나머지 혐의에 대해서는 수사하고 있다”고 설명했다.', 'crawl', '매일경제', '2026-07-07 13:52:45', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/news-p.v1.20260707.7eb4a82b862e48258c0a3a787e8af721_P1.png', '2026-07-07 06:04:22', '2026-07-07 15:30:38.364146', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2826, 'https://www.mk.co.kr/rss/50400012/', NULL, 'https://www.mk.co.kr/news/society/12092065', '경제', '[속보] 검찰, 장윤기 아버지·경찰 유착 의혹 강제수사 착수', '경찰관 비위 사건의 직접 수사권을 가진 검찰이 ‘여고생 살해범’ 장윤기(23) 아버지와 수사팀 간 유착 의혹 등을 들여다보는 직접 수사에 착수했다. 7일 광주지검은 장윤기 사건을 ..', '사진 확대 경찰관 비위 사건의 직접 수사권을 가진 검찰이 ‘여고생 살해범’ 장윤기(23) 아버지와 수사팀 간 유착 의혹 등을 들여다보는 직접 수사에 착수했다. 7일 광주지검은 장윤기 사건을 담당했던 광주 광산경찰서에 수사관을 보내 압수수색 영장을 집행하고 있다. 경찰관이 저지른 범죄 행위는 검찰, 경찰이 각각 별도로 착수할 수 있다. 검찰은 형사과 담당팀 관계자 등 다수 경찰관을 공무상비밀누설, 증거인멸 등 혐의로 입건했다. 입건된 경찰관들은 지난 5월 5일 장윤기를 긴급체포한 뒤 검찰 송치까지 수사 과정에서 케이블타이·리얼돌·차량(SUV) 등 주요 증거물을 확보하지 않고, 현직 경찰인 장윤기 아버지에게 압수수색·구속영장 내용 등 수사 상황을 누설한 혐의를 받는다. 검찰은 해당 경찰관들의 주거지도 압수수색하고 있다. 검찰은 중대성 등을 고려해 경찰의 자체 비위 수사와 별도로 이번 사안을 직접 수사하기로 했다. 장윤기 사건 담당 팀장을 전날 증거인멸 혐의로 긴급체포한 경찰은 수사 주체를 광주경찰청 전담팀에서 국가수사본부로 격상해 이날 인력을 광주로 파견하기로 했다.', 'crawl', '매일경제', '2026-07-07 10:24:30', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/news-p.v1.20260707.be255d80a5094ce79c2455248a588c9a_P1.jpg', '2026-07-07 06:04:22', '2026-07-07 15:31:55.906719', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2836, 'https://www.mk.co.kr/rss/50400012/', NULL, 'https://www.mk.co.kr/news/society/12091584', '경제', '매경이 전하는 세상의 지식 (매-세-지, 7월 7일)', '1. 삼성전자와 SK하이닉스가 총 800조원을 투자하는 서남권 반도체 클러스터가 광주 군공항 부지에 들어설 예정입니다. 강훈식 대통령 비서실장은 6일 브리핑에서 “3대 메가프로젝트..', '사진 확대 정부가 6일 호남권 반도체 산업단지가 들어설 입지로 전남광주특별시 군공항 용지를 확정했다. 군공항 이전 사업 계획상 총 248만㎡(약 250만평) 규모의 용지 확보가 가능하고, 평지라서 용지 조성 기간을 단축할 수 있을 것으로 기대된다. 사진은 광주 군공항 용지 전경. [전남광주 김호영 기자] 1. 삼성전자와 SK하이닉스가 총 800조원을 투자하는 서남권 반도체 클러스터가 광주 군공항 부지에 들어설 예정입니다. 강훈식 대통령 비서실장은 6일 브리핑에서 “3대 메가프로젝트 민관 합동회의에서 광주 군공항 부지에 호남권 반도체 산단을 조성하기로 결정했다”고 전격 발표했습니다. 앞서 정부와 전남광주통합특별시·무안군 등은 광주 도호동 인근에 자리한 공항을 무안으로 이전하기로 합의했는데 이에 따라 비게 되는 부지에 반도체 클러스터를 조성한다는 계획입니다. 2. 금융위원회와 한국거래소가 ‘중복상장 원칙금지·예외허용 세부기준’을 공개했습니다. 금융위는 “모회사 일반주주 권익을 해치는 비대칭적 중복상장을 막기 위해 모회사 이사회 의무와 상장심사 기준을 새로 설계했다”고 설명했습니다. 주주동의 방식은 상법상 감사위원 선임에 준하는 ‘3% 룰’로 정해졌습니다. 3%를 초과하는 의결권은 제한되며 참석 지분의 과반과 전체 의결권의 4분의 1 이상 찬성으로 가결됩니다. 3. 3기 신도시인 경기 고양창릉에 공급되는 공공분양주택 ‘뉴:홈’의 본청약 공고에서 사전청약 당시 예고됐던 전용 대출 혜택이 빠진 것으로 확인됐습니다. 지난달 30일 공개된 고양창릉 S-3블록 입주자 모집 공고문에는 전용 대출과 관련한 내용이 담기지 않고 요건을 갖춘 경우 디딤돌 대출을 이용할 수 있다는 안내 문구만 포함됐습니다. 4년 전 사전청약 당시에 정부는 연 1.9~3.0% 고정금리, 최대 한도 5억원, 주택가격 80%까지 지원 등을 내세워 청년·신혼부부 참여를 독려했습니다. 4. 정몽규 대한축구협회 회장이 13년 5개월여 만에 한국 축구 수장직에서 물러났습니다. 한국 축구가 북중미월드컵 조별리그에서 A조 3위(1승2패)로 탈락한 직후 각계에서 즉각 사퇴 요구가 빗발친 가운데 정 회장은 임기를 2년 반 가량 남겨놓고 사퇴했습니다. 같은 날 박지성·이영표·박주호 등 국가대표 출신 축구인들이 참여한 K축구 혁신위원회는 서울 송파구 서울올림픽파크텔에서 첫 회의를 열었습니다. ☞ 생생한 미국 증시, 뉴욕 특파원에게 직접 듣고 싶다면?', 'crawl', '매일경제', '2026-07-07 07:00:00', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.4af4e4d2a9d9455d9244e3308d4944c8_P1.jpeg', '2026-07-07 06:04:22', '2026-07-07 15:32:47.563727', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2844, 'https://www.mk.co.kr/rss/50400012/', NULL, 'https://www.mk.co.kr/news/society/12091729', '경제', '장맛비, 찜통더위와 같이 온다…한낮 최대 35도, 습도마저 최고조', '중부 장맛비 최대 80mm 한낮 35도 찜통더위 기승7일 거센 장맛비가 내리는 가운데 찜통 더위가 기승을 부리겠다. 당분간 내륙을 중심으로 천둥·번개를 동반한 강한 비가 쏟아질 수..', '중부 장맛비 최대 80mm 한낮 35도 찜통더위 기승 사진 확대 서울 광화문 광장에서 시민들이 쏟아지는 장대비를 피해 우산을 들고 서있다 [매경DB] 7일 거센 장맛비가 내리는 가운데 찜통 더위가 기승을 부리겠다. 당분간 내륙을 중심으로 천둥·번개를 동반한 강한 비가 쏟아질 수 있어 침수 등의 피해가 우려된다. 6일 기상청에 따르면 7일은 전국 대부분 지역이 장마 범위에 들겠다. 비는 8일까지 내렸다 그치기를 반복할 전망이다. 내륙 곳곳에서는 차량 와이퍼를 작동해도 시야가 가릴 정도인 시간당 20~30㎜의 매우 강한 비가 내리겠다. 8일까지 예상 강수량은 △서울, 인천, 경기, 서해5도 30~80㎜(많은 곳 경기 북부 100㎜, 서해5도 150㎜ 이상) △강원 내륙·산지 30~80㎜(많은 곳 강원 북부 내륙 100㎜ 이상) △강원 동해안 5~30㎜ △대전·세종·충남·충북 30~80㎜ △광주·전남 20~60㎜ △전북 30~80㎜ △부산·울산·경남, 대구·경북 5~20㎜ △경북 북서 내륙 20~60㎜ △제주 5㎜ 미만이다. 비가 내리는 동안은 습도가 높겠고 비가 그치면 기온이 빠르게 오르겠다. 7일 아침 최저기온은 21~24도, 낮 최고기온은 28~35도로 평년(최저 20~23도, 최고 26~30도)을 크게 웃돌 전망이다. 고온 다습한 날씨로 인해 체감온도가 실제 기온을 넘어서겠다. 한국환경공단에 따르면 미세먼지 농도는 전 권역에서 ‘좋음’ 수준을 보이겠다.', 'crawl', '매일경제', '2026-07-06 21:12:07', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20230711.3665c6bd2400413bb300e9ad8802346c_P1.jpg', '2026-07-07 06:04:22', '2026-07-07 15:33:11.141881', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2862, 'https://www.mk.co.kr/rss/30300018/', NULL, 'https://www.mk.co.kr/news/politics/12091966', '경제', '이 대통령, 나토 정상회의 열리는 튀르키예로…방산 협력 확대 본격화', '이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 취임 후 처음으로 나토 정상회의에 참석하는 이 대통령은 이날 서울공항을 출발해 튀르..', '사진 확대 북대서양조약기구(NATO·나토) 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령 부부가 7일 성남 서울공항에서 환송객들을 향해 인사하고 있다. [연합뉴스] 이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 취임 후 처음으로 나토 정상회의에 참석하는 이 대통령은 이날 서울공항을 출발해 튀르키예 앙카라에 도착한 뒤 마르크 뤼터 나토 사무총장과 함께 일본·호주·뉴질랜드 정상 등이 참석하는 IP4 소인수 회담에 참석한다. 이어 나토 방위산업포럼에서 ‘공동의 가치, 더욱 강한 산업기반’을 주제로 기조연설을 하고, 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 참석할 예정이다. 청와대는 이번 참석이 지난달 주요 7개국(G7) 정상회의에 이어 한국 외교의 지평을 넓히는 동시에 세계 국방비의 55%를 차지하는 최대 방산시장인 나토 회원국들과 방산 협력을 본격화하는 의미가 있다고 설명했다. 특히 도널드 트럼프 미국 대통령도 나토 정상회의 참석을 위해 튀르키예를 방문할 예정인 만큼 양국 정상의 현지 대면 여부에도 관심이 쏠리고 있다. 이 대통령은 8일까지 튀르키예에 머무르다가 9일부터 몽골 국빈방문 일정을 이어갈 예정이다.', 'crawl', '매일경제', '2026-07-07 09:07:25', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/rcv.YNA.20260707.PYH2026070701470001300_P1.jpg', '2026-07-07 06:04:23', '2026-07-07 15:33:56.061736', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2878, 'https://www.mk.co.kr/rss/30300018/', NULL, 'https://www.mk.co.kr/news/world/12091613', '경제', '트럼프 만나는 나토…美무기 구매로 ''달래기''', '이란 전쟁을 거치며 균열이 확대된 서방 국가들의 방위 동맹체 북대서양조약기구(NATO·나토)가 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 정상회의를 개최한다. 호르무즈 해..', '튀르키예서 32개국 정상회담 이란전·그린란드탓 잇단 갈등 방위비 증액 약속 실제로 이행 미국산 무기 대거 사들여 구애 美는 동맹 진정성 평가 나설듯 한국도 초청국 자격으로 참여 李대통령, K방산 세일즈 전망 사진 확대 이란 전쟁을 거치며 균열이 확대된 서방 국가들의 방위 동맹체 북대서양조약기구(NATO·나토)가 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 정상회의를 개최한다. 호르무즈 해협에 대한 군함 파견 요청에 유럽 국가들이 미온적으로 대응하자 도널드 트럼프 미국 대통령이 공개적으로 불만을 터뜨리는 등 팽팽한 긴장감이 감도는 가운데 나토 정상들이 갈등 봉합을 위한 해법을 내놓을지에 이목이 쏠리고 있다. 마르크 뤼터 나토 사무총장은 5일 공개된 월스트리트저널(WSJ)과 인터뷰에서 "1년 전에는 모든 것이 (방위비 증액) 약속에 관한 것이었다"며 "올해는 이를 실행하는 것"이라고 말했다. 유럽 국가들이 미국의 요구대로 방위비 증액에 나섰고, 이제는 실제 국방력 강화를 이행하는 데 초점을 맞추고 있음을 시사한 것이다. 나토에 따르면 미국을 제외한 회원국들은 지난해 국방비를 2024년 대비 약 20% 늘린 5740억달러(약 880조원)로 확대했다. 하지만 유럽의 군비 증강 속도와 규모가 방산업계가 감당하지 못할 정도의 ''수용 한계''에 다다르고 있다는 것이 뤼터 사무총장의 설명이다. 뤼터 사무총장은 러시아·우크라이나 전쟁과 이란 전쟁으로 인한 무기·탄약 소모, 신규 병력 모집 등으로 인해 병목 현상이 나타나고 있다면서 "이 같은 난관을 극복하는 것이 논의할 핵심 사안"이라고 강조했다. 트럼프 행정부는 그린란드 사태와 이란 전쟁을 거치며 나토에 대한 불만이 고조된 상황이다. 트럼프 대통령이 덴마크령 그린란드에 대한 병합 의지를 내비쳤을 때 유럽 국가들은 집단 반발했다. 이란 전쟁에 대한 미국의 지원 요청에도 유럽 국가들은 소극적인 반응을 보였다. 이에 트럼프 대통령은 반복적으로 불만을 표출해왔다. 트럼프 대통령은 지난 2일 소셜미디어 트루스소셜에서 "미국은 나토에 어느 나라보다 많은 돈을 쓰지만 그 대가로 어떤 혜택도 얻지 못하고 있다"고 비판하기도 했다. 이 과정에서 미국은 유럽에 주둔 중인 미군의 감축 계획을 공개하는 등 나토가 출범한 지 77년 만에 최대 위기를 맞았다는 평가도 제기됐다. 특히 동쪽으로는 러시아가 우크라이나와의 전쟁 수행에 집중하고 있는 상황에서 나토 내 균열은 위기감을 재차 고조시킨다. 유럽 국가들은 방위비 증액 약속 이행과 함께 대규모 무기 구매 계약을 체결하는 방향으로 미국을 달래며 나토의 결속을 도모할 것으로 예상된다. 앞서 나토 회원국들은 지난해 6월 네덜란드 헤이그에서 열린 나토 정상회의에서 2035년까지 국내총생산(GDP) 대비 5%를 국방 분야에 지출하겠다고 합의한 바 있다. 매슈 휘터커 나토 주재 미국 대사는 프레스콜에서 "앙카라 정상회의에서는 헤이그 국방 공약에 대한 진척 상황을 점검할 것"이라며 "GDP의 5% 지출 목표와 함께 동맹국들이 유럽 대륙에서 진행 중인 부담 분담을 지원하기 위해 나토의 핵심 역량을 어떻게 확대해가고 있는지 평가할 것"이라고 말했다. 트럼프 행정부 고위당국자는 프레스콜에서 이번 정상회의 기간 수십억 달러 규모 미국산 무기 판매 계약이 성사될 예정이라고 강조했다. 외신들은 8일 발표가 전망되는 나토 정상회의 공동선언문 초안에서 트럼프 대통령을 포함한 회원국 정상들이 나토의 상호방위 조항인 제5조에 규정된 집단방위 의무를 재확인할 예정이라고 전하고 있다. 볼로디미르 젤렌스키 우크라이나 대통령이 초청된 이번 정상회의에서는 5년째 러시아의 침공에 맞서고 있는 우크라이나에 대한 지원과 이란 문제도 주요 의제로 논의될 전망이다. 이번 정상회의에는 이재명 대통령도 초청받았다. 나토는 한국·일본·호주·뉴질랜드 등 인도·태평양 지역 파트너(IP4) 국가 정상을 초대했다. 청와대는 이 대통령의 이번 정상회의 참석이 세계 국방비의 55%를 차지하는 최대 방산시장인 나토 동맹국들을 상대로 관련 협력을 본격 추진한다는 의미가 있다고 설명했다. [워싱턴 최승진 특파원 / 서울 김제관 기자]', 'crawl', '매일경제', '2026-07-06 17:58:48', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/20260707_01160108000001_M00.jpg', '2026-07-07 06:04:23', '2026-07-07 15:34:38.578864', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2885, 'https://www.mk.co.kr/rss/30300018/', NULL, 'https://www.mk.co.kr/news/world/12091118', '경제', '부친 장례식 불참한 이란 최고지도자, 왜?…건강 이상설·암살 우려 잠행설까지', '이란 최고지도자의 자리를 이은 차남 아야톨라 세예드 모즈타바 하메네이가 부친의 장례식에 모습을 드러내지 않으면서 그의 건강 상태와 권력 장악력을 둘러싼 의문이 커지고 있다. 5일(..', '사진 확대 모즈타바 하메네이 이란 최고지도자. [AFP=연합뉴스] 이란 최고지도자의 자리를 이은 차남 아야톨라 세예드 모즈타바 하메네이가 부친의 장례식에 모습을 드러내지 않으면서 그의 건강 상태와 권력 장악력을 둘러싼 의문이 커지고 있다. 5일(현지시간) 로이터통신 등 외신에 따르면 이날 테헤란에서 열린 하메네이 전 최고지도자의 장례 기도에는 장남 모스타파와 셋째 마수드, 막내 메이삼 등 다른 세 아들이 관 옆에서 기도를 올렸지만, 후계자인 모즈타바는 끝내 모습을 드러내지 않았다. 이란 국영TV도 세 형제가 모즈타바 없이 부친과 가족들의 관 곁에서 기도하는 모습을 생중계했다. 하메네이 전 최고지도자와 일부 가족은 지난 2월 28일 미국과 이스라엘의 공습으로 시작된 전쟁 첫날 사망했다. 당시 모즈타바는 얼굴을 다치고 다리에 중상을 입은 것으로 알려졌으며, 이후 지금까지 공식 석상에 모습을 드러내지 않고 있다. 새 최고지도자가 부친의 장례식에도 참석하지 않자 현지에서는 건강 이상설과 함께 권력 장악 여부를 둘러싼 추측이 이어지고 있다. 실제 장례식에 참석한 일부 시민들은 아쉬움을 감추지 못했다. 이란 타스님통신은 한 젊은 여성이 “기도가 시작되기 직전까지도 모즈타바가 직접 나오기를 바랐다. 그것이 우리의 유일한 소원이었다”고 말했다고 전했다. 전문가들 사이에서는 미국이나 이스라엘의 추가 암살 시도를 우려해 신변 안전을 위해 공개 활동을 자제하고 있다는 관측도 제기된다. 이란 당국은 국민 결속을 과시하기 위해 미국 건국 250주년 기념일인 4일부터 국가장 형식의 장례 일정을 진행하고 있다. 5일 장례식에는 군인과 신학생, 일반 시민 등 수만 명이 테헤란의 이맘호메이니 대(大) 모살라를 찾아 조문했다. 참석자들은 미국과 이스라엘에 대한 보복을 촉구하는 구호를 외치며 국기를 흔들었다. 영국 일간 가디언은 일부 참석자들이 “도널드 트럼프를 죽이라”는 구호를 외쳤다고 보도했다. 또 시인 모하마드 라술리는 추모 행사에서 “이제 세상은 트럼프에게 더 이상 좋은 곳이 아니다”라며 “우리의 이맘(최고지도자)을 죽인 사람을 왜 우리가 죽이지 말아야 하는가. 그렇게 하지 않는다면 그것이야말로 수치”라고 주장했다. 국영 언론은 당초 오후 9시까지 예정됐던 장례 행사가 추모객이 몰리면서 오후 10시까지 연장됐다고 전했다. 이란 지하철 당국은 4일 밤부터 5일 아침까지 약 700만건의 승차가 이뤄졌다고 밝혔다. 장례 일정은 오는 9일까지 이어진다. 6일에는 테헤란 시내에서 장례 행진이 진행되고, 7일에는 종교도시 곰에서 시아파 고위 성직자들이 참석하는 장례 예배가 열린다. 이어 8일 이라크의 시아파 성지 카르발라와 나자프에서 추모 행사가 진행된 뒤, 9일 하메네이 전 최고지도자의 고향이자 시아파 성지인 이란 북동부 마슈하드에서 최종 안장될 예정이다. 한편 CNN은 장례식에 참석한 장남 모즈타바파가 정치 활동은 거의 하지 않았지만 종교계에서는 상당한 영향력을 가진 인물이라고 전했다. 셋째 마수드는 최고지도자의 연설과 저작을 관리하는 ‘하메네이 저작 보존 및 출판국’을 이끌고 있으며, 막내 메이삼 역시 같은 기관에서 활동한 이력이 있는 것으로 알려졌다.', 'crawl', '매일경제', '2026-07-06 13:08:39', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.7be61e7332a84cfcb4f1d8242ea2cf8c_P1.jpg', '2026-07-07 06:04:23', '2026-07-07 15:34:55.747112', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2917, 'https://www.mk.co.kr/rss/50100032/', NULL, 'https://www.mk.co.kr/news/business/12091596', '경제', '[뉴스&분석] 광속 ''광주팹''… 軍공항 용지에 짓는다', '삼성전자와 SK하이닉스가 총 800조원을 투자하는 서남권 반도체 클러스터가 전남광주 군공항 용지에 들어선다. 지난달 29일 삼성전자와 SK하이닉스가 서남권 반도체 팹 4기를 건설..', '''3대 메가프로젝트'' 속도전 투자 발표 일주일 만에 확정 李 "행정 지연 절대로 안돼" 美中日도 반도체 국가대항전 사진 확대 반도체 산단 ''속전속결'' 최적지 정부가 6일 호남권 반도체 산업단지가 들어설 입지로 전남광주특별시 군공항 용지를 확정했다. 군공항 이전 사업 계획상 총 826만㎡(약 250만평) 규모의 용지 확보가 가능하고, 평지라서 용지 조성 기간을 단축할 수 있을 것으로 기대된다. 사진은 군공항 용지 전경. 전남광주 김호영 기자 삼성전자와 SK하이닉스가 총 800조원을 투자하는 서남권 반도체 클러스터가 전남광주 군공항 용지에 들어선다. 지난달 29일 삼성전자와 SK하이닉스가 서남권 반도체 팹 4기를 건설한다는 계획을 발표한 지 일주일 만에 용지까지 확정하면서 ''3대 메가프로젝트'' 속도전을 선언한 것이다. 강훈식 대통령비서실장은 6일 브리핑에서 "3대 메가프로젝트 민관합동회의에서 전남광주 군공항 용지에 호남권 반도체 산업단지를 조성하기로 결정했다"고 전격 발표했다. 강 실장은 "기업들은 호남권 입지 후보지 중 전남광주 군공항이 가장 적합한 용지라는 의견을 제시했다"며 "군공항 지역은 250만평(약 826만㎡) 규모의 용지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료돼 있는 만큼 공사기간을 최소화할 수 있다는 장점이 있다"고 설명했다. 서남권 클러스터 용지 선정은 시장 예상보다 빠르게 이뤄졌다. 이재명 대통령이 천명한 ''메가프로젝트 속도전''의 첫 단추로 해석된다. 이 대통령은 회의 모두발언에서 "지금 전 세계적으로 국운이 걸린 총력 경쟁이 벌어지고 있는데 누가 더 빠르냐로 결판이 나는 것 같다"며 "그야말로 속도전이 중요하다는 말씀을 드린다"고 말했다. 그러면서 "행정절차 지연으로 투자 집행이 늦어지는 일이 절대로 있어서는 안되겠다"고 강조했다. 한국뿐 아니라 일본 등 경쟁국도 반도체 산업 육성에 속도를 붙이는 모양새다. 일본 정부는 홋카이도의 라피더스, 구마모토의 TSMC, 히로시마의 마이크론 공장 등에 정부 보조금을 4조6360억엔(약 43조8000억원) 편성했다. TSMC는 대만, 마이크론은 미국 회사지만 보조금에 차별을 두지 않는다. 세계적 수준의 소재·부품·장비 업체를 갖고 있는 일본이 메모리 반도체 부활까지 선언하고 나서면서 각국의 반도체 경쟁은 더욱 치열해질 전망이다. [오수현 기자 / 도쿄 이승훈 특파원]', 'crawl', '매일경제', '2026-07-06 17:58:05', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/20260707_01110101000003_L00.jpg', '2026-07-07 06:04:23', '2026-07-07 15:36:13.658981', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2922, 'https://www.mk.co.kr/rss/50100032/', NULL, 'https://www.mk.co.kr/news/business/12091553', '경제', '군공항 토지수용 부담 없고 250만평 이미 평탄화 마쳐', '삼성전자와 SK하이닉스가 서남권 반도체 클러스터에 총 800조원을 투자하겠다고 밝힌 지 일주일 만에 청와대·정부가 전남광주특별시 군공항 용지에 반도체 산업단지를 조성하기로 결정하며..', '호남 팹 용지 낙점 배경은 사진 확대 삼성전자와 SK하이닉스가 서남권 반도체 클러스터에 총 800조원을 투자하겠다고 밝힌 지 일주일 만에 청와대·정부가 전남광주특별시 군공항 용지에 반도체 산업단지를 조성하기로 결정하며 ''속도전''에 나섰다. 이날 강훈식 대통령비서실장은 3대 메가프로젝트 민관합동 점검회의를 마치고 이 같은 내용을 밝혔다. 강 실장은 "기업들은 후보지 중에서 전남광주 군공항이 가장 적합한 용지라는 의견을 제시했다"며 "관계 부처 협의를 거쳐 군공항 용지에 호남 반도체 산단을 조성하기로 결정했다"고 말했다. 전남광주 군공항으로 정부·기업이 뜻을 모은 배경에는 △넓은 용지 △평탄화 작업 완료 △토지 수용 절차 △우수한 접근성 등이 있었다. 강 실장은 "전남광주 군공항은 826만㎡(약 250만평) 규모 용지 확보가 가능하고 이미 평탄화가 완료돼 공사기간을 최소화할 수 있다"고 설명했다. 강 실장은 "무엇보다 전남광주 군공항은 국유지이기 때문에 (토지 수용) 리스크가 많이 없다고 말씀드릴 수 있다"고 강조했다. [성승훈 기자 / 이덕주 기자]', 'crawl', '매일경제', '2026-07-06 17:51:10', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/20260707_01160103000001_M00.jpg', '2026-07-07 06:04:23', '2026-07-07 15:36:31.236052', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2955, 'https://www.mk.co.kr/rss/50200011/', NULL, 'https://www.mk.co.kr/news/stock/12092019', '경제', '삼성전자 ‘역대급 실적’에도 주가 맥못추네…코스피 8000선 붕괴', '삼성전자, 호실적에도 5%대 하락 기대감 선반영·차익매물 출회 영향코스피가 장 초반 2% 넘게 급락하며 8000선을 내줬다. 삼성전자가 역대 최대 분기 실적을 발표했지만 재료소멸로..', '삼성전자, 호실적에도 5%대 하락 기대감 선반영·차익매물 출회 영향 사진 확대 7일 서울 중구 하나은행 본점 딜링룸에서 직원들이 업무를 보고 있다. [연합뉴스] 코스피가 장 초반 2% 넘게 급락하며 8000선을 내줬다. 삼성전자가 역대 최대 분기 실적을 발표했지만 재료소멸로 인한 ‘셀온(Sell on)’ 현상이 나타난 영향으로 풀이된다. 7일 오전 9시 26분 현재 코스피는 전일 대비 211.61포인트(2.63%) 내린 7839.72를 가리키고 있다. 지수는 전일 대비 131.13포인트(1.64%) 하락한 7919.20으로 출발한 뒤 낙폭을 키우며 7800선까지 밀렸다. 수급별로는 외국인과 기관이 각각 3879억원, 3311억원 순매도하고 있다. 개인은 홀로 8049억원 순매수 중이다. 업종별로는 운송장비·부품(-5.92%), 전기·전자(-3.92%), 제조(-3.72%), 기계·장비(-3.00%), 보험(-2.74%) 등이 내리고 있는 반면 오락·문화(4.11%), 종이·목재(1.59%), 음식료·담배(1.58%), IT서비스(0.91%), 비금속(0.70%) 등은 강세를 보이고 있다. 간밤 미국 뉴욕증시에서는 인공지능(AI) 반도체주가 반등했고, 국내에서는 삼성전자도 이날 역대 최대 분기 실적을 발표했지만 주가는 오히려 하락 중이다. 실적 기대감이 이미 주가에 상당 부분 반영된 데다 차익실현 매물이 출회된 것으로 보인다. 한지영 키움증권 연구원은 “삼성전자 잠정 실적 발표 이후 셀온 물량이 출회할지, 업황 개선 기대에 따른 추격 매수가 유입될지 여부가 단기 관전 포인트”라며 “이번주 반도체를 포함한 코스피의 이익 모멘텀 재생성 여부가 증시 회복력의 강도를 결정할 것”이라고 말했다. 삼성전자는 올해 2분기 연결 기준 매출 171조원, 영업이익 89조4000억원의 잠정 실적을 기록했다고 공시했다. 이는 전년 동기 대비 각각 129.31%, 1810.26% 증가한 역대 최대 실적이다. 그러나 같은 시각 삼성전자는 전일 대비 1만6500원(5.19%) 내린 30만1500원에 거래되고 있다. SK하이닉스도 2만7000만원(1.15%) 하락한 231만6000원에 거래되는 등 반도체 대형주가 약세를 나타냈다. 이밖에 코스피 시가총액 상위 10개 종목 가운데 KB금융(1.40%)을 제외한 모든 종목이 하락 중이다. SK스퀘어(-4.88%), 삼성전기(-2.02%), 현대차(-4.18%), LG에너지솔루션(-3.67%), 삼성생명(-4.83%), 삼성물산(-3.34%), 삼성바이오로직스(-0.07%) 등이다. 코스닥지수는 전일 대비 19.33포인트(2.28%) 오른 866.40을 가리키고 있다. 외국인과 기관이 각각 293억원, 1121억원을 순매수했고 개인은 1408억원을 순매도 중이다. 코스닥 시총 상위 종목에서는 리노공업(-1.07%)을 제외한 전 종목이 오름세다. 특히 코오롱티슈진(8.15%), 에이비엘바이오(7.98%)가 급등하고 있으며 알테오젠(3.63%), 에코프로(2.46%), 레인보우로보틱스(2.50%), 주성엔지니어링(3.19%), HLB(3.38%) 등이 강세다.', 'crawl', '매일경제', '2026-07-07 09:49:24', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/rcv.YNA.20260707.PYH2026070702500001300_P1.jpg', '2026-07-07 06:04:23', '2026-07-07 15:37:48.358448', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2965, 'https://www.mk.co.kr/rss/50200011/', NULL, 'https://www.mk.co.kr/news/stock/12091939', '경제', '“지긋지긋한 저평가 끝낼까?”…10일 나스닥 가는 SK하이닉스, ADR 상장 승부수', '약 43조원 규모의 미국주식예탁증서(ADR) 발행을 통해 오는 10일(현지시각) 미국 나스닥 상장을 앞둔 SK하이닉스에 업계 관심이 집중되고 있다. 단순한 자금 조달을 넘어 인공지..', '사진 확대 SK하이닉스 본사.[연합뉴스] 약 43조원 규모의 미국주식예탁증서(ADR) 발행을 통해 오는 10일(현지시각) 미국 나스닥 상장을 앞둔 SK하이닉스에 업계 관심이 집중되고 있다. 단순한 자금 조달을 넘어 인공지능(AI) 반도체 시장에서 기업가치를 재평가 받을 수 있다는 기대감 때문이다. ADR은 해외 기업의 주식을 현지 예탁기관에 보관하고 미국 은행이 발행한 증서로 미국 증시에서 달러로 매매할 수 있게 만든 주식예탁증서를 뜻한다. 7일 관련 업계에 따르면, SK하이닉스는 전날 증권예탁증서(DR) 발행 결정 정정 공시를 통해 DR 발행 총액을 기존 약 45조4500억원에서 약 43조1400억원으로 정정했다. SK하이닉스는 ADR 상장을 위해 전체 발행주식의 약 2.5%인 최대 1779만주를 신주로 발행할 예정이다. 청약일과 납입일은 14일 예정이고, 신주 DR의 상장예정일은 29일이다. 계획대로 진행되면 외국 기업의 미국 증시 신규 상장 가운데 최대 규모가 될 가능성이 있다. 특히, 전직 오픈AI 연구원이 설립한 미국 헤지펀드 등 3곳이 SK하이닉스의 ADR 공모에 최대 70억달러(약 10조7000억원)어치를 인수할 수 있음을 시사했다는 외신보도가 나오기도 했다. 이날 파이낸션타임스(FT)에 따르면 이들은 미국 헤지펀드 시추에이셔널 어웨어니스(Situational Awareness), 영국 자산운용사 베일리 기포드(Baillie Gifford), 미국 벤처캐피탈 코튜(Coatue) 등 3곳이다. 이는 전체 공모 물량 43조1400억원(280억달러)의 4분의 1에 달한다. 투자자들 사이에선 기업가치 재평가 여부가 주요 관심사다. 그간 SK하이닉스는 미국의 경쟁사인 마이크론테크놀로지 대비 주가가 저평가됐다는 평가를 받았다. SK하이닉스는 한국 증시에 상장돼 해외 투자자들이 거래 시간 차이와 환전 등 사고 파는데 제약이 있다는 점이 저평가된 배경 중 하나로 꼽혔다. 최근 한화투자증권이 블룸버그 전망을 바탕으로 비교한 자료에 따르면, 글로벌 주요 반도체 기업의 12개월 선행 주가순이익비율(PER)은 TSMC 23.1배, 마이크론 11.2배, 키옥시아 10.6배로 나타났다. 반면, SK하이닉스는 6.6배 수준에 그쳤다. 해외 3사 평균과 비교하면 SK하이닉스는 약 56% 할인받고 있는 셈이다. 사진 확대 SK하이닉스 HBM.[로이터 연합뉴스] 증권정보업체 에프앤가이드 컨센서스(증권사 전망치 평균)에 따르면, SK하이닉스의 2분기 영업이익과 올해 연간 영업이익 전망치가 각각 63조원, 265조원대로 예상되고 있다. 반면, TSMC는 올해 2분기 영업이익이 약 270억달러(약 40조원), 키옥시아는 약 1조2980억엔(약 12조원)에 달할 것으로 전망된다. 마이크론은 회계연도 3분기 영업이익 약 52조원을 기록하며 사상 최대 실적을 냈다. 업계에서는 SK하이닉스의 미국 증시 상장으로 글로벌 투자자 기반이 확대되면 밸류에이션 할인 폭이 축소될 가능성이 있다고 보고 있다. 김운호 IBK투자증권 연구원은 “SK하이닉스가 미국 시장에 직접 상장함으로써 마이크론 대비 낮았던 밸류에이션을 극복하게 되면 국내 주식에 적용되는 밸류에이션도 차별화될 수 있을 것으로 기대된다”며 “국내 시장에서도 ADR 수준의 밸류에이션이 반영되면 추가 상승 여력을 확보할 수 있다”고 전망했다. 디 저우 손버그인베스트먼트매니지먼트 포트폴리오 매니저는 “이번 공모는 한국 주식시장에 접근하기 어려운 투자자를 겨냥한 것”이라며 “SK하이닉스의 나스닥 상장은 AI 메모리 사이클에 대한 직접적이고 마찰 없는 투자 기회를 제공한다”고 말했다. 다만 AI 메모리 반도체 업종이 과열됐다는 목소리도 나온다. 빅테크 기업들이 데이터센터 투자 재원을 채권과 주식시장에서 조달하는 추세가 이어지면서 메모리 업황 호조가 언제까지 지속될지에 대한 우려가 커지고 있기 때문이다. 자산관리회사 리버웰스 어드바이저스의 에드 오고먼 최고경영자(CEO)는 “투자자들은 잠재적인 투기 버블에 발을 들여놓는 위험을 감수하고 있다”고 말했다. AJ벨의 다니엘 코츠워스 시장총괄은 블룸버그 통신에 “이번 상장이 다소 늦은 것은 아닌지”라며 의구심을 보이면서 “메모리 반도체주가 최근 몇 주간 상승 모멘텀을 잃었지만, 투자자들은 SK하이닉스를 일시적 유행이 아닌 견조한 장기 성장 스토리로 볼 수도 있다”고 전했다. SK하이닉스는 이번 미국 나스닥 상장을 통해 확보한 자금을 국내 AI 메모리 생산능력 확대에 투입할 예정이다. 용인 반도체 클러스터 1기 팹 건설에 31조원, 청주 P＆T7 어드밴스드 패키징 팹에 19조원, 극자외선(EUV) 노광장비 도입에 12조원을 투자할 계획이다. 한편, 국내 반도체 투톱인 삼성전자가 올해 2분기 또 한 번 사상 최대 실적을 경신했다. 삼성전자는 이날 올해 2분기 잠정 실적을 발표하고 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록했다고 밝혔다. 전 분기 대비 각각 27.7%, 56.2% 증가했으며, 지난해 같은 기간과 비교하면 각각 129.3%, 1810.3% 늘었다. 이에 업계는 메모리 업황 강세가 예상보다 오래 이어질 것이라는 전망에 무게를 두고 있다.', 'crawl', '매일경제', '2026-07-07 08:38:07', '보수', 'ready', 'https://wimg.mk.co.kr/news/cms/202607/07/news-p.v1.20260707.65d2fbca0f2544bb841a1f71f066d161_P1.jpg', '2026-07-07 06:04:23', '2026-07-07 15:38:28.903323', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2990, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607071126001', 'https://www.khan.co.kr/article/202607071126001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '한병도 “올림픽공원 투표지 247만장 재검표·수개표 추진 적극 검토”', '한병도 더불어민주당 대표 직무대행 겸 원내대표(가운데)가 7일 국회에서 열린 원내대책회의에서 발언하고 있다. 박민규 선임기자한병도 더불어민주당 대표 직무대행 겸 원내대표는 7일 “올림픽공원 핸드볼 경기장 개표소에 남은 투표용지 재검표 추진을 적극 검토하겠다”고 말했다.한 원내대표는 이날 국회에서 열린 원내대책회의에서 “민주당은 올림픽공원 핸드볼 경기장 개표···', '사진 크게보기 한병도 더불어민주당 대표 직무대행 겸 원내대표(가운데)가 7일 국회에서 열린 원내대책회의에서 발언하고 있다. 박민규 선임기자 한병도 더불어민주당 대표 직무대행 겸 원내대표는 7일 “올림픽공원 핸드볼 경기장 개표소에 남은 투표용지 재검표 추진을 적극 검토하겠다”고 말했다. 한 원내대표는 이날 국회에서 열린 원내대책회의에서 “민주당은 올림픽공원 핸드볼 경기장 개표소에 남은 투표용지 247만장에 대한 재검표와 수개표를 여야 협의를 통해 국조특위에서 추진하는 방안을 적극 검토하겠다”고 말했다. 한 원내대표는 “중요한 것은 국민참정권 침해의 진상을 밝히고, 책임자 처벌을 통해 선거사무에 대한 국민 신뢰를 회복하는 일”이라며 “투표지 인쇄 물량 축소 과정과 의사결정 체계, 선거 당일 지휘 체계를 면밀히 점검해 사태의 실체를 규명하고 책임 소재를 명확히 밝히겠다”고 했다. 또한 “민주당은 이미 당론으로 특검법을 추진하기로 정했고, 정치적 논란을 최소화할 수 있도록 제3자 추천 방식을 제안했다”며 “그런데도 국민의힘은 정치적 유불리를 따지며 야당 단독 추천을 고집하고 있다”고 했다. 그는 “국민의힘도 국민참정권을 정쟁으로 몰아가려는 시도를 그만두고, 실체적 진실을 밝혀내는 데 힘을 모으길 바란다”고 했다. 김성회 원내대변인은 이날 기자들과 만나 “오늘 국정조사특별위원회에서 현장조사를 하는데 여야 간사 간 논의하고 위원장과 얘기할 것”이라며 “재검표하자는 것이 민주당의 입장이다. 국민의힘과 원활히 논의될 것”이라고 말했다.', 'crawl', '경향신문', '2026-07-07 11:26:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260707.92a6c650638a4d3d8c08c4e52977b807_P1.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:39:22.385789', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2991, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607071114001', 'https://www.khan.co.kr/article/202607071114001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '김민석 “이성윤 감기약 발언, 국힘서 이야기한줄…대장동 때를 보는 것 같다”', '더불어민주당 당대표 선거에 출마하는 김민석 의원이 지난 6일 국회 소통관에서 당대표 출마 선언 기자회견을 하고 있다. 연합뉴스더불어민주당 당대표 선거에 출마하는 김민석 의원이 7일 친정청래(친청)계 이성윤 의원이 지난 6일 12·3 계엄 해제 표결 불참 의혹을 제기하며 “감기약 드시고 주무셨다는데 약 성분이 무엇이냐”고 말한 데 대해 “무슨 대장동 때를 보···', '더불어민주당 당대표 선거에 출마하는 김민석 의원이 지난 6일 국회 소통관에서 당대표 출마 선언 기자회견을 하고 있다. 연합뉴스 더불어민주당 당대표 선거에 출마하는 김민석 의원이 7일 친정청래(친청)계 이성윤 의원이 지난 6일 12·3 계엄 해제 표결 불참 의혹을 제기하며 “감기약 드시고 주무셨다는데 약 성분이 무엇이냐”고 말한 데 대해 “무슨 대장동 때를 보는 것 같다”고 밝혔다. 김 의원은 이날 KBS라디오 <전격시사>에서 “이성윤 최고위원이 말씀하셨던데 저는 ‘국민의힘에서 누가 이야기하나’ 생각했다”면서 이같이 말했다. 앞서 이 의원은 지난 6일 페이스북에서 김 의원을 겨눠 “남 탓만 하고 비난하는 식의 출마 선언이 개탄스럽다”며 “윤석열 계엄 해제 국회 표결에 왜 불참했나. 감기약을 드시고 주무셨다고 하는데 그 감기약 성분이 무엇인가”라고 말했다. 이 의원은 “민주당 의원과 계엄 선포 직전에 통화했다는데, 그럼 즉시 국회로 달려와야 하지 않았나”라며 의혹을 제기했다. 김 의원은 “제가 그때 표결하는 시점에 국회 안에 있었고, 표결 직후에 본회의장에 착석했고, 그 과정도 이미 여러 자리에서 이야기했다”며 “이 의원의 어제 말씀은 일단 허위사실”이라고 말했다. 김 의원은 “허위사실에 의한 명예훼손으로 지금 시점에서 그렇게 이야기하셔서 제가 좀 걱정하고 있다. ‘저런 식으로 정치를 하면 좀 어려워질 텐데’ 이렇게 생각하고 있다”고 말했다. 김 의원은 지난 6일 CBS라디오 <박재홍의 한판승부>에서도 이 의원의 해당 발언을 두고 “명백한 허위사실인데 어떻게 검찰 출신인 분이 저런 말을 하느냐”며 사과를 요구했다. 한편 김 의원은 8·17 전당대회 당대표 선거 판세와 관련해 “저는 어떤 선거든 여론조사에 그렇게 크게 괘념하는 편은 아니다”라면서도 “흐름 자체만 보면, 호남(뿐만)이 아니라 전국적으로 민주당 지지층과 무당층에 있어서는 비교적 제가 좀 앞서가는 (여론)조사가 현재까지 나오고 있는 것 같다”고 말했다. 김 의원은 “감사한 일이고, 그만큼 당의 변화를 중하게 생각하신다고 받아들여서 더 그 방향을 잘 풀어가도록 노력하겠다”고 했다. 김 의원은 이병태 규제합리화위원회 부위원장이 지난 6일 5·18 성역 발언 논란으로 청와대의 권고에 따라 사퇴한 것과 관련해 “사퇴가 불가피했다고 본다”면서 “저도 사건 직후에 사과를 하시라고 개인적으로 전언했다”고 말했다. 그러면서 “이번 기회에 계속해서 제기돼 왔던 5·18 정신 헌법 전문 수록을 국민의힘도 이제는 결단을 해줘야 된다”며 “5·18 문제하고 선관위 문제만 투 포인트 개헌이라도 해서 정리를 해 가는 것이 정치의 도리라고 생각한다”고 말했다.', 'crawl', '경향신문', '2026-07-07 11:14:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/rcv.YNA.20260706.PYH2026070609810001301_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:39:24.573008', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2997, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607062141015', 'https://www.khan.co.kr/article/202607062141015/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '호남권 반도체 클러스터…광주 군공항에 들어선다', '이 대통령, 3대 메가 ‘속도’ 주문“보상, 협의·강제수용 동시 진행”정부가 6일 약 800조원의 기업 투자로 조성되는 호남권 반도체 클러스터를 광주 군공항 부지에 짓기로 결정했다. 이재명 대통령은 3대 메가프로젝트와 관련해 “행정 절차가 지연돼 투자 집행이 늦어지는 일이 절대로 있어선 안 된다”며 환경영향평가 기간 단축과 토지 보상 시 협의 취득·강제 수···', '이 대통령, 3대 메가 ‘속도’ 주문 “보상, 협의·강제수용 동시 진행” 정부가 6일 약 800조원의 기업 투자로 조성되는 호남권 반도체 클러스터를 광주 군공항 부지에 짓기로 결정했다. 이재명 대통령은 3대 메가프로젝트와 관련해 “행정 절차가 지연돼 투자 집행이 늦어지는 일이 절대로 있어선 안 된다”며 환경영향평가 기간 단축과 토지 보상 시 협의 취득·강제 수용 절차 동시 진행을 주문했다. 강훈식 대통령비서실장은 이날 메가프로젝트 민관합동점검회의 결과 브리핑에서 “오늘 회의에서 광주 군공항 부지에 호남권 반도체 산단을 조성하기로 결정했다”며 “정부는 관계부처 협의를 거쳐 조속히 후보지 선정 절차를 마무리하고, 산업단지 개발을 위한 후속 절차에 착수하겠다”고 밝혔다. 강 비서실장은 “기업들은 호남권 입지 후보지 중에 광주 군공항이 가장 적합한 부지라는 의견을 제시했다”며 “광주 군공항 지역은 약 250만평(826만㎡) 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있다”고 전했다. 강 실장은 광주 군공항에 대해 광주 도심과 KTX역에 인접해 있는 등 정주 여건과 도로·공항·항만 등 물류 접근성이 우수하다고 설명했다. 그는 토지 수용과 보상 절차에서도 “광주 군공항은 국유지이기 때문에 이 같은 부분에서 리스크가 많지 않다”고 밝혔다. 호남권 클러스터 조성 사업이 공식화된 뒤 해당 지역의 부동산 가격이 들썩거린 것 역시 빠른 부지 선정의 배경이 된 것으로 보인다. 용인 반도체 클러스터 조성 사업도 속도를 내기로 했다. 강 실장은 “기업들의 요청에 따라 당초 계획된 팹(제조공장) 10기 투자가 훨씬 빠른 속도로 추진될 수 있도록 토지 보상부터 전력, 용수 공급까지 전반적인 일정을 최대한 앞당기기로 했다”고 말했다. 청와대는 또 이날 열린 이 대통령 주재 민관합동점검회의를 당분간 매달 개최하기로 했다고 밝혔다. 매달 ‘메가프로젝트’ 민관합동회의…이 대통령, 용인 반도체도 ‘속도’ 주문 강 실장은 “반도체 클러스터뿐만 아니라 지역별 3대 메가프로젝트 핵심 과제 추진 상황을 하나하나 점검해 나가기로 했다”며 “특히 대통령께서 청와대에 전담기구를 두고 직접 챙기시겠다고 하신 만큼 중량감 있는 인사를 임명해 메가프로젝트 전반에 대한 과제별 진도 점검과 부처 간 이견 조정 등을 총괄하게 한다는 데 의견을 모았다”고 말했다. 앞서 이 대통령은 이날 청와대에서 메가프로젝트 민관합동점검회의를 주재하며 “오직 속도전이 중요하다”면서 메가프로젝트의 빠른 실행을 주문했다. 이 대통령은 “행정 절차가 지연돼 투자 집행이 늦어지는 일이 절대로 있어선 안 된다”며 “환경영향평가도, 필요한 일이긴 하지만 같은 지역이라면 (기존 평가) 결과를 원용하는 것이 중요하고 새로 하게 돼도 기간을 대폭 단축할 필요가 있다”고 말했다. 이 대통령은 또 “토지 취득 과정에서도 협의 취득 절차 중 버티는 알박기가 있으면 협의에 엄청나게 많은 시간을 소요하고 마지막에 가서야 비로소 강제 수용 절차를 시작하는데, 협의 취득과 강제 수용 절차를 동시에 시작하도록 하라”고 밝혔다. 이 대통령은 3대 메가프로젝트에 대한 야당 비판을 겨냥해 “최대한 협조는 못하더라도 크게 방해는 안 했으면 좋겠다”고 했다. 민형배 전남광주통합특별시장은 “정부의 신속한 결단에 감사드린다”며 “반도체 산단 실무지원단을 구성해 전력·용수 공급, 교통·물류망, 인재 양성, 정주 여건까지 한꺼번에 치밀하고 빠르게 준비하겠다”고 밝혔다.', 'crawl', '경향신문', '2026-07-06 21:41:01', '진보', 'ready', 'https://img.khan.co.kr/newsletter/c/300x200/228606/2026/3477438/83757_3477438_1783229307622425800.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:39:37.666366', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (2999, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607062130005', 'https://www.khan.co.kr/article/202607062130005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '광주 군공항은 어떻게 되나…민항기는 무안공항으로 군공항도 무안 일대 이전', '정부가 호남권 신규 반도체 산업단지 입지로 확정한 광주 군공항은 1964년 공군 기지로 조성됐다. 현재 공군 제1전투비행단과 국내선 민항기가 함께 사용하고 있으며 소유권자는 국방부다.이곳은 광주 도심에 위치해 정주 여건을 갖췄다는 평가를 받는다. 공항만 옮긴다면 이른 시간 내에 넓은 부지를 확보해 개발할 수 있다. 현재 탄약고를 이전하기 위해 확보해둔 부지···', '정부가 호남권 신규 반도체 산업단지 입지로 확정한 광주 군공항은 1964년 공군 기지로 조성됐다. 현재 공군 제1전투비행단과 국내선 민항기가 함께 사용하고 있으며 소유권자는 국방부다. 이곳은 광주 도심에 위치해 정주 여건을 갖췄다는 평가를 받는다. 공항만 옮긴다면 이른 시간 내에 넓은 부지를 확보해 개발할 수 있다. 현재 탄약고를 이전하기 위해 확보해둔 부지 24만평과 안전구역 39만평은 공항 관련 시설 등이 없어 곧바로 활용이 가능한 것으로 분석된다. 다만 공항 부지를 모두 이용하려면 군공항과 민간공항이 모두 이동해야 한다. 광주 도심이 확장하면서 지속적으로 시민들의 공항 이전 요구가 있었다. 민간공항은 무안국제공항을 지나는 호남선 KTX 2단계 사업이 완료될 경우 무안공항으로 이전하기로 합의된 상태다. 국토교통부는 2027년 12월 광주송정역에서 무안공항을 거쳐 목포까지 잇는 호남선 KTX 2단계 사업을 끝낸다는 계획이다. 군공항은 2014년 10월 광주시가 국방부에 이전을 공식 건의해 2016년 승인이 났다. 국방부는 지난 4월 무안공항 인근을 ‘예비 이전 후보지’로 정했으며 조만간 후보지로 공식 선정할 방침이다. 무안 일대가 군공항 이전 후보지로 결정되면 국방부와 전남광주통합시는 주변 지역 지원계획을 수립해 심의한다. 주민투표를 통해 이전 부지가 최종 확정되면 이곳에 새로운 군공항을 건설해 옮기게 된다. 다만 새 군공항을 완공하기까지는 아무리 일정을 앞당겨도 6~7년이 소요될 것이라는 분석이 나온다. 이 기간을 단축해 광주 군공항 부지에 반도체 공장을 지으려면 새 군공항 완공 전에 종전 부지를 먼저 활용할 수 있도록 관련법 등이 개정돼야 한다. 군사시설 보호구역과 비행안전구역 조정, 개발제한구역 해제 등도 선행돼야 할 과제다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-06 21:30:00', '진보', 'ready', 'https://img.khan.co.kr/newsletter/c/300x200/228606/2026/3477438/83757_3477438_1783229307622425800.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:39:53.804408', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3002, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607062126005', 'https://www.khan.co.kr/article/202607062126005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '선관위 예산 집행 등 감사원서 감사 착수', '수의계약 의혹·국외 출장 포함감사원이 6일 6·3 지방선거 투표용지 부족 사태와 관련해 선거관리위원회에 대한 예산 편성·집행 실태 감사에 착수했다. 감사원은 중앙선관위 및 서울·경기·부산 지역 선관위를 대상으로 이날부터 오는 24일까지 감사를 진행한다며 이같이 밝혔다. 감사원은 선관위에 대해 2022년 정기감사 이후 회계 분야 감사가 없었던 만큼 선거 관련···', '수의계약 의혹·국외 출장 포함 감사원이 6일 6·3 지방선거 투표용지 부족 사태와 관련해 선거관리위원회에 대한 예산 편성·집행 실태 감사에 착수했다. 감사원은 중앙선관위 및 서울·경기·부산 지역 선관위를 대상으로 이날부터 오는 24일까지 감사를 진행한다며 이같이 밝혔다. 감사원은 선관위에 대해 2022년 정기감사 이후 회계 분야 감사가 없었던 만큼 선거 관련 예산 집행과 주요 의혹 등을 두루 점검한다는 계획이다. 감사 중점 사항은 2개 분야 총 12개다. 선거 예산 편성·집행 분야에선 투표용지 인쇄 예산 편성·집행, 투표용지 인쇄 계약, 선거 관련 수당, 공정선거지원단 운영 및 기간제 근로자 일용 임금 집행, 선거 물품 구매·관리와 건물 임차, 재외국민 선거 관리 경비 및 수당 지급, 인건비 등 선거 경비 소요 추계, 예산 조정 관련 사항이 대상이다. 국민적 의혹 및 감사원 처분 요구 분야에선 수의계약 체결 의혹, 공무 국외 출장과 여비 집행, 업무추진비와 특근매식비 집행, 당선무효자 선거비용 반환채권 관리 등을 점검한다. 감사원은 1단계 감사가 끝나면 이를 토대로 2단계 감사(14일간)를 진행할 예정이다.', 'crawl', '경향신문', '2026-07-06 21:26:00', '진보', 'ready', 'https://img.khan.co.kr/newsletter/c/300x200/228606/2026/3477438/83757_3477438_1783229307622425800.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:40:11.329942', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3004, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607062123005', 'https://www.khan.co.kr/article/202607062123005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '이 대통령, 나토 첫 참석…‘방산 외교’ 중점', '7일부터 튀르키예서 정상회의…유럽국들과 안보 협력 확대 전망중·러·북 ‘자극’ 가능성…평화 공존 기조와 배치 안 되게 관리 필요이재명 대통령이 7일 튀르키예 앙카라에서 열리는 북대서양조약기구(나토) 정상회의 참석을 위해 출국한다. 취임 후 처음 나토 무대에 서는 이 대통령은 최대 방산시장인 나토 회원국들을 상대로 세일즈 외교를 펼칠 계획이다. 미국·유럽 중···', '7일부터 튀르키예서 정상회의…유럽국들과 안보 협력 확대 전망 중·러·북 ‘자극’ 가능성…평화 공존 기조와 배치 안 되게 관리 필요 이재명 대통령이 7일 튀르키예 앙카라에서 열리는 북대서양조약기구(나토) 정상회의 참석을 위해 출국한다. 취임 후 처음 나토 무대에 서는 이 대통령은 최대 방산시장인 나토 회원국들을 상대로 세일즈 외교를 펼칠 계획이다. 미국·유럽 중심 안보협의체인 나토 정상회의 참석이 중국·러시아·북한을 자극할 수 있어 정부의 실용외교 기조와 진영외교 사이에서 어떻게 균형을 잡을지가 관건이다. 이 대통령은 7일(현지시간) 앙카라에서 마르크 뤼터 나토 사무총장과 만나 한·나토 협력 강화 방안을 논의하는 것으로 공식 순방 일정을 시작한다. 같은 날 나토 방위산업포럼에서 ‘공동의 가치, 더욱 강한 산업 기반’을 주제로 기조연설을 한다. 이튿날에는 방산 등 경제·안보 협력 수요가 있는 국가 정상들과 양자 회담을 한다. 한국은 나토 회원국은 아니지만 일본·호주·뉴질랜드와 함께 인도·태평양 4개국(IP4) 자격으로 초청받았다. 한국 대통령의 나토 정상회의 참석은 윤석열 전 대통령에 이어 두 번째다. 청와대는 이번 순방의 핵심 목표로 방산 협력을 꼽았다. 위성락 국가안보실장은 지난 3일 브리핑에서 “세계 국방비의 55%를 차지하는 최대 방산시장인 나토 동맹국들을 상대로 방산 협력을 본격 추진한다는 의미가 있다”고 밝혔다. 러시아·우크라이나 전쟁이 장기화하면서 한국과 유럽의 방산 협력 기반도 넓어진 상황이다. 지난달 주요 7개국(G7) 정상회의에 이어 나토 정상회의까지 참석하면서 이 대통령은 미국·유럽과의 전략적 연계를 강화하고 있다. 유지훈 한국국방연구원 연구위원은 “북·러 군사 협력 심화와 글로벌 안보 환경 변화 속에서 한국과 나토 간 전략적 연계가 더욱 강화되고 있음을 보여주는 상징적 행보”라고 평가했다. 한국과 나토 간 안보 협력 범위도 재래식 무기 분야에서 드론·우주 등 미래전 핵심 기술 분야로 확대될 것으로 전망된다. 위 실장은 “이번 정상회의를 계기로 우리 군과 기업들이 나토의 드론·우주 등 혁신 분야 네트워크에 참여해 미래전 핵심 기술을 습득하고 공동 개발을 추진할 수 있는 기반을 마련할 것”이라고 말했다. 다만 나토와의 협력 확대가 한국을 유럽의 안보 문제에 더 깊이 끌어들일 수 있다는 우려도 나온다. 이수형 국가안보전략연구원 고문은 지난 2일 보고서에서 “이번 회의에서 논의될 우크라이나에 대한 재정·군수장비 지원 문제가 한국이 직면할 가장 부담스러운 도전 과제”라며 “우크라이나 지원 문제는 국제사회에 책임 있게 기여한다는 차원에서 접근하되, 한반도 평화 공존에 부담으로 작용하는 방식은 지양해야 한다”고 밝혔다. 나토 회원국들의 중국·러시아에 대한 견제 요구도 커질 수 있다. 임을출 경남대 극동문제연구소 교수는 “나토와의 협력 강화는 외교적 관점에서 중국·러시아·북한 모두를 자극할 수 있다”며 “이 대통령이 강조해온 북한과의 평화 공존 메시지와 배치되지 않도록 섬세한 관리가 필요하다”고 말했다.', 'crawl', '경향신문', '2026-07-06 21:23:00', '진보', 'ready', 'https://img.khan.co.kr/newsletter/c/300x200/228606/2026/3477438/83757_3477438_1783229307622425800.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:40:15.246746', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3007, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607061855001', 'https://www.khan.co.kr/article/202607061855001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '민형배 전남광주통합시장 “광주 군 공항, 반도체 부지로 최적”', '“공항이전통해 산단 조성 방법 있을 것”민형배 전남광주통합특별시장이 6일 오후 통합특별시 광주청사 브리핑실에서 호남권 반도체 클러스터 부지 확정 관련 브리핑을 하고 있다. 전남광주통합시 제공.정부가 6일 광주 군 공항을 반도체 산단 부지로 발표하자 민형배 전남광주통합특별시장은 “정부 결단을 환영하며 책임있게 뒷받침하겠다”고 밝혔다.민 시장은 이날 오후 기자···', '“공항이전통해 산단 조성 방법 있을 것” 민형배 전남광주통합특별시장이 6일 오후 통합특별시 광주청사 브리핑실에서 호남권 반도체 클러스터 부지 확정 관련 브리핑을 하고 있다. 전남광주통합시 제공. 정부가 6일 광주 군 공항을 반도체 산단 부지로 발표하자 민형배 전남광주통합특별시장은 “정부 결단을 환영하며 책임있게 뒷받침하겠다”고 밝혔다. 민 시장은 이날 오후 기자회견을 통해 “오늘 정부가 광주 군 공항 부지에 서남권 반도체 산단을 조성하기로 했다. 이재명 대통령과 정부의 신속하고 책임 있는 결단에 깊이 감사드린다”며 환영 입장을 밝혔다. 민 시장은 군 공항이 반도체 산단의 핵심 입지라는 점을 강조했다. 민 시장은 “호남 반도체 클러스터는 속도가 생명이다. 기업은 빠른 착공이 가능한 확실한 입지를 요청하고 있다”면서 “반도체 투자가 생산공장과 일자리로 이어지려면 가장 빠르고, 현실적이며 크게 확장할 수 있는 길을 찾아야 한다”고 밝혔다. 이어 “공항만 이전하면 광주 군 공항 부지는 반도체 공장 부지로 최적지”라면서 “넓은 땅, 빠른 조성 가능성, 확장 가능성까지 충분히 갖춘 가장 현실적인 해법”이라고 설명했다. 현재 군과 민간이 활용하고 있는 공항을 산단으로 개발하는 것에 대한 정부의 의지도 강조했다. 민 시장은 “군 공항은 국방·안보 기능과 직결돼 있으며 이전 문제도 오랫동안 지역의 숙제로 남아 있다”면서 “오늘 정부 발표는 그 어려운 실타래를 풀겠다는 국가의 의지 표명”이라고 밝혔다. 이어 “통합특별시도 ‘반도체 산단 실무 지원단’을 구성해 전력·용수 공급, 교통·물류망, 인재 양성, 정주 여건까지 한꺼번에 치밀하고 빠르게 준비하겠다”고 밝혔다. 민 시장은 “공항이 먼저 이전하지 않으면 반도체 공장 부지로 사용할 수 없다”면서도 “구체적 언급은 적절하지 않으며 관계 당국이 부지를 사용할 수 있는 방법을 준비 중인 것으로 알고 있다”고 말했다.', 'crawl', '경향신문', '2026-07-06 18:55:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260706.678c3540419a4531898bb0587366503a_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:40:21.049636', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3011, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607061727001', 'https://www.khan.co.kr/article/202607061727001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '248만평 넓은 부지·용수 등 강점···군 공항 기능이전 해결돼야', '호남반도체 산단 광주 군공항은민형배 전남광주통합특별시장이 지난 3일 ‘반도체 메가프로젝트 성공 지원’을 위해 광주 군공항을 찾아 현장점검을 하고 있다. 전남광주통합시 제공.정부가 호남권 신규 반도체 산업단지 입지로 확정한 광주군공항은 8.2&#13218;(248만평) 대규모 부지다. 전남광주통합특별시 광산구에 1964년 공군 기지로 조성됐다. 현재 공군 ···', '호남반도체 산단 광주 군공항은 민형배 전남광주통합특별시장이 지난 3일 ‘반도체 메가프로젝트 성공 지원’을 위해 광주 군공항을 찾아 현장점검을 하고 있다. 전남광주통합시 제공. 정부가 호남권 신규 반도체 산업단지 입지로 확정한 광주군공항은 8.2㎢(248만평) 대규모 부지다. 전남광주통합특별시 광산구에 1964년 공군 기지로 조성됐다. 현재 공군 제1전투비행단과 국내선 민항기가 함께 사용하는 국방부 소유 부지다. 광주공항은 평탄하고 넓은 부지가 최대 장점으로 꼽힌다. 공항부지 185만평과 탄약고 이전부지 24만평, 안전구역 등으로 39만평이 지정돼 있다. 영산강과 황룡강도 인접해 있다. 전남연구원은 2022년 “반도체 공장에서 필수적인 용수 확보가 용이하다”고 분석하기도 했다. KTX 광주송정역이 인근에 있고 고속도로 이용도 편리하다. 호남의 최대도시 광주 도심에 위치해 정주여건도 모두 갖췄다는 평가를 받는다. 공항만 이전한다면 빠른 시간내에 넓은 부지를 확보해 개발할 수 있다. 현재 탄약고를 이전하기 위해 확보해 둔 부지 24만명과 안전구역 39만평은 공항 관련 시설 등이 없어 곧바로 활용이 가능한 것으로 분석되고 있다. 그러나 공항 부지를 모두 이용하려면 군공항과 민간공항이 모두 이전해야 한다. 광주공항은 도심이 확장하면서 전투기 소음 등으로 시민들의 이전 요구가 끊이지 않았다. 민간공항은 무안국제공항을 지나는 호남선 KTX 2단계 사업이 완료될 경우 무안공항으로 이전하기로 합의된 상태다. 국토교통부는 2027년 12월 광주송정역에서 무안공항을 거쳐 목포까지 가는 호남선 KTX 2단계 사업을 완료한다는 계획이다. 군공항은 2014년 10월 광주시가 국방부에 이전을 공식 건의해 2016년 승인이 났다. 국방부는 지난 4월 무안공항 인근을 ‘예비이전 후보지’로 선정했으며 조만간 이전 후보지로 공식 선정한다는 계획이다. 무안 일대가 군공항 이전 후보지로 선정되면 국방부와 전남광주통합시는 주변 지역 지원계획을 수립해 심의한다. 주민투표를 통해 이전부지가 최종 확정되면 이곳에 새로운 군공항을 건설해 이전하게 된다. 다만 새 군공항을 완공하기까지는 아무리 일정을 앞당겨도 6∼7년이 소요될 것이라는 분석이 나온다. 이 기간을 앞당겨 광주공항 부지에 반도체 공장을 지으려면 새 군공항 완공 전 종전 부지를 먼저 활용할 수 있도록 관련법 등이 개정돼야 한다. 군사시설 보호구역과 비행안전구역 조정, 개발제한구역 해제 등도 선행돼야 한다. 호남 반도체 클러스터, 광주 군 공항 부지에 짓는다···“250만평 부지, 도심·KTX역 인접” 정부가 6일 약 800조원의 기업 투자로 조성되는 호남권 반도체 클러스터를 광주 군공항 부지에 짓기로 결정했다. 이재명 대통령은 3대 메가프로젝트와 관련해 “행정 절차가 지연돼 투자 집행이 늦어지는 일이 절대로 있어선 안 된다”며 환경영향평가 기간 단축과 토지 보상 시 협의 취득·강제 수용 절차 동시 진행을 주문했다. 강훈식 대통령비서실장은 이날 청와... https://www.khan.co.kr/article/202607061655001', 'crawl', '경향신문', '2026-07-06 17:27:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260706.8afe327bf0864fa98cc638a7acb3b04b_P1.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:40:45.166242', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3014, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607061655001', 'https://www.khan.co.kr/article/202607061655001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '호남 반도체 클러스터, 광주 군 공항 부지에 짓는다···“250만평 부지, 도심·KTX역 인접”', '강훈식 비서실장이 6일 청와대 춘추관에서 이날 오전 열린 메가프로젝트 민관합동 점검회의 결과 브리핑을 하고 있다. 연합뉴스정부가 6일 약 800조원의 기업 투자로 조성되는 호남권 반도체 클러스터를 광주 군공항 부지에 짓기로 결정했다. 이재명 대통령은 3대 메가프로젝트와 관련해 “행정 절차가 지연돼 투자 집행이 늦어지는 일이 절대로 있어선 안 된다”며 환경영···', '강훈식 비서실장이 6일 청와대 춘추관에서 이날 오전 열린 메가프로젝트 민관합동 점검회의 결과 브리핑을 하고 있다. 연합뉴스 정부가 6일 약 800조원의 기업 투자로 조성되는 호남권 반도체 클러스터를 광주 군공항 부지에 짓기로 결정했다. 이재명 대통령은 3대 메가프로젝트와 관련해 “행정 절차가 지연돼 투자 집행이 늦어지는 일이 절대로 있어선 안 된다”며 환경영향평가 기간 단축과 토지 보상 시 협의 취득·강제 수용 절차 동시 진행을 주문했다. 강훈식 대통령비서실장은 이날 청와대 춘추관에서 메가프로젝트 민관합동점검회의 결과 브리핑을 열고 “오늘 회의에서 광주 군공항 부지에 호남권 반도체 산단을 조성하기로 결정했다”며 “정부는 관계부처 협의를 거쳐 조속히 후보지 선정 절차를 마무리하고, 산업단지 개발을 위한 후속 절차에 착수하겠다”고 밝혔다. 강 비서실장은 “기업들은 호남권 입지 후보지 중에 광주 군 공항이 가장 적합한 부지라는 의견을 제시했다”며 “광주 군 공항 지역은 약 250만평(826만㎡) 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있다”고 전했다. 강 실장은 광주 군 공항에 대해 광주 도심과 KTX역에 인접해 있는 등 정주 여건과 도로·공항·항만 등 물류 접근성이 우수하다고 설명했다. 그는 토지 수용과 보상 절차에 있어서도 “광주 군 공항은 국유지이기 때문에 이 같은 부분에서 리스크가 많지 않다”고 밝혔다. 호남권 클러스터 조성 사업이 공식화된 뒤 해당 지역의 부동산 가격이 들썩거린 것 역시 빠른 부지 선정의 배경이 된 것으로 보인다. 용인 반도체 클러스터 조성 사업도 속도를 내기로 했다. 강 실장은 “기업들의 요청에 따라 당초 계획된 팹(제조 공장) 10기 투자가 훨씬 빠른 속도로 추진될 수 있도록 토지 보상부터 전력·용수 공급까지 전반적인 일정을 최대한 앞당기기로 했다”고 말했다. 청와대는 또 이날 오전 열린 이 대통령 주재 민관 합동 점검회의를 당분간 매달 개최하기로 했다고 밝혔다. 강 실장은 “반도체 클러스터뿐만 아니라 지역별 3대 메가프로젝트 핵심 과제 추진 상황을 하나하나 점검해 나가기로 했다”며 “특히 대통령께서 청와대에 전담 기구를 두고 직접 챙기시겠다고 하신 만큼 중량감 있는 인사를 임명해 메가프로젝트 전반에 대한 과제별 진도 점검과 부처 간 이견 조정 등을 총괄하게 한다는 데 의견을 모았다”고 말했다. 이재명 대통령이 6일 청와대에서 열린 메가프로젝트 민관합동 점검회의에서 발언하고 있다. 연합뉴스 앞서 이 대통령은 이날 오전 청와대에서 메가프로젝트 민관합동 점검회의를 주재하며 “오직 속도전이 중요하다”며 메가프로젝트의 빠른 실행을 주문했다. 이 대통령은 “행정절차가 지연돼 투자 집행이 늦어지는 일이 절대로 있어선 안 된다”며 “환경영향평가도, 필요한 일이긴 하지만 같은 지역이라면 (기존의 평가) 결과를 원용하는 것이 중요하고 새로 하게 돼도 기간을 대폭 단축할 필요가 있다”고 말했다. 이 대통령은 또 “토지 취득 과정에서도 협의 취득 절차 중 버티는 알박기가 있으면 협의에 엄청나게 많은 시간을 소요하고 마지막에 가서야 비로소 강제 수용 절차를 시작하는데, 협의 취득과 강제 수용 절차를 동시에 시작하도록 하라”고 밝혔다. 이 대통령은 3대 메가프로젝트에 대한 야당 비판을 겨냥해 “최대한 협조는 못하더라도 크게 방해는 안 했으면 좋겠다”고 했다. 이 대통령은 “‘왜 우리는 빠졌냐’고 항의를 하더니 같은 입으로 ‘사기다, 불가능한 일이다, 이벤트다’ 주장을 한다”며 “가능하다는 전제로 실제 상황이라는 전제로 균형을 주장하다가, 불가능한 걸 전제로 ‘기만이다, 이벤트다’ 이렇게 주장을 하는 게 나라 살림을 맡은 공인들이 과연 이런 태도를 취하는 게 맞는가”라고 말했다.', 'crawl', '경향신문', '2026-07-06 16:55:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260706.PYH2026070609670001300_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:41:02.437378', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3015, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607061615001', 'https://www.khan.co.kr/article/202607061615001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '방산 강조한 실용 외교 vs 중·러와 대립하는 진영 외교 사이…이 대통령, 취임 후 첫 나토행', '주요 7개국(G7) 정상회의 일정을 마친 이재명 대통령과 김혜경 여사가 지난달 18일 경기 성남 서울공항에 도착해 공군 1호기에서 내리고 있다. 청와대사진기자단이재명 대통령이 오는 7일 튀르키예 앙카라에서 열리는 북대서양조약기구(나토) 정상회의 참석을 위해 출국한다. 취임 후 처음으로 나토 무대에 서는 이 대통령은 최대 방산시장인 나토 회원국들을 상대로 방···', '주요 7개국(G7) 정상회의 일정을 마친 이재명 대통령과 김혜경 여사가 지난달 18일 경기 성남 서울공항에 도착해 공군 1호기에서 내리고 있다. 청와대사진기자단 이재명 대통령이 오는 7일 튀르키예 앙카라에서 열리는 북대서양조약기구(나토) 정상회의 참석을 위해 출국한다. 취임 후 처음으로 나토 무대에 서는 이 대통령은 최대 방산시장인 나토 회원국들을 상대로 방산 세일즈 외교를 펼칠 계획이다. 미국·유럽 중심 안보협의체인 나토 정상회의 참석이 중국·러시아·북한을 자극할 수 있어 정부의 실용외교 기조와 진영 외교 사이에서 어떻게 균형을 잡을지가 관건으로 보인다. 이 대통령은 오는 7일(현지시간) 앙카라에서 마르크 뤼터 나토 사무총장과 만나 한·나토 협력 강화 방안을 논의하는 것으로 공식 순방 일정을 시작한다. 같은 날 나토 방위산업포럼에서 ‘공동의 가치, 더욱 강한 산업 기반’을 주제로 기조연설을 한다. 이튿날에는 방산 등 경제·안보 협력 수요가 있는 국가 정상들과 잇달아 양자 회담을 한다. 한국은 나토 회원국은 아니지만 일본·호주·뉴질랜드와 함께 인도·태평양 4개국(IP4) 자격으로 초청받았다. 한국 대통령의 나토 정상회의 참석은 윤석열 전 대통령에 이어 두 번째다. 이 대통령은 지난해에도 초청받았지만 참석하지 않고 위성락 국가안보실장을 보냈다. 청와대는 이번 순방의 핵심 목표로 방산 협력을 꼽았다. 위 실장은 지난 3일 브리핑에서 “세계 국방비의 55%를 차지하는 최대 방산시장인 나토 동맹국들을 상대로 방산 협력을 본격 추진한다는 의미가 있다”고 밝혔다. 러시아·우크라이나 전쟁이 장기화하면서 한국과 유럽의 방산 협력 기반도 넓어진 상황이다. 도널드 트럼프 미국 대통령은 이번 정상회의에서 동맹국들의 국내총생산(GDP) 대비 5% 국방비 증액 약속 이행 상황을 점검할 것으로 알려졌다. 지난달 주요 7개국(G7) 정상회의에 이어 나토 정상회의까지 참석하면서 이 대통령은 미국·유럽과의 전략적 연계를 강화하고 있다. 유지훈 한국국방연구원 연구위원은 “북·러 군사 협력 심화와 글로벌 안보 환경 변화 속에서 한국과 나토 간 전략적 연계가 더욱 강화되고 있음을 보여주는 상징적 행보”라고 평가했다. 한국과 나토 간 안보 협력 범위도 전통적인 재래식 무기 분야에서 드론·우주 등 미래전 핵심기술 분야로 확대될 전망이다. 위 실장은 “우크라이나 전장에서 드론, 인공지능(AI) 등 첨단기술의 전략적인 중요성이 입증되면서 나토는 이를 전장에 적용하기 위한 혁신 생태계 구축에 힘쓰고 있다”며 “이번 정상회의를 계기로 우리 군과 기업들이 나토의 드론·우주 등 혁신 분야 네트워크에 참여해 미래전 핵심기술을 습득하고 공동 개발을 추진할 수 있는 기반을 마련할 것”이라고 말했다. 다만 나토와의 협력 확대가 한국을 유럽의 안보 문제에 더 깊이 끌어들일 수 있다는 우려도 나온다. 이수형 국가안보전략연구원 고문은 지난 2일 보고서에서 “이번 회의에서 논의될 우크라이나에 대한 재정·군수 장비 지원 문제가 한국이 직면할 가장 부담스러운 도전 과제”라며 “우크라이나 지원 문제는 국제사회에 책임 있게 기여한다는 차원에서 접근하되, 한반도 평화 공존에 부담으로 작용하는 방식은 지양해야 한다”고 밝혔다. 나토 회원국들의 중국·러시아에 대한 견제 요구도 커질 수 있다. 임을출 경남대 극동문제연구소 교수는 “나토와의 협력 강화는 외교적 관점에서 중국·러시아·북한 모두를 자극할 수 있다”며 “이 대통령이 강조해온 북한과의 평화 공존 메시지와 배치되지 않도록 섬세한 관리가 필요하다”고 말했다.', 'crawl', '경향신문', '2026-07-06 16:15:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.PHOTOPOOL.20260618.kpa17817527015936_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:41:04.3089', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3019, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607061409001', 'https://www.khan.co.kr/article/202607061409001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '[속보] 청와대 “광주 군공항 250만평 부지에 호남권 반도체 산단 조성”', '이재명 대통령이 6일 오전 청와대에서 열린 메가프로젝트 민관합동 점검회의에 발언하고 있다. 20260706 청와대사진기자단정부가 6일 광주 군공항 부지를 서남권 반도체 클러스터 산업단지 입지 후보지로 결정했다.강훈식 대통령비서실장은 이날 청와대에서 메가프로젝트 민관합동 점검회의 결과 브리핑을 열고 “정부는 관계부처 협의를 거쳐 조속히 후보지 선정 절차를 마···', '이재명 대통령이 6일 오전 청와대에서 열린 메가프로젝트 민관합동 점검회의에 발언하고 있다. 20260706 청와대사진기자단 정부가 6일 광주 군공항 부지를 서남권 반도체 클러스터 산업단지 입지 후보지로 결정했다. 강훈식 대통령비서실장은 이날 청와대에서 메가프로젝트 민관합동 점검회의 결과 브리핑을 열고 “정부는 관계부처 협의를 거쳐 조속히 후보지 선정 절차를 마무리할 것”이라며 이같이 전했다. 강 비서실장은 “기업들은 호남권 입지 후보지 가운데 광주 군공항이 가장 적합한 부지라는 의견을 제시했다”며 “광주 군 공항 지역의 경우 약 250만평 규모의 부지를 확보할 수 있으며 공항의 특성상 이미 평탄화가 완료된 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있다”고 했다. 강 실장은 “광주 도심과 KTX 역도 인접해 있어 인력 확보와 정주 여건 측면에서도 강점이 있고, 도로·공항·항만 등과 연계한 물류 접근성도 우수한 것으로 검토됐다”고 설명했다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-06 14:09:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260706.664b3fae73044470b1a9d9478484ace4_P1.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:41:29.106856', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3028, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607060900001', 'https://www.khan.co.kr/article/202607060900001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '감사원, 선관위 예산 감사 착수…편성·집행 실태 살핀다 “국민 의혹 점검”', '김호철 감사원장이 지난 6월24일 서울 종로구 감사원에서 열린 기자간담회에서 발언하고 있다. 연합뉴스감사원이 6일 6·3 지방선거 투표용지 부족 사태와 관련해 선거관리위원회에 대한 예산 편성·집행 실태 감사에 착수했다.감사원은 중앙선관위 및 서울·경기·부산 지역 선관위를 대상으로 이날부터 오는 24일까지 감사를 진행한다며 이같이 밝혔다. 감사반은 행정·안전···', '김호철 감사원장이 지난 6월24일 서울 종로구 감사원에서 열린 기자간담회에서 발언하고 있다. 연합뉴스 감사원이 6일 6·3 지방선거 투표용지 부족 사태와 관련해 선거관리위원회에 대한 예산 편성·집행 실태 감사에 착수했다. 감사원은 중앙선관위 및 서울·경기·부산 지역 선관위를 대상으로 이날부터 오는 24일까지 감사를 진행한다며 이같이 밝혔다. 감사반은 행정·안전감사국장을 단장으로 총 42명으로 꾸려졌다. 감사원은 선관위에 대해 2022년 정기감사 이후 회계 분야 감사가 없었던 만큼 선거 관련 예산 집행과 주요 의혹 등을 두루 점검한다는 계획이다. 감사 중점 사항은 2개 분야 총 12개다. 선거 예산 편성·집행 분야에선 투표용지 인쇄 예산 편성·집행, 투표용지 인쇄 계약, 선거 관련 수당, 공정선거지원단 운영 및 기간제 근로자 일용 임금 집행, 선거 물품 구매·관리와 건물 임차, 재외국민 선거 관리 경비 및 수당 지급, 인건비 등 선거 경비소요 추계, 예산 조정 관련 사항이 대상이다. 국민적 의혹 및 감사원 처분 요구 분야에선 수의계약 체결 의혹, 공무 국외 출장과 여비 집행, 업무추진비와 특근매식비 집행, 당선무효자 선거비용 반환채권 관리 등을 점검한다. 감사원은 1단계 감사가 끝나면 이를 토대로 2단계 감사(14일간)를 진행할 예정이다. 앞서 감사원은 지난달 24일 선관위 회계 감사 방침을 세우고 30명가량을 투입해 자료수집을 진행해왔다. 헌법기관인 선관위는 직무감찰 대상이 될 수 없다는 지난해 헌법재판소의 결정에 따라 회계검사라는 우회로를 통해 투표용지 부족 사태의 문제점을 들여다보겠다는 취지다.', 'crawl', '경향신문', '2026-07-06 09:00:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260624.PYH2026062411260001300_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:41:56.764599', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3034, 'https://www.khan.co.kr/rss/rssdata/politic_news.xml', 'https://www.khan.co.kr/article/202607052141005', 'https://www.khan.co.kr/article/202607052141005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=politic_news', '정치', '“미래대응기금, 반도체 추가 세수로 신설”', '강훈식, 당정협의회서 추진 밝혀“양극화·청년 문제 대응에 투입”청와대와 정부, 더불어민주당이 반도체 추가세수를 활용한 미래대응기금을 신설하기로 했다. 당·정·청은 여당 내 기구를 만들어 세부 내용을 논의하고, 기금을 3대 메가프로젝트 지원과 양극화 대응 등에 사용하기로 합의했다. 올해 기금 재원 조달을 위해선 연내에 추가경정예산 편성이 필요할 것이란 전망이···', '강훈식, 당정협의회서 추진 밝혀 “양극화·청년 문제 대응에 투입” 청와대와 정부, 더불어민주당이 반도체 추가세수를 활용한 미래대응기금을 신설하기로 했다. 당·정·청은 여당 내 기구를 만들어 세부 내용을 논의하고, 기금을 3대 메가프로젝트 지원과 양극화 대응 등에 사용하기로 합의했다. 올해 기금 재원 조달을 위해선 연내에 추가경정예산 편성이 필요할 것이란 전망이 나온다. 강훈식 대통령비서실장은 5일 서울 종로구 총리공관에서 열린 고위당정협의회 모두발언에서 “이재명 정부는 추가세수를 미래세대를 위한 투자 재원으로 활용하기 위해 미래대응기금 신설을 추진하고자 한다”고 밝혔다. 강 비서실장은 “대한민국의 미래를 좌우할 절체절명의 시기에 반도체 호황 등으로 발생한 추가세수를 허투루 써서는 안 될 것”이라며 “추가세수로 기금을 조성해 3대 메가프로젝트 지원을 포함한 미래 성장동력 창출, K자형 양극화 대응, 2030 청년을 위한 주거·창업·일자리 지원 등 대한민국의 미래에 과감한 투자를 하고자 한다”고 말했다. 강준현 민주당 수석대변인은 회의 후 국회에서 브리핑을 열고 “당·정·청은 미래대응기금 신설 추진을 논의했고 추가세수를 미래세대와 대한민국 성장동력, 양극화 대응 등에 사용하겠다는 정부의 입장에 공감했다”고 밝혔다. 강 수석대변인은 “미래대응기금 관련해선 오늘 정부에서 목적과 방향성에 대해서만 말씀하신 것이고, 세부 내용과 관련해선 나중에 당·정·청이 당에서 논의할 수 있는 기구를 만들어 할 계획을 가지고 있다”고 말했다. 초과세수 올해 기금 출연하려면 ‘가을 추경’ 불가피 국가재정법에 우선 사용처 명기 예산처, 법률 제정 등 후속 작업 당·정·청이 미래대응기금 신설 방침을 공식화함에 따라 소관 부처인 기획예산처는 기금 설치를 위한 후속 작업에 착수할 것으로 전망된다. 우선 관계 부처와 협의를 거쳐 가칭 ‘미래대응기금 설치 및 운용에 관한 법률’ 제정안을 마련하고, 기금을 국가의 공식 재정 운용 체계에 편입하기 위한 법적 근거를 마련하게 된다. 기금을 국가재정법상 법정 기금으로 운영하기 위해 국가재정법 개정도 함께 추진될 가능성이 크다. 법안에는 기금의 재원 조달 방식과 운용 원칙, 지원 대상 등이 담길 것으로 보인다. 최대 과제는 재원 조달이다. 강 비서실장은 반도체 호황 등에 따른 추가세수를 기금 재원으로 활용하겠다고 밝혔지만, 현행 국가재정법상 초과세수는 지방교부세·지방교육재정교부금 정산과 공적자금·국가채무 상환 등 법정 지출에 우선 사용해야 한다. 남는 재원을 올해 기금에 출연하려면 추경을 편성해야 하는 만큼 올가을 추경이 불가피할 것이라는 전망이 나온다. 당·정·청은 3대 메가프로젝트의 후속 조치도 논의했다. 한병도 민주당 대표 직무대행 겸 원내대표는 “민주당은 3대 메가프로젝트 지원 TF를 중심으로 필요한 입법과 예산을 촘촘하게 지원하도록 하겠다”며 “특히 TF도 위원회로 격상하는 문제를 검토해 당대표나 원내대표가 직접 위원장을 맡아 일을 속도감 있게 추진하는 방안도 검토하겠다”고 밝혔다. 한성숙 국무총리는 “3대 메가프로젝트는 반도체·AI 데이터센터·피지컬 AI를 하나의 큰 그림으로 연결해 향후 3년의 국가 경쟁력을 구성하는 굉장히 도전적인 과제”라며 “과거 고속도로, 초고속통신망이 우리 경제의 비약적 발전을 이끈 것처럼, 이제 3대 메가프로젝트를 속도감 있게 실행하면 대한민국의 새로운 성장 시대를 열어갈 수 있을 것”이라고 말했다.', 'crawl', '경향신문', '2026-07-05 21:41:00', '진보', 'ready', 'https://img.khan.co.kr/newsletter/c/300x200/228606/2026/3477438/83757_3477438_1783229307622425800.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:42:19.525797', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3045, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607071200021', 'https://www.khan.co.kr/article/202607071200021/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', '‘가장 비싼 담합’ 된 전분 담합···가담 4개사, 공정위 역대 최고 과징금 ‘7476억’ 철퇴', '공정위, 대상·사조·삼양·CJ에 담합 중 최고액 부과지난 5월 밀가루 담합 7개사 6710억원 뛰어넘어10조 원대 전분당 담합 의혹을 받는 대상 임정배 대표가 지난 4월14일 서울 서초구 서울중앙지방법원에서 열린 영장실질심사에 출석하고 있다. 사진공동취재단물엿·올리고당 등 원료인 전분당과 녹말 기초 소재인 전분 등 가격을 짬짜미한 4개 제조사에 7476억원···', '공정위, 대상·사조·삼양·CJ에 담합 중 최고액 부과 지난 5월 밀가루 담합 7개사 6710억원 뛰어넘어 남동일 공정거래위원회 부위원장이 7일 세종시 정부세종청사에서 전분 및 전분당 가격담합 사건 심의 결과에 대해 브리핑하고 있다. 연합뉴스 물엿·올리고당 등 원료인 전분당과 녹말 기초 소재인 전분 등의 가격을 짬짜미한 4개 제조사에 총 7000억원대의 과징금이 부과됐다. 공정거래위원회 담합 사건 중 역대 최고 금액이다. 공정위는 7일 대상, 사조CPK, 삼양사, CJ제일제당 등 4개사의 전분·전분당 판매 가격 담합 행위를 적발해 총 7475억7800만원의 과징금을 부과하기로 했다고 밝혔다. 이와 함께 제품 가격을 담합 이전 수준으로 되돌리도록 하는 ‘독자적 가격 재결정 명령’도 내렸다. 전분당은 제과, 제면, 맥주 등 다양한 제품에서 사용하는 핵심 원료다. 옥수수, 감자 등으로 만드는 전분 역시 튀김가루, 빵류, 골판지, 건축자재 등 폭넓은 분야에 활용된다. 이번 과징금은 지난 5월 밀가루 가격 담합으로 7개 업체에 부과된 6710억원을 넘어선 것으로, 공정위 담합 제재 사상 최대 금액이다. 이재명 대통령이 지난 2월 담합 기업을 “암적 존재”로 표현하며 담합 이득을 넘어선 무거운 제재를 주문한 뒤, 공정위가 설탕, 밀가루, 인쇄용지에 이어 전분·전분당까지 민생에 직결된 제품의 담합에 연달아 철퇴를 내리는 모습이다. 공정위 조사에 따르면 이들 4개사는 2018년 5월부터 2024년 10월까지 7년 5개월간 총 13차례에 걸쳐 사업자 간 거래(B2B) 판매가격을 사전에 논의한 것으로 나타났다. 특히 2022년 러시아·우크라이나 전쟁으로 국제 곡물 가격이 급등한 시기에도 가격을 공동으로 인상하며 부당이익을 극대화한 것으로 공정위는 판단했다. 이들은 원재료인 옥수수의 국제 가격이 하락할 때도 제품 가격 인하 시점을 최대한 늦추기로 합의했다. 환율과 원가 변동 등 가격 조정 근거를 담은 공문 내용과 거래처 발송 시기까지 사전에 조율하는 등 치밀하게 담합을 이어간 것으로 조사됐다. 정부는 물가 안정과 산업 경쟁력 유지를 위해 매년 약 200만t 규모의 수입 옥수수에 대해 0% 할당 관세(특정 물품에 대해 일정 수량 관세율을 낮춰주는 것)를 적용해왔지만, 이들 기업은 해당 혜택을 활용하면서도 가격 담합을 지속한 것으로 드러났다. 이들 기업은 옥수수를 공동 수입해 담합을 더 수월하게 할 수 있었다. 4개 업체는 또 목표 가격을 설정해 입찰 ‘몰아주기’를 한 것으로 조사됐다. 예를 들어 A사가 거래처에 730원으로 가격을 제시하면 나머지 세 업체는 735∼740원에 제품을 팔겠다고 하면서 거래처가 A사 가격을 수용하도록 유도하는 방식이다. 이 같은 담합 결과 2022년 전분당 가격은 4년 전보다 73% 상승했다. 공정위는 이를 통해 4개사가 약 6조525억원의 매출을 낸 것으로 추산했다. 이들의 시장 점유율은 전분 95.7%, 전분당 86.4%에 달한다. 공정위는 이날 4개사를 대상으로 ‘입찰 및 부산물 가격 담합’ 혐의에 대해서도 별도의 심의 절차를 개시했다고 밝혔다. 이는 검찰의 기소에 해당하는 절차로, 전원회의를 통해 추가 제재 여부와 수위가 결정될 예정이다. 이들 기업은 2016년 9월부터 약 8년 9개월간 전분당 구매 입찰 과정에서 낙찰 예정자, 입찰 가격, 입찰 물량 등을 사전에 합의한 것으로 조사됐다. 공정위는 이 같은 행위를 통해 이들 기업이 총 9400억원의 매출을 낸 것으로 집계했다. CJ제일제당을 뺀 나머지 3개 업체는 2017년부터 8년 2개월간 단백피와 글루텐 등 전분당에서 나오는 부산물 판매 가격도 미리 정한 것으로 드러났다. 공정위가 추산한 관련 매출액은 1조5500억원이다. 검찰도 전분·전분당 업체에 대한 수사에 착수, 지난 4월 대상·사조CPK·CJ제일제당 등 3개사 대표이사 등 관련자 총 25명을 기소했다. 수사에 협조한 삼양사 측 관계자는 기소 대상에 포함되지 않은 것으로 전해졌다.', 'crawl', '경향신문', '2026-07-07 12:00:02', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/rcv.YNA.20260707.PYH2026070705490001300_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:42:48.338062', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3046, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607071200001', 'https://www.khan.co.kr/article/202607071200001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', '명의만 넘기고 ‘1주택 비과세···국세청, 부동산 탈세 318억원 추징', '세무조사 추징사례. 자료: 국세청 제공 그래픽을 생성형 AI 제미나이로 화질 개선서울에 고가 아파트와 저가 아파트를 각각 보유한 A씨는 양도차익이 큰 고가 아파트를 팔기 전 저가 아파트를 모친의 지인 명의로 넘겼다. 형식상 1주택자가 된 뒤 고가 아파트를 처분하면서 1세대 1주택 비과세 혜택을 적용받기 위해서였다.그러나 국세청 조사 결과 A씨는 지인의 취득···', '세무조사 추징사례. 자료: 국세청 제공 그래픽을 생성형 AI 제미나이로 화질 개선 서울에 고가 아파트와 저가 아파트를 각각 보유한 A씨는 양도차익이 큰 고가 아파트를 팔기 전 저가 아파트를 모친의 지인 명의로 넘겼다. 형식상 1주택자가 된 뒤 고가 아파트를 처분하면서 1세대 1주택 비과세 혜택을 적용받기 위해서였다. 그러나 국세청 조사 결과 A씨는 지인의 취득세와 재산세를 대신 내줬고, 명의를 넘긴 뒤에도 해당 아파트에 계속 거주한 것으로 드러났다. 명의를 돌려받을 때까지 탈세에 협조한 대가로 지인에게 매달 사례금까지 지급한 사실도 확인됐다. 국세청은 이 거래를 명의만 옮긴 가장매매로 판단해 비과세 적용을 배제하고 다주택자 중과세율을 적용, 약 10억원의 양도소득세를 추징했다. A씨와 거래를 주도한 모친, 명의를 빌려준 지인은 조세포탈 혐의로 검찰에 고발했다 국세청은 7일 초고가 주택 거래 등 부동산 탈세 혐의자 104명에 대한 동시 세무조사 결과, 현재까지 총 318억원의 세금을 추징했다고 밝혔다. 이들의 탈루 혐의 금액은 731억원에 달했다. 조사 결과 부모로부터 증여받은 자금을 신고하지 않은 채 고가 아파트를 매입해 증여세를 탈루한 사례가 확인됐다. 다주택자가 친척이나 지인에게 저가 주택의 명의만 허위로 이전한 뒤 양도차익이 큰 고가 주택을 처분하면서 1세대 1주택 비과세를 부당하게 적용받거나 다주택자 중과세율을 피한 가장매매 사례도 다수 적발됐다. 국세청은 조사 과정에서 사기나 그 밖의 부정한 방법으로 조세를 포탈한 사실이 확인된 경우에는 40%의 부당 과소신고 가산세를 부과했다. 아울러 조사 대상자뿐 아니라 탈세에 가담한 것으로 확인된 관련자 6명은 검찰에 고발했으며, 4명에게는 총 7억원의 벌금 상당액을 통고처분했다. 통고처분은 조세범에게 일정 금액의 납부를 통지하고 이를 이행하면 공소를 제기하지 않는 제도다. 명의신탁 등 부동산실명법 위반 사실이 확인된 20명에 대해서는 과징금 부과와 형사처벌 등 후속 조치가 이뤄질 수 있도록 관할 지방자치단체에 통보했다. 국세청은 이재명 정부 출범 이후 시장 과열 지역에 대한 감시와 세무 검증을 강화해왔다. 30억원 이상 초고가 주택 거래는 전수 검증했고, 30대 이하와 외국인 등의 자금출처에 대해서도 집중적으로 점검했다. 이와 함께 강남 4구와 마포·용산·성동구 아파트 증여거래 2077건도 들여다봤다. 최근에는 현금 자산가, 고액 사적 차입으로 주택을 취득한 사람, 투기 목적 다주택자 등 탈세 혐의자 127명에 대해서도 추가 세무조사에 착수했다. 오상훈 국세청 자산과세국장은 “다주택자 중과세가 재개되면서 증여 거래가 늘어날 가능성이 있는 만큼 다주택자의 증여 거래를 중심으로 증여재산을 저가 평가하거나 증여세를 대신 납부하는 등 편법 증여 여부를 점검하겠다”고 밝혔다.', 'crawl', '경향신문', '2026-07-07 12:00:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260707.42db5f177eb94ee6a9fcf06d8ee8533d_P1.png', '2026-07-07 06:04:24', '2026-07-07 15:42:50.995384', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3055, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607070911001', 'https://www.khan.co.kr/article/202607070911001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', '삼성전자, ‘어닝 서프라이즈’에도 주가 4% 하락', '서울 삼성전자 서초사옥. 문재원 기자삼성전자가 7일 시장 예상을 뛰어넘는 ‘어닝 서프라이즈’를 기록했지만 주가는 하락세를 보이고 있다.삼성전자는 이날 오전 9시 7분 현재 전장 대비 1만4500원(4.56%) 내린 30만3500원을 기록 중이다.삼성전자는 이날 프리마켓에서도 약세를 보였다.같은 반도체 대형주인 SK하이닉스도 같은 시간 3만6000원(1.54···', '서울 삼성전자 서초사옥. 문재원 기자 삼성전자가 7일 시장 예상을 뛰어넘는 ‘어닝 서프라이즈’를 기록했지만 주가는 하락세를 보이고 있다. 삼성전자는 이날 오전 9시 7분 현재 전장 대비 1만4500원(4.56%) 내린 30만3500원을 기록 중이다. 삼성전자는 이날 프리마켓에서도 약세를 보였다. 같은 반도체 대형주인 SK하이닉스도 같은 시간 3만6000원(1.54%) 내린 230만7000원에 하락 거래 중이다. 시장에서는 삼성전자의 주가가 단기간 급등한 데다 실적이 주가에 선반영돼 차익실현 물량이 나온 점을 배경으로 지목한다. 삼성전자는 이날 연결 기준 올해 2분기 영업이익이 89조4000억원으로 지난해 동기보다 1810.3% 증가한 것으로 잠정 집계됐다고 공시했다. 매출은 171조원으로 작년 동기 대비 129.3% 증가했다.', 'crawl', '경향신문', '2026-07-07 09:11:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260701.610359e61a4341949f357f9696d99835_P1.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:43:18.06731', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3062, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607062136005', 'https://www.khan.co.kr/article/202607062136005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', '투기자본 ‘무책임’에 온라인 전환 실패 덮쳐…30년 대형마트의 ‘몰락’', 'MBK, 인수 후 핵심 점포 대거 매각…팬데믹 등 유통 시장 변화 대응 못해홈플러스 노동자들이 2021년 5월13일 서울 종로구 MBK 본사 앞에서 폐점 중단과 고용안정을 촉구하며 삭발을 하고 있다. 강윤중 선임기자홈플러스가 지난 3일 법원의 기업회생절차 폐지 결정으로 창사 30년 만에 파산위기까지 왔다. 유통업계에선 사모펀드(PEF) 운용사 MBK파트너스···', 'MBK, 인수 후 핵심 점포 대거 매각…팬데믹 등 유통 시장 변화 대응 못해 홈플러스 노동자들이 2021년 5월13일 서울 종로구 MBK 본사 앞에서 폐점 중단과 고용안정을 촉구하며 삭발을 하고 있다. 강윤중 선임기자 홈플러스가 지난 3일 법원의 기업회생절차 폐지 결정으로 창사 30년 만에 파산위기까지 왔다. 유통업계에선 사모펀드(PEF) 운용사 MBK파트너스의 무리한 차입 경영에다 코로나19 팬데믹 시기 온라인으로 급속히 주도권이 넘어간 환경 변화에 대응하지 못한 것이 경영이 악화된 결정적 원인이라고 지목한다. 6일 취재를 종합하면, 홈플러스는 1997년 삼성물산 유통부문이 대구에 1호점을 열면서 시작했다. 외환위기 이후인 1999년 영국 유통업체 테스코가 경영권을 인수했고, 같은 해 삼성물산과 테스코의 합작법인이 설립됐다. 2008년엔 이랜드그룹의 홈에버까지 인수하는 등 공격적으로 사업을 확장했다. 2011년 홈플러스 지분 100%를 확보한 테스코는 2015년 MBK 컨소시엄에 팔았다. 매각 무렵 홈플러스는 대형마트 140여개, 슈퍼마켓 370여개, 편의점 320여개 등을 운영해 업계 1위 이마트에 비견되는 2위였다. MBK의 인수대금은 약 7조2000억원이었다. MBK는 이 가운데 최소 2조7000억원을 인수금융 방식으로 마련했다. MBK는 인수 직후 2년간 1조원을 투자하겠다고 밝혔다. 하지만 MBK는 경쟁력 강화를 위한 투자보다는 차입금을 메꾸기 위한 자산 유동화에 집중했다. MBK는 홈플러스 인수 이듬해인 2016년 핵심 점포 5곳을 매각해 6440억원을 확보한 것을 시작으로 2024년까지 점포와 물류창고 총 28곳을 팔아 4조1149억원을 확보했다. 이 같은 방식은 홈플러스의 경쟁력을 갉아먹었다. 홈플러스는 매각 점포 일부를 임차하는 세일 앤드 리스백 방식으로 영업을 지속했다. 이로 인해 임차료 부담이 늘면서 2023년 한 해 리스부채 관련 현금유출액은 4516억원에 달했다. 앞서 한국신용평가는 홈플러스의 상각전영업이익(EBITDA)이 2019년 7351억원에서 2023년 3214억원으로 절반 넘게 감소한 반면, 연간 6000억원 수준의 임차료와 이자비용 부담을 감당하기에는 현금창출력이 크게 부족하다고 평가했다. EBITDA는 기업의 현금창출력을 보여주는 지표다. 2020년 발생한 코로나19 팬데믹은 MBK 인수 이후 허약해진 홈플러스가 고꾸라지는 결정적 계기가 됐다. 코로나19로 유통업계 주류가 온라인으로 넘어가는 흐름이 가속화했다. 산업통상부 주요 유통업체 매출동향을 보면, 2021~2025년 온라인은 연평균 10.1% 성장한 반면 대형마트는 연평균 4.2% 감소했다. 신규 투자 여력이 없던 홈플러스는 오프라인 매장을 유지하는 데 급급했다. 한 유통업계 관계자는 “홈플러스가 코로나19 사태 때 온라인 전환에 대응하지 못한 게 파산위기로 이어졌다고 본다”고 말했다. MBK가 인수하기 직전인 2014년 홈플러스는 매출 7조526억원, 영업이익 1944억원을 올렸다. 홈플러스는 코로나19 팬데믹 직전인 2019년엔 매출 7조3002억원, 영업이익 1602억원으로 수년째 사실상 제자리걸음을 하다 2021년부터 지난해까지 5년 연속 적자를 기록했다. 지난해 매출은 5조7963억원, 영업손실은 5464억원이었다. 2021~2025년 누적 당기순손실이 2조7341억원에 달했다. 업계에선 정부의 대형마트 중심 규제가 홈플러스 몰락의 한 원인이란 지적도 나온다. 이미 유통시장 주도권이 온라인으로 넘어간 지 오래인데도 2012년 유통산업발전법 개정 이후 현재까지 대형마트 영업시간 제한, 의무휴업, 출점 규제 등이 유지되고 있어 홈플러스가 반등을 모색할 기회조차 없었다는 것이다. 유통업계 다른 관계자는 “규제가 시장 변화를 따라가지 못했다”며 “홈플러스 사태가 남의 일 같지 않다”고 말했다. 다만 이마트와 롯데마트가 신선식품 등을 중심으로 자체 경쟁력을 유지하고 있는 점을 볼 때 정부 규제만으로는 홈플러스가 지금과 같은 상황에 처한 이유를 설명하지는 못한다는 반론도 뒤따른다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-06 21:36:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000188600017081.jpg', '2026-07-07 06:04:24', '2026-07-07 15:43:37.171975', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3063, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607062130015', 'https://www.khan.co.kr/article/202607062130015/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', '착공까지 6년 걸린 용인…정부, ‘호남 임기 내 완공’ 강한 의지', '‘광주 군공항’ 빠른 선정 배경이곳에 ‘반도체 산단’ 들어섭니다 정부가 6일 호남권 반도체 산업단지 부지로 발표한 광주 군공항의 지난달 30일 모습. 청와대사진기자단‘메가’ 발표 일주일 만에 결정…부동산 투기 사전 차단 목적도 커 대부분 국유지·평탄한 820만㎡…보상 부담 적고 공기 단축 장점 영산강·황룡강 끼고 도심·KTX역 인접…교통·용수 확보도···', '‘광주 군공항’ 빠른 선정 배경 이곳에 ‘반도체 산단’ 들어섭니다 정부가 6일 호남권 반도체 산업단지 부지로 발표한 광주 군공항의 지난달 30일 모습. 청와대사진기자단 ‘메가’ 발표 일주일 만에 결정…부동산 투기 사전 차단 목적도 커 대부분 국유지·평탄한 820만㎡…보상 부담 적고 공기 단축 장점 영산강·황룡강 끼고 도심·KTX역 인접…교통·용수 확보도 용이 정부가 호남권 반도체 클러스터 투자 계획을 발표한 지 일주일 만인 6일 광주 군공항을 후보지로 결정한 것은 입지 조건은 물론이고, ‘임기 내 완공’을 겨냥한 속도를 가장 우선시한 결과로 풀이된다. 정책 속도를 높이고, 발표 지연으로 인한 부동산 투기 등 부작용도 최소화하겠다는 의지가 담겼다는 해석이 나온다. 정부 관계자의 말을 종합하면, 전남광주통합특별시 광산구 군공항 부지는 공군 비행장과 탄약고 부지를 포함해 820만㎡(약 250만평)에 달한다. 서울 여의도의 3배 크기다. 무엇보다 광주 군공항은 가장 빠르게 반도체 공장을 지을 수 있는 곳으로 평가된다. 대규모 반도체 공장이 들어설 넓은 부지가 이미 갖춰져 있고, 교통·정주 여건과 용수 확보 측면에서 좋은 평가를 받은 것으로 전해졌다. 특히 정부는 ‘임기 내 완공’을 강조하며 속도전에 사활을 걸고 있다. 그런 점에서 용인 반도체 클러스터가 착공까지 6년이나 소요된 게 반면교사로 작용했을 것으로 보인다. 용인의 경우 민간 토지 보상과 인허가 문제로 착공하는 데만 6년이 걸렸다. 반면 광주 군공항 부지는 대부분 국방부 소유 국유지이기 때문에 복잡한 토지주들과의 보상 협상 등 논란 없이 행정 절차를 밟아 곧바로 사업을 추진할 수 있다는 게 최대 강점이다. 국토교통부 관계자는 “대부분 국유지여서 개발이 쉬운 면도 고려됐을 것”이라며 “보상으로 인한 불확실성도 제거되면서 도심 인근에 대규모로 개발 가능한 부지로 이만한 게 없다고 판단한 것으로 보인다”고 말했다. 정부는 부지 선정 이후 건축 설계 등에 대해서는 기업의 자율권을 확대하는 방향으로 검토 중인 것으로 알려졌다. 활주로 등으로 쓰이던 특성상 이미 평탄화 작업이 완료돼 있다는 점도 공기를 대폭 단축할 수 있는 요인이다. 대규모 산단 조성 시 가장 오랜 시간이 걸리는 토목공사 기간을 수년 단축할 수 있을 것으로 기대된다. 또한 광주 군공항이 도심과 가까워 인력 확보와 정주 여건 면에서도 강점이 뚜렷하다. 군공항은 상무지구 등 광주 도심과 가까워 교육·의료·주거 인프라를 함께 활용할 수 있다. 광주송정역(KTX·SRT)과도 맞닿아 있고, KTX를 이용하면 군공항 이전 부지인 무안국제공항까지 연결돼 항공 물류 수출입도 용이하다. 부동산 가격 안정도 정부가 이날 부지를 전격 발표한 이유 중 하나로 꼽힌다. 강훈식 대통령비서실장은 “광주 지역 부지를 먼저 선정하는 게 시급했던 건 부동산이 들썩거린다는 여러 가지 보고가 있었기 때문”이라고 밝혔다. 기업들은 ‘3대 메가프로젝트’ 투자 발표 일주일 만에 호남권 반도체 클러스터 입지가 확정되는 등 가시적 진전이 나타난 것을 환영하면서, 현재 조성 중인 용인 반도체 클러스터를 둘러싼 각종 절차도 속도감 있게 진행될 것을 기대했다. 주요국이 생산능력 확대를 위해 증설 경쟁에 나선 상황에서 용인 제조 거점의 신속한 완공이 한국 메모리 반도체 경쟁력 확보에 필수적이라는 인식을 드러낸 것이다. 삼성전자, SK하이닉스와 더불어 ‘메모리 3강’인 마이크론은 지난 4일 일본 히로시마현 공장에서 고대역폭메모리(HBM) 등 생산을 위한 신규설비 기공식을 개최했다. 용인 산단은 2023년 지정됐지만 토지 보상이 지연되면서 부지 조성공사 입찰 등 절차가 순차적으로 뒤로 밀리고 있다. 전력·용수 공급을 위한 구체적인 청사진도 용인 산단 선정 발표 이후 약 2년이 지난 시점에서야 공개되었고, 현재 설계에 들어간 상태다. 정부는 용인·호남 반도체 클러스터 투자를 동시에 추진할 가능성도 내비쳤다. 강 실장은 “꼭 용인이 끝난 뒤 호남을 하지는 않을 수 있다”며 “최대한 가능한 모든 것들을 당겨서 하겠다는 게 정부 방침”이라고 말했다.', 'crawl', '경향신문', '2026-07-06 21:30:01', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000202500017311.jpg', '2026-07-07 06:04:24', '2026-07-07 15:43:40.373724', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3067, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607062047001', 'https://www.khan.co.kr/article/202607062047001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', '삼성카드, 홈플러스 반발에 대금 지급 보류 철회', '현대카드 포인트 제휴 서비스는 중단대형마트 홈플러스가 인수자를 찾지 못해 사실상 파산 수순을 밟게 된 지난 3일 서울 시내 한 홈플러스 매장 입고장이 한산하다. 연합뉴스홈플러스 반발에 삼성카드가 대금 지급 보류를 철회했다. 다만 현대카드 포인트 결제는 중단된 상태다.홈플러스는 6일 서울회생법원의 회생절차 폐지 결정 이후 현대카드와 삼성카드가 오프라인 가맹점···', '현대카드 포인트 제휴 서비스는 중단 대형마트 홈플러스가 인수자를 찾지 못해 사실상 파산 수순을 밟게 된 지난 3일 서울 시내 한 홈플러스 매장 입고장이 한산하다. 연합뉴스 홈플러스 반발에 삼성카드가 대금 지급 보류를 철회했다. 다만 현대카드 포인트 결제는 중단된 상태다. 홈플러스는 6일 서울회생법원의 회생절차 폐지 결정 이후 현대카드와 삼성카드가 오프라인 가맹점 대금 지급 보류 공문을 보낸 것을 두고 부당한 처사라며 즉각 철회를 요구했다. 홈플러스는 입장문을 통해 회생절차 폐지 결정 이후 현대카드와 삼성카드로부터 ‘홈플러스 온라인몰 포인트 제휴 계약 종료, 온오프라인 미수금 및 매출 취소분 처리를 위한 오프라인 가맹점 대금 지급 보류 및 상계 시행’을 알리는 공문을 받은 사실을 알렸다. 회사는 “회생절차 폐지 결정은 ‘확정’돼야 효력이 발생하는데, 공고가 있은 날부터 14일 이내에 즉시항고가 가능하므로 아직 회생절차가 유지된다”며 “카드사가 회생절차 폐지 결정을 이유로 홈플러스 온라인몰 포인트 제휴 계약종료를 통지한 것은 요건을 갖추지 않아 효력이 없다”고 주장했다. 특히 오프라인에서는 외상 구매가 불가능하고, 온라인 영업도 3일째 중단돼 주문 취소가 불가능한 상황에서, 미수금 및 매출 취소분 처리를 위해 대금 지급을 보류한다는 것도 “말이 되지 않는다”고 했다. 삼성카드는 고객 보호 차원에서 대금 지급을 보류했다고 설명했다가, 몇시간 뒤 입장을 바꿨다. 삼성카드는 “보류 이후 매출 취소 추이가 안정세를 보여 오는 7일부터 가맹점 대금을 정상적으로 지급할 예정”이라고 설명했다. 삼성카드는 당초 회생절차 폐지 결정 이후 카드 매출 취소 건이 급격히 증가했다며 “물품 및 서비스 제공의 중단, 취소 불가 등 고객의 피해를 방지하기 위해 일시적으로 가맹점 대금 지급을 보류했다”고 말했다. 삼성카드는 홈플러스와 포인트 제휴 계약은 변동이 없다는 입장이다. 현대카드 측은 “현재 홈플러스에 가맹점 대금 지급을 하고 있다”고 밝혔다. 홈플러스에 매출 취소 시 상계처리 방침을 전달한 것일 뿐, 이날도 대금 지급이 이뤄졌다는 입장으로 알려졌다. 포인트 제휴 서비스는 포인트 결제에 따른 피해 가능성 등을 고려해 고객 보호 차원에서 종료한 것은 맞다고 말했다.', 'crawl', '경향신문', '2026-07-06 20:47:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260703.PYH2026070311180001300_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:44:02.636515', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3078, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607061724001', 'https://www.khan.co.kr/article/202607061724001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', '발표 일주일만에 광주 군공항 부지 선정까지, 정부 ‘속도전’에 사활 걸었다', '빠르게 진행할 수 있는 국유지 선정하며정책 추진 의지 보여주고 부동산 투기 최소화강훈식 대통령비서실장이 6일 청와대 춘추관에서 메가프로젝트 민관합동 점검 회의 결과 브리핑을 하고 있다. 연합뉴스정부가 호남권 반도체 클러스터 투자 계획을 발표한 지 일주일만에 6일 광주 군 공항을 산업단지 입지 후보지로 결정한 것은 입지 조건은 물론이고, 무엇보다 ‘속도전’을···', '빠르게 진행할 수 있는 국유지 선정하며 정책 추진 의지 보여주고 부동산 투기 최소화 강훈식 대통령비서실장이 6일 청와대 춘추관에서 메가프로젝트 민관합동 점검 회의 결과 브리핑을 하고 있다. 연합뉴스 정부가 호남권 반도체 클러스터 투자 계획을 발표한 지 일주일만에 6일 광주 군 공항을 산업단지 입지 후보지로 결정한 것은 입지 조건은 물론이고, 무엇보다 ‘속도전’을 가장 우선시한 결과로 풀이된다. 민간 부지가 아닌 곳을 골라 정책 속도를 높이고, 발표 지연으로 인한 부동산 투기 등 부작용도 최소화 하겠다는 의지가 담겼다는 해석이 나온다. 정부 관계자의 말을 종합하면, 전남광주통합특별시 광산구 군 공항 부지는 공군 비행장과 탄약고 부지를 포함한 820만㎡(250만평) 규모에 달한다. 서울 여의도의 3배에 달하는 크기다. 무엇보다 광주 군 공항은 가장 빠르게 반도체 공장을 지을 수 있는 곳으로 평가된다. 대규모 반도체 공장이 들어설 넓은 부지가 이미 확보돼있고 교통·정주 여건, 용수 확보 측면에서 좋은 평가를 받은 것으로 전해졌다. 정부는 ‘임기 내 완공’을 강조하며 속도전에 사활을 걸고 있다. 그런 점에서 용인 반도체 클러스터가 착공까지 6년이나 소요된 점은 반면교사로 작용했을 것으로 보인다. 용인의 경우 민간 토지 보상과 인허가 문제로 착공하는 데에만 6년이 걸렸다. 반면 광주 군 공항 부지는 대부분 국방부 소유의 국유지이기 때문에 복잡한 토지주들과의 보상 협상 등의 논란 없이 행정 절차를 밟아 곧바로 사업을 추진할 수 있다는 점이 최대 강점이다. 국토교통부 관계자는 “대부분 국유지여서 개발이 쉬운 면도 고려됐을 것”이라며 “보상으로 인한 불확실성도 제거되면서 도심 인근에 대규모로 개발 가능한 부지로 이만한 게 없다고 판단한 것으로 보인다”고 말했다. 정부는 부지 선정 이후 건축 설계 등에 대해서는 기업의 자율권을 확대하는 방향으로 검토중인 것으로 알려졌다. 정부 발표대로 이미 평탄화 작업이 완료돼 있다는 점도 공기를 대폭 단축할 수 있다는 점에서 속도전에 부합하는 점수를 받았을 것으로 보인다. 군 공항은 활주로 등으로 쓰이던 특성상 이미 대규모 평탄화 공사가 완료되어, 대규모 산단 조성 시 가장 오랜 시간이 걸리는 토목 공사 기간을 수년 이상 단축할 수 있을 것으로 예상되기 때문이다. 광주 군 공항이 도심과 가까워 인력 확보와 정주 여건 측면에서도 강점이 뚜렷하다. 실제 군 공항은 상무지구 등 광주 도심과 가까워 교육·의료·주거 인프라를 함께 활용할 수 있다. 또 광주 송정역(KTX·SRT)과 맞닿아 있고, 광주송정역에서 KTX를 이용하면 군 공항이 이전 부지인 무안국제공항까지 연결돼 즉각적인 항공 물류 수출입도 가능하다. 부동산 가격 안정도 정부가 이날 부지를 발표한 이유 중 하나로 꼽힌다. 강훈식 대통령 비서실장은 “광주 지역 부지를 먼저 선정하는 게 시급했던 건 부동산이 들썩거린다는 여러 가지 보고가 있었기 때문”이라며 “빨리 부지를 확정해야지만 이게 불필요한 논란과 확대가 되지 않을 것”이라고 말했다. 기업들은 ‘3대 메가프로젝트’ 투자 발표 일주일 만에 호남권 반도체 클러스터 입지가 확정되는 등 가시적 진전이 나타난 것을 환영하면서, 현재 조성 중인 용인 반도체 클러스터를 둘러싼 각종 절차도 속도감 있게 진행될 것을 기대했다. 주요국이 생산능력 확대를 위해 증설 경쟁에 나선 상황에서 용인 제조 거점의 신속한 완공이 한국 메모리 반도체 경쟁력 확보에 필수적이라는 인식을 드러낸 것이다. 삼성전자, SK하이닉스와 더불어 ‘메모리 3강’인 마이크론은 지난 4일 일본 히로시마현 공장에서 고대역폭메모리(HBM) 등 생산을 위한 신규라인 기공식을 개최했다. 마이크론은 지난해 1조5000억엔(14조원)을 투자하겠다고 밝힌 바 있다. 업계 관계자는 “호남 지역의 차세대 반도체 클러스터 조성 계획이 빠르게 진행되는 만큼 용인 산단 조성도 원활하게 진척되어야 할 것”이라고 말했다. 용인 산단은 2023년 지정됐지만 토지 보상이 지연되면서 부지 조성공사 입찰 등의 절차가 순차적으로 뒤로 밀리고 있다. 전력·용수 공급을 위한 구체적인 청사진도 용인 산단 선정 발표 이후 약 2년이 지난 시점에서야 공개되어 설계에 들어간 상태다. 용인시 처인구의 용인 첨단시스템반도체 국가산업단지 부지는 235만평으로, 삼성전자 팹 6기와 SK하이닉스 팹 4기가 들어설 예정이다. 정부는 용인과 호남을 동시에 추진할 가능성도 내비쳤다. 강 실장은 “꼭 용인이 끝난 뒤 호남을 하지는 않을 수 있다”며 “최대한 가능한 모든 것들을 당겨서 하겠다는 게 정부의 방침”이라고 말했다.', 'crawl', '경향신문', '2026-07-06 17:24:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260706.PYH2026070609660001300_P1.jpg', '2026-07-07 06:04:24', '2026-07-07 15:44:25.492447', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3081, 'https://www.khan.co.kr/rss/rssdata/economy_news.xml', 'https://www.khan.co.kr/article/202607061640011', 'https://www.khan.co.kr/article/202607061640011/?utm_source=khan_rss&utm_medium=rss&utm_campaign=economy_news', '경제', 'MBK 무책임에 온라인 대세 못따라간 홈플러스···‘30년 역사’ 뒤로 하고 파산 위기', '법원이 회생절차 폐지 결정을 내리면서 홈플러스가 파산 절차에 들어갈 가능성이 커졌다. 연합뉴스홈플러스가 지난 3일 법원의 기업회생절차 폐지 결정으로 창사 30년 만에 파산 위기까지 왔다. 유통업계에선 사모펀드(PEF) 운용사 MBK파트너스가 무리한 차입 경영을 하면서 홈플러스의 기초체력이 약화했고, 이로 인해 코로나19 팬데믹 시기 온라인으로 급속히 주도권···', '법원이 회생절차 폐지 결정을 내리면서 홈플러스가 파산 절차에 들어갈 가능성이 커졌다. 연합뉴스 홈플러스가 지난 3일 법원의 기업회생절차 폐지 결정으로 창사 30년 만에 파산 위기까지 왔다. 유통업계에선 사모펀드(PEF) 운용사 MBK파트너스가 무리한 차입 경영을 하면서 홈플러스의 기초체력이 약화했고, 이로 인해 코로나19 팬데믹 시기 온라인으로 급속히 주도권이 넘어간 유통업의 환경 변화에 제대로 대응하지 못한 게 경영 악화의 결정적 원인이라는 데 의견이 모인다. 6일 취재를 종합하면, 홈플러스는 1997년 삼성물산 유통부문이 대구에 1호점을 열면서 시작했다. IMF 외환위기 이후인 1999년 영국 유통업체 테스코가 경영권을 인수했고, 같은 해 삼성물산과 테스코의 합작법인이 설립됐다. 2004년 슈퍼마켓부문 사업을 시작하고 2008년엔 이랜드그룹이 운영하던 홈에버를 인수하는 등 공격적으로 사업을 확장했다. 2011년 홈플러스 지분 100%를 확보한 테스코는 2015년 MBK 컨소시엄에 홈플러스를 매각했다. 매각 무렵 홈플러스는 대형마트 140여개, 슈퍼마켓 370여개, 편의점 320여개 등을 가져 업계 1위 이마트에 비견되는 2위였다. MBK의 홈플러스 인수대금은 약 7조2000억원이었다. MBK는 이 가운데 최소 2조7000억원을 인수금융 방식으로 마련했다. MBK는 인수 직후 홈플러스에 2년간 1조원을 투자하겠다고 밝혔다. 하지만 MBK는 경쟁력 강화를 위한 투자보다는 차입금을 메꾸기 위한 자산 유동화에 집중했다. MBK는 홈플러스 인수 다음해인 2016년 핵심 점포 5곳을 매각해 6440억원을 확보한 것을 시작으로 2024년까지 점포와 물류창고 총 28곳을 팔아 4조1149억원을 확보했다. 이 같은 사업 방식은 홈플러스의 경쟁력을 서서히 갉아먹었다. 홈플러스는 매각한 점포 일부를 임차하는 세일앤리스백 방식으로 영업을 지속했다. 이로 인해 임차료 부담이 늘면서 2023년 한 해 리스부채 관련 현금유출액은 4516억원에 달했다. 앞서 한국신용평가는 홈플러스의 상각전영업이익(EBITDA)이 2019년 7351억원에서 2023년 3214억원으로 절반 넘게 감소한 반면 연간 6000억원 수준의 임차료와 이자비용 부담을 감당하기에는 현금창출력이 크게 부족하다고 평가했다. EBITDA는 기업의 현금창출력을 보여주는 지표다. 서울의 한 홈플러스 매장에서 10년 넘게 영업 중인 한 입점업체 사장은 “MBK 인수 이후 조명, 간판 등 기본적인 것부터 투자가 제대로 이뤄지지 않으면서 이미 손님이 서서히 감소해왔고, 지난해 3월 회생절차에 들어간 이후로는 손님이 급감했다”고 말했다. 2020년 발생한 코로나19 팬데믹은 MBK 인수 이후 허약해진 홈플러스가 고꾸라지는 결정적 계기가 됐다. 코로나19로 대형마트를 비롯한 오프라인 유통채널은 영업에 큰 타격을 입었고, 유통업계 주류가 온라인으로 넘어가는 흐름이 가속화했다. 산업통상부 주요 유통업체 매출동향을 보면, 2021~2025년 전체 유통업체는 연평균 6.7%씩 매출이 성장했는데, 온라인은 연평균 10.1% 성장한 반면 대형마트는 연평균 4.2% 감소했다. 하지만 신규 투자 여력이 없던 홈플러스는 온라인 전환에 제대로 대응하지 못한 채 오프라인 매장을 유지하는 데 급급했다. 한 유통업계 관계자는 “홈플러스가 코로나 때 온라인 전환에 대응하지 못한 게 파산 위기로 이어졌다고 본다”고 말했다. MBK가 인수하기 직전인 2014년 홈플러스는 매출 7조526억원, 영업이익 1944억원을 올렸다. 홈플러스는 코로나 팬데믹 직전인 2019년엔 매출 7조3002억원, 영업이익 1602억원으로 수년째 사실상 제자리걸음을 하다가 2021년부터 지난해까지 5년 연속 적자를 기록했다. 지난해 매출은 5조7963억원, 영업손실은 5464억원이었다. 2021년부터 2025년 사이 당기순손실은 372억원에서 1조10억원까지 확대되면서 5년간 누적 적자는 2조7341억원에 달했다. 유통업계에선 정부의 오프라인, 특히 대형마트 중심 규제가 홈플러스 몰락의 한 원인이란 지적도 나온다. 이미 유통시장 주도권이 온라인으로 넘어간 지 오래인데도 2012년 유통산업발전법 개정 이후 현재까지 대형마트 영업시간 제한, 의무휴업, 출점 규제 등이 유지되고 있어 홈플러스가 반등을 모색할 기회조차 없었다는 것이다. 또 다른 유통업계 관계자는 “규제가 시장 변화를 따라가지 못했다”며 “홈플러스 사태가 남의 일 같지 않다”고 말했다. 다만 이마트와 롯데마트가 신선식품 등을 중심으로 자체 경쟁력을 유지하고 있는 점을 볼 때 정부 규제만으로는 홈플러스가 지금과 같은 상황에 처한 이유를 설명하지는 못한다는 반론도 뒤따른다. 한편 홈플러스는 법원의 회생절차 폐지 결정 이후 현대카드와 삼성카드가 ‘홈플러스 온라인몰 포인트 제휴 계약 종료, 온오프라인 미수금 및 매출 취소분 처리를 위한 오프라인 가맹점 대금 지급 보류 및 상계 시행’을 알리는 공문을 보낸 데 반발했다. 홈플러스는 “회생절차 폐지 결정은 확정돼야 효력이 발생하는데, 공고가 있은 날부터 14일 이내에 즉시항고가 가능하므로 아직 회생절차가 유지된다”며 “카드사가 회생절차 폐지 결정을 이유로 홈플러스 온라인몰 포인트 제휴 계약종료를 통지한 것은 요건을 갖추지 않아 효력이 없다”고 주장했다.', 'crawl', '경향신문', '2026-07-06 16:40:01', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260705.ecd7039346f74654ba1ded182a098ed5_P1.jpeg', '2026-07-07 06:04:24', '2026-07-07 15:44:31.728374', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3088, 'https://www.khan.co.kr/rss/rssdata/society_news.xml', 'https://www.khan.co.kr/article/202607071454001', 'https://www.khan.co.kr/article/202607071454001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=society_news', '사회', '시민사회 “홈플러스 사태는 사회적 재난··· 정부 긴급 개입 촉구”', '김상근 원로목사가 7일 서울 중구 민주노총에서 열린 홈플러스 회생방안 마련 위한 이재명 대통령 면담 요구 및 정부 개입 촉구 기자회견에서 발언을 하고 있다. 2026.7.7 성동훈 기자시민사회가 파산 기로에 놓인 홈플러스 사태와 관련해 정부의 긴급 개입을 촉구하고 나섰다.사회 원로 및 시민사회 각계 대표자 인사들은 7일 서울 정동 민주노총에서 기자회견을 열···', '김상근 원로목사가 7일 서울 중구 민주노총에서 열린 홈플러스 회생방안 마련 위한 이재명 대통령 면담 요구 및 정부 개입 촉구 기자회견에서 발언을 하고 있다. 2026.7.7 성동훈 기자 시민사회가 파산 기로에 놓인 홈플러스 사태와 관련해 정부의 긴급 개입을 촉구하고 나섰다. 사회 원로 및 시민사회 각계 대표자 인사들은 7일 서울 정동 민주노총에서 기자회견을 열어 “홈플러스 노동자, 입점업체, 협력업체 종사자 등 10만명의 생계가 앞으로 남은 10여일에 달려 있다”며 “이재명 대통령이 결단해 IMF 위기 이후 최대의 실업 및 민생 대란을 막아야 한다”고 촉구했다. 참가자들은 “(홈플러스 대주주인) MBK 투기 자본이 홈플러스를 인수하고 ‘먹튀’를 위해 회사를 망가뜨리는 동안 정부, 관계기관, 금융당국 어느 곳에서도 제지하지 않았다”면서 정부가 공적자금 투입 등으로 가능한 긴급 조치를 취하는 한편 MBK에 대해선 철저한 수사를 해야 한다고 촉구했다. 아울러 사태 해결을 위한 이재명 대통령과의 면담을 요구했다. 기자회견에는 김상근 목사와 함세웅 신부 등 시민사회 원로들과 양경수 민주노총 위원장, 박석운 홈플러스 살리기 공동대책위원회 상임대표 등이 참석했으며, 시민사회 각계 대표자 135명이 성명에 이름을 올렸다. 양경수 위원장은 “홈플러스 사태는 사회적 재난”이라며 “돈은 사모펀드가 벌어가고 피해는 노동자들에게 전가하는 현실에 정부가 나서 대책을 마련해야 한다”고 말했다. 사태 해결을 촉구하며 1년간 네 차례 단식 농성을 진행했던 안수용 마트노조 홈플러스지부 지부장은 정부가 홈플러스 협력업체들에 4400억원 규모의 긴급 유동성을 지원하기로 한 것을 두고 “왜 살릴 수 있을 때 살리지 않고 죽고 난 이후 혈세를 쓰는가”라면서 “홈플러스를 회생에 필요한 2000억원은 마련되지 못했고, 정부는 홈플러스를 살릴 수 있는 마지막 기회조차 놓치고 있다”고 말했다. 홈플러스는 지난 3일 법원의 기업회생절차 폐지 결정으로 창사 30년 만에 파산 위기를 맞게 됐다. 회생에 필요한 최소한의 운영자금 2000억원을 오는 20일까지 조달하지 않으면 홈플러스는 파산 수순을 밟게 된다. 법원은 2주 안에 자금을 마련하면 회생 절차를 재개할 수 있도록 유예기간을 줬지만, 대주주인 MBK파트너스와 최대 채권자인 메리츠금융그룹은 진전된 입장을 내지 않고 있다. 회생절차 폐지 결정이 확정되면 전국 60여개 점포가 폐점 위기에 놓이는 것은 물론 대량 실업 역시 우려되는 상황이다. 정부는 임금체불 노동자에게 1인당 최대 2100만원까지 대지급금을 지급하고 홈플러스가 주된 거래처인 중소기업과 소상공인에 4400억원 규모의 긴급 유동성을 지원한다고 밝힌 상태다. 물건도, 결제도 사라진 텅 빈 매장…남은 직원들은 생계 걱정 “미역 사려고 했는데 카드 결제가 안 된다길래 반품했어요. 신선식품도 하나 없고 살 수 있는 게 아무것도 없네요.” 6일 서울 성북구 홈플러스 월곡점에서 만난 정혜영씨(52)가 말했다. 법원이 지난 3일 홈플러스 회생절차 폐지 결정을 내리자 일부 카드사는 이날 홈플러스 카드 결제를 한때 중단했다. 정씨는 “홈플러스가 없어지면 온라인을 이용해야겠지만 좀... https://www.khan.co.kr/article/202607062139005 투기자본 ‘무책임’에 온라인 전환 실패 덮쳐…30년 대형마트의 ‘몰락’ 홈플러스가 지난 3일 법원의 기업회생절차 폐지 결정으로 창사 30년 만에 파산위기까지 왔다. 유통업계에선 사모펀드(PEF) 운용사 MBK파트너스의 무리한 차입 경영에다 코로나19 팬데믹 시기 온라인으로 급속히 주도권이 넘어간 환경 변화에 대응하지 못한 것이 경영이 악화된 결정적 원인이라고 지목한다. 6일 취재를 종합하면, 홈플러스는 1997년 삼성물산... https://www.khan.co.kr/article/202607062136005', 'crawl', '경향신문', '2026-07-07 14:54:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260707.1fdbd50b82b5409aac834212d977badc_P1.jpeg', '2026-07-07 06:04:25', '2026-07-07 15:44:44.546278', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3103, 'https://www.khan.co.kr/rss/rssdata/society_news.xml', 'https://www.khan.co.kr/article/202607071149001', 'https://www.khan.co.kr/article/202607071149001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=society_news', '사회', '‘음료 테러 자작극 의혹’··· 정이한 전 개혁신당 부산시장 후보, 8일 구속 여부 결정', '6·3 지방선거에서 부산시장에 출마한 당시 개혁신당 정이한 후보가 지난 4월 27일 부산 금정구 구서나들목 인근에서 지나가는 차량 운전자로부터 ‘음료 투척 테러’를 당하는 장면. 정이한 선거 캠프 제공6·3 지방선거 당시 선거운동 중 피습당했다고 주장했다가 자작극 의혹이 불거진 정이한 전 개혁신당 부산시장 후보에 대한 구속영장이 신청됐다.7일 부산경찰청 등···', '6·3 지방선거에서 부산시장에 출마한 당시 개혁신당 정이한 후보가 지난 4월 27일 부산 금정구 구서나들목 인근에서 지나가는 차량 운전자로부터 ‘음료 투척 테러’를 당하는 장면. 정이한 선거 캠프 제공 6·3 지방선거 당시 선거운동 중 피습당했다고 주장했다가 자작극 의혹이 불거진 정이한 전 개혁신당 부산시장 후보에 대한 구속영장이 신청됐다. 7일 부산경찰청 등에 따르면 경찰은 지난 1일 위계에 의한 공무집행방해 및 공직선거법 위반 혐의 등으로 정씨 등 2명에 대한 구속영장을 신청했다. 경찰 관계자는 “증거인멸과 도주 우려가 있다고 보고 구속영장을 신청했다”고 말했다. 구속 전 피의자 심문(영장실질심사)은 오는 8일 오후 2시 부산지법에서 열릴 예정이다. 경찰 등에 따르면 정씨는 지난 4월27일 부산 금정구 구서나들목 인근에서 선거 유세를 하다가 지나가던 차량 운전자 A씨가 던진 음료에 맞아 넘어져 뇌진탕과 근좌상 진단을 받았다고 주장했다. 하지만 경찰 조사에서 정씨와 A씨가 전화 통화를 한 적이 있다는 점이 드러나면서 자작극 의혹이 불거졌다. A씨는 정씨와 평소 친분이 있던 헬스 트레이너인 것으로 경찰 조사에서 확인됐다. 경찰은 음료 투척 사건 전 두 사람이 공모했을 가능성에 무게를 두고 있는 것으로 알려졌다. 한편 경찰은 이 사건과 별개로 정씨의 부친이 운영하는 병원의 의료법 위반과 선거 개입 여부 등에 대해서도 수사를 진행하고 있다.', 'crawl', '경향신문', '2026-07-07 11:49:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260617.6912445445bb4b9392946e5df5889d94_P1.png', '2026-07-07 06:04:25', '2026-07-07 15:45:15.677468', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3118, 'https://www.khan.co.kr/rss/rssdata/society_news.xml', 'https://www.khan.co.kr/article/202607070739001', 'https://www.khan.co.kr/article/202607070739001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=society_news', '사회', '장맛비에 찜통더위까지···전국 흐리고 비, 낮 최고 34도', '출근하는 시민들이 우산을 쓰고 서울 종로구 광화문 광장 일대에서 신호를 기다리고 있다. 정효진 기자화요일인 7일 전국이 대체로 흐리고 비가 오겠다. 낮 최고기온은 34도까지 올라 무덥겠다.기상청 단기예보를 보면 이날 오전에는 전국에, 오후부터 저녁 사이에는 중부지방과 전북 북부, 경북권, 경남 내륙을 중심으로 비가 내리겠다.기상청은 서해상에서 강하게 발달한···', '출근하는 시민들이 우산을 쓰고 서울 종로구 광화문 광장 일대에서 신호를 기다리고 있다. 정효진 기자 화요일인 7일 전국이 대체로 흐리고 비가 오겠다. 낮 최고기온은 34도까지 올라 무덥겠다. 기상청 단기예보를 보면 이날 오전에는 전국에, 오후부터 저녁 사이에는 중부지방과 전북 북부, 경북권, 경남 내륙을 중심으로 비가 내리겠다. 기상청은 서해상에서 강하게 발달한 비구름이 시속 약 70㎞의 속도로 빠르게 북동쪽으로 이동하면서 비를 뿌리고 있다고 설명했다. 예상 강수량은 수도권과 강원 내륙, 충청권에 20~60㎜, 강원 동해안과 경상권에 5~40㎜, 광주·전남에 5~10㎜로 예보됐다. 기상청은 “특히 오전 수도권과 충남권, 강원 내륙·산지를 중심으로 시간당 20~30㎜의 강한 비가 내릴 것으로 보여 안전에 유의해야 한다”고 당부했다. 이날 오후부터 저녁 사이에는 전국 대부분 지역에 소나기가 내리겠다. 소나기는 돌풍과 천둥·번개를 동반하고 시간당 20㎜ 안팎으로 강하게 내리겠다. 당분간 기온은 전국 내륙을 중심으로 30도 이상으로 오르고, 최고 체감온도는 31도 안팎으로 올라 덥겠다. 열대야가 나타날 가능성도 있다. 이날 낮 최고기온은 27~34도로 예보됐다.', 'crawl', '경향신문', '2026-07-07 07:39:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260707.c00c1a80803843c8a98eaec087a38f65_P1.jpeg', '2026-07-07 06:04:25', '2026-07-07 15:45:52.667507', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3122, 'https://www.khan.co.kr/rss/rssdata/society_news.xml', 'https://www.khan.co.kr/article/202607062145005', 'https://www.khan.co.kr/article/202607062145005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=society_news', '사회', '정유사들, 전쟁 틈타 14조 담합·갑질', '검찰, 오일뱅크·SK에너지 기소타사 편승…26조 경쟁 제한 효과검찰이 유가 담합 혐의로 국내 정유사와 직원들을 재판에 넘긴 6일 서울 시내 한 주유소에서 운전자가 기름을 넣고 있다. 연합뉴스정유사 HD현대오일뱅크와 SK에너지가 미·이란 전쟁 개전 직후 14조원대 가격 담합을 벌여 유가를 끌어올린 혐의로 재판에 넘겨졌다. GS칼텍스, 에쓰오일도 이에 편승해···', '검찰, 오일뱅크·SK에너지 기소 타사 편승…26조 경쟁 제한 효과 검찰이 유가 담합 혐의로 국내 정유사와 직원들을 재판에 넘긴 6일 서울 시내 한 주유소에서 운전자가 기름을 넣고 있다. 연합뉴스 정유사 HD현대오일뱅크와 SK에너지가 미·이란 전쟁 개전 직후 14조원대 가격 담합을 벌여 유가를 끌어올린 혐의로 재판에 넘겨졌다. GS칼텍스, 에쓰오일도 이에 편승해 유가를 올렸으나 담합을 했다는 증거는 나오지 않아 기소를 면했다. 검찰은 이번 담합으로 4대 정유사 간 26조원의 경쟁 제한 효과가 발생했다고 봤다. 서울중앙지검 공정거래조사부(부장검사 나희석)는 6일 유가를 담합한 혐의(공정거래법 위반)로 HD현대오일뱅크와 SK에너지 법인을 기소했다고 밝혔다. 검찰은 같은 혐의로 HD현대오일뱅크의 가격결정부서 부서장 A씨(구속)와 책임매니저 B씨도 재판에 넘겼다. 검찰은 지난 3월 미·이란 전쟁 발발 직후 발생한 한국의 유가 폭등은 HD현대오일뱅크와 SK에너지의 가격결정부서 책임자들이 가격 인상 시기와 규모를 담합한 결과라고 판단했다. 당시는 4대 정유회사가 상당한 원유를 비축한 상황이라 가격이 폭등할 사유가 없는데도 가격을 크게 올렸다는 것이다. HD현대오일뱅크 가격결정부서장 A씨는 지난 3월 전쟁이 발발하자 SK에너지의 가격결정부서장 C씨와 유가를 대폭 올리기로 합의한 혐의를 받는다. HD현대오일뱅크와 SK에너지는 2024년 7월부터 올해 2월까지 유가 정보를 교환해왔던 것으로 조사됐다. 검찰은 GS칼텍스와 에쓰오일이 HD현대오일뱅크와 SK에너지가 담합한 가격을 따라 유가를 올리면서 시장에서 전체적인 유가 폭등이 벌어졌다고 밝혔다. “100원 더 올린다, 올해 2조 벌 듯” 사내 메신저 덜미…조직적 증거인멸 정황도 검찰, ‘전량구매계약’ 관행도 적발 4대 정유회사 모두 재판에 넘겨 에쓰오일 직원들은 전쟁 발발 직후 사내 메신저에서 “오늘 가격 100원 더 올린다. 우리 올해 2조 벌 듯” “역시 전쟁으로 먹고사는 회사. 트럼프 (미국 대통령) 만세” 등 대화를 나눴다. 검찰은 4대 정유회사 전체가 담합을 공모했다고 의심했지만, GS칼텍스와 에쓰오일이 가담한 증거는 찾지 못했다. 검찰은 HD현대오일뱅크와 SK에너지의 직접 담합 규모를 14조2000억원으로 산정했다. 두 회사를 따라 GS칼텍스와 에쓰오일이 유가를 올린 것까지 종합하면 약 26조원의 경쟁 제한 효과가 발생했다고 전했다. 검찰은 HD현대오일뱅크와 GS칼텍스가 조직적으로 증거인멸을 시도한 점도 파악했다고 밝혔다. 검찰은 이들 법인과 HD현대오일뱅크 법무실장 D씨, GS칼텍스 국내영업부문장 E씨를 공정거래법상 조사방해 등 혐의로 기소했다. D씨는 지난 3월 공정거래위원회 현장조사 계획을 미리 알고 다른 정유회사들의 가격 정보를 취합한 자료를 삭제한 혐의를 받는다. E씨도 공정위 현장조사에 대비해 가격결정 회의 자료를 공유했던 사내 메신저 단체대화방을 삭제한 혐의가 있다. 검찰은 정유업계의 ‘전량구매계약’ 관행도 수사해 4대 정유회사 법인을 모두 재판에 넘겼다. 한국 정유시장을 과점한 4대 정유회사는 2021년 1월부터 지난달까지 주유소들에 일방적으로 결정한 공급가격을 통보하고, 석유 전량을 자기 회사에서만 구입하도록 계약을 맺었다. 앞서 이재명 대통령은 지난 3월 청와대 수석보좌관회의에서 “기름값 바가지처럼 공동체의 어려움을 이용해 부당한 폭리를 취하려는 반사회적인 악행에 대해서는 아주 엄정하고 단호한 대응을 해야 한다”고 말했다. 검찰은 같은 달 4대 정유회사와 한국석유협회를 압수수색했다.', 'crawl', '경향신문', '2026-07-06 21:45:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000180800017331.jpg', '2026-07-07 06:04:25', '2026-07-07 15:46:01.45109', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3124, 'https://www.khan.co.kr/rss/rssdata/society_news.xml', 'https://www.khan.co.kr/article/202607062141005', 'https://www.khan.co.kr/article/202607062141005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=society_news', '사회', '“죄송합니다”…“다시 나아가자”', '‘조롱 응원’ 고개 숙인 배재고다시는… 5·18민주화운동 폄하 및 지역 비하 응원 구호에 대해 사과하기 위해 전남광주 북구 광주제일고등학교를 찾은 서울 배재고등학교 야구부 학생과 교장, 교직원, 학부모 등 80여명이 6일 광주제일고 학생들과 함께 국립5·18민주묘지에서 참배하고 있다. 강윤중 선임기자 yaja@kyunghyang.com야구부·교직원·학부모···', '‘조롱 응원’ 고개 숙인 배재고 다시는… 5·18민주화운동 폄하 및 지역 비하 응원 구호에 대해 사과하기 위해 전남광주 북구 광주제일고등학교를 찾은 서울 배재고등학교 야구부 학생과 교장, 교직원, 학부모 등 80여명이 6일 광주제일고 학생들과 함께 국립5·18민주묘지에서 참배하고 있다. 강윤중 선임기자 yaja@kyunghyang.com 야구부·교직원·학부모 등 80여명, 광주 찾아 “깊이 반성” 사과 광주일고 “실수는 반성하면 된다” 화해…5·18묘지 참배 동행 서울 배재고등학교 야구부 학생들이 6일 광주제일고등학교(광주일고) 야구부 학생들 앞에 섰다. 두 손을 공손히 모은 배재고 학생들은 “미안하다”며 고개를 숙였다. 광주일고 학생들은 배재고 학생들의 손을 잡으며 “고개 들라. 어깨 펴라”라고 말했다. 배재고 야구부 학생과 교장, 교직원, 학부모 등 80여명은 이날 오후 3시 전남광주통합특별시 북구 누문동에 있는 광주일고를 찾았다. 배재고 야구부 주장 A군은 사과문을 낭독했다. A군은 “부적절한 발언과 행동으로 광주일고 선수와 학부모, 광주 시민들께 큰 상처를 드렸다. 진심으로 사과드린다”며 “야구를 떠나 인성과 태도가 얼마나 중요한지 다시 배우게 됐다”고 말했다. A군은 “같은 선수로서 정말 하면 안 되는 행동이었다”며 “항상 마음속 깊이 반성하는 마음과 자세로 살아가겠다”고 했다. 배재고 권오영 야구부 감독과 이효준 교장도 사과했다. 권 감독은 “지도자로서 책임이 가장 크다”며 “이기는 것보다 더 중요한 것이 있음을 잊고 있었다”고 말했다. 이 교장은 “광주학생독립운동과 5·18민주화운동의 정신을 잊지 않겠다”고 말하며 눈물을 흘렸다. 광주일고 선수 대표 B군은 “이번 일을 통해 저희도 다른 팀에게 상처를 주는 언행은 없었는지 돌아보는 계기가 됐다”고 말했다. 조윤채 광주일고 감독은 “사람은 누구나 실수한다. 실수는 반성하면 된다”고 했다. 이규연 광주일고 교장도 배재고 학생들에게 “여러분의 미래는 아직 끝나지 않았다”며 “고개를 들고 다시 나아가라”고 말했다. 사과와 화해의 시간을 마친 두 학교 학생과 교직원들은 교정 안 광주학생독립운동기념탑으로 이동했다. 배재고 학생 대표와 교장은 배재고 명의 화환을 놓고 묵념했다. 사과와 화해의 악수 서울 배재고등학교 야구부 학생들이 5·18민주화운동 폄하 응원 논란에 대해 사과하기 위해 전남광주 북구 광주제일고등학교를 방문한 가운데 배재고 야구부 주장(왼쪽)이 광주제일고 야구부 주장에게 사과문을 전달하고 있다. 강윤중 선임기자 두 손 모은 배재고…“어깨 펴” 손잡아준 광주일고 광주학생독립운동기념탑은 1929년 광주학생독립운동을 기리는 상징물이다. 광주일고는 5·18민주화운동 당시 학생들이 신군부 진압에 반발해 시위에 나서기도 했다. 정문 한쪽 담장에는 광주일고를 1981년에 졸업한 56회 졸업생 명의 현수막이 걸렸다. “배재고 아이들아! 너희를 사랑한다. 너희는 자라는 중이야, 그래도 하지 말아야 할 것도 있단다”란 메시지가 바람에 흔들렸다. 잘못은 짚되 배재고 학생들을 배척하지 않겠다는 뜻으로 읽혔다. 광주일고는 배재고의 방문을 앞두고 지난 3일 경찰에 시설 보호를 요청했지만 별다른 소란 없이 마무리됐다. 배재고 학생들은 광주일고 방문 뒤 국립5·18민주묘지로 이동해 추모탑 앞에 헌화하고 묵념했다. 이 자리에 동행한 정근식 서울시교육감은 방명록에 “5·18민주화운동의 정신이 우리 학생들과 학생선수들의 마음속에 깊이 자리 잡아 건강하고 훌륭한 민주시민으로 성장하기를 간절히 기원합니다”라고 적었다. 김대중 전남광주통합특별시교육감은 “배재고 학생들이 광주를 찾아 사과하고 광주일고 학생들과 함께 참배하는 모습은 단순한 사과를 넘어 서로를 이해하고 존중하는 교육의 과정이며, 민주주의를 배우는 뜻깊은 실천”이라고 말했다. 사건의 발단은 지난달 29일 서울 목동구장에서 열린 제81회 청룡기 전국고교야구선수권대회 겸 주말리그 왕중왕전 경기였다. 배재고 야구부 학생들이 광주일고와 경기하면서 “스타벅스 가야지” “탱크데이” 등 5·18민주화운동 조롱성 구호를 외쳐 공분을 샀다. 배재고 야구부는 이 사건으로 대한야구소프트볼협회(KBSA)로부터 6개월 출전 정지 징계를 받았다.', 'crawl', '경향신문', '2026-07-06 21:41:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000197600017351.jpg', '2026-07-07 06:04:25', '2026-07-07 15:46:05.109977', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3126, 'https://www.khan.co.kr/rss/rssdata/society_news.xml', 'https://www.khan.co.kr/article/202607062139005', 'https://www.khan.co.kr/article/202607062139005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=society_news', '사회', '물건도, 결제도 사라진 텅 빈 매장…남은 직원들은 생계 걱정', '‘회생절차 폐지 결정’ 그 후냉장고 속엔 프라이팬들이…무인 계산대는 ‘멈춤’ 서울 마포구 홈플러스 합정점 육류 등 식품 코너에 6일 프라이팬 등이 진열돼 있다(왼쪽 사진). 합정점에는 무인 계산대 운영 중단을 알리는 안내문이 붙어 있다. 안효빈 기자과거 서울 매출 1위 월드컵점도 신선식품 진열대엔 프라이팬들 입주업체들 대금 미정산 우려해 매장 철수…한때 카···', '‘회생절차 폐지 결정’ 그 후 냉장고 속엔 프라이팬들이…무인 계산대는 ‘멈춤’ 서울 마포구 홈플러스 합정점 육류 등 식품 코너에 6일 프라이팬 등이 진열돼 있다(왼쪽 사진). 합정점에는 무인 계산대 운영 중단을 알리는 안내문이 붙어 있다. 안효빈 기자 과거 서울 매출 1위 월드컵점도 신선식품 진열대엔 프라이팬들 입주업체들 대금 미정산 우려해 매장 철수…한때 카드 결제 중단 직원 “근무 지침 없어” 무력감 법원이 제시한 2주 기다리는 중 “미역 사려고 했는데 카드 결제가 안 된다길래 반품했어요. 신선식품도 하나 없고 살 수 있는 게 아무것도 없네요.” 6일 서울 성북구 홈플러스 월곡점에서 만난 정혜영씨(52)가 말했다. 법원이 지난 3일 홈플러스 회생절차 폐지 결정을 내리자 일부 카드사는 이날 홈플러스 카드 결제를 한때 중단했다. 정씨는 “홈플러스가 없어지면 온라인을 이용해야겠지만 좀 서운하다”며 “계속 계시던 직원분들도 안 보인다”고 했다. 홈플러스 회생절차 폐지 결정이 내려진 지 나흘째인 이날 경향신문이 찾은 서울 월드컵점·합정점·남현점·월곡점·서울상봉점 등은 손님들의 발길이 거의 끊겨 한적했다. 매대 대부분은 홈플러스 자체 브랜드(PB)인 ‘심플러스’ 상품으로 채워졌다. 치즈 코너에는 텀블러, 그릇 등이 진열돼 있고, 신선상품 코너에는 밀폐용기가 놓여 있었다. 냉동만두가 있어야 할 냉장고에는 심플러스 냉동 블루베리만 자리를 차지하고 있었다. 납품업체들이 상품 공급을 중단한 탓이다. 이미 공급된 납품업체 상품에도 판매 중지를 알리는 안내가 붙었다. 매점 입구에 붙은 “정상 영업합니다”라는 안내문구가 무색했다. 장보러 온 사람들은 물건을 뒤적거리다 “살 게 없다”며 빈 카트를 끌고 발길을 돌렸다. 회생절차 폐지 결정이 내려진 후 주말 사이 세일 물건이 빠지면서 재고가 더 줄었다. 합정점에서 만난 정희자씨(67)는 “가격이 싸서 살 게 있나 봤는데 없다”며 고개를 저었다. 한때 ‘서울 시내 매출 1위 홈플러스 매장’이었던 월드컵점을 찾은 이희지씨(23)는 “살 만한 물건이 없을 것이라 예상은 했지만 예상보다 더 없다. 냉장고에 프라이팬이 진열된 게 황당하다”며 “대형마트 중 하나인 홈플러스가 이렇게 쉽게 망하다니 싶다”고 말했다. 상봉점에서 만난 70대 A씨는 “뭐 하나라도 사려고 왔는데 텅텅 비었다”며 “슈퍼가 근처에 있어 참 좋았는데 홈플러스가 망해버리다니…”라고 했다. 매장에선 “없는 게 없어요. 착한 가게 홈플러스~”라는 CM송이 흘러나왔다. 김미숙씨(62)는 “올 때마다 물건이 계속 없어진다. 오늘도 멸치를 사러 왔는데 하나도 없어서 다른 곳으로 가야 한다”며 “내 집처럼 드나들고 보물창고처럼 여겼던 곳이라 너무 안타깝고 마음이 안 좋다”고 말했다. 매장을 지키는 직원들은 2주 뒤 상황을 내다보기 어렵다고 했다. 법원의 회생절차 폐지 결정으로 그나마 남아 있던 회생 기대감이 사라지고 무력감이 커진 분위기였다. 직원들은 당장 생계를 불안해하는 모습이었다. 남현점·월곡점 직원들은 “근무를 언제까지 할지 정해지거나 들은 게 없다”거나 “(법원이 제시한) 2주 시한이 지나봐야 안다”고 말했다. 한 직원은 “안 그래도 지금 어떻게 될지 몰라 머리가 아프다. 해줄 말이 없다”며 손사래를 쳤다. 일부 매장에선 무인 계산대 운영을 중단했다. 합정점 직원 B씨는 “무인 계산대는 인원이 없어서 닫아놨다”며 “최근 한 달 사이 (직원이) 많이 나갔다”고 했다. 다른 지점의 직원 C씨는 “사람도 없고 물건도 안 들어오니 손님보다 직원이 더 많다”며 “슬프다. 파산할 것으로 예상은 했지만 실제로 닥치니 더 어지럽다”고 말했다. 홈플러스 입주업체도 상황이 막막하긴 마찬가지다. 입주업체들은 회생절차 폐지 결정 전후로 판매를 중지하거나 홈플러스 단말기를 이용한 카드 결제를 중단했다. 홈플러스가 파산하면 정산 대금을 받지 못할 가능성을 우려해서다. 남현점의 한 입주업체 직원 D씨는 “사람이 거의 없어 유령매장 같다”며 “입주업체는 손님들이 장보러 왔다가 들르는 곳이니 더 힘들다”고 했다. 합정점에선 입주업체가 이미 매대를 정리하고 철수한 경우도 있다. 홈플러스는 법원의 회생절차 폐지 결정으로 회생에 필요한 최소한의 운영자금 2000억원을 오는 20일까지 조달하지 않으면 파산 수순을 밟게 된다. 법원은 홈플러스가 2주 안에 자금을 마련하면 회생절차를 재개할 수 있도록 유예기한을 줬지만, 최대 채권자인 메리츠금융그룹과 대주주 MBK파트너스는 진전된 입장을 내놓지 않고 있다. 회생절차 폐지 결정이 확정되면 9000여명에 달하는 직원들이 일자리를 잃고 전국 60여개 점포가 폐점 위기에 놓일 것으로 전망된다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-06 21:39:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000193600017321.jpg', '2026-07-07 06:04:25', '2026-07-07 15:46:08.464647', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3148, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607070744001', 'https://www.khan.co.kr/article/202607070744001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '[베네수 강진]사망자 3535명···간절함에 ‘구조’ 오보도', '6일(현지시간) 베네수엘라 카티아 라 마르 지역에 한 건물이 붕괴된 모습. EPA연합뉴스지난달 24일(현지시간) 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3535명으로 늘었다고 호르헤 로드리게스 국회의장이 6일 밝혔다. 이는 전날보다 193명 늘어난 수치다.부상자 수치는 전날과 변동 없는 1만6740명이다. 이재민은 1만7854명으로 집계됐다. 이번 ···', '6일(현지시간) 베네수엘라 카티아 라 마르 지역에 한 건물이 붕괴된 모습. EPA연합뉴스 지난달 24일(현지시간) 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3535명으로 늘었다고 호르헤 로드리게스 국회의장이 6일 밝혔다. 이는 전날보다 193명 늘어난 수치다. 부상자 수치는 전날과 변동 없는 1만6740명이다. 이재민은 1만7854명으로 집계됐다. 이번 지진으로 피해를 본 건물은 856채이며, 붕괴한 건물은 총 190채라고 로드리게스 의장은 설명했다. 정부는 육군과 보안군 2만9567명을 투입했으며 이들은 자원봉사자 2만7930명과 함께 구조·복구 작업을 진행하고 있다. 수만 명이 구조작업에 나서고 있으나 지진이 발생한 지 열흘이 넘으면서 매몰자들의 생환 가능성은 크게 줄어든 상태다. 구조에 대한 기대가 크다 보니 관련 오보도 이어지고 있다. SNS 등을 통해 알려졌던 지진 11일 만에 어린이 등 4명 구조 소식은 현지 언론의 오보인 것으로 확인됐다. 이날 현지 일간 엘나시오날은 전날 밤 9시께 라과이라주 카라바예다에서 구조대가 어린이 등 4명을 구조했다고 보도했으나, 이는 사실이 아니라고 바로잡았다. 베네수엘라 당국도 구조 대원들이 6462명을 구조했으며 이 수치는 지난 2일 이후 변동이 없다고 밝혔다.', 'crawl', '경향신문', '2026-07-07 07:44:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/07/rcv.YNA.20260707.PEP20260707137701009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:05.881857', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3150, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607062122015', 'https://www.khan.co.kr/article/202607062122015/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '유럽, 미와 갈등 최고조…나토 ‘동맹 균열’ 봉합할까', '그린란드 사태·이란전에 관계 악화트럼프에 ‘국방비 증액’ 부각할 듯“전쟁 반대! 트럼프 반대!” 활동가들이 5일(현지시간) 튀르키예 이스탄불에서 열린 나토 정상회의 반대 집회에서 “전쟁 반대” “반트럼프” 팻말을 들고 시위를 하고 있다. AFP연합뉴스북대서양조약기구(나토) 연례 정상회의가 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 열린다. 도널드 ···', '그린란드 사태·이란전에 관계 악화 트럼프에 ‘국방비 증액’ 부각할 듯 “전쟁 반대! 트럼프 반대!” 활동가들이 5일(현지시간) 튀르키예 이스탄불에서 열린 나토 정상회의 반대 집회에서 “전쟁 반대” “반트럼프” 팻말을 들고 시위를 하고 있다. AFP연합뉴스 북대서양조약기구(나토) 연례 정상회의가 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 열린다. 도널드 트럼프 미국 대통령이 나토 탈퇴 가능성 등을 거론하며 회원국들과 신뢰에 균열이 생긴 가운데 이번 회의에서 나토의 향후 방향성이 어떻게 논의될지 주목된다. 이번 회의는 미국의 그린란드 병합 추진과 이란 전쟁 등으로 미국과 다른 나토 회원국들의 갈등이 극에 달한 시점에 개최된다. 트럼프 대통령은 다른 회원국들이 국방비를 충분히 분담하지 않고 미국에 의존한다며 이 국가들을 비난해왔다. 미국과 다른 회원국들의 갈등이 본격화된 것은 트럼프 대통령이 군사력을 동원해서라도 그린란드를 병합하겠다는 야망을 드러낸 지난 1월부터다. 당시 미국의 강제 병합 가능성을 우려한 일부 회원국이 그린란드에 병력을 파견하면서 긴장이 고조됐다. 지난 2월28일 이란 전쟁 발발 후 갈등은 더 거세졌다. 트럼프 대통령은 이란을 공습한 후 나토 회원국을 포함한 동맹국들에 군함 파견과 기지 사용 등을 요청했으나 대부분 국가는 이를 거부했다. 이에 트럼프 대통령은 나토에서 탈퇴하고 유럽에 주둔한 미군을 철수하겠다고 했다. 나토 정상들은 이번 회의에서 일단 한발 물러서 갈등을 봉합하고 나토의 결속을 강조할 것으로 보인다. 앞서 로이터통신은 이번 회의에서 공동선언을 통해 ‘유럽 또는 북미에서 한 회원국이 공격받으면 모든 회원국에 대한 공격으로 간주한다’는 나토 상호방위 조항 제5조를 재확인할 예정이라고 보도했다. 나토 회원국들은 이번 회의에서 트럼프 대통령의 요구대로 국방비 지출을 늘린 점을 부각할 것으로 보인다. 지난해 기준 미국을 제외한 나토 회원국들의 국방비 지출은 전년 대비 20% 증가한 5740억달러(약 880조원)이다. 독일마셜기금의 대서양 안보 전문가인 클라우디아 메이저는 “우려를 품은 각국 지도자들은 동맹이 여전히 견고하다는 메시지를 전달하려 한다”며 “트럼프 대통령을 달래고 나토의 필요성을 설득하기 위해 노력할 것”이라고 독일 공영방송 도이체벨레에 말했다. 볼로디미르 젤렌스키 우크라이나 대통령도 참석한 가운데 우크라이나 전쟁 문제도 이번 회의에서 주요하게 다뤄질 것으로 보인다. 또 미국과 이란의 종전 양해각서(MOU) 후속 협상과 관련해 호르무즈 해협을 둘러싼 해양 안보에서의 유럽 국가들 기여 방안도 논의될 수 있다.', 'crawl', '경향신문', '2026-07-06 21:22:01', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000193200016961.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:09.828541', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3151, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607062103005', 'https://www.khan.co.kr/article/202607062103005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '“애도 대신 복수”…이란 내 ‘반미 정서’ 둑 터졌다', '하메네이 장례식 사흘째 수백만명 운집…상징적 순교자 반열에연일 “킬 트럼프” 구호 쏟아낸 추모 행렬…지도부도 보복 시사분노의 ‘반트럼프’ 물결 이란 시민들이 6일(현지시간) 테헤란에서 열린 전 최고지도자 아야톨라 알리 하메네이의 장례식 사흘째 행사에 참석해 있다. ‘반트럼프’ 현수막이 눈에 띈다. 로이터연합뉴스아야톨라 알리 하메네이 이란 전 최고지도자의 장···', '하메네이 장례식 사흘째 수백만명 운집…상징적 순교자 반열에 연일 “킬 트럼프” 구호 쏟아낸 추모 행렬…지도부도 보복 시사 분노의 ‘반트럼프’ 물결 이란 시민들이 6일(현지시간) 테헤란에서 열린 전 최고지도자 아야톨라 알리 하메네이의 장례식 사흘째 행사에 참석해 있다. ‘반트럼프’ 현수막이 눈에 띈다. 로이터연합뉴스 아야톨라 알리 하메네이 이란 전 최고지도자의 장례식이 3일째를 맞은 6일(현지시간) 추모 행렬이 이란 테헤란 이맘 후세인 광장에서 아자디 광장으로 출발했다. 도심을 메운 붉은 깃발 사이에서 “미국·이스라엘에 죽음을” 구호가 터져 나왔다. 이란 지도부도 복수를 다짐하며 도널드 트럼프 미국 대통령 등을 향한 적대감을 숨기지 않았다. 미·이란 전쟁으로 축적돼온 반미 정서가 하메네이 장례식을 계기로 분출하고 있다. 이날 오전 하메네이와 가족의 시신이 실린 관이 이란 국기로 덮인 채 트럭에 실려 이동을 시작했다. 관이 실린 트럭 칸은 시아파 성지의 영묘 내부를 형상화한 격자 장식(하람)으로 만들었다. 추모 행렬에 참석한 인파는 수백만명에 달했다고 타스님통신이 보도했다. 조문객들은 트럭에 닿기 위해 손을 뻗거나, 스카프 등 소지품을 통제 요원에게 건네며 관에 닿도록 해달라고 요청했다. AP통신은 “관에 물건을 닿게 해 축복을 받는다는 의미”라고 설명했다. 장례 행사 사흘째에 군중의 반미 감정은 최고조에 달했다. ‘하메네이의 복수자들이여’ ‘후세인의 복수자들이여’라는 문구가 적힌 붉은 깃발이 이란 국기보다 더 빽빽하게 거리를 메웠다. 시아파의 대표적 순교자이자 저항의 상징인 이맘 후세인과 하메네이의 ‘순교’가 같은 반열에 올라선 것이다. 앞서 나타났던 ‘트럼프를 죽여라’ ‘피가 흐를 것’ 등의 문구는 물론, 불타는 성조기와 트럼프 대통령이 교수대에 오른 모습을 형상화한 모형도 등장했다. 현지 언론에서는 “피에는 피” “우리 지도자를 죽인 자를 왜 우리가 죽이면 안 되는가” 등 메시지가 신문 1면에 등장했다. AP통신은 하메네이의 죽음에 대한 보복을 요구하는 목소리가 점차 커지고 있다고 했다. 이란 지도부도 분노와 반감을 여과 없이 드러냈다. 이날 다시 사법부 수장으로 임명된 골람 호세인 모세니 에제이는 미국·이스라엘의 정치 지도자들에 대한 보복 의사를 밝히며 “단호하게 추적하고, 재판에 넘겨 처벌할 것이며, 반드시 응징할 것”이라고 말했다. 모하마드 모크베르 이란 최고지도자 고문은 “(살인자들은) 자연사하지 않을 것”이라고 말했다. “피의 복수는 당국의 의무” “애도가 아닌, 복수가 필요하다” 등 적나라한 표현이 각계 지도층에서 쏟아져 나왔다. 모즈타바 하메네이 이란 최고지도자는 이날도 모습을 드러내지 않았다. 테헤란을 가득 메운 인파는 이란이 미국 등 서방에 보내는 강력한 메시지다. 전쟁 발발 직후 트럼프 대통령이 이란 정권 교체를 시사하며 이란 국민에게 봉기를 촉구한 것에 대한 이란의 응답이라는 분석이다. 전쟁 후 수백만명의 군중을 동원할 수 있는 정치적 자원과 행정력, 내부 통제와 결집을 안팎에 과시하는 효과도 있다. 발리 나스르 미국 존스홉킨스대 교수는 엑스에 “테헤란은 미국이 위성으로 군중 규모를 감시한다는 사실을 알고 있다”며 “이란이 곧 무너지리라 생각했던 워싱턴을 향한 메시지”라고 평가했다. 파테메 모하제라니 이란 정부 대변인은 “장례식에 모인 수많은 인파는 이란의 힘, 위엄, 권위를 보여주는 한 사례”라고 했다. 장례식은 이란 중부 성지 도시 곰, 이라크의 시아파 성지 나자프와 카르발라를 거쳐 오는 9일 이란 마슈하드의 이맘 레자 성지에서 안장과 함께 끝난다. 이 기간에 도로와 공항이 통제된다. 일부 지역에서는 영화관 내 코미디 영화 상영이 제한됐다.', 'crawl', '경향신문', '2026-07-06 21:03:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000194600016741.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:11.654166', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3152, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607062102015', 'https://www.khan.co.kr/article/202607062102015/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '폐허 속 독립기념일 맞은 베네수, 사망자 3340여명으로', '현지 인권단체, 미국 등 지원 촉구“재건 비용에 약 57조원 필요 전망”단전·식량난 속 구조팀 일부 철수신원미상 시신 150구 매장 작업자들이 지난 5일(현지시간) 베네수엘라 라과이라주 카티아라마르에서 신원 불명의 지진 희생자들을 위한 묘지를 만들고 있다. AFP연합뉴스베네수엘라가 5일(현지시간) 연쇄 강진 피해 속에서 독립 215주년 기념일을 맞았다. 사···', '현지 인권단체, 미국 등 지원 촉구 “재건 비용에 약 57조원 필요 전망” 단전·식량난 속 구조팀 일부 철수 신원미상 시신 150구 매장 작업자들이 지난 5일(현지시간) 베네수엘라 라과이라주 카티아라마르에서 신원 불명의 지진 희생자들을 위한 묘지를 만들고 있다. AFP연합뉴스 베네수엘라가 5일(현지시간) 연쇄 강진 피해 속에서 독립 215주년 기념일을 맞았다. 사망자 수가 3340여명으로 증가한 가운데 수색 작업이 계속되고 있다. AFP통신 등 외신을 종합하면 호르헤 로드리게스 베네수엘라 국회의장은 지진 발생 11일째인 이날 지진 사망자가 3342명으로 집계됐다고 밝혔다. 부상자는 1만6740명으로 늘었다. 공식 실종자 수는 발표되지 않았지만 유엔은 최대 5만명이 실종된 것으로 추산했다. 수색·구조 작업을 벌이던 국제 구조팀 일부는 현장에서 철수했다. 라과이라주 카티아라마르의 에스페란사 공동묘지 인근에는 신원이 확인되지 않은 시신 150구가 매장됐다. 흰색 십자가가 일렬로 늘어선 무덤마다 사망일은 모두 지진이 발생한 6월24일로 새겨졌고, 그 위에 작은 꽃다발이 놓였다. 시민들은 가족을 찾는 노력을 멈추지 않고 있다. 카티아라마르에서 아들을 찾고 있는 줄리는 “아들의 오토바이와 헬멧을 찾았다”며 “아들 없이는 이곳을 떠날 수 없다”고 AFP에 말했다. 이재민의 고통도 심화하고 있다. 현지 매체 엘나시오날은 일부 지역은 여전히 전기가 끊긴 상태라고 전했다. 주민들은 위성 인터넷 스타링크의 안테나를 실은 트럭이 올 때에 한해 약 3분씩만 인터넷에 접속하는 것으로 알려졌다. 비축된 물과 식량도 바닥나고 있다. 주민들은 음식 조리는 물론 몸을 씻기도 어려운 상황으로 전해졌다. 베네수엘라 정부의 미흡한 대응에 주민 불만도 커지고 있다. 라과이라주에서 실종된 어머니를 찾는 한 남성은 당국이 중장비를 동원해 현장에 도착한 뒤 마치 도움을 준 것처럼 사진을 찍는다며 정부가 비극을 정치화하고 있다고 비판했다. 델시 로드리게스 임시 대통령은 이날 베네수엘라 독립 215주년 기념일을 맞아 열린 군사 행사에서 정부의 대응을 옹호하며 “어떠한 종류의 음모도 용납될 수 없다”고 말했다. 유엔개발계획의 신속 피해 평가에 따르면 베네수엘라는 이번 지진으로 약 67억달러(약 10조3000억원) 규모의 피해를 본 것으로 추산된다. 현지 인권단체 프로베아는 재건 비용이 베네수엘라 국내총생산(GDP)의 40%에 해당하는 총 370억달러(약 57조원) 필요할 것으로 전망했다. 프로베아는 로드리게스 정부를 지원하는 미국과 국제통화기금, 세계은행 등 다자기구에 재건 지원을 촉구했다. 레오 14세 교황은 “주님께서 큰 고난의 시기에 그들을 붙잡아주시길 바란다”며 희생자들을 추모했다.', 'crawl', '경향신문', '2026-07-06 21:02:01', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/l_2026070701000183900016721.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:13.586029', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3153, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607062102005', 'https://www.khan.co.kr/article/202607062102005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '나토에 무기 구매 압박…트럼프, 동맹에 계산서', '나토 회의서 ‘충성심’ 요구할 듯도널드 트럼프 미국 대통령이 7일(현지시간) 튀르키예 앙카라에서 개막하는 북대서양조약기구(나토) 정상회의에 참석해 미·이란 전쟁을 지원하지 않은 유럽 동맹국에 ‘충성심’을 요구하며 미국산 무기 구매를 압박할 것이란 전망이 나왔다.매슈 휘터커 나토 주재 미국 대사는 5일 기자들에게 “정상회의에서 국내총생산(GDP) 대비 5%를···', '나토 회의서 ‘충성심’ 요구할 듯 도널드 트럼프 미국 대통령이 7일(현지시간) 튀르키예 앙카라에서 개막하는 북대서양조약기구(나토) 정상회의에 참석해 미·이란 전쟁을 지원하지 않은 유럽 동맹국에 ‘충성심’을 요구하며 미국산 무기 구매를 압박할 것이란 전망이 나왔다. 매슈 휘터커 나토 주재 미국 대사는 5일 기자들에게 “정상회의에서 국내총생산(GDP) 대비 5%를 국방비로 지출하겠다는 나토 회원국의 약속 이행 상황을 점검할 것”이라며 “어떤 나라들은 많이 뒤처져 있다”고 했다. 또 “동맹국들이 지난해 약 1200억달러 국방비 지출을 약속하면서 그중 절반을 미국산 무기 구매에 투자하기로 한 것은 좋은 시작”이라고 했다. 트럼프 행정부는 나토 회원국의 방위비 증액과 유럽 내 미군 재배치를 미국산 무기 수출 확대로 연결하려 하고 있다. 행정부 고위 당국자는 “유럽 내 미군 배치와 주요 기지 현황을 포괄적으로 검토하고 있다”며 “이것이 우리 동맹들이 더 많은 역량을 갖추기 위해 국방비 강화 공약을 빨리 이행해야 하는 이유”라고 말했다. 앞서 피트 헤그세스 미 국방부 장관은 독일 주둔 미군 철수 계획과 폴란드 파병 취소를 발표한 바 있다. 폴리티코는 ‘미국은 어떻게 나토를 돈벌이 수단으로 삼고 있는가’란 제목의 기사에서 “한때 나토를 하나로 묶어줬던 유대감이 약화하면서 동맹이 공동의 이상보다 국가 이익에 따라 움직이는 형태로 변모하고 있다”고 지적했다. 트럼프 대통령은 미국 독립 250년 축하 전화를 건 블라디미르 푸틴 러시아 대통령과 85분가량 통화했다. 트럼프 대통령은 푸틴 대통령에게 “나토 정상회의에서 우크라이나 전쟁 해결책을 찾는 데 도움을 주겠다”고 밝힌 것으로 전해졌다. 유럽은 일단 미국의 요구에 발맞추는 모양새다. 마르크 뤼터 나토 사무총장은 지난달 미국을 방문해 “유럽이 3000억달러에 달하는 미국산 무기를 주문해 11만개의 미국 일자리를 창출할 것”이라고 트럼프 대통령에게 말했다. 영국과 독일도 미국산 무기를 라이선스 방식으로 자국에서 생산할 계획이라고 발표했다. 유럽의 한 외교관은 “유럽은 당분간 미국에 의존할 수밖에 없어 미국과 충돌하는 건 이익에 부합하지 않는다”며 “그러나 우리는 단호하게 미국에 유럽을 당연한 존재로 여겨선 안 된다는 걸 이해시킬 필요가 있다”고 했다.', 'crawl', '경향신문', '2026-07-06 21:02:00', '진보', 'ready', 'https://img.khan.co.kr/newsletter/c/300x200/228606/2026/3477438/83757_3477438_1783229307622425800.jpeg', '2026-07-07 06:04:25', '2026-07-07 15:47:15.670615', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3158, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607061631001', 'https://www.khan.co.kr/article/202607061631001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '수백만 운집한 하메네이 장례식 “트럼프에 복수해야”···반미 정서 최고조', '6일(현지시간) 이란 테헤란에서 열린 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식에서 참가자들이 도널드 트럼프 미국 대통령 등에게 복수해야한다는 내용의 표지판을 들고 있다. 로이터연합뉴스아야톨라 알리 하메네이 이란 전 최고지도자의 장례식이 3일째를 맞은 6일(현지시간) 추모 행렬이 이란 테헤란 이맘 후세인 광장에서 아자디 광장으로 출발했다. 도심을 ···', '6일(현지시간) 이란 테헤란에서 열린 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식에서 참가자들이 도널드 트럼프 미국 대통령 등에게 복수해야한다는 내용의 표지판을 들고 있다. 로이터연합뉴스 아야톨라 알리 하메네이 이란 전 최고지도자의 장례식이 3일째를 맞은 6일(현지시간) 추모 행렬이 이란 테헤란 이맘 후세인 광장에서 아자디 광장으로 출발했다. 도심을 메운 붉은 깃발 사이에서 “미국·이스라엘에 죽음을” 구호가 전날에 이어 터져 나왔다. 이란 지도부도 복수를 다짐하며 도널드 트럼프 미국 대통령 등을 향한 적대감을 숨기지 않았다. 미·이란 전쟁으로 축적돼온 반미 정서가 하메네이 장례식의 대규모 군중 밀집을 기화로 분출하는 모습이다. 이날 오전 하메네이와 가족의 시신이 실린 관이 이란 국기로 덮인 채 트럭에 실려 이동을 시작했다. 관이 실린 트럭 칸은 시아파 성지의 영묘 내부를 형상화한 격자 장식(하람)으로 만들었다. 이날 추모 행렬에 참석한 인파는 수백만명에 달한다고 타스님 통신이 보도했다. 트럭을 에워싼 조문객들은 트럭에 닿기 위해 손을 뻗거나, 스카프 등 소지품을 통제 요원에게 건네며 관에 닿도록 해달라고 요청했다. AP통신은 “관에 물건을 닿게 해 축복을 받는다는 의미”라고 설명했다. 이란 당국은 운구 차량이 10㎞의 경로를 약 10~12시간 정도 걸려 이동할 것이라고 예상했다. 3일째를 맞은 장례 행사에서 군중의 반미 감정은 최고조에 달했다. ‘하메네이의 복수자들이여’ ‘후세인의 복수자들이여’라는 문구가 적힌 붉은 깃발은 이란 국기보다 더 빽빽하게 거리를 메웠다. 시아파의 대표적 순교자이자 저항의 상징인 이맘 후세인과 하메네이의 ‘순교’가 같은 반열에 올라선 것이다. 앞서 나타났던 ‘트럼프를 죽여라’ ‘피가 흐를 것’ 등의 문구는 물론, 불타는 성조기와 트럼프 대통령이 교수대에 오른 모습을 형상화한 모형도 등장했다. 현지 언론에서는 “피에는 피” “우리 지도자를 죽인 자를 왜 우리가 죽이면 안 되는가” 등의 메시지가 신문 1면에 등장했다. AP통신은 하메네이의 죽음에 대한 보복을 요구하는 목소리가 점차 커지고 있다고 했다. 이란 지도부도 분노와 반감을 여과 없이 드러냈다. 이날 다시 사법부 수장으로 임명된 골람 호세인 모세니 에제이는 미국·이스라엘의 정치 지도자들에 대한 보복 의사를 밝히면서 “단호하게 추적하고, 재판에 넘겨 처벌할 것이며, 반드시 응징할 것”이라고 말했다. 모하마드 모크베르 이란 최고지도자 고문은 장례행사에서 “(살인자들은) 자연사하지 않을 것”이라며 “이란 국민과 체제가 복수할 것”이라고 말했다. “피의 복수는 당국의 의무” “애도가 아닌, 복수가 필요하다” 등 날 것의 표현들이 각계 지도층에서 쏟아져 나왔다. 모즈타바 하메네이 이란 최고지도자는 이날도 모습을 드러내지 않았다. 6일(현지시간) 아야톨라 알리 하메네이 전 이란 최고지도자의 장례 행사가 열린 이란 테헤란 도심에 참가자들이 모여들고 있다. 로이터연합뉴스 테헤란을 가득 메운 인파는 이란이 미국 등 서방에 보내는 강력한 메시지다. 미·이란 전쟁 발발 직후 트럼프 대통령이 정권 교체를 시사하며 이란 국민에게 봉기를 촉구한 것에 대한 이란의 대답이라는 분석이다. 전쟁 직후 수백만명의 군중을 동원할 수 있는 정치적 자원과 행정력, 내부 통제와 결집을 안팎에 과시하는 효과도 있다. 발리 나스르 미국 존스홉킨스대 교수는 “테헤란은 미국이 위성으로 군중 규모를 감시한다는 사실을 알고 있다”며 “이란이 대중 봉기에 앞서 무너지리라 생각하는 워싱턴을 향한 메시지”라고 평가했다. 파테메 모하제라니 이란 정부 대변인은 “장례식에 모인 수많은 인파는 이란의 힘, 위엄, 권위를 보여주는 한 가지 사례”라고 강조했다. 장례 의식은 이란 중부 성지 도시 곰, 이라크의 시아파 성지 나자프와 카르발라를 거쳐 오는 9일 이란 마슈하드의 이맘 레자 성지에서 안장과 함께 끝난다. 이 기간에 도로와 공항이 통제된다. 일부 지역에서는 영화관 내 코미디 영화 상영이 제한됐다.', 'crawl', '경향신문', '2026-07-06 16:31:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260706.PRU20260706384101009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:24.916923', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3159, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607061616001', 'https://www.khan.co.kr/article/202607061616001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '미·유럽 분열 커진 나토, 정상회의 개막···나토 향방 어떻게 논의될까', '경찰들이 5일(현지시간) 튀르키예 앙카라에서 열리는 북대서양조약기구(나토) 정상회의를 앞두고 현수막 앞에서 순찰하고 있다. AP연합뉴스북대서양조약기구(나토) 연례 정상회의가 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 열린다. 도널드 트럼프 미국 행정부가 나토 탈퇴 가능성 등을 거론하며 회원국들과 신뢰에 균열을 내고 있는 가운데 이번 정상회의에서 나···', '경찰들이 5일(현지시간) 튀르키예 앙카라에서 열리는 북대서양조약기구(나토) 정상회의를 앞두고 현수막 앞에서 순찰하고 있다. AP연합뉴스 북대서양조약기구(나토) 연례 정상회의가 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 열린다. 도널드 트럼프 미국 행정부가 나토 탈퇴 가능성 등을 거론하며 회원국들과 신뢰에 균열을 내고 있는 가운데 이번 정상회의에서 나토의 향후 방향성이 어떻게 논의될 것인지 주목된다. 이번 나토 정상회의는 미국의 그린란드 병합 추진과 대이란전쟁 등으로 미국과 나토 회원국들의 갈등이 극에 달한 시점에서 이뤄지게 됐다. 트럼프 대통령은 나토 회원국들이 국방비를 충분히 분담하지 않고 미국에 의존한다며 이들 국가를 비난해왔다. 미국과 나토의 갈등이 본격적으로 드러난 것은 트럼프 대통령이 군사력을 동원해서라도 그린란드를 병합하겠다는 야망을 드러낸 지난 1월부터다. 당시 미국의 강제 병합 가능성을 우려한 일부 나토 회원국은 그린란드에 병력을 파견하면서 긴장이 고조됐다. 지난 2월28일 대이란 전쟁이 발발한 후 나토 회원국들과 트럼프 행정부의 충돌은 더욱 거세졌다. 트럼프 대통령은 이란을 공습한 후 나토 가입국을 포함한 동맹국들에 군함 파견과 미군의 기지 사용 등 전쟁 동참을 요청했으나 대부분의 국가는 이를 거부했다. 이에 트럼프 대통령은 나토를 탈퇴하고 유럽에 주둔한 미군을 철수하겠다며 압박 수위를 높였다. 나토 정상들은 이번 회의에서 한발 물러서 갈등을 일정 부분 봉합하고 나토의 결속을 강조할 것으로 보인다. 앞서 로이터 통신은 이번 정상회의에서 공동선언문을 통해 ‘유럽 또는 북미에서 한 회원국이 공격받으면 모든 회원국에 대한 공격으로 간주한다’는 나토 상호방위 조항 제5조를 재확인할 예정이라고 보도했다. 나토 회원국들은 트럼프 대통령의 압력에 따라 국방비 지출을 늘려왔다. 이번 회의에서 트럼프 행정부에 이러한 노력을 강조할 것으로 보인다. 매슈 휘터커 나토 주재 미국 대사는 나토 정상회의에서 유럽 동맹국들의 국방비 증액 약속 이행을 점검할 계획이라고 5일 밝히기도 했다. 나토 32개국은 지난해 2035년까지 국방비를 국내총생산(GDP)의 5%로 증액하기로 합의했다. 지난해 기준 미국을 제외한 나토 회원국들의 국방 지출은 전년 대비 20% 증가한 5740억달러(약 836조7500억원)에 이른다. 싱크탱크 독일마셜기금의 대서양 안보 전문가인 클라우디아 메이저는 “우려를 품은 각국 지도자들은 (나토) 동맹이 여전히 견고하다는 메시지를 전달하려 한다”며 “트럼프 대통령을 달래고 나토의 필요성을 설득하기 위해 노력할 것”이라고 독일 공영방송 도이치벨레에 말했다. 한편 미국에 대한 의존을 낮추고 국가 방위에 있어 자체적인 안보 역량을 강화해야 한다는 공감대도 논의될 것이라는 관측도 나온다. AFP통신은 “나토 내부에서 미국의 역할 축소는 불가피하며 이는 트럼프 대통령의 퇴임 이후에도 계속될 것이라는 인식이 확산하고 있다”고 전했다. 이란·우크라이나 문제도 이번 정상회담에서 주요한 의제로 다뤄질 것으로 보인다. 현재 진행 중인 미국과 이란의 종전 후속협상과 관련, 호르무즈 해협을 둘러싼 해양 안보에서의 유럽 국가들의 기여 방안 등이 논의될 수 있다고 외신들은 짚었다. 볼로디미르 젤렌스키 우크라이나 대통령은 8일 앙카라에서 트럼프 대통령과 양자 회담을 가질 예정이다.', 'crawl', '경향신문', '2026-07-06 16:16:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260706.PAP20260706042001009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:26.926102', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3160, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607061615021', 'https://www.khan.co.kr/article/202607061615021/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '지진 잔해 속 독립 기념일 맞은 베네수엘라···사망자 3340명대로 증가', '신원 미상 시신 150구 매장돼피해 복구비, 최대 GDP 40% 전망연쇄 강진으로 큰 피해를 본 베네수엘라 라과이라주에서 5일(현지시간) 무너진 건물 잔해 위로 국기가 휘날리고 있다. 로이터연합뉴스베네수엘라가 5일(현지시간) 연쇄 강진 피해 속에서 독립 215주년 기념일을 맞았다. 사망자 수가 3340여명으로 증가한 가운데 수색 작업과 함께 시신 수습 작업···', '신원 미상 시신 150구 매장돼 피해 복구비, 최대 GDP 40% 전망 연쇄 강진으로 큰 피해를 본 베네수엘라 라과이라주에서 5일(현지시간) 무너진 건물 잔해 위로 국기가 휘날리고 있다. 로이터연합뉴스 베네수엘라가 5일(현지시간) 연쇄 강진 피해 속에서 독립 215주년 기념일을 맞았다. 사망자 수가 3340여명으로 증가한 가운데 수색 작업과 함께 시신 수습 작업도 본격화하고 있다. AFP통신 등 외신을 종합하면 호르헤 로드리게스 베네수엘라 국회의장은 이날 지진으로 인한 사망자 수가 전날보다 388명 증가한 3342명으로 집계됐다고 밝혔다. 부상자 수는 1만6740명으로 늘었다. 공식 실종자 수는 발표되지 않은 가운데 유엔은 최대 5만명이 실종된 것으로 추산했다. 민간에서 운영하는 실종자 신고 웹사이트에서 연락이 닿지 않는 실종자 수는 3만1000명 이상으로 비공식 집계됐다. 지진 발생 11일째인 이날 수색·구조 작업을 벌이던 국제 구조팀 일부는 현장에서 철수했다. 라과이라주 카티아 라마르의 라에스페란사 공동묘지 인근에는 신원이 확인되지 않은 시신 150구가 매장됐다. 흰색 십자가가 일렬로 늘어선 무덤마다 사망일은 모두 지진이 발생한 6월24일로 새겨져 있었고, 그 위에는 작은 꽃다발이 놓여 있었다고 AFP는 전했다. 한편 지역 주민들은 건물 잔해 속에서 가족을 찾는 노력을 멈추지 않고 있다. 카티아 라마르에서 아들을 찾고 있는 줄리는 “아들의 오토바이와 헬멧을 찾았다”며 “아들이 살아있다고 믿는다. 설령 살아있지 않더라도 아들을 찾아서 볼 수 있을 것”이라고 AFP에 말했다. 그는 “아들 없이는 이곳을 떠날 수 없다”고 덧붙였다. 베네수엘라 라과이라주 카티아 라마르의 라에스페란사 공동묘지에서 5일(현지시간) 신원이 확인되지 않은 사망자들의 무덤이 조성돼 있다. AFP연합뉴스 이재민들의 고통도 심화하고 있다. 전력 공급의 90%가 복구됐다는 로드리게스 국회의장의 주장과 달리 일부 지역은 여전히 전기가 끊긴 상태라고 현지 매체 엘나시오날은 전했다. 통신망이 끊긴 상황에서 주민들은 위성 인터넷 스타링크의 안테나를 실은 트럭이 올 때에 한해 약 3분씩만 인터넷에 접속하는 것으로 알려졌다. 비축해둔 물과 식량도 바닥나고 있다. 주민들은 음식 조리는 물론 몸을 씻기도 어려운 상황으로 전해졌다. 게다가 무너진 건물들이 무방비 상태로 방치되면서 약탈 등 치안 불안도 커지고 있다. 델시 로드리게스 임시 정부의 미흡한 재난 대응에 대한 주민 불만도 커지고 있다. 라과이라주에서 실종된 어머니를 찾는 한 남성은 “정부가 투입한 일부 중장비는 간헐적으로만 가동되고 있으며, 일부는 며칠째 멈춰 서 있다”고 엘나시오날에 말했다. 그는 당국이 중장비를 동원해 현장에 도착한 뒤 마치 도움을 준 것처럼 사진을 찍는다며 정부가 비극을 정치화하고 있다고 비판했다. 로드리게스 임시 대통령은 이날 베네수엘라 독립 215주년 기념일을 맞아 열린 군사 행사에서 관련 비판에 대해 “오늘날 베네수엘라 기관들을 공격하려는 시도”로 규정했다. 그는 정부의 대응을 옹호하며 “어떠한 종류의 음모도 용납될 수 없다”고 주장했다. 유엔개발계획의 신속 피해 평가에 따르면 베네수엘라는 이번 지진으로 약 67억달러(약 10조3000억원) 규모의 물리적 피해를 본 것으로 추산된다. 현지 인권단체 프로베아는 이날 물리적 피해와 재건 비용을 합하면 총 370억달러(약 57조원)가 필요할 것으로 전망했다. 이는 현재 베네수엘라 국내총생산(GDP)의 약 40%에 해당하는 규모다. 프로베아는 로드리게스 정부를 지원하는 미국과 국제통화기금, 세계은행 등 다자기구에 재건 지원을 촉구했다. 레오 14세 교황은 이날 “주님께서 큰 고난의 시기에 그들을 붙잡아 주시길 바란다”며 희생자들을 추모했다. 수도 카라카스에 있는 베네수엘라 중앙대학교에서는 추모 행사 ‘베네수엘라를 위한 빛’이 열렸다. 학생과 교수들은 바닥에 놓인 대형 국기 주변으로 촛불을 밝히며 지진 희생자들을 기렸다. 베네수엘라 수도 카라카스에서 5일(현지시간) 연쇄 강진 희생자를 기리는 촛불 추모식이 열리고 있다. AP연합뉴스', 'crawl', '경향신문', '2026-07-06 16:15:02', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260706.PRU20260706208801009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:28.905576', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3164, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607061301001', 'https://www.khan.co.kr/article/202607061301001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '트럼프, 나토정상회의서 수조 원 무기 세일즈 나설 듯···“동맹 아닌 돈벌이 수단”', '마르크 뤼터 나토 사무총장(왼쪽)과 도널드 트럼프 미국 대통령. 로이터연합뉴스도널드 트럼프 미국 대통령이 오는 7일(현지시간) 개막하는 북대서양조약기구(나토) 정상회의에 참석해 미·이란 전쟁을 지원하지 않은 유럽 동맹국에 ‘충성심’을 요구하며 미국산 무기 구매를 압박할 것이란 전망이 나왔다. 튀르키예 앙카라에서 열리는 이번 나토 정상회의는 그린란드 갈등과 ···', '마르크 뤼터 나토 사무총장(왼쪽)과 도널드 트럼프 미국 대통령. 로이터연합뉴스 도널드 트럼프 미국 대통령이 오는 7일(현지시간) 개막하는 북대서양조약기구(나토) 정상회의에 참석해 미·이란 전쟁을 지원하지 않은 유럽 동맹국에 ‘충성심’을 요구하며 미국산 무기 구매를 압박할 것이란 전망이 나왔다. 튀르키예 앙카라에서 열리는 이번 나토 정상회의는 그린란드 갈등과 미·이란 전쟁을 거치며 대서양 동맹의 균열이 어느 때보다 커진 가운데 개최된다. 매슈 휘터커 나토 주재 미국 대사는 5일 기자들에게 “앙카라 정상회의에서는 국내총생산(GDP) 대비 5%를 국방비로 지출하겠다는 나토 회원국의 약속 이행 상황을 점검할 것”이라면서 “어떤 나라들은 많이 뒤처져 있다”고 경고했다. 그러면서 그는 “동맹국들이 지난해 약 1200억달러에 달하는 국방비 지출을 약속하면서 그중 절반을 미국산 무기에 투자하기로 한 것은 좋은 시작”이라고 말했다. 트럼프 행정부는 나토 회원국의 방위비 증액과 유럽 내 미군 재배치를 미국산 무기 수출 확대로 연결하는 것을 목표로 삼은 것으로 보인다. 트럼프 행정부 고위당국자는 “유럽 내 미군 배치와 주요 기지 현황에 대한 포괄적 검토가 이뤄지고 있으며, 이것이 우리 동맹들이 더 많은 역량을 갖추기 위해 국방비 강화 공약을 빨리 이행해야 하는 이유”라고 말했다. 앞서 피트 헤그세스 미 국방부 장관은 독일 주둔 미군 철수 계획과 폴란드 파병 취소를 발표하면서 나토 동맹국들을 압박한 바 있다. 한 고위 당국자는 “이번 정상회의 기간 수십억달러 규모의 미국산 무기 판매 계약이 있을 예정”이라고 말했다. 폴리티코는 ‘미국은 어떻게 나토를 돈벌이 수단으로 삼고 있는가’란 제목의 기사에서 “동맹에 대한 미국의 이 같은 거래적 접근은 이번 나토 정상회의에서 러시아에 맞선 나토 동부전선 방어 강화 등에 대한 논의를 (주변부로) 밀어낼 위험이 있다”며 “한때 나토를 하나로 묶어줬던 유대감이 약화하면서 동맹이 공동의 이상보다 국가적 이익에 따라 움직이는 형태로 변모하고 있다”고 지적했다. 트럼프 대통령은 이날 미국 독립 250년 축하 전화를 건 블라디미르 푸틴 러시아 대통령과 85분가량 통화하며 친분을 과시하기도 했다. 트럼프 대통령은 푸틴 대통령에게 “나토 정상회의에서 우크라이나 전쟁 해결책을 찾는 데 도움을 주겠다”는 의사를 밝힌 것으로 전해졌다. 유럽은 일단 미국의 요구에 발맞추는 모양새다. 마르크 뤼터 나토 사무총장은 지난달 미국을 방문해 “유럽이 3000억달러에 달하는 미국산 무기를 주문해 11만 개의 미국 일자리를 창출할 것”이라고 트럼프 대통령에게 말했다. 영국과 독일도 미국산 무기를 라이선스 방식으로 자국에서 생산할 계획이라고 발표했다. 그러나 트럼프 대통령이 이에 만족할지는 미지수다. 그는 뤼터 사무총장의 방위비 증액 계획에도 시큰둥한 반응을 보이며 나토 동맹들이 대이란 전쟁에 참여하지 않은 것에 대한 실망감을 드러낸 바 있다. 트럼프 대통령은 “우리는 그들의 돈이 필요하지 않다. 내가 원하는 것은 충성심뿐”이라고 말했다. 유럽의 한 외교관은 폴리티코에 “유럽은 당분간 미국에 의존할 수밖에 없기 때문에 미국과 충돌하는 것은 우리의 이익에 부합하지 않는다”면서도 “그러나 우리는 단호한 방식으로 미국에 유럽을 당연한 존재로 여겨서는 안 된다는 점, 우리에게도 우리의 이익이 중요하다는 점을 이해시킬 필요가 있다”고 말했다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-06 13:01:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260706.424510b25a504252a49775a416c8f402_P1.png', '2026-07-07 06:04:25', '2026-07-07 15:47:38.343661', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3168, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607060912001', 'https://www.khan.co.kr/article/202607060912001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '하메네이 장례식에 ‘미나브초교’ 희생자 유가족 참석···반미 정서 상징으로', '한 남성 어깨 위에 앉은 소녀가 지난 5일(현지시간) 이란 테헤란 그랜드 모살라 모스크에서 열린 이란 전 최고지도자 아야톨라 하메네이의 장례식에서 주먹을 쥐고 소리치고 있다. AP연합뉴스아야톨라 하메네이 이란 전 최고지도자의 장례식에 미국과 이스라엘의 공습으로 희생된 미나브초등학교 희생자 유가족 등이 참석했다.워싱턴포스트(WP)는 5일(현지시간) 테헤란 그···', '한 남성 어깨 위에 앉은 소녀가 지난 5일(현지시간) 이란 테헤란 그랜드 모살라 모스크에서 열린 이란 전 최고지도자 아야톨라 하메네이의 장례식에서 주먹을 쥐고 소리치고 있다. AP연합뉴스 아야톨라 하메네이 이란 전 최고지도자의 장례식에 미국과 이스라엘의 공습으로 희생된 미나브초등학교 희생자 유가족 등이 참석했다. 워싱턴포스트(WP)는 5일(현지시간) 테헤란 그랜드 모살라 모스크에서 열린 하메네이의 장례식에 미국·이스라엘의 대이란 공습으로 자녀를 잃은 미나브 초등학교 유가족 등 수만명의 조문객이 참석했다고 보도했다. 미나브 여자초등학교는 미국과 이스라엘의 이란 전쟁 개전 첫날인 지난 2월28일 공습을 받아 최소 175명의 민간인이 사망했으며 희생자 대다수가 학생이었다. WP에 따르면 이 공습은 미군 토마호크 미사일에 의한 것으로 추정되나 미국은 아직 책임을 인정하지 않았고, 국방부가 조사에 착수한다고 밝힌 지 4개월이 넘도록 조사 결과도 발표하지 않은 상태다. WP는 자체 취재와 영상 증거를 통해 해당 학교가 미군 타격 목표 리스트에 포함돼 있었다고 보도했다. 미나브 공습은 하메네이가 거처에서 가족·고위 관료들과 함께 폭사한 날과 같은 날 발생했다. 유가족들은 약 1287㎞를 기차·차량·버스로 이동해 장례식장에 도착했다고 WP는 전했다. 아들을 잃은 한잘레 살레히는 “이란 국민이 어떻게 다뤄지는지 전 세계가 알아야 한다”고 말했다. 테헤란 국제공항 등 도심 곳곳에는 미나브 희생 어린이들을 추모하는 책가방·꽃·신발 조형물이 설치됐다. 이날 장례기도에는 마수드 페제시키안 이란 대통령과 미국과의 협상을 이끌고 있는 모하마드 바게르 갈리바프 국회의장도 참석했다. 강경파 수장이자 미국과의 협상에 막후 영향력을 발휘한 것으로 알려진 아흐마드 바히디 혁명수비대(IRGC) 신임 사령관도 모습을 드러냈다. 그가 공개 석상에서 모습을 드러낸 건 전쟁 개시 후 처음이다. 바히디가 등장하자 군중 일부에서 “바히디! 복수!”라는 구호가 터져나왔다. WP는 전쟁 이후 최대 규모의 고위 관료 공개 집결로 평가된다고 분석했다. 반면 하메네이의 아들이자 후계자로 지목된 모즈타바 하메네이 이란 최고지도자는 안전 문제 등을 이유로 장례기도에 나타나지 않았다. 대신 하메네이의 다른 세 아들이 참석했으며, 후계자 선출기구인 전문가회의 위원 자파르 소바니가 기도를 주관했다고 WP는 전했다. 하메네이 유해는 공개 참배와 대규모 운구 행렬을 거쳐 이슬람 학문 중심지 곰으로 이동한 뒤, 이라크 나자프·카르발라를 거쳐 최종적으로 고향 마슈하드에 안장될 예정이다. WP는 이번 취재가 이란 정부 초청으로 이뤄졌으며 정부 측 가이드·통역이 동행하는 제한된 조건 하에 진행됐다고 밝혔다. 지난 3월3일(현지시간) 이란 남부 도시 미나브에서 미·이스라엘의 초등학교 공습 가정에서 사망한 초등학교 어린이들의 장례식 도중 조문객들이 무덤을 파고 있다. 이란적신월사·UPI연합뉴스 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-06 09:12:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260706.PAP20260706066001009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:45.702935', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3169, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607060801001', 'https://www.khan.co.kr/article/202607060801001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '트럼프 “폭풍우에 독립기념일 행사 취소됐지만 내가 뒤집어”', '도널드 트럼프 미국 대통령이 지난 4일(현지시간) 250주년 독립기념일을 맞아 워싱턴DC 내셔널몰에서 열린 행사에서 주먹을 쥐어보이며 인사하고 있다. EPA연합뉴스도널드 트럼프 미국 대통령은 5일(현지시간) 미국의 독립 250주년 기념일 행사가 폭풍우로 취소됐다가 자신의 결정으로 재개될 수 있었다고 밝혔다.트럼프 대통령은 이날 소셜미디어 트루스소셜을 통해 ···', '도널드 트럼프 미국 대통령이 지난 4일(현지시간) 250주년 독립기념일을 맞아 워싱턴DC 내셔널몰에서 열린 행사에서 주먹을 쥐어보이며 인사하고 있다. EPA연합뉴스 도널드 트럼프 미국 대통령은 5일(현지시간) 미국의 독립 250주년 기념일 행사가 폭풍우로 취소됐다가 자신의 결정으로 재개될 수 있었다고 밝혔다. 트럼프 대통령은 이날 소셜미디어 트루스소셜을 통해 독립기념일 당일인 전날 오후 7시5분 기준 워싱턴DC 내셔널몰 일대에 42만4000명의 인파가 모였지만 악천후로 행사가 취소되고 사람들이 대피해야 했다고 말했다. 이어 “행사가 취소됐다는 소식을 듣자 나는 즉시 그 결정을 뒤집었고, 사람들이 다시 돌아올 시간을 주기 위해 잠시 기다렸다”며 “믿기 어렵게도 최소 15만명이 돌아왔고, 그 덕분에 행사는 원래 예정대로 진행됐을 때보다도 더 장관을 이뤘다”고 말했다. 트럼프 대통령은 관람객들의 대피와 신속한 재입장을 지원한 비밀경호국(SS)과 법 집행기관의 대응을 치하했다. 또 “위대한 불꽃놀이가 끝난 직후부터 폭우가 쏟아져 이 놀라운 밤이 더욱 극적으로 마무리됐다”고 덧붙였다. 4일 워싱턴DC에서 진행된 건국 250주년 행사는 섭씨 40도에 육박하는 폭염 속에 뇌우 예보까지 나오며 한때 중단됐다. 대피령이 내려지자 야외 행사장 등에 모여 있던 관람객들은 인근 건물 등으로 몸을 피했다가 오후 9시가 넘어서야 주최측의 행사 재개 안내에 따라 다시 행사장으로 돌아왔다. 트럼프 대통령의 연설은 예정보다 약 1시간 30분 늦은 오후 11시 15분쯤 시작됐으며, 세계 최대 규모 기록 경신에 도전한 불꽃놀이는 트럼프 대통령의 연설이 끝난 직후 자정 무렵 시작됐다. 지난 5일(현지시간) 미국 워싱턴DC 워싱턴기념탐에 250주년 독립기념일을 축하하기 위한 불꽃놀이를 보기 위해 인파가 몰려들었다. EPA연합뉴스', 'crawl', '경향신문', '2026-07-06 08:01:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/rcv.YNA.20260705.PEP20260705221201009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:47.64927', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3172, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607060600091', 'https://www.khan.co.kr/article/202607060600091/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '[베네수 강진] 굿네이버스 대응단장 “폭탄이 투하된 듯한 모습···구호품 반입 절차 마련 시급”', '박성락 굿네이버스 베네수엘라 긴급구호 대응단장이 3일(현지시간) 오전 베네수엘라 수도 카라카스에서 경향신문과 화상 인터뷰를 진행하고 있다. 최경윤 기자“마치 전쟁 상황에서 폭탄이 투하된 것 같은 모습입니다. 한 달 같은 사흘째입니다.” 지난 1일(현지시간) 베네수엘라에 입국해 긴급구호 활동을 벌이고 있는 박성락 굿네이버스 베네수엘라 긴급구호 대응단장은 3일···', '박성락 굿네이버스 베네수엘라 긴급구호 대응단장이 3일(현지시간) 오전 베네수엘라 수도 카라카스에서 경향신문과 화상 인터뷰를 진행하고 있다. 최경윤 기자 “마치 전쟁 상황에서 폭탄이 투하된 것 같은 모습입니다. 한 달 같은 사흘째입니다.” 지난 1일(현지시간) 베네수엘라에 입국해 긴급구호 활동을 벌이고 있는 박성락 굿네이버스 베네수엘라 긴급구호 대응단장은 3일 경향신문과의 화상 인터뷰에서 참혹한 현지 상황을 이같이 전했다. 지난달 24일 발생한 연쇄 강진으로 베네수엘라에서는 사망자가 3000명에 육박했고 유엔은 실종자가 5만~6만명에 이를 것으로 추산하고 있다. 박 단장은 정부가 신속하게 구호품 반입 절차를 마련하지 않으면 생존자 지원에도 차질이 불가피하다며 “재건과 복구의 속도 역시 정부의 컨트롤에 달려 있다”고 말했다. 다음은 박 단장과의 일문일답. - 현재 지진 피해 지역 상황은. “수도 카라카스는 빌딩 3~4채가 무너졌지만 그나마 괜찮은 편이다. 북쪽 항구 도시인 라과이라 지역은 폐허가 됐다. 마치 전쟁 상황에서 폭탄이 투하된 것 같은 모습이다. 일부 생존자 수색이 끝난 건물 외벽에는 빨간색 페인트로 ‘사망(Deceased)’을 뜻하는 ‘D’ 표시가 남아 있다. 수색이 완료된 건물에는 굴착기가 들어와 잔해를 걷어내고 있다. 정말 안타까운 점은 가족들이 그 주변을 지키고 있단 점이다. 울부짖는 게 아니라 말없이 앉아서 지켜보는데, 구출이 어려운 상황에서 곁을 지키는 모습에 마음이 아팠다. 폐허가 된 건물 외벽에 ‘딸을 찾습니다’라는 전단을 붙여둔 모습도 봤는데 부모로 보이는 사람이 옆에 앉아있었다.” 지난 1일(현지시간) 베네수엘라 수도 카라카스에서 무너진 건물 외벽에 실종자 수색 전단이 부착돼 있다. 굿네이버스 제공 - 여전히 거리에서 밤을 지새우는 주민이 많은가. “공식 셸터가 운영되고는 있지만 아직 식량이나 식수, 의료서비스가 충분히 제공되지 않아 주민들이 굳이 셸터를 선택할 이유가 크지 않은 상황이다. 운동장이나 공터, 거리에서 생활하는 주민들도 여전히 많다.” - 전염병 등 보건 상황에 대한 우려도 나온다. “재난 발생 이후 환경 자체가 오염되다 보니 수인성 질병과 호흡기 질환 등 질병 발생 위험이 높다. 기후도 중요한 요인인데, 현재 베네수엘라는 우기가 시작돼 일교차가 매우 큰 상황이다. 낮에는 매우 덥고 저녁에는 매우 춥다. 비가 오고 나면 기온도 뚝 떨어져 감기와 호흡기 질환 등도 우려된다.” - 구호 활동은 어떤 방식으로 이뤄지고 있나. “현지 단체들과 협력해 전날 650가정에 식량과 위생용품 등을 전달했다. 배분 과정에서 발생할 수 있는 불상사 및 치안 문제를 막기 위해 픽업트럭 두 대 분량씩 구호물자를 전달하고 있다. 아동을 대상으로 심리적 트라우마 지원 사업도 할 계획이다.” - 구호 인력과 물자 반입에 어려움은 없나. “카라카스 인근 국제공항은 아직 폐쇄 상태다. 구호 인력은 카라카스에서 콜롬비아 국경 쪽으로 약 120㎞ 떨어져 있는 발렌시아 공항을 통해 들어오고 있다. 나도 엊그제 그곳을 통해 왔는데 비행기에는 조끼 입은 구호 인력들이 대부분이었다. 하지만 물류 쪽에서는 애를 먹고 있다. 라과이라 항만도 사실상 폐쇄된 상태라 물자는 대부분 현장에서 구매해야 해서 대량 조달이 어렵다. 최근 일부 상점에서는 물건 구매 시 여권을 제시하도록 하는 등 통제가 시작된 모습이다.” - 현지 조달 물자가 고갈될 우려는 없나. “있다. 그래서 현지 구호단체 대부분이 해외에서 물자를 들여오기 위해 준비하고 있다. 굿네이버스도 파나마에 있는 UNHRD(유엔 세계식량계획이 운영하는 인도적 지원 물류센터)에 위탁 보관 중인 물류가 있다. UNHRD 측에서 전세기를 띄워 물자를 보내려고 하는데, 베네수엘라 정부가 통관 절차를 아직 정하지 못해 들여오지 못하고 있다. 베네수엘라 정부가 수입 절차에 대한 프로토콜이 없어서 미국과 유럽 측에서도 어려움을 겪고 있다고 들었다.” - 피해 현장 진입에 어려움은 없었나. “라과이라 지역에 들어가기 위해서는 정부의 특별 허가가 필요한 상황이다. 이틀 전에 최대 피해 지역에 들어가려 했는데 팀원 중 일부가 정부 허가가 나오지 않아 진입하지 못했다. 현재는 현지 파트너와 협력해 승인을 받은 상황이다.” 박성락 굿네이버스 베네수엘라 긴급구호 대응단장이 3일(현지시간) 오전 경향신문과의 화상 인터뷰 도중 베네수엘라 정부로부터 받은 구호 활동 허가서를 펼쳐 보이고 있다. 최경윤 기자 - 베네수엘라 정부의 재난 대응이 어떤가. “단적인 예를 들면 현재 지진 발생 1주일이 지났지만 구호 사업을 조율하는 클러스터 미팅이 마련되지 않았다. 보통 재난 상황이 발생하면 정부 컨트롤이 작동하는 국가의 경우 재난안전청과 같은 조직에서 재난 정보 수집·현장 조사 등을 통해 구호 희망 단체들에 단체별 전문성을 살린 역할을 배분한다. 아이티와 같이 정부 컨트롤이 약한 국가의 경우 UNOCHA(유엔인도주의업무조정국) 등에서 이런 클러스터 미팅을 진행한다. 이는 단체 간 중복 지원과 과다 경쟁을 막는 데 필요한 과정이다. 하지만 현재 베네수엘라는 회의가 조직조차 되지 않은 것으로 안다.” - 피해 복구에 있어 중요한 과제는 무엇인가. “관건은 사람들이 얼마나 빨리 회복하는가다. 중요한 요소 중 하나는 정부의 신속한 컨트롤 역량이다. 2010년 아이티 지진과 칠레 지진 당시 구호 상황을 비교해보면, 국가 자체가 어려웠던 아이티는 10년이 지나도 사회 재건 효과가 크지 않았던 반면 칠레의 경우 6개월~1년 만에 상당수 회복할 수 있었다. 재건 복구 시간은 정부의 장악력에 달려 있다. 베네수엘라가 겪어 온 경제·정치·사회적 불안 요소를 고려했을 때 이번 지진은 자연재해를 넘어 복합적 요인에 의한 장기적 피해로 이어질 가능성이 우려된다.” - 현재 가장 시급한 과제는 무엇인가. “식량과 의류, 비누, 생리대 등 초기 물품 지원이다. 현재 카라카스 피해 지역에서는 주민들이 자발적으로 운영하는 구호 물품센터 4~5곳이 운영되고 있다. 대학생과 할아버지, 할머니가 텐트에 앉아 계시고 구조 대원들에게 물과 따뜻한 음식을 제공하고 있다. 주민들이 십시일반으로 물과 음식을 갖다주면, 필요한 사람들이 가져가는 구조로 운영되고 있다. 이재민들이 장기적으로 거주할 수 있는 셸터와 의약품 등도 필요하기 때문에 국제사회의 지원이 중요하다.” 지난 1일(현지시간) 베네수엘라 수도 카라카스에서 수색을 마친 건물의 잔해 철거 작업이 진행되고 있다. 굿네이버스 제공 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-06 06:00:09', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260704.56c2138385fa4722a2289d81ff22a741_P1.png', '2026-07-07 06:04:25', '2026-07-07 15:47:53.289586', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3173, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607052139005', 'https://www.khan.co.kr/article/202607052139005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '‘통합’ 없는 독립 250주년 트럼프 연설', '민주 진영 겨냥 “공산주의자”환희의 미국…폭죽 86만발 터뜨리며 건국 250년 ‘축하’ 5일(현지시간) 미국 워싱턴 내셔널몰에 모인 시민들이 미국 건국 250주년 경축 행사의 일환으로 열린 불꽃놀이를 지켜보고 있다. AFP연합뉴스4일(현지시간) 미국 건국 250주년을 기념하기 위해 쏘아올린 폭죽 86만발이 수도 워싱턴의 하늘을 수놓았다. 세계 기네스북 기록···', '민주 진영 겨냥 “공산주의자” 환희의 미국…폭죽 86만발 터뜨리며 건국 250년 ‘축하’ 5일(현지시간) 미국 워싱턴 내셔널몰에 모인 시민들이 미국 건국 250주년 경축 행사의 일환으로 열린 불꽃놀이를 지켜보고 있다. AFP연합뉴스 4일(현지시간) 미국 건국 250주년을 기념하기 위해 쏘아올린 폭죽 86만발이 수도 워싱턴의 하늘을 수놓았다. 세계 기네스북 기록을 깬 대규모 불꽃놀이와 웅장한 에어쇼로 그 어느 해보다 화려하게 기획된 독립기념일이었다. 그러나 찌는 듯한 폭염에 뇌우·태풍 예보까지 겹치면서 이날 행사는 곳곳에서 차질을 빚었다. 이날 워싱턴 기온이 38도까지 치솟자 행사 주최 측은 독립기념일 퍼레이드를 취소했다. 밤에는 뇌우·태풍 경보가 내려지면서 대피명령까지 떨어졌다. 우여곡절 끝에 행사가 재개되긴 했지만, 불꽃놀이는 결국 도널드 트럼프 대통령의 연설이 끝난 후 자정이 돼서야 시작됐다. 올해 행사가 파행을 빚게 된 더 큰 원인은 악천후보다 트럼프 대통령의 건국 250주년 ‘사유화’ 논란이었다. 250주년 기념행사는 2016년 미 연방의회가 만든 초당적 위원회인 ‘아메리카250’이 10년 동안 준비해왔지만, 트럼프 대통령은 지난해 취임과 동시에 행정명령으로 ‘프리덤250’을 출범시킨 후 예산과 권한을 몰아줬다. 반이민 정서 부채질 부정선거론 주장도 250주년 독립기념일의 역사적 의미는 퇴색되고, 역대 최대 규모의 불꽃놀이와 에어쇼 등 애국주의를 강조하는 화려한 볼거리가 그 자리를 메웠다. 미국의 건국정신보다 트럼프 대통령 기념 이벤트가 잇따랐다. 트럼프 대통령은 이날 본인의 서명이 들어간 100달러짜리 지폐를 소셜미디어에 공개했다. 정치적 갈등이 있더라도 독립 기념행사만큼은 건국의 의미를 되새기는 단합의 기회로 삼으려 했던 역대 정부와 달리 트럼프 대통령은 올해 행사를 대놓고 이념 투쟁의 장으로 만들었다. 그는 이날 내셔널몰에서 열린 독립 기념행사 연설에서 진보주의자들을 ‘공산주의자’로 낙인찍었다. 그는 “우리 군인들이 전 세계 전장에서 공산주의와 싸웠는데, 그 위협이 다시 미국 본토에서 고개를 드는 것을 두고 볼 수 없다”며 “그것은 암과 같다. 빨리 잘라내야 한다”고 했다. 그는 “우리는 공산주의와의 전쟁에 참전했던 용사들에게 자랑스럽게 감사를 표한다”며 6·25전쟁 참전 미군을 소개하기도 했다. 트럼프 대통령은 “공산주의 체제는 미국 체제의 정반대”라고 규정했다. 그러면서 “2세기 반이 지난 지금도 이 미국 공화국은 여전히 당당하고 강력하게 서 있다”며 “최고의 순간은 아직 오지 않았다. 이것은 미국 황금기의 서막일 뿐”이라고 강조했다. 또 오는 11월 중간선거를 앞둔 시점에서 부정선거 음모론을 설파했다. 그는 자신이 추진하는 선거법 개정안의 통과를 촉구하면서 “모든 유권자가 시민권을 증명하고, 우편투표가 없어져야 선거 부정행위가 사라진다”고 주장했다. 트럼프 대통령은 전날 역대 대통령의 얼굴이 새겨진 미 사우스다코타주 러시모어산을 방문했을 때도 민주당 내에서 부상하는 민주사회주의를 ‘공산주의’로 규정하며 통합보다는 분열과 공격을 시도했다. 그러면서 “미국의 ‘예외주의’를 지키기 위해 미국 정신을 말살하려는 자들로부터 조국의 정체성을 되찾겠다”면서 반이민 정서를 부채질했다. AP통신은 트럼프 “당파적 정치와 애국주의적 호소를 뒤섞었다”며 “역대 대통령이 국민통합의 기회로 삼아온 독립기념일 연설로는 이례적으로 당파적인 입장을 드러냈다”고 평가했다.', 'crawl', '경향신문', '2026-07-05 21:39:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/05/l_2026070601000148100012821.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:55.27903', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3174, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607052104015', 'https://www.khan.co.kr/article/202607052104015/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '하메네이 장례식 1500만명 조문 예상…“미국에 죽음을” 분노', '40도 육박 무더위 속 9일까지 추모중·러 등 우방국가 조문단도 방문트럼프 “이란에 일주일 휴가 줬다”이슬람혁명수비대 총사령관, 전쟁 후 첫 공개 석상 등장 아흐마드 바히디 이슬람혁명수비대 총사령관이 지난 5일(현지 시간) 하메네이 영결식에 참석하고 있다. 로이터연합뉴스지난 2월 미국·이스라엘의 이란 공습 첫날 사망한 아야톨라 알리 하메네이 전 최고지도자의···', '40도 육박 무더위 속 9일까지 추모 중·러 등 우방국가 조문단도 방문 트럼프 “이란에 일주일 휴가 줬다” 이슬람혁명수비대 총사령관, 전쟁 후 첫 공개 석상 등장 아흐마드 바히디 이슬람혁명수비대 총사령관이 지난 5일(현지 시간) 하메네이 영결식에 참석하고 있다. 로이터연합뉴스 지난 2월 미국·이스라엘의 이란 공습 첫날 사망한 아야톨라 알리 하메네이 전 최고지도자의 장례식이 5일(현지시간)로 2일 차에 접어들었다. 낮 최고기온이 40도에 육박하는 무더위 속에서도 테헤란을 찾은 조문객 수십만명은 하메네이를 추모하는 한편 미국과 이스라엘을 향한 분노를 드러냈다. 프레스TV 등 이란 현지 매체에 따르면 장례 이틀째인 이날 하메네이의 시신이 안치된 수도 테헤란의 그랜드 모살라는 각지에서 모인 조문객으로 인산인해를 이뤘다. 검은 옷을 입은 이들은 하메네이의 초상화와 이란 국기, 코란 등을 들고 눈물을 흘렸다. 일부는 “미국과 이스라엘에 죽음을”이라는 구호를 외치며 복수를 촉구하기도 했다. 중국과 러시아 등 우방국가의 조문단도 속속 테헤란을 찾았다. 아바스 아라그치 외교장관은 이날 엑스를 통해 “70여개국 대표단이 하메네이 최고지도자의 추모 행사에 참석했다”며 “이들 대표단을 맞아 영광”이라고 밝혔다. 장례는 오는 9일까지 총 엿새간 치러진다. 4~5일 테헤란 그랜드 모살라에서 조문을 받은 뒤 6일에는 테헤란 시내에서 추모 행진을 벌인다. 다음날 시아파 주요 성지이자 테헤란에서 120㎞ 떨어진 곰에서 추모 행사를 치른 뒤 8일에는 이라크 내 시아파 성지인 나자프와 카르발라에서 각각 행사를 진행한다. 9일에는 하메네이의 고향이자 이맘 레자 성지가 있는 이란 마슈하드에 최종 안장될 예정이다. 조문객 규모는 정확히 집계되지 않고 있으나 이란 반관영 타스님통신은 장례 첫날 오후 5시30분부터 이튿날 오전 7시까지 테헤란 지하철 이용 건수가 700만건을 넘어섰다고 보도했다. 통신은 9일까지 방문이 예상되는 조문객 규모가 1500만명에 달한다고도 전했다. 이란 정부는 전국에서 몰려온 조문객들을 위해 학교 수천개를 임시 숙소로 개방했다. 하메네이의 아들이자 그의 뒤를 이어 최고지도자에 오른 모즈타바는 이날 오전까지도 모습을 드러내지 않았다. 지난 2월 말 공습 당시 얼굴과 다리 등을 크게 다친 것으로 알려진 그는 몇 차례 성명을 발표했을 뿐 공개 석상에는 한 번도 나서지 않았다. 최근 카타르 도하에서 큰 진전 없이 마무리된 이란과 미국의 실무협상은 오는 11일 파키스탄에서 재개될 예정이라고 사우디 국영 알아라비야뉴스가 익명의 소식통을 인용해 보도했다. 이 매체는 다가올 협상에서 대이란 제재 및 이란 동결 자산 해제를 비롯해 이란 핵 프로그램이 논의 테이블에 오를 예정이며 이란 당국은 장례식을 치른 뒤 대표단을 구성할 것이라고 전했다. 도널드 트럼프 미국 대통령은 전날 미 온라인 매체 액시오스와의 전화 인터뷰에서 “이란에 장례식을 위한 일주일의 휴가를 줬다”며 이 기간 양측의 무력 충돌은 없을 것이라고 밝혔다. 이어 장례식에 이란 지도부가 집결한다는 점을 짚은 뒤 “‘한 방’에 그들을 제거할 수 있겠지만 그렇게 하지 않을 것이다. 협상 상대가 사라지기 때문”이라고 말했다. 그는 또 “이란인들은 하메네이를 싫어할 줄 알았는데 장례식에서 우는 사람을 보고 놀랐다”면서 “가짜 눈물일 수 있다”고 덧붙였다. 하메네이의 장례식이 시작된 4일은 미국이 건국 250주년을 맞아 대대적으로 기념행사를 벌인 날이기도 하다.', 'crawl', '경향신문', '2026-07-05 21:04:01', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/05/l_2026070601000154200012972.jpg', '2026-07-07 06:04:25', '2026-07-07 15:47:57.156323', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3175, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607052104005', 'https://www.khan.co.kr/article/202607052104005/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '모즈타바, 아버지 장례식도 불참…이란 지도부 ‘분열’', '지도력·정당성 의문 확산…NYT “당국, 신변 보호 위해 참석 요청 거부”아야톨라 알리 하메네이 전 이란 최고지도자의 장례식이 진행 중인 가운데 모즈타바 하메네이 현 최고지도자가 모습을 드러내지 않으면서 이란 지도부 내 혼란과 권력 갈등이 심화하고 있다.뉴욕타임스(NYT)는 4일(현지시간) 모즈타바가 공개 석상에 모습을 드러내지 않아 이란 정치권 내부에서 ···', '지도력·정당성 의문 확산…NYT “당국, 신변 보호 위해 참석 요청 거부” 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식이 진행 중인 가운데 모즈타바 하메네이 현 최고지도자가 모습을 드러내지 않으면서 이란 지도부 내 혼란과 권력 갈등이 심화하고 있다. 뉴욕타임스(NYT)는 4일(현지시간) 모즈타바가 공개 석상에 모습을 드러내지 않아 이란 정치권 내부에서 분열이 커지고 그의 역할을 둘러싼 의문이 제기되고 있다고 보도했다. 모즈타바는 장례식이 시작된지 이틀째인 5일 오전 현재까지 모습을 드러내지 않고 있다. NYT에 따르면 모즈타바가 장례식에 참석하고 싶다는 뜻을 전했으나 보안당국이 신변 보호를 이유로 참석 요청을 거부했다고 익명의 이란 관계자들이 전했다. 모즈타바가 공개 행보를 자제하고 확실한 지도력을 보여주지 못하면서 이란 지도부 내부의 갈등은 더 극심해지고 있다. 앞서 미국과 이란의 종전 양해각서(MOU)에 따른 후속 협상이 진행됨에 따라 강경파들은 협상을 주도한 실용주의적 성향의 인사들을 비판해왔다. 지금까지는 후속 협상을 주도하는 마수드 페제시키안 대통령, 모하마드 바게르 갈리바프 의회 의장, 모하마드 바게르 졸가드르 최고국가안보회의 사무총장과 이슬람혁명수비대(IRGC) 고위 장군 등 실용주의 세력이 의사결정을 이끄는 것으로 알려져 있다. 이란 고위 관리 4명과 IRGC 대원 2명은 NYT에 “공개적으로 드러난 분열은 보이지 않는 곳에서 이뤄지고 있는 더 깊은 갈등의 극히 일부에 불과하다”고 말했다. 또 각 파벌이 모즈타바를 자신의 편으로 끌어들이기 위해 치열한 다툼을 벌이고 있다고 전했다. 지난 3월 취임한 후 공개 행보를 보이지 않고 있는 모즈타바가 하메네이의 장례식에도 끝내 참석하지 않는다면 그의 정당성과 지도력을 둘러싼 의문이 확산할 것으로 보인다. 전직 미국 중앙정보국(CIA) 요원이자 이란 전문가인 노먼 룰은 워싱턴포스트에 “모즈타바가 아버지의 장례식에 참석하지 않고, 공개적으로 애도를 표하지 않으며 지도자로서의 위엄을 보여주지 않는다면 이는 그의 약점, 심지어 사망의 증거로 해석될 것”이라고 말했다. 최고지도자로서 모즈타바의 영향력이 약화했다는 징후도 있다. 모하마드 자파르 가엠파나흐 이란 부통령은 최근 모즈타바가 최종 결정권을 가진 것이 아니며 그의 의견이 다른 관리들처럼 논의되고 고려돼야 한다고 말했다. 장례식이 끝난 뒤 모즈타바가 사법부, 국영방송, IRGC 산하 바시즈 민병대, 비서실장 등 요직 인선에 나서면서 이란 지도부의 향후 방향이 결정될 것이라는 전망이 나온다.', 'crawl', '경향신문', '2026-07-05 21:04:00', '진보', 'ready', 'https://img.khan.co.kr/newsletter/c/300x200/228606/2026/3477438/83757_3477438_1783229307622425800.jpeg', '2026-07-07 06:04:25', '2026-07-07 15:47:59.359504', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3177, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607051643001', 'https://www.khan.co.kr/article/202607051643001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '미국 건국기념일 시작된 하메네이 장례식···모즈타바는 어디에?', '5일(현지시간) 이란 수도 테헤란의 그랜드 모살라에서 열린 아야톨라 알리 하마네이 이란 전 최고지도자의 장례식에 조문객들이 모여 있다. 무더운 날씨가 이어지면서 당국은 스프레이를 설치해 물을 뿌리며 열을 식혔다. 테헤란|AFP연합뉴스지난 2월 미국·이스라엘의 이란 공습 첫날 사망한 아야톨라 알리 하메네이 전 최고지도자의 장례식이 5일(현지시간)로 2일 차에···', '5일(현지시간) 이란 수도 테헤란의 그랜드 모살라에서 열린 아야톨라 알리 하마네이 이란 전 최고지도자의 장례식에 조문객들이 모여 있다. 무더운 날씨가 이어지면서 당국은 스프레이를 설치해 물을 뿌리며 열을 식혔다. 테헤란|AFP연합뉴스 지난 2월 미국·이스라엘의 이란 공습 첫날 사망한 아야톨라 알리 하메네이 전 최고지도자의 장례식이 5일(현지시간)로 2일 차에 접어들었다. 낮 최고 기온이 40도 가까이 오르는 무더위 속 테헤란을 찾은 조문객 수십만명은 하메네이에 대한 조의와 함께 미국 및 이스라엘을 향한 분노를 드러냈다. 한편 장례식을 계기로 대중 앞에 처음 설 것으로 기대됐던 새 최고지도자 모즈타바는 이틀째인 이날도 모습을 드러내지 않았다. 프레스TV 등 이란 현지 매체에 따르면 장례 이틀째인 이날 하메네이의 시신이 안치된 수도 테헤란의 그랜드 모살라는 각지에서 모인 조문객으로 인산인해를 이뤘다. 검은 옷을 입은 이들은 하메네이의 초상화와 이란 국기, 코란 등을 들고 눈물을 흘렸다. 일부는 “미국과 이스라엘에 죽음을”이라는 구호를 외치며 복수를 촉구하기도 했다. 중국과 러시아 등 우방 국가의 조문단도 속속 테헤란을 찾았다. 아바스 아라그치 외교장관은 이날 엑스를 통해 “70여 개국 대표단이 하메네이 최고지도자의 추모 행사에 참석했다”며 “이들 대표단을 맞아 영광”이라고 밝혔다. 장례는 오는 9일까지 총 엿새간 치러진다. 첫 이틀 동안 테헤란 그랜드 모살라에서 조문을 받은 뒤 6일에는 테헤란 시내에서 추모 행진을 벌인다. 다음날 시아파 주요 성지이자 테헤란에서 120㎞ 떨어진 곰에서 추모 행사를 치른 뒤 8일에는 이라크 내 시아파 성지인 나자프와 카르발라에서 각각 행사를 진행한다. 9일에는 하메네이의 고향이자 이맘 레자 성지가 있는 이란 마슈하드에 최종 안장될 예정이다. 조문객 규모는 정확히 집계되지 않고 있으나 이란 반관영 타스님통신은 장례 첫날 오후 5시30분부터 이튿날 오전 7시까지 테헤란 지하철 이용 건수가 700만 건을 넘어섰다고 보도했다. 통신은 9일까지 방문이 예상되는 조문객 규모가 1500만명에 달한다고도 전했다. 이란 정부는 전국에서 몰려온 조문객들을 위해 학교 수천 개를 임시 숙소로 개방했다. 4일(현지시간) 이란 테헤란 그랜드 모살라에서 시작된 고 아야톨라 알리 하메네이 최고 지도자 장례식에서 조문객들이 기도하고 있다. 테헤란|로이터연합뉴스 4일(현지시간) 이란 테헤란의 그랜드 모살라에서 열린 아야톨라 알리 하메네이 전 최고지도자의 장례식에 수천명의 조문객이 모여있다. 테헤란|UPI연합뉴스 하메네이의 아들이자 그의 뒤를 이어 최고지도자에 오른 모즈타바는 이날도 모습을 드러내지 않았다. 지난 2월 말 공습 당시 얼굴과 다리 등을 크게 다친 것으로 알려진 그는 몇 차례 성명을 발표했을 뿐 공개석상에는 한 번도 나서지 않았다. 이 때문에 그의 건강 상태와 실권 장악 여부를 두고 의문이 끊이지 않았고, 이번 장례식을 통해 이를 해소할 것으로 기대됐다. 다만 뉴욕타임스는 전날 이슬람혁명수비대(IRGC) 관계자 2명을 인용해 모즈타바가 9일 마슈하드에서 열릴 안장식 참석을 희망했으나 그의 신변 안전을 우려한 보안당국이 이를 허가하지 않았다고 전했다. 최근 카타르 도하에서 큰 진전 없이 마무리된 이란과 미국의 실무협상은 오는 11일 파키스탄에서 재개될 예정이라고 사우디 국영 알아라비야뉴스가 익명의 소식통을 인용해 보도했다. 이 매체는 다가올 협상에서 대이란 제재 및 이란 동결 자산 해제를 비롯해 이란 핵 프로그램이 논의 테이블에 오를 예정이며, 이란 당국은 장례식을 치른 뒤 대표단을 구성할 것이라고 전했다. 도널드 트럼프 미국 대통령은 전날 미 온라인 매체 액시오스와 전화 인터뷰에서 “이란에 장례식을 위한 일주일의 휴가를 줬다”며 이 기간 양측의 무력 충돌은 없을 것이라고 밝혔다. 이어 장례식에 이란 지도부가 집결한다는 점을 짚은 뒤 “‘한 방’에 그들을 제거할 수 있겠지만 그렇게 하지 않을 것이다. 협상 상대가 사라지기 때문”이라고 말했다. 그는 또 “이란인들은 하메네이를 싫어할 줄 알았는데 장례식에서 우는 사람을 보고 놀랐다”면서 “가짜 눈물일 수 있다”고도 덧붙였다. 하메네이의 장례식이 시작된 4일은 공교롭게도 미국이 건국 250주년을 맞아 대대적으로 기념행사를 벌인 날이기도 하다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-05 16:43:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/05/news-p.v1.20260705.dc8eaa6cabbb4ca4bd8560b25ab8e744_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:48:04.608681', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3178, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607051631001', 'https://www.khan.co.kr/article/202607051631001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '아버지 장례식에도 ‘두문불출’ 모즈타바에 이란 지도부 분열···“장례 불참, 나약함의 증거”', '골람 호세인 모흐세니 에제이 이란 대법원장, 아야톨라 사데크 아몰리 라리자니 이란 국정조정위원회 위원장, 모하마드 바게르 갈리바프 이란 의회 의장, 마수드 페제시키안 이란 대통령(왼쪽부터)이 3일(현지시간) 이란 테헤란에서 열린 아야톨라 알리 하메네이 전 이란최고지도자의 장례식에 참석하고 있다. 로이터연합뉴스아야톨라 알리 하메네이 전 이란 최고지도자의 장례···', '골람 호세인 모흐세니 에제이 이란 대법원장, 아야톨라 사데크 아몰리 라리자니 이란 국정조정위원회 위원장, 모하마드 바게르 갈리바프 이란 의회 의장, 마수드 페제시키안 이란 대통령(왼쪽부터)이 3일(현지시간) 이란 테헤란에서 열린 아야톨라 알리 하메네이 전 이란최고지도자의 장례식에 참석하고 있다. 로이터연합뉴스 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식이 진행되는 가운데 모즈타바 하메네이 현 이란 최고지도자가 참석하지 않으면서 이란 지도부 내 혼란과 갈등이 심화하고 있다. 뉴욕타임스(NYT)는 4일(현지시간) 모즈타바가 공개석상에 모습을 드러내지 않아 이란 정치권 내부에서 분열이 커지고 그의 역할을 둘러싼 의문이 제기되고 있다고 전했다. 지금까지 모즈타바는 전날부터 시작된 장례식에 참석하지 않고 있다. NYT에 따르면 모즈타바가 장례식에 참석하고 싶다는 뜻을 전했으나 그의 신변 보호를 위해 보안 당국이 요청을 거부했다고 익명의 이란 관계자들은 전했다. 모즈타바가 공개적 행보를 자제하고 확실한 지도력을 보이지 못하면서 이란 지도부 내부의 갈등은 더 극심해지고 있다. 앞서 미국과 이란의 종전 양해각서(MOU)에 따른 후속 협상이 진행됨에 따라 강경파들은 협상을 주도한 실용주의적 성향의 인사들을 비판해왔다. 강경파로 분류되는 이란의 전략가인 하산 라힘푸르 아즈가디는 최근 테헤란에서 열린 집회에서 “우리 지도자를 살해한 후 미국과 평화를 논의하는 이 시대를 나는 경멸한다”고 말했다. 일부 강경파들은 현재 진행 중인 협상이 2015년 이란핵합의(JCPOA)보다 더 광범위한 내용이며 미국과 이란의 적대 관계가 완화하는 큰 변화가 이뤄질 수 있다고 우려하는 것으로 전해졌다. 지금까지는 후속 협상을 이끄는 마수드 페제시키안 대통령, 모하마드 바게르 갈리바프 의회 의장, 모하마드 바게르 졸가드르 최고국가안보회의 사무총장과 이슬람혁명수비대(IRGC) 고위 장군 등 실용주의 세력이 의사 결정을 이끌고 있는 것으로 알려져 있다. 이란 고위 관리 4명과 IRGC 대원 2명은 NYT에 “공개적으로 드러난 분열은 보이지 않는 곳에서 이뤄지고 있는 더 깊은 갈등의 극히 일부에 불과하다”고 말했다. 이들은 모즈타바를 자신의 편으로 끌어들이기 위해 각 파벌이 치열한 다툼을 벌이고 있다고 전했다. 지난 3월 취임한 후 공개적 행보를 보이지 않고 있는 모즈타바가 하메네이의 장례식까지 참여하지 않으면서 그의 정당성과 지도력을 둘러싼 의문이 확산할 것으로 보인다. 전직 미국 중앙정보국(CIA) 요원이자 이란 전문가인 노먼 룰은 “모즈타바가 아버지의 장례식에 참석하지 않고, 공개적으로 애도를 표하지 않으며 지도자로서의 위엄을 보여주지 않는다면 이는 그의 약점, 심지어 사망의 증거로 해석될 것”이라고 워싱턴포스트에 말했다. 매일 밤 테헤란에서 열리는 집회에서는 모즈타바가 얼굴을 드러내거나 음성 녹음을 공개해야 한다는 주장이 나오고 있는 것으로 전해졌다. 이미 최고지도자로서 모즈타바의 영향력이 약화했다는 징후도 있다. 모하마드 자파르 가엠파나흐 이란 부통령은 최근 모즈타바가 최종 결정권을 가진 것이 아니며 그의 의견이 다른 관리들처럼 논의되고 고려되어야 한다고 말해 강경파의 비판을 받기도 했다. 장례식이 끝난 후 모즈타바가 사법부, 국영 방송, IRGC 산하 바시즈 민병대, 자신의 비서실장 등 요직에 대한 인선을 시작하면서 이란 지도부의 향후 방향이 결정될 것이라는 전망이 나온다. 발리 나스르 미국 존스홉킨스대 교수는 “우리는 지금 현실적이고 긴장감 넘치는 정치적 상황과 국가의 미래를 둘러싼 권력 싸움을 목격하고 있다”며 “실용주의 세력이 우위를 점한다면 강경파는 주변부에 밀려날 것이며, 그들은 이에 맞서 싸우고 있다”고 말했다.', 'crawl', '경향신문', '2026-07-05 16:31:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/05/rcv.YNA.20260703.PRU20260703412601009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:48:06.41829', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3179, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607051534001', 'https://www.khan.co.kr/article/202607051534001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '악천후에도 “연설 강행” 자정 돼서야 기네스급 불꽃놀이···트럼프가 ‘사유화’한 미국 건국 250주년, 분열로 얼룩져', '미국 건국 250주년을 맞아 4일(현지시간) 수도 워싱턴의 내셔널몰에서 86만발의 폭죽이 터지고 있다. EPA연합뉴스4일(현지시간) 미국 건국 250주년을 기념하기 위해 86만발의 폭죽이 수도 워싱턴의 하늘을 수놓았다. 세계 기네스북 기록을 깬 대규모 불꽃놀이와 웅장한 에어쇼로 그 어느 해보다 화려하게 기획된 독립기념일이었다. 그러나 찌는 듯한 폭염에 뇌우···', '미국 건국 250주년을 맞아 4일(현지시간) 수도 워싱턴의 내셔널몰에서 86만발의 폭죽이 터지고 있다. EPA연합뉴스 4일(현지시간) 미국 건국 250주년을 기념하기 위해 86만발의 폭죽이 수도 워싱턴의 하늘을 수놓았다. 세계 기네스북 기록을 깬 대규모 불꽃놀이와 웅장한 에어쇼로 그 어느 해보다 화려하게 기획된 독립기념일이었다. 그러나 찌는 듯한 폭염에 뇌우·태풍 예보까지 겹치면서 이날 행사는 곳곳에서 차질을 빚었다. 마치 ‘위대한 미국’을 강조하지만, 실제로는 분열과 전쟁으로 고전하고 있는 미국의 현주소를 보는 듯했다. 이날 워싱턴의 기온이 38도까지 치솟자 행사 주최 측은 독립기념일 퍼레이드를 취소했다. 독립선언문을 낭독하는 국립문서기록관리청 행사도 급히 실내로 장소를 옮겼다. 불꽃놀이가 열리는 내셔널몰에선 보안 검색 순서를 기다리다 일사병으로 쓰러지는 사람들이 속출했다. 시민들은 폭염 속에서도 저마다 성조기를 그려 넣은 의상을 입고 독립기념일을 축하했다. 그러나 밤에는 뇌우·태풍 경보가 내려지면서 대피 명령까지 떨어졌다. 비가 그친 후 우여곡절 끝에 행사가 재개되긴 했지만, 불꽃놀이는 결국 트럼프 대통령의 연설이 끝난 후 자정이 돼서야 시작됐다. 세계 기네스북 기록을 경신한 86만발의 폭죽이 40분 가까이 끊임없이 터졌다. 4일(현지시간) 미국 건국 250주년을 맞아 성조기로 만든 옷을 입고 나온 미국 시민들. AP연합뉴스 4일(현지시간) 강풍이 부는 미 독립기념일 행사장. AFP연합뉴스 올해 행사가 파행을 빚게 된 더 큰 원인은 악천후보다 트럼프 대통령의 건국 250주년 ‘사유화’ 논란이었다. 250주년 기념행사는 2016년 미 연방 의회가 만든 초당적 위원회인 ‘아메리카250’이 10년 동안 준비해왔지만, 트럼프 대통령은 지난해 취임과 동시에 행정명령으로 ‘프리덤250’을 출범시킨 후 예산과 권한을 몰아줬다. 250주년 독립기념일의 역사적 의미는 퇴색되고, 역대 최대 규모의 불꽃놀이와 에어쇼 등 애국주의를 강조하는 화려한 볼거리가 그 자리를 메웠다. 연방 정부가 주도하는 250주년 기념 조형물과 공공 자료에선 다문화·소수자·소수인종 내용이 대거 축소되거나 삭제됐다. 미국의 건국정신보다 트럼프 대통령을 기념하는 이벤트도 잇따랐다. 트럼프 대통령은 이날 건국 250주년을 맞아 본인의 서명이 들어간 100달러짜리 지폐를 소셜미디어에 공개했다. 앞서 그는 자신의 초상화와 서명을 새긴 ‘한정판 여권’을 출시하기도 했다. 정치적 갈등이 있더라도 독립기념 행사만큼은 건국의 의미를 되새기는 단합의 기회로 만들려 했던 역대 정부와 달리, 트럼프 대통령은 올해 행사를 대놓고 이념 투쟁의 장으로 만들었다. 그는 이날 내셔널몰에서 열린 독립기념 행사 연설에서 진보주의자들을 ‘공산주의’로 낙인찍었다. 그는 “이 나라는 공산주의자들을 원하지 않는다”며 “우리 군인들이 전 세계 전장에서 공산주의와 싸웠는데, 그 위협이 다시 미국 본토에서 고개를 드는 것을 두고 볼 수 없다. 그런 일이 일어나게 두지 않겠다”고 주장했다. 또 오는 11월 중간선거를 앞둔 시점에서 부정선거 음모론을 설파하며 선거의 신뢰성을 훼손했다. 그는 자신이 추진하는 선거법 개정안의 통과를 촉구하면서 “모든 유권자가 시민권을 증명하고, 우편투표가 없어져야 선거 부정행위가 사라진다”고 주장했다. 트럼프 대통령은 전날 역대 대통령의 얼굴이 새겨진 미 사우스다코타주 러시모어산을 방문했을 때도 민주당 내에서 부상하는 민주사회주의를 ‘공산주의’로 규정하며 통합보다는 분열과 공격을 시도했다. 그러면서 “미국의 ‘예외주의’를 지키기 위해 미국 정신을 말살하려는 자들로부터 조국의 정체성을 되찾겠다”면서 반이민 정서를 부채질했다. UPI연합뉴스 이는 ‘미국 예외주의’를 다양성에서 찾는 연설을 했던 조란 맘다니 뉴욕시장과 비교됐다. 민주사회주의자인 맘다니 시장은 “미국 예외주의의 ‘아이러니’는 이 나라의 역사가 권력과 부를 가진 사람들로부터 전혀 예외적이지 않다는 말을 들은 (평범한) 사람들에 의해 쓰였다는 점”이라고 말해 미국은 이민자들이 일군 나라임을 강조했다. 트럼프 대통령의 분열적 연설은 즉각적인 반응을 불러일으켰다. 백인우월주의단체인 ‘패트리엇 프론트’ 회원 수백명은 이날 인종차별의 상징인 남부 연합기를 들고 국회의사당으로 행진하면서 “미국을 되찾자. 앵글로색슨 혈통의 독립을 쟁취하자”라고 외쳤다고 워싱턴포스트는 전했다. 로이터통신이 지난 6월 여론조사업체 입소스와 공동으로 진행한 여론조사에 따르면 미국인 5명 중 1명은 올해 250주년 기념행사에 참여할 의지가 없다고 답했다. 또 5명 중 2명은 미국이 “극단적인 갈등으로 앞으로 250년을 더 버티지 못할 것”이라고 내다봤다.', 'crawl', '경향신문', '2026-07-05 15:34:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/05/news-p.v1.20260705.5f5f340f23ad4da283931e17f68f5509_P1.png', '2026-07-07 06:04:25', '2026-07-07 15:48:08.287486', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3181, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607051355011', 'https://www.khan.co.kr/article/202607051355011/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '[베네수 강진]사망자 3000명 달해···“생존자 구조 종료, 본격적 시신 수습 단계”', '4일(현지시간) 베네수엘라 라과이라주에 지진으로 인한 잔해 속 장난감이 놓여 있다. 로이터연합뉴스베네수엘라에서 연쇄 강진에 따른 사망자가 3000명에 육박하는 가운데 실종자들의 생존 가능성이 급격히 낮아지면서 본격적인 구조 작업이 종료되고 있다.4일(현지시간) AFP통신에 따르면 베네수엘라 정부는 이날 강진으로 인한 사망자가 2954명에 달하며 1만6500···', '4일(현지시간) 베네수엘라 라과이라주에 지진으로 인한 잔해 속 장난감이 놓여 있다. 로이터연합뉴스 베네수엘라에서 연쇄 강진에 따른 사망자가 3000명에 육박하는 가운데 실종자들의 생존 가능성이 급격히 낮아지면서 본격적인 구조 작업이 종료되고 있다. 4일(현지시간) AFP통신에 따르면 베네수엘라 정부는 이날 강진으로 인한 사망자가 2954명에 달하며 1만6500여명이 부상을 입었다고 밝혔다. 이는 하루 전 집계된 2645명보다 309명 늘어난 수치다. 정부 발표에 따르면 이번 지진으로 집을 잃은 이재민은 1만6309명이며 800여채의 건물이 피해를 입었다. 구조된 인원은 약 6500명이다. 당국이 공식 실종자 집계를 내놓지 않고 있지만 유엔은 최대 5만명이 실종됐다고 추산하고 있다. 베네수엘라로 모여든 일부 국제 구조팀은 이날부터 구조 활동을 마무리하기 시작했다. 최근 수색 작업 중 생존자를 발견하지 못하자 구조 작업을 종료하는 수순에 들어간 것이다. 미국 로스앤젤레스 카운티 소방국 구조팀은 최근 수색 작업 중 생존 징후를 발견하지 못해 작전을 종료하고 있다고 밝혔다. 플로리다주와 버지니아주 등에서 파견된 구조팀도 이날부터 철수 준비를 하고 있다. 인적·물적 자원의 부족으로 시신 수습 작업도 지연되고 있다. 붕괴한 건물 잔해를 치우기 위한 중장비가 도착하지 않으면서 주민들이 직접 잔해를 헤쳐 시신을 찾는 작업에 나서고 있다. 하지만 파손된 건물들이 계속 무너져내리면서 개별적으로 시신 수습을 하는 시민들이 위험한 상황에 처하고 있다고 베네수엘라 일간 엘나시오날은 전했다. 피해가 가장 큰 라과이라주의 항구 창고 시설은 임시 영안실로 운영되고 있다. 이곳에는 실종된 가족의 신원 확인을 위해 수십명의 유족들이 모여들었다. 임시 영안실에 안치되지 못한 시신 수백구는 야외에 놓여 부패가 빠르게 진행되고 있다고 BBC 스페인어판(BBC 문도)이 전했다. 델시 로드리게스 베네수엘라 임시 대통령은 지난 2일 모든 희생자의 신원을 확인할 것이라고 말한 바 있다. 로드리게스 임시 대통령은 “누구도 집단 매장지로 보내지지 않을 것”이라며 “법의학 전문가들이 희생자들의 모든 지문과 사진을 수집하고 개별 기록을 작성할 것”이라고 밝혔다. 베네수엘라로 들어오는 가장 큰 관문인 라과이라주 마이케티아 지역의 시몬 볼리바르 국제공항에서는 인도주의 지원을 위한 항공편만 오가고 있으며 상업 항공편 운행은 중단된 상태다. 베네수엘라 당국이 적극적으로 대응하지 않고 있다는 비판은 계속 이어지고 있다. 수십년간 경제난과 정치적 혼란으로 베네수엘라 정부의 재난 대응 능력이 매우 약화했다는 지적이 나온 바 있다. 라과이라주에 도착한 물과 식량 등 대부분의 구호물품은 수천 명의 시민이 오토바이로 직접 운반한 것으로 알려졌다. 가족을 찾기 위해 구조팀에 합류했다는 미겔 폴레오는 “대통령은 지원이 신속하게 도착했다고 말했지만 실제로는 그렇지 않았고, 우리를 도운 것은 평범한 시민들이었다”며 “경찰들이 전쟁이라도 난 것처럼 총을 들고 다니는데, 우리가 필요한 것은 그들이 일하는 것”이라고 로이터통신에 말했다. ‘베네수 강진’이 드러낸 권위주의 정권의 민낯 연쇄 강진으로 인한 사망자가 2000명을 넘어선 베네수엘라에서 구조 작업이 이어지는 가운데 관료들이 구호팀과 구호물품의 반입을 막고 있는 것으로 전해졌다. 오랜 기간 권위주의 체제를 이어오며 시스템이 무너진 베네수엘라 정부가 재난 대응의 걸림돌이 되고 있다는 지적이 나온다. 워싱턴포스트(WP)는 1일(현지시간) 베네수엘라 정권이 지진 발생 후 구조활동... https://www.khan.co.kr/article/202607022102025 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-05 13:55:01', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/05/rcv.YNA.20260705.PRU20260705339801009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:48:12.10364', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3183, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607041540001', 'https://www.khan.co.kr/article/202607041540001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '하메네이 장례식 시작…“미국에 죽음을, 복수” 붉은 깃발 든 조문객들', '4일 테헤란에서 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식이 진행되고 있다. AFP연합뉴스이스라엘의 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식이 시작했다.AP통신과 알자지라 등에 따르면 4일(현지시간) 이란의 수도 테헤란 시내에 있는 대형 예배장소인 이맘호메이니 대(&#22823;)모살라 광장에서 장례식이 열···', '4일 테헤란에서 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식이 진행되고 있다. AFP연합뉴스 이스라엘의 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식이 시작했다. AP통신과 알자지라 등에 따르면 4일(현지시간) 이란의 수도 테헤란 시내에 있는 대형 예배장소인 이맘호메이니 대(大)모살라 광장에서 장례식이 열렸다. 이날 오전 하메네이의 운구 행렬이 도착하기 전부터 수많은 추모객이 광장에 몰려들었다. 조문객들은 복수를 상징하는 붉은 깃발을 들고 “미국에 죽음을”, “복수, 복수” 등의 구호를 외쳤다. 일부는 눈물을 흘리고, 가슴을 치며 애도했다. 어머니와 함께 장례식에 참석한 27세 이란 남성 A씨는 AP통신과의 인터뷰에서 눈물을 흘리며 “사랑하는 지도자 하메네이께 작별 인사를 드리러 왔다”며 “이런 날이 올 줄은 상상도 못 했다”고 말했다. 이란 당국은 장례식에 100여개국 대표를 포함해 최대 1000만명 이상이 모일 것으로 보고 있다. 이란 교육 당국은 하메네이의 장례식에 참석하기 위해 방문하는 사람들이 머물 수 있도록 전국적으로 5000개 이상의 학교를 개방했다. 다만 하메네이의 아들이자 현 최고지도자인 아야톨라 모즈타바 하메네이가 공개 석상에 모습을 드러낼지는 불확실하다. 아버지를 살해한 공습에서 부상당한 것으로 추정되는 모즈타바 하메네이는 현재 은신 중이다. 장례 일정은 오는 9일까지 엿새 동안 이어질 예정이다. 하메네이의 시신은 향후 이라크의 시아파 성지인 나자프와 카르발라를 거쳐 이란 북동부 마슈하드의 이맘 레자 성묘에 9일 최종 안장될 예정이다. 하메네이는 미국, 이스라엘과의 전쟁이 시작된 지난 2월28일 관저에서 이스라엘의 표적 공습을 받아 일가족과 함께 숨졌다. 이란은 전쟁 때문에 장례식을 열지 못하다가 지난달 미국과 휴전을 합의해 사망 126일 만에 거행할 수 있게 됐다. 하메네이의 장례식 일정은 미국이 건국 250주년을 맞는 7월4일 독립기념일에 맞춰 시작됐다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-04 15:40:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/04/rcv.YNA.20260704.PAF20260704202301009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:48:15.951937', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3184, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607040600071', 'https://www.khan.co.kr/article/202607040600071/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '미국은 독립기념일서 ‘불꽃놀이’ 이란은 하메네이 장례식서 ‘순교 애도’···세계가 주목하는 ‘7월4일’', '아야톨라 알리 하메네이 전 이란 최고지도자의 장례식이 열린 3일(현지시간) 이란 수도 테헤란 이맘 호메이니 모살라에서 한 여성이 이동하고 있다. 로이터연합뉴스미국과 이란이 오는 4일(현지시간)로 예정된 각 국가 차원의 대대적 행사를 성공적으로 개최하는 데 국력을 쏟고 있다. 대화와 파행 위기를 오가며 위태롭게 이어져온 미·이란 종전 양해각서(MOU) 협상도···', '아야톨라 알리 하메네이 전 이란 최고지도자의 장례식이 열린 3일(현지시간) 이란 수도 테헤란 이맘 호메이니 모살라에서 한 여성이 이동하고 있다. 로이터연합뉴스 미국과 이란이 오는 4일(현지시간)로 예정된 각 국가 차원의 대대적 행사를 성공적으로 개최하는 데 국력을 쏟고 있다. 대화와 파행 위기를 오가며 위태롭게 이어져온 미·이란 종전 양해각서(MOU) 협상도 잠시 멈췄다. 이란 동결자산 해제 문제와 호르무즈 해협 통행료 논란, 레바논 남부의 전쟁 등 MOU 협상이 시작된 후에도 일절 해소되지 못한 쟁점이 산적한 가운데, 양국은 숨 고르기에 들어간 모양새다. 미·이스라엘 공습으로 숨진 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식은 3일(현지시간) 시작됐다. 공식 장례식은 4일부터지만, 이란은 이날 하메네이의 관을 수도 테헤란 이맘 호메이니 모살라(대사원)으로 옮기고 조문객의 참배를 시작했다. 이란은 하메네이의 시신이 담긴 관을 이날 처음으로 공개했다. 이란 내 초강경파를 대표하는 아흐마드 바히디 이란 이슬람혁명수비대(IRGC) 총사령관도 전쟁 이후 처음 모습을 드러냈다. 바히디 사령관은 미·이란 전쟁을 지휘하고 미국과의 MOU 협상 역시 막후에서 좌우하는 것으로 알려진 인물이다. 이란은 하메네이의 장례식을 이란 역사상 가장 큰 규모의 정치적·종교적 행사로 만들기 위해 공을 쏟아왔다. 이란은 7월4일부터 9일까지 이란·이라크 두 나라의 총 다섯 개 주요 도시를 순회하며 장례 행사를 거행한다. 세부 내용은 이란 최고국가안보회의(SNSC)와 전문가회의, 그리고 하메네이의 후계자 모즈타바 하메네이 현 이란 최고지도자의 협의를 거쳐 승인됐다. 마수드 페제시키안 이란 대통령은 이날 엑스에 올린 글에서 “위대한 지도자의 순교는 우리 국민과 이슬람 공동체, 그리고 전 세계 자유인들의 마음에 깊은 슬픔을 새겼다”며 “모든 국민이 열정과 품위를 갖고 역사적 규모로 함께해 국가적 단결과 이슬람 체제의 고귀한 이상에 대한 충성심을 보여주는 모습을 보이길 바란다”고 말했다. 이란 이슬람혁명수비대(IRGC) 아흐마드 바히디 총사령관이 3일(현지시간) 테헤란에서 열린 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식에서 조의를 표하고 있다. AFP연합뉴스 모즈타바가 장례식에 나타날지는 불확실하다. 인도 매체 인디아투데이는 압둘 마지드 하킴 엘라히 주인도 이란 특사가 “지난주 이란을 방문했을 때, 모즈타바를 만났던 지인들로부터 모즈타바가 하메네이 장례식에 올 수 없다는 이야기를 들었다”며 “경호 문제를 이유로 들었다”고 말했다고 보도했다. 이란은 장례식 기간 발생할 수 있는 군사 충돌을 경계하며 미국과 이스라엘에 경고 메시지를 냈다. IRGC는 이날 “어떤 새로운 공격도 이전보다 훨씬 더 강력하고 단호한 대응에 직면하게 될 것”이라며 “최고지도자 모즈타바 하메네이의 지휘 아래 만반의 준비를 하고 있다”고 밝혔다. 미국은 불꽃놀이 기네스 기록 도전 도널드 트럼프 미국 대통령이 지난 1일(현지시간) 노스캐롤라이나주 메도라에서 지지자들과 인사하고 있다. AP연합뉴스 같은 날 미국은 미 건국 250주년을 맞아 ‘미국에 바치는 헌사’라는 제목의 대대적인 행사를 연다. 링컨기념관과 워싱턴기념탑을 잇는 잔디 광장인 내셔널몰에서 개최되는 이 행사에는 공군 편대비행과 에어쇼, 대규모 군악·의장대 공연이 예정돼 있다. 폭염 경보에도 “아주 긴 연설” 하겠다는 트럼프···미 언론 ‘그러다 큰 일 나’ 미국 독립 250주년 기념일인 오는 4일(현지시간) 섭씨 40도에 육박하는 더위가 예고된 가운데 도널드 트럼프 미국 대통령이 장시간 연설을 예고했다. 트럼프 대통령은 지난 1일 노스다코타주에서 한 연설에서 “7월4일 기온이 화씨 약 107도(섭씨 41.7도)까지 오를 것이지만 나는 그곳에서 내가 뭐든지 할 수 있다는 걸 보여주기 위해 아주 긴 연설을 ... https://www.khan.co.kr/article/202607030922001 트럼프 대통령이 예고한 “아주 긴 연설” 이후에는 불꽃놀이가 시작된다. 주최 측은 85만발의 폭죽을 약 40분간 쏘아 올려 기네스 세계기록(81만발) 경신을 추진하고 있다. 트럼프 대통령은 이번 행사를 11월 중간선거를 앞둔 시점에서 지지율 반등의 계기로 삼으려 하고 있다. 그는 지난달 15일 트루스소셜에 올린 글에서 이번 행사를 ‘트럼프 집회’라 명명하고 “여러분이 절대 놓치고 싶지 않을 연설을 할 것”이라고 말했다. 지지율 추락의 주요 원인이 된 미·이란 전쟁에 대해서도 연설의 상당 부분이 할애될 전망이다. 독립기념일 연설에서도 트럼프 대통령이 이란 공습과 중동 휴전 국면을 외교·안보 성과로 연결 지을 가능성이 크다는 관측이 나온다. 영문번역(English Translation)', 'crawl', '경향신문', '2026-07-04 06:00:07', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/04/rcv.YNA.20260703.PRU20260703368101009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:48:17.805842', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3187, 'https://www.khan.co.kr/rss/rssdata/kh_world.xml', 'https://www.khan.co.kr/article/202607032004001', 'https://www.khan.co.kr/article/202607032004001/?utm_source=khan_rss&utm_medium=rss&utm_campaign=kh_world', '국제', '하메네이 장례 절차 개시···이란 신정체제 결속력 시험대', '아야톨라 알리 하메네이 전 이란 최고 지도자의 공식 장례식 시작 하루 전인 3일(현지시간) 테헤란에서 종교 지도자들이 하메네이와 그의 가족 관들 옆에서 조의를 표하고 있다. EPA연합뉴스이스라엘의 공습으로 사망한 아야톨라 알리 하메네이 전 이란 최고지도자의 장례 절차가 사실상 시작됐다. 이란은 약 40년간 국가를 이끌었던 최고지도자의 장례식을 통해 전쟁 이···', '아야톨라 알리 하메네이 전 이란 최고 지도자의 공식 장례식 시작 하루 전인 3일(현지시간) 테헤란에서 종교 지도자들이 하메네이와 그의 가족 관들 옆에서 조의를 표하고 있다. EPA연합뉴스 이스라엘의 공습으로 사망한 아야톨라 알리 하메네이 전 이란 최고지도자의 장례 절차가 사실상 시작됐다. 이란은 약 40년간 국가를 이끌었던 최고지도자의 장례식을 통해 전쟁 이후 흔들린 체제를 결집시키고 대중적 지지를 재확인하는 계기로 삼을 것으로 보인다. 3일(현지시간) AP통신 등에 따르면 아야톨라 하메네이의 관은 공식 장례식을 하루 앞두고 이란 수도 테헤란의 대형 기도원인 이맘 호메이니 그랜드 모살라에 안치됐다. 하메네이는 미국·이스라엘의 대이란 전쟁이 시작된 지난 2월28일 이스라엘의 표적 공습으로 테헤란 관저에서 사망했다. 전쟁이 이어지면서 장례 절차는 몇 달간 연기됐다. 이날 모살라 기도원에는 하메네이뿐만 아니라 당시 함께 숨진 딸, 사위, 손녀, 며느리 등 가족 12명의 관도 함께 안치됐다. 하메네이의 관 위에는 시아파의 제3대 이맘인 후세인을 기리는 문구인 “야 후세인(오! 후세인이여!)”이 적힌 붉은 깃발이 덮였다. 이 문구는 시아파 전통에서 순교자를 추모하고 부당한 권력에 끝까지 저항하겠다는 의미를 담고 있다. 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식을 하루 앞둔 3일(현지시간) , 운둔을 마치고 등장한 아흐마드 바히디 이란 혁명수비대 사령관이 하메네이의 관에 조의를 표하고 있다. AFP연합뉴스 장례식장에는 미국·이스라엘과의 전쟁을 지휘한 초강경파 인사인 아흐마드 바히디 이란 이슬람혁명수비대(IRGC) 총사령관도 모습을 드러냈다. 그는 전쟁 첫날 사망한 전임 총사령관의 뒤를 이어 혁명수비대를 지휘했으며, 전쟁 기간 공개 석상에 모습을 드러내지 않았다. 이날 이란 국영매체는 바히디 사령관이 장례 준비 회의에 참석하고 하메네이의 관 옆을 지키는 모습을 공개했다. AFP통신은 장례식 사전 행사에 참석한 유족과 조문객들이 오열했다고 전했다. 이란 국영방송이 공개한 영상에는 검은 옷을 입은 조문객들이 관 위에 스카프와 개인 소지품을 올리며 추모하는 모습이 담겼다. 이날 장례 현장에서 자원봉사를 하던 모하마드 호세인 레자이는 “하나님의 선택을 받은 이분들이 살아계신 한, 우리는 이슬람 공화국이 세운 ‘굴욕은 용납하지 않는다’는 정책을 반드시 지켜나갈 것”이라며 “우리는 독립 추구 정책을 계속 이어갈 것이며, 모든 결정은 국내에서 이루어지고 국민이 스스로 운명을 결정할 것”이라고 말했다. 3일(현지시간) 테헤란에서 열린 모즈타바 하메네이 이란 최고지도자의 부인 자흐라 하닷 아델의 장례식에서 조문객들이 그의 관을 운구하고 있다. 모즈타바의 부인이자 전 국회의장 골람 알리 하닷 아델의 딸인 자흐라 하닷 아델은 지난 2월28일 이스라엘의 공습으로 아야톨라 알리 전 최고지도자와 함께 사망했다. AFP연합뉴스 공식 장례식은 오는 4일부터 시작된다. 하메네이의 시신은 향후 이라크의 시아파 성지인 나자프와 카르발라를 거쳐 이란 북동부 마슈하드의 이맘 레자 성묘에 오는 9일 최종 안장될 예정이다. 다만 하메네이의 아들이자 현 최고지도자인 아야톨라 모즈타바 하메네이가 공개 석상에 모습을 드러낼지는 불확실하다. 아버지를 살해한 공습에서 부상당한 것으로 추정되는 모즈타바 하메네이는 현재 은신 중이다. 이란 정부는 테헤란에서 수백만 명이 참여하는 대규모 추모 행사를 열어 1989년 루홀라 호메이니 초대 최고지도자 장례식 당시와 비슷한 규모의 군중 집결을 재현한다는 계획이다. 경찰과 테헤란시는 테헤란에서만 1800만∼2000만 명이 조문에 참여할 것으로 예상했다. 당국은 이라크 성지 방문객까지 포함하면 전체 추모 인파가 3500만 명에 이를 것으로 예측했다. 이번 장례식은 단순한 추모 행사를 넘어 전쟁으로 타격을 입은 이란 신정체제의 결속력과 대중 동원 능력을 시험하는 무대가 될 것이라는 분석이 나온다. AP통신은 이번 장례식이 지난해 대규모 반정부 시위를 강경 진압한 지 불과 6개월 만에 열리는 만큼, 체제 정당성과 지지 기반을 확인하는 정치적 의미가 크다고 평가했다. 3일(현지시간) 이란 테헤란의 이맘 호메이니 그랜드 모살라에 아야톨라 알리 하메네이 전 최고지도자와 그의 손녀 자라 모하마디 골파이가니의 관이 안치돼 있다. 로이터연합뉴스', 'crawl', '경향신문', '2026-07-03 20:04:00', '진보', 'ready', 'https://img.khan.co.kr/news/2026/07/03/rcv.YNA.20260703.PEP20260703185501009_P1.jpg', '2026-07-07 06:04:25', '2026-07-07 15:48:23.52229', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3188, 'https://www.kmib.co.kr/rss/data/kmibPolRss.xml', NULL, 'https://www.kmib.co.kr/article/view.asp?arcid=0030075502', '정치', '‘음료테러 자작극 의혹’ 정이한 전 후보 구속영장 청구', '6·3 지방선거 당시 선거운동 과정에서 음료 테러를 당했다고 주장했다가 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보에 대해 구속영장이 청구됐다. 7일 부산 금정경찰서에 따르면 경찰은 위계공무집행방해, 공직선거법 위반 등 혐의로 정 전 후보와 음료를 던진 A씨에 대한 구속영장을 지난 1일 신청했고, 검찰은 지난 3일 부산지법에 영장을 청구했다. 경찰은 증거인멸과 도주 우려 등을 이유로 구속영장을 신청한 것으로 알려졌다. 정 전 후보 등 2명에 대한 구속 전 피의자 심문은 8일 부산지법에서 열린다. 정 전 후보는 지난 4월 27일 부산 금정구의 한 거리에서 유세하던 중 옆을 지나던 차량 운전자가 창밖으로 던진 음료를 피하려다 넘어졌고, 인근 화단에 머리를 부딪쳤다고 주장했다. 당시 정 후보 캠프는 정 후보가 의식을 잃고 병원으로 옮겨져 뇌진탕 등 진단을 받았다고 공지했다. 정 후보 측은 이를 테러로 규정하면서도 A씨의 처벌을 원치 않는다는 입장을 밝히기도 했다. 그러나 경찰은 사건 경위가 석연치 않다고 보고 공모 가능성 등을 수사해왔다. A씨는 정 전 후보의 헬스 트레이너로 알려졌고, 경찰은 두 사람이 사건 전 연락한 정황 등을 토대로 공모 여부를 파악한 것으로 알려졌다. 경찰은 정 전 후보 부친이 운영하는 온그룹 계열사 직원들이 선거운동에 동원됐다는 의혹과 정 전 후보 관련 여론조사기관의 공정성 의혹 등도 수사하고 있다. 정 전 후보는 6·3 지방선거 부산시장 선거에서 2만7418표를 얻어 득표율 1.56%로 3위를 기록했다. 정우진 기자 uzi@kmib.co.kr', '정이한 전 개혁신당 부산시장 후보가 지난 4월 27일 6·3지방선거 선거운동 당시 음료 테러를 당했다며 병원에 입원했다. 6·3 지방선거 당시 선거운동 과정에서 음료 테러를 당했다고 주장했다가 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보에 대해 구속영장이 청구됐다. 7일 부산 금정경찰서에 따르면 경찰은 위계공무집행방해, 공직선거법 위반 등 혐의로 정 전 후보와 음료를 던진 A씨에 대한 구속영장을 지난 1일 신청했고, 검찰은 지난 3일 부산지법에 영장을 청구했다. 경찰은 증거인멸과 도주 우려 등을 이유로 구속영장을 신청한 것으로 알려졌다. 정 전 후보 등 2명에 대한 구속 전 피의자 심문은 8일 부산지법에서 열린다. 정 전 후보는 지난 4월 27일 부산 금정구의 한 거리에서 유세하던 중 옆을 지나던 차량 운전자가 창밖으로 던진 음료를 피하려다 넘어졌고, 인근 화단에 머리를 부딪쳤다고 주장했다. 당시 정 후보 캠프는 정 후보가 의식을 잃고 병원으로 옮겨져 뇌진탕 등 진단을 받았다고 공지했다. 정 후보 측은 이를 테러로 규정하면서도 A씨의 처벌을 원치 않는다는 입장을 밝히기도 했다. 그러나 경찰은 사건 경위가 석연치 않다고 보고 공모 가능성 등을 수사해왔다. A씨는 정 전 후보의 헬스 트레이너로 알려졌고, 경찰은 두 사람이 사건 전 연락한 정황 등을 토대로 공모 여부를 파악한 것으로 알려졌다. 경찰은 정 전 후보 부친이 운영하는 온그룹 계열사 직원들이 선거운동에 동원됐다는 의혹과 정 전 후보 관련 여론조사기관의 공정성 의혹 등도 수사하고 있다. 정 전 후보는 6·3 지방선거 부산시장 선거에서 2만7418표를 얻어 득표율 1.56%로 3위를 기록했다.', 'crawl', '국민일보', '2026-07-07 05:06:02', '보수', 'ready', 'https://image.kmib.co.kr/online_image/2026/0707/2026042711291081842_1777256950_0030075502.jpg', '2026-07-07 06:04:26', '2026-07-07 15:48:34.734873', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3190, 'https://www.kmib.co.kr/rss/data/kmibPolRss.xml', NULL, 'https://www.kmib.co.kr/article/view.asp?arcid=0030074666', '정치', '“대장동 때 보는 것 같아” 계파간 선 넘는 설전…‘감기약 성분’ 발언 논란 이성윤 고발까지', '더불어민주당 8·17 전당대회 당대표 선거에 출마한 김민석 전 총리는 12·3 비상계엄 당시 자신이 국회의 계엄 해제 표결에 불참한 점을 두고 친청(친정청래)계가 공세를 펴는 데 대해 “무슨 꼭 대장동 때를 보는 것 같다”고 맞받았다. 김 전 총리는 7일 KBS 라디오 인터뷰에서 전날 이성윤 최고위원의 ‘감기약 성분’ 발언에 대해 “‘국민의힘에서 누가 얘기를 하나’라고 생각했다”면서 이같이 말했다. 친청계 공세가 과거 국민의힘 등이 대장동 사건으로 이재명 대통령을 비난했던 것과 별반 다르지 않은 행태라는 취지로 풀이된다. 앞서 김 전 총리는 12·3 비상계엄 당일 국회 계엄 해제 표결에 불참했다. 그는 감기약을 먹고 잠들었다고 줄곧 해명했다. 이를 두고 친청계 이 최고위원은 페이스북을 통해 “감기약을 드시고 주무셨다고 하는데 약 성분이 무엇인가. 자는 사람은 깨울 수 있어도 자는 척하는 사람은 깨울 수 없다고 하던데 그런가”라고 물었다. 이에 김 전 총리는 “그때 표결하는 시점에 국회 안에 있었고 표결 직후에 본회의장에 착석했다”라고 말한 뒤 “이 의원이 말한 게 ‘계엄과 관련한 전화를 받고 왜 거기(국회)에 오지 않았냐’(는 것)”이라며 “허위사실에 의한 명예훼손”이라고 주장했다. 전당대회를 앞두고 계파 간 설전은 선을 넘는 수준으로 치닫고 있다. 김 전 총리를 돕고 있는 박범계 의원은 라디오에서 “이성윤 최고위원과 한민수 의원도 결국 최고위원 출마를 앞둔 자기 정치 표본”이라며 “특히 이 최고위원은 이렇게 막 가면 안 된다. 그분 인격에 깜짝 놀랐다”고 비난했다. 법정 공방으로도 비화하는 모양새다. 사법정의 바로세우기 시민행동(사세행)은 8일 이 최고위원을 정통망법상 허위사실적시 명예훼손 혐의로 고발할 방침이다. 사세행은 “조금만 주의를 기울이면 사실이 아님을 알 수 있음에도 당권을 장악해 차기 총선 공천에서 자기 계파 혜택을 기대하고 정 전 대표의 강력한 라이벌인 김 전 총리를 허위 비방한 ‘정청래 호위무사’ 이 최고위원을 허위사실적시 명예훼손 혐의로 서울경찰청에 8일 고발한다”고 전했다. 김혜원 기자 kime@kmib.co.kr', '김민석 전 국무총리 더불어민주당 8·17 전당대회 당대표 선거에 출마한 김민석 전 총리는 12·3 비상계엄 당시 자신이 국회의 계엄 해제 표결에 불참한 점을 두고 친청(친정청래)계가 공세를 펴는 데 대해 “무슨 꼭 대장동 때를 보는 것 같다”고 맞받았다. 김 전 총리는 7일 KBS 라디오 인터뷰에서 전날 이성윤 최고위원의 ‘감기약 성분’ 발언에 대해 “‘국민의힘에서 누가 얘기를 하나’라고 생각했다”면서 이같이 말했다. 친청계 공세가 과거 국민의힘 등이 대장동 사건으로 이재명 대통령을 비난했던 것과 별반 다르지 않은 행태라는 취지로 풀이된다. 앞서 김 전 총리는 12·3 비상계엄 당일 국회 계엄 해제 표결에 불참했다. 그는 감기약을 먹고 잠들었다고 줄곧 해명했다. 이를 두고 친청계 이 최고위원은 페이스북을 통해 “감기약을 드시고 주무셨다고 하는데 약 성분이 무엇인가. 자는 사람은 깨울 수 있어도 자는 척하는 사람은 깨울 수 없다고 하던데 그런가”라고 물었다. 이에 김 전 총리는 “그때 표결하는 시점에 국회 안에 있었고 표결 직후에 본회의장에 착석했다”라고 말한 뒤 “이 의원이 말한 게 ‘계엄과 관련한 전화를 받고 왜 거기(국회)에 오지 않았냐’(는 것)”이라며 “허위사실에 의한 명예훼손”이라고 주장했다. 전당대회를 앞두고 계파 간 설전은 선을 넘는 수준으로 치닫고 있다. 김 전 총리를 돕고 있는 박범계 의원은 라디오에서 “이성윤 최고위원과 한민수 의원도 결국 최고위원 출마를 앞둔 자기 정치 표본”이라며 “특히 이 최고위원은 이렇게 막 가면 안 된다. 그분 인격에 깜짝 놀랐다”고 비난했다. 이성윤 더불어민주당 최고위원 법정 공방으로도 비화하는 모양새다. 사법정의 바로세우기 시민행동(사세행)은 8일 이 최고위원을 정통망법상 허위사실적시 명예훼손 혐의로 고발할 방침이다. 사세행은 “조금만 주의를 기울이면 사실이 아님을 알 수 있음에도 당권을 장악해 차기 총선 공천에서 자기 계파 혜택을 기대하고 정 전 대표의 강력한 라이벌인 김 전 총리를 허위 비방한 ‘정청래 호위무사’ 이 최고위원을 허위사실적시 명예훼손 혐의로 서울경찰청에 8일 고발한다”고 전했다.', 'crawl', '국민일보', '2026-07-07 02:03:01', '보수', 'ready', 'https://image.kmib.co.kr/online_image/2026/0707/2026070112222820229_1782876150_0030074666.jpg', '2026-07-07 06:04:26', '2026-07-07 15:48:54.12781', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3197, 'https://www.kmib.co.kr/rss/data/kmibPolRss.xml', NULL, 'https://www.kmib.co.kr/article/view.asp?arcid=1783326787', '정치', '靑 “대형 부지·평탄화 작업 완료… 기업들이 군공항 적합 의견 제시”', '청와대는 호남권 반도체 클러스터 사업지로 광주 군공항 부지를 선정한 배경이 삼성전자와 SK하이닉스 등 반도체 기업의 ‘니즈(필요)’ 때문이라고 밝혔다. 수백만평 규모의 대형 부지인 데다 부지 건설을 위한 기초 작업도 돼 있는 국유지여서 속도감 있는 사업 추진에 적합하다는 설명이다. 강훈식( 사진 ) 대통령 비서실장은 6일 열린 ‘메가프로젝트 민관합동 점검회의’ 관련 청와대 브리핑에서 “기업들은 광주 군공항이 가장 적합한 부지라는 의견을 제시했다”며 “약 250만평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료돼 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있다”고 설명했다. 이어 “어떤 부지인가에 따라 인프라나 전력·용수·정주 여건 등에 대한 판단과 기준이 달라진다”며 “일을 (신속하게) 시작하기 위해 부지를 먼저 정해야 한다고 판단한 것”이라고 덧붙였다. 광주 군공항은 서울 여의도의 약 3배 규모에 달하는 부지 대부분을 정부가 소유하고 있어서 민간 토지주를 설득해 보상하고 토지를 매입하는 시간도 단축할 수 있다. 강 실장은 토지 수용 및 보상 절차와 관련해 “광주 군공항은 그런 부분에 대한 리스크가 많이 없다”고 말했다. 건물과 활주로 등 기반시설을 활용 중이어서 인프라 설치를 위한 평탄화 작업 등도 이미 완료된 상태다. 속도전을 바라는 정부 입장에서 공기를 앞당길 수 있다는 장점이 있다. 광주 도심으로 이동할 수 있는 KTX역이 인접해 있어 산단 근무 인력을 확보하기 위한 정주 여건 측면에서도 유리하다. 공항·항만 등과 연계한 물류 접근성이 우수하다는 점도 부지 선정 이유 가운데 하나다. 메가프로젝트 발표 이후 산단 부지 후보로 거론된 지역의 부동산 가격 상승 조짐도 발 빠른 부지 선정의 배경이다. 강 실장은 “부동산이 들썩거린다는 여러 가지 보고가 있어서 빨리 부지를 확정해야만 불필요한 논란 등이 확대되지 않을 것이라는 취지도 있다”고 말했다. 군공항 이전 문제에 대해서는 “안보 공백이 발생하지 않는 범위 안에서 조기에 옮기겠다는 것을 전제로 논의한 것”이라고 설명했다. 국방부는 “이전과 관련해 구체적인 방안은 아직 결정된 바 없다”며 “국가정책에 부응하기 위해 공군과 긴밀히 협의할 예정”이라고 밝혔다. 강 실장은 “오늘은 반도체 투자와 관련된 부분을 중심으로 이야기했다”면서 “다음 회의부터 영남권이나 충청권 투자도 점검하기로 했다”고 말했다. 최승욱 이동환 기자 applesu@kmib.co.kr', '청와대는 호남권 반도체 클러스터 사업지로 광주 군공항 부지를 선정한 배경이 삼성전자와 SK하이닉스 등 반도체 기업의 ‘니즈(필요)’ 때문이라고 밝혔다. 수백만평 규모의 대형 부지인 데다 부지 건설을 위한 기초 작업도 돼 있는 국유지여서 속도감 있는 사업 추진에 적합하다는 설명이다. 강훈식 대통령 비서실장은 6일 열린 ‘메가프로젝트 민관합동 점검회의’ 관련 청와대 브리핑에서 “기업들은 광주 군공항이 가장 적합한 부지라는 의견을 제시했다”며 “약 250만평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료돼 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있다”고 설명했다. 이어 “어떤 부지인가에 따라 인프라나 전력·용수·정주 여건 등에 대한 판단과 기준이 달라진다”며 “일을 (신속하게) 시작하기 위해 부지를 먼저 정해야 한다고 판단한 것”이라고 덧붙였다. 광주 군공항은 서울 여의도의 약 3배 규모에 달하는 부지 대부분을 정부가 소유하고 있어서 민간 토지주를 설득해 보상하고 토지를 매입하는 시간도 단축할 수 있다. 강 실장은 토지 수용 및 보상 절차와 관련해 “광주 군공항은 그런 부분에 대한 리스크가 많이 없다”고 말했다. 건물과 활주로 등 기반시설을 활용 중이어서 인프라 설치를 위한 평탄화 작업 등도 이미 완료된 상태다. 속도전을 바라는 정부 입장에서 공기를 앞당길 수 있다는 장점이 있다. 광주 도심으로 이동할 수 있는 KTX역이 인접해 있어 산단 근무 인력을 확보하기 위한 정주 여건 측면에서도 유리하다. 공항·항만 등과 연계한 물류 접근성이 우수하다는 점도 부지 선정 이유 가운데 하나다. 메가프로젝트 발표 이후 산단 부지 후보로 거론된 지역의 부동산 가격 상승 조짐도 발 빠른 부지 선정의 배경이다. 강 실장은 “부동산이 들썩거린다는 여러 가지 보고가 있어서 빨리 부지를 확정해야만 불필요한 논란 등이 확대되지 않을 것이라는 취지도 있다”고 말했다. 군공항 이전 문제에 대해서는 “안보 공백이 발생하지 않는 범위 안에서 조기에 옮기겠다는 것을 전제로 논의한 것”이라고 설명했다. 국방부는 “이전과 관련해 구체적인 방안은 아직 결정된 바 없다”며 “국가정책에 부응하기 위해 공군과 긴밀히 협의할 예정”이라고 밝혔다. 강 실장은 “오늘은 반도체 투자와 관련된 부분을 중심으로 이야기했다”면서 “다음 회의부터 영남권이나 충청권 투자도 점검하기로 했다”고 말했다.', 'crawl', '국민일보', '2026-07-06 15:03:00', '보수', 'ready', 'https://image.kmib.co.kr/online_image/2026/0707/2026070623080545338_1783346885_1783326787.jpg', '2026-07-07 06:04:26', '2026-07-07 15:50:05.776224', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3198, 'https://www.kmib.co.kr/rss/data/kmibEcoRss.xml', NULL, 'https://www.kmib.co.kr/article/view.asp?arcid=0030075767', '경제', '[단독] 홈플러스 “개인 투자금 4000억 10년 안에 갚겠다… 메리츠가 우선”', '홈플러스가 기업 회생 시 자사 전자단기사채(ABSTB)에 4000억원 이상 물려 있는 개인 투자자 자금을 10년 안에 갚겠다는 계획을 세웠던 것으로 확인됐다. 같은 계획안에서 최대 채권자인 메리츠금융그룹의 돈 1조2000억원은 1~2년 차에 우선 갚는 것으로 설계됐다. 홈플러스는 앞서 “전단채를 100% 현금 변제하겠다”고 약속했는데 실제로 개인 투자자 몫은 장기 분할·무이자 변제 뒤로 미뤄져 있었던 셈이다. 7일 국민일보가 단독 입수한 6월 29일 자 홈플러스 수정 회생 계획안을 보면 전단채가 포함된 회생채권은 개인 투자자 명의가 아니라 롯데카드(2286억원)와 현대카드(2245억원), 신한카드(280억원) 명의의 총 4811억원짜리 ‘카드채권’으로 잡혀 있다. 개인 투자자는 계획안 어디에도 직접 등장하지 않는다. 변제 방식도 문제다. 홈플러스는 카드채권 원금에 ‘전액 현금 변제하겠다’는 단서를 달았지만 상환은 회생 제6차 연도인 2033년부터 제10차 연도인 2037년까지 5년에 걸쳐 이뤄진다. 구체적인 연도별 상환액은 2033년 183억원, 2034년 751억원, 2035년 791억원, 2036년 816억원, 2037년 2270억원이다. 그마저도 절반에 가까운 47%가 마지막 해에 몰려 있다. 지금으로부터 11년 뒤인 2037년이 돼야 변제가 마무리되는 것이다. 회생 개시 후 이자는 전액 면제된다. 개인 투자자는 10년을 기다려도 이자 한 푼 받을 수 없다. 반면 메리츠금융 채권 1조2397억원은 준비 연도와 제1차 연도, 즉 올해와 내년에 대부분 변제하도록 설계돼 있다. 같은 회생채권으로 묶여 있지만 개인 투자자 채권과 메리츠금융 채권의 변제 순서가 완전히 다른 것이다. 개인 투자자 권리는 최근 들어 후퇴했다. 홈플러스가 지난 1월 작성한 계획안에서는 카드채권이 2026~2027년 전액 현금 변제되는 것으로 명시돼 있었다. 약 5개월 새 개인 투자자 전단채 자금 변제 시기가 9~10년 밀린 것이다. 이 기간 홈플러스 재무 상태가 계획보다 크게 나빠진 것이 원인으로 풀이된다. 알짜 자산으로 꼽혔던 기업형 슈퍼마켓(SSM) 사업부 홈플러스 익스프레스는 3000억대로 거론되던 몸값의 3분의 1 수준인 1200억원에 팔렸다. 지난해 3월부터 올해 2월까지 매출은 5조7963억원으로 1년 전보다 17% 감소했다. 당기순손실은 1조원을 넘겼다. 이 계획안은 서울회생법원이 지난 3일 홈플러스의 회생을 중단하면서 실행력이 사라졌다. 그러나 앞으로 남은 절차에서도 적지 않은 영향력을 미칠 수 있다. 우선 홈플러스가 오는 20일까지 자금 부족분 2000억원을 구해 회생을 재진행할 경우에는 계획안에 적힌 순서대로 변제가 이뤄질 가능성이 크다. 파산으로 넘어가면 불확실성은 더 커진다. 전단채 개인 투자자는 담보 없는 ‘일반 파산채권자’로 분류될 가능성이 크다. 이 경우 직전 계획안에서 전단채가 100% 변제되는 ‘상거래채권’이 아니라 카드채권으로 다뤄진 이력을 파산관재인이 주된 참고 자료로 작용할 수 있다는 분석이다. 회생과 파산에 능한 금융권 관계자는 “회생 과정에서 상거래채권이 아니라 카드채권 등 금융 채권으로 분류됐던 이력은 파산으로 넘어가더라도 상당한 관성을 갖는다”면서 “전단채 개인 투자자 입장에서는 채권 성격을 다시 다투는 것 자체가 큰 비용이 드는 싸움이 될 것”이라고 말했다. 김진욱 기자 reality@kmib.co.kr', '홈플러스가 기업 회생 시 자사 전자단기사채(ABSTB)에 4000억원 이상 물려 있는 개인 투자자 자금을 10년 안에 갚겠다는 계획을 세웠던 것으로 확인됐다. 같은 계획안에서 최대 채권자인 메리츠금융그룹의 돈 1조2000억원은 1~2년 차에 우선 갚는 것으로 설계됐다. 홈플러스는 앞서 “전단채를 100% 현금 변제하겠다”고 약속했는데 실제로 개인 투자자 몫은 장기 분할·무이자 변제 뒤로 미뤄져 있었던 셈이다. 7일 국민일보가 단독 입수한 6월 29일 자 홈플러스 수정 회생 계획안을 보면 전단채가 포함된 회생채권은 개인 투자자 명의가 아니라 롯데카드(2286억원)와 현대카드(2245억원), 신한카드(280억원) 명의의 총 4811억원짜리 ‘카드채권’으로 잡혀 있다. 개인 투자자는 계획안 어디에도 직접 등장하지 않는다. 변제 방식도 문제다. 홈플러스는 카드채권 원금에 ‘전액 현금 변제하겠다’는 단서를 달았지만 상환은 회생 제6차 연도인 2033년부터 제10차 연도인 2037년까지 5년에 걸쳐 이뤄진다. 구체적인 연도별 상환액은 2033년 183억원, 2034년 751억원, 2035년 791억원, 2036년 816억원, 2037년 2270억원이다. 그마저도 절반에 가까운 47%가 마지막 해에 몰려 있다. 지금으로부터 11년 뒤인 2037년이 돼야 변제가 마무리되는 것이다. 회생 개시 후 이자는 전액 면제된다. 개인 투자자는 10년을 기다려도 이자 한 푼 받을 수 없다. 반면 메리츠금융 채권 1조2397억원은 준비 연도와 제1차 연도, 즉 올해와 내년에 대부분 변제하도록 설계돼 있다. 같은 회생채권으로 묶여 있지만 개인 투자자 채권과 메리츠금융 채권의 변제 순서가 완전히 다른 것이다. 개인 투자자 권리는 최근 들어 후퇴했다. 홈플러스가 지난 1월 작성한 계획안에서는 카드채권이 2026~2027년 전액 현금 변제되는 것으로 명시돼 있었다. 약 5개월 새 개인 투자자 전단채 자금 변제 시기가 9~10년 밀린 것이다. 이 기간 홈플러스 재무 상태가 계획보다 크게 나빠진 것이 원인으로 풀이된다. 알짜 자산으로 꼽혔던 기업형 슈퍼마켓(SSM) 사업부 홈플러스 익스프레스는 3000억대로 거론되던 몸값의 3분의 1 수준인 1200억원에 팔렸다. 지난해 3월부터 올해 2월까지 매출은 5조7963억원으로 1년 전보다 17% 감소했다. 당기순손실은 1조원을 넘겼다. 이 계획안은 서울회생법원이 지난 3일 홈플러스의 회생을 중단하면서 실행력이 사라졌다. 그러나 앞으로 남은 절차에서도 적지 않은 영향력을 미칠 수 있다. 우선 홈플러스가 오는 20일까지 자금 부족분 2000억원을 구해 회생을 재진행할 경우에는 계획안에 적힌 순서대로 변제가 이뤄질 가능성이 크다. 파산으로 넘어가면 불확실성은 더 커진다. 전단채 개인 투자자는 담보 없는 ‘일반 파산채권자’로 분류될 가능성이 크다. 이 경우 직전 계획안에서 전단채가 100% 변제되는 ‘상거래채권’이 아니라 카드채권으로 다뤄진 이력을 파산관재인이 주된 참고 자료로 작용할 수 있다는 분석이다. 회생과 파산에 능한 금융권 관계자는 “회생 과정에서 상거래채권이 아니라 카드채권 등 금융 채권으로 분류됐던 이력은 파산으로 넘어가더라도 상당한 관성을 갖는다”면서 “전단채 개인 투자자 입장에서는 채권 성격을 다시 다투는 것 자체가 큰 비용이 드는 싸움이 될 것”이라고 말했다.', 'crawl', '국민일보', '2026-07-07 05:57:00', '보수', 'ready', 'https://image.kmib.co.kr/online_image/2026/0707/2026070714541248126_1783403653_0030075767.jpg', '2026-07-07 06:04:26', '2026-07-07 15:50:26.65255', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3217, 'https://www.kmib.co.kr/rss/data/kmibSocRss.xml', NULL, 'https://www.kmib.co.kr/article/view.asp?arcid=0030075415', '사회', '‘피습 자작극’ 의혹 정이한 전 부산시장 후보 구속영장 신청', '6·3 지방선거 당시 ‘선거 테러’ 피해를 주장했다가 피습 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보에 대해 경찰이 구속영장을 신청했다. 사건 발생 67일 만이자 지방선거가 끝난 지 한 달여 만이다. 부산 금정경찰서는 위계에 의한 공무집행방해와 공직선거법 위반 등의 혐의로 정 전 후보와 음료를 던진 헬스 트레이너 A씨(30대)에 대해 지난 1일 구속영장을 신청했다고 7일 밝혔다. 검찰은 지난 3일 부산지법에 구속영장을 청구했으며, 구속 전 피의자 심문(영장실질심사)은 오는 8일 오후 2시 부산지법에서 열린다. 경찰은 증거인멸과 도주 우려 등을 이유로 구속영장을 신청한 것으로 알려졌다. 정 전 후보와 A씨는 지난 4월 27일 부산 금정구 구서나들목 인근에서 발생한 ‘음료 투척 사건’을 사전에 공모해 자작극을 벌인 혐의를 받고 있다. 당시 A씨는 유세 중이던 정 전 후보를 향해 “어린놈의 XX가 무슨 시장이냐”고 외치며 음료가 담긴 컵을 던졌다. 정 전 후보 측은 음료를 피하려다 넘어져 의식을 잃고 병원으로 이송됐으며 뇌진탕과 근좌상 진단을 받았다고 밝혔다. 이후 이번 사건을 ‘선거 테러’이자 ‘민주주의 압살 행위’라고 주장했다. 그러나 경찰은 수사 과정에서 두 사람이 사건 전 통화한 기록을 확보했고, A씨가 정 전 후보와 원래부터 친분이 있던 사이인 것으로 파악했다. 경찰은 통화 내역과 금전 거래 여부 등을 토대로 사전 공모 가능성을 집중 수사해 왔다. 경찰은 선거 다음 날 정 전 후보 선거사무실을 압수수색을 한 데 이어 캠프 관계자들을 참고인으로 불러 당시 상황과 사건 이후 언론 대응 경위 등을 조사했다. 이와 별도로 경찰은 음료 투척 사건 당시 정 전 후보가 뇌진탕과 근좌상 진단받은 온병원의 진단서 발급 과정과 의료법 위반 의혹도 수사하고 있다. 온병원은 정 전 후보 부친이 회장으로 있는 온그룹 계열 병원이다. 경찰은 이와 함께 온그룹 계열사인 바로미터여론연구소를 둘러싼 의혹도 별도로 들여다보고 있다. 경찰 관계자는 “이번 구속영장 실질심사는 음료 투척 사건을 둘러싼 ‘피습 자작극’ 의혹에 대한 혐의에 한정된 것”이라며 “온병원과 바로미터여론연구소 관련 의혹 등 나머지 고발 사건은 별도로 계속 수사하고 있다”고 말했다. 부산=윤일선 기자 news8282@kmib.co.kr', '지난 4월 음료 투척 사건 직후 병원 응급실에서 치료를 받고 있는 정이한 당시 개혁신당 부산시장 후보. 6·3 지방선거 당시 ‘선거 테러’ 피해를 주장했다가 피습 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보에 대해 경찰이 구속영장을 신청했다. 사건 발생 67일 만이자 지방선거가 끝난 지 한 달여 만이다. 부산 금정경찰서는 위계에 의한 공무집행방해와 공직선거법 위반 등의 혐의로 정 전 후보와 음료를 던진 헬스 트레이너 A씨(30대)에 대해 지난 1일 구속영장을 신청했다고 7일 밝혔다. 검찰은 지난 3일 부산지법에 구속영장을 청구했으며, 구속 전 피의자 심문(영장실질심사)은 오는 8일 오후 2시 부산지법에서 열린다. 경찰은 증거인멸과 도주 우려 등을 이유로 구속영장을 신청한 것으로 알려졌다. 정 전 후보와 A씨는 지난 4월 27일 부산 금정구 구서나들목 인근에서 발생한 ‘음료 투척 사건’을 사전에 공모해 자작극을 벌인 혐의를 받고 있다. 당시 A씨는 유세 중이던 정 전 후보를 향해 “어린놈의 XX가 무슨 시장이냐”고 외치며 음료가 담긴 컵을 던졌다. 정 전 후보 측은 음료를 피하려다 넘어져 의식을 잃고 병원으로 이송됐으며 뇌진탕과 근좌상 진단을 받았다고 밝혔다. 이후 이번 사건을 ‘선거 테러’이자 ‘민주주의 압살 행위’라고 주장했다. 그러나 경찰은 수사 과정에서 두 사람이 사건 전 통화한 기록을 확보했고, A씨가 정 전 후보와 원래부터 친분이 있던 사이인 것으로 파악했다. 경찰은 통화 내역과 금전 거래 여부 등을 토대로 사전 공모 가능성을 집중 수사해 왔다. 경찰은 선거 다음 날 정 전 후보 선거사무실을 압수수색을 한 데 이어 캠프 관계자들을 참고인으로 불러 당시 상황과 사건 이후 언론 대응 경위 등을 조사했다. 이와 별도로 경찰은 음료 투척 사건 당시 정 전 후보가 뇌진탕과 근좌상 진단받은 온병원의 진단서 발급 과정과 의료법 위반 의혹도 수사하고 있다. 온병원은 정 전 후보 부친이 회장으로 있는 온그룹 계열 병원이다. 경찰은 이와 함께 온그룹 계열사인 바로미터여론연구소를 둘러싼 의혹도 별도로 들여다보고 있다. 경찰 관계자는 “이번 구속영장 실질심사는 음료 투척 사건을 둘러싼 ‘피습 자작극’ 의혹에 대한 혐의에 한정된 것”이라며 “온병원과 바로미터여론연구소 관련 의혹 등 나머지 고발 사건은 별도로 계속 수사하고 있다”고 말했다.', 'crawl', '국민일보', '2026-07-07 04:54:01', '보수', 'ready', 'https://image.kmib.co.kr/online_image/2026/0707/2026070713525247899_1783399972_0030075415.jpeg', '2026-07-07 06:04:26', '2026-07-07 15:52:59.364373', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3225, 'https://www.kmib.co.kr/rss/data/kmibIntRss.xml', NULL, 'https://www.kmib.co.kr/article/view.asp?arcid=1783330695', '국제', '트럼프 “건국 250주년 행사 취소 결정, 내가 뒤집었다”', '도널드 트럼프 미국 대통령이 건국 250주년 기념일 행사가 폭풍우 등으로 취소됐다가 자신의 결정으로 뒤집혔다고 밝혔다. 행사 당일 백인우월주의 단체의 행진에 대해 더그 버검 미국 내무장관은 “표현의 자유”라고 언급해 옹호 논란이 일었다. 트럼프 대통령은 5일(현지시간) 트루스소셜에 “독립기념일인 4일 오후 7시5분 내셔널몰 일대에 42만4000명이 모였지만 악천후로 행사가 취소돼 관람객들이 대피해야 했다”며 “소식을 듣고 즉시 그 결정을 뒤집었고, 잠시 뒤 최소 15만명이 돌아와 행사를 예정대로 진행할 수 있었다”고 주장했다. 그는 또 관람객들의 대피와 재입장을 지원한 비밀경호국(SS)과 법 집행 기관을 치하하며 “정말 놀라운 밤이었다. 불꽃놀이가 끝난 직후부터 폭우가 쏟아져 더욱 극적인 마무리를 장식했다”고 덧붙였다. 트럼프 대통령은 전날 워싱턴 내셔널몰에서 진행한 독립기념일 연설에서도 “참모들이 다음 주에 행사를 하자고 했지만 안 된다고 했다”며 “독립선언 250주년은 바로 오늘이기 때문”이라고 말했다. 이날 행사는 밤 9시가 넘어서 재개됐다. 대통령 연설도 예정보다 1시간30분가량 늦어진 밤 11시15분에 시작됐다. 악천후 속에서도 자신의 건재함을 과시하기 위해 “역대 가장 긴 연설을 하겠다”고 호언장담했던 트럼프 대통령은 예상과 달리 약 40분 만에 연설을 마무리했다. 한편 버검 장관은 이날 CNN에 나와 백인우월주의 단체 ‘애국 전선’(패트리엇 프런트) 회원들의 워싱턴DC 행진에 대한 질문을 받고 “그들이 내세우는 가치에는 동의할 수 없지만 미국의 근본 원칙은 민주주의를 복잡하게 만들기는 해도 표현의 자유”라고 말했다. 지난 2017년 버지니아주 샬러츠빌 극우 폭력시위를 계기로 결성된 애국 전선 회원들은 전날 남부연합기를 든 채 의회 의사당으로 행진하며 “미국을 되찾자”, “앵글로색슨 혈통의 독립을 쟁취하자” 등의 구호를 외쳤다. 이 과정에서 지하철에 홀로 앉아 있던 흑인 여성을 둘러싼 모습이 로이터통신을 통해 공개되기도 했다. 천금주 기자 juju79@kmib.co.kr', '지난 4일(현지시간) 워싱턴DC 이스턴마켓 지하철역에서 백인우월주의 단체 ‘애국 전선’ 소속의 한 회원이 손가락질을 하고 있다. 도널드 트럼프 미국 대통령이 건국 250주년 기념일 행사가 폭풍우 등으로 취소됐다가 자신의 결정으로 뒤집혔다고 밝혔다. 행사 당일 백인우월주의 단체의 행진에 대해 더그 버검 미국 내무장관은 “표현의 자유”라고 언급해 옹호 논란이 일었다. 트럼프 대통령은 5일(현지시간) 트루스소셜에 “독립기념일인 4일 오후 7시5분 내셔널몰 일대에 42만4000명이 모였지만 악천후로 행사가 취소돼 관람객들이 대피해야 했다”며 “소식을 듣고 즉시 그 결정을 뒤집었고, 잠시 뒤 최소 15만명이 돌아와 행사를 예정대로 진행할 수 있었다”고 주장했다. 그는 또 관람객들의 대피와 재입장을 지원한 비밀경호국(SS)과 법 집행 기관을 치하하며 “정말 놀라운 밤이었다. 불꽃놀이가 끝난 직후부터 폭우가 쏟아져 더욱 극적인 마무리를 장식했다”고 덧붙였다. 트럼프 대통령은 전날 워싱턴 내셔널몰에서 진행한 독립기념일 연설에서도 “참모들이 다음 주에 행사를 하자고 했지만 안 된다고 했다”며 “독립선언 250주년은 바로 오늘이기 때문”이라고 말했다. 이날 행사는 밤 9시가 넘어서 재개됐다. 대통령 연설도 예정보다 1시간30분가량 늦어진 밤 11시15분에 시작됐다. 악천후 속에서도 자신의 건재함을 과시하기 위해 “역대 가장 긴 연설을 하겠다”고 호언장담했던 트럼프 대통령은 예상과 달리 약 40분 만에 연설을 마무리했다. 한편 버검 장관은 이날 CNN에 나와 백인우월주의 단체 ‘애국 전선’(패트리엇 프런트) 회원들의 워싱턴DC 행진에 대한 질문을 받고 “그들이 내세우는 가치에는 동의할 수 없지만 미국의 근본 원칙은 민주주의를 복잡하게 만들기는 해도 표현의 자유”라고 말했다. 지난 2017년 버지니아주 샬러츠빌 극우 폭력시위를 계기로 결성된 애국 전선 회원들은 전날 남부연합기를 든 채 의회 의사당으로 행진하며 “미국을 되찾자”, “앵글로색슨 혈통의 독립을 쟁취하자” 등의 구호를 외쳤다. 이 과정에서 지하철에 홀로 앉아 있던 흑인 여성을 둘러싼 모습이 로이터통신을 통해 공개되기도 했다.', 'crawl', '국민일보', '2026-07-06 10:00:06', '보수', 'ready', 'https://image.kmib.co.kr/online_image/2026/0706/2026070618590644367_1783331946_1783330695.jpg', '2026-07-07 06:04:26', '2026-07-07 15:56:37.386219', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3227, 'https://www.kmib.co.kr/rss/data/kmibIntRss.xml', NULL, 'https://www.kmib.co.kr/article/view.asp?arcid=1783329134', '국제', '하메네이 세 아들 개전 후 첫 등장… ‘후계자’ 모즈타바는 불참', '아야톨라 알리 하메네이 전 이란 최고지도자의 장례식에 후계자인 모즈타바 하메네이를 제외한 세 아들이 이란 전쟁 개전 후 처음으로 모습을 드러냈다. 모즈타바는 공격 가능성 등을 고려해 은신 중인 것으로 알려졌다. AP통신, 로이터통신 등 외신은 5일(현지시간) 하메네이의 세 아들과 다른 가족 4명이 고인의 관 옆에서 기도를 올렸으나 모즈타바의 모습은 확인되지 않았다고 보도했다. 공개 석상에 모즈타바가 모습을 드러내지 않으면서 건강 상태에 대한 의구심이 제기되고 있다고 CNN은 짚었다. 그는 얼굴과 다리 등에 심한 부상을 입은 것으로 전해졌으나 개전 후 사진이나 육성이 공개된 적이 없다. 하메네이와 같은 날 공습으로 사망한 미나브 지역 학생들의 유가족도 애도 행사에 참석했다. 워싱턴포스트(WP)는 여학생들이 다니는 초등학교에서 최소 175명이 숨졌다고 보도했다. WP는 해당 공습이 미군 토마호크 미사일 공격으로 추정되지만 미국이 이에 대한 책임을 인정하지 않으면서 이란에서 이들의 죽음이 전쟁의 부당함을 상징하게 됐다고 전했다. 장례식에는 전날에 이어 복수를 상징하는 붉은 깃발을 든 시민들이 등장했다. “트럼프를 죽여라” 등의 구호가 쏟아지기도 했다. 이스라엘 매체 제이피드는 도널드 트럼프 미국 대통령을 포함한 미 고위층을 겨냥해 이란 이슬람혁명수비대(IRGC)가 특수부대 ‘무크타르’를 설립했다고 정보기관 보고서를 인용해 보도했다. 모즈타바를 보기 위해 장례식을 찾은 조문객들은 아쉬움을 전했다. 한 여성은 “기도가 시작되기 직전까지 주변 사람들에게 그(모즈타바)가 직접 오기를 바란다고 계속 말했다”며 “유일한 소원이었다”고 타스님통신에 말했다. 또 다른 조문객도 로이터통신에 “장례식 중 새로운 최고 지도자를 보기를 기대했다”고 말했다. 이번 장례식을 두고 단순 애도를 넘어 이란 지도부 체제가 견고하다는 걸 알리기 위한 행사라는 분석이 나온다. 알자지라방송은 “거의 40년 동안 이란을 이끌어 온 인물이 암살당한 후에도 체제의 연속성이 유지되고 있음을 과시하는 자리”라며 “그가 구축한 제도들은 여전히 건재하며 권력 이양이 차질 없이 진행되고 있다는 메시지를 전달하는 것”이라고 짚었다. 이란 당국은 최대 1500만명이 장례식에 참여할 것으로 전망된다며 단결된 모습을 강조했지만 내부에선 다른 목소리도 감지됐다. 익명을 조건으로 인터뷰에 응한 한 시민은 “사람들의 삶을 망쳐놓은 한 사람을 위해 도시 전체를 마비시킨다는 사실에 화가 난다”고 CNN에 말했다. 그는 “아무것도 변한 게 없다”며 “모즈타바도 별반 다르지 않을 것”이라고 덧붙였다. 테헤란에서 시간제 교수로 일하는 30대 여성은 조문객 수가 부풀려졌다고 주장했다. 그는 “가장 낙관적인 시나리오를 가정해도 하루 100만명에 도달할 가능성은 거의 없다”고 말했다. 그러면서 “그들이 이 일에 얼마나 많은 돈을 쏟아부었는지 한번 보라”고 비판했다. 권민지 기자 10000g@kmib.co.kr', '지난 2월 미국과 이스라엘의 공습으로 사망한 아야톨라 알리 하메네이 전 이란 최고지도자와 그 가족들의 관을 실은 운구 차량이 6일(현지시간) 이란 수도 테헤란에서 이동하고 있다. 아야톨라 알리 하메네이 전 이란 최고지도자의 장례식에 후계자인 모즈타바 하메네이를 제외한 세 아들이 이란 전쟁 개전 후 처음으로 모습을 드러냈다. 모즈타바는 공격 가능성 등을 고려해 은신 중인 것으로 알려졌다. AP통신, 로이터통신 등 외신은 5일(현지시간) 하메네이의 세 아들과 다른 가족 4명이 고인의 관 옆에서 기도를 올렸으나 모즈타바의 모습은 확인되지 않았다고 보도했다. 공개 석상에 모즈타바가 모습을 드러내지 않으면서 건강 상태에 대한 의구심이 제기되고 있다고 CNN은 짚었다. 그는 얼굴과 다리 등에 심한 부상을 입은 것으로 전해졌으나 개전 후 사진이나 육성이 공개된 적이 없다. 하메네이와 같은 날 공습으로 사망한 미나브 지역 학생들의 유가족도 애도 행사에 참석했다. 워싱턴포스트(WP)는 여학생들이 다니는 초등학교에서 최소 175명이 숨졌다고 보도했다. WP는 해당 공습이 미군 토마호크 미사일 공격으로 추정되지만 미국이 이에 대한 책임을 인정하지 않으면서 이란에서 이들의 죽음이 전쟁의 부당함을 상징하게 됐다고 전했다. 장례식에는 전날에 이어 복수를 상징하는 붉은 깃발을 든 시민들이 등장했다. “트럼프를 죽여라” 등의 구호가 쏟아지기도 했다. 이스라엘 매체 제이피드는 도널드 트럼프 미국 대통령을 포함한 미 고위층을 겨냥해 이란 이슬람혁명수비대(IRGC)가 특수부대 ‘무크타르’를 설립했다고 정보기관 보고서를 인용해 보도했다. 모즈타바를 보기 위해 장례식을 찾은 조문객들은 아쉬움을 전했다. 한 여성은 “기도가 시작되기 직전까지 주변 사람들에게 그(모즈타바)가 직접 오기를 바란다고 계속 말했다”며 “유일한 소원이었다”고 타스님통신에 말했다. 또 다른 조문객도 로이터통신에 “장례식 중 새로운 최고 지도자를 보기를 기대했다”고 말했다. 이번 장례식을 두고 단순 애도를 넘어 이란 지도부 체제가 견고하다는 걸 알리기 위한 행사라는 분석이 나온다. 알자지라방송은 “거의 40년 동안 이란을 이끌어 온 인물이 암살당한 후에도 체제의 연속성이 유지되고 있음을 과시하는 자리”라며 “그가 구축한 제도들은 여전히 건재하며 권력 이양이 차질 없이 진행되고 있다는 메시지를 전달하는 것”이라고 짚었다. 이란 당국은 최대 1500만명이 장례식에 참여할 것으로 전망된다며 단결된 모습을 강조했지만 내부에선 다른 목소리도 감지됐다. 익명을 조건으로 인터뷰에 응한 한 시민은 “사람들의 삶을 망쳐놓은 한 사람을 위해 도시 전체를 마비시킨다는 사실에 화가 난다”고 CNN에 말했다. 그는 “아무것도 변한 게 없다”며 “모즈타바도 별반 다르지 않을 것”이라고 덧붙였다. 테헤란에서 시간제 교수로 일하는 30대 여성은 조문객 수가 부풀려졌다고 주장했다. 그는 “가장 낙관적인 시나리오를 가정해도 하루 100만명에 도달할 가능성은 거의 없다”고 말했다. 그러면서 “그들이 이 일에 얼마나 많은 돈을 쏟아부었는지 한번 보라”고 비판했다.', 'crawl', '국민일보', '2026-07-06 10:00:04', '보수', 'ready', 'https://image.kmib.co.kr/online_image/2026/0706/2026070618540544332_1783331645_1783329134.jpg', '2026-07-07 06:04:26', '2026-07-07 15:56:56.559002', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3244, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003699114', 'https://www.newsis.com/view/NISX20260707_0003699114', '정치', '靑 "미래대응기금, 특별법 형태로 신설…8월말 정부 예산안 편성쯤 내용 담아야"', '[서울=뉴시스]김경록 기자 = 류덕현 청와대 재정기획보좌관은 7일 당정이 미래 과제 대응을 위해 신설하기로 협의한 미래대응기금에 대해 "특별법의 형태를 가져서 기금을 신설해야 될 거라고 생각이 든다"며 "국회와 잘 협의하고 소통해서 절차가 완비되도록 준비할 계획을 갖고 있다"고 밝혔다. 류 보좌관은 이날 오전 청와대 오픈스튜디오에서 진행된 성기홍 홍보소통수석과의 ''팩트방앗간'' 인터뷰 중 미래대응기금 신설 로드맵에 대해 이같이 말했다. 미래대응기금은 반도체 슈퍼사이클로 인한 추가세수를 3대 메가프로젝트, 청년 지원, 양극화 완화 등에 투입할 목적으로 지난 5일 고위당정협의회에서 신설하기로 정한 새 기금이다. 류 보좌관은 이에 대해 "국민들에게 알려드리는 여러가지 절차"를 언급하며 "일주일 후 국가재정전략회의를 통해 어느 정도 알려드리고 학계, 언론, 여러가지 공적인 기구를 통해 충분히 소통하고 공감대를 형성해나갈 수 있도록 정부와 같이 준비하도록 하겠다"고 했다. 미래대응기금이 실제 편성되는 시점으로는 "원래 정부는 8월 말에 내년도 예산안을 제출하기로 돼있다"며 "가깝게는 정부 예산안 편성 즈음 구체적인 내용들을 담아야 되기 때문에 신속하게 준비하는 걸 목표하고 있다"고 설명했다. 올해 추가로 들어올 세수 규모에 대해서는 "공식적으로는 9월에 정부가 세수 전망을 새로 하게 된다. 얼마가 더 들어올지 아직은 불분명하긴 하다"면서도 "올해 추경을 할 때보다 좀 더 추가적으로 들어올 거라고 생각을 하고 있다"고 답했다. 앞서 정부는 지난 3월 법인세 등으로 인한 추가세수 25조2000억원에 기금 여유재원 1조원을 더해 총 26조2000억원 규모의 빚 없는 추가경정예산안을 편성한 바 있다. 류 보좌관은 "내년이나 내후년에 얼마 정도 들어올 거냐에 대해서는 사실 예측하기 쉽지는 않지만 상당한 규모의 추가 세수가 내년, 내후년 정도까지 들어올 거로 생각되고 있다"고 덧붙였다. ◎공감언론 뉴시스 knockrok@newsis.com', '靑 "미래대응기금, 특별법 형태로 신설…8월말 정부 예산안 편성쯤 내용 담아야" 등록 2026.07.07 14:12:23 수정 2026.07.07 14:16:40 구글에서 선호하는 매체로 추가 작게 크게 "일주일 뒤 국가재정전략회의…국회와도 잘 협의하고 소통" "정부 공식 추가세수 전망 9월에…올해 추경 때보다 추가될 듯" [서울=뉴시스]김경록 기자 = 류덕현 청와대 재정기획보좌관은 7일 당정이 미래 과제 대응을 위해 신설하기로 협의한 미래대응기금에 대해 "특별법의 형태를 가져서 기금을 신설해야 될 거라고 생각이 든다"며 "국회와 잘 협의하고 소통해서 절차가 완비되도록 준비할 계획을 갖고 있다"고 밝혔다. 류 보좌관은 이날 오전 청와대 오픈스튜디오에서 진행된 성기홍 홍보소통수석과의 ''팩트방앗간'' 인터뷰 중 미래대응기금 신설 로드맵에 대해 이같이 말했다. 미래대응기금은 반도체 슈퍼사이클로 인한 추가세수를 3대 메가프로젝트, 청년 지원, 양극화 완화 등에 투입할 목적으로 지난 5일 고위당정협의회에서 신설하기로 정한 새 기금이다. 류 보좌관은 이에 대해 "국민들에게 알려드리는 여러가지 절차"를 언급하며 "일주일 후 국가재정전략회의를 통해 어느 정도 알려드리고 학계, 언론, 여러가지 공적인 기구를 통해 충분히 소통하고 공감대를 형성해나갈 수 있도록 정부와 같이 준비하도록 하겠다"고 했다. 미래대응기금이 실제 편성되는 시점으로는 "원래 정부는 8월 말에 내년도 예산안을 제출하기로 돼있다"며 "가깝게는 정부 예산안 편성 즈음 구체적인 내용들을 담아야 되기 때문에 신속하게 준비하는 걸 목표하고 있다"고 설명했다. 올해 추가로 들어올 세수 규모에 대해서는 "공식적으로는 9월에 정부가 세수 전망을 새로 하게 된다. 얼마가 더 들어올지 아직은 불분명하긴 하다"면서도 "올해 추경을 할 때보다 좀 더 추가적으로 들어올 거라고 생각을 하고 있다"고 답했다. 앞서 정부는 지난 3월 법인세 등으로 인한 추가세수 25조2000억원에 기금 여유재원 1조원을 더해 총 26조2000억원 규모의 빚 없는 추가경정예산안을 편성한 바 있다. 류 보좌관은 "내년이나 내후년에 얼마 정도 들어올 거냐에 대해서는 사실 예측하기 쉽지는 않지만 상당한 규모의 추가 세수가 내년, 내후년 정도까지 들어올 거로 생각되고 있다"고 덧붙였다.', 'crawl', '뉴시스', '2026-07-07 14:12:23', '중도', 'ready', 'https://img1.newsis.com/2025/09/04/NISI20250904_0020961612_web.jpg?rnd=20250904161835', '2026-07-07 06:04:27', '2026-07-07 15:59:14.431295', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3266, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698886', 'https://www.newsis.com/view/NISX20260707_0003698886', '정치', '국힘 "野 추천 선관위 특검해야 공정성 시비 없어…與, 조건없이 수용해야"', '[서울=뉴시스]김지훈 한은진 기자 = 국민의힘은 7일 6·3 지방선거 투표용지 부족사태 진상규명을 위한 특검은 야당 추천 특검으로 해야 공정성이 담보된다고 강조하면서 더불어민주당이 이를 수용할 것을 촉구했다. 국민의힘 6·3 국민참정권 침해 진상규명 및 선거관리 개혁 특별위원회 위원장을 맡고 있는 박대출 의원은 이날 오전 국회에서 열린 특위 2차 회의에서 "선관위의 개혁은 비호하는 특검이 아니라 기득권을 깨는 특검에서 출발해야 한다"라며 "야당 추천 특검만이 공정성 시비 없는 유일한 퍼즐 조각"이라고 했다. 그는 "지난 한 달여 동안 선관위의 문제점과 의혹이 해소되기는커녕 고구마 줄기처럼 계속 드러나고 있음에도 위철환(상임위원)은 버티기에 들어간 듯하다"라며 "무능하고, 무책임하고, 몰염치한 작태다. 선관위에 엄중히 책임을 물어야 한다"고 했다. 그는 특히 "위철환은 이재명 대통령과 연수원 동기이자 대한변협 회장 출신"이라며 "여당 추천 특검이나 대한변협 등을 염두에 둔 제3자 추천 특검은 애초에 고려 대상에도 올라서는 안 될 것"이라고 했다. 민주당의 ''제3자 추천 특검''에 반대 입장을 분명히 한 것이다. 박 의원은 선관위 내부자들의 협조도 요청했다. 그는 "선관위 내부 비위와 불법, 국민이 알아야 할 사실이 있다면 의로운 목소리를 내달라"며 "이를 위해 특위에서는 선관위 내부 고발자 면책안을 제안하겠다. 공익 신고자를 지원하기 위해 익명성 보장과 수사 과정에서의 불처벌 등 보호 원칙을 세워줄 것을 정부에 촉구한다"고 했다. 정희용 사무총장은 앞서 국회에서 열린 원내대책회의에서 "민주당은 신속한 특검 도입을 말하면서도 추천 방식 핑계 대며 딴지 걸고 있다"라며 "이번 사태의 진상 규명은 물론 선관위의 무능과 부실의 실태를 철저히 밝혀내기 위해 민주당은 하루라도 빨리 제1야당 추천 특검을 조건 없이 수용하라"고 했다. 아울러 "제3자 추천 방식이 공정하다는 주장은 지금까지 민주당이 강행 처리한, 제3자 추천 방식이 아닌 특검들은 모두 공정하지 않았다는 고백인가"라고 덧붙였다. ◎공감언론 뉴시스 jikime@newsis.com, gold@newsis.com', '국힘 "野 추천 선관위 특검해야 공정성 시비 없어…與, 조건없이 수용해야" 등록 2026.07.07 11:32:57 수정 2026.07.07 13:38:25 구글에서 선호하는 매체로 추가 작게 크게 "변협 등 염두 제3자 추천 특검 고려 대상 올라선 안 될 것" [서울=뉴시스] 김근수 기자 = 박대출(가운데) 국민의힘 6.3 국민참정권 침해 진상규명 및 선거관리 개혁 특별위원회 위원장이 7일 오전 서울 여의도에서 열린 6.3 국민참정권 침해 진상규명 및 선거관리 개혁 특별위원회 2차 회의에서 인사말을 하고 있다. 2026.07.07. [서울=뉴시스]김지훈 한은진 기자 = 국민의힘은 7일 6·3 지방선거 투표용지 부족사태 진상규명을 위한 특검은 야당 추천 특검으로 해야 공정성이 담보된다고 강조하면서 더불어민주당이 이를 수용할 것을 촉구했다. 국민의힘 6·3 국민참정권 침해 진상규명 및 선거관리 개혁 특별위원회 위원장을 맡고 있는 박대출 의원은 이날 오전 국회에서 열린 특위 2차 회의에서 "선관위의 개혁은 비호하는 특검이 아니라 기득권을 깨는 특검에서 출발해야 한다"라며 "야당 추천 특검만이 공정성 시비 없는 유일한 퍼즐 조각"이라고 했다. 그는 "지난 한 달여 동안 선관위의 문제점과 의혹이 해소되기는커녕 고구마 줄기처럼 계속 드러나고 있음에도 위철환(상임위원)은 버티기에 들어간 듯하다"라며 "무능하고, 무책임하고, 몰염치한 작태다. 선관위에 엄중히 책임을 물어야 한다"고 했다. 그는 특히 "위철환은 이재명 대통령과 연수원 동기이자 대한변협 회장 출신"이라며 "여당 추천 특검이나 대한변협 등을 염두에 둔 제3자 추천 특검은 애초에 고려 대상에도 올라서는 안 될 것"이라고 했다. 민주당의 ''제3자 추천 특검''에 반대 입장을 분명히 한 것이다. 박 의원은 선관위 내부자들의 협조도 요청했다. 그는 "선관위 내부 비위와 불법, 국민이 알아야 할 사실이 있다면 의로운 목소리를 내달라"며 "이를 위해 특위에서는 선관위 내부 고발자 면책안을 제안하겠다. 공익 신고자를 지원하기 위해 익명성 보장과 수사 과정에서의 불처벌 등 보호 원칙을 세워줄 것을 정부에 촉구한다"고 했다. 정희용 사무총장은 앞서 국회에서 열린 원내대책회의에서 "민주당은 신속한 특검 도입을 말하면서도 추천 방식 핑계 대며 딴지 걸고 있다"라며 "이번 사태의 진상 규명은 물론 선관위의 무능과 부실의 실태를 철저히 밝혀내기 위해 민주당은 하루라도 빨리 제1야당 추천 특검을 조건 없이 수용하라"고 했다. 아울러 "제3자 추천 방식이 공정하다는 주장은 지금까지 민주당이 강행 처리한, 제3자 추천 방식이 아닌 특검들은 모두 공정하지 않았다는 고백인가"라고 덧붙였다.', 'crawl', '뉴시스', '2026-07-07 11:32:57', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0021352999_web.jpg?rnd=20260707102709', '2026-07-07 06:04:27', '2026-07-07 16:04:22.435306', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3272, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698797', 'https://www.newsis.com/view/NISX20260707_0003698797', '정치', '한병도 "올림픽공원 투표지 247만장, 재검표·수개표 추진 방안 적극 검토"', '[서울=뉴시스]정금민 김윤영 기자 = 한병도 더불어민주당 당대표 직무대행 겸 원내대표는 7일 올림픽공원 핸드볼 경기장에 보관된 6·3 지방선거 투표용지 247만장에 대해 "재검표와 수개표를 여야 협의를 통해 국정조사 특별위원회(국조특위)에서 추진하는 방안을 적극 검토하겠다"고 했다. 한 대행은 국조특위의 선거관리위원회 대상 2차 현장조사가 예정된 이날 국회에서 원내대책회의를 열어 이같이 말했다. 그는 "선관위 국조특위는 오늘 중앙선관위와 서울시선관위를 찾아 2차 현장조사를 진행한다"며 "투표지 인쇄 물량 축소 과정과 의사결정 체계, 선거 당일 지휘 체계를 면밀히 점검해 사태의 실체를 규명하고 책임 소재를 명확히 밝히겠다"고 했다. 이어 "민주당은 이미 당론으로 특검법을 추진하기로 정했고, 정치적 논란을 최소화할 수 있도록 제3자 추천 방식을 제안했다"며 "그런데도 국민의힘은 정치적 유불리를 따지며 야당 단독 추천을 고집하고 있다"고 했다. 또 "중요한 것은 국민참정권 침해의 진상을 밝히고, 책임자 처벌을 통해 선거사무에 대한 국민 신뢰를 회복하는 일"이라며 "선관위도 책임을 다해야 한다"고 했다. 그러면서 "국민의힘도 국민참정권을 정쟁으로 몰아가려는 시도를 그만두고, 실체적 진실을 밝혀내는 데 온 힘을 모으길 바란다"고 했다. 김성회 원내대변인은 회의 이후 기자들과 만나 "재검표가 필요하면 하자는 것이 민주당의 입장"이라며 "오늘 국조특위 현장 조사를 하는데 (여야) 간사 간 논의하고, 위원장 간 얘기를 할 것이다. 국민의힘과 원활히 논의될 것이라고 본다"고 했다. ◎공감언론 뉴시스 happy7269@newsis.com, youn@newsis.com', '한병도 더불어민주당 대표 직무대행 겸 원내대표가 7일 서울 여의도 국회에서 열린 원내대책회의에서 발언하고 있다. 2026.07.07. 한병도 더불어민주당 당대표 직무대행 겸 원내대표는 7일 올림픽공원 핸드볼 경기장에 보관된 6·3 지방선거 투표용지 247만장에 대해 "재검표와 수개표를 여야 협의를 통해 국정조사 특별위원회(국조특위)에서 추진하는 방안을 적극 검토하겠다"고 했다. 한 대행은 국조특위의 선거관리위원회 대상 2차 현장조사가 예정된 이날 국회에서 원내대책회의를 열어 이같이 말했다. 그는 "선관위 국조특위는 오늘 중앙선관위와 서울시선관위를 찾아 2차 현장조사를 진행한다"며 "투표지 인쇄 물량 축소 과정과 의사결정 체계, 선거 당일 지휘 체계를 면밀히 점검해 사태의 실체를 규명하고 책임 소재를 명확히 밝히겠다"고 했다. 이어 "민주당은 이미 당론으로 특검법을 추진하기로 정했고, 정치적 논란을 최소화할 수 있도록 제3자 추천 방식을 제안했다"며 "그런데도 국민의힘은 정치적 유불리를 따지며 야당 단독 추천을 고집하고 있다"고 했다. 또 "중요한 것은 국민참정권 침해의 진상을 밝히고, 책임자 처벌을 통해 선거사무에 대한 국민 신뢰를 회복하는 일"이라며 "선관위도 책임을 다해야 한다"고 했다. 그러면서 "국민의힘도 국민참정권을 정쟁으로 몰아가려는 시도를 그만두고, 실체적 진실을 밝혀내는 데 온 힘을 모으길 바란다"고 했다. 김성회 원내대변인은 회의 이후 기자들과 만나 "재검표가 필요하면 하자는 것이 민주당의 입장"이라며 "오늘 국조특위 현장 조사를 하는데 (여야) 간사 간 논의하고, 위원장 간 얘기를 할 것이다. 국민의힘과 원활히 논의될 것이라고 본다"고 했다.', 'crawl', '뉴시스', '2026-07-07 11:05:45', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0021352987_web.jpg?rnd=20260707102607', '2026-07-07 06:04:27', '2026-07-07 16:05:33.508003', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3287, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698627', 'https://www.newsis.com/view/NISX20260707_0003698627', '정치', '한병도 "보완수사권 완전 폐지는 확고부동…이번주 형소법 개정안 발의 목표"', '[서울=뉴시스]정금민 김윤영 기자 = 한병도 더불어민주당 당대표 직무대행 겸 원내대표는 7일 보완수사권 존치 여부를 논의할 형사소송법 개정안과 관련해 "이번 주 내 발의를 목표로, 밀도 높고 내실 있는 논의에 속도를 높이겠다"고 했다. 한 대행은 이날 국회에서 열린 원내대책회의에서 "원내정책수석, 정책위 부의장, 법제사법위원회 간사와 행정안전위원회 간사가 참여하는 ''형사소송법 개정 TF(태스크포스)''를 중심으로 성안 작업에 착수했다"며 이같이 말했다. 그는 "보완수사권 완전 폐지는 민주당의 확고부동한 원칙이며, 당내 이견이 없다"며 "형사소송법 개정 또한, 이 명확한 원칙과 기준에 따라 흔들림 없이 수행할 것"이라고 했다. 이어 "(형사소송법) 개정안 처리도 제헌절 전이냐, 전당대회 전이냐 이야기가 있는데, 특정 시기를 고려하지 않고 신속하게 마무리하겠다"며 "충분한 숙의와 토론을 거치되, 빠른 시일 내에 통과시켜서 오는 10월 공소청·중대범죄수사청(중수청) 출범에 차질이 없도록 하겠다"고 했다. 그러면서 "민주당은 좌고우면하지 않을 것이다. 시대적 사명이자 역사의 명령인 검찰개혁의 마침표를 단호하게 찍겠다"고 했다. 앞서 민주당은 지난달 30일 법제사법위원장을 포함한 11곳의 상임위원장을 범여권 주도로 선출한 뒤 주요 입법 작업에 나서고 있다. 김용민 민주당 의원 등이 검찰 보완수사권 폐지를 골자로 한 형사소송법 개정안을 국회에 제출한 가운데, 실질적인 법안 논의는 원내지도부, 정책위, 법사위 간사, 행정안전위원회 간사가 공동으로 참여하는 형사소송법 개정 TF가 주도할 계획이다. 현재 당내 논의는 보완수사권 폐지에 초점이 맞춰지고 있지만, 일각에서는 경찰의 부실 수사 우려를 해소하기 위해 예외적·제한적인 보완수사권이 필요하다는 의견도 나오고 있다. ◎공감언론 뉴시스 happy7269@newsis.com, youn@newsis.com', '한병도 "보완수사권 완전 폐지는 확고부동…이번주 형소법 개정안 발의 목표" 구글에서 선호하는 매체로 추가 작게 크게 "형사소송법 개정 TF 중심으로 성안…특정 시기 고려 않고 신속 마무리" [서울=뉴시스] 고범준 기자 = 한병도 더불어민주당 대표 직무대행 겸 원내대표가 6일 서울 여의도 국회에서 열린 최고위원회의에서 발언하고 있다. 한 대행은 이날 국회에서 열린 원내대책회의에서 "원내정책수석, 정책위 부의장, 법제사법위원회 간사와 행정안전위원회 간사가 참여하는 ''형사소송법 개정 TF(태스크포스)''를 중심으로 성안 작업에 착수했다"며 이같이 말했다. 그는 "보완수사권 완전 폐지는 민주당의 확고부동한 원칙이며, 당내 이견이 없다"며 "형사소송법 개정 또한, 이 명확한 원칙과 기준에 따라 흔들림 없이 수행할 것"이라고 했다. 이어 "(형사소송법) 개정안 처리도 제헌절 전이냐, 전당대회 전이냐 이야기가 있는데, 특정 시기를 고려하지 않고 신속하게 마무리하겠다"며 "충분한 숙의와 토론을 거치되, 빠른 시일 내에 통과시켜서 오는 10월 공소청·중대범죄수사청(중수청) 출범에 차질이 없도록 하겠다"고 했다. 그러면서 "민주당은 좌고우면하지 않을 것이다. 시대적 사명이자 역사의 명령인 검찰개혁의 마침표를 단호하게 찍겠다"고 했다. 앞서 민주당은 지난달 30일 법제사법위원장을 포함한 11곳의 상임위원장을 범여권 주도로 선출한 뒤 주요 입법 작업에 나서고 있다. 김용민 민주당 의원 등이 검찰 보완수사권 폐지를 골자로 한 형사소송법 개정안을 국회에 제출한 가운데, 실질적인 법안 논의는 원내지도부, 정책위, 법사위 간사, 행정안전위원회 간사가 공동으로 참여하는 형사소송법 개정 TF가 주도할 계획이다. 현재 당내 논의는 보완수사권 폐지에 초점이 맞춰지고 있지만, 일각에서는 경찰의 부실 수사 우려를 해소하기 위해 예외적·제한적인 보완수사권이 필요하다는 의견도 나오고 있다.', 'crawl', '뉴시스', '2026-07-07 10:20:18', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0021351480_web.jpg?rnd=20260706101620', '2026-07-07 06:04:27', '2026-07-07 16:08:38.881716', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3289, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698548', 'https://www.newsis.com/view/NISX20260707_0003698548', '정치', '서영교 ''형소법 처리 시점''에 "전당대회 이후 넘어가기 어려울 것"', '[서울=뉴시스]신재현 기자 = 국회 법제사법위원장인 서영교 더불어민주당 의원이 7일 보완수사권 폐지 등 내용이 담긴 형사소송법 개정안 처리 시점과 관련해 "전당대회 이후로 넘어가기는 어렵지 않을까 생각한다"고 내다봤다. 민주당은 다음달 17일 차기 지도부 선출을 위한 전당대회를 치른다. 서 의원은 이날 KBS 라디오 ''전격시사''에서 "언제라고 못 박기는 쉽지 않지만 중대범죄수사청과 공소청이라는 조직이 10월 2일에 출범한다면 이로부터 6개월 전 정도에는 절차법인 형사소송법은 입법이 거의 완료됐어야 한다"고 밝혔다. 서 의원은 "(현재 시점에서 10월 2일까지) 남은 게 이제 2개월 반 정도 되기 때문에 (형소법 개정을) 최대한 빠르게 해나간다는 말씀을 드린다"며 "의견을 쭉 수렴해서 최대한 누구도 불편하지 않은 좋은 제도를 입법화하기 위해서 움직이고 있다"고 강조했다. 서 의원은 전날 국무조정실 산하 검찰개혁추진단 등을 만났다는 사실을 언급하며 "(의견 그룹을) 다양하게 만나서 현재 여러분들의 상황은 어느 정도이고 앞으로 그렇다면 어떤 것들이 반영되면 좋은지 (의견을 조율) 해나가는 상황"이라고도 했다. 이어 "민생 입법과 타 상임위에서 올라온 모든 아주 소중한 법들이 많다. 그런 법안들과 같이 진행해 나가면서 해나갈 예정이라서 할 수 있는 한 빠르게 할 예정"이라며 "전당대회 이후로 넘어가기는 어렵지 않을까 생각한다"고 덧붙였다. 서 의원은 검찰 수사권 폐지 후 경찰 견제 방안에 대해서는 수사심의위원회 실질화, 인권보호국 설치 등을 주장했다. 그는 "수사심의위원회를 실질화, 상설화해서 피해자의 목소리도 듣고 수사를 제대로 하는지도 볼 수 있다"며 "잘 못하면 과감하게 (인력) 교체도 하는 권한들이 있는 곳이 필요하다"고 말했다. ◎공감언론 뉴시스 again@newsis.com', '서영교 ''형소법 처리 시점''에 "전당대회 이후 넘어가기 어려울 것" 등록 2026.07.07 09:49:26 수정 2026.07.07 10:32:24 구글에서 선호하는 매체로 추가 작게 크게 "절차법 형사소송법, 중수청 등 출범 6개월 전 완료됐어야" "수사심의위 실질화할 수도…잘 못하면 교체하는 권한 필요" [서울=뉴시스] 정병혁 기자 = 서영교 신임 법제사법위원장이 지난 2일 서울 여의도 국회에서 열린 국회 법제사법위원회 전체회의에서 의사봉을 두드리고 있다. 2026.07.02. [서울=뉴시스]신재현 기자 = 국회 법제사법위원장인 서영교 더불어민주당 의원이 7일 보완수사권 폐지 등 내용이 담긴 형사소송법 개정안 처리 시점과 관련해 "전당대회 이후로 넘어가기는 어렵지 않을까 생각한다"고 내다봤다. 민주당은 다음달 17일 차기 지도부 선출을 위한 전당대회를 치른다. 서 의원은 이날 KBS 라디오 ''전격시사''에서 "언제라고 못 박기는 쉽지 않지만 중대범죄수사청과 공소청이라는 조직이 10월 2일에 출범한다면 이로부터 6개월 전 정도에는 절차법인 형사소송법은 입법이 거의 완료됐어야 한다"고 밝혔다. 서 의원은 "(현재 시점에서 10월 2일까지) 남은 게 이제 2개월 반 정도 되기 때문에 (형소법 개정을) 최대한 빠르게 해나간다는 말씀을 드린다"며 "의견을 쭉 수렴해서 최대한 누구도 불편하지 않은 좋은 제도를 입법화하기 위해서 움직이고 있다"고 강조했다. 서 의원은 전날 국무조정실 산하 검찰개혁추진단 등을 만났다는 사실을 언급하며 "(의견 그룹을) 다양하게 만나서 현재 여러분들의 상황은 어느 정도이고 앞으로 그렇다면 어떤 것들이 반영되면 좋은지 (의견을 조율) 해나가는 상황"이라고도 했다. 이어 "민생 입법과 타 상임위에서 올라온 모든 아주 소중한 법들이 많다. 그런 법안들과 같이 진행해 나가면서 해나갈 예정이라서 할 수 있는 한 빠르게 할 예정"이라며 "전당대회 이후로 넘어가기는 어렵지 않을까 생각한다"고 덧붙였다. 서 의원은 검찰 수사권 폐지 후 경찰 견제 방안에 대해서는 수사심의위원회 실질화, 인권보호국 설치 등을 주장했다. 그는 "수사심의위원회를 실질화, 상설화해서 피해자의 목소리도 듣고 수사를 제대로 하는지도 볼 수 있다"며 "잘 못하면 과감하게 (인력) 교체도 하는 권한들이 있는 곳이 필요하다"고 말했다.', 'crawl', '뉴시스', '2026-07-07 09:49:26', '중도', 'ready', 'https://img1.newsis.com/2026/07/02/NISI20260702_0021347880_web.jpg?rnd=20260702155842', '2026-07-07 06:04:27', '2026-07-07 16:08:57.088997', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3291, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698519', 'https://www.newsis.com/view/NISX20260707_0003698519', '정치', '김민석 "檢 보완수사권 폐지로 정리…여러가지 보완책 불가피"', '[서울=뉴시스] 한재혁 기자 = 김민석 전 국무총리는 7일 더불어민주당이 추진 중인 검사의 보완수사권 폐지와 관련 "현재로선 수사·기소 분리에 입각해 일단 폐지하는 쪽으로 정리해놓고 여러가지 보완책을 찾는 것이 큰 흐름으로 볼 때 검찰개혁의 과제를 풀어나가는 데 불가피성이 있다"고 했다. 김 전 총리는 이날 오전 KBS 라디오 ''전격시사''에 출연해 "(보완수사권 폐지 문제는) 대통령께서 공개적으로 여러 번, 우려가 없도록 여러 보완 장치나 고민을 하고 숙의가 필요하다고 하신 것"이라고 했다. 그는 "그런 것을 반영해서 저도 정부 내에서 충분한 숙의의 시간을 가졌던 것"이라며 "정부 내에서 토론회 등을 통해 다양한 (보완수사권 폐지와 관련된) 보완 아이디어가 나와 있다. 그런 부분을 포함해 국회에서 논의를 (하면 된다)"고 했다. 김 전 총리는 "원래는 (논의가) 다 끝난 다음에 정부가 (보완수사권 폐지) 동의 입장을 표현해야 하는 것을 선제적으로 표현한 것"이라며 "당에서 이러저러한 의원들의 안이 나와 있고, 준비되고 있는 것으로 알고 있어 그 과정에 그간 다양하게 제기된 보완적 의견은 참고 자료로 제공할 것"이라고 말했다. 김 전 총리는 자신이 지난 5월 당에 보완수사권 폐지 입장을 전달했다는 입장을 재차 밝혔다. 그는 "정청래 전 대표는 기억이 없다고 말씀하시고 한 두분의 최고위원은 ''우리도 모르는데 무슨 얘기냐''라고 말씀을 하는데, 그 분들은 모를 수 있다"며 "저도 최고위원을 했지만 최고위원은 직접적인 실무를 관할하는 라인에는 있지 않다"고 했다. 이어 "그렇지만 당내에서 검찰개혁과 관련해서 논의를 하는 중심적인 위치에 있는 분들을 통해서 최고 지도부까지 전달이 됐고 그것은 이미 다 근거가 있기 때문에 제가 없는 얘기를 할 필요도 없고 그 부분에 대해서도 앞으로 더 디테일이 나오면 충분히 얘기해 가면 된다고 본다"고 했다. 김 전 총리는 전날 친청(친정청래) 이성윤 최고위원이 자신을 향해 "계엄 해제 표결에 왜 참석하지 않았느냐" "김 전 총리가 감기약을 먹고 잤다는데 성분이 무엇이냐"고 물은 것을 두고는 "저는 ''국민의힘에서 얘기하는 것인가''라고 생각했다. 무슨 꼭 대장동 때를 보는 것 같다고 생각을 했다"고 했다. 이어 "일단 허위사실이다. 허위사실에 의한 명예훼손으로 이 시점에 그렇게 얘기를 하셔서 좀 걱정하고 있다"며 "''저런 식으로 정치를 하면 좀 어려워질텐데'' 이렇게 생각하고 있다"고 했다. 지지층 분열 양상에 대해선 "가령 친DJ, 친노, 친문, 친이재명이라고 해서 완전히 서로 다른 사람들이라고 보지 않지 않나. 결국은 같은 사람들"이라며 "다시 하나가 되도록 하는 것이 당 지도부의 임무이고 저는 상대적으로 가장 그것을 잘해낼 조건과 생각과 성향과 그런 마음을 가지고 있다"고 했다. ◎공감언론 뉴시스 saebyeok@newsis.com', '김민석 "檢 보완수사권 폐지로 정리…여러가지 보완책 불가피" 등록 2026.07.07 09:44:09 수정 2026.07.07 10:22:24 구글에서 선호하는 매체로 추가 작게 크게 ''보완수사권 폐지'' 입장 전달했다…디테일 나오면 얘기'' ''친청'' 이성윤 향해 "국민의힘에서 얘기하는 줄 알았다" [서울=뉴시스] 고범준 기자 = 김민석 전 국무총리가 6일 서울 여의도 국회 소통관에서 더불어민주당 당대표 출마 선언 기자회견을 하고 있다. 2026.07.06. [email protected] [서울=뉴시스] 한재혁 기자 = 김민석 전 국무총리는 7일 더불어민주당이 추진 중인 검사의 보완수사권 폐지와 관련 "현재로선 수사·기소 분리에 입각해 일단 폐지하는 쪽으로 정리해놓고 여러가지 보완책을 찾는 것이 큰 흐름으로 볼 때 검찰개혁의 과제를 풀어나가는 데 불가피성이 있다"고 했다. 김 전 총리는 이날 오전 KBS 라디오 ''전격시사''에 출연해 "(보완수사권 폐지 문제는) 대통령께서 공개적으로 여러 번, 우려가 없도록 여러 보완 장치나 고민을 하고 숙의가 필요하다고 하신 것"이라고 했다. 그는 "그런 것을 반영해서 저도 정부 내에서 충분한 숙의의 시간을 가졌던 것"이라며 "정부 내에서 토론회 등을 통해 다양한 (보완수사권 폐지와 관련된) 보완 아이디어가 나와 있다. 그런 부분을 포함해 국회에서 논의를 (하면 된다)"고 했다. 김 전 총리는 "원래는 (논의가) 다 끝난 다음에 정부가 (보완수사권 폐지) 동의 입장을 표현해야 하는 것을 선제적으로 표현한 것"이라며 "당에서 이러저러한 의원들의 안이 나와 있고, 준비되고 있는 것으로 알고 있어 그 과정에 그간 다양하게 제기된 보완적 의견은 참고 자료로 제공할 것"이라고 말했다. 김 전 총리는 자신이 지난 5월 당에 보완수사권 폐지 입장을 전달했다는 입장을 재차 밝혔다. 그는 "정청래 전 대표는 기억이 없다고 말씀하시고 한 두분의 최고위원은 ''우리도 모르는데 무슨 얘기냐''라고 말씀을 하는데, 그 분들은 모를 수 있다"며 "저도 최고위원을 했지만 최고위원은 직접적인 실무를 관할하는 라인에는 있지 않다"고 했다. 이어 "그렇지만 당내에서 검찰개혁과 관련해서 논의를 하는 중심적인 위치에 있는 분들을 통해서 최고 지도부까지 전달이 됐고 그것은 이미 다 근거가 있기 때문에 제가 없는 얘기를 할 필요도 없고 그 부분에 대해서도 앞으로 더 디테일이 나오면 충분히 얘기해 가면 된다고 본다"고 했다. 김 전 총리는 전날 친청(친정청래) 이성윤 최고위원이 자신을 향해 "계엄 해제 표결에 왜 참석하지 않았느냐" "김 전 총리가 감기약을 먹고 잤다는데 성분이 무엇이냐"고 물은 것을 두고는 "저는 ''국민의힘에서 얘기하는 것인가''라고 생각했다. 무슨 꼭 대장동 때를 보는 것 같다고 생각을 했다"고 했다. 이어 "일단 허위사실이다. 허위사실에 의한 명예훼손으로 이 시점에 그렇게 얘기를 하셔서 좀 걱정하고 있다"며 "''저런 식으로 정치를 하면 좀 어려워질텐데'' 이렇게 생각하고 있다"고 했다. 지지층 분열 양상에 대해선 "가령 친DJ, 친노, 친문, 친이재명이라고 해서 완전히 서로 다른 사람들이라고 보지 않지 않나. 결국은 같은 사람들"이라며 "다시 하나가 되도록 하는 것이 당 지도부의 임무이고 저는 상대적으로 가장 그것을 잘해낼 조건과 생각과 성향과 그런 마음을 가지고 있다"고 했다.', 'crawl', '뉴시스', '2026-07-07 09:44:09', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0021352260_web.jpg?rnd=20260706154640', '2026-07-07 06:04:27', '2026-07-07 16:09:18.531851', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3294, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698444', 'https://www.newsis.com/view/NISX20260707_0003698444', '정치', '선관위 "올림픽공원 투표용지 재검표 검토…국조특위 의결 거쳐야"', '[서울=뉴시스] 이창환 기자 = 중앙선거관리위원회는 7일 올림픽공원 핸드볼경기장 내 투표용지에 대한 재검표 추진을 검토하겠다고 ''6·3 지방선거 투표용지 부족 사태 등 국민참정권 침해 진상규명 및 선거관리 개혁을 위한 국정조사특별위원회''에 보고했다. 국조특위 여당 간사인 윤건영 더불어민주당 의원실에 따르면, 선관위는 이날 이 같은 내용이 담긴 2차 현장조사 현안보고 자료를 국조특위에 제출했다. 먼저 선관위는 올림픽공원 핸드볼경기장(송파구 개표소) 본연의 기능을 원상복구하고 국민적 불안감과 의혹을 해소하기 위해 투표지 등의 이송이 필요하다고 보고했다. 아울러 정당별 추천자 각 1명씩 참관하에 중앙선관위 과천청사로 투표지 등을 이송하고, 선거홍보관에 보관하는 방안을 보고했다. 선관위는 ''별도의 검증 등 사전조치 후 이송하는 방안 검토가 필요하다''는 입장을 전했는데, 현행 법규상 선관위 자체 직권 재검표에 대한 법적 근거가 없기 때문에 국조특위의 의결을 거쳐 투표지 등을 검증하는 형식으로 진행하는 방안을 검토할 필요가 있다고 했다. 국조특위 의결에 따라 투표지 등을 검증하는 경우, 선관위가 비용을 부담하겠다고 밝혔다. 선관위는 올림픽공원에 보관 중인 투표용지 247만표를 검증하는 경우, 440명 인력 투입 시 예산 5000만원과 9시간이 소요된다고 전망했다. 투표지 육안 재확인 및 정당·후보자별 분류·확인 후, 심사계수기로 매수를 확인해 검증 결과표를 작성하는 등 방식이다. 또 국조특위 위원과 정당·후보자 추천 참관인, 언론 등에도 과정을 공개하겠다고 부연했다. ◎공감언론 뉴시스 leech@newsis.com', '선관위 "올림픽공원 투표용지 재검표 검토…국조특위 의결 거쳐야" 등록 2026.07.07 09:19:25 수정 2026.07.07 09:47:35 구글에서 선호하는 매체로 추가 작게 크게 "선관위가 검증 비용 부담…이후 선관위로 투표지 등 이송" [과천=뉴시스] 이영환 기자 =지난달 26일 오후 경기 과천시 중앙선거관리위원회가 보이고 있다. 더불어민주당은 이날 6·3 지방선거 투표용지 부족 사태로 논란을 빚은 중앙선거관리위원회를 겨냥한 개혁안을 공개하고 헌법 개정을 통해 선관위를 해체하겠다고 밝혔다. 2026.06.26. [서울=뉴시스] 이창환 기자 = 중앙선거관리위원회는 7일 올림픽공원 핸드볼경기장 내 투표용지에 대한 재검표 추진을 검토하겠다고 ''6·3 지방선거 투표용지 부족 사태 등 국민참정권 침해 진상규명 및 선거관리 개혁을 위한 국정조사특별위원회''에 보고했다. 국조특위 여당 간사인 윤건영 더불어민주당 의원실에 따르면, 선관위는 이날 이 같은 내용이 담긴 2차 현장조사 현안보고 자료를 국조특위에 제출했다. 먼저 선관위는 올림픽공원 핸드볼경기장(송파구 개표소) 본연의 기능을 원상복구하고 국민적 불안감과 의혹을 해소하기 위해 투표지 등의 이송이 필요하다고 보고했다. 아울러 정당별 추천자 각 1명씩 참관하에 중앙선관위 과천청사로 투표지 등을 이송하고, 선거홍보관에 보관하는 방안을 보고했다. 선관위는 ''별도의 검증 등 사전조치 후 이송하는 방안 검토가 필요하다''는 입장을 전했는데, 현행 법규상 선관위 자체 직권 재검표에 대한 법적 근거가 없기 때문에 국조특위의 의결을 거쳐 투표지 등을 검증하는 형식으로 진행하는 방안을 검토할 필요가 있다고 했다. 국조특위 의결에 따라 투표지 등을 검증하는 경우, 선관위가 비용을 부담하겠다고 밝혔다. 선관위는 올림픽공원에 보관 중인 투표용지 247만표를 검증하는 경우, 440명 인력 투입 시 예산 5000만원과 9시간이 소요된다고 전망했다. 투표지 육안 재확인 및 정당·후보자별 분류·확인 후, 심사계수기로 매수를 확인해 검증 결과표를 작성하는 등 방식이다. 또 국조특위 위원과 정당·후보자 추천 참관인, 언론 등에도 과정을 공개하겠다고 부연했다.', 'crawl', '뉴시스', '2026-07-07 09:19:25', '중도', 'ready', 'https://img1.newsis.com/2026/06/26/NISI20260626_0021338124_web.jpg?rnd=20260626140546', '2026-07-07 06:04:27', '2026-07-07 16:09:46.260864', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3295, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698429', 'https://www.newsis.com/view/NISX20260707_0003698429', '정치', '이재명 대통령, 나토 정상회의 참석 출국…"평화와 안보 역할 넓힐 것" [뉴시스Pic]', '[서울=뉴시스]최동준 조재완 김경록 기자 = 이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 이 대통령은 오는 7~8일 나토 정상회의에 참석한 뒤 9~11일 몽골을 국빈 방문하는 닷새 간의 해외순방에 나선다. 이 대통령은 이날 오전 8시께 경기 성남 서울공항에서 김혜경 여사와 함께 2026년 나토 정상회의가 열리는 튀르키예 앙카라로 출국했다. 이 대통령은 남색 정장을, 김 여사는 흰색 투피스를 착용했다. 강훈식 대통령비서실장, 홍익표 정무수석, 한병도 더불어민주당 당대표 직무대행 겸 원내대표, 윤호중 행정안전부 장관, 김진아 외교부 제2차관, 살리 무랏 타메르 주한튀르키예 대사, 수헤 수흐볼드 주한몽골 대사 등이 이 대통령 부부를 환송했다. 비가 오는 관계로 이날 공항 출국행사는 이 대통령 취임 후 처음으로 서울공항 내부에서 진행됐다. 이 대통령은 웃으며 "어색하다"고 말한 뒤 참석자들과 인사를 나누고 대통령 전용기인 공군 1호기에 탑승했다. 이 대통령은 7일(현지시간) 나토에서 주관하는 방산포럼에 참석해 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언을 하고, 8일에는 주요 방산 수요국들과 연달아 양자회담을 하며 K-방산 세일즈에 나설 예정이다. 이 대통령은 출국 직전 X(옛 트위터)에 "오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계평화와 안보에 책임 있게 기여하는 나라가 됐다"며 "지난달 G7 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다"고 적었다. 그러면서 "국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다"고 밝혔다. ◎공감언론 뉴시스 photocdj@newsis.com, wander@newsis.com, knockrok@newsis.com', '이재명 대통령, 나토 정상회의 참석 출국…"평화와 안보 역할 넓힐 것" 등록 2026.07.07 09:17:03 [성남=뉴시스] 조성봉 기자 = 북대서양조약기구(NATO) 정상회의 참석 및 몽골을 국빈 방문하는 이재명 대통령과 김혜경 여사가 7일 경기 성남 서울공항에서 출국하며 인사하고 있다. 2026.07.07. [서울=뉴시스]최동준 조재완 김경록 기자 = 이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 이 대통령은 오는 7~8일 나토 정상회의에 참석한 뒤 9~11일 몽골을 국빈 방문하는 닷새 간의 해외순방에 나선다. 이 대통령은 이날 오전 8시께 경기 성남 서울공항에서 김혜경 여사와 함께 2026년 나토 정상회의가 열리는 튀르키예 앙카라로 출국했다. 이 대통령은 남색 정장을, 김 여사는 흰색 투피스를 착용했다. 강훈식 대통령비서실장, 홍익표 정무수석, 한병도 더불어민주당 당대표 직무대행 겸 원내대표, 윤호중 행정안전부 장관, 김진아 외교부 제2차관, 살리 무랏 타메르 주한튀르키예 대사, 수헤 수흐볼드 주한몽골 대사 등이 이 대통령 부부를 환송했다. 비가 오는 관계로 이날 공항 출국행사는 이 대통령 취임 후 처음으로 서울공항 내부에서 진행됐다. 이 대통령은 웃으며 "어색하다"고 말한 뒤 참석자들과 인사를 나누고 대통령 전용기인 공군 1호기에 탑승했다. 이 대통령은 7일(현지시간) 나토에서 주관하는 방산포럼에 참석해 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언을 하고, 8일에는 주요 방산 수요국들과 연달아 양자회담을 하며 K-방산 세일즈에 나설 예정이다. 이 대통령은 출국 직전 X(옛 트위터)에 "오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계평화와 안보에 책임 있게 기여하는 나라가 됐다"며 "지난달 G7 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다"고 적었다. 그러면서 "국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다"고 밝혔다.', 'crawl', '뉴시스', '2026-07-07 09:17:03', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0021352883_web.jpg?rnd=20260707091243', '2026-07-07 06:04:27', '2026-07-07 16:09:54.51808', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3296, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260707_0003698315', 'https://www.newsis.com/view/NISX20260707_0003698315', '정치', '이 대통령, 튀르키예로 출국…닷새 간 나토·몽골 순방', '[서울=뉴시스]김경록 조재완 기자 = 이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 이 대통령은 오는 7~8일 나토 정상회의에 참석한 뒤 9~11일 몽골을 국빈 방문하는 닷새 간의 해외순방에 나선다. 이 대통령은 이날 오전 8시께 경기 성남 서울공항에서 김혜경 여사와 함께 2026년 나토 정상회의가 열리는 튀르키예 앙카라로 출국했다. 이 대통령은 남색 정장을, 김 여사는 흰색 투피스를 착용했다. 강훈식 대통령비서실장, 홍익표 정무수석, 한병도 더불어민주당 당대표 직무대행 겸 원내대표, 윤호중 행정안전부 장관, 김진아 외교부 제2차관, 살리 무랏 타메르 주한튀르키예 대사, 수헤 수흐볼드 주한몽골 대사 등이 이 대통령 부부를 환송했다. 비가 오는 관계로 이날 공항 출국행사는 이 대통령 취임 후 처음으로 서울공항 내부에서 진행됐다. 이 대통령은 웃으며 "어색하다"고 말한 뒤 참석자들과 인사를 나누고 대통령 전용기인 공군 1호기에 탑승했다. 이 대통령은 7일(현지시간) 나토에서 주관하는 방산포럼에 참석해 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언을 하고, 8일에는 주요 방산 수요국들과 연달아 양자회담을 하며 K-방산 세일즈에 나설 예정이다. 이 대통령은 출국 직전 X(옛 트위터)에 "오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계평화와 안보에 책임 있게 기여하는 나라가 됐다"며 "지난달 G7 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다"고 적었다. 그러면서 "국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다"고 밝혔다. ◎공감언론 뉴시스 knockrok@newsis.com, wander@newsis.com', '이 대통령, 튀르키예로 출국…닷새 간 나토·몽골 순방 등록 2026.07.07 08:40:56 7~8일 나토 정상회의 참석, 9~11일 몽골 국빈방문 李 "G7 이어 나토에서 세계 평화·안보 위한 韓 역할 넓힐 것" 이재명 대통령과 김혜경 여사가 7일 경기 성남 서울공항에서 출국하며 인사하고 있다. 이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 이 대통령은 오는 7~8일 나토 정상회의에 참석한 뒤 9~11일 몽골을 국빈 방문하는 닷새 간의 해외순방에 나선다. 이 대통령은 이날 오전 8시께 경기 성남 서울공항에서 김혜경 여사와 함께 2026년 나토 정상회의가 열리는 튀르키예 앙카라로 출국했다. 이 대통령은 남색 정장을, 김 여사는 흰색 투피스를 착용했다. 강훈식 대통령비서실장, 홍익표 정무수석, 한병도 더불어민주당 당대표 직무대행 겸 원내대표, 윤호중 행정안전부 장관, 김진아 외교부 제2차관, 살리 무랏 타메르 주한튀르키예 대사, 수헤 수흐볼드 주한몽골 대사 등이 이 대통령 부부를 환송했다. 비가 오는 관계로 이날 공항 출국행사는 이 대통령 취임 후 처음으로 서울공항 내부에서 진행됐다. 이 대통령은 웃으며 "어색하다"고 말한 뒤 참석자들과 인사를 나누고 대통령 전용기인 공군 1호기에 탑승했다. 이 대통령은 7일(현지시간) 나토에서 주관하는 방산포럼에 참석해 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언을 하고, 8일에는 주요 방산 수요국들과 연달아 양자회담을 하며 K-방산 세일즈에 나설 예정이다. 이 대통령은 출국 직전 X(옛 트위터)에 "오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계평화와 안보에 책임 있게 기여하는 나라가 됐다"며 "지난달 G7 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다"고 적었다. 그러면서 "국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다"고 밝혔다.', 'crawl', '뉴시스', '2026-07-07 08:40:56', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0021352865_web.jpg?rnd=20260707083710', '2026-07-07 06:04:27', '2026-07-07 16:10:02.257643', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3305, 'https://www.newsis.com/RSS/politics.xml', 'https://www.newsis.com/view/NISX20260706_0003697928', 'https://www.newsis.com/view/NISX20260706_0003697928', '정치', '이 대통령, 오늘부터 닷새간 나토·몽골 순방…방산·공급망 협력 강화', '[서울=뉴시스]김경록 기자 = 이재명 대통령이 7일부터 11일까지 북대서양조약기구(NATO·나토) 정상회의 참석 및 몽골 국빈방문을 위한 4박 5일 간의 해외 순방에 나선다. 이 대통령은 이날 오전 출국해 오는 7~8일(이하 현지시간) 튀르키예 앙카라에서 개최되는 2026년 나토 정상회의에 참석한다. 한국은 나토 회원국은 아니지만 나토가 최근 협력을 강화하고 있는 인도태평양 핵심 파트너국 IP4(한국·일본·호주·뉴질랜드) 일원으로 초청됐다. 이 대통령은 취임 후 첫 참석인 이번 나토 정상회의에서 방위산업 협력에 힘을 실을 전망이다. 우선 이 대통령은 오는 7일 튀르키예 앙카라에 도착해 마크 루터 나토 사무총장을 면담한 뒤 일본·호주·뉴질랜드 대표들과 소인수 회담을 갖는다. 이어 이 대통령은 나토에서 주관하는 방산포럼에 참석해 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언을 하고 토론에도 참석할 예정이다. 이튿날인 8일에는 주요 방산 수요국들과 양자회담을 연달아 갖고 K-방산 세일즈에 나설 계획이다. 청와대는 복수의 국가들과 연쇄 양자회담 일정을 조율 중인 것으로 전해졌다. 이후 이 대통령은 앙카라를 떠나 오는 9일 몽골 울란바타르에 도착, 11일까지 국빈 방문 일정을 갖는다. 이 대통령은 후렐수흐 몽골 대통령과의 정상회담을 계기로 ''한몽관계의 황금시대'' 공동선언을 발표할 예정이다. 핵심광물 등 자원 부국이자 북한의 2번째 수교국인 몽골과 구체적인 경제 협력 및 한반도 평화 협력을 위한 방안도 논의될 전망이다. 이 대통령은 11일 몽골 최대 명절인 ''나담축제'' 개막식에 주빈으로 참석하는 것을 마지막으로 이번 순방 일정을 마무리할 예정이다. ◎공감언론 뉴시스 knockrok@newsis.com', '이 대통령, 오늘부터 닷새간 나토·몽골 순방…방산·공급망 협력 강화 등록 2026.07.07 05:00:00 7~8일 나토 정상회의 참석, 9~11일 몽골 국빈 방문 李, 나토 방산포럼서 연설…K-방산 수요국들과 정상회담 ''한-몽 황금시대'' 공동선언…핵심광물·한반도 평화 협력 논의 이재명 대통령이 7일부터 11일까지 북대서양조약기구(NATO·나토) 정상회의 참석 및 몽골 국빈방문을 위한 4박 5일 간의 해외 순방에 나선다. 이 대통령은 이날 오전 출국해 오는 7~8일(이하 현지시간) 튀르키예 앙카라에서 개최되는 2026년 나토 정상회의에 참석한다. 한국은 나토 회원국은 아니지만 나토가 최근 협력을 강화하고 있는 인도태평양 핵심 파트너국 IP4(한국·일본·호주·뉴질랜드) 일원으로 초청됐다. 이 대통령은 취임 후 첫 참석인 이번 나토 정상회의에서 방위산업 협력에 힘을 실을 전망이다. 우선 이 대통령은 오는 7일 튀르키예 앙카라에 도착해 마크 루터 나토 사무총장을 면담한 뒤 일본·호주·뉴질랜드 대표들과 소인수 회담을 갖는다. 이어 이 대통령은 나토에서 주관하는 방산포럼에 참석해 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언을 하고 토론에도 참석할 예정이다. 이튿날인 8일에는 주요 방산 수요국들과 양자회담을 연달아 갖고 K-방산 세일즈에 나설 계획이다. 청와대는 복수의 국가들과 연쇄 양자회담 일정을 조율 중인 것으로 전해졌다. 이후 이 대통령은 앙카라를 떠나 오는 9일 몽골 울란바타르에 도착, 11일까지 국빈 방문 일정을 갖는다. 이 대통령은 후렐수흐 몽골 대통령과의 정상회담을 계기로 ''한몽관계의 황금시대'' 공동선언을 발표할 예정이다. 핵심광물 등 자원 부국이자 북한의 2번째 수교국인 몽골과 구체적인 경제 협력 및 한반도 평화 협력을 위한 방안도 논의될 전망이다. 이 대통령은 11일 몽골 최대 명절인 ''나담축제'' 개막식에 주빈으로 참석하는 것을 마지막으로 이번 순방 일정을 마무리할 예정이다.', 'crawl', '뉴시스', '2026-07-07 05:00:00', '중도', 'ready', 'https://img1.newsis.com/2026/06/17/NISI20260617_0021324798_web.jpg?rnd=20260618000000', '2026-07-07 06:04:27', '2026-07-07 16:12:01.643455', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3333, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698887', 'https://www.newsis.com/view/NISX20260707_0003698887', '국제', '하메네이 장례식서 복수 외침…트럼프 사진에 돌 던지기도', '[서울=뉴시스] 이재은 기자 = 이란 정권이 주관한 알리 하메네이 최고 지도자의 장례식에서 조문객들이 도널드 트럼프 미국 대통령의 사진을 향해 돌을 던지는 상징적 의식을 거행하는 모습이 공개됐다. 6일(현지 시간) CNN에 따르면 장례식장에서는 "미국에 죽음을", "트럼프를 죽여라" 등의 구호가 이어지며 하메네이 사망에 대한 복수를 촉구하는 분위기가 고조됐다. 이란 국영통신이 공개한 영상에 따르면 조문객들은 트럼프 대통령의 사진을 향해 돌멩이를 던지는 이른바 ''악마에게 돌 던지기'' 의식에 참여했다. 이는 이슬람 성지순례(하즈)에서 순례자들이 악마를 상징하는 기둥에 작은 돌을 던지며 악을 거부하는 의미를 담은 전통 의식을 차용한 것으로, 장례식에서는 트럼프 대통령을 상징적인 ''악마''로 규정하는 연출이 이뤄졌다. 테헤란 도심에는 검은 옷을 입은 수십만 명의 조문객이 모여 장례 행렬을 지켜봤다. 많은 참석자는 이슬람 공화국 국기와 하메네이의 사진을 들었으며, 가족 단위 조문객들도 눈에 띄었다. 일부 참가자는 "트럼프를 죽여라"라는 문구와 함께 "암살 현상금. 생사 불문. 2천만 달러"라고 적힌 플래카드를 들고 시위에 나서기도 했다. 조문객들에게는 하메네이 사망의 책임자로 트럼프 대통령과 그의 강경파 참모들을 지목한 유인물이 배포된 것으로 전해졌다. 현장에서는 "미국에 죽음을", "이스라엘에 죽음을"이라는 반미·반이스라엘 구호가 끊이지 않았다. 1979년 이슬람 혁명 이후 국가 주도 집회에서 반복돼 온 반미 구호와 국기 소각 시위도 다시 등장했다. 30세 조문객 자흐라 발라에이는 "우리는 지도자의 피에 대한 복수를 할 것이다. 지도자의 피가 짓밟히는 것을 용납하지 않을 것"이라고 말했다. 이날은 6일간 이어지는 장례 일정의 셋째 날로, 이란 국기가 덮인 관을 실은 차량들이 테헤란 시내를 행진했다. 하메네이와 오랜 기간 불편한 관계를 유지했던 강경파 마흐무드 아흐마디네자드 전 대통령도 장례식에 참석해 눈길을 끌었다. 반면 지난 3월 최고 지도자에 오른 모즈타바 하메네이는 장례 기간 내내 공개 석상에 모습을 드러내지 않아 건강이상설 의이 더욱 커지고 있다. 모즈타바는 미국과 이스라엘의 대이란 공습으로 얼굴이 크게 손상됐고, 다리는 심각한 상처를 입은 것으로 알려졌다. ◎공감언론 뉴시스 lje@newsis.com', '하메네이 장례식서 복수 외침…트럼프 사진에 돌 던지기도 등록 2026.07.07 14:04:54 수정 2026.07.07 15:58:24 구글에서 선호하는 매체로 추가 작게 크게 트럼프 사진 향해 ''악마에게 돌 던지기'' 의식 "트럼프를 죽여라", "미국에 죽음을" 외쳐 [테헤란=AP/뉴시스] 미국과 이스라엘의 표적 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식에서 도널드 트럼프 미국 대통령을 겨냥한 ''돌팔매'' 퍼포먼스가 벌어지는 등 반미 시위가 이어졌다. 5일(현지 시간) 테헤란 도심에서 한 남성이 "트럼프를 죽여라"는 문구가 적힌 팻말을 들고 있는 모습. 2026.07.07 [서울=뉴시스] 이재은 기자 = 이란 정권이 주관한 알리 하메네이 최고 지도자의 장례식에서 조문객들이 도널드 트럼프 미국 대통령의 사진을 향해 돌을 던지는 상징적 의식을 거행하는 모습이 공개됐다. 6일(현지 시간) CNN에 따르면 장례식장에서는 "미국에 죽음을", "트럼프를 죽여라" 등의 구호가 이어지며 하메네이 사망에 대한 복수를 촉구하는 분위기가 고조됐다. 이란 국영통신이 공개한 영상에 따르면 조문객들은 트럼프 대통령의 사진을 향해 돌멩이를 던지는 이른바 ''악마에게 돌 던지기'' 의식에 참여했다. 이는 이슬람 성지순례(하즈)에서 순례자들이 악마를 상징하는 기둥에 작은 돌을 던지며 악을 거부하는 의미를 담은 전통 의식을 차용한 것으로, 장례식에서는 트럼프 대통령을 상징적인 ''악마''로 규정하는 연출이 이뤄졌다. 테헤란 도심에는 검은 옷을 입은 수십만 명의 조문객이 모여 장례 행렬을 지켜봤다. 많은 참석자는 이슬람 공화국 국기와 하메네이의 사진을 들었으며, 가족 단위 조문객들도 눈에 띄었다. 일부 참가자는 "트럼프를 죽여라"라는 문구와 함께 "암살 현상금. 생사 불문. 2천만 달러"라고 적힌 플래카드를 들고 시위에 나서기도 했다. 조문객들에게는 하메네이 사망의 책임자로 트럼프 대통령과 그의 강경파 참모들을 지목한 유인물이 배포된 것으로 전해졌다. [테헤란=AP/뉴시스] 6일(현지 시간) 이란 테헤란 이슬람혁명광장에서 추모객들이 아야톨라 알리 하메네이 이란 전 최고지도자 장례 행렬을 따르고 있다. 2026.07.06. 현장에서는 "미국에 죽음을", "이스라엘에 죽음을"이라는 반미·반이스라엘 구호가 끊이지 않았다. 1979년 이슬람 혁명 이후 국가 주도 집회에서 반복돼 온 반미 구호와 국기 소각 시위도 다시 등장했다. 30세 조문객 자흐라 발라에이는 "우리는 지도자의 피에 대한 복수를 할 것이다. 지도자의 피가 짓밟히는 것을 용납하지 않을 것"이라고 말했다. 이날은 6일간 이어지는 장례 일정의 셋째 날로, 이란 국기가 덮인 관을 실은 차량들이 테헤란 시내를 행진했다. 하메네이와 오랜 기간 불편한 관계를 유지했던 강경파 마흐무드 아흐마디네자드 전 대통령도 장례식에 참석해 눈길을 끌었다. 반면 지난 3월 최고 지도자에 오른 모즈타바 하메네이는 장례 기간 내내 공개 석상에 모습을 드러내지 않아 건강이상설 의이 더욱 커지고 있다. 모즈타바는 미국과 이스라엘의 대이란 공습으로 얼굴이 크게 손상됐고, 다리는 심각한 상처를 입은 것으로 알려졌다.', 'crawl', '뉴시스', '2026-07-07 14:04:54', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0001410416_web.jpg?rnd=20260706230939', '2026-07-07 06:04:28', '2026-07-07 16:16:49.634399', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3338, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698862', 'https://www.newsis.com/view/NISX20260707_0003698862', '국제', 'SK하이닉스, 나스닥 상장에 큰손 몰린다…오픈AI 출신 펀드도 ''베팅''', '[서울=뉴시스]박미선 기자 = SK하이닉스의 280억 달러(약 42조6700억원) 규모 나스닥 상장에 전직 오픈AI 연구원이 설립한 헤지펀드와 영국 투자사 베일리 기포드가 대규모 투자 의사를 밝혔다. 6일(현지 시간) 파이낸셜타임스(FT)에 따르면 SK하이닉스는 이번 주 나스닥 기업공개(IPO) 절차를 공식 개시했다. AI 데이터센터 건설 붐으로 메모리 반도체 수요가 급증하면서 이번 상장은 아시아 기업의 뉴욕 증시 상장 가운데 역대 최대 규모 중 하나가 될 전망이다. AI 수요에 힘입어 SK하이닉스의 지난해 매출은 전년 대비 47% 증가한 97조1000억원, 영업이익은 두 배 이상 늘어난 42조9000억원을 기록했다. 올해 1분기 매출도 전년 동기 대비 약 3배 증가한 52조6000억원으로 집계됐다. 이 같은 실적에 힘입어 SK하이닉스 주가는 지난 1년간 코스피에서 750% 이상 상승했고, 시가총액은 1663조원 수준으로 불어났다. 오픈AI 출신 연구원 레오폴드 아셴브레너가 설립한 헤지펀드 시추에이셔널 어웨어니스와 베일리 기포드, 코튜는 SK하이닉스가 발행하는 미국주식예탁증서(ADS) 가운데 최대 70억 달러어치(약 10조6600억원)를 인수할 의향을 내비쳤다. 시추에이셔널 어웨어니스 AI 관련 종목에 대한 선제적 투자로 개인 투자자들 사이에서 큰 관심을 받아왔다. SK하이닉스는 이번 상장을 통해 조달한 280억 달러를 생산능력 확대에 투입할 계획이다. 자금 대부분은 국내 반도체 공장(팹) 신설에 쓰이며, 일부는 네덜란드 ASML이 만드는 최첨단 노광장비 EUV 스캐너 구매에도 사용된다. 앞서 지난주 SK하이닉스와 삼성전자는 국내 생산능력을 대폭 늘리기 위해 6000억 달러(약 914조원) 규모의 투자 계획을 발표했다. AI 데이터센터용 고대역폭메모리(HBM) 수요 급증으로 촉발된 메모리 반도체 공급 부족은 SK하이닉스, 삼성전자, 마이크론 등 3대 메모리 업체의 주가를 끌어올렸고, 이들 기업은 모두 시가총액 1조 달러를 넘어섰다. SK하이닉스는 전체 발행주식의 약 2.5%에 해당하는 신주 1779만 주를 ADS 형태로 나스닥에 상장할 계획이다. 이번 공모 규모는 최대주주인 SK스퀘어의 지분율이 20% 이상 유지되도록 설계됐다. ADS 공모가는 7월 3일 기준 코스피 종가를 반영해 주당 약 158달러(약 24만원) 수준에서 결정될 예정이며, 뱅크오브아메리카·JP모건·골드만삭스·씨티그룹이 대표 주관사를 맡는다. 미국 시장에서는 10일부터 거래가 시작될 예정이다. ◎공감언론 뉴시스 only@newsis.com', 'SK하이닉스의 280억 달러(44조4570억원) 규모 나스닥 상장에 전직 오픈AI 연구원이 설립한 헤지펀드와 영국 투자사 베일리 기포드가 대규모 투자 의사를 밝혔다. 6일(현지 시간) 파이낸셜타임스(FT)에 따르면 SK하이닉스는 이번 주 나스닥 기업공개(IPO) 절차를 공식 개시했다. AI 데이터센터 건설 붐으로 메모리 반도체 수요가 급증하면서 이번 상장은 아시아 기업의 뉴욕 증시 상장 가운데 역대 최대 규모 중 하나가 될 전망이다. AI 수요에 힘입어 SK하이닉스의 지난해 매출은 전년 대비 47% 증가한 97조1000억원, 영업이익은 두 배 이상 늘어난 42조9000억원을 기록했다. 올해 1분기 매출도 전년 동기 대비 약 3배 증가한 52조6000억원으로 집계됐다. 이 같은 실적에 힘입어 SK하이닉스 주가는 지난 1년간 코스피에서 750% 이상 상승했고, 시가총액은 1663조원 수준으로 불어났다. 오픈AI 출신 연구원 레오폴드 아셴브레너가 설립한 헤지펀드 시추에이셔널 어웨어니스와 베일리 기포드, 코튜는 SK하이닉스가 발행하는 미국주식예탁증서(ADS) 가운데 최대 70억 달러어치(약 10조6600억원)를 인수할 의향을 내비쳤다. 시추에이셔널 어웨어니스 AI 관련 종목에 대한 선제적 투자로 개인 투자자들 사이에서 큰 관심을 받아왔다. SK하이닉스는 이번 상장을 통해 조달한 280억 달러를 생산능력 확대에 투입할 계획이다. 자금 대부분은 국내 반도체 공장(팹) 신설에 쓰이며, 일부는 네덜란드 ASML이 만드는 최첨단 노광장비 EUV 스캐너 구매에도 사용된다. 앞서 지난주 SK하이닉스와 삼성전자는 국내 생산능력을 대폭 늘리기 위해 6000억 달러(약 914조원) 규모의 투자 계획을 발표했다. AI 데이터센터용 고대역폭메모리(HBM) 수요 급증으로 촉발된 메모리 반도체 공급 부족은 SK하이닉스, 삼성전자, 마이크론 등 3대 메모리 업체의 주가를 끌어올렸고, 이들 기업은 모두 시가총액 1조 달러를 넘어섰다. SK하이닉스는 전체 발행주식의 약 2.5%에 해당하는 신주 1779만 주를 ADS 형태로 나스닥에 상장할 계획이다. 이번 공모 규모는 최대주주인 SK스퀘어의 지분율이 20% 이상 유지되도록 설계됐다. ADS 공모가는 7월 3일 기준 코스피 종가를 반영해 주당 약 158달러(약 24만원) 수준에서 결정될 예정이며, 뱅크오브아메리카·JP모건·골드만삭스·씨티그룹이 대표 주관사를 맡는다. 미국 시장에서는 10일부터 거래가 시작될 예정이다.', 'crawl', '뉴시스', '2026-07-07 12:35:27', '중도', 'ready', 'https://img1.newsis.com/2026/06/24/NISI20260624_0002169158_web.jpg?rnd=20260624152933', '2026-07-07 06:04:28', '2026-07-07 16:17:37.151282', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3362, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698601', 'https://www.newsis.com/view/NISX20260707_0003698601', '국제', '뤼터 나토 총장 “中 군사력 증강에 순진하게 대응해선 안 돼”', '[서울=뉴시스] 구자룡 기자 = 마크 뤼터 북대서양조약기구(NATO) 사무총장은 6일 중국의 군사력 증강에 대해 ‘순진하게(naive)’ 대처할 수 없다고 말했다고 홍콩 사우스차이나모닝포스트(SCMP)가 7일 보도했다. 뤼터 총장은 튀르키예 앙카라에서 열리는 나토 정상회담을 하루 앞두고 중국의 첫 태평양 핵전략잠수함 잠수함발사탄도미사일(SLBM) 시험발사에 대한 질문을 받고 이같이 대답했다. 뤼터 총장은 “나토가 중국에 대해 순진해서는 안된다”며 “고이즈미 신지로 일본 방위상과 이미 문자 메시지를 통해 이 문제를 논의했다”고 말했다. 그는 “인도태평양 지역에서 일어나는 일은 대서양 지역에서 일어나는 일과 관련이 있다”며 “이것이 바로 우리가 긴밀히 협력하는 이유”라고 강조했다. 뤼터 총장은 “우크라이나 전쟁에서도 중국, 북한, 이란은 러시아가 우크라이나를 상대로 아무런 이유 없이 침략 전쟁을 벌이는 데 핵심적인 역할을 했다”며 “이는 우리가 결코 순진하게 생각해서는 안된다는 것을 다시 한번 보여주는 증거”라고 말했다. 중국은 6일 낮 태평양 공해 해역으로 훈련용 모의 탄두를 탑재한 SLBM을 발사했다. 이는 1982년 이후 첫 SLBM이자 핵잠에서 발사하기는 이번이 처음이다. 한편 뤼터 총장은 이번 정상회담과 관련 나토 회원국들이 국방비 지출을 늘려 우크라이나 안보에 대한 책임과 국방비 분담 부담을 보다 균형 있게 분담함으로써 우크라이나가 필요한 것을 얻도록 보장해야 한다고 주장했다. 그는 이번 나토 정상회담에 인도태평양 4개국(IP4) 파트너 국가 중 호주, 일본, 뉴질랜드 정상들이 불참한 것에 대해 “매우 긴밀한 협력 관계를 이유로 우려하지 않는다”고 의견을 나타냈다. 지난해 헤이그 정상회담과 마찬가지로 올해 IP4 국가 정상 대부분이 불참하는 가운데 이재명 대통령은 참석한다. ◎공감언론 뉴시스 kjdragon@newsis.com', '뤼터 나토 총장 “中 군사력 증강에 순진하게 대응해선 안 돼” 등록 2026.07.07 10:28:04 수정 2026.07.07 11:24:24 구글에서 선호하는 매체로 추가 작게 크게 中 첫 핵잠 SLBM 발사 후 나토와 인도태평양 안보 상호 연관 강조 “고이즈미 日 방위상과 문자 메시지 통해 문제 논의” 북대서양조약기구(NATO·나토)가 방위산업 역량 강화를 위해 수백억 달러 규모의 신규 계약을 체결한다. 마크 뤼터 나토 사무총장이 6일 튀르키예 앙카라에서 열리는 나토 정상회의를 앞두고 국제미디어센터에서 기자회견을 하고 있다. 2026.07.07. 마크 뤼터 북대서양조약기구(NATO) 사무총장은 6일 중국의 군사력 증강에 대해 ‘순진하게(naive)’ 대처할 수 없다고 말했다고 홍콩 사우스차이나모닝포스트(SCMP)가 7일 보도했다. 뤼터 총장은 튀르키예 앙카라에서 열리는 나토 정상회담을 하루 앞두고 중국의 첫 태평양 핵전략잠수함 잠수함발사탄도미사일(SLBM) 시험발사에 대한 질문을 받고 이같이 대답했다. 뤼터 총장은 “나토가 중국에 대해 순진해서는 안된다”며 “고이즈미 신지로 일본 방위상과 이미 문자 메시지를 통해 이 문제를 논의했다”고 말했다. 그는 “인도태평양 지역에서 일어나는 일은 대서양 지역에서 일어나는 일과 관련이 있다”며 “이것이 바로 우리가 긴밀히 협력하는 이유”라고 강조했다. 뤼터 총장은 “우크라이나 전쟁에서도 중국, 북한, 이란은 러시아가 우크라이나를 상대로 아무런 이유 없이 침략 전쟁을 벌이는 데 핵심적인 역할을 했다”며 “이는 우리가 결코 순진하게 생각해서는 안된다는 것을 다시 한번 보여주는 증거”라고 말했다. 중국은 6일 낮 태평양 공해 해역으로 훈련용 모의 탄두를 탑재한 SLBM을 발사했다. 이는 1982년 이후 첫 SLBM이자 핵잠에서 발사하기는 이번이 처음이다. 한편 뤼터 총장은 이번 정상회담과 관련 나토 회원국들이 국방비 지출을 늘려 우크라이나 안보에 대한 책임과 국방비 분담 부담을 보다 균형 있게 분담함으로써 우크라이나가 필요한 것을 얻도록 보장해야 한다고 주장했다. 그는 이번 나토 정상회담에 인도태평양 4개국(IP4) 파트너 국가 중 호주, 일본, 뉴질랜드 정상들이 불참한 것에 대해 “매우 긴밀한 협력 관계를 이유로 우려하지 않는다”고 의견을 나타냈다. 지난해 헤이그 정상회담과 마찬가지로 올해 IP4 국가 정상 대부분이 불참하는 가운데 이재명 대통령은 참석한다.', 'crawl', '뉴시스', '2026-07-07 10:28:04', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0002179449_web.jpg?rnd=20260707001505', '2026-07-07 06:04:29', '2026-07-07 16:22:30.012434', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3386, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698130', 'https://www.newsis.com/view/NISX20260707_0003698130', '국제', '베네수엘라 지진 사망자 3535명, 부상자는 16740명으로 증가', '[서울=뉴시스] 차미례 기자 = 베네수엘라에서 6월 24일 발생한 연쇄 대지진의 사망자 수가 3535명, 부상자는 1만 6740명으로 늘어났다고 호르헤 로드리게스 국회의장이 6일(현지시간) 텔레그램을 통해 수정 발표했다. 지진으로 집을 잃은 난민의 수도 1만7854명으로 증가했다고 로드리게스 의장은 밝혔다. 그는 임시 수용소 등 거처를 마련하기 위한 지휘본부의 본부장도 겸임하고 있다. 로드리게스는 지금까지 구조된 사람의 수는 6462명에 머물러 있고 구호와 지원을 받은 가족들의 수는 8만6794 가구에 달한다고 발표했다. 한편 지난 6월 24일 발생한 규모 7.2와 7.5의 쌍둥이 강진 이후로 베네수엘라 국내에서 기록된 여진의 수는 995건에 달한다고 정부의 최신 통계는 밝혔다. 생존자 구조는 더 이상 이뤄지지 않고 외국에서 지원을 나온 많은 구조대도 이제는 구조 작업을 포기, 대부분 귀국했거나 귀국을 준비하고 있다. ◎공감언론 뉴시스 cmr@newsis.com', '베네수엘라 지진 사망자 3535명, 부상자는 16740명으로 증가 등록 2026.07.07 06:48:22 수정 2026.07.07 15:59:02 로드리게스 국회의장 6일 발표… 집잃은 난민도 17854명 구조된 사람은 6462명에 머물러.. 8만6794 가구에 구호품 베네수엘라 카라카스의 한 공원에서 지진으로 집을 잃은 이재민들이 7월1일 구호 의류를 받고 있다. 지난 24일 발생한 강진으로 인한 사망자 숫자는 3535명으로 부상자는 1만 6740명으로 늘었다고 로드리게스 국회의장이 6일 발표했다. 2026.07.07. 베네수엘라에서 6월 24일 발생한 연쇄 대지진의 사망자 수가 3535명, 부상자는 1만 6740명으로 늘어났다고 호르헤 로드리게스 국회의장이 6일(현지시간) 텔레그램을 통해 수정 발표했다. 지진으로 집을 잃은 난민의 수도 1만7854명으로 증가했다고 로드리게스 의장은 밝혔다. 그는 임시 수용소 등 거처를 마련하기 위한 지휘본부의 본부장도 겸임하고 있다. 로드리게스는 지금까지 구조된 사람의 수는 6462명에 머물러 있고 구호와 지원을 받은 가족들의 수는 8만6794 가구에 달한다고 발표했다. 한편 지난 6월 24일 발생한 규모 7.2와 7.5의 쌍둥이 강진 이후로 베네수엘라 국내에서 기록된 여진의 수는 995건에 달한다고 정부의 최신 통계는 밝혔다. 생존자 구조는 더 이상 이뤄지지 않고 외국에서 지원을 나온 많은 구조대도 이제는 구조 작업을 포기, 대부분 귀국했거나 귀국을 준비하고 있다.', 'crawl', '뉴시스', '2026-07-07 06:48:22', '중도', 'ready', 'https://img1.newsis.com/2026/07/02/NISI20260702_0001394887_web.jpg?rnd=20260702094544', '2026-07-07 06:04:29', '2026-07-07 16:28:20.853797', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3390, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698109', 'https://www.newsis.com/view/NISX20260707_0003698109', '국제', '이란 의회의장 "하메네이 살해범들 대가 치를 것"', '[서울=뉴시스] 문예성 기자 = 미국과의 협상을 이끄는 모하마드 바게르 갈리바프 이란 의회 의장이 알리 하메네이 전 최고지도자 살해에 책임이 있는 이들은 반드시 대가를 치르게 될 것이라고 경고했다. 6일(현지시간) 이란인터내셔널 등에 따르면 갈리바프 의장은 하메네이의 테헤란 장례 행진을 맞아 발표한 메시지에서 이란 국민들이 지난 4개월간 "미국에 죽음을", "이스라엘에 죽음을"이라는 구호를 외치며 "순교한 이맘의 살해범들"에 대한 복수를 요구해 왔다고 밝혔다. 그는 "이슬람 이란을 침략한 자들과 이 땅의 순교자들을 살해한 자들, 특히 움마(무슬림 공동체)의 지도자를 살해한 자들은 그들의 행동에 대한 대가를 치르게 될 것"이라고 경고했다. 갈리바프 의장은 또 "복수의 최종 단계는 예루살렘 해방을 통해 실현될 것"이라고 강조했다. 이어 군사적 수단과 외교적 수단을 모두 활용해 투쟁을 이어가겠다는 입장을 재확인했다. 그는 미국과의 협상 역시 이란이 서방 강대국들과 벌이는 더 큰 차원의 ''문명적 대결''의 일부라고 주장했다. 하메네이와 그의 딸, 사위, 며느리, 외손녀는 지난 2월28일 미국과 이스라엘의 공습으로 사망했다. 한편 하메네이의 시신은 이날 장례 절차를 이어가기 위해 이란의 종교도시 곰에 도착했다. 곰에서는 7일 시아파 고위 성직자들이 참석한 가운데 장례 예배가 거행될 예정이다. 이어 8일에는 시신을 이라크 시아파 성지인 카르발라와 나자프로 운구해 장례식을 치른 뒤, 9일에는 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장할 예정이다. ◎공감언론 뉴시스 sophis731@newsis.com', '이란 의회의장 "하메네이 살해범들 대가 치를 것" 등록 2026.07.07 06:00:57 구글에서 선호하는 매체로 추가 작게 크게 갈리바프 "최종 복수는 예루살렘 해방" 군사·외교 병행 투쟁 의지 재확인 [이슬라마바드=신화/뉴시스] ﻿﻿미국과의 협상을 이끄는 모하마드 바게르 갈리바프 이란 의회 의장(가운데)이 알리 하메네이 전 최고지도자 살해에 책임이 있는 이들은 반드시 대가를 치르게 될 것이라고 경고했다. 2026.07.07 [서울=뉴시스] 문예성 기자 = 미국과의 협상을 이끄는 모하마드 바게르 갈리바프 이란 의회 의장이 알리 하메네이 전 최고지도자 살해에 책임이 있는 이들은 반드시 대가를 치르게 될 것이라고 경고했다. 6일(현지시간) 이란인터내셔널 등에 따르면 갈리바프 의장은 하메네이의 테헤란 장례 행진을 맞아 발표한 메시지에서 이란 국민들이 지난 4개월간 "미국에 죽음을", "이스라엘에 죽음을"이라는 구호를 외치며 "순교한 이맘의 살해범들"에 대한 복수를 요구해 왔다고 밝혔다. 그는 "이슬람 이란을 침략한 자들과 이 땅의 순교자들을 살해한 자들, 특히 움마(무슬림 공동체)의 지도자를 살해한 자들은 그들의 행동에 대한 대가를 치르게 될 것"이라고 경고했다. 갈리바프 의장은 또 "복수의 최종 단계는 예루살렘 해방을 통해 실현될 것"이라고 강조했다. 이어 군사적 수단과 외교적 수단을 모두 활용해 투쟁을 이어가겠다는 입장을 재확인했다. 그는 미국과의 협상 역시 이란이 서방 강대국들과 벌이는 더 큰 차원의 ''문명적 대결''의 일부라고 주장했다. 하메네이와 그의 딸, 사위, 며느리, 외손녀는 지난 2월28일 미국과 이스라엘의 공습으로 사망했다. 한편 하메네이의 시신은 이날 장례 절차를 이어가기 위해 이란의 종교도시 곰에 도착했다. 곰에서는 7일 시아파 고위 성직자들이 참석한 가운데 장례 예배가 거행될 예정이다. 이어 8일에는 시신을 이라크 시아파 성지인 카르발라와 나자프로 운구해 장례식을 치른 뒤, 9일에는 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장할 예정이다.', 'crawl', '뉴시스', '2026-07-07 06:00:57', '중도', 'ready', 'https://img1.newsis.com/2026/04/11/NISI20260411_0021243080_web.jpg?rnd=20260411094545', '2026-07-07 06:04:29', '2026-07-07 16:28:56.575081', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3392, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260706_0003697578', 'https://www.newsis.com/view/NISX20260706_0003697578', '국제', '나토 정상회의, 오늘 개막…''앙카라 선언''으로 동맹 재결속 모색', '[서울=뉴시스] 이재우 기자 = 북대서양조약기구(NATO·나토) 정상회의가 7일 튀르키예 앙카라에서 1박2일 일정으로 열린다. 도널드 트럼프 미국 대통령을 포함해 32개 나토 회원국 정상이 모두 참석하는 앙카라 정상회의는 동맹의 결속을 시험하는 자리가 될 전망이다. 미국은 나토 출범 이후 회원국에 안보 보장을 제공해왔지만 트럼프 대통령은 회원국들이 방위 투자를 늘리고 방위에 1차 책임을 맡아야 한다고 압박하고 있다. 회원국 정상들은 트럼프 대통령이 요구한 방위비 증액을 이행하고 있음을 보여줄 예정이다. 트럼프 대통령의 압박 속에 회원국 정상들은 지난해 정상회의에서 2035년까지 국내총생산(GDP)의 5%를 방위 관련 지출에 투입하기로 합의했다. 유로뉴스 등에 따르면 네덜란드 총리 출신인 마크 뤼터 나토 사무총장은 유럽과 캐나다가 ''핵심 방위비를 전년 대비 20% 늘렸다''는 점을 트럼프 대통령에게 강조할 계획이다. 그는 트럼프 대통령이 첫 임기를 시작한 이후 동맹국들의 누적 방위비 지출이 1조달러에 이른다면서 이를 ''트럼프의 트릴리언Trump’s trillion)''이라고 언급하며 공을 돌릴 예정으로도 알려졌다. 미국을 포함한 32개 회원국 대사급이 사전 합의해 만든 앙카라 정상회의 선언문 초안에는 ''유럽 회원국들과 캐나다가 지난해 핵심 방위 소요에 대한 투자를 1390억 달러 이상 늘렸다''는 문구가 포함돼 있다고 로이터통신 등이 보도했다. 초안은 회원국 정상들이 합의해야 효력이 발생한다. 앙카라 정상회의에서는 유럽 방어 책임을 미국에서 유럽으로 이전하는 ''부담 이전''에 대한 회원국들의 답변도 제시될 전망이다. 유럽 회원국 정상들은 트럼프 대통령에게 유럽 안보 책임의 무게 중심이 이미 미국에서 유럽으로 이동했다고 설득할 계획인 것으로 알려졌다. 뤼터 사무총장은 방위비 지출이 대서양 양안의 협력을 통해 실전 배치 가능한 전력으로 전환돼야 한다고 강조할 계획이다. 나토 3.0 이행을 위해 병력 증강과 방위산업 역량 확대가 필요하다고도 역설할 예정이다. 트럼프 행정부는 중국 견제를 위해 지정학적 이익의 축을 대서양에서 인도태평양으로 옮기면서 유럽이 자국 방어를 주도하고 미국은 핵우산을 제공하는 ''나토 3.0''으로 전환을 요구하고 있다. 트럼프 행정부는 지난달 전쟁 상황에서 나토에 제공할 군사 지원 범위를 축소하겠다고 밝혔다. 매튜 휘태커 나토 주재 미국 대사는 "유럽은 더 이상 미국 납세자에게 무임승차할 수 없다"고 말했다. 회원국 정상들은 앙카라 정상회의에서 ''한 나라에 대한 공격은 모두에 대한 공격''이라는 나토 조약 제5조(집단 방위)를 재천명할 예정이다. 집단 방위는 나토의 근간으로 꼽히지만 트럼프 대통령은 미국이 과도한 부담을 지고 있다며 부정적인 입장을 수차례 내비친 바 있다. 그러나 미국도 앙카라 정상회의를 앞두고 집단 방위 원칙에 동의한 것으로 알려졌다. 정상회의 선언문 초안은 나토 조약 5조에 대한 철통 같은 약속을 재확인하고 러시아가 유럽과 대서양 안보와 안정에 장기적인 위협이라는 문구가 담겨 있다고 유로뉴스는 전했다. 나토 회원국들은 앙카라에서 채택될 정상회의 최종 선언문에서, 나토 조약 제5조(Article 5)에 대한 ‘철통 같은(iron-clad)’ 약속을 재확인하고, 러시아가 “유로-대서양 안보와 안정에 대한 장기적 위협”이라는 점을 분명히 할 예정이다. 다만 트럼프 대통령이 유럽과 캐나다 등 동맹국의 설득을 완만히 받아들일지는 불투명하다. 트럼프 대통령은 나토 정상회의 직전까지 소셜미디어 트루스소셜에 미국의 부담이 과도하다면서 유럽 동맹국들을 비판했다. 트럼프 대통령 특유의 예측 불가능한 발언과 행동이 나올 수도 있다. 그는 미국의 이란 전쟁을 지지하지 않았다는 이유로 영국과 독일, 이탈리아, 스페인 등 동맹국에 무역 중단과 미군 부분 철수 등 뒷끝을 드러냈다. 유럽내 대표적인 친(親)트럼프 인사였던 조르자 멜로니 이탈리아 총리에게는 지난달 주요 7개국(G7) 정상회의에서 애원해서 사진을 찍어줬다고 사실상 모욕을 주기도 했다. 정상회의 전날인 6일에도 트루스소셜에 멜로니 총리를 조롱하는 사진 밈을 올렸다. 트럼프 대통령은 7일 오후 공식 만찬과 8일 오전 공식 환영식, 나토 정상 실무 회의 등 나토 정상회의 공식 일정 외에도 레제프 타이이프 에르도안 튀르키예 대통령, 볼로디미르 젤렌스키 우크라이나 대통령, 아흐메드 알샤라 시리아 대통령과 양자 정상회담 등 부대 일정도 소화할 예정이다. 이재명 대통령과 트럼프 대통령과 회담 여부는 알려지지 않고 있다. 이 대통령이 7일 오후 정상 만찬에 초청된 만큼 트럼프 대통령과 만남은 최소한 나토 정상회의 첫날 성사될 것으로 보인다. ◎공감언론 뉴시스 ironn108@newsis.com', '나토 정상회의, 오늘 개막…''앙카라 선언''으로 동맹 재결속 모색 등록 2026.07.07 06:00:00 수정 2026.07.07 06:38:24 유럽 정상, 방위비 증액·역할 확대 ''성적표'' 제시 전망 트럼프, 나토 근간'' 집단방위 재약속할 듯…초안 기반영 트럼프, 돌발행동 주목…멜로니와 재회 앞두고 또 ''조롱'' [워싱턴=AP/뉴시스] 도널드 트럼프 미국 대통령이 4일(현지 시간) 미국 워싱턴DC 내셔널 몰 일대에서 거행된 미 독립 250주년 기념행사에서 연설하며 주먹을 쥐어 보이고 있다. 2026.07.05 [서울=뉴시스] 이재우 기자 = 북대서양조약기구(NATO·나토) 정상회의가 7일 튀르키예 앙카라에서 1박2일 일정으로 열린다. 도널드 트럼프 미국 대통령을 포함해 32개 나토 회원국 정상이 모두 참석하는 앙카라 정상회의는 동맹의 결속을 시험하는 자리가 될 전망이다. 미국은 나토 출범 이후 회원국에 안보 보장을 제공해왔지만 트럼프 대통령은 회원국들이 방위 투자를 늘리고 방위에 1차 책임을 맡아야 한다고 압박하고 있다. 회원국 정상들은 트럼프 대통령이 요구한 방위비 증액을 이행하고 있음을 보여줄 예정이다. 트럼프 대통령의 압박 속에 회원국 정상들은 지난해 정상회의에서 2035년까지 국내총생산(GDP)의 5%를 방위 관련 지출에 투입하기로 합의했다. 유로뉴스 등에 따르면 네덜란드 총리 출신인 마크 뤼터 나토 사무총장은 유럽과 캐나다가 ''핵심 방위비를 전년 대비 20% 늘렸다''는 점을 트럼프 대통령에게 강조할 계획이다. 그는 트럼프 대통령이 첫 임기를 시작한 이후 동맹국들의 누적 방위비 지출이 1조달러에 이른다면서 이를 ''트럼프의 트릴리언Trump’s trillion)''이라고 언급하며 공을 돌릴 예정으로도 알려졌다. 미국을 포함한 32개 회원국 대사급이 사전 합의해 만든 앙카라 정상회의 선언문 초안에는 ''유럽 회원국들과 캐나다가 지난해 핵심 방위 소요에 대한 투자를 1390억 달러 이상 늘렸다''는 문구가 포함돼 있다고 로이터통신 등이 보도했다. 초안은 회원국 정상들이 합의해야 효력이 발생한다. 앙카라 정상회의에서는 유럽 방어 책임을 미국에서 유럽으로 이전하는 ''부담 이전''에 대한 회원국들의 답변도 제시될 전망이다. 유럽 회원국 정상들은 트럼프 대통령에게 유럽 안보 책임의 무게 중심이 이미 미국에서 유럽으로 이동했다고 설득할 계획인 것으로 알려졌다. 뤼터 사무총장은 방위비 지출이 대서양 양안의 협력을 통해 실전 배치 가능한 전력으로 전환돼야 한다고 강조할 계획이다. 나토 3.0 이행을 위해 병력 증강과 방위산업 역량 확대가 필요하다고도 역설할 예정이다. 트럼프 행정부는 중국 견제를 위해 지정학적 이익의 축을 대서양에서 인도태평양으로 옮기면서 유럽이 자국 방어를 주도하고 미국은 핵우산을 제공하는 ''나토 3.0''으로 전환을 요구하고 있다. 트럼프 행정부는 지난달 전쟁 상황에서 나토에 제공할 군사 지원 범위를 축소하겠다고 밝혔다. 매튜 휘태커 나토 주재 미국 대사는 "유럽은 더 이상 미국 납세자에게 무임승차할 수 없다"고 말했다. 회원국 정상들은 앙카라 정상회의에서 ''한 나라에 대한 공격은 모두에 대한 공격''이라는 나토 조약 제5조(집단 방위)를 재천명할 예정이다. 집단 방위는 나토의 근간으로 꼽히지만 트럼프 대통령은 미국이 과도한 부담을 지고 있다며 부정적인 입장을 수차례 내비친 바 있다. 그러나 미국도 앙카라 정상회의를 앞두고 집단 방위 원칙에 동의한 것으로 알려졌다. 정상회의 선언문 초안은 나토 조약 5조에 대한 철통 같은 약속을 재확인하고 러시아가 유럽과 대서양 안보와 안정에 장기적인 위협이라는 문구가 담겨 있다고 유로뉴스는 전했다. 나토 회원국들은 앙카라에서 채택될 정상회의 최종 선언문에서, 나토 조약 제5조(Article 5)에 대한 ‘철통 같은(iron-clad)’ 약속을 재확인하고, 러시아가 “유로-대서양 안보와 안정에 대한 장기적 위협”이라는 점을 분명히 할 예정이다. 다만 트럼프 대통령이 유럽과 캐나다 등 동맹국의 설득을 완만히 받아들일지는 불투명하다. 트럼프 대통령은 나토 정상회의 직전까지 소셜미디어 트루스소셜에 미국의 부담이 과도하다면서 유럽 동맹국들을 비판했다. 트럼프 대통령 특유의 예측 불가능한 발언과 행동이 나올 수도 있다. 그는 미국의 이란 전쟁을 지지하지 않았다는 이유로 영국과 독일, 이탈리아, 스페인 등 동맹국에 무역 중단과 미군 부분 철수 등 뒷끝을 드러냈다. 유럽내 대표적인 친(親)트럼프 인사였던 조르자 멜로니 이탈리아 총리에게는 지난달 주요 7개국(G7) 정상회의에서 애원해서 사진을 찍어줬다고 사실상 모욕을 주기도 했다. 정상회의 전날인 6일에도 트루스소셜에 멜로니 총리를 조롱하는 사진 밈을 올렸다. 트럼프 대통령은 7일 오후 공식 만찬과 8일 오전 공식 환영식, 나토 정상 실무 회의 등 나토 정상회의 공식 일정 외에도 레제프 타이이프 에르도안 튀르키예 대통령, 볼로디미르 젤렌스키 우크라이나 대통령, 아흐메드 알샤라 시리아 대통령과 양자 정상회담 등 부대 일정도 소화할 예정이다. 이재명 대통령과 트럼프 대통령과 회담 여부는 알려지지 않고 있다. 이 대통령이 7일 오후 정상 만찬에 초청된 만큼 트럼프 대통령과 만남은 최소한 나토 정상회의 첫날 성사될 것으로 보인다.', 'crawl', '뉴시스', '2026-07-07 06:00:00', '중도', 'ready', 'https://img1.newsis.com/2026/07/05/NISI20260705_0001406664_web.jpg?rnd=20260705131901', '2026-07-07 06:04:29', '2026-07-07 16:29:24.359398', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3395, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698119', 'https://www.newsis.com/view/NISX20260707_0003698119', '국제', '[속보] 베네수엘라 지진 사망자 3535명, 부상자 16,700 명으로 늘어', '[서울=뉴시스] 차미례 기자 = 베네수엘라에서 6월 24일 발생한 연쇄 대지진의 사망자 수가 3535명, 부상자는 1만 6740명으로 늘어났다고 호르헤 로드리게스 국회의장이 6일(현지시간) 텔레그램을 통해 발표했다. 지진으로 집을 잃은 난민의 수도 1만7854명으로 증가했다고 로드리게스 의장은 밝혔다. ◎공감언론 뉴시스 cmr@newsis.com', '[서울=뉴시스] 차미례 기자 = 베네수엘라에서 6월 24일 발생한 연쇄 대지진의 사망자 수가 3535명, 부상자는 1만 6740명으로 늘어났다고 호르헤 로드리게스 국회의장이 6일(현지시간) 텔레그램을 통해 발표했다. 지진으로 집을 잃은 난민의 수도 1만7854명으로 증가했다고 로드리게스 의장은 밝혔다. ◎공감언론 뉴시스 cmr@newsis.com', 'rss', '뉴시스', '2026-07-07 05:42:09', '중도', 'crawl_failed', 'https://image.newsis.com/2020/12/11/NISI20201211_0000654239_web.jpg?rnd=20201211094147', '2026-07-07 06:04:29', '2026-07-07 16:29:44.850174', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3399, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698107', 'https://www.newsis.com/view/NISX20260707_0003698107', '국제', '하메네이 시신 종교도시 곰 도착…장례 절차 계속', '[서울=뉴시스] 문예성 기자 = 미국과 이스라엘의 표적 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 시신이 장례 절차를 이어가기 위해 이란의 종교도시 곰에 도착했다. 6일(현지 시간) 이란 반관영 ISNA 통신에 따르면 하메네이의 시신을 운구한 헬기는 이날 곰에 도착했다. 곰에서는 7일 시아파 고위 성직자들이 참석한 가운데 하메네이의 장례 예배가 거행될 예정이다. 하메네이의 장례식은 지난 4일 수도 테헤란에서 시작됐다. 이어 8일에는 시신을 이라크 시아파 성지인 카르발라와 나자프로 운구해 장례식을 치른 뒤, 9일에는 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장할 예정이다. ◎공감언론 뉴시스 sophis731@newsis.com', '하메네이 시신 종교도시 곰 도착…장례 절차 계속 2026.07.07 04:34:33 수정 2026.07.07 04:50:25 7일 장례 예배 진행…8일 이라크 거쳐 9일 마슈하드 안장 미군과 이스라엘의 표적 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 시신이 장례 절차를 이어가기 위해 이란의 종교도시 곰에 도착했다. 6일(현지 시간) 이란 반관영 ISNA 통신에 따르면 하메네이의 시신을 운구한 헬기는 이날 곰에 도착했다. 곰에서는 7일 시아파 고위 성직자들이 참석한 가운데 하메네이의 장례 예배가 거행될 예정이다. 하메네이의 장례식은 지난 4일 수도 테헤란에서 시작됐다. 이어 8일에는 시신을 이라크 시아파 성지인 카르발라와 나자프로 운구해 장례식을 치른 뒤, 9일에는 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장할 예정이다.', 'crawl', '뉴시스', '2026-07-07 04:34:33', '중도', 'ready', 'https://img1.newsis.com/2026/07/03/NISI20260703_0001398546_web.jpg?rnd=20260703115628', '2026-07-07 06:04:29', '2026-07-07 16:32:39.70314', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3405, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698097', 'https://www.newsis.com/view/NISX20260707_0003698097', '국제', '베네수 강진 잔해 속 11일 버틴 생존자 4명 극적 구조', '[서울=뉴시스] 문예성 기자 = 베네수엘라를 강타한 규모 7.2와 7.5의 연쇄 강진으로 붕괴한 건물 잔해에 갇혀 있던 생존자 4명이 지진 발생 267시간 만에 극적으로 구조됐다. 6일(현지 시간) 현지 매체 엘나시오날에 따르면 구조대는 전날 오후 9시께 북부 라과이라주 카라베예다 지역의 붕괴 건물 잔해에서 어린이 2명과 여성 1명, 남성 1명 등 4명을 구조했다. 이들은 지난달 24일 오후 6시(현지 시간) 발생한 강진 이후 267시간 동안 잔해 속에 갇혀 있다가 구조된 것으로 확인됐다. SNS에 공개된 영상에는 구조대가 잔해 속 생존자들과 처음 접촉하는 장면이 담겼다. 구조대원들은 생존자들에게 "침착하게 움직이지 말라"고 당부한 뒤 구조 작업을 벌였다. 구조된 4명은 현장에서 응급 처치를 받은 뒤 구급차를 이용해 인근 병원으로 이송돼 치료와 정밀 검사를 받고 있다. 이번 구조는 지난달 24일 39초 간격으로 발생한 규모 7.2와 7.5의 연쇄 강진 이후 이어진 수색 작업 과정에서 이뤄졌다. 베네수엘라 정부의 최신 집계에 따르면 이번 지진으로 현재까지 최소 3342명이 숨지고 1만6700명이 다쳤다. 이번 연쇄 강진은 최근 100여 년간 베네수엘라에서 발생한 지진 가운데 가장 큰 인명 피해를 낸 재난으로 평가된다. ◎공감언론 뉴시스 sophis731@newsis.com', '베네수엘라를 강타한 규모 7.2와 7.5의 연쇄 강진으로 붕괴한 건물 잔해에 갇혀 있던 생존자 4명이 지진 발생 267시간 만에 극적으로 구조됐다. 6일(현지 시간) 현지 매체 엘나시오날에 따르면 구조대는 전날 오후 9시께 북부 라과이라주 카라베예다 지역의 붕괴 건물 잔해에서 어린이 2명과 여성 1명, 남성 1명 등 4명을 구조했다. 이들은 지난달 24일 오후 6시(현지 시간) 발생한 강진 이후 267시간 동안 잔해 속에 갇혀 있다가 구조된 것으로 확인됐다. SNS에 공개된 영상에는 구조대가 잔해 속 생존자들과 처음 접촉하는 장면이 담겼다. 구조대원들은 생존자들에게 "침착하게 움직이지 말라"고 당부한 뒤 구조 작업을 벌였다. 구조된 4명은 현장에서 응급 처치를 받은 뒤 구급차를 이용해 인근 병원으로 이송돼 치료와 정밀 검사를 받고 있다. 이번 구조는 지난달 24일 39초 간격으로 발생한 규모 7.2와 7.5의 연쇄 강진 이후 이어진 수색 작업 과정에서 이뤄졌다. 베네수엘라 정부의 최신 집계에 따르면 이번 지진으로 현재까지 최소 3342명이 숨지고 1만6700명이 다쳤다. 이번 연쇄 강진은 최근 100여 년간 베네수엘라에서 발생한 지진 가운데 가장 큰 인명 피해를 낸 재난으로 평가된다.', 'crawl', '뉴시스', '2026-07-07 02:23:10', '중도', 'ready', 'https://img1.newsis.com/2026/07/03/NISI20260703_0001397643_web.jpg?rnd=20260703092244', '2026-07-07 06:04:29', '2026-07-07 16:33:31.305276', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3409, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260707_0003698096', 'https://www.newsis.com/view/NISX20260707_0003698096', '국제', '이란 아마디네자드 전 대통령, 하메네이 장례 행진 참석', '[서울=뉴시스] 문예성 기자 = 수개월간 공개석상에 모습을 드러내지 않았던 마무드 아마디네자드 전 이란 대통령이 알리 하메네이 전 최고지도자의 장례 행진에 참석한 모습이 포착됐다. 6일(현지시간) 이란인터내셔널 등에 따르면 이날 현지 SNS에 확산한 영상에는 아마디네자드 전 대통령이 테헤란에서 열린 하메네이 장례 행진에 참석한 모습이 담겼다. 아마디네자드 전 대통령은 최근 수개월간 공개 활동을 중단하면서 그의 행방을 둘러싼 다양한 관측이 제기돼 왔다. 앞서 지난 5월 뉴욕타임스(NYT)는 미국과 이스라엘이 당초 하메네이와 갈등을 빚었던 아마디네자드 전 대통령을 이란의 차기 지도자 후보로 검토했지만, 이후 그의 행방이 묘연해졌다고 보도한 바 있다. 아마디네자드 전 대통령은 재임 기간(2005~2013년) 대이스라엘 강경 발언과 핵 프로그램 추진으로 대표적인 강경파 지도자로 평가받았다. 그러나 퇴임 후인 2019년에는 도널드 트럼프 미국 대통령을 긍정적으로 평가하며 미국과의 관계 개선 필요성을 언급하는 등 이전과 다른 행보를 보인 것으로 알려졌다. NYT는 또 아마디네자드 전 대통령이 미국 측의 이러한 구상을 인지하고 있었지만, 전쟁 첫날 발생한 공격으로 부상을 입은 뒤 입장을 바꿨다고 전했다. 다만 이 같은 보도와 관련해 미국과 이란 정부는 공식 입장을 내놓지 않았다. ◎공감언론 뉴시스 sophis731@newsis.com', '이란 아마디네자드 전 대통령, 하메네이 장례 행진 참석 등록 2026.07.07 01:54:33 수정 2026.07.07 05:48:24 구글에서 선호하는 매체로 추가 작게 크게 수개월 만에 공개석상 【테헤란=AP/뉴시스】 수개월간 공개석상에 모습을 드러내지 않았던 마무드 아마디네자드 전 이란 대통령이 알리 하메네이 전 최고지도자의 장례 행진에 참석한 모습이 포착됐다. 아마디네자드 전 대통령은 6일(현지시간) 이란인터내셔널 등에 따르면 이날 현지 SNS에 확산한 영상에는 아마디네자드 전 대통령이 테헤란에서 열린 하메네이 장례 행진에 참석한 모습이 담겼다. 아마디네자드 전 대통령은 최근 수개월간 공개 활동을 중단하면서 그의 행방을 둘러싼 다양한 관측이 제기돼 왔다. 앞서 지난 5월 뉴욕타임스(NYT)는 미국과 이스라엘이 당초 하메네이와 갈등을 빚었던 아마디네자드 전 대통령을 이란의 차기 지도자 후보로 검토했지만, 이후 그의 행방이 묘연해졌다고 보도한 바 있다. 아마디네자드 전 대통령은 재임 기간(2005~2013년) 대이스라엘 강경 발언과 핵 프로그램 추진으로 대표적인 강경파 지도자로 평가받았다. 그러나 퇴임 후인 2019년에는 도널드 트럼프 미국 대통령을 긍정적으로 평가하며 미국과의 관계 개선 필요성을 언급하는 등 이전과 다른 행보를 보인 것으로 알려졌다. NYT는 또 아마디네자드 전 대통령이 미국 측의 이러한 구상을 인지하고 있었지만, 전쟁 첫날 발생한 공격으로 부상을 입은 뒤 입장을 바꿨다고 전했다. 다만 이 같은 보도와 관련해 미국과 이란 정부는 공식 입장을 내놓지 않았다.', 'crawl', '뉴시스', '2026-07-07 01:54:33', '중도', 'ready', 'https://img1.newsis.com/2017/04/12/NISI20170412_0012891592_web.jpg?rnd=20170412165755', '2026-07-07 06:04:29', '2026-07-07 16:33:56.588209', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3411, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260706_0003698091', 'https://www.newsis.com/view/NISX20260706_0003698091', '국제', '이란 하메네이 장례식서 ''트럼프 돌팔매'' 퍼포먼스', '[서울=뉴시스] 문예성 기자 = 미국과 이스라엘의 표적 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식에서 도널드 트럼프 미국 대통령을 겨냥한 ''돌팔매'' 퍼포먼스가 벌어지는 등 반미 시위가 이어졌다. 6일(현지 시간) 이란 사법부 산하 미잔통신이 공개한 영상에 따르면 하메네이의 장례 행진에 참석한 조문객들은 트럼프 대통령의 얼굴이 담긴 대형 사진을 향해 작은 돌을 던지는 이른바 ''악마에게 돌 던지기'' 의식을 재현했다. ''악마에게 돌 던지기''는 이슬람 성지순례(하지) 의식 가운데 하나로, 악마를 상징하는 기둥을 향해 돌을 던지며 악을 물리친다는 의미를 담고 있다. 장례 행진에는 남녀노소 수많은 시민이 참가해 이란 국기를 흔들고 하메네이의 사진을 든 채 애도의 뜻을 표했다. 일부 참가자는 이란 국기와 함께 트럼프 대통령의 얼굴이 담긴 팻말을 들고 시위에 나섰다. 팻말에는 "트럼프를 죽여라"는 문구와 함께 "하메네이의 죽음에 복수하는 사람에게 2000만 달러의 현상금을 지급한다"는 내용이 적혀 있었다. ''미국에 죽음을''이라는 구호를 외치거나 미국 국기를 불태우는 행태는 이란 정부가 주관하는 집회와 행사에서 반복적으로 등장해 왔다. 한편 하메네이의 장례 일정은 오는 9일까지 이어진다. 6일에는 테헤란에서 장례 행진이 진행됐고, 7일에는 이란 중부 종교도시 곰에서 시아파 고위 성직자들이 참석하는 장례 예배가 열린다. 이어 8일에는 이라크 시아파 성지인 카르발라와 나자프로 시신을 운구해 장례식을 치른 뒤, 9일에는 하메네이의 시신이 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장될 예정이다. ◎공감언론 뉴시스 sophis731@newsis.com', '이란 하메네이 장례식서 ''트럼프 돌팔매'' 퍼포먼스 등록 2026.07.07 00:38:45 구글에서 선호하는 매체로 추가 작게 크게 ''악마에게 돌 던지기'' 의식 재현 ''트럼프를 죽여라'' 팻말도 등장 [테헤란=AP/뉴시스] 미국과 이스라엘의 표적 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식에서 도널드 트럼프 미국 대통령을 겨냥한 ''돌팔매'' 퍼포먼스가 벌어지는 등 반미 시위가 이어졌다. 5일(현지 시간) 테헤란 도심에서 한 남성이 "트럼프를 죽여라"는 문구가 적힌 팻말을 들고 있는 모습. 2026.07.07 [서울=뉴시스] 문예성 기자 = 미국과 이스라엘의 표적 공습으로 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식에서 도널드 트럼프 미국 대통령을 겨냥한 ''돌팔매'' 퍼포먼스가 벌어지는 등 반미 시위가 이어졌다. 6일(현지 시간) 이란 사법부 산하 미잔통신이 공개한 영상에 따르면 하메네이의 장례 행진에 참석한 조문객들은 트럼프 대통령의 얼굴이 담긴 대형 사진을 향해 작은 돌을 던지는 이른바 ''악마에게 돌 던지기'' 의식을 재현했다. ''악마에게 돌 던지기''는 이슬람 성지순례(하지) 의식 가운데 하나로, 악마를 상징하는 기둥을 향해 돌을 던지며 악을 물리친다는 의미를 담고 있다. 장례 행진에는 남녀노소 수많은 시민이 참가해 이란 국기를 흔들고 하메네이의 사진을 든 채 애도의 뜻을 표했다. 일부 참가자는 이란 국기와 함께 트럼프 대통령의 얼굴이 담긴 팻말을 들고 시위에 나섰다. 팻말에는 "트럼프를 죽여라"는 문구와 함께 "하메네이의 죽음에 복수하는 사람에게 2000만 달러의 현상금을 지급한다"는 내용이 적혀 있었다. ''미국에 죽음을''이라는 구호를 외치거나 미국 국기를 불태우는 행태는 이란 정부가 주관하는 집회와 행사에서 반복적으로 등장해 왔다. 한편 하메네이의 장례 일정은 오는 9일까지 이어진다. 6일에는 테헤란에서 장례 행진이 진행됐고, 7일에는 이란 중부 종교도시 곰에서 시아파 고위 성직자들이 참석하는 장례 예배가 열린다. 이어 8일에는 이라크 시아파 성지인 카르발라와 나자프로 시신을 운구해 장례식을 치른 뒤, 9일에는 하메네이의 시신이 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장될 예정이다.', 'crawl', '뉴시스', '2026-07-07 00:38:45', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0001410416_web.jpg?rnd=20260706230939', '2026-07-07 06:04:29', '2026-07-07 16:34:14.728144', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3414, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260706_0003698093', 'https://www.newsis.com/view/NISX20260706_0003698093', '국제', '나토 사무총장 "7일 수백억달러 규모 방산 계약 공개"', '[서울=뉴시스] 신효령 기자 = 북대서양조약기구(NATO·나토)가 튀르키예 앙카라 정상회의에서 수백억달러 규모의 신규 방위산업 계약을 공개한다. 회원국들이 약속한 국방비 증액을 실제 무기 생산과 공동 조달로 연결하겠다는 취지다. AFP통신 등에 따르면 마르크 뤼터 나토 사무총장은 6일(현지시간) 튀르키예 앙카라에서 열린 기자회견에서 "연례 정상회의 첫날인 7일, 동맹국의 억지력과 방어력을 높이는 데 필요한 핵심 장비를 조달하기 위한 대규모 방산 계약을 발표할 것"이라고 밝혔다. 이번 계약은 정상회의 공식 행사인 방산포럼에서 공개된다. 이번 발표는 도널드 트럼프 미국 대통령이 유럽 동맹국들의 방위비 부담 확대를 압박하는 가운데 나온 것이다. 현재 유럽 내 나토 동맹국들과 캐나다는 국내총생산(GDP)의 약 4%를 국방·안보에 투자하며 미국과의 지출 격차를 좁히고 있다. 나토는 이번 회의를 통해 방위비 증액이 실제 군사 역량 확충으로 이어지고 있다는 점을 강조할 계획이다. 뤼터 사무총장은 "지난해 합의한 ''2035년까지 국방·안보 지출 GDP 5% 달성'' 목표를 향해 이미 획기적인 진전이 이뤄지고 있다"며 "이번 회의에서 각국이 더욱 구체적이고 신뢰할 수 있는 이행 계획을 제시할 것"이라고 강조했다. 외신들은 이번 정상회의가 유럽 동맹국들이 방위 분담을 늘리고 미국 의존도를 낮추는 전환점이 될 수 있다고 봤다. 중국을 향한 견제 메시지도 나왔다. 뤼터 사무총장은 인도·태평양에서 벌어지는 정세 변화가 유럽 안보와도 무관하지 않다고 지적했다. 그는 태평양에서 벌어지는 일이 대서양 안보에도 영향을 미친다며, 나토가 러시아뿐 아니라 더 넓은 안보 환경 변화에도 대비해야 한다고 강조했다. ◎공감언론 뉴시스 snow@newsis.com', '나토 사무총장 "7일 수백억달러 규모 방산 계약 공개" 등록 2026.07.07 00:27:23 구글에서 선호하는 매체로 추가 작게 크게 뤼터 사무총장 "유럽·캐나다 이미 GDP 4% 안보 투자" 강조 [앙카라=AP/뉴시스] 북대서양조약기구(NATO·나토)가 방위산업 역량 강화를 위해 수백억 달러 규모의 신규 계약을 체결한다. 사진은 마르크 뤼터 나토 사무총장이 6일(현지 시간) 튀르키예 앙카라에서 열리는 나토 정상회의를 앞두고 국제미디어센터에서 기자회견을 하는 모습. 2026.07.07. [서울=뉴시스] 신효령 기자 = 북대서양조약기구(NATO·나토)가 튀르키예 앙카라 정상회의에서 수백억달러 규모의 신규 방위산업 계약을 공개한다. 회원국들이 약속한 국방비 증액을 실제 무기 생산과 공동 조달로 연결하겠다는 취지다. AFP통신 등에 따르면 마르크 뤼터 나토 사무총장은 6일(현지시간) 튀르키예 앙카라에서 열린 기자회견에서 "연례 정상회의 첫날인 7일, 동맹국의 억지력과 방어력을 높이는 데 필요한 핵심 장비를 조달하기 위한 대규모 방산 계약을 발표할 것"이라고 밝혔다. 이번 계약은 정상회의 공식 행사인 방산포럼에서 공개된다. 이번 발표는 도널드 트럼프 미국 대통령이 유럽 동맹국들의 방위비 부담 확대를 압박하는 가운데 나온 것이다. 현재 유럽 내 나토 동맹국들과 캐나다는 국내총생산(GDP)의 약 4%를 국방·안보에 투자하며 미국과의 지출 격차를 좁히고 있다. 나토는 이번 회의를 통해 방위비 증액이 실제 군사 역량 확충으로 이어지고 있다는 점을 강조할 계획이다. 뤼터 사무총장은 "지난해 합의한 ''2035년까지 국방·안보 지출 GDP 5% 달성'' 목표를 향해 이미 획기적인 진전이 이뤄지고 있다"며 "이번 회의에서 각국이 더욱 구체적이고 신뢰할 수 있는 이행 계획을 제시할 것"이라고 강조했다. 외신들은 이번 정상회의가 유럽 동맹국들이 방위 분담을 늘리고 미국 의존도를 낮추는 전환점이 될 수 있다고 봤다. 중국을 향한 견제 메시지도 나왔다. 뤼터 사무총장은 인도·태평양에서 벌어지는 정세 변화가 유럽 안보와도 무관하지 않다고 지적했다. 그는 태평양에서 벌어지는 일이 대서양 안보에도 영향을 미친다며, 나토가 러시아뿐 아니라 더 넓은 안보 환경 변화에도 대비해야 한다고 강조했다.', 'crawl', '뉴시스', '2026-07-07 00:27:23', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0002179449_web.jpg?rnd=20260707001505', '2026-07-07 06:04:29', '2026-07-07 16:34:38.121861', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3420, 'https://www.newsis.com/RSS/international.xml', 'https://www.newsis.com/view/NISX20260706_0003698077', 'https://www.newsis.com/view/NISX20260706_0003698077', '국제', '이란 대통령, 하메네이 장례식 참석 위해 이라크행', '[서울=뉴시스] 문예성 기자 = 마수드 페제시키안 이란 대통령이 최고지도자 알리 하메네이의 장례식 참석을 위해 이라크를 방문한다. 6일(현지 시간) 이란 반관영 ISNA 통신에 따르면 페제시키안 대통령은 8일 이라크 나자프와 카르발라에서 열리는 하메네이의 장례 행사에 참석할 예정이다. ISNA는 하메네이의 장남 모스타파 하메네이와 모하마드 바게르 갈리바프 의회 의장도 이라크에서 열리는 장례 행사에 참석할 것이라는 앞선 보도는 사실이 아니라고 전했다. 하메네이의 장례 일정은 오는 9일까지 이어진다. 6일에는 테헤란 시내에서 장례 행진이 진행되고, 7일에는 이란 중부 종교도시 곰에서 시아파 고위 성직자들이 참석하는 장례 예배가 열린다. 이어 8일에는 이라크 시아파 성지인 카르발라와 나자프로 시신을 운구해 장례식을 치른 뒤, 9일에는 하메네이의 시신이 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장될 예정이다. ◎공감언론 뉴시스 sophis731@newsis.com', '이란 대통령, 하메네이 장례식 참석 위해 이라크행 등록 2026.07.06 23:15:14 8일 나자프·카르발라서 장례식 마수드 페제시키안 이란 대통령이 최고지도자 알리 하메네이의 장례식 참석을 위해 이라크를 방문한다. 2026.07.06 문예성 기자 = 마수드 페제시키안 이란 대통령이 최고지도자 알리 하메네이의 장례식 참석을 위해 이라크를 방문한다. 6일(현지 시간) 이란 반관영 ISNA 통신에 따르면 페제시키안 대통령은 8일 이라크 나자프와 카르발라에서 열리는 하메네이의 장례 행사에 참석할 예정이다. ISNA는 하메네이의 장남 모스타파 하메네이와 모하마드 바게르 갈리바프 의회 의장도 이라크에서 열리는 장례 행사에 참석할 것이라는 앞선 보도는 사실이 아니라고 전했다. 하메네이의 장례 일정은 오는 9일까지 이어진다. 6일에는 테헤란 시내에서 장례 행진이 진행되고, 7일에는 이란 중부 종교도시 곰에서 시아파 고위 성직자들이 참석하는 장례 예배가 열린다. 이어 8일에는 이라크 시아파 성지인 카르발라와 나자프로 시신을 운구해 장례식을 치른 뒤, 9일에는 하메네이의 시신이 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에 안장될 예정이다.', 'crawl', '뉴시스', '2026-07-06 23:15:14', '중도', 'ready', 'https://img1.newsis.com/2026/06/18/NISI20260618_0002164258_web.jpg?rnd=20260618135323', '2026-07-07 06:04:29', '2026-07-07 16:35:34.537055', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3440, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260707_0003698958', 'https://www.newsis.com/view/NISX20260707_0003698958', '경제', '구윤철 "보유세·거래세 조화 이뤄야…부동산 세제개편안 7월말 발표"(종합)', '[세종=뉴시스] 안호균 기자 = 구윤철 경제부총리 겸 재정경제부 장관은 7일 정부의 3대 메가프로젝트 지원 방안과 관련, "지방에 근무하는 분들에게는 세금을 차등지원하는 방법까지도 추진해서 총력지원할 것"이라고 밝혔다. 구 부총리는 이날 오전 MBC 라디오 ''김종배의 시선집중''과의 인터뷰에서 "3대 메가프로젝트는 총력전·속도전으로 간다면 대한민국에 엄청난 기회가 될 것"이라며 이같이 밝혔다. 그는 "지방에 근무하다보면 환경이 열악하지 않나. 그런 부분을 감안해 서울의 세금(소득세)보다는 감면을 더 해준다는 것"이라며 "근로자분들의 희망사항을 반영해 검토할 것"이라고 언급했다. 기업에 대한 세제지원에 대해서는 "반도체·인공지능(AI) 쪽은 최고의 세제지원을 해주고 있다"며 "연구개발(R&D) 투자 지원을 해주려고 하고, 이익이 생겨서 지금은 내더라도 나중에 세금을 못내는 시절이 오면 이월공제까지 해주려고 한다"고 전했다. 또 "기업들이 투자를 하는거고 정부는 기업이 투자하는데 필요한 인프라, 인력 공급, 규제 완화, 재정 지원, 세제 지원 그런 부분을 총력 대응해서 지원을 할 계획"이라고 설명했다. 구 부총리는 올해 예상되는 초과세수 규모에 대해 "상반기 영업 실적과 8월 말 법인세 중간예납을 받아봐야 알 수 있겠지만 굉장히 많이 들어올 것 같다"며 FN가이드를 보면 삼성전자, 하이닉스 두 기업만 600조원의 영업이익을 예상하고 있다. 20%만 잡는다고 하더라도 어마어마한 규모"라고 했다. 정부가 초과세수를 활용해 신설하는 ''미래대응기금''에 대해서는 "미래대응기금은 그야말로 미래를 위한 준비에 사용될 것"이라며 "재정 여력을 속도감 있게 쓰는 측면도 있어야 하고, 특정 분야에 쓸 필요도 있다. 내부적으로 검토 중에 있다"고 말했다. ''미래대응기금을 (반도체 클러스터) 전력이나 용수 공급을 위한 재원으로 투입하는가''라는 질문에는 "전력·용수에도 돈이 들어가고 로봇, 피지컬AI, 조선, 항공 등 반도체 이외의 혁신산업들에도 R&D 지원이 필요하면 해야 한다"며 "매년 어마어마한 돈이 들어오기 때문에 미래 성장잠재력을 높이고 대체불가능한 대한민국을 건설하는데 필요한 인프라 지원을 우선적으로 해 줄 것"이라고 강조했다. 이와 함께 구 부총리는 부동산 세제 개편에 대해 "7월 말 정도로 생각하고 있다"며 "기본적으로 집은 바잉(buying)이 아니고 리빙(living)을 위한 것이라는 원칙 하에서 실거주자 중심의 주택시장이 확립될 수 있도록 하는 차원에서 세제를 보고 있다"고 전했다. 그는 "정부가 일방적으로 결정하기보다는 폭넓게 국민들의 의견을 경청하고 최대한 반영하려고 한다"며 "조만간 부동산 세제 관련해서 국민 의견을 수렴하는 절차를 밟고, 현장의 목소리도 들어서 최종적으로 정부 방침을 결정할 것"이라고 밝혔다. ''보유세와 거래세를 모두 건드리게 되느냐''는 질문에는 "두 가지가 밸런스를 이뤄야 한다. 그런 차원에서 함께 보고 있다"고 답했다. 최근 물가 동향과 관련해서는 "최근에 중동 상황으로 인해 석유류 등이 많이 오른 건 사실이다. 그런 부분은 최고가격제를 설정해서 6월 물가가 0.4%포인트 완화되는 추정도 있었다"고 분석했다. 구 부총리는 "석유류 외에는 축산물이 특히 많이 올랐다. 그래서 계란이나 닭고기 등의 가격을 낮추기 위해 할인 행사를 한다든지, 납품 단가가 인하되도록 지원한다든지, 수입을 확대한다든지, 정부가 비축하고 있는 물량을 확대 공급한다든지 해서 총력대응할 것"이라며 "1조 원 규모의 재정을 투입해 하반기에는 (물가상승률을) 3% 이내로 관리하겠다"고 강조했다. ◎공감언론 뉴시스 ahk@newsis.com', '구윤철 "보유세·거래세 조화 이뤄야…부동산 세제개편안 7월말 발표"(종합) 등록 2026.07.07 12:40:36 수정 2026.07.07 15:14:24 "지방 근무 근로자, 서울보다 소득세 감면 더 해줄것" "(3대 프로젝트 참여 기업은) 어려울때 이월공제까지" "추가세수, 대체불가능한 대한민국 건설에 우선 지원" "실거주 중심 주택시장 확립하는 방향으로 세제 개편" [서울=뉴시스] 구윤철 부총리 겸 재정경제부 장관이 6일 서울 중구 웨스틴조선호텔에서 열린 민관합동 ''서비스산업 경쟁력 강화 TF 2차회의''에서 발언하고 있다. 구 부총리는 7일 정부의 3대 메가프로젝트 지원 방안과 관련, "지방에 근무하는 분들에게는 세금을 차등지원하는 방법까지도 추진해서 총력지원할 것"이라고 밝혔다. 구 부총리는 이날 오전 MBC 라디오 ''김종배의 시선집중''과의 인터뷰에서 "3대 메가프로젝트는 총력전·속도전으로 간다면 대한민국에 엄청난 기회가 될 것"이라며 이같이 밝혔다. 그는 "지방에 근무하다보면 환경이 열악하지 않나. 그런 부분을 감안해 서울의 세금(소득세)보다는 감면을 더 해준다는 것"이라며 "근로자분들의 희망사항을 반영해 검토할 것"이라고 언급했다. 기업에 대한 세제지원에 대해서는 "반도체·인공지능(AI) 쪽은 최고의 세제지원을 해주고 있다"며 "연구개발(R&D) 투자 지원을 해주려고 하고, 이익이 생겨서 지금은 내더라도 나중에 세금을 못내는 시절이 오면 이월공제까지 해주려고 한다"고 전했다. 또 "기업들이 투자를 하는거고 정부는 기업이 투자하는데 필요한 인프라, 인력 공급, 규제 완화, 재정 지원, 세제 지원 그런 부분을 총력 대응해서 지원을 할 계획"이라고 설명했다. 구 부총리는 올해 예상되는 초과세수 규모에 대해 "상반기 영업 실적과 8월 말 법인세 중간예납을 받아봐야 알 수 있겠지만 굉장히 많이 들어올 것 같다"며 FN가이드를 보면 삼성전자, 하이닉스 두 기업만 600조원의 영업이익을 예상하고 있다. 20%만 잡는다고 하더라도 어마어마한 규모"라고 했다. 정부가 초과세수를 활용해 신설하는 ''미래대응기금''에 대해서는 "미래대응기금은 그야말로 미래를 위한 준비에 사용될 것"이라며 "재정 여력을 속도감 있게 쓰는 측면도 있어야 하고, 특정 분야에 쓸 필요도 있다. 내부적으로 검토 중에 있다"고 말했다. ''미래대응기금을 (반도체 클러스터) 전력이나 용수 공급을 위한 재원으로 투입하는가''라는 질문에는 "전력·용수에도 돈이 들어가고 로봇, 피지컬AI, 조선, 항공 등 반도체 이외의 혁신산업들에도 R&D 지원이 필요하면 해야 한다"며 "매년 어마어마한 돈이 들어오기 때문에 미래 성장잠재력을 높이고 대체불가능한 대한민국을 건설하는데 필요한 인프라 지원을 우선적으로 해 줄 것"이라고 강조했다. 이와 함께 구 부총리는 부동산 세제 개편에 대해 "7월 말 정도로 생각하고 있다"며 "기본적으로 집은 바잉(buying)이 아니고 리빙(living)을 위한 것이라는 원칙 하에서 실거주자 중심의 주택시장이 확립될 수 있도록 하는 차원에서 세제를 보고 있다"고 전했다. 그는 "정부가 일방적으로 결정하기보다는 폭넓게 국민들의 의견을 경청하고 최대한 반영하려고 한다"며 "조만간 부동산 세제 관련해서 국민 의견을 수렴하는 절차를 밟고, 현장의 목소리도 들어서 최종적으로 정부 방침을 결정할 것"이라고 밝혔다. ''보유세와 거래세를 모두 건드리게 되느냐''는 질문에는 "두 가지가 밸런스를 이뤄야 한다. 그런 차원에서 함께 보고 있다"고 답했다. 최근 물가 동향과 관련해서는 "최근에 중동 상황으로 인해 석유류 등이 많이 오른 건 사실이다. 그런 부분은 최고가격제를 설정해서 6월 물가가 0.4%포인트 완화되는 추정도 있었다"고 분석했다. 구 부총리는 "석유류 외에는 축산물이 특히 많이 올랐다. 그래서 계란이나 닭고기 등의 가격을 낮추기 위해 할인 행사를 한다든지, 납품 단가가 인하되도록 지원한다든지, 수입을 확대한다든지, 정부가 비축하고 있는 물량을 확대 공급한다든지 해서 총력대응할 것"이라며 "1조 원 규모의 재정을 투입해 하반기에는 (물가상승률을) 3% 이내로 관리하겠다"고 강조했다.', 'crawl', '뉴시스', '2026-07-07 12:40:36', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0021351198_web.jpg?rnd=20260706085326', '2026-07-07 06:04:30', '2026-07-07 16:38:17.537726', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3444, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260707_0003698649', 'https://www.newsis.com/view/NISX20260707_0003698649', '경제', '양도세 중과 피하려 허위 이전…731억 부동산 탈세 적발', '[세종=뉴시스] 안호균 기자 = 2주택자인 A씨는 양도 차익이 큰 서울 소재 고가 아파트를 양도하기 전 본인이 살고 있는 저가 아파트를 모친의 지인에게 낮은 가격으로 이전하고 양도차손을 신고했다. 이후 A씨는 고가 아파트를 20억원에 양도하고 1세대 1주택으로 양도세 비과세를 적용받았다. 조사 결과 A씨가 저가아파트를 지인에게 넘긴건 다주택자 양도세 중과를 피하기 위한 꼼수였다. 그는 취득세·재산세를 대납해주고, 양도 후에도 저가아파트에 계속 거주했다. 또 매월 수십만 원의 사례금을 주다가 나중에는 저가 아파트 명의를 다시 돌려받았다. 국세청은 A씨에 대한 세무조사에 착수해 10억원의 양도세를 추징하고 A씨 등을 검찰에 고발조치했다. 이렇게 고가 주택을 거래하면서 시장질서를 교란하고 납세 의무는 회피한 자산가들에 대해 국세청이 엄정한 대응에 나섰다. 국세청은 지난해 10월 초고가주택 등 부동산 탈세 혐의자 104명에 대해 동시 조사에 착수, 현재까지 세무조사를 통해 총 318억원의 세금을 추징했다고 밝혔다. 현재까지 확인된 조사 대상자들의 탈루 규모는 731억원에 달한다. 조사 결과 A씨처럼 가장매매로 부당하게 1세대 1주택 비과세를 적용받아 양도소득세를 회피한 사례가 다수 적발됐다. 부모로부터 몰래 증여받은 자금으로 고가 아파트를 취득해 증여세를 탈루한 사례도 있었다. 또 국세청은 부동산 거래 과정에서 드러난 양도세·증여세 탈루 뿐만 아니라, 자금 원천이 사업소득 누락 및 법인자금 유출과 관련된 경우 사업체까지 조사 범위를 확대해 법인세·소득세 등 누락 여부도 살폈다. B씨는 배우자가 운영하는 축산물 도매업체의 자금을 사용해 약 40억원 규모의 서울 강남권 재건축 예정 아파트를 비롯해 상가, 토지 등 다수의 부동산을 취득했다. 배우자는 거래처에 무자료 매출을 통해 조성한 비자금 약 30억원을 별도 관리하다가 B씨에게 몰래 증여한 것으로 나타났다. 국세청은 축산물 도매업체의 매출누락에 대한 법인세와 B씨의 부동산 취득자금 증여세 등 31억원을 추징했다. 부모의 도움으로 고가 아파트에 거주하면서 증여세 납부를 회피한 사례도 적발됐다. C씨는 소득이 전혀 없음에도 매월 700만원 이상의 고액 월세를 지급하면서 서울 강남 한강변 소재 고가아파트에 살고 있었다. 또 수십억원 규모의 주식을 취득하고, 매년 수억원에 달하는 생활비를 지출하는 등 소득·재산내역 등에 비해 호화·사치 생활을 하고 있는 것으로 파악됐다. 조사 결과 C씨는 임대업자인 부모로부터 월세, 주식 투자자금, 생활비를 포함한 20여억원의 자금을 증여받은 것으로 파악돼 13억원을 추징당했다. 국세청은 지난해부터 시장 과열이 나타나는 지역에 대해 모니터링 및 현장정보 수집을 한층 강화했으며 30억원 이상 초고가주택 취득거래와 강남4구 아파트 증여거래 전반을 점검했다. 최근에는 대출규제의 영향을 받지 않는 현금부자, 고액의 사적채무를 활용한 취득자, 투기목적으로 주택을 취득한 다주택자 등 탈세혐의자 등에 대한 세무조사도 실시했다. 오상훈 국세청 자산과세국장은 이날 브리핑에서 "조사과정에서 사기나 그 밖의 부정한 방법으로 조세를 포탈한 사실이 확인된 건은 40%에 상당하는 부당 과소신고가산세를 부과하는 한편, ''조세범처벌법''에 따라 세금 추징 외에도 응당한 처분을 받을 수 있도록 6명은 검찰에 고발하고, 4명은 벌금 상당액 7억원을 통고처분하는 등 엄정하게 조치했다"고 설명했다. 오 국장은 "다주택자 중과 재개 후 증여거래가 늘어날 우려가 있는 만큼 다주택자 증여거래를 중심으로 증여재산을 저가평가하거나 증여세를 대납하는 등 편법 증여가 없는지 검증할 예정"이라고 전했다. ◎공감언론 뉴시스 ahk@newsis.com', '[세종=뉴시스] 안호균 기자 = 2주택자인 A씨는 양도 차익이 큰 서울 소재 고가 아파트를 양도하기 전 본인이 살고 있는 저가 아파트를 모친의 지인에게 낮은 가격으로 이전하고 양도차손을 신고했다. 이후 A씨는 고가 아파트를 20억원에 양도하고 1세대 1주택으로 양도세 비과세를 적용받았다. 조사 결과 A씨가 저가아파트를 지인에게 넘긴건 다주택자 양도세 중과를 피하기 위한 꼼수였다. 그는 취득세·재산세를 대납해주고, 양도 후에도 저가아파트에 계속 거주했다. 또 매월 수십만 원의 사례금을 주다가 나중에는 저가 아파트 명의를 다시 돌려받았다. 국세청은 A씨에 대한 세무조사에 착수해 10억원의 양도세를 추징하고 A씨 등을 검찰에 고발조치했다. 이렇게 고가 주택을 거래하면서 시장질서를 교란하고 납세 의무는 회피한 자산가들에 대해 국세청이 엄정한 대응에 나섰다. 국세청은 지난해 10월 초고가주택 등 부동산 탈세 혐의자 104명에 대해 동시 조사에 착수, 현재까지 세무조사를 통해 총 318억원의 세금을 추징했다고 밝혔다. 현재까지 확인된 조사 대상자들의 탈루 규모는 731억원에 달한다. 조사 결과 A씨처럼 가장매매로 부당하게 1세대 1주택 비과세를 적용받아 양도소득세를 회피한 사례가 다수 적발됐다. 부모로부터 몰래 증여받은 자금으로 고가 아파트를 취득해 증여세를 탈루한 사례도 있었다. 또 국세청은 부동산 거래 과정에서 드러난 양도세·증여세 탈루 뿐만 아니라, 자금 원천이 사업소득 누락 및 법인자금 유출과 관련된 경우 사업체까지 조사 범위를 확대해 법인세·소득세 등 누락 여부도 살폈다. B씨는 배우자가 운영하는 축산물 도매업체의 자금을 사용해 약 40억원 규모의 서울 강남권 재건축 예정 아파트를 비롯해 상가, 토지 등 다수의 부동산을 취득했다. 배우자는 거래처에 무자료 매출을 통해 조성한 비자금 약 30억원을 별도 관리하다가 B씨에게 몰래 증여한 것으로 나타났다. 국세청은 축산물 도매업체의 매출누락에 대한 법인세와 B씨의 부동산 취득자금 증여세 등 31억원을 추징했다. 부모의 도움으로 고가 아파트에 거주하면서 증여세 납부를 회피한 사례도 적발됐다. C씨는 소득이 전혀 없음에도 매월 700만원 이상의 고액 월세를 지급하면서 서울 강남 한강변 소재 고가아파트에 살고 있었다. 또 수십억원 규모의 주식을 취득하고, 매년 수억원에 달하는 생활비를 지출하는 등 소득·재산내역 등에 비해 호화·사치 생활을 하고 있는 것으로 파악됐다. 조사 결과 C씨는 임대업자인 부모로부터 월세, 주식 투자자금, 생활비를 포함한 20여억원의 자금을 증여받은 것으로 파악돼 13억원을 추징당했다. 국세청은 지난해부터 시장 과열이 나타나는 지역에 대해 모니터링 및 현장정보 수집을 한층 강화했으며 30억원 이상 초고가주택 취득거래와 강남4구 아파트 증여거래 전반을 점검했다. 최근에는 대출규제의 영향을 받지 않는 현금부자, 고액의 사적채무를 활용한 취득자, 투기목적으로 주택을 취득한 다주택자 등 탈세혐의자 등에 대한 세무조사도 실시했다. 오상훈 국세청 자산과세국장은 이날 브리핑에서 "조사과정에서 사기나 그 밖의 부정한 방법으로 조세를 포탈한 사실이 확인된 건은 40%에 상당하는 부당 과소신고가산세를 부과하는 한편, ''조세범처벌법''에 따라 세금 추징 외에도 응당한 처분을 받을 수 있도록 6명은 검찰에 고발하고, 4명은 벌금 상당액 7억원을 통고처분하는 등 엄정하게 조치했다"고 설명했다. 오 국장은 "다주택자 중과 재개 후 증여거래가 늘어날 우려가 있는 만큼 다주택자 증여거래를 중심으로 증여재산을 저가평가하거나 증여세를 대납하는 등 편법 증여가 없는지 검증할 예정"이라고 전했다. ◎공감언론 뉴시스 ahk@newsis.com', 'rss', '뉴시스', '2026-07-07 12:00:00', '중도', 'crawl_failed', 'https://image.newsis.com/2026/07/07/NISI20260707_0002179885_web.jpg?rnd=20260707104926', '2026-07-07 06:04:30', '2026-07-07 16:44:51.738382', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3445, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260707_0003698867', 'https://www.newsis.com/view/NISX20260707_0003698867', '경제', '대상 등 전분당 4개사, 가격담합에 과징금 7476억 부과', '[세종=뉴시스]임하은 기자 = 공정거래위원회가 7년5개월간 기업간거래(B2B) 시장에서 가격담합을 벌인 전분당 제조·판매업체 4곳에 담합 사건 역대 최대 규모인 7476억원의 과징금을 부과했다. 아울러 경쟁 회복을 위해 가격을 새로 결정하도록 하는 ''가격 재결정 명령''도 함께 내렸다. 공정위는 7일 대상, 사조씨피케이, 삼양사, CJ제일제당 등 전분당 제조·판매업체 4곳의 가격담합에 대해 독자적 가격 재결정 등 시정명령과 함께 총 7476억원의 과징금을 부과하기로 결정했다. 이는 담합 사건에 부과된 과징금 가운데 역대 최대 규모다. 업체별 과징금은 대상 2341억원, 사조씨피케이 2001억원, 삼양사 2103억원, CJ제일제당 1029억원이다. 이들 4개사는 B2B 전분당 시장의 약 90%를 차지하고 있다. 과징금 규모 차이는 시장점유율에 따른 것으로, CJ제일제당의 점유율은 약 12%인 반면 나머지 3개사는 모두 20%를 웃돈다. 전분당은 옥수수 등을 원료로 만드는 당류로, 물엿·올리고당·포도당·과당 등이 이에 해당한다. 정부는 전분당의 주원료인 수입 옥수수가 국민 생활물가에 미치는 영향이 크다고 판단해 2021년 4월부터 할당관세 0%를 적용하고 있다. 이번 담합으로 영향을 받은 관련 매출액은 6조525억원으로 산정됐다. 공정위는 이번 담합을 ''매우 중대한 위법행위''로 판단하고 관련 매출액의 15%를 과징금으로 부과했다. 매우 중대한 위법행위의 경우 관련 매출액의 최대 20%까지 과징금을 부과할 수 있다. 앞서 밀가루·설탕 담합 사건에도 같은 기준율인 15%가 적용됐다. 남동일 공정위 부위원장은 이날 정부세종청사에서 열린 브리핑에서 "기본 부과기준율 15%를 적용한 뒤 가중·감경 사유를 반영했다"며 "조사와 심의에 협조한 점을 고려해 4개사 모두 20%를 감경했고, 대상은 법 위반 전력이 있어 횟수 가중으로 10%를 추가 적용했다"고 설명했다. 공정위는 4개사가 2018년 5월부터 지난해 10월까지 7년5개월간 모두 13차례에 걸쳐 판매가격의 인상·인하 폭과 시기 등을 합의해 실행했다고 판단했다. 특히 러시아·우크라이나 전쟁으로 국제 옥수수 가격이 급등하자 2022년 11월에는 담합 시작 시점과 비교해 판매가격을 최대 73%까지 인상했다. 이들은 모두 7차례에 걸쳐 전체 B2B 거래처를 대상으로 판매가격 인상 합의를 실행했다. 반면 옥수수 가격이 하락했을 때는 원가 하락분보다 판매가격 인하폭을 줄이고 인하 시기도 최대한 늦추기로 합의한 사례가 5차례 있었다. 당시 원가가 하락했음에도 영업이익은 오히려 개선됐고, 그 부담은 실수요처와 대리점, 소비자에게 전가됐다고 공정위는 설명했다. 또 실수요처 가운데 한 곳인 동서식품에 대해서는 자체 계산식에 따라 가격 인상을 합의하고 가격 산정의 핵심 항목 금액을 공동으로 결정하기도 했다. 4개사는 임원급 모임에서 목표 가격과 인상 시기 등을 합의하고, 팀장급 모임에서는 가격 변동 근거와 사업자별 공문 발송 순서 등을 구체적으로 정한 것으로 조사됐다. 공문 발송 당일에는 타사를 방문해 합의 내용이 그대로 반영됐는지 확인하고 우체국까지 동행하는 등 치밀하게 담합을 실행한 것으로 나타났다. 공정위는 4개사에 전분당 제품 가격을 담합 이전의 경쟁이 회복되는 수준으로 재결정하고, 향후 3년간 반기마다 그 결과를 보고하도록 하는 ''가격 재결정 명령''도 함께 부과했다. 가격 재결정 명령은 지난 5월 밀가루 담합 사건에 이어 이번이 네 번째다. 공정위는 이번 담합이 장기간 업계 관행처럼 지속됐고, 지난 20여년간 4개사의 과점 체제가 큰 변동 없이 유지된 점 등을 고려할 때 담합이 재발할 가능성이 크다고 판단했다. 한편 검찰이 지난 4월 이들 4개사를 10조원대 가격담합 혐의 등으로 기소한 것과 관련해 남 부위원장은 "검찰은 가격담합과 입찰담합, 부산물 담합을 한꺼번에 기소했다"며 "입찰담합의 경우 시작 시점을 공정위와 다르게 봤고, 관련 매출액도 형사 제재를 위한 산정과 경제적 제재를 위한 산정 방식에 차이가 있다"고 설명했다. ◎공감언론 뉴시스 rainy71@newsis.com', '대상 등 전분당 4개사, 가격담합에 과징금 7476억 부과 등록 2026.07.07 12:00:00 구글에서 선호하는 매체로 추가 작게 크게 담합 과징금 역대 최대…2010년 LPG 6개사 제재 넘어 7년5개월간 판매가격 담합…가격재결정 3년간 보고 [세종=뉴시스] 배훈식 기자 = 남동일 공정거래위원회 부위원장이 7일 오전 세종시 정부세종청사에서 전분 및 전분당 가격 담합 사건 심의 결과 브리핑을 하고 있다. 2026.07.07. [세종=뉴시스]임하은 기자 = 공정거래위원회가 7년5개월간 기업간거래(B2B) 시장에서 가격담합을 벌인 전분당 제조·판매업체 4곳에 담합 사건 역대 최대 규모인 7476억원의 과징금을 부과했다. 아울러 경쟁 회복을 위해 가격을 새로 결정하도록 하는 ''가격 재결정 명령''도 함께 내렸다. 공정위는 7일 대상, 사조씨피케이, 삼양사, CJ제일제당 등 전분당 제조·판매업체 4곳의 가격담합에 대해 독자적 가격 재결정 등 시정명령과 함께 총 7476억원의 과징금을 부과하기로 결정했다. 이는 담합 사건에 부과된 과징금 가운데 역대 최대 규모다. 업체별 과징금은 대상 2341억원, 사조씨피케이 2001억원, 삼양사 2103억원, CJ제일제당 1029억원이다. 이들 4개사는 B2B 전분당 시장의 약 90%를 차지하고 있다. 과징금 규모 차이는 시장점유율에 따른 것으로, CJ제일제당의 점유율은 약 12%인 반면 나머지 3개사는 모두 20%를 웃돈다. 전분당은 옥수수 등을 원료로 만드는 당류로, 물엿·올리고당·포도당·과당 등이 이에 해당한다. 정부는 전분당의 주원료인 수입 옥수수가 국민 생활물가에 미치는 영향이 크다고 판단해 2021년 4월부터 할당관세 0%를 적용하고 있다. 이번 담합으로 영향을 받은 관련 매출액은 6조525억원으로 산정됐다. 공정위는 이번 담합을 ''매우 중대한 위법행위''로 판단하고 관련 매출액의 15%를 과징금으로 부과했다. 매우 중대한 위법행위의 경우 관련 매출액의 최대 20%까지 과징금을 부과할 수 있다. 앞서 밀가루·설탕 담합 사건에도 같은 기준율인 15%가 적용됐다. 남동일 공정위 부위원장은 이날 정부세종청사에서 열린 브리핑에서 "기본 부과기준율 15%를 적용한 뒤 가중·감경 사유를 반영했다"며 "조사와 심의에 협조한 점을 고려해 4개사 모두 20%를 감경했고, 대상은 법 위반 전력이 있어 횟수 가중으로 10%를 추가 적용했다"고 설명했다. [세종=뉴시스] 전분당 평균가격 변동. (자료 = 공정거래위원회 제공) 2026.07.07. 공정위는 4개사가 2018년 5월부터 지난해 10월까지 7년5개월간 모두 13차례에 걸쳐 판매가격의 인상·인하 폭과 시기 등을 합의해 실행했다고 판단했다. 특히 러시아·우크라이나 전쟁으로 국제 옥수수 가격이 급등하자 2022년 11월에는 담합 시작 시점과 비교해 판매가격을 최대 73%까지 인상했다. 이들은 모두 7차례에 걸쳐 전체 B2B 거래처를 대상으로 판매가격 인상 합의를 실행했다. 반면 옥수수 가격이 하락했을 때는 원가 하락분보다 판매가격 인하폭을 줄이고 인하 시기도 최대한 늦추기로 합의한 사례가 5차례 있었다. 당시 원가가 하락했음에도 영업이익은 오히려 개선됐고, 그 부담은 실수요처와 대리점, 소비자에게 전가됐다고 공정위는 설명했다. 또 실수요처 가운데 한 곳인 동서식품에 대해서는 자체 계산식에 따라 가격 인상을 합의하고 가격 산정의 핵심 항목 금액을 공동으로 결정하기도 했다. 4개사는 임원급 모임에서 목표 가격과 인상 시기 등을 합의하고, 팀장급 모임에서는 가격 변동 근거와 사업자별 공문 발송 순서 등을 구체적으로 정한 것으로 조사됐다. 공문 발송 당일에는 타사를 방문해 합의 내용이 그대로 반영됐는지 확인하고 우체국까지 동행하는 등 치밀하게 담합을 실행한 것으로 나타났다. 공정위는 4개사에 전분당 제품 가격을 담합 이전의 경쟁이 회복되는 수준으로 재결정하고, 향후 3년간 반기마다 그 결과를 보고하도록 하는 ''가격 재결정 명령''도 함께 부과했다. 가격 재결정 명령은 지난 5월 밀가루 담합 사건에 이어 이번이 네 번째다. 공정위는 이번 담합이 장기간 업계 관행처럼 지속됐고, 지난 20여년간 4개사의 과점 체제가 큰 변동 없이 유지된 점 등을 고려할 때 담합이 재발할 가능성이 크다고 판단했다. 한편 검찰이 지난 4월 이들 4개사를 10조원대 가격담합 혐의 등으로 기소한 것과 관련해 남 부위원장은 "검찰은 가격담합과 입찰담합, 부산물 담합을 한꺼번에 기소했다"며 "입찰담합의 경우 시작 시점을 공정위와 다르게 봤고, 관련 매출액도 형사 제재를 위한 산정과 경제적 제재를 위한 산정 방식에 차이가 있다"고 설명했다.', 'crawl', '뉴시스', '2026-07-07 12:00:00', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0021353038_web.jpg?rnd=20260707120000', '2026-07-07 06:04:30', '2026-07-07 16:45:09.492875', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3446, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260707_0003698931', 'https://www.newsis.com/view/NISX20260707_0003698931', '경제', '공정위, 전분당 입찰·부산물 담합 심의 착수…과징금 최대 4980억', '[세종=뉴시스]임하은 기자 = 공정거래위원회가 기업간거래(B2B) 시장에서 8년 넘게 전분당 입찰과 부산물 가격을 각각 담합한 의혹에 대한 심의에 착수했다. 관련 매출액에 과징금 상한인 20%를 적용하면 과징금은 최대 4980억원 수준이다. 공정위는 7일 전분당 제조·판매업체들의 입찰 및 부산물 가격 담합 사건에 대한 심사보고서를 전날 위원회에 상정하고 이날부터 심의절차를 개시했다고 밝혔다. 입찰담합 대상은 대상, 사조씨피케이, 삼양사, CJ제일제당 등 4곳이며, 부산물 가격 담합 대상은 대상, 사조씨피케이, 삼양사 등 3곳이다. 전분당은 옥수수 등을 원료로 만드는 당류로, 물엿·올리고당·포도당·과당 등이 이에 해당한다. 부산물은 전분당 가공 과정에서 생산되는 단백피, 글루텐, 배아 등으로, 단백피와 글루텐은 가축용 사료에, 배아는 식용유 원료로 주로 사용된다. 공정위는 해당 업체들이 2016년 9월부터 지난해 6월까지 8년9개월간 포스코 등 7개 실수요처가 발주한 전분당 구매 입찰에서 사전에 낙찰 예정자와 순위, 투찰 가격, 물량 등을 합의했다고 판단했다. 이로 인해 영향을 받은 관련 매출액은 9400억원으로 산정됐다. 또 2017년 8월부터 지난해 10월까지 8년2개월간 전분당 부산물 제품의 판매가격을 매일 담합한 것으로 공정위는 판단했다. 이로 인해 영향을 받은 관련 매출액은 1조5500억원에 달하는 것으로 분석됐다. 공정위는 이번 담합을 ''매우 중대한 위법행위''로 판단했다. 매우 중대한 위법행위의 경우 관련 매출액의 최대 20%까지 과징금을 부과할 수 있다. 오행록 공정위 카르텔조사국장은 "부산물 담합과 입찰담합에는 가격 재결정 명령이 포함되지 않았다"며 "입찰담합은 이미 종료된 입찰에 대해 다시 결정할 가격이 없다는 점을 고려했고, 부산물 담합은 지난해 10월 담합이 종료된 이후 8차례 이상 담합 없이 가격이 독자적으로 결정된 점을 감안했다"고 설명했다. 다만 장기간 담합이 이뤄진 점 등을 고려해 향후 3년간 반기마다 가격 변경 내역을 공정위에 보고하도록 하는 시정명령을 함께 부과할 방침이다. 한편 이날 발표된 전분당 가격담합 사건에 대해 공정위가 담합 사건 역대 최대 규모인 7476억원의 과징금을 부과한 것과 관련해 남동일 공정위 부위원장은 "입찰담합과 부산물 담합이 전분당 가격담합의 가중 사유가 되지는 않는다"며 "비슷한 시기에 중복적으로 이뤄졌지만 관련 매출액이 각각 별도로 산정되기 때문"이라고 설명했다. ◎공감언론 뉴시스 rainy71@newsis.com', '공정위, 전분당 입찰·부산물 담합 심의 착수…과징금 최대 4980억 등록 2026.07.07 12:00:00 수정 2026.07.07 14:34:25 구글에서 선호하는 매체로 추가 작게 크게 전분당 업체 4곳 심사보고서 상정 8년 넘게 입찰·부산물 가격 담합 가격 변경 내역 3년간 반기별 보고 [세종=뉴시스] 배훈식 기자 = 남동일 공정거래위원회 부위원장이 7일 오전 세종시 정부세종청사에서 전분 및 전분당 가격 담합 사건 심의 결과 브리핑을 하고 있다. 2026.07.07. 공정거래위원회가 기업간거래(B2B) 시장에서 8년 넘게 전분당 입찰과 부산물 가격을 각각 담합한 의혹에 대한 심의에 착수했다. 관련 매출액에 과징금 상한인 20%를 적용하면 과징금은 최대 4980억원 수준이다. 공정위는 7일 전분당 제조·판매업체들의 입찰 및 부산물 가격 담합 사건에 대한 심사보고서를 전날 위원회에 상정하고 이날부터 심의절차를 개시했다고 밝혔다. 입찰담합 대상은 대상, 사조씨피케이, 삼양사, CJ제일제당 등 4곳이며, 부산물 가격 담합 대상은 대상, 사조씨피케이, 삼양사 등 3곳이다. 전분당은 옥수수 등을 원료로 만드는 당류로, 물엿·올리고당·포도당·과당 등이 이에 해당한다. 부산물은 전분당 가공 과정에서 생산되는 단백피, 글루텐, 배아 등으로, 단백피와 글루텐은 가축용 사료에, 배아는 식용유 원료로 주로 사용된다. 공정위는 해당 업체들이 2016년 9월부터 지난해 6월까지 8년9개월간 포스코 등 7개 실수요처가 발주한 전분당 구매 입찰에서 사전에 낙찰 예정자와 순위, 투찰 가격, 물량 등을 합의했다고 판단했다. 이로 인해 영향을 받은 관련 매출액은 9400억원으로 산정됐다. 또 2017년 8월부터 지난해 10월까지 8년2개월간 전분당 부산물 제품의 판매가격을 매일 담합한 것으로 공정위는 판단했다. 이로 인해 영향을 받은 관련 매출액은 1조5500억원에 달하는 것으로 분석됐다. 공정위는 이번 담합을 ''매우 중대한 위법행위''로 판단했다. 매우 중대한 위법행위의 경우 관련 매출액의 최대 20%까지 과징금을 부과할 수 있다. 오행록 공정위 카르텔조사국장은 "부산물 담합과 입찰담합에는 가격 재결정 명령이 포함되지 않았다"며 "입찰담합은 이미 종료된 입찰에 대해 다시 결정할 가격이 없다는 점을 고려했고, 부산물 담합은 지난해 10월 담합이 종료된 이후 8차례 이상 담합 없이 가격이 독자적으로 결정된 점을 감안했다"고 설명했다. 다만 장기간 담합이 이뤄진 점 등을 고려해 향후 3년간 반기마다 가격 변경 내역을 공정위에 보고하도록 하는 시정명령을 함께 부과할 방침이다. 한편 이날 발표된 전분당 가격담합 사건에 대해 공정위가 담합 사건 역대 최대 규모인 7476억원의 과징금을 부과한 것과 관련해 남동일 공정위 부위원장은 "입찰담합과 부산물 담합이 전분당 가격담합의 가중 사유가 되지는 않는다"며 "비슷한 시기에 중복적으로 이뤄졌지만 관련 매출액이 각각 별도로 산정되기 때문"이라고 설명했다.', 'crawl', '뉴시스', '2026-07-07 12:00:00', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0021353038_web.jpg?rnd=20260707120000', '2026-07-07 06:04:30', '2026-07-07 16:45:24.374517', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3471, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260707_0003698255', 'https://www.newsis.com/view/NISX20260707_0003698255', '경제', '구윤철 "3대 메가프로젝트 총력전…소득세 차등지원 검토"', '[세종=뉴시스] 안호균 기자 = 구윤철 경제부총리 겸 재정경제부 장관은 7일 정부의 3대 메가프로젝트 지원 방안과 관련, "지방에 근무하는 분들에게는 세금을 차등지원하는 방법까지도 추진해서 총력지원할 것"이라고 밝혔다. 구 부총리는 이날 오전 MBC 라디오 ''김종배의 시선집중''과의 인터뷰에서 "3대 메가프로젝트는 총력전·속도전으로 간다면 대한민국에 엄청난 기회가 될 것"이라며 이같이 밝혔다. 그는 "지방에 근무하다보면 환경이 열악하지 않나. 그런 부분을 감안해 서울의 세금(소득세)보다는 감면을 더 해준다는 것"이라며 "근로자분들의 희망사항을 반영해 검토할 것"이라고 언급했다. 기업에 대한 세제지원에 대해서는 "반도체·인공지능(AI) 쪽은 최고의 세제지원을 해주고 있다"며 "연구개발(R&D) 투자 지원을 해주려고 하고, 이익이 생겨서 지금은 내더라도 나중에 세금을 못내는 시절이 오면 이월공제까지 해주려고 한다"고 전했다. 또 "기업들이 투자를 하는거고 정부는 기업이 투자하는데 필요한 인프라, 인력 공급, 규제 완화, 재정 지원, 세제 지원 그런 부분을 총력 대응해서 지원을 할 계획"이라고 설명했다. 구 부총리는 올해 예상되는 초과세수 규모에 대해 "상반기 영업 실적과 8월 말 법인세 중간예납을 받아봐야 알 수 있겠지만 굉장히 많이 들어올 것 같다"며 FN가이드를 보면 삼성전자, 하이닉스 두 기업만 600조원의 영업이익을 예상하고 있다. 20%만 잡는다고 하더라도 어마어마한 규모"라고 했다. 정부가 초과세수를 활용해 신설하는 ''미래대응기금''에 대해서는 "미래대응기금은 그야말로 미래를 위한 준비에 사용될 것"이라며 "재정 여력을 속도감 있게 쓰는 측면도 있어야 하고, 특정 분야에 쓸 필요도 있다. 내부적으로 검토 중에 있다"고 말했다. ''미래대응기금을 (반도체 클러스터) 전력이나 용수 공급을 위한 재원으로 투입하는가''라는 질문에는 "전력·용수에도 돈이 들어가고 로봇, 피지컬AI, 조선, 항공 등 반도체 이외의 혁신산업들에도 R&D 지원이 필요하면 해야 한다"며 "매년 어마어마한 돈이 들어오기 때문에 미래 성장잠재력을 높이고 대체불가능한 대한민국을 건설하는데 필요한 인프라 지원을 우선적으로 해 줄 것"이라고 강조했다. 이와 함께 구 부총리는 부동산 세제 개편 방향에 대해 "기본적으로 집은 바잉(buying)이 아니고 리빙(living)을 위한 것이라는 원칙 하에서 실거주자 중심의 주택시장이 확립될 수 있도록 하는 차원에서 세제를 보고 있다"고 전했다. 그는 "정부가 일방적으로 결정하기보다는 폭넓게 국민들의 의견을 경청하고 최대한 반영하려고 한다"며 "조만간 부동산 세제 관련해서 국민 의견을 수렴하는 절차를 밟고, 현장의 목소리도 들어서 최종적으로 정부 방침을 결정할 것"이라고 밝혔다. ◎공감언론 뉴시스 ahk@newsis.com', '구윤철 "3대 메가프로젝트 총력전…소득세 차등지원 검토" 등록 2026.07.07 08:51:16 수정 2026.07.07 09:24:24 구글에서 선호하는 매체로 추가 작게 크게 "지방 근무 근로자, 서울보다 소득세 감면 더 해줄것" "(3대 프로젝트 참여 기업은) 어려울때 이월공제까지" "초과세수, 대체불가능한 대한민국 건설에 우선 지원" "실거주 중심 주택시장 확립하는 방향으로 세제 개편" [세종=뉴시스] 구윤철 경제부총리 겸 재정경제부 장관이 6일 서울 중구 웨스틴조선호텔에서 열린 민관합동 ''서비스산업 경쟁력 강화 TF 2차회의''를 주재, 모두발언을 하고 있는 모습. (사진=재경부 제공) 2026.07.06. [email protected] *재판매 및 DB 금지 [세종=뉴시스] 안호균 기자 = 구윤철 경제부총리 겸 재정경제부 장관은 7일 정부의 3대 메가프로젝트 지원 방안과 관련, "지방에 근무하는 분들에게는 세금을 차등지원하는 방법까지도 추진해서 총력지원할 것"이라고 밝혔다. 구 부총리는 이날 오전 MBC 라디오 ''김종배의 시선집중''과의 인터뷰에서 "3대 메가프로젝트는 총력전·속도전으로 간다면 대한민국에 엄청난 기회가 될 것"이라며 이같이 밝혔다. 그는 "지방에 근무하다보면 환경이 열악하지 않나. 그런 부분을 감안해 서울의 세금(소득세)보다는 감면을 더 해준다는 것"이라며 "근로자분들의 희망사항을 반영해 검토할 것"이라고 언급했다. 기업에 대한 세제지원에 대해서는 "반도체·인공지능(AI) 쪽은 최고의 세제지원을 해주고 있다"며 "연구개발(R&D) 투자 지원을 해주려고 하고, 이익이 생겨서 지금은 내더라도 나중에 세금을 못내는 시절이 오면 이월공제까지 해주려고 한다"고 전했다. 또 "기업들이 투자를 하는거고 정부는 기업이 투자하는데 필요한 인프라, 인력 공급, 규제 완화, 재정 지원, 세제 지원 그런 부분을 총력 대응해서 지원을 할 계획"이라고 설명했다. 구 부총리는 올해 예상되는 초과세수 규모에 대해 "상반기 영업 실적과 8월 말 법인세 중간예납을 받아봐야 알 수 있겠지만 굉장히 많이 들어올 것 같다"며 FN가이드를 보면 삼성전자, 하이닉스 두 기업만 600조원의 영업이익을 예상하고 있다. 20%만 잡는다고 하더라도 어마어마한 규모"라고 했다. 정부가 초과세수를 활용해 신설하는 ''미래대응기금''에 대해서는 "미래대응기금은 그야말로 미래를 위한 준비에 사용될 것"이라며 "재정 여력을 속도감 있게 쓰는 측면도 있어야 하고, 특정 분야에 쓸 필요도 있다. 내부적으로 검토 중에 있다"고 말했다. ''미래대응기금을 (반도체 클러스터) 전력이나 용수 공급을 위한 재원으로 투입하는가''라는 질문에는 "전력·용수에도 돈이 들어가고 로봇, 피지컬AI, 조선, 항공 등 반도체 이외의 혁신산업들에도 R&D 지원이 필요하면 해야 한다"며 "매년 어마어마한 돈이 들어오기 때문에 미래 성장잠재력을 높이고 대체불가능한 대한민국을 건설하는데 필요한 인프라 지원을 우선적으로 해 줄 것"이라고 강조했다. 이와 함께 구 부총리는 부동산 세제 개편 방향에 대해 "기본적으로 집은 바잉(buying)이 아니고 리빙(living)을 위한 것이라는 원칙 하에서 실거주자 중심의 주택시장이 확립될 수 있도록 하는 차원에서 세제를 보고 있다"고 전했다. 그는 "정부가 일방적으로 결정하기보다는 폭넓게 국민들의 의견을 경청하고 최대한 반영하려고 한다"며 "조만간 부동산 세제 관련해서 국민 의견을 수렴하는 절차를 밟고, 현장의 목소리도 들어서 최종적으로 정부 방침을 결정할 것"이라고 밝혔다.', 'crawl', '뉴시스', '2026-07-07 08:51:16', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0002178510_web.jpg?rnd=20260706085122', '2026-07-07 06:04:31', '2026-07-07 16:49:15.420193', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3474, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260706_0003697883', 'https://www.newsis.com/view/NISX20260706_0003697883', '경제', '미래대응기금 신설…초과세수 세계잉여금 되기 전에?', '[세종=뉴시스]박광온 기자 = 당정청이 ''미래대응기금''을 신설하기로 한 것은 반도체 호황 등으로 발생한 추가 세수를 세계잉여금으로 넘길 경우 전략산업 투자와 청년·양극화 문제 해소에 기민하게 대응하기 어렵다는 판단 때문이다. 다만 세계잉여금 처리 절차를 거치기 전에 추가세수를 별도 기금으로 관리하는 것이 적절한지는 쟁점으로 남아 있는 상황이다. 전문가들은 전략산업 투자 필요성은 인정하면서도 재정건전성 원칙을 훼손하지 않도록 기금의 규모와 용도, 성과 관리 체계를 분명히 해야 한다고 제언했다. ◆당정청, 미래대응기금 신설 공식화…연내 법 개정 추진 7일 관계부처에 따르면 정부와 청와대, 더불어민주당은 지난 5일 제9차 고위당정협의회를 열고 미래대응기금 신설을 공식화했다. 이 기금은 추가세수를 미래 세대 투자 재원으로 활용하기 위한 목적으로 추진된다. 추가세수를 일회성 재정지출이 아닌 별도 기금으로 관리해 장기 운용이 가능한 투자 재원으로 전환하는 데 초점이 맞춰져 있다. 기금을 통해 마련된 재원은 3대 메가프로젝트 지원을 비롯해 미래 성장 동력 창출, K자형 양극화 대응, 청년 주거·창업·일자리 지원 등에 사용될 예정이다. 다만 아직 기금의 규모와 조성 방식, 운용 주체 등 구체적인 계획은 나오지 않았다. 주무부처인 기획예산처는 연내 미래대응기금 신설을 위한 법 개정에 나설 계획이다. 관계부처 의견 수렴을 거쳐 기금 규모와 세부 사업, 재원 조성 방식, 운용 체계 등을 구체화한다는 방침이다. ◆세계잉여금 넘기면 교육교부금 등 법정 배분 우선…"골든타임 놓칠라" 이처럼 정부가 추가세수를 미래대응기금으로 돌리려는 것은 세수 증가분이 결산 이후 세계잉여금으로 넘어갈 경우 법정 배분 절차에 묶여 정책 재원으로 활용할 여지가 줄어든다는 판단에서다. 일반회계상 추가세수가 연내 미래대응기금이나 추가경정예산(추경) 등으로 활용되지 않으면 결산 과정에서 세출·이월액 등을 뺀 뒤 세계잉여금으로 남게 된다. 현행 국가재정법상 세계잉여금은 ▲지방교부세·지방교육재정교부금 정산 ▲공적자금상환기금 출연 ▲국가채무 상환 순으로 사용된다. 구체적으로 보면 세계잉여금은 우선 지방교부세와 지방교육재정교부금 정산에 쓰인다. 내국세 총액의 19.24%는 지방교부세로, 내국세의 20.79% 및 교육세 일부는 지방교육재정교부금으로 각각 지자체에 교부된다. 이 절차를 거친 뒤 남은 세계잉여금 중 30% 이상은 공적자금상환기금에 출연해야 한다. 공적자금상환기금이란 외환위기 당시 금융기관 구조조정 등에 투입된 공적자금을 갚기 위해 마련된 기금이다. 이후 다시 남은 금액의 30% 이상은 국채나 차입금 원리금 등 국가채무 상환에 써야 한다. 즉 반도체 호황 등에 따른 추가세수를 올해 안에 기금으로 묶거나 추경 등에 사용하지 않을 경우 내년도 세계잉여금으로 넘어가 정부가 전략 투자 재원으로 활용할 수 있는 몫이 줄어들 수 있다는 의미다. 청년 일자리와 양극화 해소, 인공지능(AI)·반도체 등 미래성장동력 확보에 적기 투자가 필요하다는 점에서 추가세수를 결산 이후 법정 배분 절차에 맡기기보다 전략산업 투자 재원으로 먼저 활용해야 한다는 것이 당정청 판단이다. 강훈식 대통령 비서실장이 지난 5일 고위당정협의회 모두발언에서 "대한민국의 미래를 좌우할 절체절명의 시기에 반도체 호황 등으로 발생한 추가 세수를 허투루 써선 안 될 것"이라고 말한 것도 같은 맥락이다. 기획처 관계자도 "추가세수를 세계잉여금으로 넘기면 법정 절차에 따라 사용처가 정해지는 만큼 정부가 필요한 분야에 신속하게 투입하기 어려운 측면이 있다"며 "미래대응기금을 통해 메가 프로젝트와 청년 일자리, 양극화 해소 등 시급한 과제에 재원을 집중하겠다"고 말했다. ◆국가채무 부담 큰데 별도 기금화…재정 원칙 훼손 우려도 다만 국가채무 부담이 큰 상황에서 추가세수를 별도 기금으로 관리하는 방식이 적절한지를 두고 비판도 나온다. 법적으로 정해진 세계잉여금 처리 절차에 따라 국채 상환에 우선 활용해야 하는 것 아니냐는 지적이다. 정부의 ''2025회계연도 국가결산''에 따르면 지난해 국가채무 비율은 전년(46.0%)보다 3.0%포인트(p) 상승한 49.0%로 역대 최고 수준을 기록했다. 국가채무 규모는 1304조5000억원으로 사상 처음 1300조원을 넘어섰다. 황성현 인천대 경제학과 교수는 "초과세수가 발생했다고 해서 이를 곧바로 별도 기금으로 돌리는 것은 재정 운용 원칙 측면에서 신중할 필요가 있다"고 말했다. 황 교수는 "반도체 초과 세수도 결국 경기가 좋아져서 세금이 더 걷히는 것이기 때문에 원칙적으로는 관리재정수지 적자를 줄이고 국채를 상환하는 데 쓰는 것이 맞다"며 "법적으로 정해진 세계잉여금 절차를 우회할 경우 재정 운용의 투명성과 예산 통제 원칙이 약해질 수 있다"고 전했다. 추가세수를 별도 기금으로 관리할 경우 일반회계 예산보다 국회의 심의·통제에서 상대적으로 벗어날 수 있어 재정 운용의 투명성이 떨어질 수 있다는 지적이다. 전략산업 투자가 필요하더라도 기금으로 어떤 사업을 할지, 돈을 얼마나 쓸지, 성과는 어떻게 따질지 기준을 분명히 해야 한다는 제언도 나왔다. 강병구 인하대 경제학과 교수는 "추가세수를 기금화해 전략산업과 디지털·AI 산업 등 필요한 분야에 집중적으로 투입하는 것은 재원의 효율적 관리 측면에서 바람직할 수 있다"며 "다만 미래대응기금이 일반 예산이나 추경과 비슷한 역할을 반복하지 않도록 제도 설계를 촘촘히 해야 한다"고 전했다. 미래대응기금이 반도체 호황으로 늘어난 세수에 기대는 구조라는 점에서 언제까지, 어느 정도 규모로 운용될지도 미지수다. 반도체 경기가 좋을 때는 돈이 들어오지만 업황이 꺾이면 기금에 쌓을 재원도 줄어들 수 있기 때문이다. 이에 기획처는 미래대응기금을 통해 향후 세입 여건 악화에 대응하는 방안도 검토 중인 것으로 알려졌다. 세입이 양호한 시기에는 재원을 일부 축적하고, 세수 결손이 발생할 때는 이를 활용해 재정 운용의 변동성을 줄이겠다는 취지다. 기획처 관계자는 "기금 재원이 언제까지 계속해서 쌓일지는 반도체 사이클과 연결돼 있어 예단하기 어려운 건 맞는다"면서 "추가세수가 향후 잠재성장률 확충을 위한 미래 투자 재원으로 쓰일 수 있도록 제도 설계와 운용 방향 마련에 총력을 기울일 것"이라고 밝혔다. ◎공감언론 뉴시스 lighton@newsis.com', '[세종=뉴시스]박광온 기자 = 당정청이 ''미래대응기금''을 신설하기로 한 것은 반도체 호황 등으로 발생한 추가 세수를 세계잉여금으로 넘길 경우 전략산업 투자와 청년·양극화 문제 해소에 기민하게 대응하기 어렵다는 판단 때문이다. 다만 세계잉여금 처리 절차를 거치기 전에 추가세수를 별도 기금으로 관리하는 것이 적절한지는 쟁점으로 남아 있는 상황이다. 전문가들은 전략산업 투자 필요성은 인정하면서도 재정건전성 원칙을 훼손하지 않도록 기금의 규모와 용도, 성과 관리 체계를 분명히 해야 한다고 제언했다. ◆당정청, 미래대응기금 신설 공식화…연내 법 개정 추진 7일 관계부처에 따르면 정부와 청와대, 더불어민주당은 지난 5일 제9차 고위당정협의회를 열고 미래대응기금 신설을 공식화했다. 이 기금은 추가세수를 미래 세대 투자 재원으로 활용하기 위한 목적으로 추진된다. 추가세수를 일회성 재정지출이 아닌 별도 기금으로 관리해 장기 운용이 가능한 투자 재원으로 전환하는 데 초점이 맞춰져 있다. 기금을 통해 마련된 재원은 3대 메가프로젝트 지원을 비롯해 미래 성장 동력 창출, K자형 양극화 대응, 청년 주거·창업·일자리 지원 등에 사용될 예정이다. 다만 아직 기금의 규모와 조성 방식, 운용 주체 등 구체적인 계획은 나오지 않았다. 주무부처인 기획예산처는 연내 미래대응기금 신설을 위한 법 개정에 나설 계획이다. 관계부처 의견 수렴을 거쳐 기금 규모와 세부 사업, 재원 조성 방식, 운용 체계 등을 구체화한다는 방침이다. ◆세계잉여금 넘기면 교육교부금 등 법정 배분 우선…"골든타임 놓칠라" 이처럼 정부가 추가세수를 미래대응기금으로 돌리려는 것은 세수 증가분이 결산 이후 세계잉여금으로 넘어갈 경우 법정 배분 절차에 묶여 정책 재원으로 활용할 여지가 줄어든다는 판단에서다. 일반회계상 추가세수가 연내 미래대응기금이나 추가경정예산(추경) 등으로 활용되지 않으면 결산 과정에서 세출·이월액 등을 뺀 뒤 세계잉여금으로 남게 된다. 현행 국가재정법상 세계잉여금은 ▲지방교부세·지방교육재정교부금 정산 ▲공적자금상환기금 출연 ▲국가채무 상환 순으로 사용된다. 구체적으로 보면 세계잉여금은 우선 지방교부세와 지방교육재정교부금 정산에 쓰인다. 내국세 총액의 19.24%는 지방교부세로, 내국세의 20.79% 및 교육세 일부는 지방교육재정교부금으로 각각 지자체에 교부된다. 이 절차를 거친 뒤 남은 세계잉여금 중 30% 이상은 공적자금상환기금에 출연해야 한다. 공적자금상환기금이란 외환위기 당시 금융기관 구조조정 등에 투입된 공적자금을 갚기 위해 마련된 기금이다. 이후 다시 남은 금액의 30% 이상은 국채나 차입금 원리금 등 국가채무 상환에 써야 한다. 즉 반도체 호황 등에 따른 추가세수를 올해 안에 기금으로 묶거나 추경 등에 사용하지 않을 경우 내년도 세계잉여금으로 넘어가 정부가 전략 투자 재원으로 활용할 수 있는 몫이 줄어들 수 있다는 의미다. 청년 일자리와 양극화 해소, 인공지능(AI)·반도체 등 미래성장동력 확보에 적기 투자가 필요하다는 점에서 추가세수를 결산 이후 법정 배분 절차에 맡기기보다 전략산업 투자 재원으로 먼저 활용해야 한다는 것이 당정청 판단이다. 강훈식 대통령 비서실장이 지난 5일 고위당정협의회 모두발언에서 "대한민국의 미래를 좌우할 절체절명의 시기에 반도체 호황 등으로 발생한 추가 세수를 허투루 써선 안 될 것"이라고 말한 것도 같은 맥락이다. 기획처 관계자도 "추가세수를 세계잉여금으로 넘기면 법정 절차에 따라 사용처가 정해지는 만큼 정부가 필요한 분야에 신속하게 투입하기 어려운 측면이 있다"며 "미래대응기금을 통해 메가 프로젝트와 청년 일자리, 양극화 해소 등 시급한 과제에 재원을 집중하겠다"고 말했다. ◆국가채무 부담 큰데 별도 기금화…재정 원칙 훼손 우려도 다만 국가채무 부담이 큰 상황에서 추가세수를 별도 기금으로 관리하는 방식이 적절한지를 두고 비판도 나온다. 법적으로 정해진 세계잉여금 처리 절차에 따라 국채 상환에 우선 활용해야 하는 것 아니냐는 지적이다. 정부의 ''2025회계연도 국가결산''에 따르면 지난해 국가채무 비율은 전년(46.0%)보다 3.0%포인트(p) 상승한 49.0%로 역대 최고 수준을 기록했다. 국가채무 규모는 1304조5000억원으로 사상 처음 1300조원을 넘어섰다. 황성현 인천대 경제학과 교수는 "초과세수가 발생했다고 해서 이를 곧바로 별도 기금으로 돌리는 것은 재정 운용 원칙 측면에서 신중할 필요가 있다"고 말했다. 황 교수는 "반도체 초과 세수도 결국 경기가 좋아져서 세금이 더 걷히는 것이기 때문에 원칙적으로는 관리재정수지 적자를 줄이고 국채를 상환하는 데 쓰는 것이 맞다"며 "법적으로 정해진 세계잉여금 절차를 우회할 경우 재정 운용의 투명성과 예산 통제 원칙이 약해질 수 있다"고 전했다. 추가세수를 별도 기금으로 관리할 경우 일반회계 예산보다 국회의 심의·통제에서 상대적으로 벗어날 수 있어 재정 운용의 투명성이 떨어질 수 있다는 지적이다. 전략산업 투자가 필요하더라도 기금으로 어떤 사업을 할지, 돈을 얼마나 쓸지, 성과는 어떻게 따질지 기준을 분명히 해야 한다는 제언도 나왔다. 강병구 인하대 경제학과 교수는 "추가세수를 기금화해 전략산업과 디지털·AI 산업 등 필요한 분야에 집중적으로 투입하는 것은 재원의 효율적 관리 측면에서 바람직할 수 있다"며 "다만 미래대응기금이 일반 예산이나 추경과 비슷한 역할을 반복하지 않도록 제도 설계를 촘촘히 해야 한다"고 전했다. 미래대응기금이 반도체 호황으로 늘어난 세수에 기대는 구조라는 점에서 언제까지, 어느 정도 규모로 운용될지도 미지수다. 반도체 경기가 좋을 때는 돈이 들어오지만 업황이 꺾이면 기금에 쌓을 재원도 줄어들 수 있기 때문이다. 이에 기획처는 미래대응기금을 통해 향후 세입 여건 악화에 대응하는 방안도 검토 중인 것으로 알려졌다. 세입이 양호한 시기에는 재원을 일부 축적하고, 세수 결손이 발생할 때는 이를 활용해 재정 운용의 변동성을 줄이겠다는 취지다. 기획처 관계자는 "기금 재원이 언제까지 계속해서 쌓일지는 반도체 사이클과 연결돼 있어 예단하기 어려운 건 맞는다"면서 "추가세수가 향후 잠재성장률 확충을 위한 미래 투자 재원으로 쓰일 수 있도록 제도 설계와 운용 방향 마련에 총력을 기울일 것"이라고 밝혔다. ◎공감언론 뉴시스 lighton@newsis.com', 'rss', '뉴시스', '2026-07-07 06:30:00', '중도', 'crawl_failed', 'https://image.newsis.com/2025/09/10/NISI20250910_0001940138_web.jpg?rnd=20250910155609', '2026-07-07 06:04:31', '2026-07-07 16:55:45.498215', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3484, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260706_0003697841', 'https://www.newsis.com/view/NISX20260706_0003697841', '경제', '[오늘의 주요일정]해양수산부(7월7일 화요일)', '[서울=뉴시스] ◇장관 ▲10:00 국무회의(서울) ◇차관 ▲통상일정', '삼성전자가 2분기 역대 최대 실적을 달성했지만 주가는 7% 가까이 하락 마감했다. 장중 한때 10% 가까이 급락한 뒤 낙폭을 일부 만회했지만 개인 투자자들의 허탈감은 쉽게 가라앉지 못했다. 7일 한국거래소에 따르면 삼성전자는 전 거래일보다 2만2000원(6.92%) 내린 29만6000원에 거래를 마쳤다. 장중에는 28만6000원까지 밀리며 10% 정치 여 "정통망법, 허위정보 방지" 야 "입틀막법" 국제 NATO 가는 트럼프…유럽, ''돌발 변수'' 촉각 경제 전분·전분당 담합 7476억 역대 최대 제재 금융 코스피, 8%대 급락에 서킷브레이커 발동 산업 쌍둥이 판다 ''루이바오·후이바오'' 세 돌…국내서 마지막 생일잔치 IT·바이오 첫 농림위성 차세대중형위성 4호, 우주 발사 사회 장윤기 증거인멸…''檢보완수사권 폐지'' 회의론 문화 조성진 "기술보다 중요한 건 음악을 대하는 태도" 스포츠 고우석 ''빅리그 데뷔'' 임박 미네소타, 로스터 정리 끝 연예 김현지PD, 원이 저격 역풍 MBC 게시판에 항의 빗발 많이 본 기사 종합 정치 국제 경제 금융 산업 IT·바이오 사회 수도권 지방 문화 스포츠 연예 김보성, 주식으로 ''강남 집 두 채'' 날렸다 "안 팔았으면 500억" 고두심, 33살 연하 지현우와 키스신 비화…"사랑스럽더라" 대신증권 "SK하이닉스, ADR 상장 임박…목표가 390만원↑" 광주 반도체팹 속도전, 관건은 군부대 이전…빨리 어떻게 "독도는 한국의 일부"…미군 당국 공식 보고서 첫 공개 "할아버지처럼 어슬렁"…호날두, 비판받으며 마지막 월드컵 마무리 닉쿤 "후덕한 모습에 충격…하루 계란 3개 먹고 감량" 손담비, ''민폐 논란'' 결국 사과…"제 부주의" 박지원 "조국, 사투리를 가지고 일베라고…외로운 것 같다" ''계엄령 놀이'' 갑질·2천만원 수수…비위 공무원 30명 적발 이 대통령, 튀르키예로 출국…닷새 간 나토·몽골 순방 정통망법 개정안 시행 논란…與 "공론장 방어벽" 野 "국민 입틀막법" 정치(7월7일 화요일) 與 "당대표 당선자, 선호투표제로 결정" 이 대통령, 오늘부터 닷새간 나토·몽골 순방…방산·공급망 협력 강화 與, 8월 전당대회서 청년최고위원제 도입 60조 잠수함, 왜 한화오션 아닌 독일 택했나…외신이 본 캐나다의 선택 SK하이닉스, 나스닥 상장에 큰손 몰린다…오픈AI 출신 펀드도 ''베팅'' 모건스탠리 "AI 투자자금, 반도체서 초대형 기술기업으로 이동" 이란, 하메네이 장례 중 상선 2척에 미사일 발사…호르무즈 긴장↑ 이 대통령, 튀르키예로 출국…닷새 간 나토·몽골 순방 "세계서 가장 뜨거운 韓 증시, ''오징어 게임'' 될 위험 처해" 美 WSJ 뉴욕 증시, 반도체주 강세에 상승 마감···나스닥 1.12%↑ 스페인 폭염으로 7월에만 사망자 150여 명 발생 SK하이닉스, 나스닥 상장에 큰손 몰린다…오픈AI 출신 펀드도 ''베팅'' 모건스탠리 "AI 투자자금, 반도체서 초대형 기술기업으로 이동" 아파트 공급난에 빌라·연립으로…비아파트 거래 16% 늘어 최저임금 격차 ''1290원'' 좁혀지나…12번째 심의 돌입 "부동산 불패는 끝났다"…31년