INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3491, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260706_0003698038', 'https://www.newsis.com/view/NISX20260706_0003698038', '경제', '홈플러스 반발에 삼성카드 대금 지급 재개…현대는 포인트만 일부 중단(종합)', '[서울=뉴시스]동효정 기자 = 홈플러스가 현대카드와 삼성카드의 가맹점 대금 지급 보류 조치가 부당하다며 철회를 촉구한 가운데 삼성카드는 지급을 재개한 것으로 확인됐다. 현대카드는 포인트 사용만 일부 제한될뿐 대금 지급을 중단한 적이 없다고 해명했다. 6일 홈플러스에 따르면 회사는 서울회생법원의 회생절차 폐지 결정 이후 현대카드와 삼성카드로부터 ''홈플러스 온라인몰 포인트 제휴 계약 종료''와 함께 온·오프라인 미수금 및 매출 취소분 처리를 위한 오프라인 가맹점 대금 지급 보류 및 상계 시행 관련 공문을 받았다. 홈플러스는 법원의 회생절차 폐지 결정은 즉시 효력이 발생하는 것이 아니라 공고일로부터 14일간 즉시항고가 가능한 만큼 현재도 회생절차가 유지되고 있다는 입장이다. 이에 따라 카드사들이 회생절차 폐지를 근거로 온라인몰 포인트 제휴 계약 종료와 대금 지급 보류를 통보한 것은 법적 근거가 부족하다고 주장했다. 홈플러스는 "오프라인에서는 외상 구매가 불가능하고 온라인도 영업 중단으로 주문 취소가 불가능한 상황"이라며 "미수금과 매출 취소분 처리를 이유로 오프라인 가맹점 대금 지급을 보류하는 것은 납득하기 어렵다"고 밝혔다. 또 "카드사의 대금 지급 보류가 계속되면 카드 매출대금을 회수할 수 없어 정상적인 영업을 이어가기 어렵다"며 "회생을 위해 노력하는 상황에서 근거 없는 조치로 경영 정상화에 차질을 줘서는 안 된다"고 강조했다. 홈플러스의 철회 촉구 이후 카드사들은 지급 보류 여부와 관련한 입장을 밝혔다. 현대카드는 "홈플러스 온라인몰 M포인트 사용 관련 일부 제휴 서비스만 중단했을 뿐 가맹점 대금 지급을 중단한 사실은 없다"고 밝혔다. 홈플러스 관계자는 "아직 삼성카드로부터 공식 통보를 받은 것은 아니지만 삼성카드의 경우 지급 보류 조치를 철회하고 대금 지급을 재개한 것으로 확인했다"고 전했다. 업계에서는 홈플러스의 회생절차를 둘러싼 불확실성이 이어지는 가운데 카드사들도 법적 절차와 리스크를 고려해 대응 수위를 조정하는 모습이라는 분석이 나온다. 한편 서울회생법원은 지난 3일 홈플러스의 회생절차를 폐지하기로 결정했다. 홈플러스는 공고일로부터 14일 이내 즉시항고가 가능하다. 이 기간 운영자금을 조달해 항고하고 법원이 정당한 사유가 있다고 판단할 경우 회생절차 폐지 결정이 취소되고 관계인집회가 다시 열릴 수 있다. ◎공감언론 뉴시스 vivid@newsis.com', '홈플러스 반발에 삼성카드 대금 지급 재개…현대는 포인트만 일부 중단(종합) 등록 2026.07.06 20:56:22 구글에서 선호하는 매체로 추가 작게 크게 홈플러스, 회생절차 유지 근거로 카드사 조치 부당 주장 현대카드 "포인트 관련 일부만…대금 지급 중단 없어" [서울=뉴시스] 황준선 기자 = 법원이 운영자금을 확보하지 못한 홈플러스의 회생절차를 폐지한 3일 서울 강서구 홈플러스 본사의 모습. 서울회생법원 회생4부(법원장 정준영, 주심 부장판사 박소영)는 이날 홈플러스의 기업회생절차(법정관리) 폐지를 결정했다. 법원은 "즉시항고 기간 내 운영자금을 조달한 뒤 항고할 경우 정당한 이유가 인정되면 ''재도의 고안'' 절차를 통해 폐지 결정을 취소하고 회생계획안 심리를 위한 관계인집회를 다시 지정할 가능성이 있다"고 설명했다. 홈플러스는 인수자를 찾지 못하는 이상 파산 수순을 밟게 된다. 2026.07.03. [email protected] [서울=뉴시스]동효정 기자 = 홈플러스가 현대카드와 삼성카드의 가맹점 대금 지급 보류 조치가 부당하다며 철회를 촉구한 가운데 삼성카드는 지급을 재개한 것으로 확인됐다. 현대카드는 포인트 사용만 일부 제한될뿐 대금 지급을 중단한 적이 없다고 해명했다. 6일 홈플러스에 따르면 회사는 서울회생법원의 회생절차 폐지 결정 이후 현대카드와 삼성카드로부터 ''홈플러스 온라인몰 포인트 제휴 계약 종료''와 함께 온·오프라인 미수금 및 매출 취소분 처리를 위한 오프라인 가맹점 대금 지급 보류 및 상계 시행 관련 공문을 받았다. 홈플러스는 법원의 회생절차 폐지 결정은 즉시 효력이 발생하는 것이 아니라 공고일로부터 14일간 즉시항고가 가능한 만큼 현재도 회생절차가 유지되고 있다는 입장이다. 이에 따라 카드사들이 회생절차 폐지를 근거로 온라인몰 포인트 제휴 계약 종료와 대금 지급 보류를 통보한 것은 법적 근거가 부족하다고 주장했다. 홈플러스는 "오프라인에서는 외상 구매가 불가능하고 온라인도 영업 중단으로 주문 취소가 불가능한 상황"이라며 "미수금과 매출 취소분 처리를 이유로 오프라인 가맹점 대금 지급을 보류하는 것은 납득하기 어렵다"고 밝혔다. 또 "카드사의 대금 지급 보류가 계속되면 카드 매출대금을 회수할 수 없어 정상적인 영업을 이어가기 어렵다"며 "회생을 위해 노력하는 상황에서 근거 없는 조치로 경영 정상화에 차질을 줘서는 안 된다"고 강조했다. 홈플러스의 철회 촉구 이후 카드사들은 지급 보류 여부와 관련한 입장을 밝혔다. 현대카드는 "홈플러스 온라인몰 M포인트 사용 관련 일부 제휴 서비스만 중단했을 뿐 가맹점 대금 지급을 중단한 사실은 없다"고 밝혔다. 홈플러스 관계자는 "아직 삼성카드로부터 공식 통보를 받은 것은 아니지만 삼성카드의 경우 지급 보류 조치를 철회하고 대금 지급을 재개한 것으로 확인했다"고 전했다. 업계에서는 홈플러스의 회생절차를 둘러싼 불확실성이 이어지는 가운데 카드사들도 법적 절차와 리스크를 고려해 대응 수위를 조정하는 모습이라는 분석이 나온다. 한편 서울회생법원은 지난 3일 홈플러스의 회생절차를 폐지하기로 결정했다. 홈플러스는 공고일로부터 14일 이내 즉시항고가 가능하다. 이 기간 운영자금을 조달해 항고하고 법원이 정당한 사유가 있다고 판단할 경우 회생절차 폐지 결정이 취소되고 관계인집회가 다시 열릴 수 있다.', 'crawl', '뉴시스', '2026-07-06 20:56:22', '중도', 'ready', 'https://img1.newsis.com/2026/07/03/NISI20260703_0021348919_web.jpg?rnd=20260703135237', '2026-07-07 06:04:31', '2026-07-07 17:05:15.37944', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3493, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260706_0003697971', 'https://www.newsis.com/view/NISX20260706_0003697971', '경제', 'SK하이닉스의 나스닥 상장, 외국기업 최대의 최초 주식매각', '[서울=뉴시스] 유세진 기자 = 이번주 290억 달러(44조4570억원) 규모의 SK하이닉스 미국 증시 상장은 외국 기업 최대의 최초 주식 매각이 될 수 있지만, 단순히 현금을 조달하는 것만은 아니라 인공지능(AI) 컴퓨팅에 사용되는 메모리칩인 글로벌 주식시장의 가장 뜨거운 구석에서 경쟁하는 것이기도 하다고 포춘이 5일(현지시각) 보도했다. SK하이닉스는 미국에 본사를 둔 주요 라이벌인 마이크론 테크놀로지에 할인된 가격으로 거래해 왔지만, AI 데이터센터에 사용되는 메모리칩 및 기타 장비를 만드는 회사들이 S&P 500 지수의 실적을 주도하는 상황에서 미국 시장에 진출함으로써 이러한 할인 관행을 변화시킬 것을 기대하고 있다. 마이크론 주식을 소유한 시노버스 트러스트의 수석 포트폴리오 매니저 다니엘 모건은 "칩 주식에 대한 열정이 극도로 뜨거운 시기인 지금은 미국 시장에 진출하기 좋은 때"라고 말했다. SK하이닉스에 베팅하는 것은 대부분의 미국 투자자들에게 불가능하지는 않더라도 어려운 일이었다. 올해 S&P 500 지수에서 242%의 큰 폭의 상승률로 두 번째로 높은 실적을 기록한 마이크론과 마찬가지로 고대역폭 메모리칩에 대한 수요 급증의 혜택을 누리고 있지만 SK하이닉스의 한국 상장 주식을 소유하려면 미국에서 시간외 거래에 의존해야 했다. 스폰서가 없는 미국 예탁증권(ADR)을 장외에서 매수하는 것은 가능했지만 스폰서가 없는 ADR은 SK하이닉스의 한국 주식보다 실적이 저조할 뿐만 아니라 유동성도 심각하게 제한돼 거래가 어려운 상황이었다. 10일로 예상되는 SK하이닉스의 나스닥 상장은 이를 바꾸고 회사의 저평가를 개선할 것으로 기대된다. SK하이닉스는 현재 향후 12개월 간 예상 실적의 6.2배에 거래되고 있다. 마이크론은 지난주 주가가 14% 하락해 3월 이후 최악의 실적을 기록한 후 현재 7배에 달하지만, 6월22일까지만 해도 11배를 넘어섰었다. SK하이닉스 주식을 보유한 손버그 인베스트먼트 매니지먼트의 포트폴리오 매니저 디 저우는 "이번 공모는 현재 한국 주식시장에 접근할 수 없는 투자자들을 대상으로 한다"며 "SK하이닉스의 나스닥 상장은 AI 메모리 사이클에서 가장 매력적인 순수 플레이 중 하나에 직접적이고 마찰 없이 노출될 수 있는 기회를 제공해준다"고 말했다. 지난 12개월 동안 SK하이닉스의 한국 상장 주식과 마이크론의 주식은 약 700% 상승하며 두 회사의 시가총액이 1조 달러(1532조6000억원)를 넘어섰다. 메모리 및 스토리지 기업들 사이에서는 이러한 랠리가 드물지 않은 일이다. 샌디스크는 3676% 급등하며 S&P 500 지수를 이끌고 있으며, 웨스턴디지털은 719%, 씨게이트 테크놀로지 홀딩스는 449% 상승했다. 필라델피아 증권거래소 반도체 지수는 지난 12개월 동안 125% 상승하며 역대 최고의 분기를 보내고 있다. 하지만 투자자들은 좋은 시기가 얼마나 더 오래 지속될 수 있을지에 대해 점점 더 불안해하고 있다. 알파벳과 마이크로소프트(MS)를 비롯한 메모리 수요의 대부분을 주도하는 거대 기술기업들은 최근까지 현금으로 충당했던 지출 자금 조달을 위해 부채와 주식시장으로 눈을 돌리고 있다. 이러한 자본 지출로 인해 메모리칩 제조업체의 수익이 급증하고 있지만 이러한 투자가 중단되면 전체 상황이 바뀔 수 있다. 리버 웰스 어드바이저의 최고경영자(CEO) 에드 오고먼은 "투자자들은 잠재적으로 투기성 거품에 빠질 위험이 있다"면서 "이처럼 주가가 급등한 기업에 투자하는 것은 매우 신중해야 한다"고 말했다. 그럼에도 불구, SK하이닉스의 ADR은 AI 지출의 최대 수혜자에 베팅할 수 있는 더 많은 방법을 찾는 많은 미국 투자자들에게 분명 매력적일 것이다. 마이크론 주식을 소유한 보케 캐피털 파트너스의 최고투자책임자(CIO) 겸 설립자인 킴 포레스트는 "이 분야에는 아무 것도 소유하지 않은 사람들이 많기 때문에 아직 매입하지 않은 사람들이 시장에 나올 수 있다"고 말했다. ◎공감언론 뉴시스 dbtpwls@newsis.com', 'SK하이닉스의 나스닥 상장, 외국기업 최대의 최초 주식매각 등록 2026.07.06 18:58:23 수정 2026.07.06 19:40:24 구글에서 선호하는 매체로 추가 작게 크게 AI 메모리칩 가장 뜨거운 주식시장에서 경쟁 시작 10일 사장 예상…44조4570억원 규모 이미 급등한 주식에 투자는 위험할 수 있지만 매력적일 수 있어 [이천=뉴시스] 김종택 기자 =이번주 290억 달러(44조4570억원) 규모의 SK하이닉스 미국 증시 상장은 외국 기업 최대의 최초 주식 매각이 될 수 있지만, 단순히 현금을 조달하는 것만은 아니라 인공지능(AI) 컴퓨팅에 사용되는 메모리칩인 글로벌 주식시장의 가장 뜨거운 구석에서 경쟁하는 것이기도 하다고 포춘이 5일(현지시각) 보도했다. SK하이닉스는 미국에 본사를 둔 주요 라이벌인 마이크론 테크놀로지에 할인된 가격으로 거래해 왔지만, AI 데이터센터에 사용되는 메모리칩 및 기타 장비를 만드는 회사들이 S&P 500 지수의 실적을 주도하는 상황에서 미국 시장에 진출함으로써 이러한 할인 관행을 변화시킬 것을 기대하고 있다. 마이크론 주식을 소유한 시노버스 트러스트의 수석 포트폴리오 매니저 다니엘 모건은 "칩 주식에 대한 열정이 극도로 뜨거운 시기인 지금은 미국 시장에 진출하기 좋은 때"라고 말했다. SK하이닉스에 베팅하는 것은 대부분의 미국 투자자들에게 불가능하지는 않더라도 어려운 일이었다. 올해 S&P 500 지수에서 242%의 큰 폭의 상승률로 두 번째로 높은 실적을 기록한 마이크론과 마찬가지로 고대역폭 메모리칩에 대한 수요 급증의 혜택을 누리고 있지만 SK하이닉스의 한국 상장 주식을 소유하려면 미국에서 시간외 거래에 의존해야 했다. 스폰서가 없는 미국 예탁증권(ADR)을 장외에서 매수하는 것은 가능했지만 스폰서가 없는 ADR은 SK하이닉스의 한국 주식보다 실적이 저조할 뿐만 아니라 유동성도 심각하게 제한돼 거래가 어려운 상황이었다. 10일로 예상되는 SK하이닉스의 나스닥 상장은 이를 바꾸고 회사의 저평가를 개선할 것으로 기대된다. SK하이닉스는 현재 향후 12개월 간 예상 실적의 6.2배에 거래되고 있다. 마이크론은 지난주 주가가 14% 하락해 3월 이후 최악의 실적을 기록한 후 현재 7배에 달하지만, 6월22일까지만 해도 11배를 넘어섰었다. SK하이닉스 주식을 보유한 손버그 인베스트먼트 매니지먼트의 포트폴리오 매니저 디 저우는 "이번 공모는 현재 한국 주식시장에 접근할 수 없는 투자자들을 대상으로 한다"며 "SK하이닉스의 나스닥 상장은 AI 메모리 사이클에서 가장 매력적인 순수 플레이 중 하나에 직접적이고 마찰 없이 노출될 수 있는 기회를 제공해준다"고 말했다. 지난 12개월 동안 SK하이닉스의 한국 상장 주식과 마이크론의 주식은 약 700% 상승하며 두 회사의 시가총액이 1조 달러(1532조6000억원)를 넘어섰다. 메모리 및 스토리지 기업들 사이에서는 이러한 랠리가 드물지 않은 일이다. 샌디스크는 3676% 급등하며 S&P 500 지수를 이끌고 있으며, 웨스턴디지털은 719%, 씨게이트 테크놀로지 홀딩스는 449% 상승했다. 필라델피아 증권거래소 반도체 지수는 지난 12개월 동안 125% 상승하며 역대 최고의 분기를 보내고 있다. 하지만 투자자들은 좋은 시기가 얼마나 더 오래 지속될 수 있을지에 대해 점점 더 불안해하고 있다. 알파벳과 마이크로소프트(MS)를 비롯한 메모리 수요의 대부분을 주도하는 거대 기술기업들은 최근까지 현금으로 충당했던 지출 자금 조달을 위해 부채와 주식시장으로 눈을 돌리고 있다. 이러한 자본 지출로 인해 메모리칩 제조업체의 수익이 급증하고 있지만 이러한 투자가 중단되면 전체 상황이 바뀔 수 있다. 리버 웰스 어드바이저의 최고경영자(CEO) 에드 오고먼은 "투자자들은 잠재적으로 투기성 거품에 빠질 위험이 있다"면서 "이처럼 주가가 급등한 기업에 투자하는 것은 매우 신중해야 한다"고 말했다. 그럼에도 불구, SK하이닉스의 ADR은 AI 지출의 최대 수혜자에 베팅할 수 있는 더 많은 방법을 찾는 많은 미국 투자자들에게 분명 매력적일 것이다. 마이크론 주식을 소유한 보케 캐피털 파트너스의 최고투자책임자(CIO) 겸 설립자인 킴 포레스트는 "이 분야에는 아무 것도 소유하지 않은 사람들이 많기 때문에 아직 매입하지 않은 사람들이 시장에 나올 수 있다"고 말했다.', 'crawl', '뉴시스', '2026-07-06 18:58:23', '중도', 'ready', 'https://img1.newsis.com/2025/10/29/NISI20251029_0021034888_web.jpg?rnd=20251029134215', '2026-07-07 06:04:31', '2026-07-07 17:05:40.777148', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3494, 'https://www.newsis.com/RSS/economy.xml', 'https://www.newsis.com/view/NISX20260706_0003697942', 'https://www.newsis.com/view/NISX20260706_0003697942', '경제', '[인사]기획예산처', '[세종=뉴시스] ◇국장급 ▲장관정책보좌관 박영선', '삼성전자가 2분기 역대 최대 실적을 달성했지만 주가는 7% 가까이 하락 마감했다. 장중 한때 10% 가까이 급락한 뒤 낙폭을 일부 만회했지만 개인 투자자들의 허탈감은 쉽게 가라앉지 못했다. 7일 한국거래소에 따르면 삼성전자는 전 거래일보다 2만2000원(6.92%) 내린 29만6000원에 거래를 마쳤다. 장중에는 28만6000원까지 밀리며 10% 정치 여 "정통망법, 허위정보 방지" 야 "입틀막법" 국제 NATO 가는 트럼프…유럽, ''돌발 변수'' 촉각 경제 구윤철 "단일종목 레버리지 ETF 보완 협의중" 금융 코스피, 8%대 급락에 서킷브레이커 발동 산업 쌍둥이 판다 ''루이바오·후이바오'' 세 돌…국내서 마지막 생일잔치 IT·바이오 첫 농림위성 차세대중형위성 4호, 우주 발사 사회 장윤기 증거인멸…''檢보완수사권 폐지'' 회의론 문화 조성진 "기술보다 중요한 건 음악을 대하는 태도" 스포츠 고우석 ''빅리그 데뷔'' 임박 미네소타, 로스터 정리 끝 연예 김현지PD, 원이 저격 역풍 MBC 게시판에 항의 빗발 많이 본 기사 종합 정치 국제 경제 금융 산업 IT·바이오 사회 수도권 지방 문화 스포츠 연예 김보성, 주식으로 ''강남 집 두 채'' 날렸다 "안 팔았으면 500억" 대신증권 "SK하이닉스, ADR 상장 임박…목표가 390만원↑" 광주 반도체팹 속도전, 관건은 군부대 이전…빨리 어떻게 "독도는 한국의 일부"…미군 당국 공식 보고서 첫 공개 "할아버지처럼 어슬렁"…호날두, 비판받으며 마지막 월드컵 마무리 닉쿤 "후덕한 모습에 충격…하루 계란 3개 먹고 감량" 손담비, ''민폐 논란'' 결국 사과…"제 부주의" ''광주軍공항 삼전닉스 반도체 단지'' 확정에…금호타이어 공장 매각 탄력받나 박지원 "조국, 사투리를 가지고 일베라고…외로운 것 같다" ''계엄령 놀이'' 갑질·2천만원 수수…비위 공무원 30명 적발 이 대통령, 튀르키예로 출국…닷새 간 나토·몽골 순방 與 "당대표 당선자, 선호투표제로 결정" 與, 8월 전당대회서 청년최고위원제 도입 이 대통령, 튀르키예로 출국…닷새 간 나토·몽골 순방 한병도 "올림픽공원 투표지 247만장, 재검표·수개표 추진 방안 적극 검토" 구윤철 "단일종목 레버리지 ETF, 문제점 보완 방안 협의 중" 60조 잠수함, 왜 한화오션 아닌 독일 택했나…외신이 본 캐나다의 선택 SK하이닉스, 나스닥 상장에 큰손 몰린다…오픈AI 출신 펀드도 ''베팅'' 모건스탠리 "AI 투자자금, 반도체서 초대형 기술기업으로 이동" 이란, 하메네이 장례 중 상선 2척에 미사일 발사…호르무즈 긴장↑ 이 대통령, 튀르키예로 출국…닷새 간 나토·몽골 순방 "세계서 가장 뜨거운 韓 증시, ''오징어 게임'' 될 위험 처해" 美 WSJ 뉴욕 증시, 반도체주 강세에 상승 마감···나스닥 1.12%↑ 스페인 폭염으로 7월에만 사망자 150여 명 발생 SK하이닉스, 나스닥 상장에 큰손 몰린다…오픈AI 출신 펀드도 ''베팅'' 모건스탠리 "AI 투자자금, 반도체서 초대형 기술기업으로 이동" 최저임금 격차 ''1290원'' 좁혀지나…12번째 심의 돌입 "부동산 불패는 끝났다"…31년 전문가가 본 한국 주택 시장의 균열 뉴욕 증시, 반