INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3507, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003699184', 'https://www.newsis.com/view/NISX20260707_0003699184', '사회', '''5·18 조롱'' 배재고, 9일부터 역사교육…"재심 신청은 논의"', '[서울=뉴시스]정예빈 기자 = 전국 고교야구 대회 도중 광주제일고등학교를 향해 "스타벅스 가야지"라는 조롱성 응원 구호를 외쳐 논란을 빚은 배재고등학교가 오는 9일부터 역사·인권교육과 차별·혐오 표현 방지교육을 받는다. 서울시교육청은 7일 배재고 전체 학생을 대상으로 이달 9일부터 여름방학 전까지 역사·인권교육, 차별·혐오 표현 방지교육을 실시한다고 밝혔다. 시교육청 민주시민교육과에서 전문 인력을 파견해 교육을 진행한다. 대한야구소프트볼협회(KBSA)의 전국대회 출전정지 6개월 징계에 대한 재심 신청 여부는 아직 논의 중이다. 재심 신청 기한은 오는 8일까지고, 신청 접수 이후 재심의까지 최소 2개월 이상 소요될 전망이다. 배재고가 광주일고에 학교발전기금을 전달했다는 주장에 관해서는 "학교에 확인한 결과 사실이 아니다"고 선을 그었다. 앞서 지난달 서울 목동구장에서 열린 ''제81회 청룡기 전국고교야구선수권대회 겸 주말리그 왕중왕전''에서 배재고 일부 학생 선수들은 상대 팀인 광주일고 더그아웃을 향해 "가야지, 가야지, 스타벅스 가야지"라는 구호를 반복해 외쳤다. 해당 구호는 스타벅스 코리아의 이른바 ''5·18 탱크데이'' 이벤트 논란을 연상시키는 조롱성 발언으로 해석되며 지역 비하라는 비판을 받았다. 시교육청은 지난달 30일부터 8월 21일까지 전체 학교운동부를 방문해 혐오·차별 표현 금지 교육 실시 현황, 스포츠 인권 교육 시행 여부, 학습권 보장 대책, 학교폭력사안 발생 및 조치 사항 등을 점검한다. 학교체육진흥회와는 학생선수 대상 혐오·차별적 표현 금지 및 건전한 응원 문화 조성 관련 교육자료를 개발 및 보급하는 것을 협의 중이다. 한편 전날 오후 배재고 교직원·야구부 학생 선수·학부모 등 86명은 광주일고에 방문해 직접 사과하고 국립 5·18민주묘지를 참배했다. ◎공감언론 뉴시스 5757@newsis.com', '배재고, 이달 9일부터 여름방학 전까지 교육 시교육청 민주시민교육과서 전문 인력 파견 6개월 출전정지 징계 재심 신청은 내일까지 [전남광주=뉴시스] 이영주 기자 = 이효준 서울 배재고등학교 교장과 야구부 학생 등이 6일 오후 전남광주통합특별시 북구 광주제일고등학교를 찾아 ''스벅 가자'' 사태에 대한 사과를 하고 있다. 2026.07.06. [서울=뉴시스]정예빈 기자 = 전국 고교야구 대회 도중 광주제일고등학교를 향해 "스타벅스 가야지"라는 조롱성 응원 구호를 외쳐 논란을 빚은 배재고등학교가 오는 9일부터 역사·인권교육과 차별·혐오 표현 방지교육을 받는다. 서울시교육청은 7일 배재고 전체 학생을 대상으로 이달 9일부터 여름방학 전까지 역사·인권교육, 차별·혐오 표현 방지교육을 실시한다고 밝혔다. 시교육청 민주시민교육과에서 전문 인력을 파견해 교육을 진행한다. 대한야구소프트볼협회(KBSA)의 전국대회 출전정지 6개월 징계에 대한 재심 신청 여부는 아직 논의 중이다. 재심 신청 기한은 오는 8일까지고, 신청 접수 이후 재심의까지 최소 2개월 이상 소요될 전망이다. 배재고가 광주일고에 학교발전기금을 전달했다는 주장에 관해서는 "학교에 확인한 결과 사실이 아니다"고 선을 그었다. 앞서 지난달 서울 목동구장에서 열린 ''제81회 청룡기 전국고교야구선수권대회 겸 주말리그 왕중왕전''에서 배재고 일부 학생 선수들은 상대 팀인 광주일고 더그아웃을 향해 "가야지, 가야지, 스타벅스 가야지"라는 구호를 반복해 외쳤다. 해당 구호는 스타벅스 코리아의 이른바 ''5·18 탱크데이'' 이벤트 논란을 연상시키는 조롱성 발언으로 해석되며 지역 비하라는 비판을 받았다. 시교육청은 지난달 30일부터 8월 21일까지 전체 학교운동부를 방문해 혐오·차별 표현 금지 교육 실시 현황, 스포츠 인권 교육 시행 여부, 학습권 보장 대책, 학교폭력사안 발생 및 조치 사항 등을 점검한다. 학교체육진흥회와는 학생선수 대상 혐오·차별적 표현 금지 및 건전한 응원 문화 조성 관련 교육자료를 개발 및 보급하는 것을 협의 중이다. 한편 전날 오후 배재고 교직원·야구부 학생 선수·학부모 등 86명은 광주일고에 방문해 직접 사과하고 국립 5·18민주묘지를 참배했다.', 'crawl', '뉴시스', '2026-07-07 14:43:09', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0021352275_web.jpg?rnd=20260706155411', '2026-07-07 06:04:33', '2026-07-07 17:08:10.116162', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3517, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003699060', 'https://www.newsis.com/view/NISX20260707_0003699060', '사회', '노동부, ''홈플러스 사태'' 전담 TF 가동…임금체불 조사', '[세종=뉴시스]박정영 기자 = 최근 홈플러스의 기업회생절차가 폐지되면서 파산 가능성이 높아진 가운데, 고용노동부가 임금체불과 관련된 태스크포스(TF)를 통해 대응하고 있다. 7일 노동부에 따르면 노동부 서울남부지청은 올해 2월 초 ''홈플러스 사태 임금체불 TF''를 구성했다. 이후 올해 3~5월 발생한 임금체불에 대한 전수조사를 거쳐 청산을 지도했으며, 임금을 체불한 사측을 형사입건 조치했다. 홈플러스 일반노조 관계자는 "3월 체불 임금은 4월에 받았고, 4~5월에 지급되지 않은 임금은 6월 말에 받았다"고 설명했다. 노동부 관계자는 "3~5월 임금체불 관련해서는 시정이 완료됐고, 6월 미지급된 임금에 대한 조사는 아직 진행하고 있다"고 밝혔다. 홈플러스의 월급 지급일은 매달 21일이지만, 6월분 임금은 아직 지급되지 않은 것으로 알려졌다. 노동부는 퇴직에 따른 체불 가능성도 고려 중이다. 홈플러스 본사는 최근 퇴직자들에게 "현재 회사의 자금 부족으로 인해 금일 지급 예정이었던 ''퇴직급여 및 퇴직금 회사 지급 분''의 지급이 부득이하게 지연되게 됐다"고 공지한 상태다. 앞서 지난 3일 서울회생법원 회생4부(법원장 정준영)는 홈플러스의 기업회생절차 폐지를 결정했다. 법원은 제출된 수정 회생계획안의 수행 가능성이 낮다고 판단한 것으로 밝혀졌다. 다만 홈플러스가 회생절차 폐지 결정 후 14일 이내 운영자금을 조달해 항고할 경우, 정당한 이유가 인정되면 폐지 결정은 취소될 수 있다. 만약 항고를 제기하지 않을 시에는 폐지 결정이 확정된다. ◎공감언론 뉴시스 us06037@newsis.com', '노동부, ''홈플러스 사태'' 전담 TF 가동…임금체불 조사 등록 2026.07.07 13:48:53 수정 2026.07.07 15:40:23 구글에서 선호하는 매체로 추가 작게 크게 3~5월 체불 조치 완료…6월 임금 미지급분은 조사 중 [서울=뉴시스] 김금보 기자 = 지난 5일 서울 송파구 홈플러스 잠실점에 임시휴업 안내문이 붙어있다. 법원은 지난 3일 운영자금을 확보하지 못한 홈플러스의 회생절차를 폐지했다. 2026.07.05. [세종=뉴시스]박정영 기자 = 최근 홈플러스의 기업회생절차가 폐지되면서 파산 가능성이 높아진 가운데, 고용노동부가 임금체불과 관련된 태스크포스(TF)를 통해 대응하고 있다. 7일 노동부에 따르면 노동부 서울남부지청은 올해 2월 초 ''홈플러스 사태 임금체불 TF''를 구성했다. 이후 올해 3~5월 발생한 임금체불에 대한 전수조사를 거쳐 청산을 지도했으며, 임금을 체불한 사측을 형사입건 조치했다. 홈플러스 일반노조 관계자는 "3월 체불 임금은 4월에 받았고, 4~5월에 지급되지 않은 임금은 6월 말에 받았다"고 설명했다. 노동부 관계자는 "3~5월 임금체불 관련해서는 시정이 완료됐고, 6월 미지급된 임금에 대한 조사는 아직 진행하고 있다"고 밝혔다. 홈플러스의 월급 지급일은 매달 21일이지만, 6월분 임금은 아직 지급되지 않은 것으로 알려졌다. 노동부는 퇴직에 따른 체불 가능성도 고려 중이다. 홈플러스 본사는 최근 퇴직자들에게 "현재 회사의 자금 부족으로 인해 금일 지급 예정이었던 ''퇴직급여 및 퇴직금 회사 지급 분''의 지급이 부득이하게 지연되게 됐다"고 공지한 상태다. 앞서 지난 3일 서울회생법원 회생4부(법원장 정준영)는 홈플러스의 기업회생절차 폐지를 결정했다. 법원은 제출된 수정 회생계획안의 수행 가능성이 낮다고 판단한 것으로 밝혀졌다. 다만 홈플러스가 회생절차 폐지 결정 후 14일 이내 운영자금을 조달해 항고할 경우, 정당한 이유가 인정되면 폐지 결정은 취소될 수 있다. 만약 항고를 제기하지 않을 시에는 폐지 결정이 확정된다.', 'crawl', '뉴시스', '2026-07-07 13:48:53', '중도', 'ready', 'https://img1.newsis.com/2026/07/05/NISI20260705_0021350773_web.jpg?rnd=20260705125324', '2026-07-07 06:04:33', '2026-07-07 17:09:45.909751', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3519, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003698996', 'https://www.newsis.com/view/NISX20260707_0003698996', '사회', '''전분당 담합'' 3개 제조사 첫 재판…"담합 인정, 대표엔 보고 안 해"', '[서울=뉴시스]이윤석 기자 = 8년에 걸쳐 10조원대 전분 및 당류(전분당) 가격을 담합한 의혹을 받는 대상·사조CPK·CJ제일제당 등 3개 제조사 임직원들이 첫 재판에서 실무자 선에서 진행된 담합 사실은 대부분 인정했다. 다만 각 회사의 대표들이 해당 내용을 보고 받지 않았다는 취지로 진술했다. 서울중앙지법 형사3단독 이호선 판사는 7일 독점규제 및 공정거래에 관한 법률 위반 혐의로 기소된 대상·사조CPK·CJ제일제당 3개 업체와 각 회사의 대표이사, 전분당협회장 등 총 24명(법인 3곳·개인 21명)의 1차 공판기일을 진행했다. 대상 측 임직원들은 담합에 가담한 사실을 모두 인정하고 반성한다고 밝혔다. 다만 대표이사들에게 보고해 지시를 받거나, 대표이사들이 승인한 적은 없다고 했다. 대상 임직원 측은 직급상 상급자들에게 보고했을 뿐 대표이사에게 직접 보고한 사실이 없어서 공모관계 있다고 인정하기 어렵다는 취지로 설명했다. 정홍언 전 대상 공동대표와 임정배 대상 대표이사 측도 대표자들과의 모임에서 가격을 합의한 적이 없다고 밝혔다. 개별적인 입찰 담합이나 부산물 가격 담합 대해 보고받거나 승인한 적도 없다고 부인했다. 사조CPK 측 역시 공소사실 모두 인정하고 반성한다고 밝혔다. 다만 임직원들의 퇴사 이후 범행들에 대해 법인 책임에 대한 귀속은 인정하지 않는다고 했다. 이창주 사조CPK 대표이사 측도 공소사실을 모두 인정하고 반성한다고 했지만, 2024년 대표이사 취임 이전 범죄사실에 대해서는 부인했다. CJ 제일제당 측은 담합 공동행위에 가담한 사실을 인정하고 깊이 반성한다고 했다. 다만 다른 제조사 주도로 담합이 진행됐고 가담한 정도가 경미하다고 주장했다. 한국전분당협회장 A씨 측도 모든 혐의를 부인했다. 협회장으로서 대표급 인사 모임을 주선한 사실은 있지만 "해당 모임에서 제품 가격 인상에 대한 논의와 공감대는 형성되지 않았다"고 주장했다. 재판부는 내달 25일 공판준비기일로 재판을 속행하기로 했다. ''전분당 담합 의혹''은 대상, 사조CPK, 삼양, CJ제일제당 등 4개 업체가 지난 8년에 걸쳐 약 10조원 규모의 가격 담합했다는 내용을 골자로 한다. 전분당은 옥수수 등에서 추출한 전분으로 만든 물엿, 과당, 올리고당 등을 지칭하며 과자, 유제품 등에 폭넓게 사용된다. 이들 4개 업체가 2017년 7월께부터 지난해 10월까지 최소 8년간 10조1520억원 규모의 담합을 한 정황이 드러났다. 국내 식료품 담합 중 역대 최대 규모인 것으로 나타났다. 검찰에 따르면 담합 발생 전 대비 전분 가격은 최고 73.4%까지, 당류 가격은 최고 63.8%까지 각 인상된 것으로 확인됐다 이들 업체가 전분당 제품별 가격 조정 시기와 폭을 정하는 합의(기본합의)를 하면서 거래처를 상대로 그 합의 내용은 관철시키되 담합 사실은 은닉하기 위해 각 업체별로 거래처에 제안할 가격 인상·인하 폭을 달리했다는 게 검찰의 판단이다. 검찰은 지난 4월 대상·사조CPK·CJ제일제당 3개 법인, 각 회사의 전·현직 임직원과 전분당협회장 A씨 등 총 25명(법인 3곳·개인 22명)을 독점규제 및 공정거래에 관한 법률 위반 혐의로 기소했다. 김모 대상 사업본부장은 구속 기소, 나머지 21명을 불구속 기소했다. 담합 가담 의혹이 제기됐던 삼양사는 이번 기소 대상에 포함되지 않았다. 함께 기소된 김씨는 서울중앙지법 형사15단독 박찬범 판사 심리로 재판을 받고 있다. 한편 공정거래위원회는 이날 대상, 사조씨피케이, 삼양사, CJ제일제당 등 전분당 제조·판매업체 4곳의 가격담합에 대해 독자적 가격 재결정 등 시정명령과 함께 총 7476억원의 과징금을 부과하기로 결정했다. 업체별 과징금은 대상 2341억원, 사조씨피케이 2001억원, 삼양사 2103억원, CJ제일제당 1029억원이다. ◎공감언론 뉴시스 leeys@newsis.com', '''전분당 담합'' 3개 제조사 첫 재판…"담합 인정, 대표엔 보고 안 해" 등록 2026.07.07 13:44:41 8년간 10조원 담합…가격 최고 73.4%까지 인상 "담합 자체는 인정…대표자들이 보고받진 않아" [서울=뉴시스] 이윤석 기자 = 8년에 걸쳐 10조원대 전분 및 당류(전분당) 가격을 담합한 의혹을 받는 대상·사조CPK·CJ제일제당 등 3개 제조사 임직원들이 첫 재판에서 실무자 선에서 진행된 담합 사실은 대부분 인정했다. 다만 각 회사의 대표들이 해당 내용을 보고 받지 않았다는 취지로 진술했다. 서울중앙지법 형사3단독 이호선 판사는 7일 독점규제 및 공정거래에 관한 법률 위반 혐의로 기소된 대상·사조CPK·CJ제일제당 3개 업체와 각 회사의 대표이사, 전분당협회장 등 총 24명(법인 3곳·개인 21명)의 1차 공판기일을 진행했다. 대상 측 임직원들은 담합에 가담한 사실을 모두 인정하고 반성한다고 밝혔다. 다만 대표이사들에게 보고해 지시를 받거나, 대표이사들이 승인한 적은 없다고 했다. 대상 임직원 측은 직급상 상급자들에게 보고했을 뿐 대표이사에게 직접 보고한 사실이 없어서 공모관계 있다고 인정하기 어렵다는 취지로 설명했다. 정홍언 전 대상 공동대표와 임정배 대상 대표이사 측도 대표자들과의 모임에서 가격을 합의한 적이 없다고 밝혔다. 개별적인 입찰 담합이나 부산물 가격 담합 대해 보고받거나 승인한 적도 없다고 부인했다. 사조CPK 측 역시 공소사실 모두 인정하고 반성한다고 밝혔다. 다만 임직원들의 퇴사 이후 범행들에 대해 법인 책임에 대한 귀속은 인정하지 않는다고 했다. 이창주 사조CPK 대표이사 측도 공소사실을 모두 인정하고 반성한다고 했지만, 2024년 대표이사 취임 이전 범죄사실에 대해서는 부인했다. CJ 제일제당 측은 담합 공동행위에 가담한 사실을 인정하고 깊이 반성한다고 했다. 다만 다른 제조사 주도로 담합이 진행됐고 가담한 정도가 경미하다고 주장했다. 한국전분당협회장 A씨 측도 모든 혐의를 부인했다. 협회장으로서 대표급 인사 모임을 주선한 사실은 있지만 "해당 모임에서 제품 가격 인상에 대한 논의와 공감대는 형성되지 않았다"고 주장했다. 재판부는 내달 25일 공판준비기일로 재판을 속행하기로 했다. ''전분당 담합 의혹''은 대상, 사조CPK, 삼양, CJ제일제당 등 4개 업체가 지난 8년에 걸쳐 약 10조원 규모의 가격 담합했다는 내용을 골자로 한다. 전분당은 옥수수 등에서 추출한 전분으로 만든 물엿, 과당, 올리고당 등을 지칭하며 과자, 유제품 등에 폭넓게 사용된다. 이들 4개 업체가 2017년 7월께부터 지난해 10월까지 최소 8년간 10조1520억원 규모의 담합을 한 정황이 드러났다. 국내 식료품 담합 중 역대 최대 규모인 것으로 나타났다. 검찰에 따르면 담합 발생 전 대비 전분 가격은 최고 73.4%까지, 당류 가격은 최고 63.8%까지 각 인상된 것으로 확인됐다. 이들 업체가 전분당 제품별 가격 조정 시기와 폭을 정하는 합의(기본합의)를 하면서 거래처를 상대로 그 합의 내용은 관철시키되 담합 사실은 은닉하기 위해 각 업체별로 거래처에 제안할 가격 인상·인하 폭을 달리했다는 게 검찰의 판단이다. 검찰은 지난 4월 대상·사조CPK·CJ제일제당 3개 법인, 각 회사의 전·현직 임직원과 전분당협회장 A씨 등 총 25명(법인 3곳·개인 22명)을 독점규제 및 공정거래에 관한 법률 위반 혐의로 기소했다. 김모 대상 사업본부장은 구속 기소, 나머지 21명을 불구속 기소했다. 담합 가담 의혹이 제기됐던 삼양사는 이번 기소 대상에 포함되지 않았다. 함께 기소된 김씨는 서울중앙지법 형사15단독 박찬범 판사 심리로 재판을 받고 있다. 한편 공정거래위원회는 이날 대상, 사조씨피케이, 삼양사, CJ제일제당 등 전분당 제조·판매업체 4곳의 가격담합에 대해 독자적 가격 재결정 등 시정명령과 함께 총 7476억원의 과징금을 부과하기로 결정했다. 업체별 과징금은 대상 2341억원, 사조씨피케이 2001억원, 삼양사 2103억원, CJ제일제당 1029억원이다.', 'crawl', '뉴시스', '2026-07-07 13:44:41', '중도', 'ready', 'https://img1.newsis.com/2026/04/23/NISI20260423_0021256666_web.jpg?rnd=20260423112735', '2026-07-07 06:04:34', '2026-07-07 17:10:08.633484', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3524, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003698594', 'https://www.newsis.com/view/NISX20260707_0003698594', '사회', '검찰, 장윤기 사건 부실수사·유착 직접수사…광산서 압색(종합)', '[전남광주=뉴시스]변재훈 박기웅 기자 = 검찰이 장윤기(23) 여고생 살인사건의 부실 수사와 경찰 유착 의혹을 규명하기 위해 직접 강제수사에 나섰다. 광주지검은 7일 오전 광주 광산경찰서 형사과, 여성청소년범죄수사과 사무실과 당시 수사팀장 A경감 자택 등 5곳에서 압수수색을 벌이고 있다. 이날 압수수색은 장윤기 사건을 수사한 광산 경찰서 수사팀의 증거인멸과 현직 경찰 장윤기 아버지와의 유착 의혹 등 제기된 의혹 전반을 밝혀내고자 진행됐다. 현재까지 입건자는 A경감과 담당 수사팀 관계자 등 다수다. 검찰이 압수수색 영장에 기재한 혐의는 공무상비밀누설, 증거인멸, 증거인멸방조다. 검찰은 A경감 외에 수사 선상에 오른 경찰관의 직급과 직책 등에 대해서는 공개하지 않았다. 경찰관의 직무상 비위와 관련해 직접 수사할 수 있는 검찰은 앞선 지난 3일 형사부장 검사를 팀장을 맡는 전담수사팀을 꾸렸다. 검찰 전담수사팀은 검사 4명과 수사관 15명 규모다. 검찰은 장윤기 사건을 수사한 경찰의 초동 수사가 적절했는지 등을 두루 수사하고 있다. 장윤기가 피해 여고생 살해 전후 이용한 스포츠유틸리티차량(SUV) 차량 내에서 발견된 ''케이블 타이''(공업용 묶음 끈)을 증거로 확보하지 않은 경위에 대해 들여다보고 있다. A팀장은 당시 살인 범행 도구인 흉기를 찾는데 집중하느라 ''케이블 타이''를 대수롭지 않게 여겼다는 취지로 주장하고 있다. 반면 검찰은 피해자를 결박할 수 있는 도구인 ''케이블 타이''가 장윤기의 범행 목적을 성범죄라고 판단한 공소사실을 뒷받침할 중요 정황 증거로 판단, 인멸 또는 분실한 증거로 보고 있다. 특히 A경감이 ''케이블 타이''가 찍힌 차량 수색 당시 영상을 뒤늦게 삭제, 증거를 인멸한 것으로 검찰은 보고 있다. 해당 영상은 촬영한 형사의 휴대전화에 저장돼 있었던 것으로 전해졌다. A경감의 영상 삭제 지시 시점은 이달 초로 알려졌다. 검찰이 보완수사를 거쳐 경찰이 적용한 살인 등 혐의가 아닌 성폭력처벌법 위반(강간 등 살인) 등 혐의로 바꿔 기소한 이후 경찰의 초동 부실 수사 논란이 불거진 시점과 맞물린다. 검찰은 또 장윤기의 SUV 차량 안팎을 촬영한 빌트인 차량 블랙박스 저장장치가 애당초 없었다는 점 역시 수사하고 있다. 검찰 수사와 별개로 앞서 경찰도 초동 수사를 둘러싼 각종 의혹을 규명하고자 공식 수사로 전환했다. 경찰도 전담수사팀을 꾸려 전날 오전 A경감을 증거인멸 등 혐의로 전격 긴급체포했다. 이후 수사 주체는 광주경찰청에서 국가수사본부로 격상 확대됐다. A경감의 신병부터 확보한 경찰은 이날 구속영장을 신청했다. 이례적으로 검찰과 경찰이 현직 경찰관의 초동 수사 부실과 증거인멸 등 의혹에 대해 동시 수사에 나선 것이다. 이같은 ''수사 경합'' 상황에서 검찰과 경찰이 같은 사건을 각기 수사할 수 있다. 다만 형사소송법 규정에 따라 체포·압수수색·통신·구속영장을 먼저 신청 또는 청구한 수사 기관이 각 영장에서 확보한 증거 자료에 대한 송치요구권을 갖는다. 검찰 관계자는 "장윤기 사건의 공소가 이미 제기된 상황에서 공소사실을 뒷받침할 증거를 빠르게 확보해야 하고 제기된 의혹을 명명백백 밝혀내야 한다고 판단, 직접 수사에 나섰다"라면서 "경찰 수사가 이미 확보한 증거 자료에 대한 송치요구권은 행사하지 않을 계획"이라고 밝혔다. 또 "경찰이 진행 중인 A경감 사건과 수사중첩 문제는 발생하지 않는 것으로 보인다. 신속·공정하게 수사를 진행해 나갈 예정입니다"면서 "A팀장에 대한 신병처리 등은 경찰 판단에 따라 진행된다"고 했다. 한편 장윤기는 지난 5월5일 광주 광산구의 한 고등학교 앞 인도에서 귀가하던 이채원(17) 양을 자신의 차량으로 끌고 가려다 흉기로 살해하고, 이를 제지하려던 남고생을 다치게 한 혐의 등으로 재판에 넘겨졌다. ◎공감언론 뉴시스 wisdom21@newsis.com, pboxer@newsis.com', '검찰, 장윤기 사건 부실수사·유착 직접수사…광산서 압색(종합) 등록 2026.07.07 12:42:48 수정 2026.07.07 14:12:39 ''비밀누설·증거인멸'' 혐의로 수사팀장 등 다수 입건 7월초 증거영상 삭제 지시 등 각종 의혹 두루 수사 경찰은 ''긴급체포'' 팀장 영장 신청…검·경 동시 수사 [전남광주=뉴시스] 양시원 기자 = 광주지검 수사관들이 7일 광주광산경찰서 형사과 등지에서 장윤기(23) 여고생 살인 사건의 부실 수사와 경찰 유착 의혹을 규명하기 위한 압수수색을 벌이고 있다. [전남광주=뉴시스]변재훈 박기웅 기자 = 검찰이 장윤기(23) 여고생 살인사건의 부실 수사와 경찰 유착 의혹을 규명하기 위해 직접 강제수사에 나섰다. 광주지검은 7일 오전 광주 광산경찰서 형사과, 여성청소년범죄수사과 사무실과 당시 수사팀장 A경감 자택 등 5곳에서 압수수색을 벌이고 있다. 이날 압수수색은 장윤기 사건을 수사한 광산 경찰서 수사팀의 증거인멸과 현직 경찰 장윤기 아버지와의 유착 의혹 등 제기된 의혹 전반을 밝혀내고자 진행됐다. 현재까지 입건자는 A경감과 담당 수사팀 관계자 등 다수다. 검찰이 압수수색 영장에 기재한 혐의는 공무상비밀누설, 증거인멸, 증거인멸방조다. 검찰은 A경감 외에 수사 선상에 오른 경찰관의 직급과 직책 등에 대해서는 공개하지 않았다. 경찰관의 직무상 비위와 관련해 직접 수사할 수 있는 검찰은 앞선 지난 3일 형사부장 검사를 팀장을 맡는 전담수사팀을 꾸렸다. 검찰 전담수사팀은 검사 4명과 수사관 15명 규모다. 검찰은 장윤기 사건을 수사한 경찰의 초동 수사가 적절했는지 등을 두루 수사하고 있다. 장윤기가 피해 여고생 살해 전후 이용한 스포츠유틸리티차량(SUV) 차량 내에서 발견된 ''케이블 타이''(공업용 묶음 끈)을 증거로 확보하지 않은 경위에 대해 들여다보고 있다. A팀장은 당시 살인 범행 도구인 흉기를 찾는데 집중하느라 ''케이블 타이''를 대수롭지 않게 여겼다는 취지로 주장하고 있다. 반면 검찰은 피해자를 결박할 수 있는 도구인 ''케이블 타이''가 장윤기의 범행 목적을 성범죄라고 판단한 공소사실을 뒷받침할 중요 정황 증거로 판단, 인멸 또는 분실한 증거로 보고 있다. 특히 A경감이 ''케이블 타이''가 찍힌 차량 수색 당시 영상을 뒤늦게 삭제, 증거를 인멸한 것으로 검찰은 보고 있다. 해당 영상은 촬영한 형사의 휴대전화에 저장돼 있었던 것으로 전해졌다. A경감의 영상 삭제 지시 시점은 이달 초로 알려졌다. 검찰이 보완수사를 거쳐 경찰이 적용한 살인 등 혐의가 아닌 성폭력처벌법 위반(강간 등 살인) 등 혐의로 바꿔 기소한 이후 경찰의 초동 부실 수사 논란이 불거진 시점과 맞물린다. 검찰은 또 장윤기의 SUV 차량 안팎을 촬영한 빌트인 차량 블랙박스 저장장치가 애당초 없었다는 점 역시 수사하고 있다. 검찰 수사와 별개로 앞서 경찰도 초동 수사를 둘러싼 각종 의혹을 규명하고자 공식 수사로 전환했다. 경찰도 전담수사팀을 꾸려 전날 오전 A경감을 증거인멸 등 혐의로 전격 긴급체포했다. 이후 수사 주체는 광주경찰청에서 국가수사본부로 격상 확대됐다. A경감의 신병부터 확보한 경찰은 이날 구속영장을 신청했다. 이례적으로 검찰과 경찰이 현직 경찰관의 초동 수사 부실과 증거인멸 등 의혹에 대해 동시 수사에 나선 것이다. 이같은 ''수사 경합'' 상황에서 검찰과 경찰이 같은 사건을 각기 수사할 수 있다. 다만 형사소송법 규정에 따라 체포·압수수색·통신·구속영장을 먼저 신청 또는 청구한 수사 기관이 각 영장에서 확보한 증거 자료에 대한 송치요구권을 갖는다. 검찰 관계자는 "장윤기 사건의 공소가 이미 제기된 상황에서 공소사실을 뒷받침할 증거를 빠르게 확보해야 하고 제기된 의혹을 명명백백 밝혀내야 한다고 판단, 직접 수사에 나섰다"라면서 "경찰 수사가 이미 확보한 증거 자료에 대한 송치요구권은 행사하지 않을 계획"이라고 밝혔다. 또 "경찰이 진행 중인 A경감 사건과 수사중첩 문제는 발생하지 않는 것으로 보인다. 신속·공정하게 수사를 진행해 나갈 예정입니다"면서 "A팀장에 대한 신병처리 등은 경찰 판단에 따라 진행된다"고 했다. 한편 장윤기는 지난 5월5일 광주 광산구의 한 고등학교 앞 인도에서 귀가하던 이채원(17) 양을 자신의 차량으로 끌고 가려다 흉기로 살해하고, 이를 제지하려던 남고생을 다치게 한 혐의 등으로 재판에 넘겨졌다.', 'crawl', '뉴시스', '2026-07-07 12:42:48', '중도', 'ready', 'https://img1.newsis.com/2026/07/07/NISI20260707_0002180004_web.jpg?rnd=20260707123223', '2026-07-07 06:04:34', '2026-07-07 17:16:50.460777', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3526, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003698960', 'https://www.newsis.com/view/NISX20260707_0003698960', '사회', '''피습 자작극 의혹'' 정이한, 구속기로…8일 영장심사(종합)', '[부산=뉴시스]김민지 이아름 기자 = 지난 6·3 지방선거에서 음료 피습 자작극을 벌인 혐의를 받는 정이한 전 개혁신당 부산시장 후보가 8일 구속기로에 선다. 부산 금정경찰서는 지난 1일 위계공무집행방해 및 공직선거법 위반 등 혐의로 정 전 후보와 공모 관계에 있는 A(30대)씨 등 2명에 대한 구속영장을 신청했다고 7일 밝혔다. 영장 신청 사유는 증거인멸 및 도주 우려다. 이후 검찰은 지난 3일 법원에 해당 구속영장을 청구했고, 부산지법은 정 전 후보와 A씨에 대한 구속전피의자심문(영장실질심사)를 8일 오후 2시에 연다. 정 전 후보에 대해서는 엄지아 판사가, A씨에 대해서는 심학식 부장판사가 영장심사를 담당한다. 앞서 A씨에 대해서는 지난 4월29일 구속영장이 한 차례 청구됐지만, 긴급체포 등 요건 소명 부족으로 기각된 바 있다. 둘에 대한 영장 심사 결과는 당일 늦은 저녁께 나올 것으로 예상된다. 정 전 후보에 대한 경찰의 구속영장 신청을 두고 이번 사건이 단순한 의혹 수준이 아닌 객관적 혐의점을 규명할 증거가 확보된 것으로 풀이된다. 정 전 후보 측은 지난 4월27일 부산 금정구에서 선거운동 중 지나가던 승용차의 운전자가 뿌린 음료수를 맞고 넘어져 뇌진탕 진단을 받았다고 주장, 이후 목에 깁스를 한 채 경찰서를 찾아 선처 탄원서를 제출하기도 했다. 하지만 경찰은 이후 자작극 의혹을 인지하고 선거 다음 날인 지난달 4일 정 전 후보 선거사무소를 압수수색했다. 또 A씨의 휴대전화 포렌식 결과 정 전 후보와 A씨 간 사전 통화 기록 등을 발견한 것으로 전해졌다. 아울러 A씨는 전직 헬스 트레이너로 정 전 후보와 알고 지내던 사이였던 것으로 알려졌다. 경찰은 정 전 후보의 자작극 의혹 외에도 학적 논란 및 여론조사 의혹, 부친 회사 계열사 직원 선거운동 동원 의혹 등 제기된 사안 전반에 대해 수사를 진행하고 있다. 현재 정 전 후보는 개혁신당을 탈당한 상태다. ◎공감언론 뉴시스 mingya@newsis.com, aha@newsis.com', '정이한 전 개혁신당 부산시장 후보가 8일 구속기로에 선다. 부산 금정경찰서는 지난 1일 위계공무집행방해 및 공직선거법 위반 등 혐의로 정 전 후보와 공모 관계에 있는 A(30대)씨 등 2명에 대한 구속영장을 신청했다고 7일 밝혔다. 영장 신청 사유는 증거인멸 및 도주 우려다. 이후 검찰은 지난 3일 법원에 해당 구속영장을 청구했고, 부산지법은 정 전 후보와 A씨에 대한 구속전피의자심문(영장실질심사)를 8일 오후 2시에 연다. 정 전 후보에 대해서는 엄지아 판사가, A씨에 대해서는 심학식 부장판사가 영장심사를 담당한다. 앞서 A씨에 대해서는 지난 4월29일 구속영장이 한 차례 청구됐지만, 긴급체포 등 요건 소명 부족으로 기각된 바 있다. 둘에 대한 영장 심사 결과는 당일 늦은 저녁께 나올 것으로 예상된다. 정 전 후보에 대한 경찰의 구속영장 신청을 두고 이번 사건이 단순한 의혹 수준이 아닌 객관적 혐의점을 규명할 증거가 확보된 것으로 풀이된다. 정 전 후보 측은 지난 4월27일 부산 금정구에서 선거운동 중 지나가던 승용차의 운전자가 뿌린 음료수를 맞고 넘어져 뇌진탕 진단을 받았다고 주장, 이후 목에 깁스를 한 채 경찰서를 찾아 선처 탄원서를 제출하기도 했다. 하지만 경찰은 이후 자작극 의혹을 인지하고 선거 다음 날인 지난달 4일 정 전 후보 선거사무소를 압수수색했다. 또 A씨의 휴대전화 포렌식 결과 정 전 후보와 A씨 간 사전 통화 기록 등을 발견한 것으로 전해졌다. 아울러 A씨는 전직 헬스 트레이너로 정 전 후보와 알고 지내던 사이였던 것으로 알려졌다. 경찰은 정 전 후보의 자작극 의혹 외에도 학적 논란 및 여론조사 의혹, 부친 회사 계열사 직원 선거운동 동원 의혹 등 제기된 사안 전반에 대해 수사를 진행하고 있다. 현재 정 전 후보는 개혁신당을 탈당한 상태다.', 'crawl', '뉴시스', '2026-07-07 12:39:50', '중도', 'ready', 'https://img1.newsis.com/2026/06/17/NISI20260617_0002163536_web.jpg?rnd=20260617164515', '2026-07-07 06:04:34', '2026-07-07 17:17:00.394252', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3533, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003698936', 'https://www.newsis.com/view/NISX20260707_0003698936', '사회', '''피습 자작극 의혹'' 정이한 전 부산시장 후보에 구속영장 청구', '[부산=뉴시스] 이아름 기자 = 지난 6·3지방선거 음료 테러 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보 등 2명이 구속 갈림길에 놓였다. 부산 금정경찰서는 지난 1일 정 전 후보 등 2명에 위계공무집행방해, 공직선거법 위반 등의 혐의로 구속영장을 신청하고, 이어 지난 3일 검찰이 구속영장을 청구했다고 7일 밝혔다. 이들에 대한 영장실질심사는 오는 8일 오후 2시 부산지방법원에서 열릴 예정이다. 정 후보 측은 지난 4월27일 부산 금정구 구서나들목 인근에서 정 후보가 선거운동을 하던 중 지나가던 승용차에서 한 남성이 뿌린 음료수를 맞고 넘어져 뇌진탕 진단을 받았다고 주장했다. 경찰은 정 후보에게 음료를 뿌린 혐의로 30대 남성을 체포해 조사했지만, 해당 남성에 대한 구속 영장은 기각됐다. 이후 정 후보는 목에 깁스를 한 채 경찰서를 찾아 음료를 뿌린 남성에 대한 선처를 요청하는 탄원서를 제출했다. 경찰은 사건 전반에 대한 수사를 진행하는 과정에서 지방선거 다음 날인 지난 6월4일 정 전 후보의 선거사무소를 압수수색한 것으로 전해졌다. 경찰은 또 음료를 뿌린 30대 남성과 사건 발생 전 정 전 후보와 통화한 기록을 확보하고, 자작극 의혹에 대해 수사를 벌이고 있는 것으로 알려졌다. 아울러 경찰은 정 전 후보 부친이 운영하는 회사 계열사 직원들이 정 전 후보의 선거 운동에 동원됐다는 의혹과 정 전 후보의 학적 논란, 여론조사 의혹 등에 대해서도 수사를 진행하고 있는 것으로 전해졌다. ◎공감언론 뉴시스 aha@newsis.com', '피습 자작극 의혹'' 정이한 전 부산시장 후보에 구속영장 청구 등록 2026.07.07 12:07:12 수정 2026.07.07 14:42:24 구글에서 선호하는 매체로 추가 작게 크게 8일 오후 2시 부산지법서 영장실질심사 [부산=뉴시스] 정이한 개혁신당 부산시장 후보. [부산=뉴시스] 이아름 기자 = 지난 6·3지방선거 음료 테러 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보 등 2명이 구속 갈림길에 놓였다. 부산 금정경찰서는 지난 1일 정 전 후보 등 2명에 위계공무집행방해, 공직선거법 위반 등의 혐의로 구속영장을 신청하고, 이어 지난 3일 검찰이 구속영장을 청구했다고 7일 밝혔다. 이들에 대한 영장실질심사는 오는 8일 오후 2시 부산지방법원에서 열릴 예정이다. 정 후보 측은 지난 4월27일 부산 금정구 구서나들목 인근에서 정 후보가 선거운동을 하던 중 지나가던 승용차에서 한 남성이 뿌린 음료수를 맞고 넘어져 뇌진탕 진단을 받았다고 주장했다. 경찰은 정 후보에게 음료를 뿌린 혐의로 30대 남성을 체포해 조사했지만, 해당 남성에 대한 구속 영장은 기각됐다. 이후 정 후보는 목에 깁스를 한 채 경찰서를 찾아 음료를 뿌린 남성에 대한 선처를 요청하는 탄원서를 제출했다. 경찰은 사건 전반에 대한 수사를 진행하는 과정에서 지방선거 다음 날인 지난 6월4일 정 전 후보의 선거사무소를 압수수색한 것으로 전해졌다. 경찰은 또 음료를 뿌린 30대 남성과 사건 발생 전 정 전 후보와 통화한 기록을 확보하고, 자작극 의혹에 대해 수사를 벌이고 있는 것으로 알려졌다. 아울러 경찰은 정 전 후보 부친이 운영하는 회사 계열사 직원들이 정 전 후보의 선거 운동에 동원됐다는 의혹과 정 전 후보의 학적 논란, 여론조사 의혹 등에 대해서도 수사를 진행하고 있는 것으로 전해졌다.', 'crawl', '뉴시스', '2026-07-07 12:07:12', '중도', 'ready', 'https://img1.newsis.com/2026/06/17/NISI20260617_0002163536_web.jpg?rnd=20260617164515', '2026-07-07 06:04:34', '2026-07-07 17:18:21.681914', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3546, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003698918', 'https://www.newsis.com/view/NISX20260707_0003698918', '사회', '기상청 "8~10일 중부지방 최대 200㎜ 폭우…이후 전국 폭염"', '[서울=뉴시스] 신항섭 기자 = 기상청은 정체전선이 남북으로 오르내리면서 8일부터 10일 오전까지 중부지방과 전라도를 중심으로 강하고 많은 비가 내릴 것으로 전망했다. 정체전선이 북상하는 10일 이후에는 폭염 특보가 전국으로 확대될 것으로 내다봤다. 기상청은 7일 오전 11시 수시브리핑을 열고 정체전선 동향과 기온 전망을 발표했다. 이광연 기상청 예보분석관은 "북태평양고기압 가장자리를 경계로 찬 공기와 정체전선이 대치하며 기압골이 주기적으로 남하해 강수시스템이 반복 활성화하고 있다"고 설명했다. 이날 새벽부터 충청권에 강한 비가 이어져 오전 9시까지 군산에 93㎜가 내렸고, 오후에는 중부지방에 돌풍·천둥번개를 동반한 최대 60㎜ 소나기가 예보됐다. 기상청에 따르면 8일 새벽부터 낮까지는 중부·전라 중심으로 비가 내린 뒤, 8일 저녁 정체전선이 남하했다가 9일 오전 다시 북상하는 과정에서 충남·전북에 비가 집중된다. 8~9일 충남·전북에는 최대 200㎜ 이상, 경기남부·강원 중남부내륙·충북에는 최대 150㎜ 이상이 예상된다. 이 예보분석관은 "취약 시간대인 새벽에 강한 비가 집중될 수 있어 사전 대비가 중요하다"고 강조했다. 정체전선은 10일 낮부터 북한으로 북상할 것으로 내다봤다. 정체전선을 따라 체감온도 33도 안팎의 무더위가 이어지고 밤 체감기온이 26도를 넘는 곳에서는 열대야도 나타날 전망이다. 정체전선이 물러나는 10일 이후 기온이 올라 10일경부터는 남부내륙 중심 폭염특보가 전국으로 확대되고, 일부 지역엔 올해 신설된 열대야주의보 발효 가능성도 있다. 우진규 기상청 통보관은 "남부지방, 특히 제주도를 중심으로 열대야 발생 가능성이 크다"고 말했다.. 제9호 태풍 바비는 7일 오전 9시 기준 괌 서북서쪽 약 610㎞ 해상에서 중심기압 925hPa, 최대풍속 51㎧(강도 ''4'')로 서진 중이다. 기상청은 태풍이 11일경 대만 북쪽 해상을 지나 12일경 중국 동안에 상륙할 것으로 전망했다. 이번 강수에 태풍 바비의 직접 영향은 없지만 상륙 후 동아시아 기압계 재배치로 다음 주 후반 강수가 추가될 가능성이 있다고 밝혔다. ◎공감언론 뉴시스 hangseob@newsis.com', '기상청이 중부지방에 장마시작을 발표한 가운데 2일 오전 인천 남동구 인천시청 재난안전상황실에서 상황실 근무자들이 호우에 대비해 위성영상을 살피고 있다. 기상청은 정체전선이 남북으로 오르내리면서 8일부터 10일 오전까지 중부지방과 전라도를 중심으로 강하고 많은 비가 내릴 것으로 전망했다. 정체전선이 북상하는 10일 이후에는 폭염 특보가 전국으로 확대될 것으로 내다봤다. 기상청은 7일 오전 11시 수시브리핑을 열고 정체전선 동향과 기온 전망을 발표했다. 이광연 기상청 예보분석관은 "북태평양고기압 가장자리를 경계로 찬 공기와 정체전선이 대치하며 기압골이 주기적으로 남하해 강수시스템이 반복 활성화하고 있다"고 설명했다. 이날 새벽부터 충청권에 강한 비가 이어져 오전 9시까지 군산에 93㎜가 내렸고, 오후에는 중부지방에 돌풍·천둥번개를 동반한 최대 60㎜ 소나기가 예보됐다. 기상청에 따르면 8일 새벽부터 낮까지는 중부·전라 중심으로 비가 내린 뒤, 8일 저녁 정체전선이 남하했다가 9일 오전 다시 북상하는 과정에서 충남·전북에 비가 집중된다. 8~9일 충남·전북에는 최대 200㎜ 이상, 경기남부·강원 중남부내륙·충북에는 최대 150㎜ 이상이 예상된다. 이 예보분석관은 "취약 시간대인 새벽에 강한 비가 집중될 수 있어 사전 대비가 중요하다"고 강조했다. 정체전선은 10일 낮부터 북한으로 북상할 것으로 내다봤다. 정체전선을 따라 체감온도 33도 안팎의 무더위가 이어지고 밤 체감기온이 26도를 넘는 곳에서는 열대야도 나타날 전망이다. 정체전선이 물러나는 10일 이후 기온이 올라 10일경부터는 남부내륙 중심 폭염특보가 전국으로 확대되고, 일부 지역엔 올해 신설된 열대야주의보 발효 가능성도 있다. 우진규 기상청 통보관은 "남부지방, 특히 제주도를 중심으로 열대야 발생 가능성이 크다"고 말했다. 제9호 태풍 바비는 7일 오전 9시 기준 괌 서북서쪽 약 610㎞ 해상에서 중심기압 925hPa, 최대풍속 51㎧(강도 ''4'')로 서진 중이다. 기상청은 태풍이 11일경 대만 북쪽 해상을 지나 12일경 중국 동안에 상륙할 것으로 전망했다. 이번 강수에 태풍 바비의 직접 영향은 없지만 상륙 후 동아시아 기압계 재배치로 다음 주 후반 강수가 추가될 가능성이 있다고 밝혔다.', 'crawl', '뉴시스', '2026-07-07 11:49:48', '중도', 'ready', 'https://img1.newsis.com/2026/07/02/NISI20260702_0021347583_web.jpg?rnd=20260702144050', '2026-07-07 06:04:34', '2026-07-07 17:20:37.048455', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3572, 'https://www.newsis.com/RSS/society.xml', 'https://www.newsis.com/view/NISX20260707_0003698770', 'https://www.newsis.com/view/NISX20260707_0003698770', '사회', '김대중 전남광주교육감, 배재고 학생들 위로…"훌훌 털고 일어나야"', '[전남광주=뉴시스]맹대환 기자 = 서울 배제고 야구부 학생선수들이 광주제일고를 방문해 5·18 조롱 응원을 공식 사과한 가운데 김대중 전남광주특별시교육감이 7일 "그동안 마음이 많이 아팠을 학생들, 이제 훌훌 털고 다시 예전처럼 씩씩하게, 건강하게 학업과 운동에 전념하길 바란다"고 위로했다. 김 교육감은 이날 자신의 사회관계망서비스(SNS)에 글을 올려 "이번 일을 계기로 전남광주와 서울 학생들이 함께 참여하는 스포츠 교류 등으로 우정을 이어갔으면 좋겠다"고 제안하며 이 같이 밝혔다. 김 교육감은 "전남광주특별시교육청은 이번 일을 교훈 삼아 교육과정 속 역사교육과 민주시민교육을 더욱 강화하겠다"며 "아이들이 올바른 역사의식을 갖춘 민주시민으로 성장하도록 가르치겠다"고 다짐했다. 김 교육감은 배재고 학생들에 대한 과도한 비난을 자제해야 한다고 호소했다. 그는 "응원 논란이 발생한 이후 줄곧 교육적으로 해결되었으면 좋겠다는 뜻을 밝혀왔다"며 "이제는 더 이상 이 문제로 학생들이 힘들어하지 않았으면 좋겠다. 갈등과 논쟁을 유발하는 과도한 관심과 언행을 삼가주시기를 부탁드린다"고 말했다. 김 교육감은 "두 학교 학생들이 용서와 화해의 손을 맞잡은 것은 단순한 사과를 넘어 서로를 이해하고 존중하는 교육의 과정이다. 민주주의를 배우는 뜻 깊은 실천이라 할 수 있다"고 진정성 있는 사과와 용서에 대한 의미를 부여했다. ◎공감언론 뉴시스 mdhnews@newsis.com', '김대중 전남광주교육감, 배재고 학생들 위로…"훌훌 털고 일어나야" "그동안 마음 많이 아팠을 것, 운동·학업 전념해야" "갈등과 논쟁 유발하는 과도한 관심·언행 삼가해야" [전남광주=뉴시스] 이영주 기자 = 서울 배재고등학교 야구부 주장(왼쪽)이 6일 오후 전남광주통합특별시 북구 광주제일고등학교를 찾아 제일고 야구부 주장에게 사과문을 전달한 후 악수를 하고 있다. [전남광주=뉴시스]맹대환 기자 = 서울 배제고 야구부 학생선수들이 광주제일고를 방문해 5·18 조롱 응원을 공식 사과한 가운데 김대중 전남광주특별시교육감이 7일 "그동안 마음이 많이 아팠을 학생들, 이제 훌훌 털고 다시 예전처럼 씩씩하게, 건강하게 학업과 운동에 전념하길 바란다"고 위로했다. 김 교육감은 이날 자신의 사회관계망서비스(SNS)에 글을 올려 "이번 일을 계기로 전남광주와 서울 학생들이 함께 참여하는 스포츠 교류 등으로 우정을 이어갔으면 좋겠다"고 제안하며 이 같이 밝혔다. 김 교육감은 "전남광주특별시교육청은 이번 일을 교훈 삼아 교육과정 속 역사교육과 민주시민교육을 더욱 강화하겠다"며 "아이들이 올바른 역사의식을 갖춘 민주시민으로 성장하도록 가르치겠다"고 다짐했다. 김 교육감은 배재고 학생들에 대한 과도한 비난을 자제해야 한다고 호소했다. 그는 "응원 논란이 발생한 이후 줄곧 교육적으로 해결되었으면 좋겠다는 뜻을 밝혀왔다"며 "이제는 더 이상 이 문제로 학생들이 힘들어하지 않았으면 좋겠다. 갈등과 논쟁을 유발하는 과도한 관심과 언행을 삼가주시기를 부탁드린다"고 말했다. 김 교육감은 "두 학교 학생들이 용서와 화해의 손을 맞잡은 것은 단순한 사과를 넘어 서로를 이해하고 존중하는 교육의 과정이다. 민주주의를 배우는 뜻 깊은 실천이라 할 수 있다"고 진정성 있는 사과와 용서에 대한 의미를 부여했다.', 'crawl', '뉴시스', '2026-07-07 10:58:29', '중도', 'ready', 'https://img1.newsis.com/2026/07/06/NISI20260706_0021352283_web.jpg?rnd=20260706155355', '2026-07-07 06:04:35', '2026-07-07 17:24:36.364621', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3594, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Society/article/all/20260707/134250298/1', '정치', '‘피습 자작극 의혹’ 정이한 前부산시장 후보 구속영장 청구', '6·3지방선거 과정에서 음료 테러 자작극을 벌였다는 의혹이 제기된 정이한 전 개혁신당 부산시장 후보 등 2명이 구속의 기로에 섰다. 부산 금정경찰서는 7일 정 전 후보 등 2명에 대해 1일 위계공무집행방해, 공직선거법 위반 등의 혐의로 구속영장을 신청했다고 밝혔다. 검찰은 3일 이들에 대한 구속영장을 청구했다.이들에 대한 영장실질심사는 8일 오후 2시 부산지방법원에서 열릴 예정이다.앞서 정 후보 측은 올해 4월 27일 부산 금정구 구서나들목 인근에서 정 후보가 선거운동을 하던 중 지나가던 승용차에서 한 남성이 뿌린 음료수를 피하려다가 넘어져 뇌진탕 진단을 받았다고 주장했다.하지만 경찰은 사건 발생 전 정 전 후보가 음료를 뿌린 30대 남성과 통화한 기록을 확보하는 등 자작극 의혹에 대해 수사를 벌인 것으로 알려졌다. 경찰은 또 정 전 후보 부친이 운영하는 회사 계열사 직원들이 정 전 후보의 선거 운동에 동원됐다는 의혹 등에 대해서도 조사하고 있는 것으로 전해진다.', '6·3지방선거 과정에서 음료 테러 자작극을 벌였다는 의혹이 제기된 정이한 전 개혁신당 부산시장 후보 등 2명이 구속의 기로에 섰다. 부산 금정경찰서는 7일 정 전 후보 등 2명에 대해 1일 위계공무집행방해, 공직선거법 위반 등의 혐의로 구속영장을 신청했다고 밝혔다. 검찰은 3일 이들에 대한 구속영장을 청구했다.이들에 대한 영장실질심사는 8일 오후 2시 부산지방법원에서 열릴 예정이다.앞서 정 후보 측은 올해 4월 27일 부산 금정구 구서나들목 인근에서 정 후보가 선거운동을 하던 중 지나가던 승용차에서 한 남성이 뿌린 음료수를 피하려다가 넘어져 뇌진탕 진단을 받았다고 주장했다.하지만 경찰은 사건 발생 전 정 전 후보가 음료를 뿌린 30대 남성과 통화한 기록을 확보하는 등 자작극 의혹에 대해 수사를 벌인 것으로 알려졌다. 경찰은 또 정 전 후보 부친이 운영하는 회사 계열사 직원들이 정 전 후보의 선거 운동에 동원됐다는 의혹 등에 대해서도 조사하고 있는 것으로 전해진다.', 'rss', '동아일보', '2026-07-07 12:18:00', '보수', 'crawl_failed', 'https://dimg.donga.com/wps/NEWS/IMAGE/2026/07/07/134250304.1.jpg', '2026-07-07 06:04:35', '2026-07-07 17:27:00.201187', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3599, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Society/article/all/20260707/134249659/1', '정치', '檢, 장윤기 ‘증거인멸 의혹’ 광주 광산경찰서·담당형사 자택 등 압색', '검찰이 ‘여고생 살해’ 장윤기(23) 사건 관련, 부실수사 의혹이 일고 있는 광주 광산경찰서에 대한 압수수색에 나섰다. 검찰은 현직 경찰인 장윤기 아버지와 수사팀 간 유착 의혹 등을 들여다볼 전망이다.7일 오전 광주지검은 장윤기 사건을 담당했던 광주 광산경찰서에 수사관을 보내 압수수색 영장을 집행하고 있다. 검찰은 사건 담당 형사들의 주거지도 압수수색 중이다. 광산서 소속 경찰관들은 5월 5일 장윤기를 긴급체포한 뒤 검찰 송치까지 수사 과정에서 케이블타이·리얼돌·차량(SUV) 등 주요 증거물을 확보하지 않고, 현직 경찰인 장윤기 아버지에게 압수수색·구속영장 내용 등 수사 상황을 누설한 혐의를 받는다. 검찰은 사안의 중대성을 고려해 경찰의 자체 비위 수사와 별도로 이번 사안을 직접 수사하기로 했다. 앞서 광주경찰청은 장윤기 사건 부실수사를 규명하기 위한 수사전담팀을 편성했고 전날 사건을 담당했던 광산서 소속 수사팀장을 증거인멸 혐의로 긴급 체포한 상태다. 경찰은 장윤기에게 살인 등', '검찰이 ‘여고생 살해’ 장윤기(23) 사건 관련, 부실수사 의혹이 일고 있는 광주 광산경찰서에 대한 압수수색에 나섰다. 검찰은 현직 경찰인 장윤기 아버지와 수사팀 간 유착 의혹 등을 들여다볼 전망이다.7일 오전 광주지검은 장윤기 사건을 담당했던 광주 광산경찰서에 수사관을 보내 압수수색 영장을 집행하고 있다. 검찰은 사건 담당 형사들의 주거지도 압수수색 중이다. 광산서 소속 경찰관들은 5월 5일 장윤기를 긴급체포한 뒤 검찰 송치까지 수사 과정에서 케이블타이·리얼돌·차량(SUV) 등 주요 증거물을 확보하지 않고, 현직 경찰인 장윤기 아버지에게 압수수색·구속영장 내용 등 수사 상황을 누설한 혐의를 받는다. 검찰은 사안의 중대성을 고려해 경찰의 자체 비위 수사와 별도로 이번 사안을 직접 수사하기로 했다. 앞서 광주경찰청은 장윤기 사건 부실수사를 규명하기 위한 수사전담팀을 편성했고 전날 사건을 담당했던 광산서 소속 수사팀장을 증거인멸 혐의로 긴급 체포한 상태다. 경찰은 장윤기에게 살인 등', 'rss', '동아일보', '2026-07-07 10:31:00', '보수', 'crawl_failed', 'https://dimg.donga.com/wps/NEWS/IMAGE/2026/07/07/134248195.1.jpg', '2026-07-07 06:04:35', '2026-07-07 17:27:48.909982', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3600, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Politics/article/all/20260707/134249563/1', '정치', '與, 보완수사권 폐지 속도…서영교 “전대 이후로 넘기기 어려울 것”', '국회 법제사법위원장을 맡고 있는 더불어민주당 서영교 의원이 7일 검찰의 보완수사권 폐지 등을 골자로 한 형사소송법 개정안 처리 시점과 관련해 “전당대회 이후로 넘어가기는 어렵지 않을까 생각한다”고 말했다. 민주당은 다음달 17일 차기 지도부 선출을 위한 전당대회를 치르게 되는데, 그 전에 입법이 완료될 것이란 취지다.서 의원은 이날 KBS 라디오 전격시사에 출연해 “중대범죄수사청과 공소청이라는 조직이 10월 2일에 출범한다면 이로부터 6개월 전 정도에는 절차법인 형사소송법은 입법이 거의 완료됐어야 한다”며 이렇게 말했다. 서 의원은 “(현재 시점에서 10월 2일까지) 남은 게 이제 2개월 반 정도 되기 때문에 (형소법 개정을) 최대한 빠르게 해나간다는 말씀을 드린다”며 “(검찰개혁을) 속도감 있게 진행할 것”이라고 말했다.서 의원은 검찰의 보완수사요구권과 관련해선 “(보완 수사를 이행해야 할 시기를) 한 달이면 한 달, 조금 더 연장을 하더라도 기본적으로 빠르게 보완 수사를 할', '올 3월 서울 여의도 국회에서 열린 제433회 국회(임시회) 윤석열 정권 정치검찰 조작기소 의혹 사건 진상규명 국정조사특별위원회 회의에서 더불어민주당 소속 서영교 특위 위원장이 의사봉을 두드리고 있다. 뉴스1 국회 법제사법위원장을 맡고 있는 더불어민주당 서영교 의원이 7일 검찰의 보완수사권 폐지 등을 골자로 한 형사소송법 개정안 처리 시점과 관련해 “전당대회 이후로 넘어가기는 어렵지 않을까 생각한다”고 말했다. 민주당은 다음달 17일 차기 지도부 선출을 위한 전당대회를 치르게 되는데, 그 전에 입법이 완료될 것이란 취지다. 서 의원은 이날 KBS 라디오 전격시사에 출연해 “중대범죄수사청과 공소청이라는 조직이 10월 2일에 출범한다면 이로부터 6개월 전 정도에는 절차법인 형사소송법은 입법이 거의 완료됐어야 한다”며 이렇게 말했다. 서 의원은 “(현재 시점에서 10월 2일까지) 남은 게 이제 2개월 반 정도 되기 때문에 (형소법 개정을) 최대한 빠르게 해나간다는 말씀을 드린다”며 “(검찰개혁을) 속도감 있게 진행할 것”이라고 말했다. 서 의원은 검찰의 보완수사요구권과 관련해선 “(보완 수사를 이행해야 할 시기를) 한 달이면 한 달, 조금 더 연장을 하더라도 기본적으로 빠르게 보완 수사를 할 수 있게 하는 장치가 중요하다”며 “경찰이 수사를 제대로 하지 않을 경우에 대한 대책도 만들어 놓고 있다”고 말했다. 서 의원은 또 수사심의위원회 실질화, 인권보호국 설치 등을 통해 경찰의 부실수사 등을 견제할 수 있다고 밝혔다. 한편 서 의원은 투표용지 부족 사태를 수사하게 될 선관위 특검의 특검 추천 방식에 대해선 “이걸 왜 야당이 추천해야 되느냐”며 “독립적인 기관이기 때문에 제3자 추천 방식이 올바르다고 생각한다”고 말했다.', 'crawl', '동아일보', '2026-07-07 10:21:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134250740.1.thumb.jpg', '2026-07-07 06:04:35', '2026-07-07 17:27:56.006431', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3604, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Politics/article/all/20260707/134249326/2', '정치', '김민석 “이성윤 감기약 발언, 국힘서 얘기한 줄…대장동 보는 듯”', '더불어민주당 당대표 출마를 선언한 김민석 전 국무총리가 7일 자신을 향한 이성윤 민주당 의원의 일명 ‘감기약 발언’에 대해 “국민의힘에서 누가 얘기하나 생각했다”며 비판했다. 앞서 친청(친정청래계) 이 의원은 2024년 12월 계엄 해제 표결 당시 김 전 총리가 복용했다는 감기약의 성분을 캐물으며 불참 의혹을 제기했다.김 전 총리는 이날 오전 KBS 라디오 전격시사에 출연해 이 의원을 향해 “”꼭 대장동 때를 보는 것 같다“며 ”‘저런 식으로 정치를 하면 좀 어려워질 텐데’ 라고 생각하고 있다“고 말했다. 2022년 대선을 앞두고 이재명 대통령과 당내 경선에서 맞붙었던 이낙연 전 국무총리가 대장동 개발비리의혹을 제기하며 내분이 불거진 상황이 떠오른다는 것이다. 이 의원은 전날 페이스북에 ”윤석열 계엄 해제 국회 표결에는 불참했는데, 왜 국회 표결에 참여하지 않았느냐“며 ”감기약을 드시고 주무셨다고 하는데 그 감기약 성분이 무엇이냐“고 의혹을 제기한 바 있다. 김 전 총리는 이에', '친청 “계엄 해제때 표결 불참” 공세에 金 “허위 사실 유포…국회 안에 있었다 그런식으로 정치하면 좀 어려워질 것” 박범계도 李겨냥 “이게 그분 인격이냐” 김민석 전 국무총리가 6일 오전 전남광주통합특별시 동구 전일빌딩 245에서 더불어민주당 대표 선거 출마 선언을 하며 주먹 쥔 손을 들어보이고 있다. 더불어민주당 당대표 출마를 선언한 김민석 전 국무총리가 7일 자신을 향한 이성윤 민주당 의원의 일명 ‘감기약 발언’에 대해 “국민의힘에서 누가 얘기하나 생각했다”며 비판했다. 앞서 친청(친정청래계) 이 의원은 2024년 12월 계엄 해제 표결 당시 김 전 총리가 복용했다는 감기약의 성분을 캐물으며 불참 의혹을 제기했다. 김 전 총리는 이날 오전 KBS 라디오 전격시사에 출연해 이 의원을 향해 “”꼭 대장동 때를 보는 것 같다“며 ”‘저런 식으로 정치를 하면 좀 어려워질 텐데’ 라고 생각하고 있다“고 말했다. 2022년 대선을 앞두고 이재명 대통령과 당내 경선에서 맞붙었던 이낙연 전 국무총리가 대장동 개발비리의혹을 제기하며 내분이 불거진 상황이 떠오른다는 것이다. 이 의원은 전날 페이스북에 ”윤석열 계엄 해제 국회 표결에는 불참했는데, 왜 국회 표결에 참여하지 않았느냐“며 ”감기약을 드시고 주무셨다고 하는데 그 감기약 성분이 무엇이냐“고 의혹을 제기한 바 있다. 김 전 총리는 이에 대해 ”허위사실에 의한 명예훼손“이라며 ”표결하는 그 시점에 국회 안에 있었다“고 반박했다. 김 전 총리는 이날 당권 경쟁주자인 정청래 전 대표에 대한 비판도 이어갔다. 김 전 총리는 ”지난 1년 동안 국정 지지를 정당 지지로 연결하지 못한 건 사실이고, 국정 지지를 선거 직전에서의 선거 예측과 달리 선거 결과로 연결하지 못한 것도 사실“이라며 ”정치는 일단 결과에 책임을 지는 것이기 때문에, 통상 그 자체로 계속해서 일을 할 수 있는 상황보다는 바뀌어야 하는 근거가 된다“고 책임론을 제기했다. ‘친이재명계(친명계)’로 김 전 총리를 지지하는 것으로 알려진 박범계 의원 역시 친청계 비판에 가세했다. 박 의원은 이날 YTN라디오 ‘장성철의 뉴스 명당’ 인터뷰에서 이 의원을 향해 ”이게 그분 인격이냐, 깜짝 놀랐다“고 질타했다. 박 의원은 이어 ”이렇게 막 가면 안 된다. 나중에 어떻게 같이 보려 하냐, 김 전 총리도 지적했듯이 팩트도 안 맞다“고도 했다. 앞서 친명계 강득구 최고위원도 전날 페이스북을 통해 ”무소속 한동훈 의원도 똑같은 논리로 김 전 총리의 그날 밤 행적을 캐물었다. 이런 말꼬투리 잡기식 문제 제기를, 우리 당 최고위원이 그대로 되풀이하고 있다“며 ”지켜야 할 선이 있다“고 지적했다.', 'crawl', '동아일보', '2026-07-07 09:56:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134250740.1.thumb.jpg', '2026-07-07 06:04:36', '2026-07-07 17:28:20.723005', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3605, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Economy/article/all/20260707/134248978/2', '정치', '구윤철 “메가 프로젝트 근로자, 세금 감면 추진…자녀 교육비도 검토”', '구윤철 부총리 겸 재정경제부 장관이 이달 말 부동산 세제 개편안 발표를 예고하며 “(보유세와 거래세) 두 가지가 밸런스(균형)을 이뤄야한다”고 말했다.7일 구 부총리는 MBC 라디오 ‘김종배의 시선집중’ 인터뷰에서 “7월 말 정도 (발표를) 생각으로 준비 중”이라며 이같이 밝혔다. 구 부총리는 “기본적으로 집은 ‘바잉(매수)이 아닌 리빙(거주)’이라는 원칙하에 실거주자 중심으로 주택 시장이 확립될 수 있도록 보고 있다”며 “정부가 일방적으로 결정하는 것이 아니라 조만간 제가 국민 의견, 현장 목소리를 듣고 최종 정부 방침을 결정할 것”이라고 설명했다. 구 부총리는 공정시장가액비율 조정, 비거주 장기보유특별공제 혜택 축소 등 부동산세 개편 방향에 관한 여러 보도에 관한 질문에 “그 부분도 국민의 한 의견인 만큼 살펴보겠다”고 즉답을 피했다.구 부총리는 정부가 추진 중인 ‘3대 메가 프로젝트’에 관해선 “ 총력전, 속도전으로 간다면 대한민국에 엄청난 기회가 될 것”이라며 “지방에', '“7월말 부동산 세제 발표 보유-거래세 균형 맞출 것” 구윤철 경제부총리 겸 재정경제부 장관이 지난달 18일 서울 종로구 정부서울청사에서 열린 민생물가 특별관리 관계장관 TF회의에서 모두발언을 하고 있다. 구윤철 부총리 겸 재정경제부 장관이 이달 말 부동산 세제 개편안 발표를 예고하며 “(보유세와 거래세) 두 가지가 밸런스(균형)을 이뤄야한다”고 말했다. 7일 구 부총리는 MBC 라디오 ‘김종배의 시선집중’ 인터뷰에서 “7월 말 정도 (발표를) 생각으로 준비 중”이라며 이같이 밝혔다. 구 부총리는 “기본적으로 집은 ‘바잉(매수)이 아닌 리빙(거주)’이라는 원칙하에 실거주자 중심으로 주택 시장이 확립될 수 있도록 보고 있다”며 “정부가 일방적으로 결정하는 것이 아니라 조만간 제가 국민 의견, 현장 목소리를 듣고 최종 정부 방침을 결정할 것”이라고 설명했다. 구 부총리는 공정시장가액비율 조정, 비거주 장기보유특별공제 혜택 축소 등 부동산세 개편 방향에 관한 여러 보도에 관한 질문에 “그 부분도 국민의 한 의견인 만큼 살펴보겠다”고 즉답을 피했다. 구 부총리는 정부가 추진 중인 ‘3대 메가 프로젝트’에 관해선 “ 총력전, 속도전으로 간다면 대한민국에 엄청난 기회가 될 것”이라며 “지방에 근무하는 분들에게는 세금을 차등지원하는 방법까지도 추진해서 총력 지원할 것”이라고 밝혔다. 그러면서 “지방에 근무하다보면 환경이 열악하지 않나. 서울보다 세금 감면을 더 해준다는 것”이라며 “그래서 지방 가시는 분들이 즐거운 마음으로 가서 일하면 지역 발전이 이뤄지고 그곳에서 또 세금이 더 들어오지 않겠나”라고 말했다. 자녀 교육비 지원에 대해서도 “경우에 따라 검토할 수 있다고 생각한다”고 덧붙였다. 다른 업종의 근로자들이 상대적 박탈감을 느낄 수 있다는 지적에 대해선 “(근로자들이) 주로 수도권에서 일하려 한다“며 ”초기에 (비수도권에) 가면 기반도 조성이 잘 안돼 있고 어려운 여건인 점을 감안할 부분”이라고 밝혔다. 그러면서 “(세제 지원을) 계속한다는 건 아니다. 기반이 조성될 때까지 하는 등 여러 고민을 하고 있다”고 했다. 기업에 대한 세제지원에 대해서는 “반도체, 인공지능(AI) 쪽은 최고의 세제지원을 해주고 있다”며 “연구개발(R&D) 투자 지원을 해주려고 하고, 이익이 생겨서 지금은 내더라도 나중에 세금을 못내는 시절이 오면 이월공제까지 해주려고 한다”고 전했다. 그는 정부가 초과세수를 활용해 신설하는 ‘미래대응기금’에 대해서는 “미래대응기금은 그야말로 미래를 위한 준비에 사용될 것”이라며 “재정 여력을 속도감 있게 쓰는 측면도 있어야 하고, 특정 분야에 쓸 필요도 있다. 내부적으로 검토 중에 있다”고 말했다.', 'crawl', '동아일보', '2026-07-07 09:20:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134249031.1.thumb.jpg', '2026-07-07 06:04:36', '2026-07-07 17:28:33.532328', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3608, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Politics/article/all/20260707/134248715/1', '정치', '‘튀르키예·몽골 순방’ 李대통령 “세계 평화·안보에 기여하는 나라 됐다”', '북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국하는 이재명 대통령은 7일 “나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가겠다”고 밝혔다.이 대통령은 이날 오전 엑스(X·구 트위터)에 올린 글에서 “마르크 뤼터 나토 사무총장의 초청을 받아 나토 정상회의가 열리는 튀르키예로 향한다”며 이같이 적었다.이 대통령은 “지난달 주요 7개국(G7) 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다”고 강조했다.이어 뤼터 사무총장이 최근 “한국을 사랑한다”며 우리 방위산업 기반을 “환상적”이라고 평가한 점을 언급하면서 “전쟁의 폐허를 딛고 나라를 지키기 위해 흘린 수많은 땀방울이 오늘날 세계가 인정하는 경쟁력이 됐다는 것이 참으로 자랑스럽다”고 했다.이 대통령은 “오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계 평화와 안보에 책임 있게 기여하는 나라가 됐다”며 “국민 여러분께 더 큰 자부', '취임 후 첫 나토 정상회의…“G7 이어 국제사회 책임 있는 기여” “뤼터 총장, 한국 방산 ‘환상적’ 평가…세계가 인정하는 경쟁력” 이재명 대통령이 6일 청와대에서 열린 메가프로젝트 민관합동 점검회의에서 발언하고 있다. (청와대통신사진기자단) 2026.7.6 ⓒ 뉴스1 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국하는 이재명 대통령은 7일 “나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가겠다”고 밝혔다. 이 대통령은 이날 오전 엑스(X·구 트위터)에 올린 글에서 “마르크 뤼터 나토 사무총장의 초청을 받아 나토 정상회의가 열리는 튀르키예로 향한다”며 이같이 적었다. 이 대통령은 “지난달 주요 7개국(G7) 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다”고 강조했다. 이어 뤼터 사무총장이 최근 “한국을 사랑한다”며 우리 방위산업 기반을 “환상적”이라고 평가한 점을 언급하면서 “전쟁의 폐허를 딛고 나라를 지키기 위해 흘린 수많은 땀방울이 오늘날 세계가 인정하는 경쟁력이 됐다는 것이 참으로 자랑스럽다”고 했다. 이 대통령은 “오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계 평화와 안보에 책임 있게 기여하는 나라가 됐다”며 “국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다”고 밝혔다. 이 대통령이 나토 정상회의에 참석하는 건 취임 후 처음이다. 이 대통령은 지난해에도 나토 정상회의 참석을 검토했으나 중동정세 등을 고려해 불참했다. 나토 측은 2022년부터 아시아·태평양 지역 국가들과의 협력을 강화하기 위해 한국·일본·뉴질랜드·호주 등 4개국 대표(IP4)를 정상회의에 초청하고 있다. 이 대통령은 이후 오흐나 후렐수흐 몽골 대통령의 초청에 따라 몽골을 국빈 방문한다. 이번 몽골 방문은 15년 만에 이뤄진 한국 대통령의 국빈 방문이다. (서울=뉴스1) 韓총리 “표현 자유 최대한 보장…조작·허위정보엔 단호히 대응” “캐나다 총리, 지난 주말 李에 “실망감 이해”… ‘잠수함 불발’ 통화” 광주 군공항 부지에 삼성-SK 반도체 팹 짓는다 1 47세 미혼 신봉선 노후 준비법 “20대부터 월 10