INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3612, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Politics/article/all/20260707/134248014/2', '정치', '광주 군공항 부지에 삼성-SK 반도체 팹 짓는다', '청와대는 6일 삼성전자와 SK하이닉스가 호남권 반도체 공장(팹) 4기를 광주 군공항 부지에 건설하기로 했다고 밝혔다. 청와대는 경기 용인에 조성 중인 팹 10기 규모의 반도체 클러스터 완공 일정도 최대한 앞당기겠다고 했다. 이재명 대통령은 “국운이 걸린 총력 경쟁이 벌어지고 있다”며 “오직 속도전이 중요하다”고 강조했다. 강훈식 대통령비서실장은 이날 청와대에서 이 대통령 주재로 열린 메가 프로젝트 민관합동 점검회의 이후 브리핑을 통해 “군공항 부지에 호남 반도체 산단을 조성하기로 결정했다”고 밝혔다. 강 실장은 “광주 군공항 지역은 250만 평(약 826만 m²) 규모의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료돼 부지 공사 기간을 최소화할 수 있다”며 “광주 도심과 KTX역에 인접해 있어 인력 확보와 정주 여건에서도 강점이 있으며 도로, 공항, 항만 등과 연계한 물류 접근성도 우수하다”고 강조했다. 정부는 군공항 기지를 활용할 경우 토지 수용에 필요한 기간을 대폭 줄일', '靑, 광주 클러스터 조성 지역 발표 공사기간-교통-정주 여건 등 강점 李 “국운 걸린 경쟁… 오직 속도전” 용인팹 완공도 최대한 앞당기기로 청와대는 6일 삼성전자와 SK하이닉스가 호남권 반도체 공장(팹) 4기를 광주 군공항 부지에 건설하기로 했다고 밝혔다. 청와대는 경기 용인에 조성 중인 팹 10기 규모의 반도체 클러스터 완공 일정도 최대한 앞당기겠다고 했다. 이재명 대통령은 “국운이 걸린 총력 경쟁이 벌어지고 있다”며 “오직 속도전이 중요하다”고 강조했다. 강훈식 대통령비서실장은 이날 청와대에서 이 대통령 주재로 열린 메가 프로젝트 민관합동 점검회의 이후 브리핑을 통해 “군공항 부지에 호남 반도체 산단을 조성하기로 결정했다”고 밝혔다. 강 실장은 “광주 군공항 지역은 250만 평(약 826만 m²) 규모의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료돼 부지 공사 기간을 최소화할 수 있다”며 “광주 도심과 KTX역에 인접해 있어 인력 확보와 정주 여건에서도 강점이 있으며 도로, 공항, 항만 등과 연계한 물류 접근성도 우수하다”고 강조했다. 정부는 군공항 기지를 활용할 경우 토지 수용에 필요한 기간을 대폭 줄일 수 있다는 판단이다. 이날 회의에 참석한 삼성전자와 SK하이닉스 측도 모두 군공항 부지가 신규 팹이 들어서기에 가장 적합한 곳이라는 의견을 밝혔다. 군공항 부지는 또 다른 후보지였던 첨단3지구(110만 평)의 두 배가 넘는 만큼 확장성에 장점이 있다는 것이다. 이 대통령은 이날 광주는 물론 용인 반도체 클러스터 조기 완공을 위한 행정 절차와 규제 완화를 강조했다. 이 대통령은 환경영향평가에 대해 “같은 지역인데 굳이 또다시 할 필요가 있느냐. 이미 (평가가) 있다면 그 결과를 원용하는 게 중요하다”며 “새로 실시하게 되더라도 기간을 대폭 단축할 필요가 있다”고 했다. 토지 수용 과정에서 빚어지는 소위 ‘알박기’ 논란 등에 대해서는 “협의 취득과 강제 수용 절차를 동시에 시작하도록 하라”면서 “불법이 아닌 한 병행 추진하도록 그렇게 했으면 좋겠다. 만약 규정에 문제가 있다면 입법으로 해결해야 된다”고 했다. 이에 따라 기후에너지환경부는 광주 반도체 클러스터에 대해선 인근 지역 환경영향평가 결과를 적용해 기간을 줄이겠다고 밝혔다. 또 용인 반도체 클러스터와 관련해 강 실장은 “토지 보상부터 전력 용수 공급까지 전반적인 일정을 최대한 앞당겠다”고 밝혔다.', 'crawl', '동아일보', '2026-07-07 04:30:00', '보수', 'ready', 'https://dimg.donga.com/a/232/131/95/1/wps/NEWS/IMAGE/2026/07/07/134247820.5.jpg', '2026-07-07 06:04:36', '2026-07-07 17:29:27.972866', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3615, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Politics/article/all/20260707/134248020/2', '정치', '광주 군공항 평지에 국유지, 빠른 사업 기대… ‘비행단 이전’ 변수', '강훈식 대통령비서실장은 6일 삼성전자와 SK하이닉스의 총 800조 규모 광주 반도체 전공정 팹(Fab·제조공장) 4기 부지로 광주 군공항을 결정한 것에 대해 “기업들이 호남권 입지 후보지 중 광주 군공항이 가장 적합한 부지라는 의견을 제시했다”고 밝혔다. 정부와 기업이 지난달 29일 ‘3대 메가 프로젝트’를 발표한 지 일주일 만에 핵심 사업인 호남권 반도체 클러스터 부지를 결정하면서 ‘반도체 속도전’을 본격화한 것. 다만 광주 군공항 예비 이전 후보지인 무안군이 민간공항 선(先)이전과 국가 차원의 인센티브, 1조 원 규모 지원 사업 등을 요구하고 있는 점 등이 변수가 될 것이란 전망이 나온다.● 靑 “광주 군공항, 공사 기간 최소화 장점”강 실장은 이날 청와대에서 열린 ‘메가 프로젝트 민관 합동 점검회의’ 후 브리핑을 열고 “광주 군공항 지역은 250만 평(약 826만 m²) 규모의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료돼 있는 만큼 부지 공사 기간을 최소화할 수', '평탄화 완료 공사기간 단축 가능… 토지수용 리스크 적고 정주 여건도 靑 “기업들 적합부지로 의견제시” 군공항 이전지 무안군 설득이 관건… 10월 주민투표 후 11월 확정 검토 李 “반도체 입지, 강제수용도 추진” 반도체 클러스터 지을 광주 군공항 정부가 6일 광주 반도체 클러스터를 조성하기로 발표한 전남광주통합특별시 군공항 부지 전경. 청와대는 약 826만 m²(약 250만 평) 규모의 부지를 확보할 수 있고, 이미 평탄화가 완료돼 부지 공사 기간을 최소화할 수 있는 데다 광주 도심과 KTX 역이 인접해 인력 확보와 정주 여건 측면에서 강점이 있다는 점 등을 고려했다고 설명했다. 강훈식 대통령비서실장은 6일 삼성전자와 SK하이닉스의 총 800조 규모 광주 반도체 전공정 팹(Fab·제조공장) 4기 부지로 광주 군공항을 결정한 것에 대해 “기업들이 호남권 입지 후보지 중 광주 군공항이 가장 적합한 부지라는 의견을 제시했다”고 밝혔다. 정부와 기업이 지난달 29일 ‘3대 메가 프로젝트’를 발표한 지 일주일 만에 핵심 사업인 호남권 반도체 클러스터 부지를 결정하면서 ‘반도체 속도전’을 본격화한 것. 다만 광주 군공항 예비 이전 후보지인 무안군이 민간공항 선(先)이전과 국가 차원의 인센티브, 1조 원 규모 지원 사업 등을 요구하고 있는 점 등이 변수가 될 것이란 전망이 나온다. ● 靑 “광주 군공항, 공사 기간 최소화 장점” 강 실장은 이날 청와대에서 열린 ‘메가 프로젝트 민관 합동 점검회의’ 후 브리핑을 열고 “광주 군공항 지역은 250만 평(약 826만 m²) 규모의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료돼 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있다”며 이같이 밝혔다. 이어 “부동산이 들썩거린다는 보고가 있었다”며 “무엇보다 광주 군공항은 국유지이기 때문에 (토지 수용) 리스크가 많이 없다”고 했다. 광주 도심과 KTX 광주송정역과 가까워 인력 확보와 정주 여건 측면에서 강점이 있고 도로, 공항, 항만 등 우수한 연계 물류 접근성도 고려됐다고 한다. 광주 군공항은 전남광주통합특별시 광산구에 있는 공군 제1전투비행단 부지로 현재 공군과 민간 항공 등이 함께 활주로를 사용하고 있다. 군공항이 이전하면 활주로와 비행장, 탄약고 등을 포함한 약 250만 평의 대규모 부지가 확보된다. 김용범 정책실장은 이날 YTN 라디오에서 “공항만 이전하거나, 아니면 비행기만 다른 공항으로 보내면 바로 땅을 쓸 수 있다”고 했다. 반도체 기업들도 호남권 반도체 클러스터 후보지 중 군공항 부지를 최우선으로 고려해 왔다. 여의도 면적(약 290만 m²)의 3배 규모로 또 다른 유력 후보지였던 첨단3지구(362만 m²)의 두 배가 넘어 대규모 팹이 들어서기에 적합하다는 것. 인근 탄약고 부지를 활용해 팹 1, 2기를 우선 건설하는 방안도 제기된다. 반도체 업계에선 전력·용수 확보라는 과제가 남았다는 목소리도 나온다. 전력의 경우 팹 4기가 완전 가동되면 6.3GW(기가와트)가 필요해 기존 발전만으론 빠듯하다는 것이다. 이에 따라 정부는 신규 원전 건설을 검토하는 동시에 변전소와 송전선로 신설, 재생에너지 활용 등으로 전력을 공급할 계획이다. 산업 용수는 하루 65만 t이 필요한 것으로 추산된다. 정부는 신규 댐 건설 없이 기존 댐 증강과 하수 재이용수 활용 등으로 충분히 확보할 수 있다고 보고 있다. 또 호남 반도체 공장이 첫 삽을 뜨기 위해서는 현재 광주 군공항을 사용하고 있는 공군 제1전투비행단도 이전해야 한다. 정부와 광주특별시는 10월 중 주민 투표를 거쳐 11월까지 무안군 망운면 일대를 군공항 이전 후보지로 확정하는 방안을 추진 중이다. 군공항 부지로 이전할 계획이었던 광주특별시 마륵동 탄약고는 다른 새 부지를 찾아야 하는 상황이다. 군공항 이전 방식을 손봐야 한다는 지적도 나온다. 신공항 완공 전에 종전 부지를 활용할 수 있도록 국유재산법을 정비해 ‘선양여’가 가능하도록 해야 한다는 것이다. 일각에선 군공항 이전에 따른 안보 공백 우려도 제기된다. 이에 대해 강 실장은 “안보 공백이 발생하지 않는 범위 안에서 조기에 옮기겠다는 것이 전제돼 있다”고 했다. ● 李 “반도체 부지 협의 취득·강제 수용 동시 추진” 청와대는 현재 건설 중인 용인 클러스터 추진 속도도 더 높일 방침이다. 강 실장은 이날 용인 반도체 클러스터 조성과 관련해 “기업들의 요청에 따라 당초 계획된 팹 10기 투자가 훨씬 빠른 속도로 추진될 수 있도록 토지 보상부터 전력, 용수 공급까지 전반적인 일정을 최대한 앞당기기로 했다”고 말했다. SK하이닉스의 경기 용인 반도체 클러스터는 토지 보상과 인허가를 거쳐 착공까지 6년이 걸렸다. 삼성전자의 용인 국가 산단 부지는 현재 토지 보상 절차가 진행 중이다. 이재명 대통령은 모두발언에서 “6년이 나름 빠르다고 할 수 있지만 제 기준으로는 그렇게 빠른 것 같지 않다”고 지적했다. 이어 토지 취득 과정에 대해 “버티는 알박기가 있으면 협의에 엄청나게 많은 시간을 소요하고 안 되면 마지막에 가서야 비로소 강제 수용 절차를 시작한다”며 “협의 취득과 강제 수용 절차를 동시에 시작하도록 하라”고 지시했다.', 'crawl', '동아일보', '2026-07-07 04:30:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134250076.3.thumb.png', '2026-07-07 06:04:36', '2026-07-07 17:30:05.121352', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3620, 'https://rss.donga.com/politics.xml', NULL, 'https://www.donga.com/news/Politics/article/all/20260707/134248045/2', '정치', '與 “보완수사권 폐지, 재논의 사항 아니다”', '보완수사권 전면 폐지를 두고 더불어민주당 내부에서도 우려의 목소리가 나오는 가운데 민주당 지도부가 8·17 전당대회 전 보완수사권 폐지를 담은 형사소송법 개정안 처리 방침을 못 박았다.김한규 원내정책수석부대표는 6일 서울 여의도 국회에서 기자들과 만나 “보완수사권 예외적 필요가 있다고 주장하시는 분들이 있긴 하지만 아주 일부”라며 “보완수사권 폐지에 대해서 지금 다시 하냐 마냐는 논의할 사항이 전혀 아니다”라고 밝혔다. 특히 김 원내수석은 형사소송법 개정안 처리 시점에 대해 “전당대회 이후에 처리할 계획은 없다”며 “빨리 처리하면 당연히 그(전당대회) 전에 처리하는 게 나을 것 같다”고 밝혔다. 다만 “(관계법 개정안의) 분량이 많아서 물리적으로 소요되는 시간이 있고 중요한 문제라 정밀하게 검토해야 된다”고 덧붙였다.김민석 전 국무총리와 송영길, 정청래 전 대표 등 당권 주자들이 전당대회를 앞두고 보완수사권 폐지를 두고 공방을 벌이고 있는 가운데 당내 이견이 확산되는 것을 차단', '당내 우려에도 전대前 처리 강조 檢 “심각한 우려” 의견서 내기로 김한규 더불어민주당 정책수석부대표가 13일 서울 여의도 국회에서 열린 원내대책회의에서 발언하고 있다. 2026.01.13 보완수사권 전면 폐지를 두고 더불어민주당 내부에서도 우려의 목소리가 나오는 가운데 민주당 지도부가 8·17 전당대회 전 보완수사권 폐지를 담은 형사소송법 개정안 처리 방침을 못 박았다. 김한규 원내정책수석부대표는 6일 서울 여의도 국회에서 기자들과 만나 “보완수사권 예외적 필요가 있다고 주장하시는 분들이 있긴 하지만 아주 일부”라며 “보완수사권 폐지에 대해서 지금 다시 하냐 마냐는 논의할 사항이 전혀 아니다”라고 밝혔다. 특히 김 원내수석은 형사소송법 개정안 처리 시점에 대해 “전당대회 이후에 처리할 계획은 없다”며 “빨리 처리하면 당연히 그(전당대회) 전에 처리하는 게 나을 것 같다”고 밝혔다. 다만 “(관계법 개정안의) 분량이 많아서 물리적으로 소요되는 시간이 있고 중요한 문제라 정밀하게 검토해야 된다”고 덧붙였다. 김민석 전 국무총리와 송영길, 정청래 전 대표 등 당권 주자들이 전당대회를 앞두고 보완수사권 폐지를 두고 공방을 벌이고 있는 가운데 당내 이견이 확산되는 것을 차단하기 위한 것으로 풀이된다. 다만 최근 민주당 의원 단체대화방에서는 “경찰의 기소 의견 송치 사건에 한해 보완수사를 인정하자”는 등 주장이 제기되며 보완수사권 폐지에 따른 보완책 마련이 필요하다는 목소리가 나오고 있는 상황이다. 한편 대검찰청은 최근 보완수사권 전면 폐지 내용을 담은 형사소송법 개정안에 대해 “심각한 우려가 있다”는 취지의 의견서를 국회에 제출할 예정이다. 앞서 지난달 민주당 김용민 의원, 조국혁신당 박은정 의원 등이 형사소송법 개정안을 발의하자 국회는 개정안에 대한 의견 제출을 검찰에 요청한 바 있다.', 'crawl', '동아일보', '2026-07-07 04:30:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134252247.1.thumb.jpg', '2026-07-07 06:04:36', '2026-07-07 17:31:08.159356', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3640, 'https://rss.donga.com/national.xml', NULL, 'https://www.donga.com/news/Society/article/all/20260707/134250675/1', '사회', '내일부터 다시 강한 장맛비…충남-전북 최대 200㎜', '8일부터 중부지방과 전라권을 중심으로 다시 강한 장맛비가 쏟아질 전망이다. 특히 8일 밤부터 9일 오전 사이 충남과 전북에는 최대 200㎜ 이상의 폭우가 예상되는 데다 강한 비가 취약 시간대인 밤사이 집중될 것으로 예상돼 철저한 대비가 필요하겠다.기상청은 7일 수시브리핑을 통해 정체전선 동향과 기온 전망을 발표했다. 이광연 기상청 예보분석관은 “북태평양고기압 가장자리에서 찬 공기와 정체전선이 대치하는 가운데 기압골이 주기적으로 남하하면서 강수시스템이 반복적으로 활성화하고 있다”고 설명했다.기상청에 따르면 8일 새벽부터 낮까지는 중부지방과 전라권을 중심으로 비가 내린 뒤, 8일 저녁 정체전선이 남하했다가 9일 오전 다시 북상하는 과정에서 충남과 전북에 비가 집중될 전망이다. 8, 9일 예상 강수량은 충남과 전북이 80~150㎜, 많은 곳은 200㎜ 이상이다. 경기 남부와 강원 중·남부 내륙, 충북은 50~100㎜, 많은 곳은 150㎜ 이상이 예상된다. 특히 8일 밤부터 9일 오전', '비가 내리고 있는 6일 오전 서울 종로구 세종대로 사거리에서 우산을 쓴 시민들이 이동하고 있다. 8일부터 중부지방과 전라권을 중심으로 다시 강한 장맛비가 쏟아질 전망이다. 특히 8일 밤부터 9일 오전 사이 충남과 전북에는 최대 200㎜ 이상의 폭우가 예상되는 데다 강한 비가 취약 시간대인 밤사이 집중될 것으로 예상돼 철저한 대비가 필요하겠다. 기상청은 7일 수시브리핑을 통해 정체전선 동향과 기온 전망을 발표했다. 이광연 기상청 예보분석관은 “북태평양고기압 가장자리에서 찬 공기와 정체전선이 대치하는 가운데 기압골이 주기적으로 남하하면서 강수시스템이 반복적으로 활성화하고 있다”고 설명했다. 기상청에 따르면 8일 새벽부터 낮까지는 중부지방과 전라권을 중심으로 비가 내린 뒤, 8일 저녁 정체전선이 남하했다가 9일 오전 다시 북상하는 과정에서 충남과 전북에 비가 집중될 전망이다. 8, 9일 예상 강수량은 충남과 전북이 80~150㎜, 많은 곳은 200㎜ 이상이다. 경기 남부와 강원 중·남부 내륙, 충북은 50~100㎜, 많은 곳은 150㎜ 이상이 예상된다. 특히 8일 밤부터 9일 오전 사이 충남과 전북에는 시간당 50㎜ 이상의 매우 강한 비가 쏟아질 것으로 예보됐다. 기상청은 짧은 시간에 많은 비가 내리면서 저지대 침수와 하천 범람, 산사태, 축대 붕괴 등의 피해가 발생할 수 있다며 배수로를 미리 정비하고 침수 우려 지역을 점검하는 등 사전 대비를 당부했다. 비가 내리는 동안에도 무더위는 이어질 전망이다. 정체전선을 따라 고온다습한 공기가 유입되면서 전국 대부분 지역의 최고 체감온도는 31도 안팎까지 오르겠고 경기남동부와 강원남부내륙, 충북중부, 전남남동부, 경상권, 제주도 일부 지역은 체감온도가 33도를 웃돌겠다. 제9호 태풍 ‘바비’는 북태평양고기압 남쪽 가장자리를 따라 이동해 11일경 대만 북쪽 해상을 지나 12일경 중국 동부 연안에 상륙할 것으로 예상된다. 이번 장맛비에 태풍의 직접적인 영향은 없을 것으로 보이지만, 태풍이 약화한 뒤 동아시아 기압계가 재배치되면서 다음 주 후반 강수가 확대될 가능성이 있는 만큼 최신 기상정보를 지속적으로 확인할 필요가 있다.', 'crawl', '동아일보', '2026-07-07 14:08:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134252146.1.thumb.jpg', '2026-07-07 06:04:36', '2026-07-07 17:40:20.928567', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3649, 'https://rss.donga.com/national.xml', NULL, 'https://www.donga.com/news/Society/article/all/20260707/134249948/1', '사회', '충청권 94㎜ 물벼락, 서울 18㎜…내일 최대 150㎜ 퍼붓는다', '화요일인 7일 오전 충청권을 중심으로 강한 비가 집중되며 일부 지역에는 100㎜에 가까운 비가 내렸다. 서울 등 수도권은 20㎜ 안팎의 비가 내렸고, 전국 대부분 지역은 오전 중 비가 소강상태를 보이는 곳이 많겠다. 오후에는 다시 소나기가 지나겠고, 8일부터 9일 사이에는 경기 남부와 충청권을 중심으로 더 많은 비가 예보됐다.7일 기상청에 따르면 이날 오전 9시 55분 기준 일 강수량은 충남 금산에서 93.7㎜(금산)로 전국에서 가장 많았다. 충북 영동에선 86.5㎜(가곡), 전북 익산 78.0㎜(함라), 충남 서천 68.5㎜(춘장대), 충북 옥천 66.5㎜, 전북 군산 62.6㎜, 경북 칠곡 61.5㎜ 등으로 집계됐다.서울에서는 강서구에 17.9㎜가 기록되며 자치구 중 가장 많은 비가 관측됐다. 은평 17.5㎜, 용산 14.0㎜, 구로 13.5㎜, 금천 13.0㎜ 등으로 뒤따랐다. 서울 공식 통계를 작성하는 종로구 관측지점의 강수량은 5.7㎜가 기록됐다.짧은 시간에 강한 비가', '9일 아침엔 경기 남부~전북 북부에 ‘집중호우’ 하천변·지하차도 ‘안전 유의’…접경지역 수위↑ ‘예의주시’ 7일 서울 광화문네거리에서 출근하는 시민들이 비가 내렸다 그치기를 반복하는 날씨 속에 우산을 손에 든 채 발걸음을 옮기고 있다. 장마철이지만 정체전선이 뚜렷하게 형성되지 않으면서 내륙 곳곳에서는 국지적으로 비가 오락가락하는 날씨가 이어지고 있다. 2026.7.7 뉴스1 화요일인 7일 오전 충청권을 중심으로 강한 비가 집중되며 일부 지역에는 100㎜에 가까운 비가 내렸다. 서울 등 수도권은 20㎜ 안팎의 비가 내렸고, 전국 대부분 지역은 오전 중 비가 소강상태를 보이는 곳이 많겠다. 오후에는 다시 소나기가 지나겠고, 8일부터 9일 사이에는 경기 남부와 충청권을 중심으로 더 많은 비가 예보됐다. 7일 기상청에 따르면 이날 오전 9시 55분 기준 일 강수량은 충남 금산에서 93.7㎜(금산)로 전국에서 가장 많았다. 충북 영동에선 86.5㎜(가곡), 전북 익산 78.0㎜(함라), 충남 서천 68.5㎜(춘장대), 충북 옥천 66.5㎜, 전북 군산 62.6㎜, 경북 칠곡 61.5㎜ 등으로 집계됐다. 서울에서는 강서구에 17.9㎜가 기록되며 자치구 중 가장 많은 비가 관측됐다. 은평 17.5㎜, 용산 14.0㎜, 구로 13.5㎜, 금천 13.0㎜ 등으로 뒤따랐다. 서울 공식 통계를 작성하는 종로구 관측지점의 강수량은 5.7㎜가 기록됐다. 짧은 시간에 강한 비가 쏟아진 곳도 충청권에 집중됐다. 60분 최대 강수량은 충남 금산 58.4㎜(금산), 전북 군산 48.5㎜(어청도), 충북 영동 46.0㎜(가곡), 충남 서천 44.5㎜(춘장대), 전북 무주 42.5㎜(무주), 충남 보령 40.4㎜(보령) 등이다. 전북 익산은 39.0㎜(함라), 충남 부여는 38.5㎜(양화), 경북 칠곡은 36.5㎜(팔공산), 경북 포항은 35.0㎜(청하), 충남 논산은 34.0㎜(논산), 충남 홍성은 33.9㎜(홍성)의 60분 최대 강수량을 기록했다. 서울에서는 강서구(김포공항)에서 1시간에 17.2㎜, 은평 17.0㎜의 시간당 강수량이 관측됐다. 오전 10시 기준 전국에선 장맛비가 소강상태를 보이고 있다. 충청권을 대부분에 발령됐던 호우 특보는 충북 영동과 대구 군위, 경북 영천·칠곡·김천 등 일부 지역을 제외하곤 모두 해제된 상태다. 이날 예상 강수량은 서울·인천·경기와 서해5도 20~60㎜다. 경기 북부와 서해5도에는 80㎜ 이상 내리는 곳도 있겠다. 강원 내륙·산지는 20~60㎜, 많은 곳은 강원 북부 내륙·산지 80㎜ 이상이다. 강원 동해안은 5~40㎜다. 대전·세종·충남과 충북은 20~60㎜, 전북은 5~40㎜, 광주·전남 북부는 5~10㎜, 경남 내륙과 대구·경북은 5~40㎜가 예상된다. 오후부터 저녁 사이에는 전국 대부분 지역에 소나기가 내리겠다. 소나기에 의한 예상 강수량은 서울·인천·경기 5~40㎜, 강원 내륙·산지 5~60㎜, 강원 동해안 5~40㎜다. 대전·세종·충남과 충북, 전북 북부, 경남 내륙, 대구·경북은 5~40㎜다. 소나기가 내리는 지역에서는 돌풍과 천둥·번개를 동반한 시간당 20㎜ 안팎의 강한 비가 내릴 수 있다. 소나기 특성상 같은 지역 안에서도 강수량 차이가 크게 나타날 수 있다. 8일부터 9일 사이에는 다시 전국 대부분 지역에 비가 내리겠다. 비는 8일 새벽부터 9일 저녁 사이 이어지겠고, 경기 북부와 강원 북부는 9일 늦은 밤까지 비가 계속되는 곳도 있겠다. 8~9일 예상 강수량은 서울·인천·경기와 서해5도 50~100㎜다. 경기 남부에는 150㎜ 이상 내리는 곳도 있겠다. 강원 내륙·산지도 50~100㎜, 강원 중·남부 내륙은 150㎜ 이상이 예상된다. 충청권은 대전·세종·충남과 충북에 50~100㎜가 내리겠고, 충남권과 충북 중·북부에는 150㎜ 이상 많은 비가 내리는 곳이 있겠다. 전북은 30~80㎜, 전북 북서부는 120㎜ 이상이다. 경북 북부 내륙도 30~80㎜, 많은 곳은 120㎜ 이상이 예상된다. 강한 비는 8일 이른 새벽부터 경기 북부와 서해5도, 강원 북부 내륙에 먼저 집중되겠다. 8일 저녁부터 9일 새벽 사이에는 경기 남부와 강원 중·남부 내륙·산지에 시간당 20~30㎜의 강한 비가 내릴 전망이다. 특히 9일 아침부터 낮 사이에는 경기 남부와 강원 중·남부 내륙·산지, 충청권, 전북 북부를 중심으로 시간당 30~50㎜의 매우 강한 비가 내릴 가능성이 있다. 기상청은 중부지방과 전북 북부, 경북 북서 내륙을 중심으로 호우특보가 발표될 가능성이 있다고 밝혔다. 비가 내리는 지역에서는 돌풍과 천둥·번개가 치겠다. 짧은 시간 강한 비가 쏟아지면 계곡과 하천 물이 갑자기 불어날 수 있어 접근과 야영을 피해야 한다. 하천변 산책로와 지하차도는 고립 위험이 있어 출입하지 않는 것이 좋다. 저지대 침수와 하천 범람, 급류, 하수도·우수관·배수구 역류에도 유의해야 한다. 강한 비로 토사 유출, 산사태, 낙석, 축대 붕괴가 발생할 수 있고 도로가 미끄럽거나 침수되는 곳도 있겠다. 북한 지역에도 많은 비가 내리면서 경기 북부와 강원 북부 인근 강 유역의 수위가 높아질 가능성이 있다. 임진강과 한탄강, 북한강 등 인근 하천에서는 유속이 빨라질 수 있어 안전사고에 주의해야 한다. 비가 내려도 더위는 계속되겠다. 7일 낮 최고기온은 27~34도, 8일 아침 최저기온은 21~25도, 낮 최고기온은 26~34도로 예보됐다. 경기 남동부와 강원 남부 내륙, 충북 중부, 전남 남동부, 경상권, 제주도 일부 지역에는 폭염특보가 발효 중이며, 폭염특보 지역은 최고체감온도가 33도 이상 오르는 곳이 있겠다. (세종=뉴스1) 1 47세 미혼 신봉선 노후 준비법 “20대부터 월 100만원 저축” 2 [오늘의 운세/7월 7일] 3 변진섭, 골프공으로 황영조 맞혔다…“뇌진탕에 50바늘” 4 잠수함 수주 실패, 장동혁은 “정부 책임”이라는데…韓 “최선 다 했다” 5 인천지검, ‘대북송금 수사’ 박상용 감찰…징계 수위 높아지나 6 김민석 맞받은 정청래…“총리가 ‘당대표 로망’ 말한게 자기정치” 7 3군 사관학교 통합 계획 발표, 100분전 돌연 취소한 국방부 8 “예전엔 잘 먹었는데…” 나이 들면 금방 배부른 이유 있었다 [노화설계] 9 ‘연어 술파티’ 증언 前KH부회장, 前연인 흉기위협·감금…징역 4년 10 혈당-염증 관리 돕는 ‘텃밭 보약’ 애호박[정