INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3674, 'https://rss.donga.com/national.xml', NULL, 'https://www.donga.com/news/Society/article/all/20260707/134248624/1', '사회', '합수본, 투표지 인쇄업자·서초구 선관위원 등 9명 무더기 소환', '6·3 지방선거 투표용지 부족 사태를 수사하는 검경 합동수사본부(본부장 김태훈 차장검사)가 인쇄업자와 선관위 관계자 등 9명을 무더기 소환한다.7일 법조계에 따르면 합수본은 이날 인쇄업자 1명을 참고인 신분으로 불러 조사한다.또 송파·강남·관악·서대문·강서·중랑·마포구 선관위 관계자 각 1명과 서초구 선관위원 1명을 참고인 신분으로 소환한다.합수본은 이들에게 투표용지가 언제부터 부족했는지를 비롯해 현장과 중앙선거관리위원회, 서울시 선관위 등 상급 위원회와 소통이 원활했는지 물을 것으로 보인다.또 투표용지 부족 가능성을 인지하고도 관련 대응 지침 등을 따르지 않았는지 등을 살필 것으로 전망된다.인쇄업자에게는 투표용지 인쇄 과정을 캐물을 것으로 보인다.합수본은 지난달 11일 중앙선관위와 서울시 선관위, 송파·강남·서초·광진·동작구 선관위 등 7곳을 대상으로 13시간에 걸친 전방위적 압수수색을 벌였다. 지난달 24일에는 서울시 선관위와 송파구 선관위 관계자 12명에 대해 압수수', '송파·강남·관악·서대문·강서·중랑·마포구 관계자도 9명 모두 참고인 신분 과천 중앙선거관리위원회 모습. ⓒ 뉴스1 6·3 지방선거 투표용지 부족 사태를 수사하는 검경 합동수사본부(본부장 김태훈 차장검사)가 인쇄업자와 선관위 관계자 등 9명을 무더기 소환한다. 7일 법조계에 따르면 합수본은 이날 인쇄업자 1명을 참고인 신분으로 불러 조사한다. 또 송파·강남·관악·서대문·강서·중랑·마포구 선관위 관계자 각 1명과 서초구 선관위원 1명을 참고인 신분으로 소환한다. 합수본은 이들에게 투표용지가 언제부터 부족했는지를 비롯해 현장과 중앙선거관리위원회, 서울시 선관위 등 상급 위원회와 소통이 원활했는지 물을 것으로 보인다. 또 투표용지 부족 가능성을 인지하고도 관련 대응 지침 등을 따르지 않았는지 등을 살필 것으로 전망된다. 인쇄업자에게는 투표용지 인쇄 과정을 캐물을 것으로 보인다. 합수본은 지난달 11일 중앙선관위와 서울시 선관위, 송파·강남·서초·광진·동작구 선관위 등 7곳을 대상으로 13시간에 걸친 전방위적 압수수색을 벌였다. 지난달 24일에는 서울시 선관위와 송파구 선관위 관계자 12명에 대해 압수수색하고 이들의 휴대전화 등을 확보했다. 합수본은 최근 ‘인사·예산 전담팀’을 꾸려 채용 비리와 외유성 출장 등 선관위의 추가 의혹 수사에도 속도를 내고 있다. 전담팀은 지난 1일 합류한 임홍석 창원지검 통영지청 부장검사(사법연수원 40기)가 이끈다. 임 부장검사는 다스 비자금 특별수사팀을 거친 ‘특수통’이다. 이번 주 합류하는 평검사 2명도 전담팀에 배정된다. 앞서 합수본은 지난달 30일 노태악 전 중앙선거관리위원장의 부부 동반 해외 출장 의혹과 관련해 고발인을 참고인 신분으로 조사했다. 노 전 위원장은 재임 중 배우자와 독일 및 스웨덴 등 해외 출장을 세 차례 다녀왔다. 그러나 배우자 동행 사실이 선관위 사후 보고서에는 기재되지 않아 횡령 의혹이 제기됐다. 선관위 공무원들도 지난 2023년 9월 ‘몰디브 대통령 선거 참관’을 명목으로 몰디브로 출장을 떠나 경비 1470만 원을 쓴 점이 드러나 고발 대상이 됐다. (서울=뉴스1) 유노윤호, 콘서트 장소 결국 변경…‘개표소 봉쇄 시위’ 장기화 여파 선관위 특검 ‘동상이몽’…與 “제3자 추천” 