INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3679, 'https://rss.donga.com/national.xml', NULL, 'https://www.donga.com/news/Society/article/all/20260707/134248012/2', '사회', '중동전쟁 틈타 폭리… 정유사 ‘14조 담합’', '국내 정유사의 기름값 담합 의혹을 수사해 온 검찰이 HD현대오일뱅크, SK에너지, GS칼텍스, 에쓰오일 등 4대 정유사 법인과 임직원 4명을 최소 14조2000억 원대 담합 혐의 등으로 재판에 넘겼다. 단일 담합 사건으로는 역대 최대 규모다. 특히 검찰 수사 결과 2월 28일 미국과 이스라엘의 공습으로 이란 전쟁이 발발한 직후 국내 기름값이 폭등한 건 불안정한 국제 정세 때문만이 아니라 정유사들의 가격 담합이 영향을 미쳤던 것으로 드러났다. 6일 서울중앙지검 공정거래조사부(부장검사 나희석)는 SK에너지와 담합해 서로 가격 정보를 교환하고 가격을 대폭 상승시키기로 합의한 HD현대오일뱅크 법인과 가격결정 부서장(구속), 책임 매니저 등을 공정거래법 위반 혐의로 기소했다고 밝혔다. 담합에 가담한 SK에너지는 자진신고자 감면제도(리니언시)에 따라 기소되진 않았다. 검찰은 두 회사가 2024년 7월부터 올 2월까지 가격을 사전에 공유하는 등 담합을 벌여 오다 이란 전쟁이 발발한 직후엔', '檢 “단일 최대규모” 법인 등 기소 국내 정유사의 기름값 담합 의혹을 수사해 온 검찰이 HD현대오일뱅크, SK에너지, GS칼텍스, 에쓰오일 등 4대 정유사 법인과 임직원 4명을 최소 14조2000억 원대 담합 혐의 등으로 재판에 넘겼다. 단일 담합 사건으로는 역대 최대 규모다. 특히 검찰 수사 결과 2월 28일 미국과 이스라엘의 공습으로 이란 전쟁이 발발한 직후 국내 기름값이 폭등한 건 불안정한 국제 정세 때문만이 아니라 정유사들의 가격 담합이 영향을 미쳤던 것으로 드러났다. 6일 서울중앙지검 공정거래조사부(부장검사 나희석)는 SK에너지와 담합해 서로 가격 정보를 교환하고 가격을 대폭 상승시키기로 합의한 HD현대오일뱅크 법인과 가격결정 부서장(구속), 책임 매니저 등을 공정거래법 위반 혐의로 기소했다고 밝혔다. 담합에 가담한 SK에너지는 자진신고자 감면제도(리니언시)에 따라 기소되진 않았다. 검찰은 두 회사가 2024년 7월부터 올 2월까지 가격을 사전에 공유하는 등 담합을 벌여 오다 이란 전쟁이 발발한 직후엔 SK에너지가 HD현대오일뱅크보다 먼저 L당 30∼40원 높이고, 뒤이어 HD현대오일뱅크가 따라 가격을 올리는 방식으로 합의한 정황을 포착했다. HD현대오일뱅크와 SK에너지의 담합 규모는 매출 기준 총 14조2000억 원으로 추산됐다. 검찰은 GS칼텍스와 에쓰오일까지 이같은 추세에 따라 가격을 올리면서 담합에 영향을 받은 석유제품 거래 규모가 총 26조 원 수준에 달한다고 밝혔다. 검찰은 불공정거래를 이어온 4대 정유사 법인을 공정거래법 위반 혐의로 재판에 넘기고, 관련 증거를 없앤 혐의를 받는 HD현대오일뱅크 법무실장과 GS칼텍스 국내영업부문장도 기소했다.', 'crawl', '동아일보', '2026-07-07 04:30:00', '보수', 'ready', 'https://dimg.donga.com/a/232/131/95/1/wps/NEWS/IMAGE/2026/07/07/134248225.1.jpg', '2026-07-07 06:04:36', '2026-07-07 17:44:19.56335', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3705, 'https://rss.donga.com/economy.xml', NULL, 'https://www.donga.com/news/Economy/article/all/20260707/134249926/1', '경제', '삼성전자 역대급 실적에도 30만원 붕괴, 이유는?', '7일 오전 코스피가 급락하면서 매도 사이드카(프로그램 매도 호가 효력 일시 정지)가 발동됐다. 삼성전자가 올 2분기(4~6월) 사상 최대 수준의 잠정 실적을 발표했는데도 6% 넘게 하락하며 힘을 쓰지 못하는 영향이 컸다.7일 한국거래소에 따르면 이날 오전 10시 23분 코스피200선물 지수의 급격한 변동으로 코스피 프로그램 매도 호가의 효력이 5분간 정지되는 매도 사이드카가 발생했다. 코스피에 대한 매도 사이드카는 코스피200선물 지수가 5% 이상 하락해 1분간 지속되는 경우 발동된다. 이날 오전 11시 2분 기준 코스피는 전일 대비 4.7% 급락한 7672.10에 거래되고 있다. 외국인이 1조5670억 원어치를 순매도한 반면 개인은 1조5590억 원어치 순매수하고 있다.삼성전자의 주가가 전일 대비 6.84% 하락한 29만6500원 거래되며 증시 약세를 주도하고 있다. 삼성전자는 이날 공시를 통해 2분기 잠정 영업이익이 89조4000억 원을 기록했다고 밝혔다. 이는 성과급 지급', '7일 오전 서울 중구 하나은행 딜링룸 전광판에 코스피 지수가 표시되고 있다. 이날 코스피는 장중 5% 넘게 급락하면서 유가증권시장 매도 사이드카(프로그램 매도호가 일시 효력정지)가 발동됐다. 7일 오전 코스피가 급락하면서 매도 사이드카(프로그램 매도 호가 효력 일시 정지)가 발동됐다. 삼성전자가 올 2분기(4~6월) 사상 최대 수준의 잠정 실적을 발표했는데도 6% 넘게 하락하며 힘을 쓰지 못하는 영향이 컸다. 7일 한국거래소에 따르면 이날 오전 10시 23분 코스피200선물 지수의 급격한 변동으로 코스피 프로그램 매도 호가의 효력이 5분간 정지되는 매도 사이드카가 발생했다. 코스피에 대한 매도 사이드카는 코스피200선물 지수가 5% 이상 하락해 1분간 지속되는 경우 발동된다. 이날 오전 11시 2분 기준 코스피는 전일 대비 4.7% 급락한 7672.10에 거래되고 있다. 외국인이 1조5670억 원어치를 순매도한 반면 개인은 1조5590억 원어치 순매수하고 있다. 삼성전자의 주가가 전일 대비 6.84% 하락한 29만6500원 거래되며 증시 약세를 주도하고 있다. 삼성전자는 이날 공시를 통해 2분기 잠정 영업이익이 89조4000억 원을 기록했다고 밝혔다. 이는 성과급 지급을 위한 충당금 약 17조 원을 반영한 수치로, 실질 영업이익은 106조5000억 원 정도로 추산된다. 분기 영업이익이 처음으로 100조 원을 넘어선 것이다. 증권가에서는 삼성전자의 2분기 실적에 대한 기대가 주가에 선반영돼 이른바 ‘셀온(sell-on·차익 실현 매물이 쏟아져 주가가 하락하는 것) 현상’이 발생했다는 진단이 나온다. 한지영 키움증권 연구원은 “삼성전자의 2분기 잠정 실적은 시장의 전망치인 85조 원을 상회하는 ‘어닝 서프라이즈’ 수준”이라며 “이번 실적 발표 후 셀온 물량 출회 여부, 반도체 업황 노이즈 극복 등에 따른 추격 매수세 여부가 금일 증시의 단기적인 관점 포인트가 될 것”이라고 말했다.', 'crawl', '동아일보', '2026-07-07 11:17:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134250649.1.thumb.jpg', '2026-07-07 06:04:37', '2026-07-07 17:49:06.601315', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3714, 'https://rss.donga.com/economy.xml', NULL, 'https://www.donga.com/news/Economy/article/all/20260707/134249463/1', '경제', '삼성전자 89.4조 ‘잭팟’에도 주가 털썩…증권가는 오히려 “매수 기회”', '삼성전자가 7일 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록하며 시장 컨센서스를 대폭 웃도는 ‘어닝 서프라이즈’를 달성했다. 증권가는 이번 호실적을 기점으로 글로벌 시장을 괴롭히던 ‘인공지능(AI) 거품론’이 가라앉고 AI 메모리 슈퍼사이클이 본격화될 것으로 내다봤다. 전문가들은 삼성전자가 압도적인 지배력과 차세대 고대역폭메모리(HBM) 납품을 통해 반도체 경쟁력을 완연히 회복하며 본격적인 주가 재평가(리레이팅) 국면에 진입했다고 평가했다. 다만 향후 추가적인 상승 탄력은 하반기 세부 로드맵의 실현 여부와 예고된 대규모 주주환원책에 달려 있다고 진단했다.김선우 메리츠증권 연구원은 “공간 제약으로 인해 메모리 공급은 최소 내년 4분기까지 수요 증가 속도를 따라잡기에 턱없이 부족한 상황”이라며 “메모리 업황은 사이클상 아직 중반(Mid-cycle)에도 미치지 못했다”고 진단했다.일각에서 제기되는 AI 거품론에 대해 “내연기관차를 바라보는 마부의 절규일 뿐, 범용인', '‘AI 거품론’ 잠재운 깜짝 실적 기록 “비중 확대 시점, 하반기 주가 랠리” 7일 오전 서울 중구 하나은행 딜링룸 전광판에 코스피와 원·달러 환율이 표시되고 있다. 이날 코스피 지수는 전 거래일 대비 장초반 2% 넘게 내리며 7,800선으로 밀려났다. 2026.7.7 뉴스1 삼성전자가 7일 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록하며 시장 컨센서스를 대폭 웃도는 ‘어닝 서프라이즈’를 달성했다. 증권가는 이번 호실적을 기점으로 글로벌 시장을 괴롭히던 ‘인공지능(AI) 거품론’이 가라앉고 AI 메모리 슈퍼사이클이 본격화될 것으로 내다봤다. 전문가들은 삼성전자가 압도적인 지배력과 차세대 고대역폭메모리(HBM) 납품을 통해 반도체 경쟁력을 완연히 회복하며 본격적인 주가 재평가(리레이팅) 국면에 진입했다고 평가했다. 다만 향후 추가적인 상승 탄력은 하반기 세부 로드맵의 실현 여부와 예고된 대규모 주주환원책에 달려 있다고 진단했다. 김선우 메리츠증권 연구원은 “공간 제약으로 인해 메모리 공급은 최소 내년 4분기까지 수요 증가 속도를 따라잡기에 턱없이 부족한 상황”이라며 “메모리 업황은 사이클상 아직 중반(Mid-cycle)에도 미치지 못했다”고 진단했다. 일각에서 제기되는 AI 거품론에 대해 “내연기관차를 바라보는 마부의 절규일 뿐, 범용인공지능(AGI) 선착순 투자 경쟁 시대에는 공급량 재분배에 순응하는 것이 불가피하다”며 “가장 강력한 실적 개선 속도를 보이는 삼성전자에 대한 적극적인 비중 확대가 필요한 시점”이라고 권고했다. 최보영 교보증권 연구원도 “에이전틱(Agentic) AI의 확산으로 메모리 전방위 수요가 확대되고 있으며, 이에 따른 구조적 공급 부족이 오는 2028년까지 지속될 것”이라고 전망했다. 최 연구원은 “삼성전자는 범용 D램과 낸드(NAND) 가격 급등을 주도하며 두 시장에서 각각 38%, 29%의 압도적인 점유율로 1위를 유지하고 있다”며 “특히 엔비디아향 HBM4 첫 납품을 계기로 HBM 시장 추격을 본격화하는 동시에 비메모리 부문의 적자를 축소하며 종합 반도체 기업(IDM)으로서의 경쟁력을 완연히 회복하고 있다”고 분석하며 목표주가를 50만원으로 상향했다. 삼성전자의 압도적인 호실적에도 이날 주가는 단기 차익실현 매물 등으로 6%대 하락세를 보이고 있지만 증권가는 이번 조정을 오히려 ‘매수 기회’라고 입을 모았다. 강세장 속 일시적인 조정일 뿐, 하반기 모멘텀은 유효하다는 판단이다. 손인준 유진투자증권 연구원은 “하반기에는 메모리 업체 간 주주환원 경쟁이 본격화될 전망”이라며 “삼성전자는 연간 잉여현금흐름(FCF)의 50%를 자사주 소각 중심으로 활용할 것으로 보이며, 이러한 대규모 주주환원책이 최근 상대적으로 부진했던 삼성전자 주가의 아웃퍼폼(시장 수익률 상회)을 이끌 것”이라고 내다봤다. 손 연구원은 “최근 메모리 업종의 주가가 큰 폭의 하락세를 보였으나, 이는 여전히 강세장 속에서 나타나는 일시적인 조정에 불과하다”고 판단했다. 실적 눈높이가 올라가면서 증권가의 목표가 상향 랠리도 확산하는 추세다. 이번 어닝 서프라이즈로 장기 성장성까지 확인된 만큼, 현재 주가는 확실한 저평가 영역에 머물고 있다는 진단이 지배적이다. 신한투자증권과 한투증권이 가장 높은 59만원을 제시했다. 김형태 신한투자증권 연구원은 “목표주가는 주당순자산가치(BPS) 상승과 Peer(유사 경쟁기업) 평균 PBR(주가순자산비율)을 반영해 59만원으로 상향한다”며 “2028년까지 서버 중심의 공급 부족이 지속돼 LTA(장기공급계약) 협상이 유리하게 진행 중이고, 250조 원 규모의 FCF를 활용한 강력한 주주환원도 대기 중이다. 확실한 공급 우위를 바탕으로 경쟁사와 밸류에이션 격차를 줄이며 주가 랠리를 재개할 것”이라고 예상했다. 정민규 상상인증권 연구원은 “하반기에도 메모리 가격 상승세는 이어진다. 데이터센터향 수요가 워낙 견조한 데다, LTA 확대로 실적 안정성까지 확보했다”며 “이에 따라 3분기 영업이익은 53.4%의 이익률을 기록하며 110조7000억원을 달성하고, 연간 영업이익은 전년 대비 755% 폭증한 372조9000억원으로 역대 최대 실적을 기록할 전망”이라며 목표주가를 58만원으로 높였다. [서울=뉴시스] 1 47세 미혼 신봉선 노후 준비법 “20대부터 월 100만원 저축” 2 [오늘의 운세/7월 7일] 3 변진섭, 골프공으로 황영조 맞혔다…“뇌진탕에 50바늘” 4 잠수함 수주 실패, 장동혁은 “정부 책임”이라는데…韓 “최선 다 했다” 5 인천지검, ‘대북송금 수사’ 박상용 감찰…징계 수위 높아지나 6 김민석 맞받은 정청래…“총리가 ‘당대표 로망’ 말한게 자기정치” 7 3군 사관학교 통합 계획 발표, 100분전 돌연 취소한 국방부 8 “예전엔 잘 먹었는데…” 나이 들면 금방 배부른 이유 있었다 [노화설계] 9 혈당-염증 관리 돕는 ‘텃밭 보약’ 애호박[정세연의 음식처방] 10 홍석천 “헤어진 연인에게 가게 차려줘…위자료라 생각” 1 ‘5·18 성역’ 이병태, 靑 권고에 결국 사퇴…“성역 강요 사회 안돼” 2 3군 사관학교 통합 계획 발표, 100분전 돌연 취소한 국방부 3 광주 찾은 배재고 교장, 눈물의 사과…야구부 주장 “인성 중요 깨달아” 4 장동혁, ‘복당 영구금지’까지 꺼냈다…당내 “징계정치는 파멸” 5 정점식 “폭군 연산군처럼, 국민 목에 ‘현대판 신언패’…입틀막법 헌법소원” 6 나토 벽 높았다…캐나다, 60조 잠수함 사업자에 獨 TKMS 선정 7 ‘복당 영구 금지’까지 들고나온 장동혁… 당내 “징계정치는 파멸” 8 국방부, ‘사관학교 통합’ 발표 100분전 돌연 취소…반대여론 의식했나 9 국힘 개혁파 “장동혁, 정치생명 연장 위해 뺄셈 정치” 10 광주 찾아 고개숙인 배재고 “깊이 반성” 1 47세 미혼 신봉선 노후 준비법 “20대부터 월 100만원 저축” 2 [오늘의 운세/7월 7일] 3 변진섭, 골프공으로 황영조 맞혔다…“뇌진탕에 50바늘” 4 잠수함 수주 실패, 장동혁은 “정부 책임”이라는데…韓 “최선 다 했다” 5 인천지검, ‘대북송금 수사’ 박상용 감찰…징계 수위 높아지나 6 김민석 맞받은 정청래…“총리가 ‘당대표 로망’ 말한게 자기정치” 7 3군 사관학교 통합 계획 발표, 100분전 돌연 취소한 국방부 8 “예전엔 잘 먹었는데…” 나이 들면 금방 배부른 이유 있었다 [노화설계