INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3736, 'https://rss.donga.com/international.xml', NULL, 'https://www.donga.com/news/Society/article/all/20260707/134247863/2', '국제', '“전쟁으로 올해 2조 벌듯, 트럼프 만세” 담합으로 기름값 40% 올려', '“역시 전쟁으로 먹고사는 회사. 트럼프 만세.” “오늘 가격 100원 더 올린다, 올해 2조 벌 듯.” 미국과 이란의 전쟁이 격화되던 3월 4일 국내 정유사인 에쓰오일 가격결정 부서에서 근무하는 임직원들은 회사 업무용 메신저 대화방에서 이런 대화를 나눴다. 당시 국내 휘발유 평균 판매가격이 L당 1800원을 넘어서며 3년 7개월 만에 최고치를 경신했고, 이재명 대통령도 임시 국무회의를 열어 “시장 환경을 악용해 불합리한 폭리를 취하려는 시도에 단호히 대응하라”고 지시하던 상황이었지만 정유사 직원들은 환호하고 있었던 것. 검찰 조사 결과 HD현대오일뱅크는 이 대통령의 지시가 나왔던 당일에도 ‘휘발유 1955원, 등유 2515원, 경유 2185원’이라는 가격 정보를 SK에너지에 전달한 것으로 드러났다. ● 檢 “전쟁을 이윤 추구 기회로 삼아 담합 범행” 6일 서울중앙지검 공정거래조사부(부장검사 나희석)는 HD현대오일뱅크, SK에너지, GS칼텍스, 에쓰오일 등 국내 정유사 4곳', '檢, 유가 담합 정유사-임직원 기소 두 회사가 먼저 인상하면 따라 올려 “폭리 위해 위기 상황서 밀실 합의” 판매가 낮춰 정부에 허위 보고도 크게보기 이란 전쟁 발발 이후 서울 평균 휘발유 가격이 L당 1900원을 넘어섰던 3월 6일 시내 한 주유소에 유류 가격이 표시돼 있다. 뉴스1 “역시 전쟁으로 먹고사는 회사. 트럼프 만세.” “오늘 가격 100원 더 올린다, 올해 2조 벌 듯.” 미국과 이란의 전쟁이 격화되던 3월 4일 국내 정유사인 에쓰오일 가격결정 부서에서 근무하는 임직원들은 회사 업무용 메신저 대화방에서 이런 대화를 나눴다. 당시 국내 휘발유 평균 판매가격이 L당 1800원을 넘어서며 3년 7개월 만에 최고치를 경신했고, 이재명 대통령도 임시 국무회의를 열어 “시장 환경을 악용해 불합리한 폭리를 취하려는 시도에 단호히 대응하라”고 지시하던 상황이었지만 정유사 직원들은 환호하고 있었던 것. 검찰 조사 결과 HD현대오일뱅크는 이 대통령의 지시가 나왔던 당일에도 ‘휘발유 1955원, 등유 2515원, 경유 2185원’이라는 가격 정보를 SK에너지에 전달한 것으로 드러났다. ● 檢 “전쟁을 이윤 추구 기회로 삼아 담합 범행” 크게보기 6일 서울중앙지검 공정거래조사부(부장검사 나희석)는 HD현대오일뱅크, SK에너지, GS칼텍스, 에쓰오일 등 국내 정유사 4곳 법인과 임직원 4명을 공정거래법 위반 혐의로 재판에 넘기면서 “만성적 가격 담합 관행이 국제 위기 상황에서 노골적으로 표출됐다”며 “국내 정유사들끼리 폭리를 취득하기 위한 밀실 합의가 있었다”고 밝혔다. HD현대오일뱅크와 SK에너지가 전쟁 발발 직후 적극적으로 기름값 인상을 담합했고, GS칼텍스와 에쓰오일이 그 흐름을 쫓아가면서 기름값이 폭등했다는 것이다. 검찰은 정유사들이 원유를 상당량 비축해둔 상태여서 가격을 급히 올릴 필요성이 없었는데도 경제적 이익을 취하기 위해 서로 짜고 가격을 인상해 전쟁 발발 직후 기름값이 일주일 안에 40%가량 폭등했다고 밝혔다. 검찰은 HD현대오일뱅크와 SK에너지에 대해 최소 2024년 7월 무렵부터 서로 가격 정보를 공유하며 담합한 것으로 판단했다. 조사 결과 두 회사는 3월 이란 전쟁이 격화되자 SK에너지가 HD현대오일뱅크보다 L당 30∼40원 높은 가격을 유지하는 방향으로 기름값을 올리기로 했다. 두 회사 직원들이 담합 과정에서 “경쟁사가 따르지 않을 경우 우려 사항, 전체 시장가격 저가 수렴 가능성” 등 대응 문건을 만든 사실도 확인됐다. 다만 검찰은 ‘가격 담합 혐의’를 받는 두 회사 가운데 HD현대오일뱅크만 재판에 넘기고 SK에너지와 임직원은 기소 대상에서 제외했다. SK에너지 측이 담합 경위에 대해 적극적으로 진술한 뒤 리니언시(자진신고자 감면제도)를 신청해 기소는 면한 것이다. 검찰은 GS칼텍스와 에쓰오일에 대해서는 담합 혐의를 입증할 증거가 부족하다고 판단했다고 밝혔다. 나 부장검사는 이날 브리핑에서 “(HD현대오일뱅크와 SK에너지가) 가격을 급등시키자 흐름을 그대로 추종해 (GS칼텍스와 에쓰오일도) 가격을 상승시켜 범행에 편승했다”며 “경쟁 질서를 교란하는 행위에 해당하지만 법률상 형사처벌 대상이 아니라 기소 범위에서 제외됐다”고 밝혔다. ● “4대 정유사, 대통령에도 허위 보고” 검찰은 4대 정유사가 직영이 아닌 자영 주유소들과도 석유제품 전량을 정유사로부터 구입하도록 하는 ‘전량 구매 계약’을 맺은 행위가 불공정 거래라고 판단해 4대 정유사 모두 공정거래법 위반 혐의로 기소했다. 담합은 매출액의 최대 30%까지 과징금을 부과할 수 있지만, 불공정 거래는 최대 10%까지만 부과할 수 있다. 또 기름값 폭등 논란이 불거진 뒤 4대 정유사가 산업통상부에 보고하는 ‘일일 판매 가격’을 실제보다 낮은 수준으로 허위 보고한 정황도 드러났다. 나 부장검사는 “대통령에게 보고하는 가격도 허위가 있었던 것”이라며 “담합 규모도 기소된 2개사만 (매출 기준) 14조2000억 원이지만 나머지 2개사를 (담합 범행에) 포함하면 26조 원 규모”라고 설명했다. 검찰 수사에 대해 공식 입장문을 내지 않은 4대 정유사는 재판에서 사실관계를 소명하겠다는 방침이다. 앞서 정유사들은 2011년 공정거래위원회의 가격 담합 과징금 납부명령에 대해 취소 소송을 냈고, 대법원에서 “객관적 근거가 부족하다”는 이유로 최종 승소했다.', 'crawl', '동아일보', '2026-07-07 04:30:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134252075.1.thumb.jpg', '2026-07-07 06:04:37', '2026-07-07 17:53:21.738269', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3740, 'https://rss.donga.com/international.xml', NULL, 'https://www.donga.com/news/Inter/article/all/20260706/134247744/2', '국제', '美 “나토 정상회의서 수조원대 무기계약 예정”', '미국 도널드 트럼프 행정부가 7, 8일 튀르키예 수도 앙카라에서 열리는 북대서양조약기구(NATO·나토) 정상회의에서 유럽 동맹국들의 국방비 증액 약속 이행을 점검하고, 수조 원대의 미국산 무기 판매를 추진할 거라고 5일 밝혔다. 지난해 6월 네덜란드 헤이그에서 열린 나토 정상회의에서 유럽 국가들은 트럼프 대통령의 요구대로 2035년까지 국방비 지출을 국내총생산(GDP) 대비 5%까지 늘리는 데 합의했다. 트럼프 행정부는 유럽의 국방비 증액을 자국산 무기 구매 기회로 활용하겠다는 전략이다. 매슈 휘터커 나토 주재 미국대사는 이날 브리핑에서 “이번 앙카라 정상회의에서 헤이그에서 약속한 유럽의 국방 공약에 대한 진척 상황을 점검할 것”이라며 “우리는 모든 동맹국이 방위비 지출에서 양적, 질적으로 의미 있는 증가세를 보여줌으로써 공정한 부담 분담이 이뤄지기를 기대한다”고 밝혔다. 이어 “(러시아와 인접한) 폴란드, 북유럽 국가들, 발트해 국가들이 (국방비 증액에) 앞장서고 있고, 독일도', '美대사 “동맹국 방위비 지출 기대” 유럽, 호르무즈 앙금 해소 나설듯 李대통령도 K방산 세일즈 예상 미국 도널드 트럼프 행정부가 7, 8일 튀르키예 수도 앙카라에서 열리는 북대서양조약기구(NATO·나토) 정상회의에서 유럽 동맹국들의 국방비 증액 약속 이행을 점검하고, 수조 원대의 미국산 무기 판매를 추진할 거라고 5일 밝혔다. 지난해 6월 네덜란드 헤이그에서 열린 나토 정상회의에서 유럽 국가들은 트럼프 대통령의 요구대로 2035년까지 국방비 지출을 국내총생산(GDP) 대비 5%까지 늘리는 데 합의했다. 트럼프 행정부는 유럽의 국방비 증액을 자국산 무기 구매 기회로 활용하겠다는 전략이다. 매슈 휘터커 나토 주재 미국대사는 이날 브리핑에서 “이번 앙카라 정상회의에서 헤이그에서 약속한 유럽의 국방 공약에 대한 진척 상황을 점검할 것”이라며 “우리는 모든 동맹국이 방위비 지출에서 양적, 질적으로 의미 있는 증가세를 보여줌으로써 공정한 부담 분담이 이뤄지기를 기대한다”고 밝혔다. 이어 “(러시아와 인접한) 폴란드, 북유럽 국가들, 발트해 국가들이 (국방비 증액에) 앞장서고 있고, 독일도 2029년까지 국방비를 GDP의 5% 수준으로 끌어올리겠다는 계획대로 가고 있다. 하지만 다른 많은 국가는 여전히 뒤처져 있다”고 지적했다. 트럼프 행정부는 이번 앙카라 정상회의를 계기로 유럽 동맹들에 무기 구매도 강조할 방침이다. 트럼프 행정부 고위 당국자는 이날 브리핑에서 “정상회의 기간에 수십억 달러(수조 원) 규모의 미국산 무기 판매 계약이 있을 예정”이라고 했다. 이번 회의에서 유럽 동맹국들은 올 2월 이란 전쟁 발발 후 호르무즈 해협 군사작전 참여 요청을 둘러싼 미국과의 갈등 해소에 주력할 것으로 보인다. 트럼프 대통령은 지난달 24일 백악관에서 마르크 뤼터 나토 사무총장과 만나 나토 회원국들의 국방비 증액 상황을 듣고 “나는 단지 그들(동맹국들)의 충성심을 원한다. 우리는 그들의 돈이 필요하지 않다”고 했다. 이란 전쟁에 비협조적이었던 유럽 동맹국들에 대한 불만을 표출한 것으로 풀이된다. 한편 이재명 대통령은 이번 앙카라 정상회의에 일본, 호주, 뉴질랜드와 함께 초대돼 나토 정상회의에 처음 데뷔한다. 이 대통령은 세계 국방비의 55%를 차지하는 나토 동맹국들을 상대로 방산 세일즈 외교를 펼칠 것으로 예상된다.', 'crawl', '동아일보', '2026-07-07 04:30:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134252992.1.thumb.jpg', '2026-07-07 06:04:37', '2026-07-07 17:54:18.951181', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3741, 'https://rss.donga.com/international.xml', NULL, 'https://www.donga.com/news/Inter/article/all/20260706/134247748/2', '국제', '베네수엘라 지진 사망 3342명 촛불 추모', '5일 베네수엘라의 수도 카라카스에서 지난달 24일 발생한 연쇄 강진으로 숨진 시민들을 기리는 촛불 추모식이 열렸다. 이날 당국은 누적 사망자가 3342명, 부상자가 1만6740명이라고 밝혔다.', '5일 베네수엘라의 수도 카라카스에서 지난달 24일 발생한 연쇄 강진으로 숨진 시민들을 기리는 촛불 추모식이 열렸다. 이날 당국은 누적 사망자가 3342명, 부상자가 1만6740명이라고 밝혔다.', 'rss', '동아일보', '2026-07-07 04:30:00', '보수', 'crawl_failed', 'https://dimg.donga.com/wps/NEWS/IMAGE/2026/07/06/134245589.4.jpg', '2026-07-07 06:04:37', '2026-07-07 17:54:23.579867', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3744, 'https://rss.donga.com/international.xml', NULL, 'https://www.donga.com/news/Inter/article/all/20260707/134248330/1', '국제', '베네수 강진 잔해 속 11일 버틴 생존자 4명 극적 구조', '베네수엘라를 강타한 규모 7.2와 7.5의 연쇄 강진으로 붕괴한 건물 잔해에 갇혀 있던 생존자 4명이 지진 발생 267시간 만에 극적으로 구조됐다.6일(현지 시간) 현지 매체 엘나시오날에 따르면 구조대는 전날 오후 9시께 북부 라과이라주 카라베예다 지역의 붕괴 건물 잔해에서 어린이 2명과 여성 1명, 남성 1명 등 4명을 구조했다.이들은 지난달 24일 오후 6시(현지 시간) 발생한 강진 이후 267시간 동안 잔해 속에 갇혀 있다가 구조된 것으로 확인됐다.SNS에 공개된 영상에는 구조대가 잔해 속 생존자들과 처음 접촉하는 장면이 담겼다. 구조대원들은 생존자들에게 “침착하게 움직이지 말라”고 당부한 뒤 구조 작업을 벌였다.구조된 4명은 현장에서 응급 처치를 받은 뒤 구급차를 이용해 인근 병원으로 이송돼 치료와 정밀 검사를 받고 있다.이번 구조는 지난달 24일 39초 간격으로 발생한 규모 7.2와 7.5의 연쇄 강진 이후 이어진 수색 작업 과정에서 이뤄졌다.베네수엘라 정부의', '어린이 2명 등 267시간만에 생환 [라과이라=AP/뉴시스] ﻿﻿베네수엘라를 강타한 규모 7.2와 7.5의 연쇄 강진으로 붕괴한 건물 잔해에 갇혀 있던 생존자 4명이 지진 발생 267시간 만에 극적으로 구조됐다. 사진은 지난 2일(현지 시간) 베네수엘라 라과이라에서 지진으로 무너진 건물 잔해에 페인트로 적힌 ‘S.O.S’ 구조 신호가 남아 있다. 2026.07.07 베네수엘라를 강타한 규모 7.2와 7.5의 연쇄 강진으로 붕괴한 건물 잔해에 갇혀 있던 생존자 4명이 지진 발생 267시간 만에 극적으로 구조됐다. 6일(현지 시간) 현지 매체 엘나시오날에 따르면 구조대는 전날 오후 9시께 북부 라과이라주 카라베예다 지역의 붕괴 건물 잔해에서 어린이 2명과 여성 1명, 남성 1명 등 4명을 구조했다. 이들은 지난달 24일 오후 6시(현지 시간) 발생한 강진 이후 267시간 동안 잔해 속에 갇혀 있다가 구조된 것으로 확인됐다. SNS에 공개된 영상에는 구조대가 잔해 속 생존자들과 처음 접촉하는 장면이 담겼다. 구조대원들은 생존자들에게 “침착하게 움직이지 말라”고 당부한 뒤 구조 작업을 벌였다. 구조된 4명은 현장에서 응급 처치를 받은 뒤 구급차를 이용해 인근 병원으로 이송돼 치료와 정밀 검사를 받고 있다. 이번 구조는 지난달 24일 39초 간격으로 발생한 규모 7.2와 7.5의 연쇄 강진 이후 이어진 수색 작업 과정에서 이뤄졌다. 베네수엘라 정부의 최신 집계에 따르면 이번 지진으로 현재까지 최소 3342명이 숨지고 1만6700명이 다쳤다. 이번 연쇄 강진은 최근 100여 년간 베네수엘라에서 발생한 지진 가운데 가장 큰 인명 피해를 낸 재난으로 평가된다. [서울=뉴시스] 1 47세 미혼 신봉선 노후 준비법 “20대부터 월 100만원 저축” 2 [오늘의 운세/7월 7일] 3 변진섭, 골프공으로 황영조 맞혔다…“뇌진탕에 50바늘” 4 잠수함 수주 실패, 장동혁은 “정부 책임”이라는데…韓 “최선 다 했다” 5 인천지검, ‘대북송금 수사’ 박상용 감찰…징계 수위 높아지나 6 김민석 맞받은 정청래…“총리가 ‘당대표 로망’ 말한게 자기정치” 7 3군 사관학교 통합 계획 발표, 100분전 돌연 취소한 국방부 8 “예전엔 잘 먹었는데…” 나이 들면 금방 배