INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3757, 'https://rss.donga.com/international.xml', NULL, 'https://www.donga.com/news/Inter/article/all/20260706/134244253/1', '국제', '트럼프, 나토 회의서 국방비 증액 점검… 무기 세일즈도 예고', '미국 도널드 트럼프 행정부가 7, 8일 튀르키예 수도 앙카라에서 열리는 북대서양조약기구(NATO·나토) 정상회의에서 유럽 동맹국들의 국방비 증액 약속 이행을 점검하고, 수조 원대의 미국산 무기 판매를 추진할 거라고 5일 밝혔다. 지난해 6월 네덜란드 헤이그에서 열린 나토 정상회의에서 유럽 국가들은 트럼프 대통령의 요구대로 2035년까지 국방비 지출을 국내총생산(GDP) 대비 5%까지 늘리는데 합의했다. 트럼프 행정부는 유럽의 국방비 증액을 자국산 무기 구매 기회로 활용하겠다는 전략이다.매슈 휘터커 나토 주재 미국 대사는 이날 브리핑에서 “이번 앙카라 정상회의에서 헤이그에서 약속한 유럽의 국방 공약에 대한 진척 상황을 점검할 것”이라며 “우리는 모든 동맹국이 방위비 지출에서 양적, 질적으로 의미 있는 증가세를 보여줌으로써 공정한 부담 분담이 이뤄지기를 기대한다”고 밝혔다. 이어 “(러시아와 인접한) 폴란드, 북유럽 국가들, 발트해 국가들이 (국방비 증액에) 앞장서고 있고 독일도 20', '미국 도널드 트럼프 행정부가 7, 8일 튀르키예 수도 앙카라에서 열리는 북대서양조약기구(NATO·나토) 정상회의에서 유럽 동맹국들의 국방비 증액 약속 이행을 점검하고, 수조 원대의 미국산 무기 판매를 추진할 거라고 5일 밝혔다. 지난해 6월 네덜란드 헤이그에서 열린 나토 정상회의에서 유럽 국가들은 트럼프 대통령의 요구대로 2035년까지 국방비 지출을 국내총생산(GDP) 대비 5%까지 늘리는데 합의했다. 트럼프 행정부는 유럽의 국방비 증액을 자국산 무기 구매 기회로 활용하겠다는 전략이다. 매슈 휘터커 나토 주재 미국 대사는 이날 브리핑에서 “이번 앙카라 정상회의에서 헤이그에서 약속한 유럽의 국방 공약에 대한 진척 상황을 점검할 것”이라며 “우리는 모든 동맹국이 방위비 지출에서 양적, 질적으로 의미 있는 증가세를 보여줌으로써 공정한 부담 분담이 이뤄지기를 기대한다”고 밝혔다. 이어 “(러시아와 인접한) 폴란드, 북유럽 국가들, 발트해 국가들이 (국방비 증액에) 앞장서고 있고 독일도 2029년까지 국방비를 GDP의 5% 수준으로 끌어올린다는 계획대로 가고 있다. 하지만 다른 많은 국가들은 여전히 뒤처져 있다”고 지적했다. 트럼프 행정부는 이번 앙카라 정상회의를 계기로 유럽 동맹들에 무기 구매도 강조할 방침이다. 트럼프 행정부 고위당국자는 이날 브리핑에서 “정상회의 기간 수십억 달러(수조 원) 규모의 미국산 무기 판매 계약이 있을 예정”이라고 했다. 이번 회의에서 유럽 동맹국들은 올 2월 이란 전쟁 발발 후 호르무즈 해협 군사작전 참여 요청을 둘러싼 미국과의 갈등 해소에 주력할 것으로 보인다. 트럼프 대통령은 지난달 24일 백악관에서 마르크 뤼터 나토 사무총장과 만나 나토 회원국들의 국방비 증액 상황을 듣고 “나는 단지 그들(동맹국들)의 충성심을 원한다. 우리는 그들의 돈이 필요하지 않다”고 했다. 이란 전쟁에 비협조적이었던 유럽 동맹국들에 대한 불만을 표출한 것으로 풀이된다. 백악관에 따르면 트럼프 대통령은 6일 저녁 백악관을 출발해 7일 오후 앙카라에 도착할 예정이다. 레제프 타이이프 에르도안 튀르키예 대통령과 양자 정상회담을 갖고, 나토 정상 친목 만찬에 참석한다. 8일에는 볼로디미르 젤렌스키 우크라이나 대통령, 아메드 알샤라 시리아 대통령과 각각 양자회담을 가진 뒤 미국으로 출국할 예정이다. 한편, 이재명 대통령은 이번 앙카라 정상회의에 일본, 호주, 뉴질랜드와 함께 초대돼 나토 정상회의에 처음 데뷔한다. 이 대통령은 세계 국방비의 55%를 차지하는 나토 동맹국들을 상대로 방산 세일즈 외교를 펼칠 것으로 예상된다.', 'crawl', '동아일보', '2026-07-06 15:29:00', '보수', 'ready', 'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134251147.1.thumb.jpg', '2026-07-07 06:04:38', '2026-07-07 17:56:09.728886', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3758, 'https://rss.donga.com/international.xml', NULL, 'https://www.donga.com/news/Inter/article/all/20260706/134244265/1', '국제', '이란 최고지도자 모즈타바, 부친 장례식 끝내 불참…건강이상설 증폭', '이란 최고지도자 모즈타바 하메네이가 부친의 장례식에 모습을 드러내지 않아 건강 이상설이 증폭되고 있다고 로이터 통신 등이 5일(현지 시간) 보도했다.외신에 따르면 4일부터 이란 테헤란에서 열린 알리 하메네이 전 최고지도자의 장례 기도회에 하메네이의 다른 세 아들은 관 옆에 서서 기도를 올렸다. 하지만 정작 최고지도자를 승계한 차남 모즈타바는 공개적으로 모습을 드러내지 않았다.모즈타바는 2월 28일 미국과 이스라엘의 공습 첫날 부친이 숨질 당시 얼굴을 다치고 다리에 중상을 입은 것으로 알려졌다. 모즈타바는 이후 지금까지 공식 석상에 모습을 드러내지 않고 있다. 이에 외신들은 모즈타바의 부상이 생각보다 심각한 상태이고, 최고 권력 공백 속에 이란 혁명수비대 등 이란 내 권력 갈등이 증폭되고 있다고 분석했다. CNN에 따르면 이날 장례식에 모습을 드러낸 하메네이의 장남 모스타파는 정부 직책을 맡지 않는 등 정치 활동을 거의 하지 않고 있지만 종교계에서 영향력을 발휘하는 것으로 알려졌', '이란 최고지도자 모즈타바 하메네이가 부친의 장례식에 모습을 드러내지 않아 건강 이상설이 증폭되고 있다고 로이터 통신 등이 5일(현지 시간) 보도했다.외신에 따르면 4일부터 이란 테헤란에서 열린 알리 하메네이 전 최고지도자의 장례 기도회에 하메네이의 다른 세 아들은 관 옆에 서서 기도를 올렸다. 하지만 정작 최고지도자를 승계한 차남 모즈타바는 공개적으로 모습을 드러내지 않았다.모즈타바는 2월 28일 미국과 이스라엘의 공습 첫날 부친이 숨질 당시 얼굴을 다치고 다리에 중상을 입은 것으로 알려졌다. 모즈타바는 이후 지금까지 공식 석상에 모습을 드러내지 않고 있다. 이에 외신들은 모즈타바의 부상이 생각보다 심각한 상태이고, 최고 권력 공백 속에 이란 혁명수비대 등 이란 내 권력 갈등이 증폭되고 있다고 분석했다. CNN에 따르면 이날 장례식에 모습을 드러낸 하메네이의 장남 모스타파는 정부 직책을 맡지 않는 등 정치 활동을 거의 하지 않고 있지만 종교계에서 영향력을 발휘하는 것으로 알려졌', 'rss', '동아일보', '2026-07-06 14:54:00', '보수', 'crawl_failed', 'https://dimg.donga.com/wps/NEWS/IMAGE/2026/07/06/134244399.1.jpg', '2026-07-07 06:04:38', '2026-07-07 17:56:17.714501', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3770, 'https://www.mediatoday.co.kr/rss/S1N2.xml', NULL, 'https://www.mediatoday.co.kr/news/articleView.html?idxno=335601', '정치', '‘5·18민주화운동 맞냐’ 답변 회피 이진숙, 배재고 화환… “행동 매우 부적절”', '이진숙 국민의힘 의원이 방송통신위원회(방통위) 위원장 후보 시절 ‘5·18민주화운동 맞냐’ ‘일본군 위안부 강제입니까?’ 질문에 ‘답변하지 않겠다’라고 말했는데, 이번엔 ‘스타벅스 가야지’ 응원가를 불러 파문을 일으킨 배재고등학교에 응원 화환을 보냈다. 이를 두고 “매우 부적절하다”라는 비판이 나왔다.지난 5일 이진숙 의원은 자신의 페이스북에 “배재고에 화환을 보냈다. 스타벅스가 5·18 모욕과 무슨 관계가 있는지 설명해 주실 분 댓글 달아주세요. 만약 스타벅스가 5·18과 광주에 대한 모욕을 상징한다면 스타벅스는 더 이상 영업해서', '2026년 7월5일 이진숙 국민의힘 의원이 자신의 페이스북에 게시한 배재고 관련 화환 사진과 이진숙 의원. 이진숙 국민의힘 의원이 ‘스타벅스 가야지’ ‘탱크데이’ 내용을 담은 혐오 발언을 응원가로 불러 파문을 일으킨 배재고등학교에 응원 화환을 보내 “매우 부적절하다”는 비판이 나왔다. 앞서 이진숙 의원은 5·18민주화운동 폄훼 글에 ‘좋아요’를 눌러 논란이 된 적 있다. 지난 5일 이진숙 의원은 자신의 페이스북에 “배재고에 화환을 보냈다. 스타벅스가 5·18 모욕과 무슨 관계가 있는지 설명해 주실 분 댓글 달아주세요. 만약 스타벅스가 5·18과 광주에 대한 모욕을 상징한다면 스타벅스는 더 이상 영업해서는 안 될 것”이라며 “그 민주 세력의 추정으로 스타벅스 가야지가 광주 5·18 모욕이라고 단정하고 배재고 야구부 학생들을 징계한다면, 그들은 ‘생각에 수갑을 채우는 짓’을 시작하는 것”이라고 주장했다. 이진숙 의원은 2024년 7월 국회에서 진행된 방통위원장 후보 인사청문회 당시에도 5·18 민주화운동과 관련한 인식이 문제가 됐다. 당시 “5·18이 민주화 운동인가. 개인 생각을 말해달라”라는 질문에 끝까지 대답하지 않았다. 또 방통위원장 후보가 되기 전 ‘5·18은 폭도들의 선전선동에 의해 사망자 속출한 비극의 날’이라는 게시물에 ‘좋아요’ 버튼을 누르기도 했다. 이를 두고 당시 야당 의원들의 질책이 이어지자, 이진숙 당시 후보는 “손가락 운동에 신경 쓰겠다”라고 답했다. 야당 의원이 “일본군 위안부 강제적인가” 묻자, 이진숙 당시 후보는 “논쟁적인 사안이기 때문에 답변하지 않겠다”라고 답했다. 정작 배재고 학생들은 6일 광주제일고를 찾아 피해 학생들과 광주 시민들에게 사과했다. 이날 배재고 야구부 주장 A군이 낭독한 사과문에서 “6월29일 목동야구장에서 펼쳐진 청룡기 야구대회에서 꿈과 희망이 담겨야 하는 야구장에서 배재고등학교 선수들의 부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주제일고 선수들과 학부모님, 광주 시민분들에게 진심으로 사과드립니다”라고 밝혔다. 더불어민주당 공보국은 같은 날 <학생들은 성숙하게 사죄했고, 국회의원은 미숙하게 화환을 보냈습니다> 제목의 서면브리핑을 내고 “배재고 야구부 학생들과 지도부, 학부모들은 자신들의 언행이 지닌 무게와 잘못을 깨닫고, 오늘 광주일고를 찾아 고개 숙여 사과의 뜻을 전한다. 나아가 두 학교 학생들은 손을 맞잡고 국립 5·18 민주묘지를 함께 참배할 예정이다. 잘못을 인정하고 책임 있는 자세로 사죄에 나선 배재고의 용기와, 이를 너른 마음으로 받아들인 광주일고 공동체의 포용에 경의를 표한다”라고 했다. 민주당은 이어 “배재고 사태에 대한 교육적 해결 절차가 차분히 진행 중임에도, 국민의힘 일각에서는 이를 정쟁의 소재로 삼으려 하고 있다. 특히 국민의힘의 모 의원이 배재고에 응원 화환을 보낸 행동은 매우 부적절하며, 최소한의 역사의식마저 의심케 하는 처사다. 갈등을 중재하고 상처를 치유해야 할 책임이 있는 국회의원이, 배재고 사태를 지지층 결집의 불씨로 삼고 있는 것은 아닌지 강한 유감을 표한다”라고 밝혔다.', 'crawl', '미디어오늘', '2026-07-06 21:48:06', '진보', 'ready', 'https://cdn.mediatoday.co.kr/news/photo/202607/335601_480694_501.jpeg', '2026-07-07 06:04:38', '2026-07-07 17:58:21.871443', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3776, 'https://www.mediatoday.co.kr/rss/S1N2.xml', NULL, 'https://www.mediatoday.co.kr/news/articleView.html?idxno=335587', '정치', '배재고 사과 전날 화환 보낸 이진숙 “스타벅스, 5·18 무슨 관계?”', '배재고등학교 야구부 선수들이 광주일고와의 경기에서 5·18민주화운동을 폄훼하고 희생자를 욕보였다고 비판 받은 스타벅스 및 ‘탱크데이’ 구호를 외친 것을 사과하기로 한 가운데, 이진숙 국민의힘 의원이 “배재고등학교에 화환을 보냈다”고 밝혔다,이진숙 의원은 5일 “스타벅스가 5·18과 무슨 관계냐?” “배재고 학생들과 함께 합니다”라는 글귀가 적힌 화환을 배재고에 보냈다면서 관련 사진을 자신의 페이스북 계정에 게시했다.그러면서 “스타벅스가 5·18 모욕과 무슨 관계가 있는지 설명해 주실 분 댓글 달아달라. 만약 스타벅스가 5·18과 광', '2026년 7월5일 이진숙 국민의힘 의원이 자신의 페이스북에 게시한 배재고 관련 화환 사진과 이진숙 의원. 배재고등학교 야구부 선수들이 광주일고와의 경기에서 5·18민주화운동을 폄훼하고 희생자를 욕보였다고 비판 받은 스타벅스 및 ‘탱크데이’ 구호를 외친 것을 사과하기로 한 가운데, 이진숙 국민의힘 의원이 “배재고등학교에 화환을 보냈다”고 밝혔다, 이진숙 의원은 5일 “스타벅스가 5·18과 무슨 관계냐?” “배재고 학생들과 함께 합니다”라는 글귀가 적힌 화환을 배재고에 보냈다면서 관련 사진을 자신의 페이스북 계정에 게시했다. 그러면서 “스타벅스가 5·18 모욕과 무슨 관계가 있는지 설명해 주실 분 댓글 달아달라. 만약 스타벅스가 5·18과 광주에 대한 모욕을 상징한다면, 스타벅스는 더이상 영업을 해서는 안될 것”이라면서 “‘생각에 수갑을 채우는 나라’는 어딘가. 김정은은 북한에서 성역”이라고 썼다. 이 의원은 이어 “공포에 질려있을지도 모를 배재고 학생들에게 조금이나마 힘을 주고 싶어서 화환을 보냈다”라면서 “그들이 미래 세대, 자유민주주의를 지켜낼 주역”이라고 주장했다. ‘#성역이_많은_나라는_독재국가’, ‘#배재고_학생들과_함께_합니다’ 등의 해시태그도 붙였다. 이 글에서 이 의원은 최교진 교육부 장관이 과거 박정희 대통령 서거일, 안중근 의사의 이토 히로부미 저격 등이 이뤄진 10월26일에 대해 “‘탕탕절’이라고 부르기도 한다지요”라고 썼던 게시글 등 사진을 함께 올리기도 했다. 배재일고 사과 하루 전, 광주일고 폭발물 협박 신고 등 불거진 가운데 화환 사진 올려 이 의원은 이런 게시글을 오는 6일로 예정된 배재고 야구부의 광주일고 공식 사과 방문을 하루 앞두고 올렸다. 경찰이 온라인 상에 광주일고에 폭발물을 설치했다는 협박 글이 게시됐다는 신고를 받고 수사에 착수한 날이기도 하다. 이에 앞서 서울 강동구에 위치한 배재고 앞에는 야구부 선수들을 비판하거나, 오히려 옹호하는 화환들이 대거 설치돼 강동구가 이를 수거하는 일도 있었다. 이런 가운데 제1야당 국회의원이 다시금 색깔론을 꺼내든 것이다. 이 의원은 지난 2024년 윤석열 정부 방송통신위원회 위원장 신분으로 극우 성향 유튜브 출연 등을 통해 ‘가짜 좌파들과 싸우는 전사들이 필요하다’라는 취지의 주장을 펼쳐 공직선거법 위반 등 혐의로 수사 받고 있다. 앞서 배재고 선수들은 지난달 29일 청룡기 전국고교야구대회 경기 후반에 광주일고 선수들을 향해 “가야지, 가야지, 스타벅스 가야지” 구호를 율동과 함께 외쳤고, 일부 학생은 “탱크데이”라고 큰 소리로 외쳤다. 스타벅스코리아가 5·18민주화운동 기념일 무렵 ‘탱크데이’ 마케팅을 펼치며 ‘책상에 탁’ 등의 문구를 쓴 논란이 불거진 이후 생긴 일이었다. 스타벅스의 ‘탱크데이’ 마케팅은 5·18 당시 계엄군의 탱크 진압, 1987년 고 박종철 열사 고문치사 사건 당시 치안본부가 ‘책상을 탁! 치니 억! 하고 죽었다’고 발표한 일 등을 희화화했다는 비판을 불렀다. 이 사태로 정용진 신세계 회장, 스타벅스 글로벌 본사 등이 사과했다.', 'crawl', '미디어오늘', '2026-07-05 16:41:01', '진보', 'ready', 'https://cdn.mediatoday.co.kr/news/photo/202607/335587_480671_3636.jpeg', '2026-07-07 06:04:38', '2026-07-07 17:59:17.32559', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3785, 'https://www.mediatoday.co.kr/rss/S1N2.xml', NULL, 'https://www.mediatoday.co.kr/news/articleView.html?idxno=335554', '정치', '배재고 응원 화환 등장에 MBC 앵커 “어른들이 아이 미래 망쳐”', '학살 피해 조롱 응원으로 출전정치 6개월 징계를 받은 배재고 야구부를 두고 비판하는 근조화환에 이어 조롱에 동조한 맞불 응원 화환까지 학교 앞에 등장해 논란이다. MBC 앵커는 자신들의 이익과 만족을 위해서라면 혐오를 넘어 아이들의 미래까지 망치고 있다고 비판했고, JTBC 앵커는 강속구 던지는 법과 스윙 잘하는 법만 가르친 감독과 코칭 스태프가 아픔에 공감하는 법은 가르치지 않았다고 지적했다.KBS와 MBN은 징계가 가혹하다는 지적이 나온다는 점을 강조했고, 조선일보 에디터는 여야가 갈등을 증폭시키고 있다고 지적했다.조현용 MBC', '▲조현용 MBC 앵커가 2026년 7월2일 뉴스데스크 앵커멘트에서 학살 피해 조롱 응원을 해 징계를 받은 배재고 야구부 학생을 두둔하는 화환이 늘어선 것을 두고 어른들이 아이들의 미래까지 망치고 있다고 지적하고 있다. 사진=MBC 뉴스데스크 영상 갈무리 학살 피해 조롱 응원으로 출전정치 6개월 징계를 받은 배재고 야구부를 두고 비판하는 근조화환에 이어 조롱에 동조한 맞불 응원 화환까지 학교 앞에 등장해 논란이다. MBC 앵커는 자신들의 이익과 만족을 위해서라면 혐오를 넘어 아이들의 미래까지 망치고 있다고 비판했고, JTBC 앵커는 강속구 던지는 법과 스윙 잘하는 법만 가르친 감독과 코칭 스태프가 역사의 아픔에 공감하는 법은 가르치지 않았다고 쓴소리했다. KBS와 MBN은 징계가 가혹하다는 지적이 나온다는 점을 강조했고, 조선일보 에디터는 여야가 갈등을 증폭시키고 있다고 지적했다. 조현용 MBC 앵커는 지난 2일 저녁 ‘뉴스데스크’ <기자의눈 학교 앞 늘어선 화환 … ‘혐오’ 응원하는 어른들> 앵커 멘트에서 “오늘(2일) 배재고등학교 앞에는 학살 피해를 조롱하며 물의를 빚은 야구 선수단을 도리어 응원하는 화환들이 늘어섰다”라며 “자신들의 이익과 만족 등을 위해서라면 인권유린과 혐오마저 확산시키는 이런 어른들이 여론을 오염시키는 걸 넘어 아이들의 미래까지 망치고 있는 것”이라고 질타했다. 이혜리 MBC 기자는 해당 칼럼성 리포트에서 배재고 앞 현장에서 조롱 응원을 한 야구부를 비판하는 근조 화환과 함께 ‘자랑스러운 애국청년들’, ‘스포츠 오염시키는 5·18’ 등 되레 야구부를 두둔하고 5·18을 조롱하는 화환을 소개하면서 “갈라진 근조화환과 축하화환을 바라보는 학생들의 심경은 혼란스러울 수밖에 없다”라고 평가했다. 이 기자는 “어른들이 정치적으로 접근하는 행위가 현대사의 의미를 되새기려는 학생들을 오히려 방해하고 있다”며 “배재고 야구부에 내려진 중징계가 이번 사안의 해결책은 될 수 없다. 아이들의 일상에 침투한 조롱과 혐오의 언어를 걷어낼 수 있는 범사회적인 대책이 필요해 보인다”라고 촉구했다. 오대영 JTBC 앵커는 ‘뉴스룸’ ‘앵커 한 마디’ <그때, 더그아웃의 어른들은… >에서 조롱 응원 사태라는 참담한 결과 뒤에 무겁고 본질적인 질문이 숨어 있다라며 “‘그때, 어른들은 어디에 있었나’. 목청껏 혐오를 뿜어내던 순간, 더그아웃의 어른들은 기괴하리만큼 조용했다. 눈과 귀를 닫았다면, 그건 방관을 넘어 직무유기”라고 지적했다. 오 앵커는 “시속 150km의 강속구를 던지는 법, 정교하게 배트 돌리는 법을 가르쳤을진 몰라도, 우리가 발딛고 선 이 땅의 역사적 아픔을 공감하는 법은 단 한 줄기도 가르치지 않은 것”이라며 “더그아웃과 교실, 나아가 이 사회의 기성세대는 아이들의 잘못을 따갑게 질타하는 것 만큼이나 뼈아픈 자성과 책임의 시간을 마주해야 한다”라고 털어놨다. ▲오대영 JTBC 앵커가 2일 뉴스룸 앵커 한 마디에서 강속구를 던지고 스윙을 잘하는 법을 가르쳤을 지는 몰라도 감독과 코칭스태프가 역사적 아픔에 공감하는 법은 가르치지 않았다고 비판하고 있다. 사진=JTBC 뉴스룸 영상 갈무리 이수진 JTBC 앵커도<“왜 학생만” 배재고 어른들 징계는 없다?> 앵커 멘트에서 “배재고 사태에서 제대로 책임지는 어른이 없다는 것도 큰 문제”라며 “책임져야 할 어른들은 빠져나가고 아이들만 남았다는 비판이 거세다”라고 지적했다. 이 앵커는 이어 <입시프로행 타격 … 징계 외 ‘해야 할 것’>에서도 “비판을 받아 마땅하지만, 선수이기 전에 학생인 만큼 지나친 낙인은 경계해야 한다는 목소리도 나온다”라고 언급했다. 배성규 조선일보 정치에디터는 TV조선 ‘뉴스9’ 스튜디오에 출연해 “코칭스태프가 먼저 제지를 했어야 했다”라며 “여기엔 스포츠맨십과 인성·역사 교육을 하지 못한 학교와 협회의 책임도 있다. 그런데 선수들에게만 책임을 지웠다는 지적”이라고 비판했다. 배 에디터는 “여야가 이런 갈등을 해결하기는커녕 정치적으로 증폭시키고 있다”라며 “지나친 정치화는 역풍을 부를 수 있다. 갈등을 완화하는 노력이 필요할 것 같다”라고 지적했다. 윤정호 TV조선 앵커는 “모든 게 과하면 지나치다. 상식적인 선에서 해결할수 있으면 좋겠다”라고 거들었다. 유호정 MBN 앵커는 ‘뉴스7’ <“아이들 장래 막아” “선배로서 부끄러워”> 앵커 멘트에서 “학생들의 진학 길까지 막는 과도한 징계라는 비판과 함께, 제대로 지도하지 못한 어른들을 향한 책임론도 나온다”라고 우려했다. MBN은 리포트에서 야구계 일각에선 학생 선수들의 진로를 막는 가혹한 처사라는 목소리도 나온다라며 오히려 도를 넘은 막말을 막지 못한 지도자와 심판진 등 어른들의 소극적인 대처에 대한 아쉬움이 컸다고 보도했다. 관련기사 표현의 자유? 보수단체·국힘, 배재고 ‘혐오발언’ 진영대결로 만드나 배재고 징계에 국힘 “표현자유, 이재명탓”? … SBS “제재 없어 조롱 난무” “광주일고 동창 계엄군 총에 사망했는데… 배재고 응원 있을 수 없어” “탱크데이” 혐오 발언한 배재고 야구부, 6개월 동안 경기출전 못한다 더보기 ▲유호정 MBN 앵커가 2026년 7월2일 배재고가 조롱 응원으로 받은 6개월 출전정지가 과하다는 지적이 나온다면서 이를 막지 못한 어른들의 책임론도 나온다고 언급하고 있다. 사진=MBN 뉴스7 영상 갈무리 KBS는 ‘뉴스9’ <‘조롱성 응원’ 6개월 중징계 … 선수 영향은?>에서 “출전 기록과 대회 실적이 생명인 선수들에겐 사형 선고와 같다는 지적도 나온다”라고 우려한 뒤 “배재고 정문엔 근조 화환과 응원 화환이 뒤엉켜 갈등이 더 깊어지고 있다”라고 언급했다. 채널A는 ‘뉴스A’ <“역사 망각” vs “기죽지 마” … 화환 싸움>에서 배재고 학생이 “표현의 자유니까 저는 이거 놓는 것 자체는 문제가 없지만, 저희 기분이 좀 그렇긴 하다”라는 인터뷰 내용을 소개했을 뿐 별다른 판단없이 양쪽 주장을 나열하는 데 그쳤다.', 'crawl', '미디어오늘', '2026-07-03 12:06:55', '진보', 'ready', 'https://cdn.mediatoday.co.kr/news/photo/202607/335554_480622_4644.jpg', '2026-07-07 06:04:38', '2026-07-07 18:00:26.782918', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3787, 'https://www.mediatoday.co.kr/rss/S1N2.xml', NULL, 'https://www.mediatoday.co.kr/news/articleView.html?idxno=335536', '정치', '배재고 징계에 국힘 “표현자유, 이재명탓”? … SBS “제재 없어 조롱 난무”', '국민의힘 인사들이 청룡기 전국고교야구에서 광주일고 선수에게 ‘스타벅스 가야지’ 조롱을 한 배재고 야구부에 6개월 출전정지 결정한 대한야구소프트볼협회에 “표현의 자유”, “이재명 탓”, “개탄스럽다”며 반발하고 나서 논란이다. 이에 반해 SBS는 학생들의 조롱, 극우성 발언이 난무하는 이유를 두고 “강력한 제재사례가 없어서”라고 지적하기도 했다. 국민의힘에 고개숙여 참회하라는 정치권 비판도 나왔다.이준성 대한야구소프트볼협회 홍보위원은 지난 1일 기자회견에서 “스포츠공정위원회 결과 배재고등학교 야구부에 대해서 출전 정지 6개월을 결론', '이지애 국민의힘 미디어대변인이 2026년 7월1일 고성국TV에 출연해 스타벅스 응원이 표현의 자유라며 징계조치는 지나치다라고 말하고 있다. 국민의힘 인사들이 청룡기 전국고교야구에서 광주일고 선수에게 ‘스타벅스 가야지’ 조롱을 한 배재고 야구부에 6개월 출전정지 결정한 대한야구소프트볼협회에 “표현의 자유”, “이재명 탓”, “개탄스럽다”며 반발하고 나서 논란이다. 이에 반해 SBS는 학생들의 조롱, 극우성 발언이 난무하는 이유를 두고 “강력한 제재사례가 없어서”라고 지적하기도 했다. 국민의힘에 고개숙여 참회하라는 정치권 비판도 나왔다. 이준성 대한야구소프트볼협회 홍보위원은 지난 1일 기자회견에서 “스포츠공정위원회 결과 배재고등학교 야구부에 대해서 출전 정지 6개월을 결론 내렸다”라며 “내일(2일) 배제고 출전 2회전부터 당장 적용된다”라고 밝혔다. 지도자 및 선수에 대한 징계는 6개월 이내에 다시 스포츠공정위를 열어 다시 결정하기로 했다고도 했다. 이지애 국민의힘 미디어 대변인은 1일 유튜브 고성국TV에 출연해 “정치적 발언이 아니고 학생들이 스타벅스 가자, 커피 마시러 가자는 표현의 자유의 부분인데 이걸로 교육위원회 회부해 조치하겠다라는 것은 너무 지나친 조치”라고 말했고, 같은 당의 손수조 미디어대변인은 “스타벅스 사태를 촉발시키고 사회적 갈등으로 만들어 갈라치게 한 것이 이재명 정권 아니냐”, “징계까지 하는 행태 자체가 굉장히 과하다”라고 주장했다. 나경원 의원도 이날 페이스북에 “과연 합당한가? 스벅 가는 자유도 뺏더니, 아이들 꿈마저 빼앗나, 이것이 이재명 정권 치하의 부끄러운 대한민국의 모습이다. 개탄스럽다”라고 썼다. 김재원 국민의힘 최고위원은 2일 최고위원회의에서 “이 징계는 명백히 과도하고 폭력”이라며 “대학 진학과 프로 입단을 앞둔 학생 선수 전원에게 사실상 야구 인생을 끝장내는 처분을 내렸다”라고 말했다. 김 위원은 방송인 최욱 씨가 극단적인 발언을 하고도 사과 한 번 하고 넘어간 것과 비교하면, 이 나라 어른들의 막말엔 관대하고, 아이들의 철없는 응원가에 너무나 잔인하고 폭력적이라고 비난했다. 우재준 청년 최고위원도 회의에서 “5·18민주화운동을 비하하는 듯한 발언은 적절하지 않다”라면서도 “다만, 학생들이 어린 친구들인데 너무 지나친 징계하는 것도 적절하지 않다”라고 말했다. 이에 반해 양향자 최고위원은 “한 고등학교 야구부의 조롱 섞인 응원 문제가 진보·보수 진영 간 싸움으로 번지고 있다. 자중해야 한다”라고 지적했다. “벌이 너무 과하다”라는 점을 지적하면서도 양 최고위원은 “문제 학생들의 프로선수 진출을 막아야 한다, 반대로 그런 응원이 뭐가 문제냐는 등의 극단적 주장은 문제 해결은커녕 더 큰 혼란과 갈등을 일으키는 일”이라고 경계했다. 이번 사건은 역사적 진실에 대한 올바른 이해와 나와 다름이 혐오가 되지 않는 문화로 귀결되어야 한다고도 했다. 정점식 국민의힘 원내대표도 1일 페이스북에 배재고 선수들의 행위가 부적절한 행동이었다고 지적하면서도 “전국대회 출전 6개월 정지 징계를 내린 것은 지나친 조치라고 여겨진다. 배재고 선수 전체가 잘못을 저지른 것도 아니고, 조롱에 동조하지 않은 선수들도 많이 있는데 배재고 야구부 전체에 6개월 출전정지 징계는 과도하다”라고 썼다. 홍성규 진보당 대변인은 2일 논평에서 ‘과도하다’는 정 원내대표와 ‘개탄스럽다’는 나경원 의원의 반발을 두고 “’과도’와 ‘개탄’ 이전에 사과와 반성부터 해야 마땅하다”라며 “장동혁 대표의 ‘커피 한 잔의 자유’ 궤변이 이번 배재고에까지 이어진 것 아니냐”라고 비판했다. 홍 대변인은 진심으로 고개 숙여 사과하고 참회하는 것이 바로 정점식 원내대표가 언급했던 ‘교육과 지도의 책무’일 것이라고 촉구했다. 주진희 MBN 기자는 ‘뉴스7’ 스튜디오에 출연해 차동철 전 해태 타이거즈 선수가 과거 청룡기 대회를 준비하던 관사에 계엄군이 쳐들어온 육성, 계엄군이 대검을 자신의 가슴까지 들이댔던 방수원 전 해태 투수의 회고 영상을 소개했다. 주 기자는 “광주제일고 야구부 역사엔 이런 아픔이 있다”라며 “물론 배재고 학생선수들이 이런 사연까지 알고서 일부러 그런 건 아니겠지만 앞으론 이런 일이 반복되지 않길 바란다”라고 쓴소리했다.', 'crawl', '미디어오늘', '2026-07-02 17:24:09', '진보', 'ready', 'https://cdn.mediatoday.co.kr/news/photo/202607/335536_480590_434.jpg', '2026-07-07 06:04:38', '2026-07-07 18:01:08.596386', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3811, 'https://www.mediatoday.co.kr/rss/S1N4.xml', NULL, 'https://www.mediatoday.co.kr/news/articleView.html?idxno=335611', '정치', '배재고 징계에 “북한 모습” 이병태 옹호한 조선일보', '주요 공직자와 정치권 인사들이 배재고등학교 야구부 선수들의 5·18민주화운동 폄훼 구호 사태를 정쟁화하면서 논란을 확산시키고 있다. 사태가 발생한 청룡기 전국고교야구선수권대회를의 공동 주최사인 조선일보는 갈등을 부추긴 이병태 전 대통령직속 규제합리화위원회 부위원장 발언을 옹호하거나 사안의 심각성을 축소했다.이병태 전 부위원장은 배재고 선수들이 5·18로 수많은 희생자가 발생한 전남 광주 지역의 광주제일고(광주일고)를 향해 폄훼 구호를 외친 일을 ‘표현의 자유’로 보호해야 한다는 취지의 주장을 펼치며, 한국야구소프트볼협회의 배재고 선', '▲2026년 7월 6일 ''미디어오늘내일 라이브'' 이미지. 사진=유튜브 ''미디어오늘'' 주요 공직자와 정치권 인사들이 배재고등학교 야구부 선수들의 5·18민주화운동 폄훼 구호 사태를 정쟁화하면서 논란을 확산시키고 있다. 사태가 발생한 청룡기 전국고교야구선수권대회를의 공동 주최사인 조선일보는 갈등을 부추긴 이병태 전 대통령직속 규제합리화위원회 부위원장 발언을 옹호하거나 사안의 심각성을 축소했다. 이병태 전 부위원장은 배재고 선수들이 5·18로 수많은 희생자가 발생한 전남 광주 지역의 광주제일고(광주일고)를 향해 폄훼 구호를 외친 일을 ‘표현의 자유’로 보호해야 한다는 취지의 주장을 펼치며, 한국야구소프트볼협회의 배재고 선수단 징계 등 제재가 이뤄지는 상황을 “북한의 모습”에 빗대기도 했다. 조선일보는 지난 6일자 사설에서 이 전 부위원장을 옹호하면서 “최근 상황은 ‘표현의 자유’가 위태로워졌다고 느낄 정도로 지나치다”라며 “계엄 여파로 야당이 지리멸렬한 상태에서 민주당이 압도적 의석수에 취해 독주하는 것과 무관하지 않다”라고 했다. 지난 6일 미디어오늘내일(미오내) 라이브에서 금준경 미디어오늘 기자는 조선일보가 책임감을 갖고 ‘이런 일이 벌어지지 않도록 각별한 노력을 기울이겠다’라는 입장을 내야 한다고 꼬집었다. 윤수현 미디어오늘 기자는 조선일보에 이번 사안 관련 입장을 물었지만 답이 오지 않았다고 전했다. 이 전 부위원장이 5·18 폄훼 구호를 ‘표현의 자유’를 들어 옹호한 것 자체가 부적절하다는 지적도 이어졌다. 금준경 기자는 “지금 언급되는 5·18에 대한 표현들은 (이 전 부위원장이 주장한) ‘엉뚱한 표현들’이 아니다. 특정 지역과 사건의 피해자들에 대해 혐오를 하는 표현”이라며, 미국 고교 야구대회에서 수많은 희생자가 발생한 ‘9·11 테러’ 등에 빗댄 응원을 했다면 용인됐겠느냐고 예를 들어 설명했다. 윤수현 기자는 뿌리 깊은 호남 지역에 대한 혐오가 사회적 문제로 불거진 상황에서 차별과 혐오를 조장하는 발언이 가져오는 문제를 지적하고, 해외 사례를 설명했다. 관련기사 배재고 사과에 피해자 광주일고 “어깨 펴라” 화답 이병태 사퇴에 한겨레 “대통합 차원 인사 실패” 중앙 “갈등 증폭” 이병태 결국 사퇴 “갈등 증폭 불찰…성역 강요는 전체주의” 주장 ‘5·18민주화운동 맞냐’ 답변 회피 이진숙, 배재고 화환… “행동 매우 부적절” 더보기 이번 사안을 정쟁화하는 정치인들의 행태도 문제다. 일례로 윤석열 정부 방송통신위원회(현 방송미디어통신위원회) 위원장을 지낸 이진숙 국민의힘 의원은 광주일고에 대한 배재고의 사과 방문 전날 자신이 배재고에 보냈다는 화환 사진을 공개하면서 배재고를 응원했다. 이 학교 학생들을 비판하거나 옹호하는 화환이 쌓인 것이 교육적으로도 적절하지 않다는 지적이 제기된 가운데 행한 일이다. 이런 사안들에 대해 잘못된 것을 비판하고 사회적 논의의 방향을 짚어내야 하는 언론이 이 의원의 주장을 검증 없이 확산시키며 정쟁을 부추기는 데 일조하고 있다는 비판도 있다. ‘미오내 라이브’는 매주 월요일부터 수요일까지 오후 4시 유튜브 채널 ‘미디어오늘’에서 볼 수 있다.', 'crawl', '미디어오늘', '2026-07-07 12:44:12', '진보', 'ready', 'https://cdn.mediatoday.co.kr/news/photo/202607/335611_480717_3256.jpg', '2026-07-07 06:04:38', '2026-07-07 18:04:15.160896', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3814, 'https://www.mediatoday.co.kr/rss/S1N4.xml', NULL, 'https://www.mediatoday.co.kr/news/articleView.html?idxno=335610', '정치', '배재고 사과에 피해자 광주일고 “어깨 펴라” 화답', '광주제일고가 5·18민주화운동 관련 혐오 표현을 쓴 배재고 측의 사과를 수용했다.지난 6일 광주일고 광장을 찾아 사과를 한 배재고 학생들에게 이규연 광주일고 교장은 “배재고 학생들 고개 들어요. 다음에 저희 (광주)일고 학생들 만날 때 정말 당당하게 서로 있는 기량 마음껏 펼치면서 멋진 승부를 펼쳐주는 것. 그것이 여러분이 용서를 구하는 가장 멋진 모습”이라고 했다. 그러면서 “여러분들의 미래는 아직 끝나지 않았다”고 했다.광주제일고 선수 대표는 “이번 일을 통해 광주일고 야구도 상처주는 언행을 하지 않았는지 돌아보는 계기가 됐다”', '▲배재고와 광주일고 경기 중 배재고 학생들이 “가야지 가야지 스타벅스 가야지” 라는 응원구호를 사용했다. 사진=MBC 유튜브 화면 갈무리 광주제일고가 5·18민주화운동 관련 혐오 표현을 쓴 배재고 측의 사과를 수용했다. 지난 6일 광주제일고 강당을 찾아 사과를 한 배재고 학생들에게 이규연 광주일고 교장은 “배재고 학생들 고개 들어요. 다음에 저희 (광주)일고 학생들 만날 때 정말 당당하게 서로 있는 기량 마음껏 펼치면서 멋진 승부를 펼쳐주는 것. 그것이 여러분이 용서를 구하는 가장 멋진 모습”이라고 했다. 그러면서 “여러분들의 미래는 아직 끝나지 않았다”고 했다. 광주제일고 선수 대표는 “이번 일을 통해 광주일고 야구도 상처주는 언행을 하지 않았는지 돌아보는 계기가 됐다”며 “다시는 이런 일이 발생하지 않길 바란다”고 말했다. 앞서 배재고 야구부 주장은 낭독한 사과문에서 “6월29일 목동야구장에서 펼쳐진 청룡기 야구대회에서 꿈과 희망이 담겨야 하는 야구장에서 배재고등학교 선수들의 부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주제일고 선수들과 학부모님, 광주 시민분들에게 진심으로 사과드립니다”라고 밝혔다. 배재고 야구부 감독은 “광주일고를 향한 저희 야구부 학생 선수들의 지역 비하 응원은 무엇으로도 변명할 수 없는 잘못”이라며 “제대로 가르치지 못한 과오를 인정하며 지도자로서 져야 할 책임을 겸허히 감당하겠다”고 했다. 관련기사 배재고 징계에 “북한 모습” 이병태 옹호한 조선일보 ‘5·18민주화운동 맞냐’ 답변 회피 이진숙, 배재고 화환… “행동 매우 부적절” 배재고 선수단, 광주일고 방문 “선수들과 광주 시민에게 진심으로 사과” 이병태 ‘5·18 성역’ 발언에 경향신문 “‘극우적 표현’의 자유” 더보기 이날 배재고 선수단과 정근식 서울시교육감은 국립 5·18민주묘지 참배를 이어갔다. 앞서 배재고 선수단은 지난달 29일 서울 목동야구장에서 열린 청룡기 전국고교야구선수권대회 1회전에서 광주제일고를 향해 “탱크데이”,“가야지, 가야지, 스타벅스 가야지”라는 구호를 반복해 외치는 등 혐오 발언을 했다.', 'crawl', '미디어오늘', '2026-07-07 10:28:40', '진보', 'ready', 'https://cdn.mediatoday.co.kr/news/photo/202607/335610_480716_329.jpg', '2026-07-07 06:04:38', '2026-07-07 18:04:33.246596', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3820, 'https://www.mediatoday.co.kr/rss/S1N4.xml', NULL, 'https://www.mediatoday.co.kr/news/articleView.html?idxno=335598', '정치', '배재고 선수단, 광주일고 방문 “선수들과 광주 시민에게 진심으로 사과”', '‘스타벅스 가야지’ 응원 구호를 외쳐 파문을 일으킨 서울 배재고등학교 학생들이 6일 광주제일고등학교(광주일고)를 찾아 피해 학생들과 광주 시민들에게 사과했다.이날 배재고 야구분 주장 A군이 낭독한 사과문에서 “안녕하십니까. 배재고 야구부 주장입니다. 먼저 저희가 광주에 발을 딛는 것만으로도 불편하셨을 텐데, 이렇게 귀한 시간 마련해주신 광주일고 관계자분들과 광주일고 선수분께 진심으로 감사드립니다”라고 했다.A군은 “6월29일 목동야구장에서 펼쳐진 청룡기 야구대회에서 꿈과 희망이 담겨야 하는 야구장에서 배재고등학교 선수들의 부적절한', '▲배재고와 광주일고 경기 중 배재고 학생들이 “가야지 가야지 스타벅스 가야지” 라는 응원구호를 사용했다. 사진=MBC 유튜브 화면 갈무리 ‘스타벅스 가야지’ 응원 구호를 외쳐 파문을 일으킨 서울 배재고등학교 학생들이 6일 광주제일고등학교(광주일고)를 찾아 피해 학생들과 광주 시민들에게 사과했다. 이날 배재고 야구부 주장 A군이 낭독한 사과문에서 “먼저 저희가 광주에 발을 딛는 것만으로도 불편하셨을 텐데, 이렇게 귀한 시간 마련해주신 광주일고 관계자분들과 광주일고 선수분께 진심으로 감사드립니다”라고 했다. A군은 “6월29일 목동야구장에서 펼쳐진 청룡기 야구대회에서 꿈과 희망이 담겨야 하는 야구장에서 배재고등학교 선수들의 부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주제일고 선수들과 학부모님, 광주 시민분들에게 진심으로 사과드립니다”라고 했다. 이어 “이번 사건으로 저를 포함한 저희 팀 모든 선수들이 진심으로 깊이 반성하고 있으며 야구를 떠나서 인성이나 태도가 인생에서 얼마나 중요한지 깨닫고 다시 한번 배우게 됐습니다”라며 “광주일고 선수분들에게 정신적으로 큰 피해와 힘듦을 겪게 한 점, 같은 선수로서 정말 하면 안 되는 행동이었고, 일어나면 안 되는 상황이었는데 많은 고통을 드렸다. 진심으로 사과드린다. 저희 선수들의 좋지 못한 발언, 행동으로 인해 정말 많은 분이 마음의 상처와 고통을 받고 계신다. 선수들을 대표해서 정말 진심으로 사과드립니다. 죄송합니다. 항상 마음 속 깊이 반성하는 마음과 자세로 살아가겠습니다. 다시 한번 죄송합니다”라고 했다. 관련기사 ‘5·18민주화운동 맞냐’ 답변 회피 이진숙, 배재고 화환… “행동 매우 부적절” 배재고 징계에 “북한 모습” 이병태 옹호한 조선일보 배재고 사과에 피해자 광주일고 “어깨 펴라” 화답 배재고 야구부 감독 B씨는 “선수들의 지역 비하 응원은 무엇으로도 변명할 수 없는 잘못임을 인정하며, 학생들을 잘 이끌고 가르쳐야 할 지도자로서 책임이 가장 크기에 진심으로 사죄드린다. 깨끗하고 정정당당해야 할 경기에서 상대에 대한 존중과 동업자 정신, 선수로서 가져야 할 태도에 대해 제대로 가르치고 인도하지 못했다. 이기는 것보다 더 중요한 것이 있음을 저도 모르게 잊고 있었고, 저의 언행과 지도 방식이 올바른 본보기가 되지 못한 듯해 더욱 깊이 자책하며 부끄러울 뿐”이라고 밝혔다. 배재고 교장을 포함한 교직원들은 “이번 사태를 단순한 일탈이나 실수가 아닌 윤리 의식과 역사 인식에 대한 총체적인 붕괴에서 비롯된 사례로 보고 심각하게 사안을 받아들이고 있다. 참담하고 부끄러운 마음”이라며 “여러 기관의 조사에도 성실히 응하겠다”라고 설명했다.', 'crawl', '미디어오늘', '2026-07-06 15:38:36', '진보', 'ready', 'https://cdn.mediatoday.co.kr/news/photo/202607/335598_480690_3645.jpg', '2026-07-07 06:04:38', '2026-07-07 18:05:41.712573', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3894, 'https://www.segye.com/Articles/RSSList/segye_politic.xml', NULL, 'https://www.segye.com/newsView/20260707510344', '정치', '“계엄 때 왜 안 와” “대장동 때 보는 듯”…또 도마 오른 金의 행적', '김 전 총리는 7일 12·3 비상계엄 당시 자신의 행적을 문제 삼는 친청(친정청래)계의 질타를 ‘대장동 공세’에 빗대며 역공에 나섰다. 20대 대선 경선 후보였던 이재명 대통령이 당내에서 제기된 대장동 의혹에 직면했던 일을 소환하며 자기방어에 나선 것이다. 대장동 의혹은 이 대통령의 ‘사법 리스크’로 거론됐던 사안 중 하나다. 정청래 전 대표는 “동지의 언', '재조명된 계엄해제안 표결 불참 “표결 당시 국회 안에 있었고 표결 직후 본회의장에 착석해” 鄭, ‘네거티브 중단’ 선언하며 “李와 내란 이겨낸 이들 뭉치자” “(계엄 때) 감기약 먹고 잤다고 하는데, 그 감기약 성분이 뭔가.”(더불어민주당 이성윤 최고위원) “무슨 꼭 대장동 때를 보는 것 같다.”(김민석 전 국무총리) 김민석 전 국무총리(왼쪽), 더불어민주당 이성윤 최고위원. 뉴시스 김 전 총리는 7일 12·3 비상계엄 당시 자신의 행적을 문제 삼는 친청(친정청래)계의 질타를 ‘대장동 공세’에 빗대며 역공에 나섰다. 20대 대선 경선 후보였던 이재명 대통령이 당내에서 제기된 대장동 의혹에 직면했던 일을 소환하며 자기방어에 나선 것이다. 대장동 의혹은 이 대통령의 ‘사법 리스크’로 거론됐던 사안 중 하나다. 정청래 전 대표는 “동지의 언어를 쓰겠다”고 강조하는 등 ‘네거티브 중단’ 선언을 했던 이재명 경선 후보를 벤치마킹하려는 기색이다. 김 전 총리는 이날 KBS라디오에서 “(계엄 당시) 표결하는 시점에 국회 안에 있었고, 표결 직후에 본회의장에 착석했다”고 했다. 이어 “계엄과 관련한 전화를 받고 거기(국회)에 오지 않았냐는 것은 허위사실에 의한 명예훼손”이라고 날을 세웠다. 친청계인 이 최고위원이 계엄 당일 김 전 총리가 본회의장에 출석하지 않은 점을 공개 저격한 데 대한 반박이었다. 이 최고위원은 전날 페이스북에서 “온 국민이 다 알듯이 김 전 총리가 윤석열 계엄해제 국회 표결에는 불참했는데, 왜 하지 않았나”라고 추궁했다. 이어 “어느 글에 ‘잠을 자는 사람은 깨울 수 있어도 자는 척하는 사람은 깨울 수 없다’고 하던데, 그런가”라고 압박했다. 윤석열 전 대통령이 위헌적 계엄을 선포했던 2024년 12월3일 당시 우원식 국회의장과 민주당 의원 대다수는 국회 본회의에서 계엄해제결의안을 의결했다. 한동훈 당시 국민의힘 대표(현 무소속 의원)도 친한(친한동훈)계 의원들을 이끌고 국회로 가 결의안 표결에 참석하도록 독려했다. 그러나 계엄 가능성을 예견했던 김 전 총리는 본회의에 출석하지 않아 입방아에 올랐다. 국회는 김 전 총리의 지역구(서울 영등포을)에 있다. 정 전 대표는 네거티브와 거리 두기를 하며 ‘원팀’ 행보를 이어갈 방침이다. 그는 페이스북에 “김대중을 존경하는 사람들, 노무현을 사랑하는 사람들, 문재인을 좋아하는 사람들, 이재명과 함께 12·3 비상계엄 내란을 이겨낸 사람들 똘똘 뭉치자”며 “단결하면 승리한다. 저는 단결의 언어, 동지의 언어만 쓰겠다”고 했다. 다른 글에서도 이재명정부 성공과 정권 재창출을 강조하며 “저는 네거티브를 하지 않겠다”고 했다.', 'crawl', '세계일보', '2026-07-07 11:24:43', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707510538.jpg', '2026-07-07 06:04:40', '2026-07-07 18:16:03.363755', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3898, 'https://www.segye.com/Articles/RSSList/segye_politic.xml', NULL, 'https://www.segye.com/newsView/20260707508621', '정치', '캐나다 잠수함 고배 아쉬움 딛고…李대통령, ‘방산외교’ 위해 튀르키예로 출국', '이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 이 대통령은 이번 주 나토 정상회의 참석에 이어 몽골 국빈 방문까지 3박 5일간의 정상외교 일정을 소화한다. 나토 정상회의에 참석하는 도널드 트럼프 미국 대통령과의 회담 성사 여부도 주목된다. 이 대통령은 이날 오전 경기 성남시 서울공항에서 튀르키예 앙카라', '이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 튀르키예로 출국했다. 이 대통령은 이번 주 나토 정상회의 참석에 이어 몽골 국빈 방문까지 3박 5일간의 정상외교 일정을 소화한다. 나토 정상회의에 참석하는 도널드 트럼프 미국 대통령과의 회담 성사 여부도 주목된다. 이 대통령은 이날 오전 경기 성남시 서울공항에서 튀르키예 앙카라로 출국했다. 출국 행사에는 강훈식 대통령 비서실장과 홍익표 정무수석, 더불어민주당 한병도 당대표 직무대행, 윤호중 행정안전부 장관 등이 참석했다. 이 대통령은 앙카라 도착 후 마르크 뤼터 나토 사무총장과 면담을 가진 뒤 뤼터 총장과 일본, 호주, 뉴질랜드 등 인도태평양 파트너국 소인수회담에 참석한다. 이후 나토 정상회의 메인 행사인 방위산업포럼에 참석해 ‘대한민국과 나토의 방위산업 연대’를 주제로 기조연설에 나선다. 이 대통령은 대한민국이 나토와 공동의 가치를 바탕으로 방위산업 역량을 함께 축적해 온 파트너라는 점을 강조할 것으로 보인다. 이날 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령이 주최하는 공식 환영 만찬에도 참석한다. 트럼프 대통령 역시 앙카라를 찾아 나토 정상회의에 참석하는 만큼 두 정상의 회담 가능성도 거론되고 있다. 이 대통령은 미국 외에도 나토 내 방산 협력 수요국들과의 양자 회담을 추진 중인 것으로 전해졌다. 이 대통령은 순방길에 오르며 남긴 페이스북 메시지에서 “(뤼터) 총장님께서 ‘한국을 사랑한다’며 우리 방위산업 기반이 ‘환상적’이라고 평가해 주셨다고 한다”며 “국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다”고 했다. 또 한화오션의 수주 불발 소식이 알려진 캐나다 잠수함 프로젝트와 관련해서는 “K-방산의 담대한 도전은 계속된다”며 “우리 잠수함이 세계 바다의 평화와 안전을 수호하게 될 그 날을 위해 정부가 할 수 있는 모든 것을 다하겠다”고 말했다.', 'crawl', '세계일보', '2026-07-07 10:34:00', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707508851.jpg', '2026-07-07 06:04:40', '2026-07-07 18:16:34.019351', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3900, 'https://www.segye.com/Articles/RSSList/segye_politic.xml', NULL, 'https://www.segye.com/newsView/20260707508520', '정치', '한병도 “247만장 투표용지 재검표 추진안 적극 검토”', '더불어민주당 한병도 대표직무대행 겸 원내대표는 7일 6·3 지방선거 투표용지 부족사태와 관련해 서울 올림픽공원 핸드볼경기장에 보관중인 247만표의 재검표 방안을 적극 검토하겠다는 입장을 밝혔다. 한 원내대표는 이날 국회에서 열린 원내대책회의에서 “투표용지 247만장에 대한 재검표와 수개표를 여야 협의를 통해 국조특위에서 추진하는 방안을 적극 검토하겠다', '더불어민주당 한병도 대표직무대행 겸 원내대표는 7일 6·3 지방선거 투표용지 부족사태와 관련해 서울 올림픽공원 핸드볼경기장에 보관중인 247만표의 재검표 방안을 적극 검토하겠다는 입장을 밝혔다. 한 원내대표는 이날 국회에서 열린 원내대책회의에서 “투표용지 247만장에 대한 재검표와 수개표를 여야 협의를 통해 국조특위에서 추진하는 방안을 적극 검토하겠다”며 이같이 밝혔다. 이는 국민의힘 소속 윤상현 특위 위원장이 제시한 ‘공개 재검표’ 추진 계획에 대한 긍정적인 답변으로 여겨진다. 앞서 윤 위원장은 5일 기자회견에서 공개 재검표를 추진할 계획이라고 언급한 바 있다. 윤 위원장은 “지지난주부터 위철환 중앙선거관리위원장 직무대행에게 247만표 유·무효표에 대해 공개적으로 재검증하자고 했다”며 “선관위 입장에서도 그것에 대해 잘못된 투·개표가 없다는 것을 보여줘야 하지 않느냐”고 했다. 윤 위원장은 “(선관위가 경기장을) 임차하는 비용이 7월 10일까지 약 2억원이 든다고 하는데, 사람들을 동원해 재검표하는 데 5000만원 정도가 들 것으로 예상된다”며 “계속해서 임차하면서 비용이 드는 것보다 한 번에 정확히 재검표하는 것이 그것(봉쇄된 투표함)을 옮길 명분도 생기는 게 아닌가 생각한다”고 했다. 윤 위원장은 “지난주 중앙선관위 기관 보고에서 강동완 사무총장 대행도 ‘좋다, 하겠다’는 의견을 제시했다”고 했었다. 한 원내대표는 “중요한 것은 국민 참정권 침해의 진상을 밝히고, 책임자 처벌을 통해 선거 사무에 대한 국민 신뢰를 회복하는 일”이라며 “선관위도 책임을 다해야 한다. 국민의힘도 국민 참정권을 정쟁으로 몰아가려는 시도를 그만두고, 실체적, 진실을 밝혀내는 데 온 힘을 모으기를 바란다”고 했다.', 'crawl', '세계일보', '2026-07-07 10:30:22', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707508684.jpg', '2026-07-07 06:04:40', '2026-07-07 18:16:44.14834', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3903, 'https://www.segye.com/Articles/RSSList/segye_politic.xml', NULL, 'https://www.segye.com/newsView/20260707507947', '정치', '선관위 "투표지 247만장 이송 전 검증에 9시간·5000만원 소요"', '중앙선거관리위원회는 7일 송파구 잠실 올림픽공원 개표소에 보관된 6·3 지방선거 투표용지들을 이송 전 검증하는 데 총 9시간이 걸리고 비용은 5천만원이 소요될 것으로 추산했다. 중앙선관위는 이날 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위의 2차 현장조사에서 투표지 이송방안을 보고하며 이같이 밝혔다. 중앙선관위는 먼저 "투표지 등을 임시공간에', '국조특위 2차 현장조사서 추산 보고…"검증에는 국회 의결 필요" 중앙선거관리위원회는 7일 송파구 잠실 올림픽공원 개표소에 보관된 6·3 지방선거 투표용지들을 이송 전 검증하는 데 총 9시간이 걸리고 비용은 5천만원이 소요될 것으로 추산했다. 중앙선관위는 이날 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위의 2차 현장조사에서 투표지 이송방안을 보고하며 이같이 밝혔다. 국회 ''제9회 전국동시지방선거 투표용지 부족 사태 등 국민 참정권 침해 진상규명 및 선거관리 개혁을 위한 국정조사 특별위원회'' 위원들이 지난 2일 현장 조사를 위해 서울 송파구 올림픽공원 핸드볼경기장 개표소로 들어가고 있다. 중앙선관위는 먼저 "투표지 등을 임시공간에 장기간 보관함에 따른 국민적 불안감 및 의혹을 해소하고, 올림픽공원 핸드볼경기장 본연의 기능을 할 수 있도록 원상복구 할 필요성이 있다"고 밝혔다. 현재 잠실 개표소에 보관된 투표지는 서울시장 선거 총 37매, 송파구의회의원 마선거구 총 25만매, 잠실7동 총 4만매 등 총 247만매이다. 앞서 국조특위가 지난 2일 올림픽공원을 찾아 현장을 확인한 바 있다. 중앙선관위는 이송 전 투표지 육안 재확인과 정당·후보자별 분류 및 확인 등 검증을 하려면 인력 440명, 예산 5천만원이 필요하고 총 9시간이 소요될 것으로 보고했다. 투표지 이송장소로는 중앙선관위 과천청사를 꼽으며 그 이유로 송파구선관위 청사는 동일 건물 내 유치원과 산후조리원이 입주해있고, 건물 앞 집회가 장기화하면 시민 불편이 극심해질 것을 꼽았다. 중앙선관위 과천청사는 출입 통제가 용이하고, 워낙 집회가 수시로 발생하는 장소라 경찰 협조로 경비도 가능해 추가 혼란을 최소화할 수 있다는 게 중앙선관위 판단이다. 중앙선관위는 투표지 이송 방안에 대해선 국회 원내정당별 추천자 각 1명 참관하에, 차량에 적재 후 중앙선관위로 이송하겠다고 밝혔다. 차량 적재 및 이송과정을 촬영하고, 이송 차량에는 참관인과 경찰관이 동승해야 한다고도 덧붙였다. 이송 후에는 출입구에 이송 참관인이 서명한 특수봉인지를 부착하고 내부와 출입구에 CCTV를 설치해 상시 녹화하겠다는 계획도 밝혔다. 아울러 중앙선관위는 이송 전 별도의 검증 등 사전 조치가 필요하다고도 강조했다. 다만 현행 법규상 선관위 자체 직권 재검표는 법적 근거가 없어, 해당 투표지가 선거 당일 사용한 투표지라는 무결성을 입증하려면 국조특위 의결을 거쳐 투표지 검증을 해야 할 필요성이 있다고 설명했다. 국조특위는 이날 중앙선관위와 서울시선관위를 대상으로 2차 현장조사를 벌인 후 오는 14일과 22일 청문회를 거쳐 잠정적으로 결과보고서를 채택할 계획이다.', 'crawl', '세계일보', '2026-07-07 10:09:08', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707508023.jpg', '2026-07-07 06:04:40', '2026-07-07 18:17:14.713246', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3905, 'https://www.segye.com/Articles/RSSList/segye_politic.xml', NULL, 'https://www.segye.com/newsView/20260707502387', '정치', '선관위 국조특위, 오늘 중앙선관위·서울선관위 현장 조사', '국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 7일 중앙선거관리위원회와 서울시선거관리위원회를 직접 찾아 현장 조사에 나선다. 국조특위 위원장인 국민의힘 윤상현 의원을 비롯한 여야 특위 위원들은 이날 오전 경기 중앙선관위 과천청사를 살핀 뒤 오후에는 서울 종로구 서울선관위 사무소로 이동해 현장 조사를 이어갈 예정이다. 국조특위는 본투표 당일 중', '국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 7일 중앙선거관리위원회와 서울시선거관리위원회를 직접 찾아 현장 조사에 나선다. 국조특위 위원장인 국민의힘 윤상현 의원을 비롯한 여야 특위 위원들은 이날 오전 경기 중앙선관위 과천청사를 살핀 뒤 오후에는 서울 종로구 서울선관위 사무소로 이동해 현장 조사를 이어갈 예정이다. 윤상현 국조특위 위원장과 6·3 지방선거 투표용지 부족 사태를 조사 중인 국회 국정조사특별위원회 위원들이 지난 2일 서울 송파구 올림픽공원 내 개표소 입구에서 대기하고 있다. 국조특위는 본투표 당일 중앙선관위와 서울시선관위가 투표용지 부족을 최초 인지한 시점과 이후 보고·의사결정 체계 등을 검증한다는 방침이다. 또 중앙선관위 상황실의 보고체계 등 위기 대응 능력도 살펴볼 예정이다. 이 과정에서 윤 위원장이 제안한 올림픽공원 개표소 내 투표지에 대한 재검표 추진도 검토될 가능성이 있다. 앞서 특위는 지난 2일 송파구 선관위와 잠실 올림픽공원에 대한 현장 조사를 실시한 바 있다.', 'crawl', '세계일보', '2026-07-07 09:52:09', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707507430.jpg', '2026-07-07 06:04:40', '2026-07-07 18:17:26.917313', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3906, 'https://www.segye.com/Articles/RSSList/segye_politic.xml', NULL, 'https://www.segye.com/newsView/20260707506606', '정치', '김민석, ''계엄해제 표결 불참'' 공세에 "대장동 때 보는 듯"', '더불어민주당 당 대표 선거에 출마한 김민석 전 총리는 12·3 비상계엄 당시 자신이 국회의 계엄 해제 표결에 불참한 점을 두고 친청(친정청래)계가 공세를 펴는 데 대해 "무슨 꼭 대장동 때를 보는 것 같다"고 역공했다. 김 전 총리는 7일 KBS 라디오 인터뷰에서 해당 비판에 대해 "''국민의힘에서 누가 얘기를 하나''라고 생각했다"면서 이같이 말했다.', '''이병태 논란''에 "개헌, ''5·18·선관위'' 투포인트로 하자" 더불어민주당 당 대표 선거에 출마한 김민석 전 총리는 12·3 비상계엄 당시 자신이 국회의 계엄 해제 표결에 불참한 점을 두고 친청(친정청래)계가 공세를 펴는 데 대해 "무슨 꼭 대장동 때를 보는 것 같다"고 역공했다. 김 전 총리는 7일 KBS 라디오 인터뷰에서 해당 비판에 대해 "''국민의힘에서 누가 얘기를 하나''라고 생각했다"면서 이같이 말했다. 김민석 전 국무총리가 지난 6일 서울 여의도 국회 소통관에서 더불어민주당 당대표 출마 선언 기자회견을 하고 있다. 그의 이런 언급은 ''계엄 해제 표결 불참''에 대한 친청(친정청래)계의 공세를 과거 국민의힘 등이 대장동 사건으로 이재명 대통령을 비난하던 것에 빗댄 것이다. 앞서 김 전 총리는 2024년에 12·3 비상계엄 사태 이전부터 계엄 선포 가능성을 거론했으나 실제 계엄 사태가 발생했을 당시 국회의 계엄 해제 표결에는 불참했다. 그는 이후 당시 감기약을 먹고 잤다고 해명한 바 있다. 이를 두고 친청계 이성윤 의원은 전날 "감기약을 드시고 주무셨다고 하는데 약 성분이 무엇인가. 자는 사람은 깨울 수 있어도 자는 척하는 사람은 깨울 수 없다고 하던데 그런가"라고 공세를 폈다. 이에 김 전 총리는 이날 "그때 표결하는 시점에 국회 안에 있었고, 표결 직후에 본회의장에 착석했다"라고 말한 뒤 "이 의원이 말한 게 ''계엄과 관련한 전화를 받고 왜 거기(국회)에 오지 않았냐''(는 것)"이라며 "허위사실에 의한 명예훼손"이라고 주장했다. 김 전 총리는 캠페인 일환으로 진행하는 ''유튜브 백문백답''에 대해선 "저에 대해 무엇이든 물어보시라는 차원"이라고 소개했다. 그러면서 "당의 내부 문화가 조금 이상해져서 멸칭, 갈라치기도 있고 전혀 (사실이) 아닌 가짜뉴스도 돌아다닌다"며 "그런 것들을 정리하면 좋겠다(는 취지)"라고 했다. 자신이 당의 혁신을 강조한 배경에 대해선 "검찰개혁이 중요하지만, 민주당은 그것 외에는 어젠다가 없느냐는 느낌이 들게 해선 안된다"며 "(정부를) 착착 뒷받침하는 느낌을 주는 1년은 아니지 않았는가"라고 반문했다. 그는 ''5·18은 성역이 아니다''라는 발언으로 논란을 빚은 뒤 사퇴한 이병태 전 규제합리화위원회 부위원장에 대해선 "사퇴는 불가피했다"며 "이번 기회에 5·18 헌법 전문 수록과 선거관리위원회 문제에 관한 투포인트 개헌을 하자"고 제안했다. 이어 이재명 정부의 ''통합 인사'' 기조에 대해선 "사람을 더 넓게 쓰잔 방향 자체는 버릴 수 없다"며 더욱 엄격한 검증 필요성을 강조했다.', 'crawl', '세계일보', '2026-07-07 09:48:40', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707507208.jpg', '2026-07-07 06:04:40', '2026-07-07 18:17:38.229438', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3907, 'https://www.segye.com/Articles/RSSList/segye_politic.xml', NULL, 'https://www.segye.com/newsView/20260707505731', '정치', '李대통령, 튀르키예로 출발…유럽 방산외교 스타트', '이재명 대통령이 7일 서울공항을 통해 북대서양조약기구(NATO·나토) 정상회의가 열리는 튀르키예 앙카라를 향해 출국했다. 정부에서는 윤호중 행정안전부 장관이, 더불어민주당에서는 한병도 대표 직무대행 겸 원내대표가, 청와대에서는 강훈식 대통령 비서실장과 홍익표 정무수석이 이 대통령의 출국길을 배웅했다. 이 대통령은 출국에 앞서 엑스(X·옛 트위터)를 통', '이재명 대통령이 7일 서울공항을 통해 북대서양조약기구(NATO·나토) 정상회의가 열리는 튀르키예 앙카라를 향해 출국했다. 정부에서는 윤호중 행정안전부 장관이, 더불어민주당에서는 한병도 대표 직무대행 겸 원내대표가, 청와대에서는 강훈식 대통령 비서실장과 홍익표 정무수석이 이 대통령의 출국길을 배웅했다. 이 대통령은 출국에 앞서 엑스(X·옛 트위터)를 통해 "지난달 주요 7개국(G7) 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 넓혀 가려 한다"고 밝혔다. 마르크 뤼터 나토 사무총장이 최근 한국의 방위산업 기반을 ''환상적''이라고 평가했다는 사실을 거론하면서 "전쟁의 폐허를 딛고 나라를 지키기 위해 흘린 수많은 땀방울이 오늘날 세계가 인정하는 경쟁력이 됐다는 것이 참으로 자랑스럽다"고 언급하기도 했다. 그러면서 "오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계 평화와 안보에 책임 있게 기여하는 나라가 됐다"며 "국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다"고 다짐했다. 이번 일정은 뤼터 사무총장의 초청으로 성사된 것으로, 취임 후 첫 나토 정상회의 참석이기도 하다. 우선 이 대통령은 이날 오후 앙카라에 도착, 뤼터 사무총장과 함께 일본, 호주, 뉴질랜드 등 인도·태평양 파트너국, 이른바 IP4 국가 대표들과의 소인수회담에 참석한다. 이후 이 대통령은 정상회의 공식 행사 중 하나인 나토 방위산업포럼에 참석, ''공동의 가치, 더욱 강한 산업기반''을 주제로 한 세션에서 기조발언을 한다. 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 참석한다. 이번 참석은 지난달 주요 7개국(G7) 정상회의에 이어 한국 외교의 지평을 더욱 넓히는 동시에, 특히 세계 국방비의 55%를 차지하는 최대 방산시장인 나토 동맹국들을 상대로 방산협력을 본격 추진한다는 의미가 있다고 청와대는 설명했다. 특히 도널드 트럼프 미국 대통령 역시 나토 정상회의 참석을 위해 튀르키예를 방문할 예정인 만큼, 이 대통령과 현지에서 대면할 것인지에도 관심이 쏠리고 있다. 이 대통령은 8일까지 튀르키예에 머무른 뒤 9일부터는 몽골에서 국빈방문 일정을 소화한다.', 'crawl', '세계일보', '2026-07-07 09:41:27', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707507153.jpg', '2026-07-07 06:04:40', '2026-07-07 18:17:45.054699', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3910, 'https://www.segye.com/Articles/RSSList/segye_economy.xml', NULL, 'https://www.segye.com/newsView/20260707513813', '경제', '연일 ''팔자'' 외국인 삼전 보유율, 금융위기 이후 최저…개미 빚투↑', '최근 외국인의 반도체주 매도세가 이어진 가운데 외국인의 삼성전자 주식 보유율이 글로벌 금융위기 이후 약 17년 만에 최저를 기록했다. 반면 개인의 반도체주에 대한 ''빚투(빚내서 투자)'' 열기는 오히려 뜨거워지면서 신용잔고 금액은 이달 들어 사상 최대 수준으로 늘었다. 7일 한국거래소에 따르면 전날(6일) 기준 외국인의 삼성전자 주식 보유율은 46.69', '외국인 13일째 삼전·닉스 ''팔자''…SK하이닉스 신용잔고 역대 최대 전문가들 "하반기 메모리 가격 강세 지속"…하이닉스 ADR 상장 주목 최근 외국인의 반도체주 매도세가 이어진 가운데 외국인의 삼성전자 주식 보유율이 글로벌 금융위기 이후 약 17년 만에 최저를 기록했다. 반면 개인의 반도체주에 대한 ''빚투(빚내서 투자)'' 열기는 오히려 뜨거워지면서 신용잔고 금액은 이달 들어 사상 최대 수준으로 늘었다. 7일 서울시 서초구 삼성전자 서초사옥 지하에서 직원 등이 오가고 있다. 7일 한국거래소에 따르면 전날(6일) 기준 외국인의 삼성전자 주식 보유율은 46.69%로 집계됐다. 이는 글로벌 금융위기 여파로 투자심리가 위축됐던 지난 2009년 7월 23일(46.67%) 이후 약 17년 만에 가장 낮은 수준이다. 외국인의 삼성전자 보유율은 지난해 말 52.33%에 달했으나, 미국과 이란 간 전쟁 발발 이후인 지난 3월 4일 50%선을 내준 뒤 같은 달 26일에는 49%대 아래로 밀려났다. 이후 상승 전환해 5월 6일 49.6%까지 회복했으나 다시 하락세로 돌아서 지난달 4일 48% 아래로 떨어졌고, 지난달 말 47%선마저 내준 뒤 현재까지 지속해 하강 곡선을 그리고 있다. SK하이닉스 보유율도 하락세다. 전날 기준 외국인의 SK하이닉스 보유율은 50.17%로, 2023년 5월 19일(50.10%) 이후 3년 2개월 만에 최저를 기록했다. 외국인이 삼성전자와 SK하이닉스에 대한 순매도세를 장기간 이어간 영향으로 풀이된다. 외국인은 지난달 19일 이후 이날까지 삼성전자와 SK하이닉스를 13거래일 연속 순매도 중이다. 지난달 19일 이후 전날까지 외국인의 삼성전자[005930] 순매도액은 13조2천650억원, SK하이닉스는 19조5천820억원으로 순매도 규모는 SK하이닉스가 더 컸다. 7일 서울 중구 하나은행 딜링룸 전광판에 삼성전자 주가가 표시되고 있다. 반면 같은 기간 개인 투자자들은 이들 종목에 대한 ''빚투''를 늘리며 대거 쓸어 담고 있다. 연합인포맥스에 따르면 전날(6일) 기준 삼성전자의 신용잔고 금액은 5조5천75억원으로 한 달 전 대비 1조2천465억원 늘었다. 지난달 24일 사상 처음 5조원을 돌파한 뒤 이달 1일에는 5조5천304억원까지 늘며 사상 최대치를 기록하기도 했다. 전날 SK하이닉스 신용잔고도 5조3천49억원으로 역대 최대를 기록했다. 한 달 전 대비로는 1조5천866억원 늘었다. 신용거래융자 잔고는 투자자가 주식 투자를 위해 증권사로부터 자금을 빌린 뒤 변제를 마치지 않은 금액으로, 이 잔고가 늘었다는 것은 레버리지(차입) 투자가 증가했다는 의미다. 삼성전자가 이날 2분기 잠정 실적을 공개한 가운데 외국인의 복귀 시점에 투자자들의 관심이 쏠리고 있다. 이날 개장 전 삼성전자는 연결 기준 올해 2분기 영업이익이 89조4천억원으로 지난해 동기보다 1천810.3% 증가한 것으로 잠정 집계됐다고 공시했다. 이번 영업이익은 연합인포맥스가 집계한 시장 전망치 84조1천606억원을 6.2% 상회했다. 매출은 171조원으로 작년 동기 대비 129.3% 증가했다. 이같은 호실적에도 현재 삼성전자 주가는 9.28% 급락해 ''30만전자''를 내준 상태다. 기대감이 선반영된 가운데 이벤트 소멸 심리에 따른 차익 매물이 출회된 영향이다. 다만 증권가에서는 향후 호실적 지속과 주주환원 증가 등이 기대되는 만큼 최근 조정을 저가 매수 기회로 삼아야 한다는 제언이 나온다. 경기도 이천시 SK하이닉스 본사 모습. 연합뉴스 손인준 유진투자증권 연구원은 "하반기 메모리 가격 강세가 지속될 것이고, 메모리 업체 간 주주환원 경쟁이 본격화할 것"이라며 "이러한 대규모 주주환원은 최근 상대적으로 부진했던 삼성전자 주가의 아웃퍼폼을 이끌 것"이라고 내다봤다. 이어 "메모리 업종의 주가가 최근 큰 폭의 하락세를 보였으나 여전히 강세장 속 나타나는 조정에 불과하다"며 삼성전자에 대한 투자의견을 ''강력 매수(Strong Buy)''로 유지했다. 일각에서는 오는 10일 SK하이닉스[000660]의 미국주식예탁증서(ADR) 상장을 계기로 국내 반도체주에 대한 외국인의 매기가 다시 살아날 수 있다는 기대감도 번지고 있다. 한지영 키움증권 연구원은 "10일 미국 증시에서 SK하이닉스가 상장할 때 흥행 여부가 관건"이라며 "그 결과에 따라 미국 증시에서 삼성전자, SK하이닉스 대비 높은 밸류에이션(평가가치) 프리미엄을 받고 있는 마이크론과의 PER(주가수익비율) 격차를 줄일 수 있는 내러티브가 형성될 수 있기 때문"이라고 설명했다.', 'crawl', '세계일보', '2026-07-07 14:12:45', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707514235.jpg', '2026-07-07 06:04:40', '2026-07-07 18:18:09.692155', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3911, 'https://www.segye.com/Articles/RSSList/segye_economy.xml', NULL, 'https://www.segye.com/newsView/20260707512159', '경제', 'SK하이닉스, 나스닥 상장에 큰손 몰린다…오픈AI 출신 펀드도 ''베팅''', 'SK하이닉스의 280억 달러(약 42조6700억원) 규모 나스닥 상장에 전직 오픈AI 연구원이 설립한 헤지펀드와 영국 투자사 베일리 기포드가 대규모 투자 의사를 밝혔다. 6일(현지 시간) 파이낸셜타임스(FT)에 따르면 SK하이닉스는 이번 주 나스닥 기업공개(IPO) 절차를 공식 개시했다. AI 데이터센터 건설 붐으로 메모리 반도체 수요가 급증하면서 이번', 'SK하이닉스의 280억 달러(약 42조6700억원) 규모 나스닥 상장에 전직 오픈AI 연구원이 설립한 헤지펀드와 영국 투자사 베일리 기포드가 대규모 투자 의사를 밝혔다. 6일(현지 시간) 파이낸셜타임스(FT)에 따르면 SK하이닉스는 이번 주 나스닥 기업공개(IPO) 절차를 공식 개시했다. AI 데이터센터 건설 붐으로 메모리 반도체 수요가 급증하면서 이번 상장은 아시아 기업의 뉴욕 증시 상장 가운데 역대 최대 규모 중 하나가 될 전망이다. AI 수요에 힘입어 SK하이닉스의 지난해 매출은 전년 대비 47% 증가한 97조1000억원, 영업이익은 두 배 이상 늘어난 42조9000억원을 기록했다. 올해 1분기 매출도 전년 동기 대비 약 3배 증가한 52조6000억원으로 집계됐다. 이 같은 실적에 힘입어 SK하이닉스 주가는 지난 1년간 코스피에서 750% 이상 상승했고, 시가총액은 1663조원 수준으로 불어났다. 오픈AI 출신 연구원 레오폴드 아셴브레너가 설립한 헤지펀드 시추에이셔널 어웨어니스와 베일리 기포드, 코튜는 SK하이닉스가 발행하는 미국주식예탁증서(ADS) 가운데 최대 70억 달러어치(약 10조6600억원)를 인수할 의향을 내비쳤다. 시추에이셔널 어웨어니스 AI 관련 종목에 대한 선제적 투자로 개인 투자자들 사이에서 큰 관심을 받아왔다. SK하이닉스는 이번 상장을 통해 조달한 280억 달러를 생산능력 확대에 투입할 계획이다. 자금 대부분은 국내 반도체 공장(팹) 신설에 쓰이며, 일부는 네덜란드 ASML이 만드는 최첨단 노광장비 EUV 스캐너 구매에도 사용된다. 앞서 지난주 SK하이닉스와 삼성전자는 국내 생산능력을 대폭 늘리기 위해 6000억 달러(약 914조원) 규모의 투자 계획을 발표했다. AI 데이터센터용 고대역폭메모리(HBM) 수요 급증으로 촉발된 메모리 반도체 공급 부족은 SK하이닉스, 삼성전자, 마이크론 등 3대 메모리 업체의 주가를 끌어올렸고, 이들 기업은 모두 시가총액 1조 달러를 넘어섰다. SK하이닉스는 전체 발행주식의 약 2.5%에 해당하는 신주 1779만 주를 ADS 형태로 나스닥에 상장할 계획이다. 이번 공모 규모는 최대주주인 SK스퀘어의 지분율이 20% 이상 유지되도록 설계됐다. ADS 공모가는 7월 3일 기준 코스피 종가를 반영해 주당 약 158달러(약 24만원) 수준에서 결정될 예정이며, 뱅크오브아메리카·JP모건·골드만삭스·씨티그룹이 대표 주관사를 맡는다. 미국 시장에서는 10일부터 거래가 시작될 예정이다.', 'crawl', '세계일보', '2026-07-07 14:04:39', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707512162.jpg', '2026-07-07 06:04:40', '2026-07-07 18:18:18.599778', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3912, 'https://www.segye.com/Articles/RSSList/segye_economy.xml', NULL, 'https://www.segye.com/newsView/20260707513707', '경제', '2분기 전망치 웃돈 실적에도 삼전 폭락…증권가 평가는', '코스피 대장주 삼성전자[005930]가 2분기 전망치를 웃도는 실적을 냈음에도 7일 주가가 급락하자 증권가는 신중한 평가를 내놓고 있다. 시장 전망치를 웃돌며 반도체 호황을 재확인했지만, 일각에선 비반도체 부문 수익 부진에 대한 우려가 함께 나오면서다. 다만 장기적으로 주가 우상향 흐름 자체가 이어질 것이란 의견은 일치했다. 이병건 DB증권 리서', '서프라이즈, 안도" 평가속 신중…"비메모리 부진 우려" 단 실적 개선은 지속 전망…"중장기적으로는 우상향" 코스피 대장주 삼성전자[005930]가 2분기 전망치를 웃도는 실적을 냈음에도 7일 주가가 급락하자 증권가는 신중한 평가를 내놓고 있다. 시장 전망치를 웃돌며 반도체 호황을 재확인했지만, 일각에선 비반도체 부문 수익 부진에 대한 우려가 함께 나오면서다. 삼성전자가 2분기 잠정 영업이익으로 89조4천억원을 기록, 성과급 충당금 제외시 106조원 이상을 벌어들였다. 단 1개 분기 만에 지난 3년간 합산 영업이익을 한꺼번에 벌어들인 것이다. 7일 업계에 따르면, 이날 삼성전자가 발표한 올해 2분기 잠정 영업이익(89조4천억원)은 성과급 지급을 위한 충당금 약 17조원이 제외된 수치다. 다만 장기적으로 주가 우상향 흐름 자체가 이어질 것이란 의견은 일치했다. 이병건 DB증권 리서치센터장은 이날 공개된 삼성전자 2분기 실적 잠정치에 대해 "성과급 충당금을 제외한 영업이익 기준으로도 실적은 개선됐지만, 비(非)메모리와 세트(디바이스경험·DX) 부문 수익성은 부진한 것으로 보인다"고 평가했다. 삼성전자는 이날 오전 2분기 잠정 영업이익은 89조4천억원, 매출액은 171조원을 기록했다고 밝혔다. 각각 전년 대비 1천810%, 129% 증가한 것으로, 둘 다 3분기 연속 역대 최대 기록을 경신했다. 성과급 지급을 위한 충당금 추정치(17조원)를 더하면 영업이익은 100조원을 넘는다는 관측이 나온다. 단 부문별 영업이익이 상세히 공개되지 않은 가운데, 전망치 상회 폭이 상대적으로 작다는 평가와 맞물리며 DX나 모바일(MX), 생활가전 등 사업 부문의 부진 관측이 제기된 것이다. 김두언 하나증권 연구원은 이날 실적에 대해 "실망스러웠다. 시장 전망치는 그간 70조원에서 100조원 사이 움직이다가 오늘 자로 84조원이 된 것인데, 이날 발표치는 전망대로 나온 수준"이라고 평가했다. 이어 "그렇다 보니 DX나 파운드리 부문 적자가 여전히 이어졌을 것이라는 분석이 나오는 것"이라고 설명했다. 한지영 키움증권 연구원은 "실적이 시장 전망치를 상회하는 ''서프라이즈''(호실적)를 기록해 개인적으로는 다행, 안도 요인으로 판단하고 있다"면서도 "(시장은)이번 실적을 ''셀온''(매도) 이벤트로 접근하는 시각이 단기적으로 우세한 것으로 보인다"고 말했다. 다만 메리츠증권과 대신증권 등 일부 증권사에선 "호실적", "업계 최대 체급의 힘을 보여준 것"이라는 호평도 나왔다. 이날 오후 삼성전자는 9% 이상 내리고 있다. 전문가들은 이번 실적 발표로 당장 분위기가 전환되진 않더라도, 장기적으로 보면 주가 우상향 흐름은 계속될 것으로 봤다. 류형근 대신증권 연구원은 "내년 고대역폭메모리(HBM) ASP(평균판매단가)는 전년 대비 91% 상승할 것으로 전망된다. 절대 우위를 기반으로 수익성 격차를 축소해갈 것"이라며 "임직원 성과급 보상 목적의 자사주 매입이 재개되면 주가 하방 강직성을 높일 변화가 될 것"이라고 분석했다. 또 비메모리 부문에 대해선 "성과급 충당금을 제외하면 연내 흑자전환이 가능한 구조"라며 "성과급 정책 변화로 분기 흑자전환 시점은 밀렸으나, 우호적 수주 환경이 펼쳐지는 만큼 서프라이즈를 기대한다"고 덧붙였다. 김선우 메리츠증권 연구원은 "비록 DX 부문적자 기여 발생으로 일부 투자자들의 막연한 눈높이에 미달 요인으로 작용했지만, 이는 메모리 중장기 개선 과정의 일부로 해석돼야 한다"고 강조했다. 그는 "삼성전자는 D램 및 낸드 가격에서의 리더십을 계속 발생시키고 있다"며 "현재 사이클은 메모리 공급이 최소 내년 4분기까지 수요 증가 속도를 따라잡기에 턱없이 부족한 상황이 지속될 것"이라고 봤다. 이병건 센터장은 "단기적으로는 ''호재 소멸''에 따른 차익 실현과 종목별 차별화가 나타날 가능성이 있다. 하지만 장기적으로는 AI 투자 확대와 메모리 업황 개선이 이어질 경우 반도체 업종의 실적 개선도 지속될 가능성이 높다"며 "코스피에도 긍정적인 영향을 줄 것"이라고 설명했다. 또 다른 증권사 연구원도 "비메모리 사업 부문이 잠식되는 것 아니냐는 우려도 시장에서 나왔을 것으로 보이지만, 지난 1분기 실적 발표 때도 당일은 주가가 크게 안 올랐다가 이후에 차츰 오르는 모습을 보이기도 했다"고 말했다. 오는 30일 나오는 세부 실적 및 확정치와 함께 미국 빅테크의 설비투자 계획 등을 지켜봐야 할 것이란 의견도 나온다. 김두언 연구원은 "부문별 실적 확정치가 중요해 보인다. 부문별 기여도를 확인해야 제대로 평가할 수 있을 것"이라고 말했다. 아울러 "이달 말 구글의 실적 발표 후 컨퍼런스콜에서 AI 설비투자는 계속하겠다는 의지가 드러나면 지금의 과한 낙폭은 되돌려질 것"이라고 전망했다.', 'crawl', '세계일보', '2026-07-07 14:01:16', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707513803.jpg', '2026-07-07 06:04:40', '2026-07-07 18:18:32.812154', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3922, 'https://www.segye.com/Articles/RSSList/segye_economy.xml', NULL, 'https://www.segye.com/newsView/20260707510184', '경제', '남편 친구에게 명의 허위 이전, 1세대1주택 혜택 받아 세금 탈루…731억원 규모 부동산 탈루 적발', '광역시 소재 아파트와 단독주택을 한 채씩 보유한 A씨는 양도차익이 큰 단독주택을 팔기 전 아파트를 남편 친구 B씨에게 이전했다. 이후 A씨는 단독주택을 15억원에 양도하면서 1세대1주택 비과세 혜택을 받았다. 그런데 국세청이 자금 흐름을 확인해보니 A씨는 B씨가 아파트를 실제 취득한 것처럼 꾸미기 위해 거래에 필요한 매매대금 등을 친구·회사동료를 통해 몰래', '광역시 소재 아파트와 단독주택을 한 채씩 보유한 A씨는 양도차익이 큰 단독주택을 팔기 전 아파트를 남편 친구 B씨에게 이전했다. 이후 A씨는 단독주택을 15억원에 양도하면서 1세대1주택 비과세 혜택을 받았다. 그런데 국세청이 자금 흐름을 확인해보니 A씨는 B씨가 아파트를 실제 취득한 것처럼 꾸미기 위해 거래에 필요한 매매대금 등을 친구·회사동료를 통해 몰래 전달, 금융증빙을 조작한 것으로 나타났다. A씨가 단독주택 양도시점에 1세대1주택자인 것처럼 세정당국을 속여 비과세를 적용받은 셈이다. 국세청은 이에 A씨에게 6억원의 양도세를 추징하는 한편 A씨는 물론 탈세에 협조한 B씨도 조세포탈 혐의로 검찰에 고발했다. 서울 남산에서 바라본 아파트 단지 모습. 국세청은 지난해 10월부터 부동산 탈세 혐의자 104명에 대해 조사를 착수한 결과, 318억원의 세금을 추징했다고 7일 밝혔다. 이들의 탈루 규모는 731억원에 달했다. 이들 중에는 A씨처럼 다주택자가 저가주택을 명의만 허위 이전해 1세대1주택 비과세를 부당하게 적용(가장매매)받거나, 부모로부터 고가 아파트를 취득하며 증여세를 탈루한 사례 등이 포함됐다. 국세청은 부정한 방법으로 조세를 포탈한 사실이 확인된 건은 40%에 상당하는 부당 과소신고 가산세를 부과하는 한편 6명은 조세범처벌법에 따라 검찰에 고발했다. 2주택자인 C씨 사례 역시 A씨와 비슷했다. C씨는 양도차익이 큰 서울 소재 고가아파트를 양도하기 전에 본인이 거주하는 저가아파트를 모친의 지인에게 이전했다. C씨는 고가아파트를 20억원에 양도하면서 1세대1주택자로 비과세를 적용, 양도세를 신고했다. 조사결과 C씨는 모친의 지인에게 취득세·재산세를 대납해주고, 양도 후에도 저가아파트에 계속 거주했다. 그러면서 탈세에 협조한 대가로 모친의 지인에게 매월 수십만원의 사례금을 지원했다. C씨 모친은 허위계약서 작성 등 가장매매를 주도했다. 국세청은 C씨에게 10억원의 양도세를 추징하는 한편 C씨와 거래 과정을 주도한 모친, 모친의 지인을 검찰에 고발조치했다. 부동산 취득 자금원천을 확인하는 과정에서 사업소득 누락 및 법인자금 유출된 사실이 드러난 경우도 있었다. 50대 D씨는 40억원 규모 서울 강남 소재 재건축 예정 아파트를 비롯해 상가, 토지 등 다수의 부동산을 취득했는데, 신고소득 등에 비해 부동산이 과다해 조사대상에 올랐다. 자금출처를 조사한 결과, D씨 배우자가 운영하는 축산물 도매업체 자금이 사용된 것으로 확인됐다. 이에 국세청이 법인을 추가 조사해보니 거래처에 무자료 매출을 통해 조성한 비자금 약 30억원을 D씨 배우자가 별도 관리하다가 D씨에게 몰래 증여한 사실이 드러났다. 국세청은 축산물 도매업체의 매출누락에 대한 법인세, D씨 부동산 취득자금 증여세 등 31억원을 추징했다. 부모로부터 몰래 증여받은 자금으로 고가 아파트를 취득하며 세금을 탈루한 사례도 확인됐다. 40대 E씨는 소득이 전혀 없음에도 매월 700만원 이상의 고액 월세를 지급하면서 서울 강남 한강변 소재 고가아파트에 거주했다. 또 수십억원 규모의 주식을 취득하고 매년 수억원에 달하는 생활비를 지출하는 등 호화·사치 생활을 누렸다. 조사결과 E씨는 임대사업자인 부모로부터 월세, 주식 투자자금, 생활비를 포함한 총 20억여원의 자금을 증여받은 것으로 나타났다. 국세청은 E씨가 부모로부터 증여받은 자금에 대해 증여세 13억원을 추징했다. 국세청은 부동산 취득·보유·양도 등 거래 전 과정에서 발생하는 탈세 위험요인을 조기에 포착하고, 탈세행위가 확인될 경우 세무조사를 실시하는 등 강력 대응해 나갈 방침이라고 밝혔다. 국세청 오상훈 자산과세국장은 “다주택자 중과 재개 후 증여거래가 늘어날 우려가 있는 만큼 다주택자 증여거래를 중심으로 증여재산을 저가평가하거나 증여세를 대납하는 등 편법 증여가 없는지 검증할 예정”이라면서 “부모가 보유한 아파트를 시세보다 현저히 낮은 가격으로 자녀에게 양도하거나 매매 형식을 위장해 사실상 증여하는 경우 등 세금 회피 목적의 가족 간 편법 거래도 꼼꼼히 살펴볼 것”이라고 강조했다.', 'crawl', '세계일보', '2026-07-07 12:02:00', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707510347.jpg', '2026-07-07 06:04:40', '2026-07-07 18:20:40.640481', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3930, 'https://www.segye.com/Articles/RSSList/segye_society.xml', NULL, 'https://www.segye.com/newsView/20260707514267', '사회', '“8일 밤 충남·전북 시간당 최대 50㎜ 이상 비…호우피해 유의” [날씨]', '수요일인 8일은 전국 대부분에 비가 내리겠다. 특히 8일 밤부터 다음날 오전 충남·전북 중심으로 매우 강한 비가 예상돼 호우 피해에 유의해야겠다. 7일 기상청에 따르면 8일부터 금요일인 10일 오전까지 우리나라 상공의 정체전선이 남북으로 진동하면서 중부·전라 지역 중심으로 강하고 많은 비가 내릴 전망이다. 이 기간 충남과 전북의 경우 예상 강수량이', '수요일인 8일은 전국 대부분에 비가 내리겠다. 특히 8일 밤부터 다음날 오전 충남·전북 중심으로 매우 강한 비가 예상돼 호우 피해에 유의해야겠다. 7일 기상청에 따르면 8일부터 금요일인 10일 오전까지 우리나라 상공의 정체전선이 남북으로 진동하면서 중부·전라 지역 중심으로 강하고 많은 비가 내릴 전망이다. 충북 영동군이 7일 오전 영동읍 영동천 하상주차장 출입을 막고 있으나 노숙 차량 20여 대가 남아 있어 완벽히 통제하지 못하고 있다. 기상청은 이날 오전 8시20분을 기해 영동지역에 대한 호우주의보를 호우경보로 격상했다. 이 기간 충남과 전북의 경우 예상 강수량이 최대 200㎜ 이상, 경기남부, 강원중·남부내륙, 충북은 최대 150㎜ 이상이다. 취약 시간대인 8일 밤부터 9일 오전 사이에는 시간당 최대 50㎜ 이상의 매우 강한 비가 예상된다. 당분간 전국 내륙 중심으로 낮 최고기온이 30도 이상으로, 최고 체감온도도 31도 안팎을 오가는 등 더위가 계속되겠다. 8일 예상 낮 최고기온은 26∼34도다. 남북 진동을 하던 정체전선이 물러나면 토요일인 11일쯤엔 남부내륙 중심 폭염 특보가 전국으로 확대할 것으로 전망된다. 제9호 태풍 바비는 11일쯤 대만 북쪽 해상을 지나 중국 동안에 상륙할 것으로 예상된다. 이번 강수에 태풍 바비의 직접 영향은 없지만 상륙 후 동아시아 기압계 재배치로 다음 주 강수 확대 가능성이 있다.', 'crawl', '세계일보', '2026-07-07 14:26:00', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707514563.jpg', '2026-07-07 06:04:40', '2026-07-07 18:21:40.784337', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3934, 'https://www.segye.com/Articles/RSSList/segye_society.xml', NULL, 'https://www.segye.com/newsView/20260707513627', '사회', '‘음료 피습 자작극 의혹’ 정이한 구속영장 청구', '6·3 지방선거 당시 발생한 ‘음료수 피습 자작극 의혹’으로 경찰 수사를 받아온 정이한 전 개혁신당 부산시장 후보와 정 후보에게 음료수를 던진 30대 헬스트레이너 A씨에 대해 구속영장이 청구됐다. 부산 금정경찰서는 지난 1일 위계에 의한 공무집행방해와 공직선거법 위반 등의 혐의로 정 전 후보와 A씨에 대해 구속영장을 신청했다고 7일 밝혔다. 검찰은 증거', '6·3 지방선거 당시 발생한 ‘음료수 피습 자작극 의혹’으로 경찰 수사를 받아온 정이한 전 개혁신당 부산시장 후보와 정 후보에게 음료수를 던진 30대 헬스트레이너 A씨에 대해 구속영장이 청구됐다. 6·3 지방선거에서 부산시장에 출마한 당시 개혁신당 정이한 후보가 지난 2026년 4월 27일 부산 금정구 구서나들목 인근에서 지나가는 차량 운전자로부터 ‘음료 투척 테러’를 당하는 모습과 이후 병원에서 진료받는 모습. 부산 금정경찰서는 지난 1일 위계에 의한 공무집행방해와 공직선거법 위반 등의 혐의로 정 전 후보와 A씨에 대해 구속영장을 신청했다고 7일 밝혔다. 검찰은 증거인멸 및 도주 우려가 있다고 보고, 경찰이 신청한 구속영장을 이틀 뒤 부산지법에 청구했다. 이들에 대한 구속 전 피의자 심문(영장실질심사)은 8일 오후 2시 부산지법에서 열릴 예정이다. 정 전 후보는 지난 4월27일 부산 금정구 구서나들목 인근에서 유세 도중 한 차량 운전자가 던진 음료에 맞았다고 주장했다. 당시 그는 이를 피하는 과정에서 넘어져 의식불명 상태로 병원에 이송됐고, 곧바로 뇌진탕 진단을 받았다고 전해졌다. 그러나 음료를 던진 A씨가 정 전 후보와 평소 ‘알고 지내던 사이’였다는 사실이 알려지면서 자작극 의혹이 제기됐다. 경찰 수사 과정에서 두 사람이 사건 발생 전 통화한 기록이 확인됐고, 원래부터 친분이 있었던 사이로 파악됐다. 정 전 후보는 자작극 의혹이 불거지자 사회관계망서비스(SNS)를 통해 정계 은퇴 의사를 밝히고, 온라인으로 탈당한 뒤 두문불출했다.', 'crawl', '세계일보', '2026-07-07 13:58:06', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707513685.jpg', '2026-07-07 06:04:40', '2026-07-07 18:22:11.398196', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3943, 'https://www.segye.com/Articles/RSSList/segye_society.xml', NULL, 'https://www.segye.com/newsView/20260707511265', '사회', '정체전선 남북 진동하며…내일부터 장맛비 쏟아진다', '8일부터 전국에 많은 비가 거세게 내리겠다. 7일 기상청에 따르면 8일 새벽에서 오후까지 서해상에 새로 형성된 정체전선이 북태평양고기압 확장에 따라 북상하면서 중부지방과 호남을 중심으로 장맛비가 내리겠다. 새 정체전선은 우리나라 북쪽에 형성된 절리저기압에서 부는 차고 건조한 공기와 남쪽 북태평양고기압 가장자리에서 부는 고온다습한 공기가 충돌하면서 형성', '8일부터 전국에 많고 강한 비…충남·전북 이틀간 최고 200㎜ 이상 8일과 9일 사이 밤에 충남·전북에 시간당 50㎜ 이상 집중호우 고온다습한 공기 지속해서 유입…주말 폭염 전국 확대 8일부터 전국에 많은 비가 거세게 내리겠다. 7일 기상청에 따르면 8일 새벽에서 오후까지 서해상에 새로 형성된 정체전선이 북태평양고기압 확장에 따라 북상하면서 중부지방과 호남을 중심으로 장맛비가 내리겠다. 7일 서울 종로구 광화문광장 인근에서 시민들이 우산을 쓰고 이동하고 있다. 새 정체전선은 우리나라 북쪽에 형성된 절리저기압에서 부는 차고 건조한 공기와 남쪽 북태평양고기압 가장자리에서 부는 고온다습한 공기가 충돌하면서 형성되겠다. 절리저기압은 대기 상층에 부는 빠른 바람인 제트기류가 구불구불하게 흐르다가 일부가 떨어져 나와서 형성된 저기압이다. 8일 저녁부터 9일 새벽까지는 정체전선이 찬 공기에 밀려 남하하겠다. 전선은 9일 오전부터 다시 북상, 10일 낮 북한 쪽으로 넘어가겠다. 이처럼 정체전선이 남북으로 진동하면서 중부지방과 호남에 많은 비가 매우 거세게 내릴 것으로 예상된다. 특히 8일 늦은 밤부터 9일 오전 사이 충남과 전북을 중심으로는 1시간에 50㎜ 이상씩 비가 쏟아질 것으로 보인다. 기상청에 따르면 8일 새벽에서 오후까지는 기압골 전면과 북태평양고기압이 만나면서 비구름대가 한곳에 머물기보다는 지속해서 이동하는 모습을 보이겠다. 그러나 8일 저녁에서 10일 오전까지는 기압골 뒤편에서 부는 차고 건조한 북서풍과 북태평양고기압 가장자리를 타고 부는 고온다습한 남서풍이 강하게 충돌, 비구름대가 띠 모양으로 압축되고 정체하겠다. 더욱이 8일에서 9일로 넘어가는 밤 대기 하층으로 수증기를 다량 머금은 빠른 바람인 하층제트까지 불겠다. 그러면서 비구름대가 머무는 곳을 중심으로 집중호우가 내리겠다. 8∼9일 예상 강수량은 대전·세종·충남·전북 80∼150㎜(최고 200㎜ 이상), 수도권·서해5도·강원내륙·강원산지·충북 50∼100㎜(경기남부·강원중부내륙·강원남부내륙·충북 최고 150㎜ 이상), 전남북서부·경북중부·경북북부 30∼80㎜(경북중·북부 최고 120㎜ 이상, 전남북서부 최고 100㎜ 이상), 대구·경북남부 20∼60㎜, 강원동해안 5∼50㎜, 광주·전남(북서부 제외) 10∼40㎜, 경남서부내륙 5∼40㎜, 제주 5㎜ 안팎이다. 10일 강수량을 고려하면, 총강수량은 더 많을 것으로 보인다. 많은 비가 예고된 만큼 비 피해 없게 대비해야 한다. 정체전선이 북한 쪽으로 넘어간 뒤인 11일에는 북태평양고기압이 우리나라를 덮으면서 매우 무덥겠다. 현재 남부지방 내륙지역을 중심으로 폭염주의보가 내려져 있는데, 11일께 전국으로 확대 발령되겠다. 북태평양고기압 가장자리를 타고 고온다습한 공기가 지속해서 유입되는 상황이라 남부지방을 중심으로 열대야가 나타나는 곳이 있겠다. 열대야는 밤(오후 6시 1분부터 이튿날 오전 9시까지) 기온이 25도 밑으로 떨어지지 않는 현상이다. 제주와 남부지방을 중심으로 첫 열대야주의보가 발령될 수 있다. 열대야주의보는 최고 체감온도가 33도 이상인 상황이 이틀 이상 이어질 것으로 예상되는 지역의 밤 최저기온이 25도(대도시·해안·섬은 26도, 제주는 27도) 이상일 것으로 예상되면 내려진다.', 'crawl', '세계일보', '2026-07-07 11:59:49', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707511446.jpg', '2026-07-07 06:04:40', '2026-07-07 18:23:20.98713', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3954, 'https://www.segye.com/Articles/RSSList/segye_international.xml', NULL, 'https://www.segye.com/newsView/20260707505718', '국제', '베네수 지진 사망자 3535명…"어린이 구조 보도는 오보"', '지난달 24일(현지시간) 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3천535명으로 늘었다고 호르헤 로드리게스 국회의장이 6일 밝혔다. 이는 전날보다 193명 늘어난 수치다. 부상자 수치는 전날과 변동 없는 1만6천740명이다. 이재민은 1만7천854명으로 집계됐다. 이번 지진을 통해 피해를 본 건물은 856채이며, 붕괴한 건물은 총 190채라고', '부상자 1만6000여명, 이재민 약 1만8000여명…매몰자 생환 가능성 줄어 지난달 24일(현지시간) 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3천535명으로 늘었다고 호르헤 로드리게스 국회의장이 6일 밝혔다. 이는 전날보다 193명 늘어난 수치다. 부상자 수치는 전날과 변동 없는 1만6천740명이다. 이재민은 1만7천854명으로 집계됐다. 이번 지진을 통해 피해를 본 건물은 856채이며, 붕괴한 건물은 총 190채라고 로드리게스 의장은 설명했다. 정부는 육군과 보안군 2만9천567명을 투입했으며 이들은 자원봉사자 2만7천930명과 함께 구조·복구 작업을 진행하고 있다. 수만 명이 구조작업에 나서고 있으나 지진이 발생한 지 열흘이 넘으면서 매몰자들의 생환 가능성은 크게 줄어든 상태다. 구조에 대한 기대가 크다 보니 관련 오보도 이어지고 있다. 소셜미디어(SNS) 등을 통해 알려졌던 지진 11일 만에 어린이 등 4명 구조 소식은 현지 언론의 오보인 것으로 확인됐다. 이날 현지 유력 일간 엘나시오날은 전날 밤 9시께 라과이라주 카라바예다에서 구조대가 어린이 등 4명을 구조했다고 보도했으나, 이는 사실이 아니라고 바로잡았다. 엘나시오날은 해당 영상이 최근 발견된 게 아닌 이전에 있었던 구조 장면이라면서 이같이 정정했다. 베네수엘라 당국도 구조 대원들이 6천462명을 구조했으며 이 수치는 지난 2일 이후 변동이 없다고 밝혔다.', 'crawl', '세계일보', '2026-07-07 09:50:43', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/07/20260707507440.jpg', '2026-07-07 06:04:40', '2026-07-07 18:24:40.484739', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3960, 'https://www.segye.com/Articles/RSSList/segye_international.xml', NULL, 'https://www.segye.com/newsView/20260706515372', '국제', '모즈타바, 父 장례식도 불참… ‘건강이상설’ 증폭', '미국과 이스라엘의 공습으로 폭사한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식에 후계자인 모즈타바 하메네이 최고지도자가 모습을 드러내지 않으면서 ‘건강이상설’ 의혹이 증폭되고 있다. 5일(현지시간) 알자지라, AP통신 등에 따르면 이란 수도 테헤란에서 진행 중인 하메네이 전 최고지도자 장례 기도에 하메네이의 세 아들인 모스타파·마수드·메', '하메네이 폭사 후 넉달째 은둔 NYT “이란 정치권 분열 심화” ‘암살 시도 우려에 잠행’ 분석도 미국과 이스라엘의 공습으로 폭사한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식에 후계자인 모즈타바 하메네이 최고지도자가 모습을 드러내지 않으면서 ‘건강이상설’ 의혹이 증폭되고 있다. 5일(현지시간) 알자지라, AP통신 등에 따르면 이란 수도 테헤란에서 진행 중인 하메네이 전 최고지도자 장례 기도에 하메네이의 세 아들인 모스타파·마수드·메이삼이 모습을 드러냈다. 이란 전쟁 이후 처음이다. 그러나 차남인 모즈타바 최고지도자는 나타나지 않았다. 모즈타바, 父 장례식도 불참… 아들 4명 중 삼형제만 참석 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 네 아들 중 장남 모스타파(오른쪽 두 번째), 셋째 마수드(〃 세 번째), 넷쩨 메이삼(〃 네 번째)이 5일(현지시간) 수도 테헤란 대모살라 광장에서 진행 중인 아버지 장례식에 참석해 관 앞에서 기도하고 있다. 둘째 아들이자 후계자인 모즈타바는 불참했다. 지난 2월 미국·이스라엘의 공습으로 다친 것으로 알려진 그가 모습을 드러내지 않으면서 건강이상설이 증폭되고 있다. 테헤란=AFP연합뉴스 모즈타바는 3월 초 최고지도자에 임명된 뒤 공개 석상에 모습을 드러낸 적이 없다. 지난 1일 열린 부인의 비공식 추모식에도 참석하지 않았다. 전쟁 첫날인 2월28일 하메네이 전 최고지도자를 사망케 한 공습 당시 중상을 입었기 때문이라는 설이 지배적이다. 로이터통신은 지난 4월 측근의 말을 인용해 모즈타바 최고지도자의 얼굴이 크게 손상됐고, 다리는 심각한 상처를 입었다고 보도한 바 있다. 이란 국영TV는 그를 부상한 참전 용사라는 뜻의 ‘잔바즈’라고 칭하기도 했다. 일부 추모객은 실망감을 드러냈다. 장례식에 참석한 한 시민은 AP통신에 “우리가 무엇을 해야 하는지는 최고지도자가 직접 말해야 한다”고 했다. 뉴욕타임스(NYT)는 모즈타바 최고지도자가 오랜 기간 모습을 드러내지 않으면서, 이란 정치권의 분열이 심화하고 있다고 보도했다. NYT는 “그의 부재는 ‘누가 실제로 나라를 통치하는가’와 ‘부재 통치가 장기적으로 지속 가능한가’에 대한 의문을 불러일으키고 있다”고 지적했다. 모즈타바 최고지도자가 암살 시도를 우려해 공개 석상에 모습을 드러내지 않고 있다는 분석도 나온다. 최근 NYT는 이란 이슬람혁명수비대와 장례 준비 관계자의 말을 인용해 그가 장례식에 참석하고 싶다는 뜻을 밝혔으나, 이스라엘이 암살을 시도하거나 은신처를 추적할 수 있다는 우려로 이란 보안 당국이 거부했다고 보도했다. 알자지라도 “모즈타바 최고지도자의 불참은 이스라엘의 생명 위협 때문인 것으로 추정된다”고 전했다.', 'crawl', '세계일보', '2026-07-06 20:07:46', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/06/20260706515977.jpg', '2026-07-07 06:04:41', '2026-07-07 18:25:24.234087', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3962, 'https://www.segye.com/Articles/RSSList/segye_international.xml', NULL, 'https://www.segye.com/newsView/20260706515373', '국제', '일손도 보관장소도 태부족… 베네수엘라, 신원 확인 못한 채 매장', '베네수엘라를 강타한 연쇄 강진 발생 이후 열하루가 지나면서 구조 작업이 사실상 마무리 국면에 접어들고 있다. 법의학 체계가 수용 한계를 훌쩍 넘어서면서 시신 보관과 신원 확인에 어려움을 겪자 당국은 신원 미상 시신의 매장을 시작했다. 5일(현지시간) AFP통신과 BBC, 가디언 등에 따르면 베네수엘라 북부 라과이라주 라 에스페란자 공동묘지에는 이날 끝내', '강진 구조작업 마무리 국면 시신 보관체계 붕괴, 150여구 안장 비닐로 묶어 창고 밖 땡볕 방치도 부패 심해… “마치 공포영화 같다” 유가족들, 집단매장 우려감 확산 정부 “지문 등 확인 우선” 선 그어 베네수엘라를 강타한 연쇄 강진 발생 이후 열하루가 지나면서 구조 작업이 사실상 마무리 국면에 접어들고 있다. 법의학 체계가 수용 한계를 훌쩍 넘어서면서 시신 보관과 신원 확인에 어려움을 겪자 당국은 신원 미상 시신의 매장을 시작했다. 5일(현지시간) AFP통신과 BBC, 가디언 등에 따르면 베네수엘라 북부 라과이라주 라 에스페란자 공동묘지에는 이날 끝내 신원이 확인되지 않은 시신 150여구가 개별 무덤 형태로 한꺼번에 매장됐다. AFP는 현장에서 굴착기 두 대가 계속해서 새 무덤을 파고 있었고, 이미 조성된 묘지에는 흰 나무 십자가와 꽃다발이 놓였다고 전했다. 십자가에는 이름 없이 사망일만 지진이 발생한 6월24일로 표시됐다. 이름도 없이 ‘6월24일’ 사망일만… 빽빽한 십자가 5일(현지시간) 베네수엘라 라과이라주 카티아라마르에 신원 미상 지진 희생자를 위해 조성된 공동묘지에서 인부들이 나무 십자가를 세우고 있다. 라과이라주는 이번 지진의 최대 피해 지역 중 하나로 이날 해당 묘지에만 시신 150여구가 안장됐으며 십자가에는 이름 없이 사망일과 번호만 표기됐다. 이번 매장은 시신 보관 체계가 사실상 붕괴한 데 따른 조치로 보인다. 지진 직후 병원 영안실은 곧바로 포화 상태에 이르렀고, 이후 수습된 시신들은 라과이라 항구에 마련된 임시 보관소로 옮겨졌다. 그러나 항구에서 민간 기부로 운영되던 냉동 창고마저도 더 이상 수용할 수 없게 되면서 이후 수습된 시신은 비닐에 싸인 채 땡볕 아래 놓이는 상황까지 벌어졌다. BBC는 “시신 부패가 빠르게 진행돼 항구 시설에 강한 악취가 퍼지고 있고, 가족들은 손이나 헝겊 마스크로 입을 막은 채 시신 확인을 하고 있다”고 현지 분위기를 전했다. 신원 확인도 난항을 겪고 있다. 유가족들은 수시간씩 줄을 선 뒤 모니터에 띄워진 1000장 이상의 시신 사진을 일일이 넘겨보며 가족을 찾아야 한다. 상당수 시신은 부패와 외상으로 얼굴 식별이 어려워 문신, 팔찌, 옷가지, 담요 같은 단서에 의존할 수밖에 없는 것으로 알려졌다. 60세 여성 리리아나 곤살레스는 먼지가 묻은 담요를 통해 37세 조카를 알아봤다며 이 상황이 “마치 공포 영화 같다”고 BBC에 말했다. 현장에서 일하는 법의학자 조엘 미라발(45)은 “수습된 시신 중 신원을 확인해 줄 유가족이나 이웃이 있는 경우는 60∼70% 정도이며 그마저도 쉽지 않다”면서 “희생자들의 생전 모습이 10%도 남아있지 않기 때문”이라고 설명했다. 시신의 신원이 확인돼도 비용 문제로 장례를 치르지 못하는 경우도 잇따르고 있다. 25세 경비원 호세 안토니오 톨레도의 시신은 붕괴한 건물 잔해 아래에서 수습된 뒤 병원, 시설을 떠돌다 야외주차장으로 옮겨졌다. 며칠 뒤 가족이 신원을 확인했지만, 장례비용 450달러(약 60만원)를 마련하지 못해 곧바로 장례를 치르지 못했다. 그의 가족은 이후 지역 공동묘지의 무료 매장 공간을 제공한다는 시의 연락을 받고서야 한 시간 만에 공동묘지로 가서 장례를 마쳤다. 지난 2일 베네수엘라 라과이라를 강타한 지진으로 파손된 건물 잔해 속에서 주민들과 구조대원들이 수색 작업을 벌이고 있다. 현장 혼란이 커지면서 유가족들 사이에서는 신원 확인 없이 시신이 집단으로 매장될 수 있다는 공포도 확산하고 있다. 집단 매장 공포를 조장하는 허위·조작 영상이 소셜미디어를 통해 유포되기도 했다. 이에 델시 로드리게스 임시 대통령은 “집단 매장 계획은 없다”며 “정부는 법률에 따라 우선 지문과 사진으로 신원을 확인하고, 여기서 확인이 안 될 경우 법치의학적 방식으로 넘어가는 엄격한 절차를 마련해 두고 있다”고 강조했다. 건물 붕괴 현장에서 구조 작업이 여전히 진행되고 있지만 거의 마무리된 분위기다. 지난 2일 40대 경비원이 구조된 뒤 이틀 넘게 생존자가 발견되지 않고 있다. 국제 구조대도 철수를 시작해 당초 77개 구조팀 가운데 현재는 25개 팀만 현장에 남아있고, 유엔도 구조 대응 주도권을 지난 3일부터 베네수엘라 민방위 당국에 넘겼다. 베네수엘라 당국 공식 집계에 따르면 이번 지진으로 인한 사망자는 이날 기준 3342명, 부상자는 1만6700명이며, 이재민은 1만7000명 이상으로 나타났다. 민간 운영 실종자 신고 사이트에는 3만명 넘는 이름이 등록된 상태다.', 'crawl', '세계일보', '2026-07-06 20:03:45', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/06/20260706515904.jpg', '2026-07-07 06:04:41', '2026-07-07 18:25:47.878313', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3963, 'https://www.segye.com/Articles/RSSList/segye_international.xml', NULL, 'https://www.segye.com/newsView/20260706515655', '국제', '美, 국방비 증액 이행 압박 쟁점… 나토 정상 올해도 ‘트럼프 달래기’', '서방의 대표적인 자유진영 방위 동맹체인 북대서양조약기구(NATO·나토) 32개 회원국 정상들이 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 당면한 안보 현안을 논의한다. 올해 회의는 도널드 트럼프 미국 대통령으로부터 촉발된 나토 분열이 시작된 상황에서 열리는 것이라 향후 동맹의 향방을 가늠할 중요한 시험대가 됐다. 5일 로이터통신 등에 따르면 유', '7일부터 튀르키예서 정상회의 유럽 미군감축 계획 등 큰 부담 대서양동맹 향방 시험대 될 듯 서방의 대표적인 자유진영 방위 동맹체인 북대서양조약기구(NATO·나토) 32개 회원국 정상들이 7일(현지시간)부터 이틀간 튀르키예 수도 앙카라에서 당면한 안보 현안을 논의한다. 올해 회의는 도널드 트럼프 미국 대통령으로부터 촉발된 나토 분열이 시작된 상황에서 열리는 것이라 향후 동맹의 향방을 가늠할 중요한 시험대가 됐다. 5일 로이터통신 등에 따르면 유럽 국가의 국방비 증액 문제는 나토가 당면한 최대 안보 현안으로 꼽힌다. 현재 나토 국방비의 약 60%는 미국이 대고 있다. 트럼프 대통령은 줄곧 나토 회원국들이 ‘안보 무임승차’를 하고 있다며 국방비 증액을 요구해왔다. 또한 미국은 유럽에 주둔하고 있는 미군 감축 계획을 공개하는 등 나토 회원국을 압박했다. 트럼프 대통령이 2기 행정부 출범 이후 덴마크령 그린란드를 무력을 써서라도 병합하겠다는 의지를 드러내고, 지난 2월28일 이란과의 전쟁 과정에서 트럼프 대통령의 지원 요청에 나토 회원국이 미온적으로 반응하면서 트럼프 대통령의 요구는 더 거세졌다. 이 때문에 나토는 출범 77년 만에 최대 위기를 맞았다는 평가까지 나왔다. 일단 외신들은 8일 발표될 것으로 보이는 정상회의 공동선언문 초안에서 트럼프 대통령을 포함한 나토 정상들이 나토의 상호방위 조항인 제5조에 규정된 집단방위 의무를 재확인할 것이라고 보고 있다. 또한 트럼프 행정부는 이번 나토 정상회의에서의 미국 측 주요 의제와 관련, 유럽 동맹국들의 국방비 증액 약속 이행을 점검할 계획이다. 나토는 지난해 6월 네덜란드 헤이그에서 열린 정상회의에서 2035년까지 국내총생산(GDP) 대비 5%를 국방 분야에 지출하겠다고 합의했다. 마르크 뤼터 나토 사무총장도 최근 유럽과 캐나다가 안보 증강을 위해 군비를 대폭 늘리고 있다는 점을 강조하면서 트럼프 대통령의 거듭된 비판을 잠재우려고 노력하고 있다. 지난해 기준 미국을 제외한 나토 회원국들의 국방 지출은 전년 대비 20% 증가한 5740억달러(약 879조원)로 집계됐다. 뤼터 사무총장은 이날 미 월스트리트저널(WSJ)과의 인터뷰에서 “1년 전에는 모든 게 (방위비 증액) 약속에 관한 것이었다”며 “올해는 약속을 이행하는 것”이라고 말했다. 이어 그는 폭증하는 방산업계가 수요를 감당하지 못하는 ‘생산 수용 능력’의 한계에 직면했다고 지적했다. 나토는 정상회의 기간 방산업체 임원진과 정부 관계자들과 만나 무기 생산 증대 방안을 논의할 예정이다. 이번 정상회의에 이재명 대통령도 참석하는데, 앞서 청와대는 이 대통령이 나토 동맹국들을 상대로 방산 협력을 본격 추진한다는 의미가 있다고 설명했다. 이밖에 이번 나토 정상회의에서는 우크라이나 지원 문제와 이란 문제가 논의될 예정이다. 이날 백악관은 트럼프 대통령이 튀르키예에서 볼로디미르 젤렌스키 우크라이나 대통령, 아흐메드 알샤라 시리아 대통령과 회담한다고 밝혔다.', 'crawl', '세계일보', '2026-07-06 19:01:28', '보수', 'ready', 'https://img.segye.com/content/image/2026/07/06/20260706516339.jpg', '2026-07-07 06:04:41', '2026-07-07 18:25:58.582971', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3977, 'https://www.sisajournal.com/rss/S1N47.xml', NULL, 'https://www.sisajournal.com/news/articleView.html?idxno=378917', '정치', '합수본, 투표용지 인쇄업자·선관위 관계자 줄소환…계약·납품 과정 등 조사', '6∙3 지방선거 과정에서 불거진 투표용지 부족 사태를 수사 중인 검∙경 합동수사본부(본부장 김태훈 차장검사)가 투표용지 인쇄업자와 지역 선관위 관계자 등을 줄소환 한다.합수본은 7일 투표용지 인쇄업자 1명을 참고인 신분으로 불러 조사한다. 이어 서초구 선관위원 1명을 비롯해 송파구∙강남구∙관악∙서대문∙강서∙중랑∙마포구 선관위 관계자 각각 1명 등 8명을 참고인 신분으로 불러 조사할 예정이다.합수본은 이날 투표용지 인쇄업자를 상대로 선관위와 투표용지 공급 계약을 맺은 과정 및 실제 공급 과정 전반을 들여다볼 방침이다. 또 각 지역 선', 'м„ңмҡёмӢң м„ кұ°кҙҖлҰ¬мң„мӣҗнҡҢ в“’м—°н•©лүҙмҠӨ 6вҲҷ3 м§Җл°©м„ кұ° кіјм •м—җм„ң л¶Ҳкұ°м§„ нҲ¬н‘ңмҡ©м§Җ л¶ҖмЎұ мӮ¬нғңлҘј мҲҳмӮ¬ мӨ‘мқё кІҖвҲҷкІҪ н•©лҸҷмҲҳмӮ¬ліёл¶Җ(ліёл¶ҖмһҘ к№ҖнғңнӣҲ м°ЁмһҘкІҖмӮ¬)к°Җ нҲ¬н‘ңмҡ©м§Җ мқёмҮ„м—…мһҗмҷҖ м§Җм—ӯ м„ кҙҖмң„ кҙҖкі„мһҗ л“ұмқ„ мӨ„мҶҢнҷҳ н•ңлӢӨ. н•©мҲҳліёмқҖ 7мқј нҲ¬н‘ңмҡ©м§Җ мқёмҮ„м—…мһҗ 1лӘ…мқ„ м°ёкі мқё мӢ л¶„мңјлЎң л¶Ҳлҹ¬ мЎ°мӮ¬н•ңлӢӨ. мқҙм–ҙ м„ңмҙҲкө¬ м„ кҙҖмң„мӣҗ 1лӘ…мқ„ л№„лЎҜн•ҙ мҶЎнҢҢкө¬вҲҷк°•лӮЁкө¬вҲҷкҙҖм•…вҲҷм„ңлҢҖл¬ёвҲҷк°•м„ңвҲҷмӨ‘лһ‘вҲҷл§ҲнҸ¬кө¬ м„ кҙҖмң„ кҙҖкі„мһҗ к°Ғк°Ғ 1лӘ… л“ұ 8лӘ…мқ„ м°ёкі мқё мӢ л¶„мңјлЎң л¶Ҳлҹ¬ мЎ°мӮ¬н• мҳҲм •мқҙлӢӨ. н•©мҲҳліёмқҖ мқҙлӮ нҲ¬н‘ңмҡ©м§Җ мқёмҮ„м—…мһҗлҘј мғҒлҢҖлЎң м„ кҙҖмң„мҷҖ нҲ¬н‘ңмҡ©м§Җ кіөкёү кі„м•Ҫмқ„ л§әмқҖ кіјм • л°Ҹ мӢӨм ң кіөкёү кіјм • м „л°ҳмқ„ л“Өм—¬лӢӨліј л°©м№ЁмқҙлӢӨ. лҳҗ к°Ғ м§Җм—ӯ м„ кҙҖмң„ кҙҖкі„мһҗл“Өмқ„ мғҒлҢҖлЎңлҠ” нҲ¬н‘ңмҡ©м§Җ мқёмҮ„ л°ңмЈј л°Ҹ м„ кұ° лӢ№мқј лҢҖмқ‘ кіјм • л“ұмқ„ нҷ•мқён•ҙ нҲ¬н‘ңмҡ©м§Җ л¶ҖмЎұ мӮ¬нғңк°Җ л°ңмғқн•ҳм§Җ м•ҠмқҖ м§Җм—ӯ м„ кҙҖмң„мҷҖмқҳ м°Ёмқҙм җмқ„ л¶„м„қн• мҳҲм •мқҙлӢӨ. м•һм„ң н•©мҲҳліёмқҖ м§ҖлӮңлӢ¬ 11мқј мӨ‘м•ҷм„ кұ°кҙҖлҰ¬мң„мӣҗнҡҢлҘј л№„лЎҜн•ҙ мҶЎнҢҢвҲҷк°•лӮЁвҲҷм„ңмҙҲвҲҷкҙ‘м§„вҲҷлҸҷмһ‘кө¬ м„ кҙҖмң„ л“ұ 7кіім—җ лҢҖн•ң м••мҲҳмҲҳмғүмқ„ лІҢмҳҖлӢӨ. м§ҖлӮңлӢ¬ 24мқјм—җлҠ” м„ңмҡёмӢң м„ кҙҖмң„вҲҷмҶЎнҢҢкө¬ м„ кҙҖмң„ кҙҖкі„мһҗ 12лӘ…м—җ лҢҖн•ң м••мҲҳмҲҳмғүмқ„ м§„н–үн•ҙ мқҙл“Өмқҳ нңҙлҢҖм „нҷ” л“ұмқ„ нҷ•ліҙн–ҲлӢӨ. м•„мҡёлҹ¬ н•©мҲҳліёмқҖ л…ёнғңм•… м „ м„ кҙҖмң„мӣҗмһҘ л“ұ м„ кҙҖмң„мқҳ мҷёмң м„ұ м¶ңмһҘ мқҳнҳ№м—җ лҢҖн•ҙм„ңлҸ„ мҲҳмӮ¬м—җ мҶҚлҸ„лҘј лӮҙкі мһҲлӢӨ. н•©мҲҳліёмқҖ м§ҖлӮңлӢ¬ 30мқј л…ё м „ мң„мӣҗмһҘ л¶Җл¶Җмқҳ н•ҙмҷё лҸҷл°ҳ м¶ңмһҘ мқҳнҳ№кіј кҙҖл Ён•ҙ кі л°ңмқё мЎ°мӮ¬лҘј м§„н–үн–ҲлӢӨ. л…ё м „ мң„мӣҗмһҘмқҖ мһ¬мһ„ кё°к°„ мӨ‘ л°°мҡ°мһҗмҷҖ н•Ёк»ҳ лҸ…мқј, мҠӨмӣЁлҚҙ л“ұ н•ҙмҷё м¶ңмһҘмқ„ м„ё м°ЁлЎҖ лӢӨл…Җмҷ”лӢӨ. н•ҳм§Җл§Ң м„ кҙҖмң„ мӮ¬нӣ„ ліҙкі м„ңм—җлҠ” л°°мҡ°мһҗ лҸҷн–ү мӮ¬мӢӨмқҙ кё°мһ¬лҗҳм§Җ м•Ҡм•„ нҡЎл № мқҳнҳ№мқҙ м ңкё°лҗҗлӢӨ. м„ кҙҖмң„ кіөл¬ҙмӣҗл“ӨлҸ„ 2023л…„ 9мӣ” ‘лӘ°л””лёҢ лҢҖнҶөл № м„ кұ° м°ёкҙҖ’мқ„ лӘ…лӘ©мңјлЎң лӘ°л””лёҢ м¶ңмһҘмқ„ лӢӨл…ҖмҳӨлҠ” кіјм •м—җм„ң кІҪл№„ 1470л§Ңмӣҗмқ„ м„ кҙҖмң„ мҳҲмӮ°мңјлЎң м“ҙ мӮ¬мӢӨмқҙ м•Ңл Өм ё кі л°ң лҢҖмғҒмқҙ лҗҗлӢӨ.', 'crawl', '시사저널', '2026-07-07 11:14:03', '중도', 'ready', 'https://cdn.sisajournal.com/news/photo/202607/378917_386703_2244.jpg', '2026-07-07 06:04:41', '2026-07-07 18:26:52.987457', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3980, 'https://www.sisajournal.com/rss/S1N47.xml', NULL, 'https://www.sisajournal.com/news/articleView.html?idxno=378870', '정치', '배재고 “진심으로 사과”…광주일고 “어깨 펴길, 멋진 승부 펼치자”', '''스타벅스 응원'' 논란을 일으킨 서울 배재고등학교 야구부 학생들과 학부모, 교사가 6일 광주제일고등학교(광주일고)를 찾아 고개를 숙였다. 광주일고 측은 배재고의 사과를 받아들이며 "멋진 승부를 펼치는 날을 기대해본다"고 응답했다. 서울시교육청에 따르면, 배재고 야구부원 36명 전원과 일부 학부모 및 교직원 등 86명은 이날 오후 3시께 전남광주통합특별시 북구에 위치한 광주일고를 방문했다. 광주일고와 경기 도중 부적절한 구호를 외쳐 물의를 일으킨 지 일주일만이다. 배재고 야구부 주장 A군은 "저희가 광주에 발을 딛는 것만으로도 불편하', '7월6일 오후 전남광주통합특별시 북구 광주제일고등학교 강당에서 배재고 야구부 선수(왼쪽)가 광주일고 야구부 선수에게 사과문을 전달한 뒤 인사하고 있다. ⓒ 연합뉴스 ''스타벅스 응원'' 논란을 일으킨 서울 배재고등학교 야구부 학생들과 학부모, 교사가 6일 광주제일고등학교(광주일고)를 찾아 고개를 숙였다. 광주일고 측은 배재고의 사과를 받아들이며 "멋진 승부를 펼치는 날을 기대해본다"고 응답했다. 서울시교육청에 따르면, 배재고 야구부원 36명 전원과 일부 학부모 및 교직원 등 86명은 이날 오후 3시께 전남광주통합특별시 북구에 위치한 광주일고를 방문했다. 광주일고와 경기 도중 부적절한 구호를 외쳐 물의를 일으킨 지 일주일만이다. 배재고 야구부 주장 A군은 "저희가 광주에 발을 딛는 것만으로도 불편하셨을 텐데 귀한 시간 마련해주신 광주일고에 감사드린다"며 "부적절한 발언과 행동들로 마음의 큰 상처를 입은 광주일고 선수들과 학부모님, 광주 시민분들께 진심으로 사과드린다"고 밝혔다. A군은 "모든 선수가 진심으로 깊이 반성하고 있으며, 야구를 떠나서 인성이나 태도가 인생에서 얼마나 중요한지 깨닫고 다시 한번 배우게 됐다"면서 "같은 선수로서 정말 하면 안 되는 행동이었고 일어나면 안 되는 상황이었다"고 말했다. 이어 "저희 선수들의 좋지 못한 발언, 행동으로 인해 많은 분이 마음의 상처와 고통을 받고 계신다"며 "항상 마음속 깊이 반성하는 마음과 자세로 살아가겠다"고 강조했다. A군은 낭독을 마친 후 자필 사과문을 광주일고 주장에게 전달했다. 배재고 야구부 감독도 "선수들의 지역 비하 응원은 무엇으로도 변명할 수 없는 잘못임을 인정하며, 학생들을 잘 이끌고 가르쳐야 할 지도자로서 책임이 가장 크기에 진심으로 사죄드린다"고 사과했다. 그는 "깨끗하고 정정당당해야 할 경기에서 상대에 대한 존중과 동업자 정신, 선수로서 가져야 할 태도에 대해 제대로 가르치고 인도하지 못했다"며 "이기는 것보다 더 중요한 것이 있음을 저도 모르게 잊고 있었고, 저의 언행과 지도 방식이 올바른 본보기가 되지 못한 듯해 더욱 깊이 자책하며 부끄러울 뿐"이라고 덧붙였다. 배재고 교직원들은 "이번 사태를 단순한 일탈이나 실수가 아닌 윤리 의식과 역사 인식에 대한 총체적인 붕괴에서 비롯된 사례로 보고 심각하게 사안을 받아들이고 있다"며 "참담하고 부끄러운 마음"이라고 전했다. 이번 사태에 대한 진상조사와 징계 절차를 진행 중이라며, 외부 기관에서 진행 중인 조사에도 성실히 임하겠다고 약속했다. 배재고 교장과 야구부 감독은 눈물을 흘리기도 했다. 7월6일 오후 전남광주통합특별시 북구 국립 5·18 민주묘지에서 광주제일고등학교·배재고등학교 학생들이 참배하고 있다. ⓒ 연합뉴스 광주일고 "다시는 이런 일 발생하지 않길" 광주일고 선수 대표는 "이번 일을 통해 광주일고 야구도 상처주는 언행을 하지 않았는지 돌아보는 계기가 됐다"며 "다시는 이런 일이 발생하지 않길 바란다"고 당부했다. 광주일고 야구부 감독도 "사람은 누구나 실수를 한다. 실수는 반성하고, 서로 화해하는 것이 더 성숙된 사람으로 성장하게 만드는 것"이라며 "배재고와 다시 그라운드에서 경기를 하게 된다면 정정당당하게 멋진 승부 펼치는 날을 기대해본다"고 격려를 전했다. 이규연 광주일고 교장은 "들어오실 때 어머니들께서 눈물흘리고 계셔서 마음이 아팠다"며 "배재고 학생들, 고개 들고 어깨를 펴라. 여러분들 미래는 아직 끝나지 않았다"고 응원의 말을 건넸다. 이 교장은 "사과도 중요하고 실천도 중요한데 더 중요한 건 앞으로 더 잘 사는 것"이라며 "다음에 다시 만나 서로 마음껏 실력을 펼치고 멋진 웃음을 주도록 하자"고 했다. 양쪽 선수단은 광주일고 교내에 있는 광주학생독립운동 기념탑을 함께 참배했다. 이후 광주 국립 5·18 민주묘지로 이동해 5·18 민주화운동 피해자 묘역을 찾아 민주·인권·평화의 가치를 학습했다. 정근식 서울시 교육감과 김대중 전남광주 교육감도 묘역 참배에 동행했다. 앞서 배재고 야구부 학생 선수 일부는 지난달 29일 서울 목동구장에서 열린 경기에서 광주일고 더그아웃을 향해 "가야지, 가야지, 스타벅스 가야지"라는 구호를 외쳤다. 한 학생은 "탱크데이"라고 소리를 쳤다. ''스타벅스 5·18 탱크데이 이벤트''를 연상시키는 배재고 학생들의 지역 비하성 구호와 조롱성 행위가 담긴 영상이 공유되면서 여론의 공분이 커졌다. 이에 대한야구소프트볼협회 스포츠공정위원회는 배재고에 6개월 출전 정지와 함께 제81회 청룡기 전국고교야구선수권대회의 남은 경기 몰수패를 의결했다. 자체 조사를 벌여 온 배재고는 선창한 학생과 ''탱크데이''를 외친 학생 총 2명을 생활교육위원회에 회부하고 징계를 내리기로 했다. 경위를 파악 중인 서울시교육청은 결과에 따라 교장·교감 등에 대한 관리 책임을 물을지 여부를 검토할 방침이다.', 'crawl', '시사저널', '2026-07-06 17:36:45', '중도', 'ready', 'https://cdn.sisajournal.com/news/photo/202607/378870_386655_1831.jpg', '2026-07-07 06:04:41', '2026-07-07 18:26:58.607722', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3993, 'https://www.sisajournal.com/rss/S1N54.xml', NULL, 'https://www.sisajournal.com/news/articleView.html?idxno=378926', '경제', '“미·영 투자사 3곳, SK하이닉스 ADR 최대 70억 달러 인수 의사”', 'SK하이닉스의 미국 나스닥 상장을 앞두고 미국의 헤지펀드와 영국 자산운용사 등 투자사 3곳이 최대 70억 달러(10조7000억원) 규모의 SK하이닉스 미국주식예탁증서(ADR) 인수 의사를 밝혔다. 6일(현지시간) 파이낸셜타임스는 전직 오픈AI 연구원이 설립한 미국 헤지펀드 시추에이셔널 어웨어니스(Situational Awareness), 영국 자산운용사 베일리 기포드(Baillie Gifford), 미국 벤처캐피탈 코튜(Coatue)가 SK하이닉스가 발행하는 ADR 인수 의향을 밝혔다고 보도했다. 이들 3곳 투자사들이 밝힌 인수 금', '미국 헤지펀드 등 3곳이 SK하이닉스의 미국주식예탁증서(ADR) 공모에 최대 70억 달러(약 10조7000억원)어치를 인수할 수 있음을 시사했다.ⓒSK하이닉스 제공 SK하이닉스의 미국 나스닥 상장을 앞두고 미국의 헤지펀드와 영국 자산운용사 등 투자사 3곳이 최대 70억 달러(10조7000억원) 규모의 SK하이닉스 미국주식예탁증서(ADR) 인수 의사를 밝혔다. 6일(현지시간) 파이낸셜타임스는 전직 오픈AI 연구원이 설립한 미국 헤지펀드 시추에이셔널 어웨어니스(Situational Awareness), 영국 자산운용사 베일리 기포드(Baillie Gifford), 미국 벤처캐피탈 코튜(Coatue)가 SK하이닉스가 발행하는 ADR 인수 의향을 밝혔다고 보도했다. 이들 3곳 투자사들이 밝힌 인수 금액은 전체 공모 물량 43조1400억원(280억 달러)의 4분의 1에 달한다. 전직 오픈AI 연구원 리오폴드 애션브레너가 설립한 시추에이셔널 어웨어니스는 인공지능(AI) 관련 종목에 대한 선구적 투자로 유명하다. 베일리 기포드는 혁신 기업을 발굴해 초기 단계부터 장기간 보유하는 성장주 투자에 강점이 있으며, 코튜는 테크 기업에 대한 공격적 투자로 알려져 있는 벤처캐피탈이다. SK하이닉스는 발행 주식의 약 2.5%에 해당하는 신주 1779만 주를 ADR 형태로 발행해 오는 10일 나스닥에서 거래를 시작할 예정이다. 로이터 통신에 따르면, 페트라 캐피털 매니지먼트의 알버트 용 매니징파트너는 최근 시장 변동성이 큰 점을 언급하면서도 "SK하이닉스 주식 수요가 상대적으로 견조할 것"이라고 전망했다. 반면 스탠다드차타드의 순딥 간토리 주식 부문 최고투자책임자는 미국 상장에 따른 접근성 개선은 긍정적이라면서도 "메모리 사이클의 타이밍도 그만큼 중요하다"며 신중한 입장을 보였다. AJ벨의 다니엘 코츠워스 시장총괄은 "이번 상장이 다소 늦은 것은 아닌지"라며 의구심을 보이면서 "메모리 반도체주가 최근 몇 주간 상승 모멘텀을 잃었지만, 투자자들은 SK하이닉스를 일시적 유행이 아닌 견조한 장기 성장 스토리로 볼 수도 있다"고 블룸버그 통신에 전했다.', 'crawl', '시사저널', '2026-07-07 13:50:03', '중도', 'ready', 'https://cdn.sisajournal.com/news/photo/202607/378926_386717_1144.jpg', '2026-07-07 06:04:41', '2026-07-07 18:27:35.757919', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (3998, 'https://www.sisajournal.com/rss/S1N54.xml', NULL, 'https://www.sisajournal.com/news/articleView.html?idxno=378914', '경제', '엔비디아도 제쳤는데 주가는 ‘털썩’…삼성전자 30만원 밑으로', '삼성전자가 2분기 역대 최고 실적 기록을 썼는데도 주가 급락세를 맞았다. 실적 기대가 이미 주가에 선반영 되면서 차익 실현 매물이 나온 영향으로 풀이된다.한국거래소에 따르면, 7일 오전 45분 현재 삼성전자 주가는 전장 대비 6.29% 내린 29만8000원에 거래 중이다. 프리 마켓에서도 4%대 하락세를 보이며 30만5000원에 거래를 시작한 주가는 낙폭을 확대하며 30만원 밑으로 하락했다.시가총액 1위 기업인 삼성전자 주가가 큰 폭으로 떨어지자 코스피 지수도 급락하고 있다. 같은 시각 코스피 지수는 4.38% 내린 7698.71을', 'м„ңмҡё к°•лӮЁкө¬ м„ңмҙҲлҸҷ мӮјм„ұм „мһҗ м„ңмҙҲмӮ¬мҳҘ в“’ м—°н•©лүҙмҠӨ мӮјм„ұм „мһҗк°Җ 2л¶„кё° м—ӯлҢҖ мөңкі мӢӨм Ғ кё°лЎқмқ„ мҚјлҠ”лҚ°лҸ„ мЈјк°Җ кёүлқҪм„ёлҘј л§һм•ҳлӢӨ. мӢӨм Ғ кё°лҢҖк°Җ мқҙлҜё мЈјк°Җм—җ м„ л°ҳмҳҒ лҗҳл©ҙм„ң м°Ёмқө мӢӨнҳ„ л§Өл¬јмқҙ лӮҳмҳЁ мҳҒн–ҘмңјлЎң н’ҖмқҙлҗңлӢӨ. н•ңкөӯкұ°лһҳмҶҢм—җ л”°лҘҙл©ҙ, 7мқј мҳӨм „ 45л¶„ нҳ„мһ¬ мӮјм„ұм „мһҗ мЈјк°ҖлҠ” м „мһҘ лҢҖл№„ 6.29% лӮҙлҰ° 29л§Ң8000мӣҗм—җ кұ°лһҳ мӨ‘мқҙлӢӨ. н”„лҰ¬ л§Ҳмј“м—җм„ңлҸ„ 4%лҢҖ н•ҳлқҪм„ёлҘј ліҙмқҙл©° 30л§Ң5000мӣҗм—җ кұ°лһҳлҘј мӢңмһ‘н•ң мЈјк°ҖлҠ” лӮҷнҸӯмқ„ нҷ•лҢҖн•ҳл©° 30л§Ңмӣҗ л°‘мңјлЎң н•ҳлқҪн–ҲлӢӨ. мӢңк°Җмҙқм•Ў 1мң„ кё°м—…мқё мӮјм„ұм „мһҗ мЈјк°Җк°Җ нҒ° нҸӯмңјлЎң л–Ём–ҙм§Җмһҗ мҪ”мҠӨн”ј м§ҖмҲҳлҸ„ кёүлқҪн•ҳкі мһҲлӢӨ. к°ҷмқҖ мӢңк°Ғ мҪ”мҠӨн”ј м§ҖмҲҳлҠ” 4.38% лӮҙлҰ° 7698.71мқ„ к°ҖлҰ¬нӮӨкі мһҲлӢӨ. ‘л°ҳлҸ„мІҙ нҲ¬нҶұ’мқё SKн•ҳмқҙлӢүмҠӨлҸ„ 4.18% лӮҙлҰ° 224л§Ң5000мӣҗм—җ кұ°лһҳ мӨ‘мқҙл©° мӮјм„ұм „кё°(-5.91%), мӮјм„ұмғқлӘ…(-6.10%), мӮјм„ұл¬јмӮ°(-5.12%) л“ұ лӢӨлҘё мӮјм„ұ кі„м—ҙмӮ¬л“ӨлҸ„ нҒ° лӮҷнҸӯмқ„ кё°лЎқ мӨ‘мқҙлӢӨ. мқҙлӮ мЈјк°Җ н•ҳлқҪм„ёлҠ” ‘м…ҖмҳЁ’ л¬јлҹүмқҙ лӮҳмҳЁ лҚ° л”°лҘё кІ°кіјлЎң л¶„м„қлҗңлӢӨ. мӢӨм Ғ кё°лҢҖк°җмқҙ мқҙлҜё мЈјк°Җм—җ м„ л°ҳмҳҒ лҗҗмңјл©°, м§Җн‘ңк°Җ нҷ•мқёлҗң мқҙлӮ кі м җмқҙлқјкі нҢҗлӢЁн•ң м°ЁмқөмӢӨнҳ„ л§Өл¬јмқҙ мҸҹм•„мЎҢлӢӨлҠ” л¶„м„қмқҙлӢӨ. н•ңм§ҖмҳҒ нӮӨмӣҖмҰқк¶Ң м—°кө¬мӣҗмқҖ “л°©кёҲ л°ңн‘ңлҗң 2л¶„кё° мһ м •мӢӨм Ғ мӢӨм ңм№ҳк°Җ 89мЎ°4000м–ө мӣҗмңјлЎң м»Ём„јм„ңмҠӨ 85мЎ°мӣҗмқ„ мғҒнҡҢн•ҳлҠ” м„ңн”„лқјмқҙмҰҲлҘј кё°лЎқн–ҲлӢӨ”л©ҙм„ңлҸ„ “мқҙлІҲ мӢӨм Ғ л°ңн‘ң нӣ„ м…ҖмҳЁ л¬јлҹү м¶ңнҡҢмҷҖ м—…нҷ© л…ёмқҙмҰҲ к·№ліөм—җ л”°лҘё м¶”кІ© л§ӨмҲҳ м—¬л¶Җк°Җ кёҲмқј лӢЁкё°м Ғмқё кҙҖм „ нҸ¬мқёнҠё”лқјкі л°қнҳ”лӢӨ. лӢӨл§Ң мҰқк¶Ңк°Җм—җм„ңлҠ” мӮјм„ұм „мһҗмқҳ мЈјк°Җ мғҒмҠ№ м—¬л ҘмқҖ м—¬м „н•ҳлӢӨкі ліҙкі мһҲлӢӨ. лҘҳнҳ•к·ј лҢҖмӢ мҰқк¶ҢмқҖ мқҙлӮ “лӮҙл…„м—җлҠ” мҳ¬н•ҙ лҢҖл№„ л©”лӘЁлҰ¬л°ҳлҸ„мІҙ кіөкёү л¶ҖмЎұмқҳ к°•лҸ„к°Җ мӢ¬нҷ”н• кІғмқҙл©°, мҳ¬н•ҙ нҳ„кёҲнқҗлҰ„мқҙ кө¬мІҙнҷ”лҗҳлҠ” 3л¶„кё° мӢӨм Ғл°ңн‘ң мқҙнӣ„ м—ӯлҢҖ мөңлҢҖ к·ңлӘЁмқҳ мЈјмЈјнҷҳмӣҗ м •мұ…лҸ„ мӢңн–үн• кІғ”мқҙлқјл©° л№„мӨ‘нҷ•лҢҖлҘј м ңмӢңн–ҲлӢӨ. н•ңнҺё мӮјм„ұм „мһҗлҠ” мқҙлӮ 2л¶„кё° м—°кІ° кё°мӨҖ л§Өм¶ң 171мЎ°мӣҗ, мҳҒм—…мқҙмқө 89мЎ°4000м–өмӣҗмқҳ мһ м • мӢӨм Ғмқ„ кё°лЎқн–ҲлӢӨкі л°қнҳ”лӢӨ. м§ҖлӮңн•ҙ к°ҷмқҖ кё°к°„ліҙлӢӨ л§Өм¶ңмқҖ 129%, мҳҒм—…мқҙмқөмқҖ 1810% мҰқк°Җн•ң мҲҳм№ҳлӢӨ. м„ұкіјкёү м¶©лӢ№кёҲ м¶”м •м№ҳ 15мЎ°~19мЎ°мӣҗмқ„ л°ҳмҳҒн•ҳл©ҙ, м—…кі„м—җм„ңлҠ” л¶„кё° мҳҒм—…мқҙмқөмқҙ мӮ¬мӢӨмғҒ 100мЎ°мӣҗмқ„ мӣғлҸҲ кІғмңјлЎң ліҙкі мһҲлӢӨ. мқҙлҠ” кёҖлЎңлІҢ мӢңмһҘм—җм„ңлҸ„ м „лЎҖлҘј м°ҫкё° нһҳл“ к·ңлӘЁлӢӨ. мў…м „ мҳҒм—…мқҙмқө мөңкі м№ҳмқё м—”л№„л””м•„мқҳ 535м–ө лӢ¬лҹ¬, м• н”Ңмқҙ 508м–ө5000л§Ң лӢ¬лҹ¬ кё°лЎқмқ„ лӘЁл‘җ л„ҳм–ҙм„°мңјл©°, л¶„кё° л§Өм¶ңлЎңлҸ„ кёҖлЎңлІҢ л№…н…ҢнҒ¬мӮ¬мқҳ кё°лЎқмқ„ лӣ°м–ҙл„ҳм—ҲлӢӨ. мөңк·ј л©”нғҖмқҳ нҒҙлқјмҡ°л“ң мӮ¬м—… л°ңн‘ңлЎң ‘л°ҳлҸ„мІҙ н”јнҒ¬м•„мӣғ’ мҡ°л Өк°Җ лІҲм§„ к°ҖмҡҙлҚ° лӮҳмҳЁ ‘м—ӯлҢҖкёү’ м„ұм Ғн‘ңлқј, мӢңмһҘм—җм„ңлҠ” мӮјм„ұм „мһҗк°Җ н•ҙлӢ№ мҡ°л ӨлҘј лӢЁмҲЁм—җ мһ мһ¬мӣ лӢӨкі нҸүк°Җн•ҳкі мһҲлӢӨ.', 'crawl', '시사저널', '2026-07-07 09:57:10', '중도', 'ready', 'https://cdn.sisajournal.com/news/photo/202607/378914_386698_5655.jpg', '2026-07-07 06:04:41', '2026-07-07 18:27:47.157827', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4007, 'https://www.sisajournal.com/rss/S1N54.xml', NULL, 'https://www.sisajournal.com/news/articleView.html?idxno=378861', '경제', '홈플러스 “일부 카드사, 대금 지급 보류 즉각 철회해야”', '홈플러스는 서울회생법원의 회생절차 폐지 결정 이후 현대카드와 삼성카드가 오프라인 가맹점 대금 지급 보류 공문을 보낸 데 대해 부당한 처사라며 즉각 철회를 요구했다.6일 홈플러스에 따르면, 홈플러스는 회생절차 폐지 결정 이후 현대카드와 삼성카드로부터 ‘홈플러스 온라인몰 포인트 제휴 계약 종료, 온·오프라인 미수금 및 매출 취소분 처리를 위한 오프라인 가맹점 대금 지급 보류 및 상계 시행’을 알리는 공문을 받았다.홈플러스는 “회생절차 폐지 결정은 ‘확정’돼야 효력이 발생하는데, 공고가 있은 날부터 14일 이내에 즉시항고가 가능하므로 아', 'м§ҖлӮң 3мқј м„ңмҡё к°•м„ңкө¬ нҷҲн”Ңлҹ¬мҠӨ ліёмӮ¬ л¬ёмқҙ лӢ«нҳҖ мһҲлӢӨ. в“’м—°н•©лүҙмҠӨ нҷҲн”Ңлҹ¬мҠӨлҠ” м„ңмҡёнҡҢмғқлІ•мӣҗмқҳ нҡҢмғқм Ҳм°Ё нҸҗм§Җ кІ°м • мқҙнӣ„ нҳ„лҢҖм№ҙл“ңмҷҖ мӮјм„ұм№ҙл“ңк°Җ мҳӨн”„лқјмқё к°Җл§№м җ лҢҖкёҲ м§Җкёү ліҙлҘҳ кіөл¬ёмқ„ ліҙлӮё лҚ° лҢҖн•ҙ л¶ҖлӢ№н•ң мІҳмӮ¬лқјл©° мҰүк°Ғ мІ нҡҢлҘј мҡ”кө¬н–ҲлӢӨ. 6мқј нҷҲн”Ңлҹ¬мҠӨм—җ л”°лҘҙл©ҙ, нҷҲн”Ңлҹ¬мҠӨлҠ” нҡҢмғқм Ҳм°Ё нҸҗм§Җ кІ°м • мқҙнӣ„ нҳ„лҢҖм№ҙл“ңмҷҖ мӮјм„ұм№ҙл“ңлЎңл¶Җн„° ‘нҷҲн”Ңлҹ¬мҠӨ мҳЁлқјмқёлӘ° нҸ¬мқёнҠё м ңнңҙ кі„м•Ҫ мў…лЈҢ, мҳЁ·мҳӨн”„лқјмқё лҜёмҲҳкёҲ л°Ҹ л§Өм¶ң м·ЁмҶҢл¶„ мІҳлҰ¬лҘј мң„н•ң мҳӨн”„лқјмқё к°Җл§№м җ лҢҖкёҲ м§Җкёү ліҙлҘҳ л°Ҹ мғҒкі„ мӢңн–ү’мқ„ м•ҢлҰ¬лҠ” кіөл¬ёмқ„ л°ӣм•ҳлӢӨ. нҷҲн”Ңлҹ¬мҠӨлҠ” “нҡҢмғқм Ҳм°Ё нҸҗм§Җ кІ°м •мқҖ ‘нҷ•м •’лҸјм•ј нҡЁл Ҙмқҙ л°ңмғқн•ҳлҠ”лҚ°, кіөкі к°Җ мһҲмқҖ лӮ л¶Җн„° 14мқј мқҙлӮҙм—җ мҰүмӢңн•ӯкі к°Җ к°ҖлҠҘн•ҳлҜҖлЎң м•„м§Ғ нҡҢмғқм Ҳм°Ёк°Җ мң м§ҖлҗңлӢӨ”л©° “м№ҙл“ңмӮ¬к°Җ нҡҢмғқм Ҳм°Ё нҸҗм§Җ кІ°м •мқ„ мқҙмң лЎң нҷҲн”Ңлҹ¬мҠӨ мҳЁлқјмқёлӘ° нҸ¬мқёнҠё м ңнңҙ кі„м•Ҫ мў…лЈҢлҘј нҶөм§Җн•ң кІғмқҖ мҡ”кұҙмқ„ к°–м¶”м§Җ м•Ҡм•„ нҡЁл Ҙмқҙ м—ҶлӢӨ”кі мЈјмһҘн–ҲлӢӨ. лҳҗ “мҳӨн”„лқјмқём—җм„ңлҠ” мҷёмғҒ кө¬л§Өк°Җ л¶Ҳк°ҖлҠҘн•ҳкі мҳЁлқјмқё мҳҒм—…лҸ„ 3мқјм§ё мӨ‘лӢЁлҸј мЈјл¬ё м·ЁмҶҢк°Җ л¶Ҳк°ҖлҠҘн•ң мғҒнҷ©”мқҙлқјл©° “мҳЁ·мҳӨн”„лқјмқё лҜёмҲҳкёҲ л°Ҹ л§Өм¶ң м·ЁмҶҢл¶„ мІҳлҰ¬лҘј мң„н•ҙ мҳӨн”„лқјмқё к°Җл§№м җ лҢҖкёҲ м§Җкёүмқ„ ліҙлҘҳн•ҳлҠ” кІғмқҖ лӮ©л“қн•ҳкё° м–ҙл өлӢӨ”кі мЈјмһҘн–ҲлӢӨ. нҷҲн”Ңлҹ¬мҠӨлҠ” м№ҙл“ңмӮ¬мқҳ лҢҖкёҲ м§Җкёү ліҙлҘҳк°Җ м§ҖмҶҚлҗ кІҪмҡ° м •мғҒм Ғмқё мҳҒм—…мқҙ м–ҙл ӨмӣҢм§Ҳ мҲҳ мһҲлӢӨкі мҡ°л Өн–ҲлӢӨ. м№ҙл“ңмӮ¬мқҳ лҢҖкёҲ м§Җкёү ліҙлҘҳлЎң м№ҙл“ң лҢҖкёҲ нҡҢмҲҳк°Җ л§үнһҗ кІҪмҡ° мҳҒм—…мқ„ мқҙм–ҙк°Ҳ мҲҳ м—ҶлӢӨлҠ” мһ…мһҘмқҙлӢӨ.', 'crawl', '시사저널', '2026-07-06 17:22:16', '중도', 'ready', 'https://cdn.sisajournal.com/news/photo/202607/378861_386643_3217.jpg', '2026-07-07 06:04:41', '2026-07-07 18:28:04.244334', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4123, 'https://www.womennews.co.kr/rss/S1N1.xml', NULL, 'https://www.womennews.co.kr/news/articleView.html?idxno=279483', '정치', '국회 국조특위 의원들, 봉쇄 27일 만에 잠실 개표소 진입', '경찰이 2일 6·3 지방선거 투표용지 부족 사태 국정조사특별위원회 의원들의 개표소 진입을 위해 개표소 앞 시위대들을 해산시켰다.경찰은 이날 오전부터 봉쇄 시위가 진행 중인 서울 송파구 올림픽공원 핸드볼경기장 입구에 경력을 배치해 입구 좌우에 벽을 만들었다.경찰은 경기장을 봉쇄하고 있던 시위 참가자들을 끌어냈다.이날 이날 국회 6·3 지방선거 투표용지 부족 사태 국정조사특별위원회 의원들의 경기장 내부 현장 검증을 위한 조치다. 의원들은 이날 오후 경찰의 도움으로 개표소 안으로 들어갔다.이날 낮 12시25분께 경찰이 2-1번 게이트 앞', '국회 ''제9회 전국동시지방선거 투표용지 부족 사태 등 국민 참정권 침해 진상규명 및 선거관리 개혁을 위한 국정조사 특별위원회'' 위원들이 2일 현장 조사를 위해 서울 송파구 올림픽공원 핸드볼경기장 개표소로 들어가고 있다. ⓒ연합뉴스 경찰이 2일 6·3 지방선거 투표용지 부족 사태 국정조사특별위원회 의원들의 개표소 진입을 위해 개표소 앞 시위대들을 해산시켰다. 경찰은 이날 오전부터 봉쇄 시위가 진행 중인 서울 송파구 올림픽공원 핸드볼경기장 입구에 경력을 배치해 입구 좌우에 벽을 만들었다. 경찰은 경기장을 봉쇄하고 있던 시위 참가자들을 끌어냈다. 이날 이날 국회 6·3 지방선거 투표용지 부족 사태 국정조사특별위원회 의원들의 경기장 내부 현장 검증을 위한 조치다. 의원들은 이날 오후 경찰의 도움으로 개표소 안으로 들어갔다. 이날 낮 12시25분께 경찰이 2-1번 게이트 앞에 몸으로 벽을 만들어 저지선을 형성하자 시위대가 강하게 항의했다. 의원들의 진입과정에서 이를 저지하려는 시위대와 경찰의 몸싸움이 벌어졌다. 의원들의 개표소 진입은 지난달 5일 잠실7동 제2투표소 투표함 두 개가 개표소인 핸드볼경기장으로 옮겨지고 ''봉쇄 시위''가 시작된 지 27일 만이다. 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 이날오전 10시께 송파구 선관위에서 투표용지 관리와 사태 발생 당시 대응 상황, 투·개표 과정 등에 대한 설명을 들은데 이어 잠실 개표소 현장 조사를 진행할 예정이다. 송파선관위 보고에 따르면 현재 올림픽공원 핸드볼경기장 대관사무실에는 투표록 104부, 사전투표록 27부, 투표함 및 투표 관계 서류 등 인계서 146부, 개표상황표 460부, 투표지 보관 상자 428~434박스, 잠실7동 투표함 4개, 선거 관계 서류, 거소투표 등 접수 및 반송 처리 대장, 잘못 투입·구분된 투표지 봉투 보관 상자 등이 보관돼 있다. 투표지 분류기, 심사계수기, 개표 보고용 노트북, 기타 개표 관련 비품들과 임차한 PC 및 프린터, 팩스, 전화기 등도 있다. 2일 서울 송파구 올림픽공원 핸드볼경기장 개표소 앞에서 국조특위 현장조사를 앞두고 시위 참가자들이 구호를 외치고 있다. ⓒ연합뉴스 경찰은 이날 잠실 개표소 현장에 대화경찰 100여명과 형사 300여명, 기동대 25개 부대 등 약 1600여명을 배치해 국회 국정조사특별위원회의 개표소 현장검증에 대비했다. 우종화 송파경찰서 경비과장은 현장 방송을 통해 "국정조사특별위원회가 경찰에 진입로 확보를 요청했다"며 "현장 조사를 위해 필요한 조치를 취할 수 있다고 말했다. 오전에는 저지선 뒤로 진입을 막는 경찰과 이를 저지하지 말라는 시민들 간 충돌도 벌어졌다. 오전 9시께 1~3번 게이트 앞에는 100명 안팎의 시위대가 모여 태극기를 흔들며 "부정선거 재선거" "당일투표 수개표"를 일제히 외쳤다. 황교안 자유와혁신 대표와 이영돈 PD, 체육단체의 경기장 진입을 혼자 끝까지 막았던 이른바 ''올다르크''(올림픽공원+잔 다르크) 등도 2-1번 게이트 앞을 지켰다. 오전 9시30분께는 시민들간의 충돌도 있었다. 성조기를 든 시위대가 "윤어게인, 윤석열 대통령"을 선창 후 삼창하는 방식으로 구호를 외치기 시작했고, "부정선거 재선거 당일투표 수개표", "한미공조 국제수사" 구호도 뒤섞여 나왔다. "부정선거 재선거만 외쳐야 하는데 왜 윤어게인을 외치느냐"며 언성을 높이는 참가자들도 있었다.', 'crawl', '여성신문', '2026-07-02 13:43:55', '진보', 'ready', 'https://cdn.womennews.co.kr/news/photo/202607/279483_450467_3544.jpg', '2026-07-07 06:04:43', '2026-07-07 18:33:23.47075', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4128, 'https://www.womennews.co.kr/rss/S1N2.xml', NULL, 'https://www.womennews.co.kr/news/articleView.html?idxno=279664', '사회', '''피습 자작극 의혹'' 정이한 개혁신당 부산시장 후보 구속영장', '지난 6·3 지방선거에서 음료 피습 자작극을 벌인 혐의를 받는 정이한 전 개혁신당 부산시장 후보에 대해 구속영장이 청구됐다.부산 금정경찰서는 지난 1일 위계공무집행방해 및 공직선거법 위반 등 혐의로 정 전 후보와 공모 관계에 있는 A(30대)씨 등 2명에 대한 구속영장을 신청했다고 7일 밝혔다.검찰은 지난 3일 법원에 해당 구속영장을 청구했다. 정 전 후보와 A씨에 대한 구속전피의자심문(영장실질심사)은 오는 8일 오후 2시 부산지밥법원에서 열린다..정 전 후보에 대해서는 엄지아 판사가, A씨에 대해서는 심학식 부장판사가 영장심사를', '정이한 전 개혁신당 부산시장 후보 ⓒ연합뉴스 지난 6·3 지방선거에서 음료 피습 자작극을 벌인 혐의를 받는 정이한 전 개혁신당 부산시장 후보에 대해 구속영장이 청구됐다. 부산 금정경찰서는 지난 1일 위계공무집행방해 및 공직선거법 위반 등 혐의로 정 전 후보와 공모 관계에 있는 A(30대)씨 등 2명에 대한 구속영장을 신청했다고 7일 밝혔다. 검찰은 지난 3일 법원에 해당 구속영장을 청구했다. 정 전 후보와 A씨에 대한 구속전피의자심문(영장실질심사)은 오는 8일 오후 2시 부산지밥법원에서 열린다.. 정 전 후보에 대해서는 엄지아 판사가, A씨에 대해서는 심학식 부장판사가 영장심사를 담당한다. 정 전 후보 측은 지난 4월27일 부산 금정구에서 선거운동 중 지나가던 승용차의 운전자가 뿌린 음료수를 맞고 넘어져 뇌진탕 진단을 받았다고 주장, 이후 목에 깁스를 한 채 경찰서를 찾아 선처 탄원서를 제출하기도 했다. 경찰은 이후 자작극 의혹을 인지하고 선거 다음 날인 지난달 4일 정 전 후보 선거사무소를 압수수색했다. 또 A씨의 휴대전화 포렌식 결과 정 전 후보와 A씨 간 사전 통화 기록 등을 확보한 것으로 전해졌다. A씨는 전직 헬스 트레이너로 정 전 후보와 알고 지내던 사이였던 것으로 알려졌다. 경찰은 정 전 후보의 자작극 의혹 외에도 학적 논란 및 여론조사 의혹, 부친 회사 계열사 직원 선거운동 동원 의혹 등 제기된 사안 전반에 대해 수사를 진행하고 있다. 정 전 후보는 사건이 언론에 보도되기 전 탈당계를 제출했고, 선거 직후 사회관계망서비스(SNS)를 통해 정계 은퇴를 선언했다.', 'crawl', '여성신문', '2026-07-07 13:07:37', '진보', 'ready', 'https://cdn.womennews.co.kr/news/photo/202607/279664_450719_5729.jpg', '2026-07-07 06:04:43', '2026-07-07 18:33:32.825056', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4131, 'https://www.womennews.co.kr/rss/S1N2.xml', NULL, 'https://www.womennews.co.kr/news/articleView.html?idxno=279658', '사회', '검찰, ''여고생 살인'' 장윤기 수사 광주 광산경찰서 압수수색', '검찰이 장윤기 사건에 대한 경찰의 부실수사 정황을 확인하기 위해 7일 광주 광산경찰서에 대한 압수수색에 나섰다.광주지검은 이날 오전 광주 여고생 살인 사건과 관련 공무상비밀누설, 증거인멸 등 혐의로 광산경찰서와 주요 피의자의 주거지 등에 대해 압수수색을 벌이고 있다.검찰은 수사 기밀 유출 및 증거 은폐 등 사안의 중대성을 고려해, 김봉진 형사1부장을 팀장으로 하는 별도의 전담 수사팀을 구성해 수사하고 있다.검찰은 형사과 담당팀 관계자 등 다수 경찰관을 공무상비밀누설, 증거인멸 등 혐의로 입건했다.앞서 광주경찰청은 장윤기 사건 부실수', '살인·살인미수 혐의를 받는 장윤기(23) 씨가 14일 오전 광주 서부경찰서에서 검찰로 송치되고 있다. ⓒ연합뉴스 검찰이 장윤기 사건에 대한 경찰의 부실수사 정황을 확인하기 위해 7일 광주 광산경찰서에 대한 압수수색에 나섰다. 광주지검은 이날 오전 광주 여고생 살인 사건과 관련 공무상비밀누설, 증거인멸 등 혐의로 광산경찰서와 주요 피의자의 주거지 등에 대해 압수수색을 벌이고 있다. 검찰은 수사 기밀 유출 및 증거 은폐 등 사안의 중대성을 고려해, 김봉진 형사1부장을 팀장으로 하는 별도의 전담 수사팀을 구성해 수사하고 있다. 검찰은 형사과 담당팀 관계자 등 다수 경찰관을 공무상비밀누설, 증거인멸 등 혐의로 입건했다. 앞서 광주경찰청은 장윤기 사건 부실수사를 규명하기 위한 수사전담팀을 편성, 전날 사건을 담당했던 광주 광산경찰서 수사팀장을 증거인멸 혐의로 긴급 체포했다. 장윤기 사건 담당팀장이었던 A 경감은 지난 5월 5일 사건 직후 장윤기의 차량(SUV)을 압수수색하는 과정에서 일부 증거를 인멸한 혐의를 받고 있다. 경찰은 수사 주체를 광주경찰청 전담팀에서 국가수사본부로 격상해 전날 인력을 광주로 파견했다. 해당 팀장은 장윤기의 SUV 차량 내부에서 범행에 사용했던 케이블타이(공업용 묶음 끈)를 압수하지 않은 혐의를 받고 있다. 장윤기는 범행을 위해 사전에 흉기 2점을 준비했는데, 케이블타이는 장윤기가 피해자 납치 때 사용하려 했을 가능성이 제기됐다.', 'crawl', '여성신문', '2026-07-07 10:37:16', '진보', 'ready', 'https://cdn.womennews.co.kr/news/photo/202607/279658_450709_301.jpg', '2026-07-07 06:04:43', '2026-07-07 18:33:40.43347', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4154, 'https://www.womennews.co.kr/rss/S1N3.xml', NULL, 'https://www.womennews.co.kr/news/articleView.html?idxno=279610', '국제', '[세계는 지금] 하메네이 4개월 만의 장례식..."이란 격변의 전환점"', '지난 2월 28일 미국과 이스라엘의 공습으로 사망한 알리 하메네이 전 이란 최고지도자의 장례식이 사흘째를 맞고 있다.하메네이의 장례식은 사망 126일 만인 4일(현지 시각)부터 일주일간 진행되고 있다. 하메네이의 시신은 앞서 사망 약 4개월 만인 지난 2일 테헤란 이맘 호메이니 모살라(대사원)에 안치됐다. 4~5일 일반 참배객 조문을 시작으로 6일 테헤란 시내 장례 행렬, 7일 종교 도시 곰에서 열리는 추모 행사를 거쳐 9일 하메네이의 고향 마슈하드에 안장될 예정이다.뉴욕타임스(NYT)는 하메네이가 살해된 지 4달이 넘도록 장례식이', '5일(현지시각) 테헤란에서 열린 장례식 둘째 날 그랜드 모살라(대사원)에 사람들이 모여 피살된 이란의 최고지도자 아야톨라 알리 하메네이를 추모하고 있다. 지난 2월 28일 미국과 이스라엘의 공습으로 사망한 알리 하메네이 전 이란 최고지도자의 장례식이 사흘째를 맞고 있다. 하메네이의 장례식은 사망 126일 만인 4일(현지 시각)부터 일주일간 진행되고 있다. 하메네이의 시신은 앞서 사망 약 4개월 만인 지난 2일 테헤란 이맘 호메이니 모살라(대사원)에 안치됐다. 4~5일 일반 참배객 조문을 시작으로 6일 테헤란 시내 장례 행렬, 7일 종교 도시 곰에서 열리는 추모 행사를 거쳐 9일 하메네이의 고향 마슈하드에 안장될 예정이다. 뉴욕타임스(NYT)는 하메네이가 살해된 지 4달이 넘도록 장례식이 지연된 것은 올해 이란이 직면한 이례적인 상황을 반영한 것이라고 분석했다. 미국과 이스라엘의 폭격이 이어지는 가운데, 정부가 장례 행사의 안전을 보장할 수 있을지 불확실했기 때문이다. 대사원에는 하메네이의 시신이 담긴 관은 함께 사망한 사위, 장녀, 며느리 등 가족들의 관과 함께 놓였다. 생후 14개월 손녀의 관도 포함됐다. 이란 국영방송은 단상에 놓인 하메네이와 그 일가의 관을 보고 울부짖는 시민들의 모습을 방영했다. 공습으로 일가족이 함께 사망한 사실을 상기시키며 국민의 슬픔과 분노를 자극하려는 연출이라는 분석이 나온다. 하메네이는 2월 28일 미국과 이스라엘의 공습으로 사망했다. 이란 신정 체제에서 최고지도자는 단순한 국가 원수가 아닌 혁명 운동 지도자이자 시아파의 마지막 이맘(선지자)을 대변하는 특별한 종교적 존재다. 특히 하메네이의 경우 이란 이슬람 혁명 이후 최장기간인 37년간 이란의 최고지도자로 군림해 왔다. 이란 언론은 알리 하메네이의 장례식에 100여 개국 대표단이 참석할 것이라고 전했다. 이란과 미국의 종전 협상을 중재하고 있는 파키스탄에서는 국가 정상인 셰바즈 샤리프 총리와 사이드 아심 무니르 육군참모총장이 조문했다. 파키스탄은 미국과 이란 사이에서 핵심적인 중재국 역할을 해왔으며, 지난 4월의 휴전과 6월의 양해각서(MoU) 체결을 이끌어내는 데 기여했다. 이 합의는 현재 전쟁 종식을 목표로 하는 광범위한 협상의 기반이 되고 있다. 파키스탄과 이란의 관계는 최근 몇 년간 긴장으로 얼룩졌으나, 미국 및 이스라엘과의 전쟁, 그리고 갈등을 종식하기 위한 파키스탄의 중재자 역할이 양국 지도부를 더 가깝게 만들었다. 러시아에서는 드미트리 메드베데프 국가안보회의 부의장이 참석했고 중국은 최고 입법기관인 전국인민대표대회(전인대) 상무위원회의 허웨이 부위원장이 장례식에 참석했다. 알 자지라에 따르면 에모말리 라흐몬 타지키스탄 대통령, 나콜 파시냔 아르메니아 총리, 미하일 카벨라슈빌리 조지아 대통령도 장례식에 참석할 것이라고 확인했다. 중국 외교부에 따르면 허웨이 부위원장은 이란 테헤란에서 열린 하메네이 장례식에 중국 정부 대표로 참석해 마수드 페제시키안 이란 대통령과 모하마드 바게르 갈리바프 국회의장을 각각 만나 중국 정부의 조의를 전했다. 그는 "중국은 하메네이 최고지도자의 불행한 서거에 깊은 애도를 표하며 이란 정부와 국민, 유가족에게 진심 어린 위로를 전한다"며 "모즈타바 최고지도자의 지도 아래 이란이 하루빨리 안보와 안정을 회복하고 발전하기를 바란다"고 말했다. 허웨이 부위원장은 "수교 55년 동안 중국과 이란 관계는 안정적이고 건전하게 발전해 왔다"며 "대이란 관계를 발전시키려는 중국의 의지는 확고하며 양국 관계의 방향도 변하지 않을 것"이라고 강조했다. 팔레스타인 무장정파 하마스와 레바논 친이란 무장정파 헤즈볼라 조문단도 이날 테헤란에 도착했다. 아야톨라 하메네이의 장례식에는 역내에서 치명적인 갈등을 벌이고 있는, 완전한 적대 관계까지는 아니더라도 서로 반대 입장에 선 이들을 한자리에 모였다. 이란 관영 매체에 따르면 네치르반 바르자니 이라크 쿠르드 자치정부 수반은 지난 금요일 이란 관료들과 만났다. 쿠르드 자치정부는 이란의 망명 쿠르드 무장단체들을 수용하고 있으며, 이들은 이란 이슬람혁명수비대(IRGC)와 선전포고 없는 그림자 전쟁을 이어가고 있다. 니자르 아메디 이라크 대통령과 하이바트 알할부시 이라크 하원의장도 장례식에 참석했다. 이라크 관료들의 이번 방문은 이란과의 관계를 멀리하라는 압박을 점점 더 강하게 받고 있는 이라크 신임 정부에 다소 곤혹스러운 시점에 이루어졌다. 이란 테헤란에서 열릴 아야톨라 알리 하메네이 최고지도자의 장례식을 앞두고, 혁명광장에 그의 ''주먹''을 형상화한 동상이 세워져 있다. 붉고 검은 배경 위에 하메네이가 저항하듯 주먹을 움켜쥔 모습을 그린 동상은 이번 장례식의 상징적인 이미지가 되었다. 아랍계 언론 알 자지라는 "그가 사망한 이후 정부 선전에 광범위하게 활용되고 있디"며, "이는 최고지도자 자리에 오른 이후 공식 석상에 모습을 드러내거나 목소리를 내지 않고 있는 모즈타바 하메네이가 보낸 것으로 알려진 한 성명에 뿌리를 두고 있다"고 분석했다. 알 자지라에 따르면 최고국가안보회의 사무총장 알리 라리자니가 암살당하기 직전인 3월 12일에 공개한 문자 성명틀 통해 "(하메네이 최고지도자의) 성한 왼손 주먹이 단단히 쥐어졌다는 소식을 들었다"고 전했다. 아야톨라 알리 하메네이는 1981년 폭탄 암살 기도 사건 당시 심각한 파편상과 화상을 입어 오른팔을 쓰지 못하게 되었다. 검은색과 붉은색의 사용은 슬픔, 순교, 그리고 보복의 촉구라는 개념을 결합한 것으로 알려졌다. 최고국가안보위원회는 일요일 오후 성명을 통해 "최고지도자의 장례 행렬을 배웅하고 동행하며 요동치고 있는 이 인파는 두 가지 상징, 즉 ''적들에 대한 저항''과 ''순교한 이란 지도자의 피에 대한 보복''을 외치고 있다"고 밝혔다. 지난 토요일 시작된 장례식에서 추모객들은 테헤란에서 국기로 감싸인 관이 들어찬 유리 상자 앞에서 슬픔에 겨워 가슴을 치며, 이스라엘과 미국을 향한 보복을 촉구했다. 추모객인 마수메 모하마디는 아랍계 언론 알 자지라에 "이맘 하메네이는 우리의 심장이자 아버지였고, 우리의 모든 것이었다"며 "그들이 그를 순교하게 만들었다는 사실이 아직도 믿기지 않는다. 그의 죽음을 보복할 때까지 우리는 쉬지 않을 것"이라고 말했다. 추모객들은 "미국에 죽음을!" "이스라엘에 신의 저주가 내리기를!"이라고 외쳤다. 광장 곳곳에는 하메네이의 대형 사진이 내걸렸고, 그 옆으로는 살벌한 문구의 현수막이 함께 등장했다. "트럼프를 죽여라","피의 복수"라는 등의 문구가 적혔다. 한여름 무더위 속에서 자원봉사자들이 군중을 향해 시원한 물을 뿌렸고, 야외 가판대에서는 음식과 음료를 제공했다. 남성과 여성들은 금속 탐지기 검사와 몸수색을 거친 뒤 그랜드 모살라 내부로 따로따로 모여들었다. 소총으로 무장한 경찰들이 주변 거리에서 경계를 섰다. 도시 전체가 폐쇄됐다. 테헤란에서 약 530km 북서부 도시 타브리즈에서 온 알리 카제미는 "우리는 우리 나라와 종교를 수호하는 데 모두가 헌신하고 있음을 보여주기 위해 장례식에 참석했다"고 말했다. 이번 장례식은 현대사에서 가장 큰 규모의 국장 중 하나로 기록될 전망이다. 그 규모와 인파는 약 1,000만 명의 추모객이 몰렸던 1989년 전 최고지도자 아야톨라 루홀라 호메이니의 장례식을 넘어설 것으로 예상된다. 5일(현지시각) 이란 테헤란에서 열린 장례식 둘째 날에 조문객들이 이란의 살해된 최고지도자 아야톨라 알리 하메네이를 추모하기 위해 그랜드 모살라(대사원)에 모인 가운데, 한 남성이 미국 대통령에 대한 보복을 촉구하는 팻말을 들고 있다. 하메네이의 장례식은 테헤란에서의 사흘간의 애도 기간으로 시작되었으며, 이후 이란과 이라크의 여러 도시를 거치는 운구 행렬로 이어진다. 이 행렬에는 전 최고지도자의 삶과 시아파 이슬람 전반에 관한 짙은 상징성이 담겨 있다. 일주일간 이어지는 최고지도자 아야톨라 알리 하메네이의 장례 의식이 정부 지지 성향의 종교적·정치적 이야기를 전파하기 위해 짙은 상징성을 띠고 있다. 이란 당국은 세심하게 기획된 국가적 수사부터 조직적인 시위에 이르기까지, 1979년 혁명 이후 집권해 온 이란 정부 지지자들 사이의 결속력을 다지는 서사를 만들기 위해 전방위적인 말들을 쏟아내고 있다. 미국과 이스라엘의 수개월간 군사 공세에도 이란 체제가 무너지지 않았을 뿐 아니라 더욱 강경하고 자신감 있게 재편됐다고 미국 워싱턴포스트(WP)가 4일(현지시각) 보도했다. WP는 안보 당국자와 전문가들을 인용해, 최근 진행 중인 알리 하메네이 전 최고지도자의 장례 절차가 새로운 강경파 권력 체제의 출범을 상징한다고 보도했다. 새 권력의 중심에는 하메네이의 아들이자 후계자인 아야톨라 세예드 모즈타바 하메네이가 있다. 그는 부친이 사망한 공습 당시 부상을 입은 이후 공개 석상에 모습을 드러내지 않고 있다. 그러나 그를 보좌하는 새로운 권력층은 이전 세대보다 젊고 국가 권력기관 장악력이 뛰어난 것으로 평가된다고 WP는 전했다. 이는 이번 전쟁이 정권교체를 불렀고 이는 미국 요구를 수용할 실용주의 세력이 힘을 얻었다는 도널드 트럼프 미국 대통령의 주장과 배치된다고 WP는 지적했다. 이스라엘 국가안보연구소(INSS)의 이란 연구 책임자인 라즈 짐트는 "이란이 경제 상황이나 산업, 일부 전략적 능력 면에서는 약화했을지 모른다"라면서도 "결론적으로 우리는 지금 더 대담하고 자신감에 찬 새로운 이란을 마주하고 있다"고 분석했다. 권력 핵심에는 군과 정보기관 출신 강경파가 대거 포진했다. 최고국가안보회의 사무총장을 맡은 모하마드 바게르 졸가드르는 이슬람혁명수비대(IRGC) 출신이며, IRGC 총사령관에 오른 아흐마드 바히디는 2022년 여성 인권 시위 유혈 진압을 주도한 대표적 강경 인사다. 최고지도자의 군사 고문을 맡은 모흐센 레자이 역시 미국과 이스라엘에 대한 강경 대응을 지속적으로 주장해 온 인물이다. WP는 이번 전쟁을 통해 이란이 호르무즈 해협을 가장 강력한 전략적 지렛대로 재발견했다고 평가했다. 민간 정치인들은 권력 중심에서 밀려났다. 마수드 페제시키안 대통령과 아바스 아라그치 외무장관은 미국과 협상을 담당하면서 이란 외부 세상에 얼굴이 널리 알려진 인물들이지만, 이번 권력 재편 과정에서 영향력이 크게 약화한 것으로 전해졌다. 전문가들은 트럼프 대통령이 “이란 문명을 말살하겠다”고 위협한 것이 오히려 강경파에 ‘체제 생존’ 명분을 제공하면서 온건 세력의 입지를 약화시키는 결과를 낳았다고 분석했다. 모즈타바 아야톨라 알리 하메네이 장례식이 치러지는 테헤란의 그랜드 모살라(대사원) 외곽에 조문객들이 몰려든 가운데, 한 조문객이 이란의 최고지도자 모즈타바 하메네이의 모습이 그려진 현수막을 들고 있다. 모즈타바 하메네이는 부친의 장레식에 아직까지는 참석하지 않았다. 하메네이의 장례식 불참과 관련해 여러가지 억측이 제기되고 있다. 현재 이란 정권의 가장 시급한 과제는 부상당한 모즈타바가 최고지도자로서의 직무를 정상적으로 수행할 수 있는지 증명하는 것이다. 조지타운 대학교 카타르 캠퍼스의 폴 머스그레이브 부교수는 알 자지라 와의 인터뷰에서 "이란의 현 최고지도자가 부친의 장례식에 참석하지 않는 것은 이해할 수 있는 일"이라고 말했다. 그레이브 부교수는 "결국 이란은 이 지도자가 숨어 있는 최고지도자가 아니라, 실제로 국가를 이끄는 인물임을 보여줄 방법을 찾아야 할 것"이라며, "이란 당국이 정당한 안보적 우려를 가질 수 있겠지만, 조만간 대중 앞에 모습을 드러내는 일을 성사시켜야만 한다"고 말했다. 매일 밤 테헤란에서 열리는 집회에서는 모즈타바가 얼굴을 드러내거나 음성 녹음을 공개해야 한다는 주장이 나오고 있는 것으로 알려졌다. 모즈타파는 그동안 막후에서 주로 활동해 왔다. 이란 전쟁 초기, 미국과 이스라엘의 공습으로 1989년부터 집권해 온 부친 알리 하메네이가 사망한 직후 종신직인 최고지도자 자리에 임명되었을 때만 해도 이란 국민들은 이 젊은 하메네이에 대해 아는 바가 거의 없었다. 공습 당시 부상을 입은 것으로 알려진 모스타바 하메네이는 지도자 취임 이후 십여 차례 성명을 발표하며 미국과 이스라엘을 적대시하는 부친의 대립적 전략을 이어왔다. 최근 그가 개입한 가장 중요한 행보 중 하나는 지난 6월 18일 발표된 서한이었다. 그는 전쟁을 끝내기 위한 미국과의 회담에 대해 자신은 "다른 견해"를 가지고 있음에도 불구하고 이를 축복(승인)했다고 밝혔다. 이는 국내 정치적 공방에서 한 걸음 물러나 초연한 위치를 지키려는 시도로 해석된다고 AFP는 분석했다. 이러한 성명 발표와 사회관계망(SNS)을 통한 활동에도 불구하고, 지난 2월 28일 그의 아내 자하라 하다드 아델을 비롯한 하메네이 가문 구성원들의 목숨을 앗아간 공습 이후, 모스타바 하메네이가 실제로 생존해 있는지에 대한 구체적인 증거는 아직 확인되지 않았다. 뉴욕타임스(NYT)도 모즈타바가 공개석상에 모습을 드러내지 않아 이란 정치권 내부에서 분열이 커지고 그의 역할을 둘러싼 의문이 제기되고 있다고 전했다. NYT에 따르면 모즈타바가 장례식에 참석하고 싶다는 뜻을 전했으나 그의 신변 보호를 위해 보안 당국이 요청을 거부했다고 익명의 이란 관계자들은 전했다. 5일(현지시각) 이란 테헤란에서 열린 알리 하메네이의 장례식에 참석하기 위해 그랜드 모살라(대사원)로 향하던 한 여성이 이란의 현 최고지도자 모즈타바 하메네이(오른쪽)와 그의 전임자들인 아버지 알리 하메네이(왼쪽), 루홀라 호메이니(왼쪽에서 두 번째)의 초상화 앞을 지나가고 있다. 이미 최고지도자로서 모즈타바의 영향력이 약화했다는 징후도 있다. 모하마드 자파르 가엠파나흐 이란 부통령은 최근 모즈타바가 최종 결정권을 가진 것이 아니며 그의 의견이 다른 관리들처럼 논의되고 고려되어야 한다고 말해 강경파의 비판을 받기도 했다. 장례식이 끝난 후 모즈타바가 사법부, 국영 방송, IRGC 산하 바시즈 민병대, 자신의 비서실장 등 요직에 대한 인선을 시작하면서 이란 지도부의 향후 방향이 결정될 것이라는 전망이 나온다. 발리 나스르 미국 존스홉킨스대 교수는 “우리는 지금 현실적이고 긴장감 넘치는 정치적 상황과 국가의 미래를 둘러싼 권력 싸움을 목격하고 있다”며 “실용주의 세력이 우위를 점한다면 강경파는 주변부에 밀려날 것이며, 그들은 이에 맞서 싸우고 있다”고 말했다. 지금까지는 후속 협상을 이끄는 마수드 페제시키안 대통령, 모하마드 바게르 갈리바프 의회 의장, 모하마드 바게르 졸가드르 최고국가안보회의 사무총장과 이슬람혁명수비대(IRGC) 고위 장군 등 실용주의 세력이 의사 결정을 이끌고 있는 것으로 알려져 있다. 전직 미 중앙정보국(CIA) 관리 노먼 룰은 "최고지도자가 부친 장례식에 모습을 드러내지 않는다면 이란 국내외에서는 그의 건강 이상이나 권력 약화를 의심할 것"이라고 말했다. 그러나 익명을 요구한 이란 외교관은 미국이나 이스라엘의 암살 시도를 우려해 모즈타바가 공개 석상에 모습을 드러내지 않을 가능성이 크다고 전망했다. 전문가들은 모즈타바가 은신 중에도 핵심 전략 결정을 직접 내리고 있으며 미국과의 협상에서도 실질적인 최종 결정권을 행사하고 있다고 분석했다. 2일(현지시각) 이란 테헤란에서 미국-이스라엘의 공격에 따른 연기가 피어오르자 새들이 날아가고 있다. 1979년 이슬람 혁명 이후 이란이 최고지도자를 잃은 것은 이번이 두 번째다. 알리 하메네이는 1989년부터 사망한 초대 최고지도자 아야톨라 루홀라 호메이니의 뒤를 이어 2대 최고지도자로 선출돼 37년간 집권했다. 테헤란 전역에는 애도의 상징들이 확산되고 있다. 고가도로와 건물에는 거대한 검은 현수막이 걸렸고, 주요 도로와 교차로에는 아야톨라 하메네이의 초상화가 담긴 대형 광고판이 등장했다. 일부 광고판에는 오랫동안 이란의 정치 지형을 지배해 온 익숙한 공식적인 사진처럼 그가 홀로 밖을 응시하는 모습이 담겨 있었다. 다른 광고판에는 그의 아들이자 후계자인 모즈타바 하메네이와 함께 있는 모습이 담겨 있어, 한 시대의 종말과 또 다른 시대의 시작을 시각적으로 연결 지었다. 이란 정부는 아야톨라 하메네이를 세계적 위상을 지닌 경외받고 존경받는 지도자로 묘사하려 애쓰고 있지만, 많은 이란인은 막대한 비용이 드는 수일간의 장례식을 불만이나 분노의 시선으로 바라볼 수 있다. 아야톨라 하메네이는 37년이 넘는 독재 통치 기간 동안 반대파를 가혹하게 탄압했으며, 경제적 실정과 부패가 만연하도록 방치했다. 아야톨라 하메네이는 수십 년 동안 이란 정치계에 늘 존재하는 인물이었다. 그의 지지자 중 일부는 그의 죽음을 여전히 받아들이기 어렵다고 말했으며, 전국적으로 계획된 애도 기간은 슬픔을 나누고 한 정치 시대의 종말을 기념하는 자리가 되었다. 이번 장례식은 이란에 있어 특히 격동의 시기에 치러지고 있다. 지난 6개월간 시위, 지역 분쟁, 안보 긴장, 인터넷 차단 등이 일상을 뒤흔들고 광범위한 불확실성과 불안정을 초래하면서 이란 내부에는 깊은 균열이 생겼다. 수많은 이란인에게 수십 년간 군림했던 지도자의 죽음은 격변으로 표현할 수 있는 시기의 또 다른 전환점이다. 지난 금요일 테헤란 중심가에서 10개월 된 아들 알리와 함께 있던 두냐 모하마디(24세)는 NYT에 "그가 세상을 떠났다는 게 아직도 믿기지 않는다"고 말했다. 그녀는 의식에 참석하기 위해 수도에서 서쪽으로 약 24마일(약 38km) 떨어진 말라르드에서 가족과 함께 이동해 왔다고 밝혔다. 그녀는 "내 마음이 허락하는 한 최선을 다해 애도하고 싶다"고 덧붙였다. 뉴욕타임스(NYT)는 이란 정부의 허가를 받아 아야톨라 하메네이의 장례 의식을 취재했다고 전했다. 이란 당국은 NYT기자들이 참석할 수 있는 의식을 지정했으며, 정부가 제공한 통역사와 안내원이 동행했다. NYT는 이러한 행사에서 인터뷰에 응한 이들의 의견은 대다수 이란인의 생각을 대변하지 않을 수 있으며, 일부는 자유롭게 말할 수 없다고 느꼈을 가능성도 있다고 전했다. 9일(현지시각) 사회관계망(SNS)에 공개된 화면. 이란 수도 테헤란의 시위대가 차량을 불태우고 있다. 이란 지도부는 하메네이의 장례식을 이란 국민들의 헌신적인 지지를 보여주는 증거로 부각시키려는 대대적인 선전 활동으로 활용하고 있다. 미국의 주요 방송사를 비롯한 서방 언론에는 장례 의식 취재를 위한 이란 방문 특별 허가가 내려진 반면, 공식 애도 의식에 참석하기 위해 콤, 나자프, 카르발라 같은 주요 도시에 도착하는 이란인 조문객들에게는 무료 숙식의 혜택이 제공되고 있다. 이란 군은 올해 초 발생했던 반정부 시위가 재개되는 것을 막기 위해 총력을 기울이고 있다. 당시 정권의 후속 진압 과정에서 3만 명 이상의 이란 민간인이 사망한 것으로 알려졌다. 아무 일도 없다는 듯한 상징을 보여주려는 정권의 노력에도 불구하고, 미국과 이스라엘의 합동 군사 공세 동안 이란의 군사력과 경제적 생존 능력이 초토화되는 피해를 입었다는 사실은 변함이 없다. 영국의 텔레그래프는 지난 4달은 정권을 강화하기는커녕 이슬람 공화국이 권력을 유지할 능력이 있는지에 대한 심각한 의문을 제기했으며, 동시에 재앙적인 좌절 이후 나라를 재건하는 가장 좋은 방법을 두고 고위 지도부 내의 분열을 악화시켰다고 분석했다. 이란 정권은 앞으로 며칠 동안 치러질 하메네이의 장례식에서 쏟아져 나올 대중적 지지가 자신들이 그 어느 때보다 강하다는 것을 입증한다고 외부 세계가 믿기를 바라고 있다. 텔레그래프는 그러나 현실은 이란 통치지도부 핵심 내부에서 깊은 균열이 나타나기 시작했으며, 이것이 궁극적으로 이슬람 공화국의 종말을 초래할 수도 있다는 우려도 나오고 있다고 전했다. 미국과 이스라엘은 지난 2월 28일 공습에서 아야톨라 하메네이를 비롯한 이란 정권의 지도부 대다수를 제거했다. 아야톨라 하메네이의 장례식은 중대한 기로의 시작이다. 기존의 구세대가 물러나고 완전히 새로운 세대가 정권을 잡았음을 대대적으로 상기시켜 주는 순간이다. 새로운 인물들의 등장과 함께, 그들만의 파급력을 지닌 새로운 접근 방식이 찾아오고 있다. 이슬람 공화국은 여전히 건재하다. 여기에는 세계에서 가장 중요한 수로 중 하나인 호르무즈 해협을 봉쇄해 세계 경제의 숨통을 틀어쥘 수 있었던 이란의 역량이 부분적으로 기여했다. 지금의 이란은 그 어느 때보다 이슬람혁명수비대(IRGC) 지도부들에 의해 움직이고 있는 반면, 지난 1월의 피비린내 나는 진압으로 수천 명의 친구를 잃고 여전히 슬퍼하고 있는 수많은 고학력 청년들은 국가의 미래를 결정하는 데 자신들의 목소리가 전혀 반영되지 않는다고 느끼고 있다. BBC는 올해 대규모 격변을 겪은 지금의 이란이 국내외적으로 구질서와 미래의 가능성 사이에서 위태롭게 균형을 잡고 있는 전환점(Inflection point)이라고 분석했다.', 'crawl', '여성신문', '2026-07-06 11:17:25', '진보', 'ready', 'https://cdn.womennews.co.kr/news/photo/202607/279610_450626_914.jpg', '2026-07-07 06:04:43', '2026-07-07 18:35:46.837932', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4161, 'https://www.womennews.co.kr/rss/S1N3.xml', NULL, 'https://www.womennews.co.kr/news/articleView.html?idxno=279573', '국제', '이란, 하메네이 전 최고지도자 장례식 시작...100개국 대표 조문', '미국과 이스라엘의 공습으로 사망한 이란의 2대 최고지도자 아야톨라 알리 하메네이의 장례 절차가 사망 약 4개월 만에 시작됐다.이란은 4일(현지시각) 하메네이의 장례식 절차를 시작했다. 장례식은 장례식은 전쟁이 시작된 2월28일 미국·이스라엘의 공습에 사망한 지 126일 만에이다. 일주일간 수도 테헤란, 시아파 성지 마슈하드 등에서 열린다.아야톨라 하메네이의 시신은 전날 테헤란 시내 대형 예배장소인 이맘호메이니 대(大)모살라로 운구됐고 외교 사절의 조문을 받았다. 이란 국영방송은 단상에 놓인 그와 딸, 사위, 손녀 등 함께 폭사한 가', '3일(현지시각) 드미트리 메드베데프 러시아 안보리 부의장이 이맘 호메이니 모살라(대사원)에서 열린 알리 하메네이 전 최고지도자를 조문하고 있다. ⓒ타스 연합뉴스 미국과 이스라엘의 공습으로 사망한 이란의 2대 최고지도자 아야톨라 알리 하메네이의 장례 절차가 사망 약 4개월 만에 시작됐다. 이란은 4일(현지시각) 하메네이의 장례식 절차를 시작했다. 장례식은 장례식은 전쟁이 시작된 2월28일 미국·이스라엘의 공습에 사망한 지 126일 만에이다. 일주일간 수도 테헤란, 시아파 성지 마슈하드 등에서 열린다. 아야톨라 하메네이의 시신은 전날 테헤란 시내 대형 예배장소인 이맘호메이니 대(大)모살라로 운구됐고 외교 사절의 조문을 받았다. 이란 국영방송은 단상에 놓인 그와 딸, 사위, 손녀 등 함께 폭사한 가족의 관을 보고 울부짖는 시민들의 모습을 방영했다. AP통신은 테헤란 전역에는 86세 성직자의 목숨을 앗아간 파괴적인 전쟁 이후, 이슬람 공화국을 지지하기 위해 대중의 결집을 촉구하는 현수막들이 내걸렸다고 전했다. 본격적인 장례식은 4일부터 시작된다. 이날부터 이틀간 일반 시민들이 테헤란 모살라에 안치된 그의 관 앞을 지나며 추모하는 방식으로 조문한다. 6일에는 이란 중부 종교도시 곰으로 옮겨 조문 행사를 이어가고, 7일에는 이라크의 시아파 성지 카르발라를 비롯해 바그다드, 나자프에서 장례식이 엄수된다. AP는 수백만명이 수도 테헤란에서 수백만 명이 참여할 것으로 예상하고 있다고 보도했다. 전국에서 1천만명 이상이 참여할 것으로 당국은 예상했다. 이란 북동부의 시아파 성지이자 아야톨라 하메네이의 고향이 마슈하드의 이맘 레자 성지에서 9일 열리는 매장 행사로 장례 일정이 모두 마무리된다. 3일(현지시각) 셰바즈 샤리프 총리(오른쪽에서 두 번째)와 사이드 아심 무니르 육군참모총장(오른쪽)이 이맘 호메이니 모살라(대사원)에서 열린 알리 하메네이 전 최고지도자를 조문하고 있다. ⓒUPI 연합뉴스 1989년 6월에 치러진 초대 최고지도자 아야톨라 루홀라 호메이니의 장례식 당시 테헤란에 1천만명이 모였다. 테헤란시는 조문객들을 위해 빵 5천만개를 준비했으며, 수도권 내 모스크 5천여곳과 학교 700곳을 숙소로 개방했다. 이 기간 테헤란 시내 상점은 강제 휴업한다. 이란 당국은 이번 장례식의 구호를 ''반드시 일어서리라''로 정했다. 장례식을 미국과 이스라엘에 대한 복수를 다짐하는 계기로 삼아 전쟁으로 혼란해진 민심을 결속하겠다는 의도로 풀이된다. 후계자인 아야톨라 모즈타바 하메네이는 지난 3월 최고지도자로 선출된 이후 공식 석상에 모습을 드러내지 않았으며, 이번 장례 행사 참석 여부도 아직 공개되지 않았다. 장례식에 참석하기 위해 약 100개국에서 200명의 고위급 조문단이 이란을 방문한다. 이란과 미국의 종전 협상을 중재하고 있는 파키스탄에서는 국가 정상인 셰바즈 샤리프 총리가 직접 조문하기로 했다. 중국은 최고 입법기관인 전국인민대표대회(전인대) 상무위원회의 허웨이 부위원장이 장례식에 참석한다. 러시아에서는 드미트리 메드베데프 국가안보회의 부의장이 참석했고, 중국은 허웨이 전국인민대표대회 부위원장을 파견했다. 3일(현지시각) 이란 테헤란에서 거행된 고(故) 알리 하메네이 이란 최고지도자의 장례식에서 추모 인파가 그의 관 주위로 모여들고 있다. ⓒUPI 연합뉴스 파키스탄의 셰바즈 샤리프 총리와 사이드 아심 무니르 육군참모총장도 참석했다. 이란 국영 ISNA 통신에 따르면무니르는 테헤란에서 추모식에 참석한 뒤, 이란 외무장관 아바스 아라그치를 만났다. 이라크와 파키스탄, 아프가니스탄 등 시아파 및 역내 국가 관계자들이 대거 참석했으며, 이라크 내 친이란 민병대와 레바논 헤즈볼라 관계자들도 모습을 드러냈다. 이란과 갈등 관계에 있는 세력들과 연결된 인사들까지 한자리에 모이면서 이번 장례식은 중동 역학 구도를 보여주는 상징적인 외교 무대로도 주목받고 있다. 이란 정부는 외신 기자도 600명 초청했다. 장례식이 시작되는 7월4일이 미국 독립 250주년 기념일이다. 이란 당국은 지난달 25일 아슈라(이맘 후세인의 순교 추모일)에서 아르바인(아슈라 뒤 40일째)으로 이어지는 성스러운 기간에 장례식 일정을 맞춘 것이라고 설명했다. 아야톨라 하메네이의 사망을 시아파 무슬림이 가장 숭모하는 이맘 후세인의 비극적 죽음에 투영해 그가 이교도(미국과 이스라엘을 비롯한 서방 기독교 진영)에 맞선 성전의 순교자가 됐다는 종교적 서사를 구현하려는 의도로 보인다.', 'crawl', '여성신문', '2026-07-04 07:09:02', '진보', 'ready', 'https://cdn.womennews.co.kr/news/photo/202607/279573_450576_214.png', '2026-07-07 06:04:43', '2026-07-07 18:35:58.475644', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4179, 'https://www.womennews.co.kr/rss/S1N4.xml', NULL, 'https://www.womennews.co.kr/news/articleView.html?idxno=279539', '경제', '법원, 홈플러스 회생절차 폐지... 인수자 못찾아 파산 수순', '대형마트 홈플러스가 인수자를 찾지 못해 돌파구가 없는 이상 파산 수순을 밟게 됐다.서울회생법원 회생4부(법원장 정준영, 주심 박소영 부장판사)는 3일 홈플러스의 기업회생절차(법정관리) 폐지를 결정했다법원은 홈플러스가 지난달 30일 제출한 수정 회생계획안 변경안의 수행 가능성이 없다고 판단했다.재판부는 "이 상황에서 회생계획안을 수행하려면 최소 약 2천억원이 필요함에도 현재까지 조달되지 않았다"며 "회생계획안의 수행 가능성이 없으므로 관계인집회의 심의·결의에 부치지 않고 회생절차를 폐지했다"고 밝혔다.홈플러스는 지난해 12월 29일과', '홈플러스 ⓒ연합뉴스 대형마트 홈플러스가 인수자를 찾지 못해 돌파구가 없는 이상 파산 수순을 밟게 됐다. 서울회생법원 회생4부(법원장 정준영, 주심 박소영 부장판사)는 3일 홈플러스의 기업회생절차(법정관리) 폐지를 결정했다 법원은 홈플러스가 지난달 30일 제출한 수정 회생계획안 변경안의 수행 가능성이 없다고 판단했다. 재판부는 "이 상황에서 회생계획안을 수행하려면 최소 약 2천억원이 필요함에도 현재까지 조달되지 않았다"며 "회생계획안의 수행 가능성이 없으므로 관계인집회의 심의·결의에 부치지 않고 회생절차를 폐지했다"고 밝혔다. 홈플러스는 지난해 12월 29일과 지난달 30일 두 차례에 걸쳐 구조혁신형 회생계획안과 재수정안을 제출했다. 계획안에는 수익성이 낮은 점포를 정리하고 영업양도와 인수합병(M&A)을 추진하는 내용이 담겼다. 재판부는 "홈플러스 익스프레스 사업 부문 매각이 성사됐으나 잔존 사업부에 대한 인수·합병이 이뤄지지 않은 채 영업을 지속하는 과정에서 매출이 감소하는 반면 급여, 물품대금 채무, 조세 등 공익채권이 급증하는 상황"이라고 설명했다. 공익채권은 회생절차 중인 기업에서 일반 회생채권이나 회생담보권보다 우선해 변제받는 청구권을 뜻한다. 홈플러스는 이번 결정에 대해 14일 이내에 즉시항고할 수 있다. 홈플러스가 자금을 조달해 기한 내 즉시항고할 경우 재판부가 회생절차 폐지 결정을 취소할 가능성이 열려 있다. 즉시항고를 제기하지 않으면 폐지 결정이 확정된다. 기업회생절차는 경영 위기를 겪는 기업을 청산할 때의 가치(청산가치)보다 유지할 때의 가치(존속가치)가 더 크다고 인정되는 경우 법원의 관리를 받아 회생시키는 제도다. 기업회생절차에 따른 회생 계획을 수행할 수 없어 절차가 폐지된 경우 채무자 기업이 밟을 수 있는 선택지는 사실상 파산뿐이다. 폐지 결정 이후 회생절차를 다시 신청하는 재도의(재신청)도 가능하지만, 특별한 사정 변경이 없는 한 받아들여질 가능성이 작다. 홈플러스는 작년 3월 4일 회생을 신청해 당일 회생절차 개시 결정이 내려졌다. 법원은 당시 홈플러스의 청산가치가 계속기업가치보다 크다고 판단해 영업 전부 혹은 일부를 양도하는 내용의 ''구조혁신형 회생계획안''을 허가했다. 채무자회생법에 따라 법원은 회생계획안 가결 기한을 오는 9월까지 연장할 수 있으나, 재판부는 그 실효가 없다고 보고 회생절차를 중단한 것으로 해석된다.', 'crawl', '여성신문', '2026-07-03 13:17:01', '진보', 'ready', 'https://cdn.womennews.co.kr/news/photo/202607/279539_450531_017.jpg', '2026-07-07 06:04:43', '2026-07-07 18:36:34.326383', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4211, 'https://www.pressian.com/api/v3/site/rss/section/65', NULL, 'https://www.pressian.com/pages/articles/2026062817500288269&ref=rss', '정치', '베네수엘라 지진 사망자 1430명으로 늘어hellip;실종자 무려 7만명', '베네수엘라를 강타한 연쇄 강진이 발생한 지 나흘째로 접어들며 인명 구조의 분수령으로 여겨지는 72시간 ''골든타임''이 지나갔다. 일부 지역에서는 극적인 생환 소식도 전해지고 있다. 하지만 시간이 흐를수록 사망자와 실종자 수가 크게 늘어나면서 현장의 슬픔과 절망도 깊어지는 상황이다. 여기에 피해 집중 지역에서는 베네수엘라 정부의 구조 활동이 제대로 이뤄지지', '베네수엘라를 강타한 연쇄 강진이 발생한 지 나흘째로 접어들며 인명 구조의 분수령으로 여겨지는 72시간 ''골든타임''이 지나갔다. 일부 지역에서는 극적인 생환 소식도 전해지고 있다. 하지만 시간이 흐를수록 사망자와 실종자 수가 크게 늘어나면서 현장의 슬픔과 절망도 깊어지는 상황이다. 여기에 피해 집중 지역에서는 베네수엘라 정부의 구조 활동이 제대로 이뤄지지 않고 있고, 각종 지원마저 턱없이 부족해 이번 지진으로 인한 피해는 걷잡을 수 없이 커질 것으로 우려된다. 사망자 1400명 넘어서…비공식 실종자 신고 7만 명 육박 27일(현지시간) <AP>통신 등에 따르면 호르헤 로드리게스 베네수엘라 국회의장은 지난 24일 연쇄 강진으로 인한 사망자가 이날까지 1430명으로 집계됐다고 밝혔다. 이는 전날 집계된 920명에서 하루 만에 500명 넘게 급증한 수치다. 비공식 실종 집계도 급격히 늘어나고 있다. 이날 오전 기준 민간 웹사이트에 신고된 실종자 수는 최소 6만8900명에 달했다. 다만, 이는 정부 당국이 공식 확인한 수치가 아닌 민간 사이트의 자체 집계 결과라고 외신들은 전했다. 기적적 생환에 환호…여진 공포에 구조 작업은 지연 전문가들이 사고 후 생존 가능성이 가장 높다고 판단하는 ''골든타임''(사고 발생 후 48∼72시간)은 이미 지났다. 한국 시간 28일 오전 8시를 기준으로 지진 발생 후 72시간이 지나면서 현장의 초조함은 극에 달한 상황이다. 그래도 일부 지역에서는 기적적인 생환 소식이 전해지며 주민들은 실낱같은 희망을 이어갔다. 미 CNN 방송에 따르면 엘살바도르 구조대원들은 라과이라주(州)에서 무너진 건물 잔해 속에 갇혀 있던 15세 소녀와 반려견을 무사히 구조했다. 다행히 건강한 상태로 구조된 소녀는 구조대원들을 향해 ''손 하트''를 만들어 보이며 감사 인사를 전했다. 나이브 부켈레 엘살바도르 대통령은 엑스(X·옛 트위터)에서 직접 구조 소식을 공유했다. 현지에 파견된 스페인 긴급 구조대도 약 72시간 동안 건물 잔해 아래 깔려 있던 여성을 구조해냈다. 현장 영상에서 흙먼지를 뒤집어쓴 여성이 마침내 잔해 밖으로 모습을 드러내자 구조대원들은 일제히 환호성을 질렀다. 또 다른 영상에는 한 베네수엘라 구조대원이 잔해에 깔린 채 추가 붕괴의 공포에 떨고 있는 노인을 안심시키는 모습이 담겼다. 이 구조대원은 노인을 향해 "지붕은 절대 무너지지 않을 것이며, 만약 무너지더라도 내가 여기 끝까지 함께 있겠다"고 말했다. 그러나 지진 피해 지역에 여진이 이어지며 구조 작업은 난항을 겪는 것으로 전해졌다. 로이스 페이스 미국 적십자사 미주지역 국장은 CNN 인터뷰에서 "엄청난 피해에 더해 여진이 끊이지 않으면서 지역사회는 물론, 구조에 나선 자원봉사자 사이에도 극심한 불안감이 만연해 있다"고 전했다. 심각한 교통 체증과 당국의 통제 역시 구조 현장 진입을 가로막고 있다. 베네수엘라 정부는 공식 허가증을 보유한 사람만 현장에 진입할 수 있도록 허가하겠다는 방침인데, 허가증 발급 절차가 지연되면서 오히려 작업에 차질을 주고 있다는 것이다. 한 자원봉사자는 <AFP> 통신과의 인터뷰에서 "사람들을 구조하러 가기 위해 새벽부터 줄을 서서 계속 기다리고만 있다"며 답답함을 호소했고, 또 다른 봉사자는 "생명을 구하는 데 허가증이 필요하냐"며 목소리를 높였다. "정부는 어디 있나" 분노한 주민들…약탈 등 무법천지 혼란도 베네수엘라 정부의 미흡한 대응에 주민들의 분노도 이어지고 있다. 정부는 피해가 집중된 라과이라주에 군 병력을 투입해 대응에 나섰다. 그러나 정작 재난 지역 주민들은 "정부 관계자의 얼굴조차 보기 힘들다"며 분통을 터뜨리는 모습이다. 라과이라주 카라바예다 지역에서 구조를 돕던 주민 밀레이디 로메로는 AP와의 인터뷰에서 "정부는 잔해 아래 살아있는 사람들을 구조하려 하지도 않았고, 우리가 여러 시신의 위치를 찾아냈는데도 수습조차 돕지 않았다"며 "그들은 대체 무엇을 기다리고 있는 것이냐"고 말했다. 이번 지진으로 딸과 사위를 한꺼번에 잃은 한 어머니는 "우리는 맨손으로 직접 아이들의 시신을 끌어내야 했고, 도움은 전혀 오지 않았다"고 AFP에 말했다. 일부 현장에서는 분노한 주민들과 정부 관계자 간에 충돌까지 벌어졌다. AP는 굴착기를 몰고 온 관계자들이 현장에서 ''셀카''만 찍은 뒤 철수하려 하자, 현지 주민들이 운전사를 끌어내리고 차량을 가로막았다고 전했다. 동시에 치안 시스템도 붕괴하며 일부 상점과 가옥에서는 약탈이 이어지고 있다고 멕시코 일간 라호르나다 등이 보도했다. 국제사회 구호 손길 잇달아…美, 추가 재정 지원 예고 국제사회는 전방위적 구호 지원에 나섰다. 미국·멕시코·엘살바도르·스위스·콜롬비아·스페인·에콰도르·칠레·도미니카공화국·파나마 등 각국에서 모인 구조대원 1600명은 이날 베네수엘라 현지에 도착해 수색 및 구조 활동에 돌입했다. 베네수엘라 최대 공항인 시몬 볼리바르 국제공항이 부분 운영을 재개하면서 본격적 구조 지원이 가능해진 것이다. 당초 볼리바르 국제공항은 강진의 여파로 활주로가 심각하게 손상된 것으로 알려졌으나, 이날 현재는 활주로 한 곳이 열린 상태라고 미 국무부 관계자가 기자들에게 전했다. 베네수엘라 정부는 구조대원들이 항공편 17편으로 나뉘어 도착했으며, 향후 24시간 이내에 추가 항공편 25편이 도착할 예정이라고 밝혔다. 미국은 1억5000만달러(약 2317억 원) 규모 원조를 발표한 데 이어 추가 재정지원도 검토 중인 것으로 알려졌다. 미 정부 고위 관계자는 "수억 달러 규모의 자금 지원 패키지가 곧 발표될 것으로 예상한다"고 로이터통신에 말했다. 이와 함께 의료 공백을 메우기 위한 이동식 병원과 스페이스X의 위성 인터넷 서비스 ''스타링크'' 등 맞춤형 구호 장비도 현장에 투입됐다. 지진 피해 지역 인프라 복구도 제한적으로나마 진전을 보인다. 베네수엘라 당국은 라과이라주 전력 공급 약 60%를 복구했다고 발표했으며, 대통령실은 실종자 신고와 긴급 지원 요청을 일원화하는 지진 전용 신고 전화를 개설했다고 밝혔다. 경제적 피해 GDP 6% 규모…장기화 국면 접어든 재건 과제 그러나 이번 지진이 남긴 타격은 여전히 재앙적인 수준인 것으로 나타났다. 유엔개발계획(UNDP)은 전날 성명에서 이번 지진에 따른 물리적 손실 규모가 67억 달러(약 10조3000억 원)로 추산된다고 밝혔다. 이는 베네수엘라 국내총생산(GDP)의 6%에 달하는 규모다. 엘리너 레이크스 국제구호위원회(IRC) 부사장은 <로이터>과의 인터뷰에서 "베네수엘라 지진 대응은 장기적인 과제가 될 것"이라고 말했다. ⓒAFP=연합뉴스', 'crawl', '프레시안', '2026-06-28 17:50:14', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/06/28/2026062618072601500_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:38:32.533526', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4214, 'https://www.pressian.com/api/v3/site/rss/section/66', NULL, 'https://www.pressian.com/pages/articles/2026070711173695590&ref=rss', '정치', '민주당 quot;''보완수사권 완전 폐지'' 착수hellip;최대한 신속하게 추진quot;', '한병도 더불어민주당 당대표 직무대행 겸 원내대표가 "보완수사권 완전 폐지는 민주당의 확고부동한 원칙이며 당내 이견은 없다"며 "특정 시기를 고려하지 않고 신속하게 마무리하겠다"고 밝혔다. 한 대행은 7일 오전 국회에서 열린 당 원내대책회의 모두발언에서 이같이 말하며 "형사소송법 개정 또한 이 명확한 원칙과 기준에 따라 흔들림 없이 수행할 것"이라고 말했다', '한병도 더불어민주당 당대표 직무대행 겸 원내대표가 "보완수사권 완전 폐지는 민주당의 확고부동한 원칙이며 당내 이견은 없다"며 "특정 시기를 고려하지 않고 신속하게 마무리하겠다"고 밝혔다. 한 대행은 7일 오전 국회에서 열린 당 원내대책회의 모두발언에서 이같이 말하며 "형사소송법 개정 또한 이 명확한 원칙과 기준에 따라 흔들림 없이 수행할 것"이라고 말했다. 한 대행은 "이미 원내정책수석, 정책위 부의장, 법사위 간사와 행안위 간사가 참여하는 형사소송법개정TF를 중심으로 성안 작업에 착수했다"며 "이번 주 내 형소법 개정안 발의를 목표로 밀도 높고 내실 있느 논의에 속도를 높이겠다"고 했다. 한 대행은 특히 형소법 개정 시기와 관련해 "개정안 처리가 제헌절 전이냐, 전당대회 전이냐 이야기가 있는데, 특정 시기를 고려하지 않고 신속하게 마무리하겠다"고 강조했다. 그는 "충분한 숙의와 토론을 거치되 빠른 시일 내에 통과시켜서 오는 10월 공소청, 중대범죄수사청 출범에 차질이 없도록 할 것"이라며 "민주당은 좌고우면하지 않겠다"고 덧붙였다. 한 대행은 이재명 대통령이 전날 속도전을 강조한 3대 메가프로젝트와 관련해선 "이번 프로젝트는 대한민국 국토의 균형발전과 국가 생존을 위한 대전환점을 만드는 일"이라며 "민주당도 조속히 특위를 꾸려 입법과 예산을 확실하게 지원하겠다"고 했다. 한 대행은 "지금 승패를 가르는 것은 속도"라며 "이 대통령께서 말씀하셨듯 ''불법이 아닌 한 모든 행정절차를 동시 병행하여 투자 집행이 지연되는 일이 원천적으로 없도록 차단해야'' 한다"고 강조했다. 그는 그러면서 상임위원회 참석을 거부하고 있는 국민의힘을 향해 "민생 보이콧"이라며 "엄중히 경고한다. 일하라. 국민이 부여한 국회의원의 의무를 다할 것을 촉구한다"고 비판했다. 한 대행은 "국민의힘의 반대로 본회의 문턱에서 잠들어 있는 법안이 59건에 달한다"며 "국민의힘의 태업으로 국민 삶까지 멈춰서서는 안 된다다. 오는 9일 민생법안 처리를 위한 본회의 개최가 필요하다"고 주장했다. 한 대행을 포함한 민주당 원내대표단은 이날 회의 직후엔 조정식 국회의장을 찾아 오는 9일 민생법안 처리를 위한 본회의 개최를 요청했다. 조 의장은 법안처리 지연 상황에 대해 공감을 표하면서도 "여야 간의 최종 협의를 좀 더 해 달라"고 당부한 것으로 전해졌다. ▲더불어민주당 한병도 당 대표 직무대행 및 원내대표가 7일 국회에서 열린 원내대책회의에서 발언하고 있다. ⓒ연합뉴스', 'crawl', '프레시안', '2026-07-07 12:57:34', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/07/2026070711171247495_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:38:40.066383', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4216, 'https://www.pressian.com/api/v3/site/rss/section/66', NULL, 'https://www.pressian.com/pages/articles/2026070711231447483&ref=rss', '정치', '[속보] 경찰, ''음료 테러 자작극'' 의혹 개혁신당 정이한에 구속영장 신청', '6·3 지방선거 선거운동 기간 발생한 ‘음료컵 피습’ 사건의 자작극 의혹과 관련해 개혁신당 정이한 전 부산시장 후보에 대해 경찰이 구속영장을 신청했다. 부산 금정경찰서는 7일 정 전 후보에 대해 위계에 의한 공무집행방해와 공직선거법 위반 등의 혐의로 구속영장을 신청했다고 밝혔다. 정 전 후보에 대한 영장실질심사는 오는 8일 오후 2시에 열린다. 정 전', '6·3 지방선거 선거운동 기간 발생한 ‘음료컵 피습’ 사건의 자작극 의혹과 관련해 개혁신당 정이한 전 부산시장 후보에 대해 경찰이 구속영장을 신청했다. 부산 금정경찰서는 7일 정 전 후보에 대해 위계에 의한 공무집행방해와 공직선거법 위반 등의 혐의로 구속영장을 신청했다고 밝혔다. 정 전 후보에 대한 영장실질심사는 오는 8일 오후 2시에 열린다. 정 전', 'rss', '프레시안', '2026-07-07 11:23:14', '진보', 'crawl_failed', NULL, '2026-07-07 06:04:44', '2026-07-07 18:38:43.871309', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4224, 'https://www.pressian.com/api/v3/site/rss/section/66', NULL, 'https://www.pressian.com/pages/articles/2026070615083987835&ref=rss', '정치', '靑 quot;호남 반도체 산단, 광주 군공항 부지에 조성quot;', '정부가 ''3대 메가 프로젝트'' 일환으로 추진하는 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다. 강훈식 대통령비서실장은 6일 이재명 대통령이 주재한 민관합동 점검회의 결과를 전하며 "약 250만 평의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료된 만큼 부지 공사 기간을 최소화할 수 있는 장점이 있다"고 했다. 강 실장은 "기업', '정부가 ''3대 메가 프로젝트'' 일환으로 추진하는 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다. 강훈식 대통령비서실장은 6일 이재명 대통령이 주재한 민관합동 점검회의 결과를 전하며 "약 250만 평의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료된 만큼 부지 공사 기간을 최소화할 수 있는 장점이 있다"고 했다. 강 실장은 "기업들은 호남권 입지 후보지 중에 광주 군공항이 가장 적합한 지역이라는 의견을 제시했다"며 "광주 도심과 KTX역에 인접해 있어 인력 확보와 정주 여건 측면에서도 강점이 있으며 도로, 공항, 항만 등과 연계한 물류 접근성도 우수한 것으로 검토됐다"고 했다. 그러면서 "관계부처 협의를 거쳐 조속히 후보지 선정 절차를 마무리하고 산업단지 개발을 위한 후속 절차에 착수하겠다"고 했다. 그는 "광주 군공항을 비울 수 있는 방법을 다각적으로 검토할 것"이라며 "안보 공백이 발생하지 않는 범위 내에서 조기에 옮길 것"이라고 했다. 군공항이 국유지인 만큼 토지 수용이 용이하다는 점도 작용했다고 한다. 청와대가 호남권 반도체 클러스터 부지 선정을 서두른 배경은 지난주 삼성전자와 SK하이닉스 등의 투자계획 발표 이후 후보로 거론되는 지역의 부동산 시장이 이상 조짐을 보이고 있다는 판단에 따른 것이다. 강 실장은 "광주 지역 선정이 시급했던 이유는 부동산이 들썩인다는 보고도 있어 빨리 부지를 확정해야 불필요한 논란 확대를 막을 수 있다고 판단했다"고 밝혔다. 아울러 "어떤 부지냐에 따라 전력과 용수, 정주 여건 등 판단 기준이 달라진다"며 "부지를 먼저 확정해야 후속 인프라 계획도 구체화할 수 있다"고 했다. 이어 그는 용인 일반산단과 관련해서도 "기업들의 요청에 따라 당초 계획된 팹(반도체 생산시설) 10기 투자가 훨씬 빠른 속도로 추진될 수 있도록 토지 보상부터 전력, 용수 공급까지 전반적인 일정을 최대한 앞당기기로 했다"고 밝혔다. 그는 "용인 일반산단이 내년 가동을 시작하는 만큼 국가산단도 가동 일정을 최대한 앞당겨 글로벌 반도체 수요에 신속히 대응하겠다"고 했다. 아울러 "기업들은 전력과 용수 등 핵심 인프라뿐 아니라 우수 인력 확보 방안과 주거, 교통, 교육 등 정주 여건 개선에 대해서도 다양한 건의를 했고, 관계 장관들은 이를 지속 검토해 나가기로 했다"고 덧붙였다. 강 실장은 또 ''메가 프로젝트'' 전담 체계와 관련해선 "대통령이 청와대에 전담 기구를 두고 직접 챙기기로 한 만큼 중량감 있는 인사를 임명해 메가 프로젝트 전반에 대한 과제별 진도 점검과 부처 간 이견 조정 등을 총괄하게 한다는 데에 의견 모았다"고 했다. 이 대통령이 주재하는 민관합동 점검회의도 당분간 매달 개최키로 했다. 그는 "기업과 정부가 원팀이 되어야 한다"면서 "정부가 해야 할 일은 부지, 전력, 용수, 도로 등 인프라와 정주 여건, 산업 생태계를 선제적으로 만드는 것"이라고 했다. ▲강훈식 비서실장이 6일 청와대 춘추관에서 이날 오전 열린 메가프로젝트 민관합동 점검회의 결과 브리핑을 하고 있다. ⓒ연합뉴스', 'crawl', '프레시안', '2026-07-06 15:28:23', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/06/2026070615073205068_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:39:08.624455', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4228, 'https://www.pressian.com/api/v3/site/rss/section/66', NULL, 'https://www.pressian.com/pages/articles/2026070611064714671&ref=rss', '정치', '국민의힘 quot;선관위 특검, 수사대상 1호는 위철환hellip;''제3자 추천'' 반대quot;', '국민의힘은 6일 더불어민주당이 6.3 지방선거 투표용지 부족 사태 진상규명과 책임자 처벌을 위한 ''선관위 특검법''을 이번 주 발의한다고 예고한 것에 "침대 특검 작전"이라고 비난했다. 민주당이 여당, 야당이 아닌 제3자가 특검을 추천하도록 법안을 준비하는 데 대해 반발한 것이다. 국민의힘은 △자신들이 특검을 추천하고 △수사 범위를 무제한으로 두는 특검법을', '국민의힘은 6일 더불어민주당이 6.3 지방선거 투표용지 부족 사태 진상규명과 책임자 처벌을 위한 ''선관위 특검법''을 이번 주 발의한다고 예고한 것에 "침대 특검 작전"이라고 비난했다. 민주당이 여당, 야당이 아닌 제3자가 특검을 추천하도록 법안을 준비하는 데 대해 반발한 것이다. 국민의힘은 △자신들이 특검을 추천하고 △수사 범위를 무제한으로 두는 특검법을 수용하라고 민주당에 역제안했다. 장동혁 대표는 이날 국회에서 최고위원회의를 열고 "(민주당은) 그동안 국민의힘 배제 특검을 수없이 밀어붙인 것을 기억 못 하나"라며 "수사 범위도 이번 사태와 선거관리위원회 내부로 제한하겠다고 한다. 이야말로 진상규명을 거부하겠다는 무책임한 몽니"라고 지적했다. 장 대표는 "과거부터의 모든 진상을 규명하고, 선거 카르텔까지 뿌리뽑으려면 수사 범위 제한이야말로 어불성설"이라며 "국민이 바라는 특검은 야당 추천, 수사 범위 무제한"이라고 주장했다. 정점식 원내대표는 "특검 수사 대상에는 선관위뿐만 아니라 선거 지원 업무를 소관하는 행정안전부가 포함될 수밖에 없다. 아울러 특검 수사 대상 1호는 ''대통령의 밥 친구'' 위철환 중앙선관위원장 직무대행"이라며 "이해당사자 배제 원칙에 따라 민주당 특검 추천권은 당연히 배제돼야 한다"고 요구했다. 민주당 한병도 대표 직무대행 겸 원내대표가 특검은 특정 정당이 아닌 대한변호사협회 등 제3자의 추천이 ''더 현실적인 방안''이라고 제시한 것에 정 원내대표는 "느닷없다"며 "위 직무대행이 대한변협 회장 출신이라는 점에서 수용할 수 없다"고 못 박았다. 또 "노태악 대법관이 중앙선관위원장을 겸임했고, 현직 판사들이 시도, 시군구 선관위원장도 겸직하는 구조에서 대법원 추천 (특검) 방식도 검토할 가치가 없다"고 잘라 말했다. 그는 "깔끔하게 야당 추천 특검을 수용하라"고 촉구했다. 한편 오는 7일부터 온라인상 허위·조작 정보 유통을 막기 위한 개정 정보통신망법이 시행되는 가운데, 국민의힘 지도부는 "''입틀막법''의 시행"이라며 이날 회의 참석자 전원이 검은색 마스크를 쓰고 입장하면서 법안에 항의 표시를 했다. 장 대표는 "반중 언론 문 닫고 감옥 보낸 홍콩의 모습이 떠오른다. 국민의 눈을 가리고 귀를 막고 입까지 틀어막으면 그 끝은 바로 이재명 독재의 완성"이라고 비난했다. 그는 모두발언 이후 추가발언까지 나서 정보통신망법 비판에 상당 시간을 할애했는데, "언론은 이재명 독재의 마지막 침묵자가 되지 않길 간곡히 부탁한다"고도 주장했다. 정 원내대표는 "명백한 위법이고 희대의 악법"이라며 "시행을 즉시 유예하고 독소조항을 삭제하기 위한 재개정 논의에 착수하자"고 민주당에 제안했다. ▲국민의힘 장동혁 대표가 6일 국회에서 열린 최고위원회의에서 발언하고 있다. 왼쪽은 정점식 원내대표. ⓒ연합뉴스', 'crawl', '프레시안', '2026-07-06 11:59:59', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/06/2026070611004487598_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:39:16.62619', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4233, 'https://www.pressian.com/api/v3/site/rss/section/66', NULL, 'https://www.pressian.com/pages/articles/2026070522111527579&ref=rss', '정치', '이진숙 quot;스벅과 5.18 모욕이 무슨 관계? 생각에 수갑 채우는 나라는 어딘가quot;', '이진숙 국민의힘 의원이 "이재명 정권은 생각에도 ''수갑''을 채울 것인가"라고 강하게 비판했다. 이 의원은 5일 자신의 페이스북에 "배재고등학교에 화환을 보냈다. 화환 리본에는 ''스타벅스가 5.18과 무슨 관계가 있나'' ''배재고 학생들과 함께 합니다''라는 글귀가 적혀 있다"라며 이 같이 말했다. 그는 "스타벅스가 5.18 모욕과 무슨 관계가 있는지 설명해', '이진숙 국민의힘 의원이 "이재명 정권은 생각에도 ''수갑''을 채울 것인가"라고 강하게 비판했다. 이 의원은 5일 자신의 페이스북에 "배재고등학교에 화환을 보냈다. 화환 리본에는 ''스타벅스가 5.18과 무슨 관계가 있나'' ''배재고 학생들과 함께 합니다''라는 글귀가 적혀 있다"라며 이 같이 말했다. 그는 "스타벅스가 5.18 모욕과 무슨 관계가 있는지 설명해 주실 분 댓글 달아달라"며 "만약 스타벅스가 5.18과 광주에 대한 모욕을 상징한다면, 스타벅스는 더이상 영업을 해서는 안될 것"이라고 주장했다. 그는 "그 ''민주세력''의 추정으로 ''스타벅스 가야지''가 광주.5.18 모욕이라고 단정하고 배재고 야구부 학생들을 징계한다면, 그들은 ''생각에 수갑을 채우는 짓''을 시작하는 것"이라며 "학생들이 그렇게 생각했다는 것이 아니다. ''스타벅스 가야지라고 말한 게 5.18과 광주를 모욕할 생각이 있었던 거잖아''라고 판정내린다는 것"이라고 주장했다. 그는 "''생각에 수갑을 채우는 나라''는 어딘가. 김정은은 북한에서 성역이다. 누가 5.18도 성역이라고 말했다. ''더 평등한 동물'' 중의 한 명이"라며 "교육부 장관을 하는 인물은 대통령이 시해된 날을 ''탕탕절''로 불러도 괜찮고, 좌파면 ''탱크로 밀어버려야''라고 말해도 용인이 되는 세상"이라고 했다.', 'crawl', '프레시안', '2026-07-06 05:01:46', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/06/2026070522094729473_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:39:31.76229', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4241, 'https://www.pressian.com/api/v3/site/rss/section/67', NULL, 'https://www.pressian.com/pages/articles/2026070311204076443&ref=rss', '경제', '법원, ''2000억 조달 문제''로 홈플러스 회생절차 폐지  결정', '법원이이 기업회생절차를 밟고 있는 홈플러스의 회생절차 폐지를 결정했다. 서울회생법원 4부(재판장 정준영 법원장)는 3일 홈플러스 회생계획안의 수행 가능성에 대해 불가능하다고 판단하고 회생절차 폐지 결정을 내렸다. 앞서 홈플러스가 법원에 제출한 수정 회생계획안에는 기존 126개였던 점포 수를 67개로 줄이고, 인력도 약 50% 감축하는 내용이 담겼다. 이', '법원이이 기업회생절차를 밟고 있는 홈플러스의 회생절차 폐지를 결정했다. 서울회생법원 4부(재판장 정준영 법원장)는 3일 홈플러스 회생계획안의 수행 가능성에 대해 불가능하다고 판단하고 회생절차 폐지 결정을 내렸다. 앞서 홈플러스가 법원에 제출한 수정 회생계획안에는 기존 126개였던 점포 수를 67개로 줄이고, 인력도 약 50% 감축하는 내용이 담겼다. 이를 통해 1조 2000억 원 규모의 비용을 절감하겠다는 것이다. 홈플러스가 회생계획안 수정안을 제출하면서 절차는 재판부와 조사위원의 수행가능성 검토 단계로 넘어갔지만, 2000억원 규모 추가 자금 조달 문제가 해소되지 않아 기한 연장이 이뤄지지 않은 것이다. ▲홈플러스의 회생계획안 인가 시한을 하루 앞둔 2일 서울 시내 한 홈플러스 매장 앞에서 시민들이 오가고 있다. ⓒ연합뉴스', 'crawl', '프레시안', '2026-07-03 11:20:41', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/03/2026070311172812651_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:39:45.175683', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4257, 'https://www.pressian.com/api/v3/site/rss/section/67', NULL, 'https://www.pressian.com/pages/articles/2026062415355084150&ref=rss', '경제', '''흡혈귀 경영'' MBK는 어떻게  홈플러스를 망가뜨렸나?', '노동은 ''사회 안보''(Social Security)의 문제다. 우리는 IMF 구조조정 사태를 거친 후 ''대량 해고''가 어떻게 사회를 망가뜨리는지 지켜본 경험이 있다. 이후 신자유주의 개혁이 가속화되면서 어느새 ''사모펀드''는 우리 삶의 주변에 익숙하게 다가와 있다. 사모펀드에 대한 논쟁은 자본 시장과 노동 시장에서 여전히 뜨겁게 진행 중이다. 한편에서는 사', '노동은 ''사회 안보''(Social Security)의 문제다. 우리는 IMF 구조조정 사태를 거친 후 ''대량 해고''가 어떻게 사회를 망가뜨리는지 지켜본 경험이 있다. 이후 신자유주의 개혁이 가속화되면서 어느새 ''사모펀드''는 우리 삶의 주변에 익숙하게 다가와 있다. 사모펀드에 대한 논쟁은 자본 시장과 노동 시장에서 여전히 뜨겁게 진행 중이다. 한편에서는 사모펀드가 자본시장의 체질을 개선하는 ''메기'' 역할을 한다고 주장한다. 기업의 경영 효율화와 체질 개선, 그리고 새로운 자금 조달로 자본 시장에서 활력을 줄 수 있다는 것이다. 하지만 ''암''도 존재한다. 단기 수익 지상주의로 구조조정을 일삼고 기업을 망가뜨리며 결과적으로 경제 주체의 부담을 가중시킨다는 주장이다. 지금 MBK의 홈플러스 인수 및 파산 논란은 사모펀드의 ''약탈적 경영''의 교과서라 불러도 손색이 없다. 특히 수익 추구 과정에서 노동자들이 대거 해고될 위기에 처한 상황은 ''사회 안보''를 위협하는 지경까지 이르고 있다. MBK의 ''홈플러스 사냥''에 관한 이야기를 4회에 걸쳐 연재한다. 편집자 1948년 설립된 장난감 전문 매장 토이저러스(Toys ''R'' Us)는 한때 세계 1600개 매장에서 115억 달러의 매출을 자랑했던 회사였다. 소비패턴의 변화, 신생아 수 감소 등으로 고전하던 이 회사를 2005년 콜버그크래비스로버츠(KKR), 베인캐피털(Bain Capital), 부동산 투자회사 보나도(Vornado) 등으로 구성된 사모펀드 컨소시엄이 66억 달러에 사들였다. 이때 사용된 게 악명 높은 ''차입 매수(LBO)'' 방식이다. 사모펀드는 인수자금 중 50억 달러 이상을 금융권에서 빌려 회사 경영권을 인수했고, 이 대출 이자만 연간 수천억 원 규모를 지급해야 했다. 회사의 유동성은 망가졌고, 점포 확장, 온라인 시장 공략 등 성장에 쓸 돈은 없었다. 그리고 2017년 토이저러스는 사실상 파산했고, 약 3만 명의 노동자가 길거리에 나 앉은 것으로 추산된다. 지금 MBK가 홈플러스를 인수해 파산 지경에 이른 것과 놀랄만큼 똑같은 모습이다. 지난 2015년 북아시아 최대 사모펀드로 불리는 김병주의 MBK파트너스가 인수한 홈플러스는 신용등급 하락에 따른 선제적 구조조정과 막대한 금융 채무 조정을 위해 2025년 3월 서울회생법원에 기업 회생 절차(법정관리)를 신청했다. 표면적으로는 경영 실패다. 하지만 MBK 연례보고서에서는 홈플러스 투자펀드 3호 블라이드 펀드는 홈플러스 경영 실패에도 1조2000억 원의 수익을 올렸다고 돼 있다. 홈플러스 최대 채권자인 메리츠의 추산에 따르면 MBK는 이 펀드 운용으로 약 3억 달러의 관리보수와 약 5억 달러의 성과보수 등 총 8억2000만달러(한화 약 1조2300억 원) 규모의 보수를 취한 것으로 추정된다고 한다. 3호 펀드의 포트폴리오는 홈플러스 외에 7개 이상의 기업이다. 홈플러스로 1조 원가량의 손실을 낸 것으로 추정되지만, 해당 펀드는 수익을 낸 셈이다. (MBK 측은 "홈플러스 투자와 관련해 성과 보수를 수령한 것은 전혀 없다. 메리츠 금융지주가 주장하는 성과보수는 여러 펀드의 미실현 평가 가치를 근거로 한 가설적 성과보수 추정치를 합산한 것에 불과하다"고 반박했다.) 홈플러스는 ''버리는 카드'', 일개 포트폴리오다. 그 ''일개 포트폴리오'' 홈플러스가 파산 위기에 빠져 수천명이 일자리를 잃고 길거리에 나앉게 생겼다. ''남의 돈''으로 회사 인수해 ''살점 뜯어먹기'' MBK는 영국 테스코로부터 7조2000억 원에 홈플러스를 인수했다. MBK의 실제 투자금은 3조2000억 원에 불과했고, 나머지 4조 원은 홈플러스 자산을 담보로 대출을 받은 ''차입매수(LBO)'' 방식으로 해결했다. 이때부터 이상한 상황이 벌어지기 시작했다. (MBK 측은 "홈플러스 인수 과정에서 체결된 인수 금융 대출 계약에서 홈플러스 자산이 담보로 제공된 바 없다"고 반박했다.) 막대한 빚을 갚기 위해 MBK는 홈플러스의 자산을 닥치는대로 팔아 치웠다. 2016년~2018년 홈플러스 가좌점, 김포점, 김해점, 북수원점 등 알짜 매장들을 세일앤리스백(Sale & Lease-back, 매각후 다시 임차해 영업하는 방식)으로 매각했다. 자가 건물을 남의 건물로 바꿔 현금을 확보해 빚을 갚는 데 썼다. 매년 수천억 원의 임차료 고정비 부담이 발생했다. 2020년부터는 아예 부동산 개발업자에게 부지를 매각하고 매장을 없애는 ''폐점 매각''으로 방식을 바꿨다. 쿠팡 등 이커머스 시장이 커지고 코로나19 직격탄을 맞으며 대형마트 업황은 나빠지기 시작했다. 그럴수록 홈플러스는 ''자산 유동화''에 매달렸다. 안산고잔점, 대구점, 대전탄방점, 대전둔산점, 동청주점 부산 해운대점, 가야점 등을 매각했다. MBK 인수 후 2024년까지 28개 안팎의 점포 및 물류센터가 매각됐고, 전체 점포의 절반 이상이 임차 매장으로 바뀌었다. 누적 매각 대금은 약 4조 원, 이에 따른 연간 임차료만 4000억 원에 달했다. 악순환이었다. 3년 연속 1000억 원대 영업손실을 기록했다. 결국 부채비율 1400%를 돌파한 후 강제 구조조정 단계에 돌입했다. 결국 지난해 3월 서울회생법원에 기습적으로 기업회생절차(법정관리)를 신청했다. 법정관리 돌입 직전 전자단기사채(전단채·ABSTB)를 팔아치워, 개미들의 피눈물을 뽑아냈다. 홈플러스 전단채 피해 규모는 피해자 비상대책위원회 집계 기준으로 4000억 원이 넘는다. 검찰은 MBK가 신용등급 하락 가능성을 알면서도 대규모 단기채권을 발행한 뒤 기습적으로 기업회생을 신청해 투자자들을 기망했다는 혐의를 잡고 김병주 회장 등을 수사하고 있다. 홈플러스는 그나마 알짜 사업부인 기업형 슈퍼마켓(SSM) ''홈플러스 익스프레스''를 쪼개 분리 매각하고, 향후 6년간 부실 대형마트 점포 41개 개소를 추가로 정리할 예정이다. 올해 초부터 임직원을 대상으로 한 희망퇴직 등 인력 감축 작업을 본격적으로 진행하고 있다. MBK의 홈플러스 경영은 과도한 빚을 내서 인수→빚을 갚기 위해 알짜 점포 4조 원어치 매각→매각 후 임차료 부담 급증으로 실적 악화→법정관리 및 노동자 구조조정으로 이어졌다. 이들은 경영 실패 따위는 아랑곳 않는다. 팔고 떠나면 그만이다. 그 과정에서 어떻게든 이익을 짜내면 된다. 노동자가 대거 길거리에 나 앉든 상관 없다. 홈플러스는 지난 4일 노동조합에 공문을 발송하고 "현재 낮은 기여도로 휴업 중인 37개 점포에 대해 폐점을 결정했다"고 밝혔다. 이번 폐점 결정에 영향을 받는 인원은 약 3500명 규모다. 민주노총 마트산업노동조합에 따르면 지난해 말 1만7986명이었던 홈플러스 직원 수는 올해 4월 말 기준 1만5398명으로 감소했다. 이미 올해 들어서만 2500명 넘는 직원이 회사를 떠난 것이다. 그리고 6000명의 노동자가 길거리에 나앉거나 나앉게 생겼다. 직원 월급이나 퇴직금 등을 챙겨주기 위해서는 채권단 동의를 바탕으로 신규 대출이나 DIP(회생기업 금융) 자금 조달이 이뤄져야 하는데, MBK는 움직이지 않는다. 최대 채권자인 메리츠금융은 "투자 펀드에서 1조 원 넘게 수익을 올리고 포브스에 14조 원대 자산가로 이름을 올린 김병주 회장이 대주주로서 책임은커녕 왜 1000억 원 보증조차 할 수 없는지 투명하게 밝혀야 한다"고 비난했다. ▲김병주 MBK파트너스 회장 ⓒ연합뉴스 ''메뚜기 자본주의''가 지나간 자리들 마이클 병주 킴(Michael ByungJu Kim, 한국명 김병주)에서 이름을 딴 MBK는 김병주 회장이 주도하는 사모펀드다. 사모펀드는 수익만을 목표로 한다. 회사의 비전이나 고용의 안정성이 아니라 보통 단기(5년~10년) 내로 투자한 물건·회사를 처분하는 경향이 크다. 한국에서 사모펀드와 관련된 역사는 그리 유쾌하지 않다. IMF 구제금융 사태 이후 자본 시장이 개방되면서 수많은 기업들과 은행들이 사모펀드들에 넘어갔다가 ''먹튀''로 귀결된 경험들을 가지고 있다. 이런 행태의 사모펀드 경영 방식에 빗댄 별명들만 봐도 무시무시하다. 기업 사냥꾼 (Corporate Raider), 벌처 자본주의 (Vulture Capitalism, 시체나 썩은 고기를 먹는 독수리Vulture에 빗댄 표현), 메뚜기 자본주의(Locust Capitalism, 메뚜기 떼가 농작물을 모두 휩쓸고 지나가 황폐화시키듯, 사모펀드가 회사의 자산을 갉아먹고 기업의 생존 기반을 무너뜨린 뒤 떠나버리는 현상에 비유), 금융 뱀파이어/흡혈귀(Financial Vampires) 등 다양하다. 특히 간과되고 있는 것은 사모펀드 인수 기업에서 나타나는 고용 불안 문제다. 과거엔 이런 문제가 당연히 치러야 할 ''희생'' 쯤으로 인식됐지만, 이미 한국은 국가 경제 규모가 커지는 것과 별개로 상시적 고용의 불안정과 양극화가 더 심화되고 있다. 이는 사회적 안보와 직결된다. 고용은 중요한 사회적 안보 요소고, 이런 요소가 흔들리고 취약해지면 사회 혼란이 극심해진다. MBK는 기업을 인수한 후 인력 구조조정에 돌입하는 것으로 악명이 높은 회사다. MBK가 지난 2007년 인수한 케이블방송 씨앤앰(C&M, 현 딜라이브) 사태는 방송 역사상 최악의 구조조정이 벌어진 케이스다. MBK는 기업 매각 대금을 높이고 비용을 줄이기 위해 원청의 외주화 및 하청 업체 교체를 진행했다. 이 과정에서 협력업체 노동자 109명이 대량 해고됐다. 해고 노동자들이 복직을 요구하며 광화문 전광판 위에서 고공 농성을 벌였고, MBK 본사 앞 노숙 농성이 150일 넘게 이어졌다. 인력 감축과 외주화로 인해 결국 씨앤앰의 브랜드 신뢰도와 시장 점유율은 폭락했다. MBK가 2009년 인수한 철강구조물 제조업체 영화엔지니어링은 실적 악화로 2012년 대규모 구조조정(임직원 약 70% 감원)을 단행했다. 중장기 경영 전략보다는 단기 배당과 투자금 회수 등에 우선순위를 두면서 벌어진 일이라는 지적이다. 핵심 인력들이 나가면서 경쟁력을 상실했고, 무리한 경영과 업황 악화가 겹치며 적자 행진을 벌였다. 이는 신용등급 하락과 수주 급감으로 이어져 2016년 법정관리를 신청했고 2017년 회사를 매각하는 것으로 MBK는 손을 털었다. 하지만 사회적 책임과 같은 말은 사치였다. 지난 2013년 MBK가 오렌지라이프(구 ING생명)를 인수할 때 "장기 투자를 통해 고용 안정을 보장하겠다"고 약속했지만, 인수한 지 채 1년도 되지 않아 비용 절감을 목표로 전체 임직원의 30% 수준 감축 목표로 구조조정을 단행했다. ING생명 노조는 MBK를 "천박한 투기 자본"이라고 비난했다. 그러나 결국 2조 원 규모의 차익을 남기고 재매각에 성공해 ''먹튀'' 논란을 낳았다. 아웃도어 브랜드 네파 인수는 홈플러스 사태와 판박이처럼 비슷하다. MBK는 2013년 네파를 약 1000억 원에 인수했는데, 4800억 원은 차입으로 조달했다. 그리고 네파를 티비홀딩스와 합병하면서 부채를 네파로 이전했다. 네파는 원금은 물론 매년 300억원 안팎의 이자를 부담하면서 경영이 급속도로 악화됐다. 영업으로 번 돈을 투자나 브랜드 경쟁력 강화가 아닌 금융비용 상환에 우선 투입되는 구조가 고착화된 것이다. 전형적인 ''단물 빨아먹기'' 식 MBK의 경영 수법이다. 일각에서는 ''다음 먹튀'' 대상으로 네파가 거론되기도 한다. 그리고 MBK는 현재 고려아연과 경영권 분쟁에도 뛰어들었다. 한국노총 전국금속노동조합연맹 산하 고려아연 노조가 "MBK의 사모펀드식 경영이 홈플러스 노동자들의 생존권 위기로 이어지고 있다"면서 홈플러스 노조와 연대를 선언한 것은 의미심장하다. 사모펀드의 ''약탈적 경영''으로 노동자들은 오늘도 불안에 시달리고 있다. 게다가 고려아연은 반도체, 자동차, 배터리 등 국내 주요 산업의 기초 소재인 아연, 연, 은 등을 공급하는 세계 1위 비철금속 종합 제련 기업이다. 국가 경제와 공급망 안보에 직결되는 핵심 역할을 담당하고 있어 국가 기간산업으로 평가받는다. 사모펀드의 ''약탈적 경영''이 국가 기간 산업에 들어올 때, 우린 어떤 상황에 직면하게 될까?', 'crawl', '프레시안', '2026-06-26 08:58:28', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/06/30/2026062415254640154_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:40:23.585396', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4263, 'https://www.pressian.com/api/v3/site/rss/section/68', NULL, 'https://www.pressian.com/pages/articles/2026070714371957614&ref=rss', '국제', 'quot;차에 사람이 깔리면 모두 돕지 않나quot;hellip;홈플러스 살리려는 원로들의 호소', '10만 여 명의 생계가 달린 홈플러스를 되살릴 시한이 열흘 앞으로 다가온 가운데, 김상근 목사, 함세웅 신부 등 시민사회 원로들이 이재명 대통령 면담 및 정부 차원의 2000억 원 긴급 자금 마련을 촉구했다. 13조 원대 재산가로 알려진 김병주 MBK 회장의 책임을 묻는 목소리도 나왔다. 전국민중행동은 7일 서울 서대문 민주노총 건물에서 홈플러스 회생방안', '10만 여 명의 생계가 달린 홈플러스를 되살릴 시한이 열흘 앞으로 다가온 가운데, 김상근 목사, 함세웅 신부 등 시민사회 원로들이 이재명 대통령 면담 및 정부 차원의 2000억 원 긴급 자금 마련을 촉구했다. 13조 원대 재산가로 알려진 김병주 MBK 회장의 책임을 묻는 목소리도 나왔다. 전국민중행동은 7일 서울 서대문 민주노총 건물에서 홈플러스 회생방안 마련을 위한 사회원로 및 각계 대표자 기자회견을 열었다. 김 목사와 함 신부 등이 자리에 직접 참석했고, 이부영 원로언론인, 백도명 서울대 명예교수 등 135명이 회견문 연서명으로 뜻을 보탰다. 참가자들은 "매우 위중하고 엄중한 마음으로 이 자리에 섰다"며 법원의 회생폐지 결정에 대한 즉시항고 기한인 오는 17일까지 "2000억 원의 긴급운영자금이 마련되지 못한다면, 홈플러스는 청산 절차로 내몰릴 수밖에 없다"고 밝혔다. 이어 홈플러스 파산은 "대규모 고용대란 등 사회적 재난에 버금가는 실로 엄중한 사태"라며 "홈플러스에는 직영 노동자 2만여 명 외에 협력 외주업체 노동자까지 무려 10만 명 안팎의 노동자가 일하고 있다. 1800여 개 납품업체, 8000여 개 입점업주와 그 가족까지 포함하면 피해는 수십만 명에게까지 미칠 수 있다"고 강조했다. 참가자들은 "이재명 대통령께 절박하게 요청드린다. 이제 허비할 시간도 얼마 남지 않았다"며 "대통령께서 직접 나서 해결의 길을 열어 젖히는 수밖에 없다"고 주장했다. 이어 이 대통령 면담과 함께 △공공부문에서 2000억 원의 긴급 운영자금 마련 △공공부문이 참여해 초기 투자자와 컨소시엄을 만들고 특수목적법인(SPC)을 설립 등 대책 마련을 정부에 요구했다. 안수용 민주노총 서비스연맹 마트산업노조 홈플러스지부장은 "지금 홈플러스는 벼랑 끝에 서 있다"며 "이재명 정부는 홈플러스를 정상화하겠다고 수차례 약속했다. 저희는 그 약속을 믿었다"고 말했다. 이어 "아직 늦지 않았다. 아직 살릴 수 있다. 대통령께서 결단해 주시면 수십만 명이 살아날 수 있다"며 "부디 더 늦기 전에 결단해달라. 저희는 결코 포기하지 않겠다"고 강조했다. ▲전국민중행동이 7일 서울 서대문 민주노총 건물에서 연 홈플러스 회생방안 마련을 위한 이재명 대통령 면담 요구 및 정부의 긴급 개입 촉구 사회원로 및 각계 대표자 기자회견에서 안수용 홈플러스지부장(가운데)이 발언하고 있다. ⓒ프레시안(최용락) 양경수 민주노총 위원장은 "IMF 이후 대우차 노동자가 구조조정 당할 때, 쌍용차 노동자가 구조조정 당할 때 2000여 명 수준이었다"며 "그들이 구조조정 당함으로써 수많은 노동자가 목숨을 끊었고, 사회적으로 막대한 비용이 발생했다"고 짚었다. 이어 홈플러스에 생계가 달린 이는 "10만 명"이라며 "10만 국민이 어려움을 호소하는데 정부가 외면하는 것은 적절하지 않다"고 지적했다. 김 회장의 잘못을 질타하는 목소리도 나왔다. 김 목사는 "마지막에 자기 재산을 갖고 가는 일은 없다. 결국 이 세상은 빈손으로 떠난다"며 "2000억 원을 만들지 못해 수천 명 직원을 사지에 몰아넣는다? (김 회장의) 재산이 몇 조원이라고 했다. 그 십분의 일만 내놔도 사태를 해결할 수 있다"고 일갈했다. <포브스>에 따르면 올해 기준 김 회장 재산은 약 13조 7700억 원이다. 정강자 전 참여연대 대표는 자신이 홈플러스에서 생선과 야채, 생필품을 구입할 때 만난 이들은 "농민이고, 어민이고, 제조업 노동자고, 주차, 미화, 판매 노동자고, 자영업자들이었다"며 "홈플러스는 시민과 소비자, 지역주민이 어우러져 살던 곳이었다"고 짚었다. 이어 "그런 홈플러스에 탈이 났다. 진단도 나왔다. 그렇다면 긴급자금을 투입해야 한다"며 "차에 사람이 깔리면 지나가던 모든 사람이, 자기가 할 수 있는 모든 방법으로 차를 끌어올린다. 홈플러스에 대해서도 그렇게 해야 할 때"라고 호소했다. ▲전국민중행동이 7일 서울 서대문 민주노총 건물에서 연 홈플러스 회생방안 마련을 위한 이재명 대통령 면담 요구 및 정부의 긴급 개입 촉구 사회원로 및 각계 대표자 기자회견에서 참가자들이 구호를 외치고 있다. ⓒ프레시안(최용락) 앞서 서울회생법원 회생3부(법원장 정준영)는 지난 3일 홈플러스 회생절차 폐지 결정을 했다. 즉시항고 기간은 오는 17일까지다. 이 사이에 홈플러스가 2000억 원의 긴급자금을 마련하면 법원은 절차를 재개할 가능성이 열려 있다는 입장이다. 법원 판단에 앞서 홈플러스는 제1채권자인 메리츠그룹에 2000억 원의 긴급자금 대출을 요청했다. 메리츠그룹은 이에 김 회장 등 MBK 경영진의 보증을 요구했으나, MBK 측이 1000억 원에 대해서만 보증을 서겠다고 밝혀 대출이 이뤄지지 않았다.', 'crawl', '프레시안', '2026-07-07 14:56:29', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/07/2026070714290996933_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:40:36.886287', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4267, 'https://www.pressian.com/api/v3/site/rss/section/68', NULL, 'https://www.pressian.com/pages/articles/2026070710140078080&ref=rss', '국제', '[속보] 검찰, ''장윤기 수사팀장'' 경찰 상대 압수수색', '광주 여고생 살인사건을 수사한 경찰을 상대로 검찰이 압수수색에 나섰다. 광주지검은 7일 "광산경찰서 수사팀장 박모(59) 경감에 대해 증거인멸·공무상 비밀누설 등 혐의로 강제 수사에 착수했다"고 밝혔다. 전남광주 광산경찰서를 대상으로 수사팀장의 증거인멸 등 혐의를 확인하기 위한 압수수색도 실시했다. 앞서 광주경찰청은 전날 수사팀장인 박모 경감을 증거인멸', '광주 여고생 살인사건을 수사한 경찰을 상대로 검찰이 압수수색에 나섰다. 광주지검은 7일 "광산경찰서 수사팀장 박모(59) 경감에 대해 증거인멸·공무상 비밀누설 등 혐의로 강제 수사에 착수했다"고 밝혔다. 전남광주 광산경찰서를 대상으로 수사팀장의 증거인멸 등 혐의를 확인하기 위한 압수수색도 실시했다. 앞서 광주경찰청은 전날 수사팀장인 박모 경감을 증거인멸 혐의로 긴급 체포한 바 있다. 현재 경찰청 국가수사본부는 27명 규모의 특별수사팀을 꾸려 진상 조사에 나섰다. 박 경감은 장윤기가 지난 5월 5일 여고생을 납치하려고 할 때 사용한 SUV 차량에서 케이블타이를 발견하고도 압수하지 않은 혐의, 차량 수색 채증 영상을 검찰에 제출하지 않은 혐의 등을 받고 있다. ▲6일 경찰청 국가수사본부는 ''여고생 살해범'' 장윤기(23)의 차량에서 주요 증거물인 케이블 타이(결박 도구)가 사라진 사실을 토대로 현직 경찰관인 장윤기 아버지와 담당 수사팀 간 유착 의혹에 대한 수사에 착수했다. 장윤기를 검찰에 송치할 때까지 수사를 담당했던 광주 광산경찰서 형사과 소속 A 팀장은 사라진 케이블 타이와 관련해 증거인멸 혐의로 이날 경찰에 긴급체포됐다. 사진은 지난 5월 5일 사건 발생 직후 언론에 포착된 장윤기의 차량. ⓒ연합뉴스', 'crawl', '프레시안', '2026-07-07 10:14:00', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/07/2026070710134718126_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:40:44.380229', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4273, 'https://www.pressian.com/api/v3/site/rss/section/68', NULL, 'https://www.pressian.com/pages/articles/2026070615360558968&ref=rss', '국제', '[속보] 배재고 야구부, 광주일고 찾아 자필 사과문 전달', '배재고 야구부 선수단과 지도자가 “스타벅스 가야지” 응원에 대해 사과하기 위해 광주제일고에 도착했다. 선수단과 감독이 각각 자필 사과문도 전달했다. 응원으로 물의를 빚은지 일주일만이다. 배재고 야구부원 36명과 배재고 교장, 지도자, 학부모, 교육청 관계자 등 86명은 6일 오후 3시경 광주일고를 방문해 부적절한 응원에 대해 사과했다. 배재고 야구부 선', '배재고 야구부 선수단과 지도자가 “스타벅스 가야지” 응원에 대해 사과하기 위해 광주제일고에 도착했다. 선수단과 감독이 각각 자필 사과문도 전달했다. 응원으로 물의를 빚은지 일주일만이다. 배재고 야구부원 36명과 배재고 교장, 지도자, 학부모, 교육청 관계자 등 86명은 6일 오후 3시경 광주일고를 방문해 부적절한 응원에 대해 사과했다. 배재고 야구부 선수들은 사과문을 통해 "우리가 광주에 발을 딛는 것만으로도 불편했을 텐데 이렇게 귀한 시간 마련해주신 광주일고 관계자들과 선수들께 진심으로 감사드린다"며 "꿈과 희망이 담겨야 하는 야구장에서 배재고 선수들의 부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주일고 선수들과 학부모, 광주 시민들께 진심으로 사과드린다"고 밝혔다. 이어 "이번 사건으로 저를 포함한 팀 모든 선수가 진심으로 깊이 반성하고 있으며 야구를 떠나 인성이나 태도가 인생에서 얼마나 중요한지 깨닫고 다시 한번 배우게 됐다"며 "선수들의 좋지 못한 발언, 행동으로 인해 정말 많은 분이 마음의 상처와 고통을 받고 계시다. 항상 마음속 깊이 반성하는 마음과 자세로 살아가겠다"고 덧붙였다. 권오영 배재고 야구부 감독도 지도자 사과문에서 "야구부 학생 선수들 지역 비하 응원은 무엇으로도 변명할 수 없는 잘못임을 인정하며 학생들을 잘 이끌고 가르쳐야 할 지도자로서 저의 책임이 가장 크기에 진심으로 사죄를 드린다"고 했다. 이어 "이기는 것보다 더 중요한 것이 있음을 저도 모르게 잊고 있었고 저의 언행과 지도 방식이 올바른 본보기가 되지 못한 듯해 더욱 깊이 자책하며 부끄러울 뿐"이라며 "배재고 학생 선수들의 잘못 이전에 제대로 가르치고 이끌지 못한 저의 과오를 인정하며 지도자로서 져야 할 책임을 겸허히 감당하고자 한다"고 강조했다. 앞서 배재고 야구부는 지난달 29일 서울 목동구장에서 열린 제81회 청룡기 전국고교야구선수권대회에서 광주제일고를 상대하던 중 "가야지, 가야지, 스타벅스 가야지", "탱크데이" 등 응원구호를 외쳤다. 이에 대해 5.18민주화운동을 조롱하는 부적절한 응원이었다는 비판이 일었다. ▲배재고 야구부 선수와 감독의 자필 사과문. ⓒ연합뉴스', 'crawl', '프레시안', '2026-07-06 15:36:58', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/06/2026070615351476663_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:40:55.643341', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4277, 'https://www.pressian.com/api/v3/site/rss/section/68', NULL, 'https://www.pressian.com/pages/articles/2026070610502608928&ref=rss', '국제', '[속보] 검찰에 기소된 정유사 4곳, 담합으로 미middot;이란 전쟁 직후 가격 폭등', '정유사 4곳(HD현대오일뱅크·SK에너지·GS칼텍스·에쓰오일(S-OIL)과 소속 임직원들이 재판에 넘겨졌다. 이들은 미국과 이란 전쟁 직후 담합 통해 국내 유가를 급등시킨 혐의를 받고 있다. 서울중앙지검 공정거래조사부(부장검사 나희석)는 6일 4대 법인을 공정거래법 위반 혐의로 기소했다고 밝혔다. 같은 혐의로 HD현대오일뱅크의 가격 결정 부서장을 구속 기소', '정유사 4곳(HD현대오일뱅크·SK에너지·GS칼텍스·에쓰오일(S-OIL)과 소속 임직원들이 재판에 넘겨졌다. 이들은 미국과 이란 전쟁 직후 담합 통해 국내 유가를 급등시킨 혐의를 받고 있다. 서울중앙지검 공정거래조사부(부장검사 나희석)는 6일 4대 법인을 공정거래법 위반 혐의로 기소했다고 밝혔다. 같은 혐의로 HD현대오일뱅크의 가격 결정 부서장을 구속 기소하고 해당 부서 책임매니저와 법무실장은 불구속 기소했다. GS칼텍스 국내영업부문장도 불구속 기소했다. 검찰은 미·이란 전쟁 후 발생한 한국 석유가격 폭등은 HD현대오일뱅크와 SK에너지의 가격 결정부서 책임자들이 가격 인상 시기와 규모를 담합한 결과라고 판단했다. 검찰은 이들의 답함 규모를 14.2조 원으로 판단했다. 또한 GS칼텍스와 에쓰오일이 HD현대오일뱅크·SK에너지의 담합 가격을 참고해 유가를 인상한 것까지 고려하면, 약 26조원 상당의 경쟁 제한 효과가 발생했다고 판단했다. 4대 정유회사들은 2021년 1월부터 지난달까지 우월적 지위를 이용해 주유소들에 전량구매 계약을 체결하고, 공급 가격을 일방적으로 통보한 것으로 조사됐다. ▲28일 서울 시내 한 주유소 앞에 휘발유 가격이 게시돼 있다. ⓒ연합뉴스', 'crawl', '프레시안', '2026-07-06 10:50:26', '진보', 'ready', 'https://www.pressian.com/_resources/10/2026/07/06/2026070610483004465_l.jpg', '2026-07-07 06:04:44', '2026-07-07 18:41:19.289587', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4296, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/politics', 'https://news.jtbc.co.kr/article/NB12306959', 'https://news.jtbc.co.kr/article/NB12306959', '정치', '김민석, 친청계 ''감기약 발언''에 "대장동 보는 듯...허위사실 유포 책임져야"', '더불어민주당 당 대표 출마를 선언한 김민석 전 국무총리가 친청(친정청래)계의 ''계엄 해제 표결 불참'' 의혹 제기에 대해 "무슨 대장동 때를 보는 것 같다"고 했습니다. 김 전 총리는 오늘(7일) KBS라디오 ''전격', '더불어민주당 당 대표 출마를 선언한 김민석 전 국무총리가 친청(친정청래)계의 ''계엄 해제 표결 불참'' 의혹 제기에 대해 "무슨 대장동 때를 보는 것 같다"고 했습니다. 김 전 총리는 오늘(7일) KBS라디오 ''전격시사''에서 "이성윤 최고위원이 말씀하셨던데, ''국민의힘에서 누가 얘기하나'' 생각했다"며 "''저런 식으로 정치를 하면 좀 어려워 질텐데''라고 생각하고 있다"고 말했습니다. 2022년 대선을 앞두고 이재명 대통령과 경선에서 붙었던 이낙연 전 총리 측이 대장동 개발비리의혹을 제기했던 것을 시사한 걸로 풀이됩니다. 김민석 전 국무총리가 어제(6일) 국회 소통관에서 당 대표 출마 선언 기자회견을 마친 뒤 기자들의 질의에 답하고 있습니다. [사진출처=연합뉴스] 이 의원은 전날(6일) 소셜미디어에 "윤석열 계엄 해제 국회 표결에는 불참했는데, 왜 국회 표결에 참여하지 않았느냐"며 "감기약을 드시고 주무셨다고 하는데 그 감기약 성분이 무엇이냐"고 의혹을 제기했습니다. 김 전 총리는 "표결 시점에 국회에 있었다"며 "허위사실에 의한 명예훼손"이라고 반박했습니다. 앞서 친명계 강득구 최고위원도 소셜미디어에 "무소속 한동훈 의원도 똑같은 논리로 김 전 총리의 그 날 밤 행적을 캐물었다. 이런 말꼬투리 잡기식 문제 제기를, 우리 당 최고위원이 그대로 되풀이하고 있다"며 "지켜야 할 선이 있다"고 했습니다.', 'crawl', 'JTBC', '2026-07-07 11:00:38', '진보', 'ready', 'https://photo.jtbc.co.kr/news/jam_photo/202607/07/131b4402-7ce5-4bd3-9385-f4400e10459e.jpg', '2026-07-07 06:04:45', '2026-07-07 18:41:55.309561', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4297, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/politics', 'https://news.jtbc.co.kr/article/NB12306939', 'https://news.jtbc.co.kr/article/NB12306939', '정치', '이 대통령, 나토 정상회의 참석 위해 튀르키예로 출국', '이재명 대통령이 오늘(7일) 나토 정상회의 참석을 위해 튀르키예로 출국했습니다. 방산 협력 확대와 정상외교에 나섭니다. 이 대통령은 이날 서울공항을 통해 북대서양조약기구(NATO·나토) 정상회의가 열리는 튀르키예', '이재명 대통령 부부. 〈사진=연합뉴스〉 이재명 대통령이 오늘(7일) 나토 정상회의 참석을 위해 튀르키예로 출국했습니다. 방산 협력 확대와 정상외교에 나섭니다. 이 대통령은 이날 서울공항을 통해 북대서양조약기구(NATO·나토) 정상회의가 열리는 튀르키예 앙카라로 출국했습니다. 이번 일정은 마르크 뤼터 나토 사무총장의 초청으로 이뤄졌습니다. 이 대통령의 취임 후 첫 나토 정상회의 참석입니다. 이 대통령은 이날 오후 앙카라에 도착해 뤼터 사무총장과 함께 일본, 호주, 뉴질랜드 등 인도·태평양 파트너국(IP4) 대표들과 소인수회담에 참석합니다. 이어 나토 방위산업포럼에 참석해 ''공동의 가치, 더욱 강한 산업기반''을 주제로 한 세션에서 기조연설을 합니다. 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 참석합니다. 청와대는 이번 참석이 지난달 주요 7개국(G7) 정상회의에 이어 한국의 외교 지평을 넓히는 계기가 될 것이라고 설명했습니다. 또 세계 국방비의 55%를 차지하는 최대 방산시장인 나토 동맹국들과 방산 협력을 본격 추진하는 의미도 있다고 밝혔습니다. 특히 도널드 트럼프 미국 대통령도 나토 정상회의 참석을 위해 튀르키예를 찾는 만큼 두 정상이 현지에서 만날지에도 관심이 쏠립니다. 이 대통령은 8일까지 튀르키예 일정을 소화한 뒤 9일부터 몽골을 국빈 방문합니다.', 'crawl', 'JTBC', '2026-07-07 08:42:05', '진보', 'ready', 'https://photo.jtbc.co.kr/news/jam_photo/202607/07/1483cc49-46a2-475c-a277-1d6cddf22714.jpg', '2026-07-07 06:04:45', '2026-07-07 18:41:57.17624', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4299, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/politics', 'https://news.jtbc.co.kr/article/NB12306921', 'https://news.jtbc.co.kr/article/NB12306921', '정치', '속전속결 ''광주 군 공항'' 낙점…"리스크 적은 국유지" 속도전 최적', '[앵커] 호남 반도체 클러스터의 위치가 광주 군공항 부지로 확정됐습니다. 이재명 대통령이 계획을 발표한 지 불과 일주일 만에 삼성전자와 SK하이닉스가 이곳이 가장 적합하다는 의견을 냈습니다. 광주 도심에서 가까운데', '[앵커] 호남 반도체 클러스터의 위치가 광주 군공항 부지로 확정됐습니다. 이재명 대통령이 계획을 발표한 지 불과 일주일 만에 삼성전자와 SK하이닉스가 이곳이 가장 적합하다는 의견을 냈습니다. 광주 도심에서 가까운데다 국유지여서 토지 수용이나 보상에 걸리는 시간을 크게 줄일 수 있다는 점이 장점입니다. 유선의 기자입니다. [기자] 지난주 전국 4700조 규모의 반도체·AI 투자 계획을 발표하며 ''속도''를 강조했던 이재명 대통령. 청와대에서 점검회의를 열고 당장 시작해야 한다고 강조했습니다. [어차피 해야 될 일이라면 그런 절차 때문에 시간을 낭비하지 않도록 모든 절차를 불법이 아닌 한 동행, 병행 추진하도록 그렇게 했으면 좋겠습니다.] 이 대통령이 회의에서 ''서남권 반도체 클러스터''를 조성할 부지를 선정하자고 했고, [부지 선정을 오늘 논의했으면 좋겠어요. 물론 대체적으로 짐작 가는 바들이 있겠지만 그래도 확정을 지어야 되겠습니다.] 강훈식 대통령 비서실장은 부지가 확정됐다고 발표했습니다. [강훈식/대통령 비서실장 (어제) : 오늘 회의에서 광주 군 공항 부지에 호남권 반도체 산단을 조성하기로 결정했습니다.] 반도체 클러스터 투자 계획을 밝힌 지 일주일만에 부지 선정까지 마친 겁니다. 삼성전자와 SK하이닉스 등이 후보지 가운데 광주 군 공항이 가장 적합하다는 의견을 냈는데, 여의도 면적 약 3배에 달하는 약 250만평 규모인데다 토지 수용과 보상 등 작업이 비교적 단순해 공사기간을 단축할 수 있다는 점이 크게 작용했습니다. 광주 도심·KTX역과 가까워 인력 확보와 정주 여건 측면에서도 강점이 있다는 점 등이 고려됐습니다. [마침 재정적으로도 반도체 산업 분야의 초과 세수가 많이 발생하고 있기 때문에 재정 지원을 포함해서 모든 지원을 하겠다는 말씀을 드리고.] 안보 공백 없이 군 공항을 이전해야 하고 전력과 산업용수 확보 등 숙제가 남아 있지만 20년 넘게 표류해온 군 공항 이전 문제도 함께 털어낼 수 있게 되는 겁니다. 이 대통령의 국정수행 지지도는 지난주 서남·충청·영남권 대규모 지역 투자 발표에 힘입어 7주 만에 소폭 반등해 47%로 집계됐습니다. [영상취재 이주현 김미란 최무룡 영상편집 지윤정 영상디자인 정수임 신하경]', 'crawl', 'JTBC', '2026-07-07 08:14:00', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/news/cms/etc/2026/07/07/20260707073219222001.jpg', '2026-07-07 06:04:45', '2026-07-07 18:42:08.163076', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4313, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/politics', 'https://news.jtbc.co.kr/article/NB12306848', 'https://news.jtbc.co.kr/article/NB12306848', '정치', '호남 반도체 클러스터 속전속결…"광주 군 공항" 부지 확정', '[앵커] 호남 반도체 클러스터가 빠른 속도로 시작됐습니다. 이재명 대통령이 계획을 공개한 지 불과 일주일 만에 위치가 확정됐습니다. 광주 군공항 부지입니다. 삼성전자와 SK하이닉스가 이곳이 가장 적합하다는 의견을', '[앵커] 호남 반도체 클러스터가 빠른 속도로 시작됐습니다. 이재명 대통령이 계획을 공개한 지 불과 일주일 만에 위치가 확정됐습니다. 광주 군공항 부지입니다. 삼성전자와 SK하이닉스가 이곳이 가장 적합하다는 의견을 냈습니다. 국유지입니다. 수용과 보상에 걸리는 시간을 확 줄일 수 있습니다. 광주 도심에서 가깝습니다. KTX를 비롯해 교통이 좋습니다. 이 대통령은 매달 직접, 진척 상황을 점검하기로 했습니다. 첫 소식, 유선의 기자입니다. [기자] 지난주 전국 4700조 규모의 반도체·AI 투자 계획을 발표하며 ''속도''를 강조했던 이재명 대통령. 오늘 청와대에서 점검회의를 열고 당장 시작해야 한다고 강조했습니다. [어차피 해야 될 일이라면 그런 절차 때문에 시간을 낭비하지 않도록 모든 절차를 불법이 아닌 한 동행, 병행 추진하도록 그렇게 했으면 좋겠습니다.] 이 대통령이 오전 회의에서 ''서남권 반도체 클러스터''를 조성할 부지를 선정하자고 했고, [부지 선정을 오늘 논의했으면 좋겠어요. 물론 대체적으로 짐작 가는 바들이 있겠지만 그래도 확정을 지어야 되겠습니다.] 강훈식 대통령 비서실장은 오후에 부지가 확정됐다고 발표했습니다. [강훈식/대통령 비서실장 : 오늘 회의에서 광주 군 공항 부지에 호남권 반도체 산단을 조성하기로 결정했습니다.] 반도체 클러스터 투자 계획을 밝힌 지 일주일만에 부지 선정까지 마친 겁니다. 삼성전자와 SK하이닉스 등이 후보지 가운데 광주 군 공항이 가장 적합하다는 의견을 냈는데, 여의도 면적 약 3배에 달하는 약 250만평 규모인데다 토지 수용과 보상 등 작업이 비교적 단순해 공사기간을 단축할 수 있다는 점이 크게 작용했습니다. 광주 도심·KTX역과 가까워 인력 확보와 정주 여건 측면에서도 강점이 있다는 점 등이 고려됐습니다. [마침 재정적으로도 반도체 산업 분야의 초과 세수가 많이 발생하고 있기 때문에 재정 지원을 포함해서 모든 지원을 하겠다는 말씀을 드리고.] 안보 공백 없이 군 공항을 이전해야 하고 전력과 산업용수 확보 등 숙제가 남아 있지만 20년 넘게 표류해온 군 공항 이전 문제도 함께 털어낼 수 있게 되는 겁니다. 이 대통령의 국정수행 지지도는 지난주 서남·충청·영남권 대규모 지역 투자 발표에 힘입어 7주 만에 소폭 반등해 47%로 집계됐습니다. [영상취재 이주현 김미란 최무룡 영상편집 지윤정 영상디자인 정수임 신하경]', 'crawl', 'JTBC', '2026-07-06 18:47:09', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/news/cms/etc/2026/07/06/20260706184642275001.jpg', '2026-07-07 06:04:45', '2026-07-07 18:42:43.71669', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4316, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/politics', 'https://news.jtbc.co.kr/article/NB12306801', 'https://news.jtbc.co.kr/article/NB12306801', '정치', '배재고 사과에도 정쟁은 계속…''5·18 성역'' 발언 이병태 사퇴', '"광주일고 선수들과 학부모님, 광주 시민분들께 진심으로 사과드린다" 배재고 학생들이 광주일고 찾아 고개를 숙였습니다. 하지만 ''5·18 비하 논란''을 놓고 정치권 공방은 더욱 뜨거워졌는데요. [황명선/더불어민주', '"광주일고 선수들과 학부모님, 광주 시민분들께 진심으로 사과드린다" 배재고 학생들이 광주일고 찾아 고개를 숙였습니다. 하지만 ''5·18 비하 논란''을 놓고 정치권 공방은 더욱 뜨거워졌는데요. [황명선/더불어민주당 최고위원 : 민주화를 위해 피 흘린 역사를 부정하고 모욕하는 사람은 이재명 국민주권 정부의 일원이 될 자격이 없습니다. 이병태 부위원장은 즉각 사퇴하시기 바랍니다.] "5·18이 성역이 됐다" 이병태 규제합리화위원회 부위원장의 발언에 반발하며 사퇴를 촉구한 민주당. 하지만 국민의힘은 ''집단 린치''라는 입장입니다. [김재원/국민의힘 최고위원 : 제가 보기에도 여권에 지금 성한 사람이 별로 없는 것 같습니다. 이병태 규제합리화위원회 부위원장, 한때는 이분도 옳은 말을 좀 하시던 분입니다. 그런데, 이렇게 집단적인 린치를 당하고 있습니다.] 여야의 공방이 계속되는 가운데, 광주일고 사과 방문에 이어 5·18 묘지 참배에 나선 배재고. ''스타벅스 응원 논란'' 7일만 입니다. [앵커] 오늘 오후에 배재고등학교 야구부 학생들과 학부모, 교직원 등등 광주제일고등학교를 찾아서 야구부 학생 등에게 직접 사과했습니다. 자필로 쓴 사과문을 낭독하는 일정도 있었다고 하고요. 오늘 배재고의 사과와 광주제일고의 용서로, 사태 해결 국면에 접어들었다고 보세요? · 배재고, 광주일고 찾아 사과 · 감독·주장 ''자필 사과문'' 공개 · ''5·18 성역'' 이병태 발언 논란', 'crawl', 'JTBC', '2026-07-06 18:33:31', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/news/cms/etc/2026/07/06/20260706180423903001.jpg', '2026-07-07 06:04:45', '2026-07-07 18:42:49.315883', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4317, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/politics', 'https://news.jtbc.co.kr/article/NB12306799', 'https://news.jtbc.co.kr/article/NB12306799', '정치', '[오늘 한 컷] 학생들도 사과했건만…', '"마음의 큰 상처를 입은 광주제일고 선수들과 학부모님, 광주시민분들께 진심으로 사과드립니다." 배재고 야구부 학생들이 자필 사과문을 들고, 광주를 방문해서 직접 사과했습니다. 5·18 민주묘지도 참배하며 자신들의', '"마음의 큰 상처를 입은 광주제일고 선수들과 학부모님, 광주시민분들께 진심으로 사과드립니다." 배재고 야구부 학생들이 자필 사과문을 들고, 광주를 방문해서 직접 사과했습니다. 5·18 민주묘지도 참배하며 자신들의 뼈아픈 실수를 되돌아보았습니다. 잘못을 깨닫고 상황을 수습하려는 학생들의 용기 있는 발걸음에, 따가운 질책의 목소리도 ''용서와 화해의 박수''로 조금씩 바뀌고 있습니다. 그런데 일부 어른들은, 오히려 그 반성의 의미를 흔드는 듯합니다. 한 야당 국회의원은 "스타벅스가 5·18과 무슨 관계가 있나", "배재고 학생들과 함께합니다"라고 적힌 화환을 학교 앞으로 보냈다고 직접 알렸습니다. 또, 대통령 직속 기구 총리급 한 고위 공직자는 "5·18이 성역화되었다", "어린 학생들의 장난이다"라며 ''표현의 자유''를 들이댔습니다. 국가 폭력에 희생된 아픔을 조롱한 행동은 질책받아 마땅합니다. 꽃을 보내 응원할 일도 아니고, ''치기 어린 장난''이라며 ''표현의 자유''를 들먹일 일도 아닙니다. 학생들은 자신의 잘못을 인정했고, 피해자를 찾아가 사과했고, 다시는 그러지 않겠다고 다짐했습니다. 그렇다면 이제 어른들이 해야 할 것은, 그 잘못을 두둔하거나 ''정치 도구''로 활용하는 것이 아니라, 함께 되새기고 반성하는 일입니다. 오늘 한 컷이었습니다.', 'crawl', 'JTBC', '2026-07-06 18:32:56', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/news/cms/etc/2026/07/06/20260706183053430001.jpg', '2026-07-07 06:04:45', '2026-07-07 18:42:51.192855', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4329, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/economy', 'https://news.jtbc.co.kr/article/NB12306979', 'https://news.jtbc.co.kr/article/NB12306979', '경제', '나스닥 상장 앞둔 SK하이닉스…증권신고서에 담긴 투자 위험 요인?', 'SK하이닉스가 국내 반도체 기업 최초로 오는 10일 미국 나스닥 시장에 약 43조원 규모의 미국주식예탁증서(ADR)를 상장하며 본격적인 기업 가치 재평가 시험대에 오릅니다. 시장의 뜨거운 기대감 속에서도 SK하이닉스', 'SK하이닉스가 국내 반도체 기업 최초로 오는 10일 미국 나스닥 시장에 약 43조원 규모의 미국주식예탁증서(ADR)를 상장하며 본격적인 기업 가치 재평가 시험대에 오릅니다. 시장의 뜨거운 기대감 속에서도 SK하이닉스는 증권신고서를 통해 투자자들이 유의해야 할 구체적인 위험 요소를 직접 명시했습니다. 기업이 지목한 첫 번째 리스크는 생산시설 확충 지연에 따른 시장 주도권 상실과 공급 부족으로 인한 글로벌 고객사 이탈 가능성입니다. 특히 최근 메모리 3사를 상대로 제기된 반독점 위반 소송 등 규제 리스크와 더불어, 대규모 투자 이후 경기 변동 주기에 맞물려 발생할 수 있는 공급 과잉 우려도 함께 언급되었습니다. 아울러 SK하이닉스는 미국 증시 상장이 무조건적인 주가 상승을 보장하지는 않으며, 국내 본국 주가와 미국 ADR 주가 간의 직접적인 동조화 경향성은 발견되지 않았다고 주의를 당부했습니다. +++ SK하이닉스는 43조원 규모의 미국주식예탁증서(ADR)발행으로 오는 10일 미국 나스닥 상장을 앞두고 있습니다. 이번 상장은 국내 반도체 기업 최초로 세계 최대 규모의 미 증시에 입성하는 사례인 만큼 기업 가치의 본격적인 재평가 계기가 마련될 것이라는 시장의 기대감으로 이어졌습니다. SK하이닉스가 상장을 위해 제출한 증권신고서에 따르면 장밋빛 전망만 담긴 게 아닌 투자자들이 반드시 유의해야 할 위험 요소도 함께 명시됐습니다. 기업이 지목한 첫 번째 위험 요인, 생산시설 확충 지연에 따른 시장 주도권 상실 가능성으로 AI 메모리 수요 증가를 적절한 시점에 대응하지 못할 때 고객 이탈이 우려된다고 설명했습니다. 현재, 용인과 청주에 건설 중인 공장만으로는 향후 글로벌 메모리 수요를 감당하기 어려워 또 다른 대형 생산 거점 확보가 불가피한 상황이라는 점을 분명히 한 겁니다. 길어지는 공급 부족에 따른 고객사 이탈과 규제 리스크도 투자 위험 요인입니다. 공급 부족 현상으로 메모리 가격이 급등할 땐 대체 공급선 확보 움직임이 커질 수 있다는 건데 실제 미국 소비자들과 기업은 최근 SK하이닉스를 포함한 메모리 3사를 상대로 반독점 위반 소송을 제기한 바 있습니다. 끝으로 SK하이닉스는 대규모 설비 투자 이후에 발생할 수 있는 공급 과잉을 우려하며 생산시설 확충을 마친 뒤 수요가 둔화될 경우 기업 실적에 부정적인 영향을 미칠 수 있다고 언급했습니다. 메모리 반도체 사업이 전체 매출의 90% 이상을 차지하기 때문에 2~3년을 주기로 하는 경기 변동에 진입하게 된다면 투자 과잉 부담이 가중될 수밖에 없다는 분석입니다.', 'crawl', 'JTBC', '2026-07-07 13:10:48', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/etc/2026/07/07/20260707130931241001.png', '2026-07-07 06:04:46', '2026-07-07 18:43:15.912776', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4332, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/economy', 'https://news.jtbc.co.kr/article/NB12306945', 'https://news.jtbc.co.kr/article/NB12306945', '경제', '구윤철 "7월말 부동산세제 발표…보유세·거래세 균형 이뤄야"', '구윤철 부총리 겸 재정경제부 장관이 부동산 세제 개편과 관련해 "7월 말 정도 (발표를) 생각하고 있다"며 "지금 준비 중"이라고 밝혔습니다. 오늘(7일) 구 부총리는 MBC 라디오 ''김종배의 시선집중'' 인터뷰에서', '구윤철 부총리 겸 재정경제부 장관이 지난 3일 세종시 정부세종청사에서 열린 비상경제본부 회의 겸 경제관계장관회의를 주재하고 있다. 〈사진=연합뉴스〉 구윤철 부총리 겸 재정경제부 장관이 부동산 세제 개편과 관련해 "7월 말 정도 (발표를) 생각하고 있다"며 "지금 준비 중"이라고 밝혔습니다. 오늘(7일) 구 부총리는 MBC 라디오 ''김종배의 시선집중'' 인터뷰에서 이같이 밝혔습니다. 이어 ''보유세와 거래세를 함께 개편할 것이냐''는 물음에 "두 가지가 밸런스를 이루어야 한다. 그런 차원에서 함께 보고 있다"고 말했습니다. 구 부총리는 "기본적으로 집은 바잉, 사는 것이 아니고 리빙(living·거주)이라는 그런 원칙 하에 실거주자 중심으로 한 주택시장이 확립할 수 있도록 하는 차원에서 세제를 보고 있다"고 했습니다. 이어 "그것도 정부가 일방적으로 결정하기보다는 폭넓게 국민들의 의견을 경청하고 거기에 따라서 최대한 반영하려고 한다"며 "조만간 부동산 세제와 관련해 국민 의견을 수렴하는 절차를 밟을 것"이라고 덧붙였습니다. 또 구 부총리는 공정시장가액비율 조정, 비거주 장기보유특별공제 혜택 축소 등을 다룬 언론 전망에 대한 질문에는 "언론에서 말하는 것도 국민의 한 의견이라 생각한다"고 답했습니다. 그러면서도 "다양한 목소리가 있기 때문에 다 들어보고 어떤 게 가장 실거주 중심 주택시장을 확립하는 데 도움이 될까 하는 차원에서 최종 판단하려고 한다"고 설명했습니다.', 'crawl', 'JTBC', '2026-07-07 09:23:49', '진보', 'ready', 'https://photo.jtbc.co.kr/news/jam_photo/202607/07/7528e56c-83ca-4ddd-9ea0-7d741f9667d9.jpg', '2026-07-07 06:04:46', '2026-07-07 18:43:21.438906', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4356, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/society', 'https://news.jtbc.co.kr/article/NB12306962', 'https://news.jtbc.co.kr/article/NB12306962', '사회', '광주제일고, 5.18 폄훼 응원 논란 배재고 선처 촉구..."징계 6개월 처분 과해"', '배재고등학교 야구부가 5·18 민주화운동을 조롱하는 응원 구호로 징계를 받은 사안과 관련해 광주제일고가 선처를 촉구하기로 했습니다. 광주제일고 총동창회는 오늘(7일) 오후 5시쯤 기자회견을 열고 "배재고 야구선수들', '배재고등학교 야구부가 5·18 민주화운동을 조롱하는 응원 구호로 징계를 받은 사안과 관련해 광주제일고가 선처를 촉구하기로 했습니다. 광주제일고 총동창회는 오늘(7일) 오후 5시쯤 기자회견을 열고 "배재고 야구선수들', 'rss', 'JTBC', '2026-07-07 11:04:38', '진보', 'crawl_failed', NULL, '2026-07-07 06:04:46', '2026-07-07 18:44:08.638024', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4358, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/society', 'https://news.jtbc.co.kr/article/NB12306949', 'https://news.jtbc.co.kr/article/NB12306949', '사회', '검찰, ''장윤기 증거인멸 의혹'' 광주 광산경찰서 압수수색', '검찰이 장윤기 증거인멸 의혹과 관련해 광주 광산경찰서를 압수수색하고 있습니다. 오늘(7일) 광주지방검찰청은 공무상비밀누설 및 증거인멸 등의 혐의로 광산경찰서와 당시 수사팀원 등 주요 피의자의 주거지 등에 대해 압수', '살인·살인미수 혐의를 받는 장윤기가 지난 5월 14일 광주 서부경찰서에서 검찰로 송치되고 있다. 〈사진=연합뉴스〉 검찰이 장윤기 증거인멸 의혹과 관련해 광주 광산경찰서를 압수수색하고 있습니다. 오늘(7일) 광주지방검찰청은 공무상비밀누설 및 증거인멸 등의 혐의로 광산경찰서와 당시 수사팀원 등 주요 피의자의 주거지 등에 대해 압수수색을 진행하고 있다고 밝혔습니다. 입건된 수사팀원들은 지난 5월 5일 장윤기를 긴급체포한 뒤 수사 과정에서 케이블타이와 리얼돌, 차량 등 주요 증거물을 확보하지 않은 혐의를 받습니다. 또한 현직 경찰인 장윤기의 부친에게 압수수색과 구속영장 내용 등 수사 상황을 누설한 혐의도 함께 받습니다. 광주경찰청도 ''장윤기 사건'' 수사 관련 각종 의혹을 밝히기 위해 수사전담팀을 편성해 수사를 진행하고 있습니다. 광주경찰청은 증거인멸 정황을 일부 포착해 당시 수사를 담당했던 광산경찰서 수사팀장 A경감을 어제(6일) 긴급 체포했습니다.', 'crawl', 'JTBC', '2026-07-07 09:48:04', '진보', 'ready', 'https://photo.jtbc.co.kr/news/jam_photo/202607/07/52351307-0ec8-4f97-bd9e-666250916bf6.jpg', '2026-07-07 06:04:46', '2026-07-07 18:44:13.336798', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4361, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/society', 'https://news.jtbc.co.kr/article/NB12306922', 'https://news.jtbc.co.kr/article/NB12306922', '사회', '배재고 눈물의 사과에…광주제일고 "어깨 펴시고" 용서', '[앵커] 5·18 민주화운동을 조롱하는 구호로 물의를 빚은 배재고 야구부 선수들이 광주를 찾아 직접 사과했습니다. 눈물로 사과문을 읽고 성찰을 약속했고, 광주일고 역시 사과를 받아들였습니다. 두 학교 선수들은 5·', '[앵커] 5·18 민주화운동을 조롱하는 구호로 물의를 빚은 배재고 야구부 선수들이 광주를 찾아 직접 사과했습니다. 눈물로 사과문을 읽고 성찰을 약속했고, 광주일고 역시 사과를 받아들였습니다. 두 학교 선수들은 5·18 민주묘지에 함께 가서 참배했습니다. 정진명 기자입니다. [기자] 광주제일고와 경기에서 5·18 민주화운동을 조롱하는 듯한 응원 구호를 외쳐 물의를 일으킨 서울 배재고 야구 선수들. [가야지, 가야지. 스타벅스 가야지. 탱크 데이.] 두 학교 선수들이 일주일 만에 다시 만났습니다. 배재고 야구부 감독과 선수, 교장과 학부모 등 80여 명이 사과하기 위해 광주제일고를 찾은 겁니다. 감독과 선수들은 인성과 태도의 중요성을 깨달았다며 직접 쓴 사과문을 읽어 내려갔습니다. [서울 배재고 야구부 주장 : 부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주제일고 선수들과 학부모님, 그리고 광주 시민분들께 진심으로 사과드립니다.] 배재고 교장은 학생들과 함께 배우고 성찰하겠다며 울먹였습니다. [이효준/서울 배재고 교장 : 배재는 광주학생독립운동과 5·18민주화운동의 정신을 잊지 않고 있습니다. 가슴속 깊이 진심으로 사과드립니다. 죄송합니다.] 광주 제일고 선수들도 다른 팀에게 상처를 준 언행이 없었는지 되돌아보는 계기가 됐다고 말했습니다. [광주 제일고 야구부 주장 : 이번 일을 통해서 다시는 이런 일이 발생하지 않도록 그런 환경이 조성되었으면 좋겠습니다.] 사과를 받아들인 광주제일고는 배재고 선수들이 위축되지 않고 성장하기를 바랐습니다. [이규연/광주 제일고 교장 : 여러분의 미래는 아직 끝나지 않았습니다. 충분히 여러분들 다시 생활할 수 있을 테니까 어깨 펴시고. 더 중요한 것은 앞으로 더 잘사는 겁니다.] 용서와 화해의 악수를 나눈 두 학교 선수들은 광주학생독립운동기념탑에 헌화를 한 뒤 5·18 민주묘지를 참배했습니다. [영상취재 장정원 영상편집 배송희]', 'crawl', 'JTBC', '2026-07-07 08:21:09', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/news/cms/etc/2026/07/07/20260707082056159001.png', '2026-07-07 06:04:46', '2026-07-07 18:44:20.073215', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4362, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/society', 'https://news.jtbc.co.kr/article/NB12306923', 'https://news.jtbc.co.kr/article/NB12306923', '사회', '중앙선관위 "올림픽공원 투표용지 재검표 추진…비용 직접 부담"', '중앙선거관리위원회가 올림픽공원에 보관하고 있는 투표용지에 대한 재검표를 추진하겠다고 밝힌 것으로 전해졌습니다. 어제(6일) MBC에 따르면 중앙선거관리위원회는 더불어민주당 김남희 의원실에 제출한 2차 현장검증 현안', '지난 10일 투표용지 부족사태로 진상규명위원회 제1차 회의가 개최된 중앙선관위 과천청사의 모습. 〈사진=연합뉴스〉 중앙선거관리위원회가 올림픽공원에 보관하고 있는 투표용지에 대한 재검표를 추진하겠다고 밝힌 것으로 전해졌습니다. 어제(6일) MBC에 따르면 중앙선거관리위원회는 더불어민주당 김남희 의원실에 제출한 2차 현장검증 현안보고서에서 올림픽공원 핸드볼경기장에 남아있는 투표용지를 이송하기 전 재검표를 진행하겠다고 국회에 보고했습니다. 다만 현행 법규상 선관위가 자체적으로 재검표를 실시할 법적 근거는 없어 국회 국정조사특별위원회의 의결이 선행돼야 한다고 설명했습니다. 선관위는 재검표 비용 약 5000만원을 직접 부담하겠다고 제안했습니다. 또 440명을 투입하면 전체 247만표를 재검표하는 데 약 9시간이 걸릴 것으로 전망했습니다. 올림픽공원에 보관 중인 투표용지 가운데 서울시장 선거 투표용지 37만표만 재검표할 경우에는 200명을 투입해 약 5시간이 걸릴 것으로 예상했습니다. 비용은 2200만원으로 추산했습니다. 재검표는 육안으로 투표지를 다시 확인한 뒤 정당별·후보자별 분류가 맞는지 확인하는 방식으로 진행됩니다. 이후 심사계수기로 투표지 매수를 확인해 기존 개표 상황표와 일치하는지 검증할 예정입니다. 선관위는 재검표 과정을 국회 국정조사특위 위원과 정당·후보자 추천 참관인, 언론 등에 공개하겠다고 밝혔습니다. 재검표가 끝나면 투표용지는 경기도 과천 중앙선관위 선거홍보관으로 옮길 계획입니다. 선관위는 올림픽공원 핸드볼경기장의 본래 기능을 회복하고 국민적 불안과 의혹을 해소하기 위한 조치라고 설명했습니다. 또 선거홍보관 출입구에는 이송 참관인이 서명한 특수 봉인지를 부착하고 CCTV를 설치해 출입을 관리할 예정입니다. 앞서 국민의힘 소속 윤상현 국정조사특위 위원장은 1차 현장조사에서 선관위에 투표용지 재검표를 제안했습니다. 윤 위원장은 "247만표를 공개적으로 재검증해 잘못된 투·개표가 없었다는 것을 보여달라는 의미"라며 "여야 간사가 협의해달라"고 요청했습니다. 국회 국정조사특위는 오늘(7일) 중앙선관위와 송파구선관위를 방문해 현장조사를 실시합니다.', 'crawl', 'JTBC', '2026-07-07 07:41:05', '진보', 'ready', 'https://photo.jtbc.co.kr/news/jam_photo/202607/07/1207f413-c846-49c9-bc92-bdcd38da36ba.jpg', '2026-07-07 06:04:46', '2026-07-07 18:44:21.975828', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4372, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/society', 'https://news.jtbc.co.kr/article/NB12306865', 'https://news.jtbc.co.kr/article/NB12306865', '사회', '배재고 사과 받아준 광주제일고…"어깨 펴" 화해의 악수', '[앵커] 5·18 민주화운동을 조롱하는 구호로 물의를 빚은 배재고 야구부 선수들이 오늘 광주제일고를 찾아 사과하며 고개를 숙였습니다. 자필로 쓴 사과문을 읽었고 앞으로 성찰하고 배우겠다고 했습니다. 광주제일고 측도', '[앵커] 5·18 민주화운동을 조롱하는 구호로 물의를 빚은 배재고 야구부 선수들이 오늘 광주제일고를 찾아 사과하며 고개를 숙였습니다. 자필로 쓴 사과문을 읽었고 앞으로 성찰하고 배우겠다고 했습니다. 광주제일고 측도 사과를 받아들였습니다. 두 학교 선수들은 민주묘지에 함께 가서 참배했습니다. 정진명 기자가 보도합니다. [기자] 광주제일고와 경기에서 5·18 민주화운동을 조롱하는 듯한 응원 구호를 외쳐 물의를 일으킨 서울 배재고 야구 선수들. [가야지, 가야지. 스타벅스 가야지. 탱크 데이.] 두 학교 선수들이 일주일 만에 다시 만났습니다. 배재고 야구부 감독과 선수, 교장과 학부모 등 80여 명이 사과하기 위해 광주제일고를 찾은 겁니다. 감독과 선수들은 인성과 태도의 중요성을 깨달았다며 직접 쓴 사과문을 읽어 내려갔습니다. [서울 배재고 야구부 주장 : 부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주제일고 선수들과 학부모님, 그리고 광주 시민분들께 진심으로 사과드립니다.] 배재고 교장은 학생들과 함께 배우고 성찰하겠다며 울먹였습니다. [이효준/서울 배재고 교장 : 배재는 광주학생독립운동과 5·18민주화운동의 정신을 잊지 않고 있습니다. 가슴속 깊이 진심으로 사과드립니다. 죄송합니다.] 광주 제일고 선수들도 다른 팀에게 상처를 준 언행이 없었는지 되돌아보는 계기가 됐다고 말했습니다. [광주 제일고 야구부 주장 : 이번 일을 통해서 다시는 이런 일이 발생하지 않도록 그런 환경이 조성되었으면 좋겠습니다.] 사과를 받아들인 광주제일고는 배재고 선수들이 위축되지 않고 성장하기를 바랐습니다. [이규연/광주 제일고 교장 : 여러분의 미래는 아직 끝나지 않았습니다. 충분히 여러분들 다시 생활할 수 있을 테니까 어깨 펴시고. 더 중요한 것은 앞으로 더 잘사는 겁니다.] 용서와 화해의 악수를 나눈 두 학교 선수들은 광주학생독립운동기념탑에 헌화를 한 뒤 5·18 민주묘지를 참배했습니다. [영상취재 장정원 영상편집 배송희]', 'crawl', 'JTBC', '2026-07-06 19:44:00', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/news/cms/etc/2026/07/06/20260706185656945001.jpg', '2026-07-07 06:04:46', '2026-07-07 18:44:50.837859', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4377, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/society', 'https://news.jtbc.co.kr/article/NB12306833', 'https://news.jtbc.co.kr/article/NB12306833', '사회', '배재고 야구부, 광주 찾아 사과…"항상 반성하는 마음으로 살겠다"', '"항상 깊이 반성하는 마음과 자세로 살아가겠습니다" 한 글자씩 꾹 눌러쓴 자필 사과문. 배재고 야구부 선수 36명이 오늘(6일) 광주제일고등학교를 찾아 공식 사과했습니다. 학부모와 교직원들도 함께 했습니다. 배', '"항상 깊이 반성하는 마음과 자세로 살아가겠습니다" 한 글자씩 꾹 눌러쓴 자필 사과문. 배재고 야구부 선수 36명이 오늘(6일) 광주제일고등학교를 찾아 공식 사과했습니다. 학부모와 교직원들도 함께 했습니다. 배재고 야구부 주장은 "부적절한 발언으로 상처를 입은 광주일고 선수들과 광주 시민께 진심으로 사죄드린다"며 고개를 숙였습니다. "모든 선수가 진심으로 깊이 반성하고 있다"며 "야구를 떠나서 인성이나 태도가 인생에 얼마나 중요한지 깨닫고 다시 한번 배우게 됐다"고 전했습니다. 배재고 야구부 감독 또한 "선수들의 지역 비하 응원은 무엇으로도 변명할 수 없는 잘못"이라며, "상대에 대한 존중과 동업자 정신, 선수로서 가져야 할 태도에 대해 제대로 가르치고 인도하지 못했다"며 지도자로서의 책임을 통감했습니다. "이기는 것보다 더 중요한 것이 있음을 잊고 있었다"며 "이번 사태를 단순한 일탈이나 실수가 아닌 윤리의식과 역사 인식에 대한 총체적 붕괴에서 비롯된 사례로 받아들이고 있다"고 밝혔습니다. 학교 측은 자체 진상조사와 징계 절차를 진행하고 있습니다. 서울시교육청도 자세한 경위를 파악한 뒤 결과에 따라 교장·교감 등 관리자 책임을 물을지 검토할 방침입니다.', 'crawl', 'JTBC', '2026-07-06 17:08:39', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/etc/2026/07/06/20260706180708551001.png', '2026-07-07 06:04:46', '2026-07-07 18:45:00.253468', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4379, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/society', 'https://news.jtbc.co.kr/article/NB12306819', 'https://news.jtbc.co.kr/article/NB12306819', '사회', '광주서 고개 숙인 배재고…"인성·태도 중요성 깨달아" 사과문 전달', '5·18 광주를 비하하는 이른바 ''스타벅스 구호''로 논란이 된 배재고등학교 야구부 학생들이 광주제일고등학교를 방문해 "진심으로 사과드린다"며 고개를 숙였습니다. 서울시교육청에 따르면 배재고 야구부 전원과 학부모,', '6일 오후 전남광주통합특별시 북구 광주제일고등학교 강당에서 배재고 야구부 선수(왼쪽)가 광주일고 야구부 선수에게 사과문을 전달한 뒤 인사하고 있다. 〈사진=공동취재〉 5·18 광주를 비하하는 이른바 ''스타벅스 구호''로 논란이 된 배재고등학교 야구부 학생들이 광주제일고등학교를 방문해 "진심으로 사과드린다"며 고개를 숙였습니다. 서울시교육청에 따르면 배재고 야구부 전원과 학부모, 교직원 등 86명은 오늘(6일) 광주일고를 방문해 사과했습니다. 배재고 야구부 주장은 선수단 명의 자필 사과문을 통해 "우리가 광주에 발을 딛는 것만으로도 불편했을 텐데 이렇게 귀한 시간 마련해주신 광주일고 관계자들과 선수들께 진심으로 감사드린다"고 말했습니다. 이어 "꿈과 희망이 담겨야 하는 야구장에서 배재고 선수들의 부적절한 발언과 행동들로 인해 마음의 큰 상처를 입은 광주일고 선수들과 학부모, 광주 시민들께 진심으로 사과드린다"며 "이번 사건으로 저를 포함한 팀 모든 선수들이 진심으로 깊이 반성하고 있으며 야구를 떠나 인성이나 태도가 인생에서 얼마나 중요한지 깨닫고 다시 한번 배우게 됐다"고 했습니다. 그러면서 "광주일고 선수들께 정신적으로 큰 피해와 힘듦을 겪게 한 점, 같은 선수로서 정말 하면 안 되는 행동이었고 일어나면 안 되는 상황이었는데 많은 고통을 드렸다"며 "저희 선수들의 좋지 못한 발언, 행동으로 인해 정말 많은 분이 마음의 상처와 고통을 받고 계신다. 항상 마음 속 깊이 반성하는 마음과 자세로 살아가겠다"고 밝혔습니다. 배재고 야구부 선수단과 감독의 사과문. 〈사진=서울시교육청 제공〉 권오영 배재고 야구부 감독도 자필 사과문에서 "무엇으로도 변명할 수 없는 잘못임을 인정하며 학생들을 잘 이끌고 가르쳐야 할 지도자로서 저의 책임이 가장 크기에 진심으로 사죄드린다"고 사과했습니다. 이어 "깨끗하고 정정당당해야 할 경기에서 상대에 대한 존중과 동업자 정신을 비롯한 학생 선수로서 가져야 할 태도에 대해 제대로 가르치고 인도하지 못했다"며 "승패에만 집중하느라 잘못된 응원 소리를 바로 파악하지 못했고 제때 제지하지 못했다는 말은 변명에 지나지 않는다는 것도 너무도 잘 알고 있다"고 말했습니다. 또한 "이기는 것보다 더 중요한 것이 있음을 저도 모르게 잊고 있었고 저의 언행과 지도 방식이 올바른 본보기가 되지 못한 듯해 더욱 깊이 자책하며 부끄러울 뿐"이라며 "배재고 학생 선수들의 잘못 이전에 제대로 가르치고 이끌지 못한 저의 과오를 인정하며 지도자로서 져야 할 책임을 겸허히 감당하고자 한다"고 했습니다. 마지막으로 권 감독은 "저의 사죄가 모든 분의 상처를 달래기에는 한없이 부족하겠지만 제가 할 수 있는 모든 최선을 다해 끊임없이 사죄하고 다시는 이런 일들이 반복되지 않도록 지도자로서의 책임을 끝까지 다하겠다"고 전했습니다. 배재고 측은 5·18 민주 묘지도 참배할 계획인 것으로 알려졌습니다. 최근 배재고 선수들은 전국고교야구선수권대회에서 상대 팀이자 광주가 연고인 광주일고를 향해 "가야지, 가야지, 스타벅스 가야지"라고 반복해 외쳐 비판을 받았습니다. 앞서 스타벅스는 ''탱크데이''라는 문구를 마케팅에 사용해 5·18을 희화화했다는 비판을 받았는데, 배재고 선수들이 이를 인용해 광주일고를 조롱했다는 지적에 휩싸인 겁니다. 대한야구소프트볼협회는 배재고 야구팀에 대해 전국대회 6개월 출전정지를 결정했습니다. 이는 해당 조항으로 내릴 수 있는 최대치 중징계입니다. 배재고는 해당 구호를 선창한 학생 2명을 생활교육위원회에 회부하기로 결정했습니다. 동조한 학생들을 추가로 회부하는 방안도 검토하고 있습니다.', 'crawl', 'JTBC', '2026-07-06 16:34:06', '진보', 'ready', 'https://photo.jtbc.co.kr/news/jam_photo/202607/06/5a3b4184-2d0c-4ba4-9785-b9d2f4dc5a76.jpg', '2026-07-07 06:04:46', '2026-07-07 18:45:04.023079', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4397, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/international', 'https://news.jtbc.co.kr/article/NB12306828', 'https://news.jtbc.co.kr/article/NB12306828', '국제', '분노의 이란 초등생 폭사 유가족들, 최고지도자 장례식 참석', '이란 전쟁 첫날 미군의 공습으로 숨진 초등학교 어린이들 부모 등 유족들이 전 이란 최고지도자 아야톨라 세예드 알리 하메네이의 장례식에 참석했다고 미국 워싱턴포스트가 보도했습니다. 지난 2월 28일 미군은 대규모 군', '지난 5일 이란 수도 테헤란에 설치된 아야톨라 세예드 알리 하메네이의 추도 행사장에 걸려 있는 이란 남부 미나브 소재 초등학교 공습 피해 어린이들의 사진. 〈사진출처=연합뉴스〉 이란 전쟁 첫날 미군의 공습으로 숨진 초등학교 어린이들 부모 등 유족들이 전 이란 최고지도자 아야톨라 세예드 알리 하메네이의 장례식에 참석했다고 미국 워싱턴포스트가 보도했습니다. 지난 2월 28일 미군은 대규모 군사시설이 있는 이란 남부 호르모즈간주(州)의 소도시 미나브의 초등학교를 공습했습니다. 토마호크 미사일로 추정되는 무기가 사용된 공습으로 최소 175명의 민간인이 숨졌는데, 대부분은 어린이였습니다. 미국 워싱턴포스트에 따르면 이날 숨진 어린이들의 유족은 기차와 자동차, 버스 등을 타고 수도 테헤란 장례식장까지 이동했습니다. 이란 수도 테헤란과는 약 1300㎞ 떨어진 곳으로 각자 버스와 기차 등을 이용해 수일 동안 이동한 건데, 초등학교 공습과 같은 날 테헤란 공습에서 숨진 최고 지도자 알리 하메네이의 장례식에 참석하기 위해서입니다. 워싱턴포스트는 이란 정부의 취재 초청으로 전쟁 시작 이후 처음으로 이란에서 보도할 기회를 얻었다고 했습니다. 워싱턴포스트는 "미국이 미나브 초등학교 공습 책임을 인정하지 않고 있지만 영상 증거와 취재로 해당 학교가 미국의 표적 목록에 올라 있었음이 사실상 확인됐다"고 전했습니다. 미국 전쟁부는 이번 공습에 대한 조사 결과를 4개월이 넘도록 내놓지 않고 있습니다. 워싱턴포스트는 "알리 하메네이 장례식에 대해 저명한 신학자인 아야톨라 자파르 소브하니가 기도를 주재했다"면서 "하메네이의 차남이며 현 최고지도자인 아야톨라세예드모즈타바 하메네이가 공개석상에 나와 장례 기도를 이끌 것으로 기대했지만 나타나지 않았다"고 전했습니다. 장례식 이후 하메네이의 시신은 고향인 이란 동부 마슈하드에 안장될 예정입니다.', 'crawl', 'JTBC', '2026-07-06 17:04:00', '진보', 'ready', 'https://photo.jtbc.co.kr/news/jam_photo/202607/06/7c1c0d63-d707-4ad8-8dae-707ee7ce92d8.jpg', '2026-07-07 06:04:46', '2026-07-07 18:45:39.730093', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4398, 'https://news-ex.jtbc.co.kr/v1/get/rss/section/international', 'https://news.jtbc.co.kr/article/NB12306798', 'https://news.jtbc.co.kr/article/NB12306798', '국제', '하메네이 장례에 모인 세 아들, 모즈타바는 없었다...''초교 오폭 참사'' 유가족도 참석', '- 아야톨라 하메네이 이란 전 최고지도자의 장례식에 세 아들이 참석해 공개적으로 애도를 표했습니다. 후계자인 차남 모즈타바는 이번에도 모습을 드러내지 않았습니다. 장례식은 미국과 트럼프 미국 대통령에 대한 보복을 촉', '- 아야톨라 하메네이 이란 전 최고지도자의 장례식에 세 아들이 참석해 공개적으로 애도를 표했습니다. 후계자인 차남 모즈타바는 이번에도 모습을 드러내지 않았습니다. 장례식은 미국과 트럼프 미국 대통령에 대한 보복을 촉구하는 반미 집회를 방불케 한 가운데, 최악의 오폭 참사로 꼽히는 이란 남부의 미나브 초등학교 희생자 유가족들도 참석했습니다. 영상으로 확인해보시죠. 미군 공습에 폭사한 하메네이 전 이란 최고지도자의 장례식 장남 모스타파와 셋째 마수드, 막내 메이삼 등 성직자 세 아들 참석해 공개 애도 후계자 차남 모즈타바는 불참 공습으로 중상 입은 뒤 공개 석상에 모습 드러내지 않아 오는 10일 예정된 매장식에 등장할지 관심 사흘째 맞은 장례식은 반미 집회 방불케 해 미국과 영국 국기 불태우는가 하면 트럼프 미국 대통령에 대한 보복 촉구 [모하마드 라술리 / 이란 종교시인] "당신의 피를 걸고 맹세한다. 트럼프를 암살하는 것은 우리의 의무다." 오폭으로 희생된 미나브 초교 희생자 유가족도 참석 미나브 공습은 하메네이 폭사한 날과 같은 날 발생 토마호크 미사일 추정되는 무기로 공습 가해져 최소 175명 숨져 당시 사망자 대부분은 어린이 유족들 "이란 사람들이 어떤 대우를 받는지 전 세계 사람들이 알아야 한다"', 'crawl', 'JTBC', '2026-07-06 15:28:38', '진보', 'ready', 'https://thumb.jtbc.co.kr/photo/r600x0/etc/2026/07/06/20260706152556616001.png', '2026-07-07 06:04:46', '2026-07-07 18:45:41.616312', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4401, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=01&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645595', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645595&plink=RSSLINK&cooper=RSSREADER', '정치', '민형배 시장 "군공항 이전 전에도 반도체 산단 착수 가능"', '&#9650; 민형배 전남광주통합특별시장이 7일 광주 군공항 인근 공군 탄약고 부지를 점검하고 있다. 정부는 호남권 반도체 클러스터 부지로 광주…', '▲ 민형배 전남광주통합특별시장이 7일 광주 군공항 인근 공군 탄약고 부지를 점검하고 있다. 정부는 호남권 반도체 클러스터 부지로 광주 군공항을 선정했다. 민형배 전남광주통합특별시장이 호남권 반도체 클러스터 입지로 확정된 광주 군공항 부지에 대해 "군공항이 완전히 이전하지 않아도 반도체 산단 조성을 시작할 수 있다"고 밝혔습니다. 민 시장은 오늘(7일) 광주 광산구 도산동·신촌동 일원 군공항 대상 부지를 찾아 기자들에게 현황을 설명하며 "이곳은 사전 절차가 거의 필요 없는 곳으로, 속도전을 내는 데 아주 좋다"고 말했습니다. 어제 정부가 호남권 반도체 클러스터 부지로 특정한 곳은 광주송정역에서 약 1㎞ 떨어진 군공항 일원으로, 현 군공항 부지와 탄약고 예정 부지 등을 포함해 전체 면적은 약 8.2㎢(248만 평)입니다. 민 시장은 "이곳 대부분이 국유지이고 평지라 산단 조성에 최적"이라며 "주민 수용성 문제가 거의 없어 이런 조건을 갖춘 땅은 찾기 어렵다"고 강조했습니다. 다만 산단 조성 과정에서 군공항 이전, 군사시설 정비, 미군 관련 시설, 유류 저장시설과 송유관 처리 등이 과제로 남아 있다고 설명했습니다. 그는 "군공항 관련 이슈 중 하나는 유류 저장시설"이라며 "오랫동안 유류 탱크가 있었던 만큼 환경오염 우려가 있었지만, 관련 정화 작업은 거의 끝난 것으로 점검했다"고 밝혔습니다. 이어 "미군이 사용하는 시설과 연결된 송유관이 부지 일부 구간에 남아 있어 이를 어떻게 처리할 것인지도 검토해야 한다"고 덧붙였습니다. 이러한 과제들이 산단 착수 자체를 막는 요인은 아니라고 봤습니다. 민 시장은 "현재 공군 훈련 문제만 정리되면 군공항 이전과 상관없이 일단 시작할 수 있다"며 "부지를 결정했으니 송전선로, 전력, 용수 확보도 동시에 시작해야 속도전이 작동할 수 있다"고 했습니다. 전력 수급에 대해서는 장성 신장성변전소와의 연계 가능성을 언급하며 "반도체 팹 1기에 1GW 정도가 필요하고, 단전이 없도록 복선화까지 검토해야 한다"고 설명했습니다. 용수에 대해서도 "팹 1기에 6만t, 안정적으로는 10만t 정도가 필요하다"며 "관로만 연결하면 4기까지 공급하는 데 문제가 없다고 보고 있다"고 말했습니다. 민 시장은 구체적인 로드맵은 기업·정부 협의가 필요하다면서도 "속도전의 본질은 기업이 하려다 마는 일이 없도록 하는 것"이라며 "대통령 임기와 지방정부 임기 안에 사업을 안착시키는 것이 목표"라고 밝혔습니다. 전남광주통합특별시는 오늘 오후 반도체 전략위원회 현판식을 열고, 부지·전력·용수·인허가 등 후속 절차를 총괄할 실무지원 체계를 본격적으로 가동할 예정입니다. (사진=연합뉴스)', 'crawl', 'SBS', '2026-07-07 14:48:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260707/202199757_1280.jpg', '2026-07-07 06:04:47', '2026-07-07 18:45:45.81035', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4408, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=01&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645228', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645228&plink=RSSLINK&cooper=RSSREADER', '정치', '김민석, ''계엄해제 표결 불참'' 공세에 "대장동 때 보는 듯"', '&#9650; 더불어민주당 당권주자인 김민석 전 국무총리가 6일 국회 소통관에서 당 대표 출마 선언 기자회견을 하고 있다.민주당 당 대표 선거에…', '▲ 더불어민주당 당권주자인 김민석 전 국무총리가 6일 국회 소통관에서 당 대표 출마 선언 기자회견을 하고 있다. 민주당 당 대표 선거에 출마한 김민석 전 총리는 12·3 비상계엄 당시 자신이 국회의 계엄 해제 표결에 불참한 점을 두고 친청(친정청래)계가 공세를 펴는 데 대해 "무슨 꼭 대장동 때를 보는 것 같다"고 역공했습니다. 김 전 총리는 7일 KBS 라디오 인터뷰에서 해당 비판에 대해 "''국민의힘에서 누가 얘기를 하나''라고 생각했다"면서 이같이 말했습니다. 그의 이런 언급은 ''계엄 해제 표결 불참''에 대한 친청(친정청래)계의 공세를 과거 국민의힘 등이 대장동 사건으로 이재명 대통령을 비난하던 것에 빗댄 것입니다. 앞서 김 전 총리는 2024년에 12·3 비상계엄 사태 이전부터 계엄 선포 가능성을 거론했으나 실제 계엄 사태가 발생했을 당시 국회의 계엄 해제 표결에는 불참했습니다. 그는 이후 당시 감기약을 먹고 잤다고 해명한 바 있습니다. 이를 두고 친청계 이성윤 의원은 전날 "감기약을 드시고 주무셨다고 하는데 약 성분이 무엇인가. 자는 사람은 깨울 수 있어도 자는 척하는 사람은 깨울 수 없다고 하던데 그런가"라고 공세를 폈습니다. 이에 김 전 총리는 이날 "그때 표결하는 시점에 국회 안에 있었고, 표결 직후에 본회의장에 착석했다"라고 말한 뒤 "이 의원이 말한 게 ''계엄과 관련한 전화를 받고 왜 거기(국회)에 오지 않았냐''(는 것)"이라며 "허위사실에 의한 명예훼손"이라고 주장했습니다. 김 전 총리는 캠페인 일환으로 진행하는 ''유튜브 백문백답''에 대해선 "저에 대해 무엇이든 물어보시라는 차원"이라고 소개했습니다. 그러면서 "당의 내부 문화가 조금 이상해져서 멸칭, 갈라치기도 있고 전혀 (사실이) 아닌 가짜뉴스도 돌아다닌다"며 "그런 것들을 정리하면 좋겠다(는 취지)"라고 했습니다. 자신이 당의 혁신을 강조한 배경에 대해선 "검찰개혁이 중요하지만, 민주당은 그것 외에는 어젠다가 없느냐는 느낌이 들게 해선 안된다"며 "(정부를) 착착 뒷받침하는 느낌을 주는 1년은 아니지 않았는가"라고 반문했습니다. 그는 ''5·18은 성역이 아니다''라는 발언으로 논란을 빚은 뒤 사퇴한 이병태 전 규제합리화위원회 부위원장에 대해선 "사퇴는 불가피했다"며 "이번 기회에 5·18 헌법 전문 수록과 선거관리위원회 문제에 관한 투포인트 개헌을 하자"고 제안했습니다. 이어 이재명 정부의 ''통합 인사'' 기조에 대해선 "사람을 더 넓게 쓰잔 방향 자체는 버릴 수 없다"며 더욱 엄격한 검증 필요성을 강조했습니다. (사진=연합뉴스)', 'crawl', 'SBS', '2026-07-07 11:30:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260707/202199711_1280.jpg', '2026-07-07 06:04:47', '2026-07-07 18:46:01.153231', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4412, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=01&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644663', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644663&plink=RSSLINK&cooper=RSSREADER', '정치', '이 대통령, NATO 정상회의 참석 차 출국…3박 5일 순방 돌입', '&#9650; 북대서양조약기구 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령이 7일 성남 서울공항에서 환송 나온 더불어민주당 한…', '▲ 북대서양조약기구(NATO) 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령이 7일 성남 서울공항에서 환송 나온 더불어민주당 한병도 대표 직무대행 겸 원내대표와 인사하고 있다. 이재명 대통령이 북대서양조약기구(NATO·나토) 정상회의 참석을 위해 오늘(7일) 아침, 튀르키예 앙카라로 출국했습니다. 이 대통령은 한병도 민주당 대표 직무대행 겸 원내대표, 윤호중 행정안전부 장관, 강훈식 대통령비서실장, 홍익표 정무수석, 김진아 외교부 제2차관, 살리 무랏 타메르 주한 튀르키예 대사, 수헤 수흐볼드 주한 몽골대사 등의 환송을 받으며 김혜경 여사와 함께 공군1호기에 올랐습니다. 이 대통령은 7일부터 이틀간 튀르키예 앙카라에서 열리는 나토 정상회의에 참석합니다. 우리나라는 이번에 나토의 인도·태평양 파트너국(IP4 국가, 한국·일본·호주·뉴질랜드)의 일원으로 마르크 뤼터 사무총장의 초청을 받았습니다. 이 대통령은 자신의 SNS를 통해 "지난달 G7 정상회의에 이어 이번에는 NATO 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 더욱 넓혀가려 한다"고 밝혔습니다. 그러면서, "오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계평화와 안보에 책임 있게 기여하는 나라가 되었다. 국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다"고 다짐했습니다. 이미지 확대하기 이 대통령은 튀르키예 앙카라 도착 직후 뤼터 사무총장과의 소인수회담을 한 뒤, 정상회의 공식 행사 중 하나인 나토 방위산업 포럼에 참석, ''공동의 가치, 더욱 강한 산업기반'' 주제의 세션에서 기조 발언에 나섭니다. 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 참석합니다. 튀르키예 방문 둘째 날인 내일(8일)엔 방산 등 분야에 협력 수요가 있는 국가들과 양자 회담을 할 예정입니다. 방산포럼에 이어 나토 회의 참석 정상들과의 만남을 통해 세계 최대 규모의 나토 방산 시장 진출 교두보를 마련하겠다는 게 청와대의 설명입니다. 이 대통령은 이후 몽골 국빈 방문을 위해 수도 울란바타르로 이동합니다. 한국 대통령의 몽골 국빈 방문은 15년 만으로 오흐나 후렐수흐 대통령의 초청으로 이뤄졌습니다. 이 대통령은 9일 몽골 울란바타르에서 후렐수흐 대통령과 정상회담을 하고 협정·양해각서(MOU) 교환식 및 공동언론발표를 통해 이번 회담 성과를 알릴 예정입니다. 양국 정상은 양국 관계의 미래 비전을 담은 ''한몽 관계의 황금시대'' 공동선언도 발표합니다. 이 대통령은 ''한몽 비즈니스 포럼''에서 기조연설, 이태준 열사 기념관 방문, 몽골 교민들과 오찬 간담회, 몽골 최대 명절 ''나담축제'' 개막식 주빈 자격 참석 등의 일정을 소화한 뒤 11일 귀국길에 오를 예정입니다. (사진=연합뉴스)', 'crawl', 'SBS', '2026-07-07 08:39:00', '중도', 'ready', 'https://img.sbs.co.kr/news/pc/thumb_v3.png', '2026-07-07 06:04:47', '2026-07-07 18:47:12.884058', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4417, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=01&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644392', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644392&plink=RSSLINK&cooper=RSSREADER', '정치', '호남 반도체 기지, 광주 군 공항에…"오직 속도전"', '정부가 호남권 반도체 클러스터를, 광주 군 공항 부지에 조성하기로 결정했습니다. 3대 메가프로젝트 발표 일주일 만에 첫 부지가 정해진 건데 이재명 대통령은 민관합동 회의에서 다시 ''속도전''을 주문했습니다.강민우 기자입니다.', '<앵커> 정부가 호남권 반도체 클러스터를, 광주 군 공항 부지에 조성하기로 결정했습니다. 3대 메가프로젝트 발표 일주일 만에 첫 부지가 정해진 건데 이재명 대통령은 민관합동 회의에서 다시 ''속도전''을 주문했습니다. 강민우 기자입니다. <기자> 청와대는 호남권 반도체 기지를 광주 군 공항 부지에 조성한다고 어제(6일) 발표했습니다. [강훈식/대통령비서실장 : 약 250만 평 규모의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있습니다.] 광주 도심, KTX 역과 인접해 인력 확보 및 정주 여건 마련에 유리하고, 토지 수용이 수월한 국유지라는 점 등이 선정 이유로 꼽혔습니다. 지난주 ''3대 메가 프로젝트''가 발표된 지 불과 일주일 만에 첫 부지가 결정된 겁니다. 부지 발표 전에 열린 민관합동점검회의에서 이재명 대통령은 ''속도전''을 주문했는데, [이재명 대통령 : 국운이 걸린 총력 경쟁이 벌어지고 있는데, 누가 얼마나 더 빨리 선점하느냐, 누가 더 빠르냐로 결판이 나는 것 같습니다. 그야말로. 오직 속도전이 중요하다.] 민관 합동 회의도 매달 열어 추진 상황을 직접 챙긴다는 계획입니다. 이 대통령은 전력·용수의 선제적 확보를 강조하며 신속한 행정을 당부했고, 프로젝트 실현 가능성에 대한 보수 야권 비판을 겨냥, "협조는 못하더라도 방해는 하지 말라"고 말하기도 했습니다. [이재명 대통령 : (투자 규모) 균형을 주장하다가, 불가능한 걸 전제로 기만이다, 이벤트다 이렇게 주장을 해요. 이게 나라 살림을 맡은 공인들이 과연 이런 태도를 취하는 게 맞는가. 한 가지만 하십시오.] 이에 장동혁 국민의힘 대표는 이 대통령이 민주당 대표였을 때는 윤석열 정부 ''대왕고래'' 사업을 "십중팔구 실패할 사안"이라고 해놓고, ''메가 프로젝트''는 비판도 하지 말라는 거냐고 쏘아붙였습니다. (영상취재 : 정상보·하륭, 영상편집 : 이승희, 디자인 : 장채우)', 'crawl', 'SBS', '2026-07-07 06:26:00', '중도', 'ready', 'https://img.sbs.co.kr/news/pc/thumb_v3.png', '2026-07-07 06:04:47', '2026-07-07 18:47:22.373272', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4419, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=01&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644407', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644407&plink=RSSLINK&cooper=RSSREADER', '정치', '이 대통령, 오늘부터 튀르키예·몽골 순방…나토 정상회의 참석 예정', '&#9650; 북대서양조약기구 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령 부부가 7일 성남 서울공항에서 환송객들을 향해 인사…', '▲ 북대서양조약기구(NATO·나토) 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령 부부가 7일 성남 서울공항에서 환송객들을 향해 인사하고 있다. 이재명 대통령은 오늘(7일)부터 11일까지 3박 5일 간 튀르키예에서 열리는 북대서양조약기구(NATO·나토) 정상회의 참석 및 몽골 국빈 방문 등의 정상외교 일정을 소화합니다. 이 대통령은 우선 마르크 뤼터 나토 사무총장의 초청으로 이날부터 이틀간 앙카라에서 열리는 나토 정상회의에 참석합니다. 이날 오후 앙카라에 도착, 뤼터 사무총장와 일본, 호주, 뉴질랜드 등 인도·태평양 파트너국(IP4 국가) 대표들과의 소인수 회담을 할 예정입니다. 이 대통령은 이후 정상회의 공식 행사 중 하나인 나토 방위산업 포럼에 참석, ''공동의 가치, 더욱 강한 산업기반'' 주제의 세션에서 기조 발언에 나섭니다. 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 자리합니다. 이 대통령은 튀르키예 방문 둘째 날인 8일에는 방산 등 분야에서 협력 수요가 있는 국가들과 양자 회담을 할 것으로 보입니다. 청와대는 이 대통령의 나토 정상회의 방문을 통해 세계 최대 규모의 나토 방산 시장 진출의 교두보를 마련하겠다는 방침입니다. 이미지 확대하기 이 대통령은 이후 오흐나 후렐수흐 몽골 대통령의 초청에 따라 몽골을 국빈 방문합니다. 한국 대통령의 몽골 국빈 방문은 15년 만입니다. 이 대통령은 9일 몽골 울란바타르에 도착해 후렐수흐 대통령과 정상회담을 하고 협정·양해각서(MOU) 교환식 및 공동언론발표를 통해 이번 회담 성과를 알릴 예정입니다. 양 정상은 양국 관계의 미래 비전을 담은 ''한몽 관계의 황금시대'' 공동선언도 발표합니다. 이 대통령은 같은 날 저녁엔 양국 정부 및 기업 인사들이 경제 협력 방안을 논의하는 ''한몽 비즈니스 포럼''에서 기조연설도 나섭니다. 이어 10일엔 몽골에서 인술을 펼치며 독립운동을 지원한 이태준 열사 기념관을 찾은 뒤 몽골 교민들과 오찬 간담회를 합니다. 순방 마지막 날인 11일에는 후렐수흐 대통령과 함께 몽골 최대 명절 '' 나담축제'' 개막식에 주빈으로 참석한 뒤 귀국길에 오릅니다. (사진=연합뉴스)', 'crawl', 'SBS', '2026-07-07 09:29:00', '중도', 'ready', 'https://img.sbs.co.kr/news/pc/thumb_v3.png', '2026-07-07 06:04:47', '2026-07-07 18:47:27.985462', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4420, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=01&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644301', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644301&plink=RSSLINK&cooper=RSSREADER', '정치', '호남 반도체 기지, 광주 군공항에…''속도전'' 강조', '정부가 광주 군 공항 부지에 호남권 반도체 클러스터를 조성하기로 결정했습니다. ''3대 메가 프로젝트'' 발표 일주일 만에 첫 부지가 확정·발표된 건데, 이재명 대통령은 민관합동 회의에서 ''속도전''을 주문했습니다.강민우 기자가 보도합니다.', '<앵커> 정부가 광주 군 공항 부지에 호남권 반도체 클러스터를 조성하기로 결정했습니다. ''3대 메가 프로젝트'' 발표 일주일 만에 첫 부지가 확정·발표된 건데, 이재명 대통령은 민관합동 회의에서 ''속도전''을 주문했습니다. 강민우 기자가 보도합니다. <기자> 청와대는 오늘(6일), 호남권 반도체 기지를 광주 군 공항 부지에 조성한다고 발표했습니다. [강훈식/대통령비서실장 : 약 250만 평 규모의 부지 확보가 가능하고 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있습니다.] 광주 도심, KTX 역과 인접해 인력 확보와 정주 여건 마련에 유리하고, 토지 수용이 수월한 국유지라는 점 등이 선정 이유로 꼽혔습니다. 지난달 29일, ''3대 메가 프로젝트''가 발표된 지 불과 일주일 만에 첫 부지가 결정된 겁니다. 이재명 대통령은 부지 발표 전에 열린 오늘 오전 민관합동 점검회의에서 ''속도전''을 주문했습니다. [이재명 대통령 : 국운이 걸린 총력 경쟁이 벌어지고 있는데, 누가 얼마나 더 빨리 선점하느냐, 누가 더 빠르냐로 결판이 나는 것 같습니다. 그야말로. 오직 속도전이 중요하다.] 이 대통령은 전력과 용수의 선제적 확보를 강조하며 신속한 행정을 당부했고, 프로젝트 실현 가능성에 대한 보수 야권의 비판에 반박하는 듯, "협조는 못하더라도 방해는 하지 말라"고 말하기도 했습니다. [이재명 대통령 : (투자 규모) 균형을 주장하다가, 불가능한 걸 전제로 기만이다, 이벤트다 이렇게 주장을 해요. 이게 나라 살림을 맡은 공인들이 과연 이런 태도를 취하는 게 맞는가. 한 가지만 하십시오.] 이에 장동혁 국민의힘 대표는 이 대통령이 민주당 대표였을 때는 운석열 정부의 ''대왕고래'' 사업을 "십중팔구 실패할 사안"이라고 해놓고, ''메가 프로젝트''는 비판도 하지 말라는 거냐고 쏘아붙였습니다. 이 대통령은 오늘 같은 민관합동 점검회의를 매달 열어 추진 상황을 직접 챙긴다는 계획입니다. (영상취재 : 정상보·하륭, 영상편집 : 이승희, 디자인 : 장채우)', 'crawl', 'SBS', '2026-07-07 00:40:00', '중도', 'ready', 'https://img.sbs.co.kr/news/pc/thumb_v3.png', '2026-07-07 06:04:47', '2026-07-07 18:47:30.098398', NULL);
