INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4428, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=02&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645480', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645480&plink=RSSLINK&cooper=RSSREADER', '경제', '양도세 피하려 엄마 친구와 가짜 매매…국세청 80여 명 318억 추징', '&#9650; 사례 1 가장매매 국세청이 지난해 10월 부동산 탈세 혐의자 104명을 동시 조사해 오늘까지 80여 명이 벌인 총 731억 원 규…', '이미지 확대하기 ▲ 사례 1 가장매매 국세청이 지난해 10월 부동산 탈세 혐의자 104명을 동시 조사해 오늘까지 80여 명이 벌인 총 731억 원 규모 탈루를 적발해 세금 318억 원을 추징했다고 오늘 밝혔습니다. 국세청은 사기나 그 밖의 부정한 방법으로 조세를 포탈한 사실이 확인된 건은 40%에 상당하는 부당 과소신고가산세를 부과했습니다. 아울러 조세범처벌법에 따라 6명은 검찰에 고발하고, 4명은 벌금 상당액 총 7억 원 납부를 통지하는 통고처분을 했습니다. 당사자뿐 아니라 관련자도 함께 처분했습니다. 2주택자인 A 씨는 두 채 중 가격이 싼 아파트를 어머니의 친구에게 팔았습니다. 이어 고가 아파트를 20억 원에 팔면서 1세대 1주택자 비과세를 적용해 양도세를 신고했습니다. 하지만, A 씨는 지을 판 뒤 가짜 전세 계약을 맺어 계속 같은 집에 거주하고 탈세 협조 대가로 매달 수십만 원씩 사례비도 지급하는 등 어머니 친구와 거래는 허위였습니다. 국세청은 A 씨로부터 중과세율을 적용한 양도세 10억 원을 추징했고 A 씨 어머니 등 관련자들도 함께 처분했습니다. 국세청은 이른바 ''검머외''(검은 머리 외국인)라 불리는 외국 국적자의 증여세 탈루도 적발했습니다. A 씨는 실거주 목적 없이 마용성(마포·용산·성동구) 고가아파트 2채를 외국인 배우자와 함께 30억 원에 공동 취득했습니다. 소득원이 없는 가정주부 B 씨는 주택 취득자금과 인테리어 자금 전액을 배우자에게 증여받고 증여세를 신고하지 않은 점이 확인됐습니다. 결국 내지 않은 세금 4억 원을 내게 됐습니다. ''부모 찬스''도 적발됐습니다. 서울 강남 한강변 소재 고가 아파트에 월세 700만 원을 내는 40대 C 씨는 수십억 원 규모의 주식을 취득하고, 매년 수억 원에 달하는 생활비를 지출하고 있었습니다. 조사 결과 20여 억 원의 자금을 부모로부터 증여받은 것으로 확인됐고, 증여세 총 13억 원을 추징당했습니다. 국세청은 명의신탁 등 부동산실명법 위반 행위가 확인된 20명도 과징금 부과와 형사처벌 조치가 이뤄지도록 관할 지방자치단체에 통보했습니다. 국세청은 앞으로도 부동산 취득·보유·양도 등 거래 전 과정에서 발생하는 탈세 위험요인을 조기에 포착하고, 탈세행위가 확인될 경우 세무조사를 실시하는 등 강력하게 대응해 나갈 방침입니다. 특히 다주택자 중과 재개 후 증여거래가 늘어날 우려가 있는 만큼 증여재산을 저가평가하거나 증여세를 대납하는 등 편법 증여가 없는지 검증할 예정입니다. ''부동산 탈세 신고센터''를 통해 접수한 제보를 철저히 검증해 탈루 세금을 추징하는 한편, 제보자 포상금도 신속히 지급할 계획입니다. (사진=국세청 제공, 연합뉴스)', 'crawl', 'SBS', '2026-07-07 14:19:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260707/202199741_1280.jpg', '2026-07-07 06:04:47', '2026-07-07 18:47:45.063571', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4437, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=02&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644972', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644972&plink=RSSLINK&cooper=RSSREADER', '경제', '[자막뉴스] 엔비디아 제치고 ''세계 1위'' 우뚝 섰는데…"삼전 주가는 대체 왜?" 개미들 ''멘붕''', '삼성전자가 글로벌 기업들 가운데 분기 기준 사실상 역대 최대 영업이익을 올리는 신기록을 세웠지만, 오늘 코스피와 삼성전자 주가는 오히려 하락세를…', '삼성전자가 글로벌 기업들 가운데 분기 기준 사실상 역대 최대 영업이익을 올리는 신기록을 세웠지만, 오늘 코스피와 삼성전자 주가는 오히려 하락세를 보이고 있습니다. 삼성전자가 공시한 올해 2분기 잠정 영업이익은 시장 전망치를 크게 웃도는 89조 4천억 원으로, 지난해 같은 기간보다 무려 1,810% 급증했습니다. 단 1개 분기 만에 지난 3년간 합산 영업이익을 한꺼번에 벌어들인 것입니다. 특히 업계에서는 이번 실적에 특별경영성과급 충당금 20조 원 안팎이 반영된 것으로 보고 있어, 이를 포함하면 사실상 106조 원 상당의 영업이익을 벌어들인 것으로 추정됩니다. 이는 미국 엔비디아의 분기 영업이익인 81조 원을 넘어서는 규모고, 전 세계 국영 기업까지 포함했을 때 사우디 아람코의 지난 2022년 영업이익에 이어 역사상 두 번째로 높은 대기록입니다. 하지만, 이 같은 사상 최대의 어닝 서프라이즈에도 불구하고 주식시장 반응은 냉담합니다. 삼성전자 주가는 개장 직후부터 급락세를 타며 장중 30만 원 선 사수에 실패했고 오전 10시 기준 5%대 하락한 29만 8천 원대에 거래됐습니다. 기록적인 호실적이 이미 주가에 선반영 됐다는 인식 속에, 막상 공식 발표가 나오자 차익 실현 매물이 쏟아지는 이른바 ''셀온'' 현상이 나타난 것이라는 해석이 나옵니다. 대장주 삼성전자의 급락에 코스피 지수 역시 개장 직후부터 낙폭을 키우며 7천 700선까지 하락했습니다. 오늘 오전 10시 기준 외국인은 7천 8백억 원, 기관은 2천 8백억 원어치를 동반 매도한 반면, 개인인은 홀로 1조 7백억 원 규모를 매수하며 물량을 받아냈습니다. 국내 주식시장이 간밤 미국 뉴욕증시가 반도체주 중심으로 상승 마감한 것과 대조적인 흐름을 보이는 가운데, 시장들은 향후 주가 반등 여부와 시기를 두고 추가 매물 출회 여부와 지지선 구축 여부에 주목하고 있습니다. (취재: 이현영, 영상편집: 서병욱, 디자인: 육도현, 제작: 디지털뉴스부)', 'crawl', 'SBS', '2026-07-07 11:12:00', '중도', 'ready', 'https://img.sbs.co.kr/news/pc/thumb_v3.png', '2026-07-07 06:04:48', '2026-07-07 18:48:04.029526', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4450, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=02&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644786', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644786&plink=RSSLINK&cooper=RSSREADER', '경제', '구윤철 "7월 말 부동산 세제 발표…보유세·거래세 균형 이뤄야"', '&#9650; 구윤철 부총리 겸 재정경제부 장관이 6일 서울 중구 웨스틴 조선 서울에서 열린 서비스산업 경쟁력 강화 TF 2차 회의에서 모두발언…', '▲ 구윤철 부총리 겸 재정경제부 장관이 6일 서울 중구 웨스틴 조선 서울에서 열린 서비스산업 경쟁력 강화 TF 2차 회의에서 모두발언을 하고 있다. 구윤철 부총리 겸 재정경제부 장관은 오늘(7일) 부동산 세제 개편을 하면서 보유세와 거래세를 함께 손질할지에 관해 "두 가지가 밸런스(균형)를 이뤄야 한다"고 말했습니다. 구 부총리는 오늘 MBC 라디오 ''김종배의 시선집중'' 전화 인터뷰에서 "7월 말 정도 (발표를) 생각으로 준비 중"이라며 이같이 밝혔습니다. 그는 "기본적으로 집은 ''바잉(buying·매수)이 아닌 리빙(living·거주)''이라는 원칙하에 실거주자 중심으로 주택 시장이 확립될 수 있도록 보고 있다"며 "정부가 일방적으로 결정하는 것이 아니라 조만간 제가 국민 의견, 현장 목소리를 듣고 최종 정부 방침을 결정할 것"이라고 설명했습니다. 구 부총리는 공정시장가액비율 조정, 비거주 장기보유특별공제 혜택 축소 등 부동산세 개편 방향에 관한 여러 보도에 관한 질문에 "그 부분도 국민의 한 의견인 만큼 살펴보겠다"고 즉답을 피했습니다. 진행자가 ''보유세와 거래세 두 가지를 모두 건드리는 것이 맞느냐''고 묻자 "두 가지 밸런스를 이뤄야 한다는 차원에서 함께 보고 있다"고 답했습니다. 구 부총리는 정부가 추진 중인 ''3대 메가 프로젝트''에 관해선 "인공지능(AI) 반도체 혁명은 과거 박정희 대통령 시절 경부고속도로 건설과 중화학 공업 육성, 김대중 대통령 시절 정보기술(IT) 혁명보다 훨씬 더 큰 문명사적 의미가 있다고 생각한다"며 "다행히 대한민국은 준비가 잘 돼 있어 제대로 총력전·속도전으로 대응하면 엄청난 기회가 될 것"이라고 설명했습니다. 지역 편중 우려에는 "전국의 운동장을 골고루 활용할 계획"이라며 "예를 들자면 호남은 수도권에 이은 반도체 제2생산기지, 충청은 패키징 담당, 영남은 AI에 필요한 소부장(소재·부품·장비) 등으로 특성화해 한반도 전체가 AI 반도체 에코시스템이라고 판단하는 것"이라고 말했습니다. 구 부총리는 "연구개발(R&D)이나 투자에 지원하고 지금은 세금을 내더라도 나중에 세금을 못 내는 시기가 생기면 이월공제도 해주려고 한다"고 세제 지원 구상도 언급했습니다. 그는 또 "지방에서 근로하는 분들은 서울 거주 때보다는 소득세 감면을 더 해주고 경우에 따라 자녀 교육비 지원도 검토할 수 있다"며 "소득공제나 세액공제 등 그 방법은 지역 근로자의 희망 사항을 감안해 검토 중"이라고 부연했습니다. 구 부총리는 반도체 호황에 따른 법인세 세수 규모에 관해서는 "수백조 원 영업이익이 난다고 하는데 아직까지 정확히 기업 영업이익을 집계하지 않은 상황"이라며 "상반기 영업실적과 8월 법인세 중간예납을 받아야 예측 가능하다"고 말했습니다. 반도체 관련 기업에만 한정해 달라는 요청에는 "에프앤가이드 금년 영업이익 전망을 보면 삼성전자와 SK하이닉스 두 곳만 600조 원 영업이익이 예상되고 평균 20%만 잡아도 어마어마한 돈이 된다"며 "두 기업이 그동안의 법인세를 다 내는 구도"라고 했습니다. 600조 원의 20%는 120조 원입니다. 구 부총리는 이른바 초과세수를 활용한 ''미래대응기금'' 구상에 관해 "저는 추가세수라고 말하고 싶다"며 "대체 불가능한 대한민국을 위한 미래 작업을 위해 쓰기 위해 내부적으로 검토 중"이라고 설명했습니다. 기금의 상당 부분이 반도체 산업에 필요한 전력·용수 추가 공급에 투입되느냐는 물음에 "반도체 외에도 여러 혁신 산업이 있다. 로봇·피지컬 AI·조선·항공 등에도 R&D 등 인프라 지원을 해야 한다"며 청년을 위한 AI 교육, 창업 등에도 주목할 수 있다고 예를 들었습니다. 구체적인 청사진 공개 시점에는 "지금 기획예산처에서 준비 중"이라며 "관련 법안을 정기국회(9월) 전에 할 수 있다면 해야 할 정도로 속도가 필요하다"고 말했습니다. 역시 정기국회에 제출하는 내년도 예산안에 대해선 "AI 지원, 양극화, 민생, 구조혁신 등 우리 사회가 안고 있는 문제를 해결하고 선도 국가로 나아가는 지원을 대대적으로 해나갈 것"이라며 "세수가 좋으니까 세입 사정 감안해서 재정 규모를 판단할 계획"이라고 설명했습니다. 진행자가 삼성전자의 2분기 영업이익이 89조 4천억 원이라며 적극재정을 기대한다고 하자 구 부총리는 "그렇게 하겠다"고 답했습니다. (사진=연합뉴스)', 'crawl', 'SBS', '2026-07-07 09:51:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260706/202199282_1280.jpg', '2026-07-07 06:04:48', '2026-07-07 18:48:31.177531', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4454, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=02&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008643934', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008643934&plink=RSSLINK&cooper=RSSREADER', '경제', '"10만 명 생계가 흔들"…업계 2위 ''공중분해'' 초유의 위기 [스프]', '&#9889; 스프 핵심요약최후통첩: 서울회생법원이 2000억 원의 최소 운영자금 조달 실패를 이유로 홈플러스에 회생절차 폐지 결정을 내리며 14일의 즉시항고 기한을 부여함.책임 공방: 대주주 MBK파트너스와 최대 채권자 메리츠금융그룹이 자금 부담 책임을 서로에게 떠넘기며 1만 2천 명의 노동자와 4,600여 협력업체의 생계가 위협받음.구조적 역풍: 이번 사태는 단순 경영 실패를 넘어 온라인 시대로의 급격한 전환과 사모펀드 모델이 안은 한계가 복합적으로 작용한 결과임.대형마트 2위 홈플러스가 2026년 7월 3일, 법원으로부터 회생절차 폐지 결정을 받았습니다.', '⚡ 스프 핵심요약 최후통첩: 서울회생법원이 2000억 원의 최소 운영자금 조달 실패를 이유로 홈플러스에 회생절차 폐지 결정을 내리며 14일의 즉시항고 기한을 부여함. 책임 공방: 대주주 MBK파트너스와 최대 채권자 메리츠금융그룹이 자금 부담 책임을 서로에게 떠넘기며 1만 2천 명의 노동자와 4,600여 협력업체의 생계가 위협받음. 구조적 역풍: 이번 사태는 단순 경영 실패를 넘어 온라인 시대로의 급격한 전환과 사모펀드(PEF) 차입매수(LBO) 모델이 안은 한계가 복합적으로 작용한 결과임. 대형마트 2위 홈플러스가 2026년 7월 3일, 법원으로부터 회생절차 폐지 결정을 받았습니다. 남은 시간은 딱 2주. 2000억 원을 마련하지 못하면 1만 2000명의 직원과 4600여 개 협력업체가 거리로 내몰립니다. 대주주 MBK파트너스(MBK Partners)와 최대 채권자 메리츠금융그룹(Meritz Financial Group)은 서로에게 책임을 떠넘기며 공방만 되풀이하고 있고, 정부는 청산을 전제로 한 대책만 내놨습니다. 1997년 창사 이래 최대 위기를 맞은 홈플러스, 지금 무슨 일이 벌어지고 있는 걸까요? 1. "2000억 원 없으면 끝" 법원이 내린 최후통첩 법원은 왜 회생절차를 폐지했을까요? 서울회생법원은 7월 3일 "회생계획안 수행 가능성이 없다"며 홈플러스 기업회생절차 폐지를 결정했습니다. 핵심 이유는 단 하나. 회생에 필요한 최소 운영자금 2000억 원을 조달하지 못했다는 겁니다. 법원은 "홈플러스 익스프레스 매각은 성사됐지만, 나머지 대형마트 사업부는 인수합병이 이뤄지지 않은 채 영업을 지속하며 매출은 감소하고 급여·물품대금 등 공익채권은 급증했다"고 설명했습니다. 다만 법원은 14일 이내에 자금을 조달해 즉시항고하면 회생절차를 재개할 수 있다는 여지를 남겼습니다. 2주 안에 2000억 원이 마련되지 않으면 홈플러스는 사실상 청산 수순을 밟게 됩니다. 2. MBK와 메리츠, 서로에게 책임 떠넘기기 2000억 원은 왜 마련되지 못했을까요? 대주주 MBK파트너스와 최대 채권자 메리츠금융그룹이 책임 공방만 벌였기 때문입니다. 메리츠는 "MBK와 김병주 회장의 연대보증을 조건으로 1000억 원을 에스크로 계좌에 예치했다"며 "나머지 1000억 원은 MBK가 책임져야 한다"고 주장합니다. 반면 MBK는 "메리츠가 2000억 원 전액을 대출하면 그중 1000억 원에 대해 연대보증할 의사가 있다"며 "이미 수천억 원을 투입했고 추가 재원 마련 여력이 없다"는 입장입니다. 법원 결정 직후에도 양측은 기존 입장을 되풀이했습니다. 홈플러스는 "메리츠가 1000억 원의 연대보증만으로는 부족하다며 자금지원을 거절하고 있다"고 밝혔고, 메리츠는 "홈플러스 위기는 지난 10년간 MBK가 투자금 회수에만 몰두한 경영의 참담한 결과"라고 맞받았습니다. 3. "2000억 원 추가 증여" MBK 약속은 어떻게? MBK는 과거 무슨 약속을 했을까요? MBK는 2025년 9월 대국민 사과문에서 "인수인의 자금 부담을 덜어주기 위해 장래 운영 수입을 재원으로 향후 최대 2000억 원을 홈플러스에 무상으로 추가 증여하겠다"고 밝혔습니다. 법원이 요구한 2000억 원과 정확히 일치하는 금액입니다. 그런데 이 약속이 발표된 지 9개월이 지나도록 실제 집행 여부는 명확히 확인되지 않고 있습니다. 홈플러스가 최근 공시한 감사보고서상 회생절차 신청 이후 2025년 3월부터 2026년 2월까지 MBK로부터 출자나 무상대여 등 직접적인 현금성 자금지원 내역은 드러나지 않았습니다. 같은 기간 홈플러스는 금융기관 차입으로 약 607억 원을 조달했을 뿐입니다. 이와 관련해 MBK 측은 이미 2000억 원 규모의 지원을 이행했다는 입장을 전해왔습니다. 김병주 회장 개인이 출연한 현금 400억 원, DIP대출 600억 원에 대한 구상권 포기(대위변제)로 이미 1000억 원을 지원했고, 지난 3월에는 김 회장과 경영진이 자택 등을 담보로 긴급 운영자금 1000억 원을 조성해 지원했다는 설명입니다. 여기에 메리츠금융 대출이 성사되면 1000억 원을 추가로 연대보증하겠다는 조건부 확약도 더했습니다. 다만 이는 애초 약속한 ''홈플러스 운영 수입을 재원으로 한 무상 증여''에 해당하는지, 그래서 약속 이행으로 볼 수 있는지에 대한 설명은 더 필요해 보입니다. 4. 1만 2000명 실직, 10만 명 연쇄 타격 불가피 홈플러스가 청산되면 누가 피해를 볼까요? 우선 직고용 노동자 1만 2000명과 간접고용 1000명, 총 1만 3000명이 일자리를 잃게 됩니다. 여기에 납품업체 4600여 개, 입점 소상공인, 배송기사, 전단채 투자자까지 포함하면 피해 규모는 최대 10만 명에 달한다는 분석이 나옵니다. 중소기업중앙회 조사에 따르면 홈플러스 납품 중소기업·소상공인 150곳이 받지 못한 납품대금은 업체당 평균 7억 7400만 원입니다. 전단채 투자자들의 피해액도 4000억 원대에 달합니다. 폐점된 홈플러스에 입점한 한 자영업자는 이렇게 말합니다. "매장 시설물 설치에 들인 수억 원을 회수도 못 했는데, 언제까지 영업할 수 있는지도 알 수 없어 막막하다." 노동계는 "직·간접고용 노동자와 협력업체, 입점 소상공인과 그 가족까지 포함하면 30만 명의 생계가 달렸다"고 주장합니다. 5. 정부 대책은? 청산 전제로 한 임시방편뿐 정부는 무엇을 하고 있을까요? 정부는 7월 3일 관계기관 전담반 회의를 열고 대책을 발표했습니다. 임금체불 피해 근로자에게 1인당 최대 2100만 원 대지급금 지급, 최대 1000만 원 저리 융자, 저소득 재직자 대상 최대 2000만 원 생활안정자금 융자 등입니다. 협력업체에는 총 4400억 원 규모의 유동성 지원 방안도 논의됐습니다. 그런데 정부 대책은 모두 "청산을 전제"로 한 사후 지원입니다. 회생을 위한 긴급 개입이나 공적자금 투입 방안은 포함되지 않았습니다. 마트산업노조는 "국가마저 거대 자본의 ''쩐의 전쟁''을 방관한 결과"라며 "정부는 14일 내 공적자금 투입을 포함한 모든 가능한 긴급조치를 통해 회생 방안을 마련하라"고 촉구했습니다. 하지만 정부가 2주 안에 입장을 바꿀 가능성은 낮아 보입니다. 이미지 확대하기 6. 홈플러스만의 문제가 아니다: 대형마트 업태 자체가 무너지고 있다 홈플러스 위기는 경영 실패 때문만일까요? 한국 대형마트 업태 자체가 구조적 역풍을 맞고 있습니다. 산업통상자원부 자료에 따르면 한국 소매시장에서 온라인 유통 비중은 60.3%인 반면, 하이퍼마켓(대형마트) 비중은 7.9%에 그쳤습니다. 대형마트 매출 부진은 2024년 2분기 이후 지속되고 있습니다. 한국개발연구원(KDI)은 "온라인 확산은 대형마트의 범용적 수요를 흡수하는 반면, 근거리 상권 기반 SSM·편의점에는 새로운 기회를 열어주는 이중 구조를 만든다"고 분석했습니다. 즉, 오프라인 전체가 무너지는 게 아니라 특히 넓은 매장·대량구매·차량이동을 전제로 한 하이퍼마켓 포맷이 가장 직접적 타격을 받는다는 겁니다. 홈플러스의 실패를 "특정 경영진의 실수"로만 좁혀 보기 어려운 이유입니다. 7. 규제는 보호였나, 족쇄였나 대형마트 규제는 어떤 역할을 했을까요? 2013년 학술논문은 한국의 대형점포 규제가 전통시장과 중소상인을 보호하는 정책적 근거를 가졌다고 평가했습니다. 그러나 2026년 KDI 보고서는 지금의 시장환경에서는 이 제도를 온·오프라인 규제 불균형 관점에서 재검토해야 한다고 봅니다. 온라인 유통이 소비의 다수를 차지하는데도 규제는 주로 오프라인 대형마트에 집중돼 있어 경쟁조건이 달라졌다는 지적입니다. KDI는 향후 정책 방향으로 유통산업발전법의 유연한 재설계, 오프라인의 O2O 연계와 디지털 전환 지원을 제안했습니다. 규제가 홈플러스를 직접 파산시켰다고 단정할 수는 없지만, 오프라인 대형마트의 회복 여지를 좁힌 환경요인이었을 가능성은 충분합니다. 8. 2015년 MBK 인수, 무엇이 잘못됐나 MBK는 홈플러스를 어떻게 운영했을까요? 로이터(Reuters) 보도에 따르면 테스코(Tesco)는 2015년 홈플러스를 61억 달러(약 7조 2000억 원)에 MBK파트너스 주도 컨소시엄에 매각했습니다. 당시 MBK 컨소시엄은 향후 2년간 1조 원 투자 계획을 밝혔습니다. 출발점 자체가 "값싸게 산 후 단기 차익만 노린 거래"로만 보이진 않았습니다. 그런데 문제는 이후 10년 동안 오프라인 대형마트 업태의 구조적 악화, 부동산·임대차 구조, 차입 기반 자본구조, 재투자 우선순위가 결합되며 기업의 체력이 약해졌다는 점입니다. 미국 국가경제연구소(NBER) 연구는 사모펀드 바이아웃 이후 근로자 1인당 보상이 1.7% 감소했고, 특히 비상장화(public-to-private) 거래에서는 큰 폭의 일자리 손실과 더 높은 파산위험이 나타났다고 보고합니다. 홈플러스처럼 산업 자체가 역풍을 맞는 경우에는 사모펀드의 운영개선 논리보다 레버리지와 현금흐름 압박이 더 크게 부각될 수 있습니다. 9. 협력업체 충격은 왜 이렇게 큰가 협력업체 피해는 왜 이렇게 심각할까요? KDI Journal of Economic Policy에 실린 2025년 논문에 따르면 대형마트 부문(이마트, 롯데마트, 홈플러스)에 약 1500개 거래공급업체가 연결돼 있었고, 해당 부문이 조사대상 전체 유통거래액의 23%를 차지했습니다. 대형슈퍼마켓의 주요 거래방식은 직매입(특히 가공식품 55%) 중심입니다. 이는 상품대금 정산 지연이나 영업중단이 발생할 경우 충격이 단순 매장 내부에서 끝나지 않고 납품업체 재고·운전자본·현금흐름으로 빠르게 번질 수 있음을 뜻합니다. 정부가 협력업체 지원책으로 4400억 원+α의 긴급 유동성과 폐업·전환지원까지 제시한 것도, 홈플러스를 하나의 "소매법인"이 아니라 중소 협력업체 연쇄현금흐름의 결절점으로 보고 있기 때문입니다. 10. 앞으로 어떻게 될까: 세 가지 시나리오 홈플러스의 운명은 어떻게 결정될까요? 세 가지 시나리오가 있습니다. 첫째, 14일 내 자금조달 성공. 홈플러스가 2000억 원을 확보해 즉시항고하면 회생절차가 재개될 수 있습니다. 다만 이미 법원이 "실행 가능성"에 의문을 제기한 만큼, 단순 브리지론이 아니라 중장기 사업계획과 신규자금 구조가 함께 제시돼야 설득력이 생길 겁니다. 둘째, 항고 실패 또는 자금조달 실패. 이 경우 홈플러스는 사실상 청산 또는 파산 수순으로 기울 가능성이 높습니다. 정부가 선제적으로 근로자·협력업체 지원 패키지를 내놓은 것도 이 가능성을 염두에 둔 대응으로 보입니다. 셋째, 제3의 구조조정. 이론적으로는 일부 점포·온라인 자산·물류망을 묶은 부분 매각 또는 업태분할형 재편도 가능합니다. 다만 현재 시장환경에서 하이퍼마켓 자산만으로 높은 기업가치를 기대하긴 어렵습니다. 홈플러스 사태는 단순한 기업 하나의 실패가 아닙니다. 온라인 전환으로 약해진 하이퍼마켓 모델이, 사모펀드형 자본구조와 회생금융의 제약 속에서 버티지 못한 사건입니다. 2000억 원이라는 숫자 뒤에는 1만 명 넘는 노동자와 수만 개 협력업체의 생계가 걸려 있습니다. 그리고 이 모든 것이 지금, 딱 2주 안에 결정됩니다. 확실한 건, 이제 홈플러스를 만만한 파트너로 봐선 안 된다는 겁니다. 아니, 이미 늦었을지도 모릅니다. 이미지 확대하기 Deep Dive Q&A Q1. 법원이 홈플러스의 회생절차 폐지를 결정한 결정적인 계기는 무엇인가요? A1. 핵심은 ''2000억 원 규모의 최소 운영자금 조달 실패''입니다. 홈플러스 익스프레스 매각에는 성공했으나 본체인 대형마트 사업부의 인수합병(M&A)이 난항을 겪었고, 그 사이 고정비(급여, 물품대금 등)인 공익채권이 급증하면서 법원이 "회생계획 수행 가능성이 없다"고 판단한 것입니다. Q2. 글로벌 외신 및 경제 학계에서는 홈플러스 사태의 배경이 된 사모펀드(PEF) 인수를 어떻게 바라보나요? A2. 로이터(Reuters) 등 외신과 미국 국가경제연구소(NBER)의 분석을 종합하면, 사모펀드의 차입매수(LBO) 모델은 산업 구조가 급격히 온라인으로 변하는 시기에 치명적인 약점을 드러냅니다. 과도한 부채 중심의 자본구조가 현금흐름을 압박하고 재투자를 제한하여 파산 위험을 키운다는 지적입니다. Q3. 향후 14일 이내에 자금 조달이 실패할 경우 어떤 사회적 파장이 예상되나요? A3. 직·간접고용 노동자 1만 3,000명의 실직뿐만 아니라, 대형마트 유통 특성인 ''직매입(가공식품 55%)'' 구조로 인해 4,600여 개 협력업체의 미수금 및 재고 부담이 가중됩니다. 이는 연쇄적인 중소 납품업체의 도산과 소상공인 붕괴 등 최대 10만 명에게 직접적인 타격을 줄 수 있습니다.', 'crawl', 'SBS', '2026-07-07 10:06:00', '중도', 'ready', 'https://news.sbs.co.kr/img/soupContentsAD_01.png', '2026-07-07 06:04:48', '2026-07-07 18:48:38.710324', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4462, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=03&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645201', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645201&plink=RSSLINK&cooper=RSSREADER', '사회', '"등교하는 애들 안 무섭겠냐"…배재고 ''화환 행렬''에 일침', '5.18 관련 부적절한 응원 구호를 외쳐 중징계를 받은 배재고등학교 야구부와 관련해 가수 하림이 배재고 앞에 늘어선 근조화환 행렬을 강하게 비판…', '5.18 관련 부적절한 응원 구호를 외쳐 중징계를 받은 배재고등학교 야구부와 관련해 가수 하림이 배재고 앞에 늘어선 근조화환 행렬을 강하게 비판했습니다. 하림은 어제(6일) 자신의 SNS를 통해 "언젠가부터 정치적 공격을 근조화환으로 하는 기괴한 문화가 생겼다"며, 이는 "죽음을 연상시켜 받는 이의 기분을 망치겠다는 악의적인 의도이자 거리에 노출된 오프라인 댓글과 같다"고 지적했습니다. 이어 "누가 아이들의 학교 앞에까지 근조화환을 보내냐"며, "누가 무슨 잘못을 했든 간에 혐오의 잔재 사이를 뚫고 등교하는 아이들은 다 무섭고 다 싫지 않겠느냐"며 우려의 목소리를 냈습니다. 하림은 그러면서, 배재고 학생들을 응원하는 취지에서 배달된 응원 화환들에 대해서도 비판했습니다. "정치적 이슈에 편승하려 보내는 응원의 화환도 마찬가지"라며 "꽃은 누군가를 때리는 데 쓰는 게 아니"라고 말했습니다. 하림은 그러면서 "타인을 해치기 위해 무기화된 꽃은 더 이상 꽃이 아니다, 우리마저 이 혐오의 방식에 익숙해지기 전에, 아름다운 것을 아름답게 지켜내는 최소한의 품격을 회복했으면 좋겠다"고 덧붙였습니다. 앞서 지난달 29일 청룡기 전국고교야구선수권대회에서 배재고 일부 선수들은 광주제일고 더그아웃을 향해 5.18 탱크데이 마케팅을 연상시키는 "스타벅스 가야지" 등의 구호를 외쳐 대한야구소프트볼협회로부터 ''6개월 출전 정지''라는 중징계를 받았습니다. 배재고 야구부 학생과 학부모, 교사들은 어제 광주제일고를 찾아 공식 사과하고 국립 5·18 민주묘지를 참배했습니다. (취재 : 이현영, 영상편집 : 김혜주, 디자인 : 양혜민, 제작 : 디지털뉴스부)', 'crawl', 'SBS', '2026-07-07 14:57:00', '중도', 'ready', 'https://img.sbs.co.kr/news/pc/thumb_v3.png', '2026-07-07 06:04:48', '2026-07-07 18:49:07.417542', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4467, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=03&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645427', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645427&plink=RSSLINK&cooper=RSSREADER', '사회', '"역대 최대 규모"…무려 7천476억 원 물린다', '&#9650;위 사진은 기사 내용과 관련이 없습니다.과자·빵·음료·빙과·맥주 등 먹거리는 물론 제지·철강 등 산업용 원재료로 쓰이는 전분·전분당…', '▲위 사진은 기사 내용과 관련이 없습니다. 과자·빵·음료·빙과·맥주 등 먹거리는 물론 제지·철강 등 산업용 원재료로 쓰이는 전분·전분당 가격을 7년 넘게 짬짜미한 업체들이 역대 최대 규모의 과징금에 처해집니다. 공정거래위원회는 대상㈜, (유)사조CPK, ㈜삼양사, CJ제일제당㈜ 등 4개사가 7년 5개월에 걸쳐 식품업체, 제지사, 철강사 등 사업자 간 거래(B2B)에 적용되는 전분·전분당(이하 ''전분당'') 가격을 담합한 것으로 드러나 합계 7천476억 원의 과징금을 부과하기로 했다고 오늘(7일) 밝혔습니다. 이는 5월 밀가루 가격을 밀약한 7개 업체에 매긴 6천710억 원을 뛰어넘습니다. 공정위의 담합 제재 사상 역대 최대 규모입니다. 공정위는 전분담 담합 사건을 수사한 검찰의 요청에 따라 이들 4개사 법인과 임직원들을 앞서 고발했습니다. 공정위의 심판 결과를 보면 4개 전분당 업체는 정부의 정책적 보호를 받고 있음에도 밀약으로 경쟁 질서를 왜곡한 것으로 평가됩니다. 이들은 전분당의 주원료인 수입 옥수수를 공동으로 수입합니다. 부는 전분당이 국민 물가, 산업 경쟁력 등에 미치는 영향을 고려해 2021년 4월부터 매년 200만t 내외의 가곡용 옥수수에 할당관세(0%)를 적용하고 있습니다. 그런데도 4개 업체는 2018년 5월부터 지난해 10월까지 13차례에 걸쳐 전분당 판매가격의 인상·인하 폭과 시기 등을 합의하고 이를 실행한 것으로 드러났습니다. 구체적으로 옥수수 가격 인상 시기에 원가 상승분을 신속히 반영해 판매 가격 인상을 합의한 것은 8차례로 나타났습니다. 옥수수 가격이 인하할 때 거래처의 가격 인하 요구에 대응해 인하 폭을 최소화하고 인하 시기를 최대한 늦추기로 합의한 것이 5차례에 달한 것으로 조사됐습니다. 이 과정에서 4개 업체는 가격 인하를 요구하는 대형 실수요처를 대상으로 가격을 인하하고, 소규모 실수요처·대리점에는 최대한 판매 가격을 유지해 반발을 최소화하고 이윤을 극대화했습니다. 4개 업체는 가격 변경의 경우 거래처의 저항을 최소화하기 위해 가격 변경의 폭과 시기, 가격 변경의 근거가 되는 환율, 원료가 등 공문에 담을 내용과 발송 시기도 구체적으로 합의했습니다. 특히 전분당 품목별 목표 가격을 합의한 뒤 그보다 높은 금액을 거래처에 통보해 거래처가 목표가격을 최대한 수용하도록 압박·유도하기도 했습니다. 4개 업체는 가격 합의대로 거래처에 공문을 발송하면서 이행 여부도 철저하게 점검한 것으로 나타났습니다. 실수요처에 공문을 발송하기로 한 날짜에 4개사 관계자들이 서로를 찾아가 공문에 품목별 인상 폭, 인상 시기, 공문 수신처 주소 등이 제대로 기재됐는지 꼼꼼히 살폈습니다. 이후 우체국까지 따라가 공문이 발송되는지 확인하기도 했습니다. 4개 업체는 또 전체 거래처에 가격 변경 계획을 통지한 후 필요한 경우 거래처와 가격 협상에 나서기도 했습니다. 이때 수요처별 가장 거래 비중이 높은 전분사가 협상을 주도하고, 다른 전분사는 주관사보다 높은 가격을 제시하면서 함께 목표 가격 수준으로 가격이 결정될 수 있도록 ''품앗이 대응''에도 나섰습니다. 예를 들어 4개 업체가 1㎏당 730원으로 판매 가격을 합의한 뒤 주관사는 실수요처에 목표 가격인 730원으로 가격을 제시하되 나머지 업체들은 735∼740원 등 합의 가격보다 높게 제시해 최대한 목표 가격을 수용하도록 유도했습니다. B2B 전분당 시장에서 이들 4개 업체의 점유율은 전분 95.7%, 전분당 86.4%에 달해 가격에 미치는 영향이 매우 컸다고 공정위는 지적했습니다. 특히 4개 업체는 코로나19, 러시아-우크라이나 전쟁 등으로 국민 경제 전반이 어려운 시기에 옥수수 가격 변동 부담을 거래처에 전가하고, 자신의 부당 이득을 극대화한 것으로 나타났습니다. 전쟁으로 국제 옥수수 가격이 급등하던 2022년 11월에는 판매 가격을 1㎏당 971원으로, 담합을 시작하던 시기(2018년 5월·1㎏당 559원)보다 최대 73%까지 급격히 올리기도 했습니다. 옥수수 가격이 하락하는 동안에는 원가 인하 폭보다 판매 가격 인하 폭을 줄였습니다. 이런 대응으로 인해 가격은 낮춰도 영업 이익이 오히려 개선됐습니다. 대상의 경우 영업 이익은 2023년 901억 원에서 2025년 1천505억 원으로, 사조는 140억 원에서 361억 원으로 개선됐다고 공정위는 전했습니다. 4개 업체의 짬짜미로 물가가 오르고 결국 실수요처와 대리점, 나아가 최종 소비자인 국민에게 부담이 전이됐다고 공정위는 판단했습니다. 4개 전분당 업체 담합의 영향을 받은 관련 매출액은 6조 525억 원에 달했습니다. 공정위는 이들이 조사·심의에 협조한 점을 과징금 감경 사유로 참작했습니다. 다만 대상의 경우 과거 법 위반을 반복한 적 있어 10% 가중했다고 덧붙였습니다. 공정위는 과징금과 함께 법 위반 행위 금지 명령, 독자적 가격 재결정 명령도 내렸습니다. 4개 업체는 국내에서 판매하는 전분당 제품 가격을 담합 전 수준으로 재결정하고, 향후 3년간 반기마다 변경 내용을 보고해야 합니다. 독자적 가격 재결정 명령은 밀가루 담합 제재(2006년 4월, 2026년 5월), 인쇄용지 담합 제재(2026년 4월)에 이어 네 번째로 부과됐습니다. 공정위는 담합이 장기간 지속된 점, 국내 전분당 시장이 과점 체제가 유지돼 담합 재발 우려가 큰 점 등을 고려했다고 설명했습니다.', 'crawl', 'SBS', '2026-07-07 14:27:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260323/202167743_1280.jpg', '2026-07-07 06:04:48', '2026-07-07 18:49:16.864825', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4468, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=03&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645421', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645421&plink=RSSLINK&cooper=RSSREADER', '사회', '검찰, 장윤기 아버지·경찰 유착 의혹 강제수사', '&#9650; 7일 전남광주통합특별시 광산구 광산경찰서에서 광주지검 수사관들이 압수수색을 하고 있다.경찰관 비위 사건의 직접 수사권을 가진 검찰…', '▲ 7일 전남광주통합특별시 광산구 광산경찰서에서 광주지검 수사관들이 압수수색을 하고 있다. 경찰관 비위 사건의 직접 수사권을 가진 검찰이 ''여고생 살해범'' 장윤기(23)의 아버지와 수사팀 간 유착 의혹 등을 들여다보는 직접 수사에 착수했습니다. 오늘(7일) 광주지검은 장윤기 사건을 담당했던 광주 광산경찰서에 수사관을 보내 압수수색 영장을 집행했습니다. 검찰은 형사과 담당 수사팀 관계자 등 다수 경찰관을 공무상비밀누설, 증거인멸, 증거인멸교사 등 혐의로 입건했습니다. 입건된 경찰관들은 지난 5월 5일 장윤기를 긴급체포한 뒤 검찰 송치까지 수사 과정에서 케이블타이·리얼돌·차량(SUV) 등 주요 증거물을 확보하지 않고, 현직 경찰인 장윤기 아버지에게 압수수색·구속영장 내용 등 수사 상황을 누설한 혐의를 받습니다. 입건된 경찰관들의 주거지도 압수수색했습니다. 검찰은 사건 하루 만에 수사팀이 장윤기 아버지에게 넘긴 차량(SUV)에서 결박 도구인 케이블타이가 사라지고, 그로부터 이틀 뒤에는 자취방 인계 조치로 리얼돌이 폐기된 이번 사안의 중대성을 고려해 직접 수사하기로 했습니다. 경감 계급의 현직 경찰인 장윤기 아버지는 리얼돌을 폐기하고 경찰 압수수색에서 빠졌던 아들의 과거 핸드폰을 소각하는 등 증거인멸 행위를 벌였으나, ''친족은 증거인멸죄로 처벌할 수 없다''는 형법상 특례에 따라 형사입건되지 않았습니다. 검찰보다 하루 앞서 장윤기 수사팀장인 A 경감(형사과)을 증거인멸 혐의로 긴급체포한 경찰은 이 사건을 검찰에 중도 이첩하지 않고 자체적으로 결론 낸다는 방침입니다. 또 48시간인 체포 시한을 고려해 오늘 오전 A 경감에 대한 구속영장을 신청했습니다. 수사 주체를 광주경찰청 전담팀에서 국가수사본부 특별팀으로 격상한 경찰은 오늘 인력을 광주로 파견했습니다. 경찰관이 저지른 범죄 행위는 검찰, 경찰이 각각 수사할 수 있습니다. (사진=연합뉴스)', 'crawl', 'SBS', '2026-07-07 14:33:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260707/202199743_1280.jpg', '2026-07-07 06:04:48', '2026-07-07 18:49:18.727594', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4470, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=03&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645414', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645414&plink=RSSLINK&cooper=RSSREADER', '사회', '양도세 피하려 엄마 친구와 가짜매매…국세청 80여 명 318억 추징', '&#9650; 오상훈 국세청 자산과세국장이 7일 정부세종2청사에서 부동산 탈세 혐의자 조사 결과를 발표하고 있다.2주택자인 A 씨는 두 채 중 …', '▲ 오상훈 국세청 자산과세국장이 7일 정부세종2청사에서 부동산 탈세 혐의자 조사 결과를 발표하고 있다. 2주택자인 A 씨는 두 채 중 저가인 아파트를 모친의 친구에게 팔았습니다. 이어 고가 아파트를 20억 원에 팔면서 1세대 1주택자 비과세를 적용해 양도세를 신고했습니다. 하지만 실상은 모친 친구와의 거래는 허위였습니다. A 씨는 양도 후 허위 전세계약을 맺어 계속 같은 집에 거주했고, 나중에 명의를 돌려받기까지 탈세 협조 대가로 매월 수십만 원의 사례비도 지원했습니다. A 씨는 국세청에 적발돼 중과세율을 적용한 양도세 10억 원을 추징당했습니다. 여기에 본인과 허위 거래를 주도한 모친, 모친 친구까지 조세포탈 혐의로 검찰 수사를 받게 됐습니다. B 씨는 40억 원 가치의 서울 강남권 재건축 예정 아파트를 비롯해 다수의 부동산을 취득했습니다. 국세청이 소득에 비해 부동산 취득 규모가 크다는 점을 수상히 여겨 조사한 결과, 배우자가 운영하는 축산물 도매업체 자금이 흘러 들어간 것을 확인했습니다. 조사 대상을 넓힌 결과 무자료 매출을 통해 조성한 비자금 약 30억 원이 B 씨에게 갔습니다. 국세청은 매출누락 법인세, B 씨의 부동산 취득자금 증여세 등 31억 원을 추징했습니다. 국세청은 지난해 10월 A·B 씨를 비롯한 부동산 탈세 혐의자 104명을 동시 조사해 오늘까지 80여 명의 총 731억 원 규모 탈루를 적발해 세금 318억 원을 추징했다고 오늘(7일) 밝혔습니다. 국세청은 사기나 그 밖의 부정한 방법으로 조세를 포탈한 사실이 확인된 건은 40%에 상당하는 부당 과소신고가산세를 부과했습니다. 아울러 조세범처벌법에 따라 6명은 검찰에 고발하고, 4명은 벌금 상당액 총 7억 원 납부를 통지하는 통고처분을 했습니다. 당사자뿐 아니라 A 씨의 모친 등 관련자도 함께 처분했습니다. 2주택자인 C 씨도 남편 친구를 활용해 비과세를 위한 가장매매를 벌였다가 6억 원 상당의 양도세를 추징당하고 검찰에 고발됐습니다. C 씨는 15억 원짜리 단독주택을 매각하기 전 아파트를 남편 친구에게 매각하는 것처럼 꾸미기 위해 거래 자금을 또다른 친구 등을 통해 남편 친구에게 우회 전달하는 방식으로 금융 증빙을 조작한 것으로 조사됐습니다. 30대 D 씨는 40억 원짜리 서울 강북 대형 아파트를 취득해 인테리어 비용으로만 수억 원을 썼습니다. 자금조달계획서에는 전액 예금으로 기재했지만, D 씨는 그럴 만한 소득원이 없어 조사 대상으로 선정됐습니다. 조사 결과 D 씨는 외국인을 상대로 숙소·식당 예약, 면세점 쇼핑·관광 등을 알선하는 미등록 여행업체를 운영하고 있었고, 현금 수입 60억 원을 신고하지 않은 것으로 파악됐습니다. 그는 부가가치세와 종합소득세 25억 원을 추징당했습니다. 국세청은 이른바 ''검머외''(검은 머리 외국인)라 불리는 외국 국적자의 증여세 탈루도 적발했습니다. E 씨는 실거주 목적 없이 마용성(마포·용산·성동구) 소재 고가아파트 2채를 외국인 배우자와 함께 30억 원에 공동 취득했습니다. 소득원이 없는 가정주부 E 씨는 주택 취득자금과 인테리어 자금 전액을 배우자에게 증여받고 증여세를 신고하지 않은 점이 확인됐습니다. 결국 내지 않은 세금 4억 원을 내게 됐습니다. ''부모 찬스''도 적발됐습니다. 서울 강남 한강변 소재 고가 아파트에 월세 700만 원을 내는 40대 F 씨는 수십억 원 규모의 주식을 취득하고, 매년 수억 원에 달하는 생활비를 지출하고 있었습니다. 조사 결과 20여억 원의 자금을 부모로부터 증여받은 것으로 확인됐고, 증여세 총 13억 원을 추징당했습니다. 이미지 확대하기 국세청은 명의신탁 등 부동산실명법 위반 행위가 확인된 20명도 과징금 부과와 형사처벌 조치가 이뤄지도록 관할 지방자치단체에 통보했습니다. 국세청은 앞으로도 부동산 취득·보유·양도 등 거래 전 과정에서 발생하는 탈세 위험요인을 조기에 포착하고, 탈세행위가 확인될 경우 세무조사를 실시하는 등 강력하게 대응해 나갈 방침입니다. 특히 다주택자 중과 재개 후 증여거래가 늘어날 우려가 있는 만큼 증여재산을 저가평가하거나 증여세를 대납하는 등 편법 증여가 없는지 검증할 예정입니다. ''부동산 탈세 신고센터''를 통해 접수한 제보를 철저히 검증해 탈루 세금을 추징하는 한편, 제보자 포상금도 신속히 지급할 계획입니다. 오상훈 국세청 자산과세국장은 "부동산 탈세 차단은 조세정의를 바로 세우는 일이자 주택시장의 안정과 신뢰를 회복하는 출발점으로, ''탈세는 반드시 적발된다''는 원칙을 지켜내겠다"고 강조했습니다. (사진=국세청 제공, 연합뉴스)', 'crawl', 'SBS', '2026-07-07 12:44:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260707/202199741_1280.jpg', '2026-07-07 06:04:48', '2026-07-07 18:49:22.341181', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4476, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=03&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645298', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645298&plink=RSSLINK&cooper=RSSREADER', '사회', '광주 광산경찰서 압수수색…''장윤기 수사팀'' 입건', '검찰이 여고생 살해범 장윤기 경찰 수사팀에 대한 첫 강제수사에 착수했습니다. 경찰 수사팀의 증거인멸 의혹과 함께 현직 경찰인 장윤기 아버지에 대…', '<앵커> 검찰이 여고생 살해범 장윤기 경찰 수사팀에 대한 첫 강제수사에 착수했습니다. 경찰 수사팀의 증거인멸 의혹과 함께 현직 경찰인 장윤기 아버지에 대한 수사 정보 유출 등을 규명할 방침입니다. 신용일 기자가 보도합니다. <기자> 검찰이 여고생 살해범 장윤기 사건 경찰 수사팀에 대한 강제수사에 나섰습니다. 광주지검은 오늘(7일) 오전부터 공무상 비밀누설과 증거인멸 등 혐의로 광주광산경찰서 등을 압수수색하고 있습니다. 검찰은 사건을 담당했던 광주 광산경찰서와 수사팀 경찰관들을 입건했고, 광산경찰서와 이들의 주거지 등에 수사관을 보내 압수수색을 진행하고 있습니다. 현행법상 검찰은 경찰의 직무상 비위 사건에 대해 직접 수사 개시할 수 있습니다. 앞서 경찰 수사팀은 지난 5월 여고생 살해 사건이 발생한 직후 광주 지역 현직 경찰 간부인 장윤기의 아버지 A 경감에게 장윤기 집 주소와 비밀 번호를 알려준 것으로 드러났는데, 이후 A 경감은 장윤기의 주거지에서 강간 살인 범행의 핵심 증거물인 성인용품 ''리얼돌''을 직접 폐기한 걸로 파악됐습니다. 경찰 수사팀은 또 A 경감에게 장윤기에 대한 구속 영장 신청 예정 사실과 영장 내용을 미리 알려주는 등 수사 기밀 사항을 공유한 것으로도 드러났습니다. 경찰 수사팀은 국립과학수사연구원의 DNA 감식 보고서도 확보해 놓고 검찰에 송치하지 않다가, 최근 경찰의 부실 수사가 논란이 되자 사건 발생 두 달 만에 뒤늦게 넘기기도 했습니다. 다만 A 경감의 증거인멸 혐의는 친족 특례법이 적용돼 형사 처벌할 수 없는 만큼, 검찰은 장윤기의 아버지인 A 경감은 별도로 입건하지는 않은 것으로 알려졌습니다. 검찰은 이 사건의 중대성 등을 감안해 경찰이 진행하는 수사와 별개로 이번 사안을 직접 수사하기로 결정한 것으로 알려졌습니다. (영상취재 : 정경문, 영상편집 : 신세은)', 'crawl', 'SBS', '2026-07-07 12:10:00', '중도', 'ready', 'https://img.sbs.co.kr/news/pc/thumb_v3.png', '2026-07-07 06:04:48', '2026-07-07 18:49:35.730949', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4479, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=03&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645307', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008645307&plink=RSSLINK&cooper=RSSREADER', '사회', '''피습 자작극 의혹'' 정이한 전 부산시장 후보 구속영장 청구', '&#9650; 정이한 개혁신당 부산시장 후보가 지난 6·3 지방선거를 앞두고 4월 29일 부산 구포시장에서 목에 깁스를 하고 선거 유세를 하는 …', '▲ 정이한 개혁신당 부산시장 후보가 지난 6·3 지방선거를 앞두고 4월 29일 부산 구포시장에서 목에 깁스를 하고 선거 유세를 하는 모습 6·3 지방선거 당시 선거운동 중 피습당했다고 주장했다가 자작극 의혹이 제기된 정이한 전 개혁신당 부산시장 후보에 대해 구속영장이 청구됐습니다. 부산 금정경찰서에 따르면 경찰은 위계공무집행방해와 공직선거법 위반 등 혐의로 정 전 후보와 음료를 던진 A 씨에 대한 구속영장을 지난 1일 신청했고, 검찰은 지난 3일 부산지법에 영장을 청구했습니다. 경찰은 증거인멸과 도주 우려 등을 이유로 구속영장을 신청한 것으로 알려졌습니다. 정 전 후보 등 2명에 대한 구속 전 피의자 심문은 8일 오후 2시 부산지법에서 열립니다. 이번 구속영장 신청은 사건 발생 67일, 선거가 끝난 지 한 달여 만에 이뤄진 것입니다. 정 전 후보는 지난 4월 27일 부산 금정구 구서 나들목 인근에서 유세하던 중 지나가던 차량 운전자가 차창 밖으로 던진 음료에 맞아 쓰러졌다고 주장했습니다. 당시 캠프는 정 전 후보가 음료를 피하려다 넘어져 의식을 잃고 병원으로 옮겨졌으며, 뇌진탕과 근좌상 진단을 받았다고 밝혔습니다. 이후 경찰은 사건 경위에 석연치 않은 점이 있다고 보고 정 전 후보와 A 씨의 관계, 사건 전후 연락 여부, 공모 가능성 등을 수사해왔습니다. A 씨는 정 전 후보와 친분이 있던 헬스장 트레이너 겸 관장으로 알려졌습니다. 경찰은 두 사람이 사건 전 연락한 정황 등을 토대로 사전 공모 여부를 확인해온 것으로 전해졌습니다. 경찰은 선거 다음 날 정 전 후보 캠프로 사용된 사무실을 압수수색하고, 당시 캠프 관계자들을 참고인으로 불러 사건 당시 정 전 후보의 상태와 언론 대응 경위 등을 확인했습니다. 이와 별도로 경찰은 정 전 후보 부친이 운영하는 온그룹 계열사 직원들이 선거운동에 동원됐다는 의혹과, 정 전 후보 관련 여론조사기관의 공정성 의혹 등도 수사하고 있습니다. 정 전 후보는 6·3 지방선거 부산시장 선거에서 2만7천418표를 얻어 득표율 1.56%로 3위를 기록했습니다. 개혁신당은 앞서 정 전 후보가 탈당한 상태라며 수사에 적극 협조하겠다는 입장을 밝혔습니다. 경찰 관계자는 "이번 구속영장 청구는 테러 자작극 의혹에 한정된 것"이라면서 "나머지 혐의에 대해서는 수사하고 있다"고 말했습니다. (사진=연합뉴스)', 'crawl', 'SBS', '2026-07-07 11:49:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260707/202199718_1280.jpg', '2026-07-07 06:04:48', '2026-07-07 18:49:41.443146', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4503, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=07&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644982', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644982&plink=RSSLINK&cooper=RSSREADER', '국제', '"미·영 투자사 3곳, SK하이닉스 ADR 최대 70억 달러 인수 의사"', '&#9650; SK하이닉스전직 오픈AI 연구원이 설립한 미국 헤지펀드 등 세 곳이 SK하이닉스의 미국주식예탁증서 공모에 최대 70억달러어치를 인…', '▲ SK하이닉스 전직 오픈AI 연구원이 설립한 미국 헤지펀드 등 세 곳이 SK하이닉스의 미국주식예탁증서(ADR) 공모에 최대 70억달러(약 10조7천억원)어치를 인수할 수 있음을 시사했다고 파이낸셜타임스(FT)가 6일(현지시간) 보도했습니다. FT에 따르면 이들은 미국 헤지펀드 시추에이셔널 어웨어니스(Situational Awareness), 영국 자산운용사 베일리 기포드(Baillie Gifford), 미국 벤처캐피탈 코튜(Coatue) 등 3곳입니다. 이는 전체 공모 물량 43조1천400억원(280억달러)의 4분의 1에 달합니다. 전직 오픈AI 연구원 리오폴드 애션브레너가 설립한 시추에이셔널 어웨어니스는 인공지능(AI) 관련 종목에 대한 선구적 투자로 개인 투자자들 사이에서 큰 관심을 받아온 곳입니다. 베일리 기포드는 혁신 기업을 발굴해 초기 단계부터 장기간 보유하는 성장주 투자에 강점을 보이는 곳이며 코튜는 테크 기업에 대한 공격적 투자로 유명한 벤처캐피탈입니다. SK하이닉스는 발행주식의 약 2.5%에 해당하는 신주 1천779만주를 ADS 형태로 발행해 오는 10일 나스닥에서 거래를 시작할 예정입니다. 로이터 통신에 따르면 페트라 캐피털 매니지먼트의 알버트 용 매니징 파트너는 최근 시장 변동성이 큰 점을 언급하면서도 "SK하이닉스 주식 수요가 상대적으로 견조할 것"이라고 내다봤습니다. 반면 스탠다드차타드의 순딥 간토리 주식 부문 최고투자책임자는 미국 상장에 따른 접근성 개선은 긍정적이라면서도 "메모리 사이클의 타이밍도 그만큼 중요하다"며 신중론을 폈습니다. AJ벨의 다니엘 코츠워스 시장총괄은 "이번 상장이 다소 늦은 것은 아닌지"라며 의구심을 보이면서 "메모리 반도체주가 최근 몇 주간 상승 모멘텀을 잃었지만, 투자자들은 SK하이닉스를 일시적 유행이 아닌 견조한 장기 성장 스토리로 볼 수도 있다"고 블룸버그 통신에 전했습니다.', 'crawl', 'SBS', '2026-07-07 10:18:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260618/202193806_1280.jpg', '2026-07-07 06:04:49', '2026-07-07 18:50:28.553559', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4510, 'https://news.sbs.co.kr/news/SectionRssFeed.do?sectionId=07&plink=RSSREADER', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644825', 'https://news.sbs.co.kr/news/endPage.do?news_id=N1008644825&plink=RSSLINK&cooper=RSSREADER', '국제', '베네수 지진 사망자 3천535명…"어린이 구조 보도는 오보"', '&#9650; 베네수엘라 구조 현장지난달 24일 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3천535명으로 늘었다고 호르헤 로드리게스 국회의…', '▲ 베네수엘라 구조 현장 지난달 24일(현지시간) 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3천535명으로 늘었다고 호르헤 로드리게스 국회의장이 6일 밝혔습니다. 전날보다 193명 늘어난 수치입니다. 부상자 숫자는 전날과 변동 없는 1만 6천740명, 이재민은 1만 7천854명으로 집계됐습니다. 이번 지진을 통해 피해를 본 건물은 856채이며, 붕괴한 건물은 총 190채라고 로드리게스 의장은 설명했습니다. 정부는 육군과 보안군 2만 9천567명을 투입했으며 이들은 자원봉사자 2만 7천930명과 함께 구조·복구 작업을 진행하고 있습니다. 수만 명이 구조작업에 나서고 있으나 지진이 발생한 지 열흘이 넘으면서 매몰자들의 생환 가능성은 크게 줄어든 상태입니다. 구조에 대한 기대가 크다 보니 관련 오보도 이어지고 있습니다. 소셜미디어(SNS) 등을 통해 알려졌던 지진 11일 만에 어린이 등 4명 구조 소식은 현지 언론의 오보인 것으로 확인됐습니다. 이날 현지 유력 일간 엘나시오날은 전날 밤 9시쯤 라과이라주 카라바예다에서 구조대가 어린이 등 4명을 구조했다고 보도했으나, 이는 사실이 아니라고 바로잡았습니다. 엘나시오날은 해당 영상이 최근 발견된 게 아닌 이전에 있었던 구조 장면이라면서 이같이 정정했습니다. 베네수엘라 당국도 구조 대원들이 6천462명을 구조했으며 이 수치는 지난 2일 이후 변동이 없다고 밝혔습니다. (사진=AP, 연합뉴스)', 'crawl', 'SBS', '2026-07-07 09:35:00', '중도', 'ready', 'https://img.sbs.co.kr/newimg/news/20260707/202199667_1280.jpg', '2026-07-07 06:04:49', '2026-07-07 18:50:43.806973', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4575, 'https://rss.etoday.co.kr/eto/economy_news.xml', 'https://www.etoday.co.kr/news/view/2601061', 'https://www.etoday.co.kr/news/view/2601061', '경제', '7년간 빵·과잣값 올린 전분당업계 담합 철퇴…과징금 역대 최대 7476억', '전분·전분당 제조·판매 4사, 7년 5개월에 걸쳐 장기간 담합 원가 오를 땐 빠르게, 원가 내릴 땐 느리게 판매가에 반영 러우전...', '전분·전분당 제조·판매 4사, 7년 5개월에 걸쳐 장기간 담합 원가 오를 땐 빠르게, 원가 내릴 땐 느리게 판매가에 반영 러우전쟁 땐 판매가 최대 73% 인상해 영업이익 하락 최소화 ▲공정거래위원회 (이투데이DB) 대상, 사조CPK, 삼양사, CJ제일제당 등 전분·전분당 제조·판매 4사가 과자·빵 등 먹거리는 물론 제지·철강 등 산업용 원재료로 쓰이는 전분당 판매 가격을 담합한 사실이 적발돼 총 7400억 원대의 과징금을 물게 됐다. 그간 공정거래위원회가 담합 사건에 부과한 과징금 중 역대 최대 규모다. 공정위는 이들 4사에 대해 법 위반행위 금지명령, 독자적 가격 재결정 명령 등의 시정 명령과 과징금 총 7475억 7800만 원을 부과했다고 7일 밝혔다. 이는 지난 5월 밀가루 가격을 밀약한 7개 업체에 매긴 6710억 원을 뛰어넘는다. 공정위의 담합 제재 사상 역대 최대 규모다. 이번 사건은 과점 구조가 장기간 유지된 시장에서 가격 담합이 이뤄졌다는 점에서 중대성이 크다는 평가를 받는다. 남동일 공정위 부위원장은 이날 브리핑에서 "국내 전분 및 전분당 시장에서 지배적 지위를 가진 전분사들은 담합 행위를 통해 옥수수 가격이 상승하는 동안 영업이익의 하락을 최소화할 수 있었다"며 "담합으로 인한 피해는 후방산업을 영위하는 실수요처와 대리점, 나아가 최종 소비자에게 전가됐다"고 설명했다. 4개 전분당 업체는 정부의 정책적 보호를 받고 있는데도 밀약해 경쟁 질서를 왜곡했다. 이들은 전분당의 주원료인 수입 옥수수를 공동으로 수입한다. 정부는 전분당이 국민 물가, 산업 경쟁력 등에 미치는 영향을 고려해 2021년 4월부터 매년 200만t 내외의 가곡용 옥수수에 할당관세(0%)를 적용하고 있다. 그런데도 4개 전분당 업체는 2018년 5월부터 2025년 10월까지 옥수수 가격이 인상·인하되는 시기에 총 13차례에 걸쳐 판매가격을 합의하고 실행했다. 이 과정에서 전분사들은 가격 인하를 강하게 요구하는 대형 실수요처의 가격은 인하해주면서 소규모 실수요처나 대리점 등은 최대한 판매가격을 유지해 이윤을 극대화했다. 또한 이들 업체는 가격 변경 폭과 시기, 가격 변경의 근거, 공문 발송 시기 등 세부적인 내용도 합의했다. 특히 4개사는 전분당 품목별 목표 가격을 합의한 뒤 전분사별로 그보다 높은 금액을 차례로 거래처에 통보해 거래처가 목표 가격을 최대한 수용하도록 압박·유도했다. 이들은 가격 합의대로 거래처에 공문을 발송하면서 이행 여부도 철저하게 점검했다. 실수요처에 공문을 발송하기로 한 날짜에 4개사 관계자들이 서로를 찾아가 공문에 품목별 인상 폭, 인상 시기, 공문 수신처 주소 등이 제대로 기재됐는지 꼼꼼히 살폈다. 이후 우체국까지 따라가 공문이 발송되는지 확인하기도 했다. 특히 전분사들은 전체 거래처에 가격 변경을 통지한 뒤 필요한 경우 협상을 진행했다. 이때 거래처와 가장 거래를 많이 하던 전분사가 앞장서서 협상을 주도했다. 나머지 전분사들은 일부러 이보다 더 비싼 가격을 제시하며 거래처를 압박했고, 결국 거래처가 미리 짜둔 목표 가격을 받아들이도록 유도했다. B2B 전분당 시장에서 4개 업체의 점유율은 전분 95.7%, 전분당 86.4%에 달한다. 특히 이들은 국제 옥수수 가격 상승기에는 전분당 판매가격을 인상했고 옥수수 가격 하락기에는 가격 인하를 최대한 지연시켰다. 러시아·우크라이나 전쟁으로 국제 옥수수 가격이 급등하자 담합을 시작했던 2018년 5월보다 판매가격을 최대 73%까지 인상하기도 했다. 이로 인해 전분사들은 옥수수 가격이 상승하는 동안에도 영업이익 하락을 최소화할 수 있었다. 옥수수 가격이 하락하는 동안에는 원가 인하 폭에 비해 판매가격 인하 폭을 최소화했다. 이런 대응으로 가격은 낮춰도 오히려 영업이익은 개선됐다. 대상의 경우 영업 이익은 2023년 901억 원에서 2025년 1505억 원으로, 사조는 140억 원에서 361억 원으로 개선됐다. 이후 실수요처와 대리점을 거쳐 최종 소비자에 대한 물가 인상 요인으로 고스란히 전가됐다. 공정위 관계자는 "이 사건은 장기간 국내 전분당 시장에서 지속한 전분사들의 가격 담합을 제재한 사건"이라며 "최근 공정위가 조치한 제당사, 제분사, 제지사 등의 담합 사건에 이어 국민이 피부로 체감하는 식품 등의 가격을 안정시키고 독과점 사업자들이 담합을 통해 부당하게 가격을 인상하는 행위에 경종을 울릴 수 있을 것으로 기대된다"고 밝혔다.', 'crawl', '이투데이', '2026-07-07 14:07:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/04/20260428060818_2326998_1179_560.jpeg', '2026-07-07 06:04:50', '2026-07-07 18:53:12.772978', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4584, 'https://rss.etoday.co.kr/eto/economy_news.xml', 'https://www.etoday.co.kr/news/view/2601000', 'https://www.etoday.co.kr/news/view/2601000', '경제', '"아직 안 끝났다"...공정위, 전분당 입찰·부산물 가격 담합 심의 개시', '공정위, 대상·사조CPK·삼양사·CJ제일제당 등에 심사보고서 송부전분당 밀약한 4개사, 최대 과징금 7476억 원 부과받고 또 심...', '공정위, 입찰ㆍ부산물 담합 추가 심의 과징금 최대 5000억 부과할수도 ▲공정거래위원회 (이투데이DB) 대상·사조CPK·삼양사·CJ제일제당 등 전분당 제조사들이 또다시 공정거래위원회의 심판대에 올랐다. 장기간 입찰과 부산물 가격을 담합한 혐의로 추가 과징금 규모가 수천억원에 이를 가능성이 제기된다. 공정위 사무처는 4개 전분당 제조 및 판매사업자들의 위반 혐의와 제재 의견을 담은 심사보고서를 당사자에게 송부하고 위원회에 제출했다고 7일 밝혔다. 전분당 입찰담합 협의를 받는 곳은 대상, 사조CPK, 삼양사, CJ제일제당이며, 전분당 부산물 가격 담합 혐의를 받는 곳은 대상, 사조CPK, 삼양사다. 심사보고서는 공정위 심사관이 파악한 위법 행위 사실과 제재 의견을 담은 문서로, 형사소송의 공소장에 해당한다. 심사보고서가 당사자에게 송부되면서 전분당 제조 및 판매사업자에 대한 공정위의 제재 절차가 본격적으로 시작됐다. 심사관은 전분당 제조 및 판매사업자들이 2016년 9월부터 2025년 6월까지 포스코 등 7개 대형 실수요처가 발주한 전분 및 전분당 구매 입찰에 참여하면서 사전에 낙찰예정자, 낙찰순위, 투찰가격, 투찰물량 등을 합의하고 낙찰물량을 배분하는 등의 입찰담합 및 물량 배분 담합행위를 했다고 판단했다. 이 사건 담합행위로 영향받은 관련 매출액은 9400억 원에 이르는 것으로 추산됐다. CJ제일제당을 뺀 나머지 3개 업체는 2017년 8월부터 2025년 10월까지 매달 전분당 부산물 제품의 판매 가격을 밀약한 혐의도 받고 있다. 공정위는 전분당 부산물 담합 관련 매출액이 1조5500억 원에 이른다고 산정했다. 전분당 부산물은 전분당을 가공하는 과정에서 부수적으로 생성되는 글루텐·단백피·배아 등이며 가축용 사료·식용유 원료로 사용된다. 심사관은 이런 행위가 공정거래법 제40조 제1항 제1호(가격담합), 제3호(물량담합) 또는 제8호(입찰담합)를 위반하는 ''매우 중대한 위법행위''를 저질렀다고 판단하고 시정조치 및 과징금 부과 의견을 제시했다. 향후 공정위는 심의를 거쳐 관련 법령에 따라 담합행위로 영향을 받은 관련 매출액의 최대 20%까지 과징금을 부과할 수 있다. 관련 매출액에 비춰보면 과징금 규모는 전분당 입찰 담합은 1880억 원, 부산물 가격 담합은 3100억 원까지 가능하다. 심사보고서를 받은 업체는 8주 내 서면 의견 제출, 증거자료 열람·복사 등을 통해 방어권을 행사할 수 있다. 공정위는 피심인의 방어권을 보장하는 절차를 마치는 대로 최대한 신속하게 전원회의를 열어 처분을 결정한다는 방침이다. 공정위 관계자는 "민생을 위협하는 담합행위에 대해서는 집중 감시 및 엄중한 법 집행을 통해 담합 유인이 실질적으로 차단될 수 있도록 노력하겠다"고 밝혔다.', 'crawl', '이투데이', '2026-07-07 12:39:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/04/20260428060818_2326998_1179_560.jpeg', '2026-07-07 06:04:50', '2026-07-07 18:53:37.939084', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4585, 'https://rss.etoday.co.kr/eto/economy_news.xml', 'https://www.etoday.co.kr/news/view/2601018', 'https://www.etoday.co.kr/news/view/2601018', '경제', '초고가 아파트 돈줄 캐보니 부모·회사…부동산 탈루 731억원 들통', '104명 세무조사로 318억원 추징…6명 검찰 고발 가장매매·편법증여·법인자금 유출 등 부동산 탈세 적발 부동산실명법 위반 20...', '104명 세무조사로 318억원 추징…6명 검찰 고발 가장매매·편법증여·법인자금 유출 등 부동산 탈세 적발 부동산실명법 위반 20명 지자체 통보…다주택자 증여거래 검증 ▲오상훈 국세청 자산과세국장이 7일 정부세종청사에서 초고가주택 등 부동산 탈세 혐의자에 대한 조사 결과를 브리핑하고 있다. (사진제공=국세청) 초고가 아파트를 사들이면서 부모에게서 편법으로 자금을 받거나, 회사 자금을 빼돌려 취득자금으로 쓴 부동산 탈세 사례가 대거 적발됐다. 다주택자가 지인이나 가족에게 주택을 형식상 넘긴 뒤 1세대 1주택자인 것처럼 꾸며 양도소득세 를 피한 가장매매도 조사망에 걸렸다. 국세청은 7일 브리핑을 열고 초고가주택 등 부동산 탈세 혐의자 104명에 대한 세무조사 결과 현재까지 731억원의 탈루금액을 확인하고 318억원을 추징했다고 밝혔다. 이번 조사는 지난해 10월 1일 착수한 부동산 탈세 동시조사의 중간 결과다. 국세청은 조사 과정에서 사기나 그 밖의 부정한 행위로 세금을 포탈한 6명을 검찰에 고발했다. 4명에 대해서는 벌금 상당액 7억원을 통고처분했다. 명의신탁 등 부동산실명법 위반 행위가 확인된 20명에 대해서는 과징금 부과와 형사처벌 등 조치가 이뤄질 수 있도록 관할 지방자치단체에 통보했다. ▲대금지급 능력이 없는 지인에게 허위로 저가아파트를 이전하고 고가아파트를 비과세 받은 것이 확인돼 검찰 고발 조치. (자료제공=국세청) 대표적인 수법은 가장매매였다. 2주택자인 A씨는 서울 소재 고가아파트를 팔기 전 자신이 살던 저가아파트를 모친 지인에게 형식상 이전했다. 이후 고가아파트를 약 20억원에 팔면서 1세대 1주택 비과세를 적용했다. 그러나 조사 결과 A씨는 명의상 매수인의 저가아파트 취득세와 재산세 를 대신 내고, 양도 뒤에도 계속 거주한 것으로 드러났다. 국세청은 양도세 10억원을 추징하고 A씨와 모친, 명의를 빌려준 지인을 검찰에 고발했다. 가족 간 형식 거래도 적발됐다. 한 다주택자는 거액의 양도세가 예상되자 다가구주택의 건물만 동생에게 넘긴 뒤 아파트를 팔면서 비과세를 적용받았다. 하지만 매매대금 거래 내역이 확인되지 않았고, 양도 이후에도 세입자 월세를 본인이 계속 받은 것으로 조사됐다. 국세청은 양도세 4억원을 추징하고 본인과 동생에게 각각 1억여원씩 통고처분했다. ▲매출 누락한 법인자금을 유출해 배우자의 고가아파트 취득자금으로 사용 (자료제공=국세청) 초고가 아파트 취득자금 출처를 추적한 끝에 법인자금 유출이 드러난 사례도 나왔다. 50대 B씨는 약 40억원 규모의 서울 강남권 재건축 예정 아파트 등 다수 부동산을 취득했다. 자금 흐름을 추적한 결과 배우자가 운영하는 축산물 도매업체의 무자료 매출로 조성한 비자금 약 30억원이 B씨에게 증여된 사실이 확인됐다. 국세청은 법인세와 증여세 등 31억원을 추징했다. 미등록 여행업으로 거둔 현금 매출을 신고하지 않고 초고가 아파트를 산 30대도 적발됐다. 이 납세자는 서울 강북의 70여 평형 대형 아파트를 약 40억원에 취득했지만, 외국인 대상 미등록 여행서비스업을 운영하며 현금 수입 60여억원을 신고하지 않은 것으로 조사됐다. 국세청은 해당 사업장을 직권으로 사업자등록하고 부가가치세와 종합소득세 25억원을 추징했다. 오상훈 국세청 자산과세국장은 “국세청은 부동산 취득·보유·양도 등 거래 전 과정에서 발생하는 탈세 위험요인을 조기에 포착하고, 탈세가 확인되면 세무조사 등으로 강력하게 대응하겠다”며 “다주택자 증여거래, 가족 간 저가 양도, 매매 형식을 위장한 사실상 증여 등 세금 회피 목적의 편법거래도 꼼꼼히 살피겠다”고 말했다. 이어 “부동산 탈세 차단은 조세정의를 바로 세우는 일이자 주택시장 안정과 신뢰 회복의 출발점”이라며 “탈세는 반드시 적발된다는 원칙을 지키겠다”고 덧붙였다.', 'crawl', '이투데이', '2026-07-07 12:00:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707112209_2356022_1199_552.jpg', '2026-07-07 06:04:50', '2026-07-07 18:53:39.934794', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4587, 'https://rss.etoday.co.kr/eto/economy_news.xml', 'https://www.etoday.co.kr/news/view/2601062', 'https://www.etoday.co.kr/news/view/2601062', '경제', '홈플러스 집단체불 우려 확산⋯노동부 전수조사 중', '홈플러스의 파산 위기가 고조되는 가운데, 대규모 임금체불 우려도 확산하고 있다. 고용노동부도 임금체불 발생 가능성을 염...', '▲서울회생법원이 홈플러스의 기업회생절차 지속 여부를 결정하는 3일 서울 시내의 한 홈플러스 매장 앞으로 시민들이 지나고 있다. 이날 서울회생법원 4부(재판장 정준영 법원장)는 회생계획안의 수행 가능성을 검토한 뒤 관계인 집회에 부칠지, 회생계획안을 배제하고 회생절차를 폐지할지 결정한다. 앞서 홈플러스는 작년 3월 회생절차를 개시한 뒤 회생계획안 가결 기한을 올해 3월과 5월 두 차례 연장했다. 고성준 기자 joonko1@ (이투데이DB) 홈플러스의 파산 위기가 고조되는 가운데, 대규모 임금체불 우려도 확산하고 있다. 고용노동부도 임금체불 발생 가능성을 염두에 두고 상황을 모니터링 중이다. 7일 고용노동부에 따르면, 노동부는 홈플러스 임금체불이 발생한 지난해 12월부터 서울남부지청에 전담반(TF)을 구성해 홈플러스 사태에 대응하고 있다. 노동부 전수조사와 청산 지도로 5월까지 발생한 체불임금은 청산됐으나, 법원의 홈플러스 기업회생절차(법정관리) 폐지를 결정으로 파산 가능성이 커지면서 대규모 임금체불 가능성이 대두한다. 홈플러스는 월급 정기지급일이 매달 21일인데, 아직 6월분이 지급되지 않은 것으로 알려졌다. 여기에 퇴직급여 체불도 우려된다. 홈플러스 본사는 이미 “자금 부족으로 6월 중순 퇴직자의 퇴직급여 지급이 지연된다”고 공지한 상태인데, 퇴직자는 계속 증가하고 있다. 다만, 현 시점에선 임금체불이 발생했다고 판단하기 어렵다. 현재 6월 임금에 대해 전수조사가 진행 중이서 미지급 임금은 1개월분 뿐이다. 또 퇴직급여는 퇴직 후 14일이 지난 날부터 체불로 판단된다. 노동부 관계자는 “현재 남은 임금은 6월분인데, 7월 21일까지는 상황을 지켜보려 한다”며 “퇴직급여는 퇴직자가 체불 가능성이 있으나, 모든 퇴직자가 퇴직 후 14일이 지난 것이 아니고 당사자 간 합의로 지급일을 변경할 수 있기에 ‘퇴직급여가 체불됐다’고 말하기 어렵다. 상황은 유동적이다”라고 설명했다. 한편, 홈플러스가 자금을 조달해 회생절차 폐지 결정일(3일)로부터 14일 이내에 즉시항고하면 회생절차 폐지결정이 취소될 수 있다. 즉시항고를 제기하지 않으면 폐지 결정이 확정된다.', 'crawl', '이투데이', '2026-07-07 11:50:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707105007_2355986_1000_1503.jpg', '2026-07-07 06:04:50', '2026-07-07 18:53:43.698998', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4592, 'https://rss.etoday.co.kr/eto/economy_news.xml', 'https://www.etoday.co.kr/news/view/2600967', 'https://www.etoday.co.kr/news/view/2600967', '경제', '구윤철 "부동산 보유세·거래세 함께 손질"…이달 말 세제개편안 발표', '실거주 중심 부동산 세제 개편 추진…국민 의견 수렴 후 최종안 확정 지방 근로자 세제 혜택·미래대응기금도 검토 정부가 이달...', '실거주 중심 부동산 세제 개편 추진…국민 의견 수렴 후 최종안 확정 지방 근로자 세제 혜택·미래대응기금도 검토 ▲구윤철 부총리 겸 재정경제부 장관이 6일 서울 중구 웨스틴 조선 서울에서 열린 서비스산업 경쟁력 강화 TF 2차회의에서 모두발언을 하고 있다. (사진제공=연합뉴스) 정부가 이달 말 발표를 목표로 준비 중인 세제개편안을 통해 부동산 세제를 손질한다. 보유세와 거래세를 함께 개편하는 방안을 검토하는 한편 실거주 중심의 주택시장 확립에 초점을 맞출 방침이다. 지방 근로자에 대한 세제 혜택과 미래산업 투자 재원 마련 방안도 세제개편 논의에 포함될 전망이다. 구윤철 부총리 겸 재정경제부 장관은 7일 MBC 라디오 ''김종배의 시선집중''에 출연해 "7월 말 정도 발표를 생각으로 준비 중"이라며 "기본적으로 집은 ''사는(buying) 대상이 아니라 거주(living)하는 곳''이라는 원칙 아래 실거주자 중심으로 주택시장이 확립될 수 있도록 보고 있다"고 밝혔다. 최근 정부와 여당은 집값 안정과 실수요자 보호를 위해 부동산 세제 개편을 검토해 왔다. 구 부총리는 공정시장가액비율 조정과 비거주 장기보유특별공제 축소 등 구체적인 개편 방안에 대해서는 "국민의 한 의견인 만큼 살펴보겠다"고 말했다. 이어 "보유세와 거래세 두 가지가 균형을 이뤄야 한다는 차원에서 함께 보고 있다"며 두 세제를 함께 손질하는 방향을 검토하고 있다고 설명했다. 최종 개편안은 국민 의견과 현장 목소리를 수렴한 뒤 확정할 계획이다. 구 부총리는 지방 균형발전을 위한 세제 지원 방안도 공개했다. 그는 "지방에서 근로하는 분들은 서울에 거주할 때보다 소득세 감면을 더 해주고, 경우에 따라 자녀 교육비 지원도 검토할 수 있다"며 "소득공제나 세액공제 등 방법은 지역 근로자의 희망 사항을 감안해 검토하고 있다"고 말했다. 이는 정부가 추진하는 AI 반도체 중심의 3대 메가 프로젝트에 필요한 인력을 지역으로 유치하기 위한 지원책의 하나로 풀이된다. 구 부총리는 "전국의 운동장을 골고루 활용할 계획"이라며 호남은 반도체 제2생산기지, 충청은 반도체 패키징, 영남은 AI 반도체 소재·부품·장비 중심지 등 지역별 특성화 전략을 제시했다. 반도체와 AI 등 미래산업에 대한 세제 지원도 확대한다. 구 부총리는 연구개발(R&D)과 투자에 대한 세제 지원을 강화하고 이월공제 확대도 검토하는 한편, 반도체 호황으로 늘어날 추가 세수를 활용한 미래대응기금을 조성해 AI, 로봇, 조선, 항공 등 미래산업과 청년 AI 교육·창업 등에 투자하겠다고 밝혔다. 관련 법안은 가능하면 오는 9월 정기국회 전에 마련하겠다는 방침이다.', 'crawl', '이투데이', '2026-07-07 09:41:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260706094414_2355348_1198_687.jpg', '2026-07-07 06:04:50', '2026-07-07 18:53:55.131728', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4597, 'https://rss.etoday.co.kr/eto/global_news.xml', 'https://www.etoday.co.kr/news/view/2601113', 'https://www.etoday.co.kr/news/view/2601113', '국제', 'SK하닉, 뉴욕증시 데뷔 흥행 청신호⋯미ㆍ영 큰손 3곳, 최대 70억달러 투자 시사', '전 오픈AI 연구원 세운 헤지펀드 참여 눈길 IPO 공모 물량 4분의 1 수준 SK하이닉스 미국주식예탁증서(ADR)의 나스닥거래소 ...', '전 오픈AI 연구원 세운 헤지펀드 참여 눈길 IPO 공모 물량 4분의 1 수준 ▲SK하이닉스 이천시 본사 모습. (뉴시스) SK하이닉스 미국주식예탁증서(ADR)의 나스닥거래소 상장 흥행 청신호가 켜졌다. 6일(현지시간) 파이낸셜타임스(FT)에 따르면 미국과 영국의 기관투자자 세 곳이 SK하이닉스 ADR 기업공개( IPO )에 최대 70억달러(약 10조7000억원)를 투자할 의향이 있음을 시사했다. 세 곳은 미국 헤지펀드 시추에이셔널어웨어니스, 영국 자산운용사 베일리기포드, 미국 벤처캐피털 코튜 등이다. 특히 전직 오픈AI 연구원인 리오폴드 애션브레너가 설립한 시추에이셔널어웨어니스는 AI 관련 주식에 대한 선제적 투자를 연이어 진행하면서 개인 투자자들 사이에서 큰 인기를 얻고 있어 SK하이닉스에 대한 베팅이 주목된다. 베일리기포드는 혁신 기업을 발굴해 초기 단계부터 장기간 보유하는 성장주 투자에 강점을 보이는 곳이다. 코튜는 테크기업에 대한 공격적 투자로 유명한 벤처캐피털이다. 70억달러는 SK하이닉스의 이번 전체 공모 물량 43조1400억원(약 280억달러)의 4분의 1 수준이라고 FT는 전했다. SK하이닉스는 전체 발행주식의 약 2.5%에 해당하는 신주 1779만 주를 ADR 형태로 나스닥에 10일 상장할 계획이다. 상장 이후 미국 투자자들의 접근성이 크게 높아지고 나스닥100 등 주요 지수 편입 자격도 확보하게 된다. 이에 따라 관련 상장지수펀드(ETF)와 인덱스펀드의 기계적인 매수 수요도 기대된다. 시장에서는 특히 SK하이닉스가 미국 경쟁사인 마이크론테크놀로지 수준의 기업가치를 인정받을 수 있을지가 최대 관심사다. 손버그인베스트먼트매니지먼트의 디 저우 포트폴리오 매니저는 “SK하이닉스의 ADR 상장은 투자자 기반을 넓히고 미국 경쟁사 마이크론과의 밸류에이션 격차를 줄이는 데 긍정적”이라고 평가했다. 페트라캐피털매니지먼트의 앨버트 용 공동대표도 “최근 시장 변동성이 매우 컸지만 SK하이닉스 주식에 대한 수요는 여전히 견조할 것으로 예상한다”고 말했다. 다만 ADR과 원주 간 가격 괴리가 존재하는 만큼 단기간에 국내 주가가 동일한 수준으로 재평가되기는 쉽지 않을 것이란 신중론도 제기됐다. 더불어 최근 메모리 반도체주는 AI 호황이 얼마나 지속될지를 놓고 투자자들의 우려가 다시 커지면서 변동성이 확대되고 있다.', 'crawl', '이투데이', '2026-07-07 14:18:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707140412_2356092_1200_875.jpg', '2026-07-07 06:04:51', '2026-07-07 18:54:04.437812', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4600, 'https://rss.etoday.co.kr/eto/politics_news.xml', 'https://www.etoday.co.kr/news/view/2601144', 'https://www.etoday.co.kr/news/view/2601144', '정치', '국조특위, 중앙선관위 현장조사…“느슨한 상황실 운영이 사태 키워”', '“투표지 부족 인지부터 지침 내리기까지 1시간반 이상” “송파선관위에 남은 4만장만 재분배해도 참정권 보장” 국회 6·3 지방...', '“투표지 부족 인지부터 지침 내리기까지 1시간반 이상” “송파선관위에 남은 4만장만 재분배해도 참정권 보장” ▲6·3 지방선거 투표용지 부족 사태 국정조사특위 윤상현 위원장을 비롯한 위원들이 7일 경기 과천 중앙선거관리위원회에서 열린 현장조사 및 전체회의에 참석하고 있다. 사진=연합뉴스 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 7일 중앙선거관리위원회 현장 조사에서 투표용지 부족 사태 인지와 보고, 조치 등에 걸친 선관위 대응 체계가 총체적으로 부실했다고 질타했다. 국조특위는 2일 서울 올림픽공원 개표소와 송파구 선관위에서 1자 현장 조사 벌인 데 이어 이날 오전 경기 과천 중앙선관위 청사에서 2차 현장 조사를 진행했다. 특위 위원들은 선관위가 ‘선거 관리 컨트롤타워’로서 제대로 역할을 하지 않아 선거 종합 상황실 등에 걸쳐 부실 대응이 벌어졌다고 비판했다. 이기헌 더불어민주당 의원은 선관위가 투표용지 부족 사태를 처음 인지한 시점에 대해 “16시 25분은 선거 상황실에 전달된 시간”이라며 “상황이 심각하다고 인지하는 데 걸린 시간은 그로부터 50분이 지난 17시 8분이다. 투표용지가 부족하다는 전화를 받고도 자체 확인하는 데에만 50분씩 소요되는 조직이 돼버렸다”고 지적했다. 이어 “(투표용지 부족 사태에 대한) 지침을 내리는 데 걸린 시간은 그로부터 55분이 걸린 18시 3분으로 (이 시점까지) 걸린 총시간이 1시간 반 이상”이라며 “선거를 총괄하는 선관위가 상황실을 느슨하게 운영했기 때문에 사안을 이렇게 키워온 것”이라고 강조했다. 주진우 국민의힘 의원도 “6월 3일 가장 기민하게 움직여야 하는, 대한민국에서 가장 정신 바짝 차려야 하는 데가 선관위 상황실이었는데 이미 투표가 끝난 상황에서 위철환 중앙선관위원장 직무대행에게 보고됐다”며 “말이 안 되고 국민들이 납득을 못할 것”이라고 질책했다. 또 선거 종료 후에도 송파구에 투표용지 4만2000여 장이 남았음에도 일부 투표소에서 용지가 바닥나 투표가 중단된 데 대해 “4만장이나 되는 투표용지가 송파구 선관위에 버젓이 남아 있었다. 합리적으로 재분배만 했어도 참정권이 보장되는 것”이라며 “국민들이 수사를 원하기 때문에 특검을 받아야 된다고 본다”고 했다. 정춘생 조국혁신당 의원은 “상황실에 전국에서 벌어지는 상황이 취합되고 이에 대한 보고가 이뤄지고 대응 방안에 대한 지시가 내려가는 것이 일반적 프로토콜 아니냐”며 “상황실에서 (투표용지 부족 관련) 민원 내용을 확인하기 위해 서울시선관위에 연락을 시도했으나 연결이 불가했다고 한다. 중요한 선거 국면에서 연결이 안 됐다는 게 도대체 이해가 안 된다”고 했다. 올림픽공원 핸드볼경기장에 보관된 투표용지를 이송하기 전 공개 검증하는 방안을 둔 질의도 나왔다. 이날 선관위는 핸드볼경기장 개표소에 보관 중인 투표지를 공개 검증 뒤 이송하자고 제안했다. 국조특위 위원장인 윤상현 국민의힘 의원은 247만장 투표용지 재검표에 대해 “핸드볼경기장 밖에 있는 ‘참정권 수호’를 외치는 시민들에 대한 최소한의 조치 측면에서 한다는 말이냐”라고 물었다. 강동완 선관위 사무총장 직무대리는 “그런 측면 더하기 해당 투표용지 자체가 선거 당일 개표한 투표지와 다르지 않다는 걸 확인하기 위한 차원”이라고 답했다. 이준석 개혁신당 의원은 “투표용지의 무결성은 봉인 상태 등을 보면 어느 정도 검증될 것 같다. 의혹을 해소하기 위해 하는 것이면 도대체 뭘 검증하려고 하는지를 파악해야 된다”며 “(재검표) 절차를 진행한다면 무엇을 검증할지, 공식적으로 접수하는 절차라든지 있어야할 것 같다”고 했다.', 'crawl', '이투데이', '2026-07-07 14:56:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707145054_2356139_1200_744.jpeg', '2026-07-07 06:04:51', '2026-07-07 18:54:10.054293', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4604, 'https://rss.etoday.co.kr/eto/politics_news.xml', 'https://www.etoday.co.kr/news/view/2601043', 'https://www.etoday.co.kr/news/view/2601043', '정치', '與 한병도 “올림픽공원 투표지 재검표·수개표 추진 적극 검토”', '“참정권 침해 진상 밝히고 책임자 처벌해야” “野, 투표지 특검 단독 추천 고집…정쟁 몰아가” “국힘 민생 보이콧…9일 본회의 ...', '“참정권 침해 진상 밝히고 책임자 처벌해야” “野, 투표지 특검 단독 추천 고집…정쟁 몰아가” “국힘 민생 보이콧…9일 본회의 국회의장에 요청” ▲더불어민주당 한병도 당 대표 직무대행 및 원내대표가 7일 국회에서 열린 원내대책회의에서 발언하고 있다. 사진=연합뉴스 한병도 더불어민주당 당대표 직무대행 겸 원내대표는 서울 송파구 올림픽공원 핸드볼경기장에 보관 중인 6·3 지방선거 투표용지 247만장과 관련해 “재검표와 수개표를 여야 협의로 국정조사 특별위원회에서 추진하는 방안을 적극 검토하겠다”고 7일 밝혔다. 한 원내대표는 이날 국회에서 열린 원내대책회의에서 “중요한 것은 국민참정권 침해의 진상을 밝히고 책임자 처벌을 통해 선거사무에 대한 국민 신뢰를 회복하는 일”이라며 이같이 말했다. 국민의힘 소속 윤상현 국조특위 위원장이 제시한 공개 재검표 방안에 화답한 것으로 풀이된다. 윤 위원장은 5일 기자회견에서 247만장 투표지에 대해 “공개적으로 재검증해 잘못된 투·개표가 없었는지 파악할 것”이라고 한 바 있다. 투표용지 부족 사태 특검과 관련해서는 국민의힘과 온도 차를 나타냈다. 한 원내대표는 “민주당은 이미 당론으로 특검법을 추진하기로 정했고 정치적 논란을 최소화할 수 있도록 제3자 추천 방식을 제안했다”며 “국민의힘은 정치적 유불리를 따지며 야당 단독 추천을 고집하고 있다”고 지적했다. 이어 “국민의힘도 국민참정권을 정쟁으로 몰아가려는 시도를 그만두고 실체적 진실을 밝혀내는 데 힘을 모으길 바란다”고 강조했다. 국민의힘의 상임위원회 보이콧에 대해서는 ‘민생 보이콧’이라고 규정하며 “국민의힘에 엄중히 경고한다. 일하라”고 요구했다. 그러면서 “상임위와 법사위를 통과했지만 국민의힘의 반대로 본회의 문턱에서 잠들어 있는 법안이 59건에 달한다”며 “국민의힘의 태업으로 국민 삶까지 멈춰 서서는 안 된다”고 압박했다. 한 원내대표는 9일 국회 본회의 개최를 조정식 국회의장에게 요청하겠다고 예고했다. 그는 “9일 민생법안 처리를 위한 본회의 개최가 필요하다”며 “조 의장을 찾아뵙고 본회의 개최를 요청드리겠다”고 했다.', 'crawl', '이투데이', '2026-07-07 10:59:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707105927_2355998_1200_814.jpeg', '2026-07-07 06:04:51', '2026-07-07 18:54:27.698235', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4606, 'https://rss.etoday.co.kr/eto/politics_news.xml', 'https://www.etoday.co.kr/news/view/2600920', 'https://www.etoday.co.kr/news/view/2600920', '정치', '이 대통령, 나토 정상회의 참석위해 출국…"K-방산 세일즈"', '이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석과 몽골 국빈 방문을 위해 3박 5일간의 순방길에 올랐다. 취...', '▲북대서양조약기구(NATO·나토) 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령이 7일 성남 서울공항에서 환송 나온 더불어민주당 한병도 대표 직무대행 겸 원내대표와 인사하고 있다. (연합뉴스) 이재명 대통령이 7일 북대서양조약기구(NATO·나토) 정상회의 참석과 몽골 국빈 방문을 위해 3박 5일간의 순방길에 올랐다. 취임 후 처음으로 나토 정상회의에 참석하는 이 대통령은 유럽 방산시장 공략과 공급망 협력 확대에 외교 역량을 집중할 예정이다. 이 대통령은 이날 오전 8시 35분 공군 1호기 편으로 경기 성남 서울공항을 출발해 튀르키예 앙카라로 향했다. 강훈식 대통령 비서실장과 홍익표 정무수석 등 청와대 참모, 한병도 더불어민주당 당대표 직무대행 겸 원내대표, 윤호중 행정안전부 장관 등이 서울공항에서 환송했다. 이 대통령의 나토 정상회의 참석은 취임 이후 처음이다. 이번 순방의 핵심 의제는 방산 협력이다. 세계 국방비의 절반 이상을 차지하는 나토 회원국들은 최근 안보 환경 변화에 대응해 국방비를 확대하고 있으며, 이번 정상회의에서도 신규 방산 협력과 계약이 주요 의제로 다뤄질 예정이다. 이 대통령은 정상회의를 계기로 유럽 정상과 방산업계 관계자들을 만나 K-방산 경쟁력을 알리고 수출 확대와 공급망 협력 기반 마련에 주력할 계획이다. 먼저 이날 오후에는 마르크 뤼터 나토 사무총장과 면담한 뒤 일본·호주·뉴질랜드 등 IP4 정상들과 소인수 회담을 갖는다. 이어 나토 방산포럼에 참석해 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언을 하고 패널 토론에도 참여해 한국 방위산업의 경쟁력과 협력 비전을 소개할 예정이다. 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 참석한다. 8일에는 방산 협력 수요가 있는 주요 국가들과 양자 회담을 이어갈 것으로 예상된다. 나토 일정을 마친 이 대통령은 9일부터 몽골을 국빈 방문한다. 대한민국 대통령의 몽골 국빈 방문은 2011년 이후 15년 만이다.', 'crawl', '이투데이', '2026-07-07 09:07:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707090646_2355850_657_447.jpg', '2026-07-07 06:04:51', '2026-07-07 18:54:31.519097', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4607, 'https://rss.etoday.co.kr/eto/society_news.xml', 'https://www.etoday.co.kr/news/view/2601129', 'https://www.etoday.co.kr/news/view/2601129', '사회', '광주일고, 배재고 선처 요청…''6개월 출전정지'' 징계 완화될까', '5·18 민주화운동 조롱 응원으로 6개월 출전정지 징계를 받은 배재고등학교 야구부에 대해 피해 당사자인 광주제일고등학교와 ...', '▲6일 오후 전남광주통합특별시 북구 국립 5·18 민주묘지에서 광주제일고등학교·배재고등학교 학생들이 참배하고 있다. (연합뉴스) 5·18 민주화운동 조롱 응원으로 6개월 출전정지 징계를 받은 배재고등학교 야구부에 대해 피해 당사자인 광주제일고등학교와 총동창회가 잇따라 선처를 요청하면서 징계 수위가 완화될지 관심이 쏠린다. 7일 교육계에 따르면 광주제일고와 광주서중·일고 총동창회는 이날 각각 입장문과 성명서를 내고 대한야구소프트볼협회 등 관계 기관에 배재고 야구부 학생들에 대한 선처를 요청했다. 광주서중·일고 총동창회는 이날 성명서를 통해 “가해 학생들을 향한 증오나 보복의 감정이 우리 마음속 깊은 어두운 구석에서도 자라나지 않기를 원한다”며 “교육의 참된 의미와 스포츠맨십의 본질을 되살려 이들을 넓은 관용으로 품어 안고자 한다”고 밝혔다. 이어 “광주서중·일고 동창회의 궁극적이고 타협할 수 없는 목표는 어린 학생들에 대한 단죄가 아니라 올바른 교육과 정의의 회복”이라며 “잘못을 깊이 뉘우치고 진심으로 용서를 구한 학생들의 가슴에 주홍글씨를 새기는 일은 우리가 바라는 길이 결코 아니다”라고 강조했다. 총동창회는 학생들의 잘못과 별개로 사회와 학교, 지도자 등 어른들의 책임도 강조했다. △학생들에게 무분별하게 노출된 사회적 혐오 문화 근절 △사태를 방조하고 관여한 지도자와 학교·교육청의 책임 △학생들의 책임 인식과 재발 방지 등을 요구했다. 광주제일고도 배재고 학생들이 야구장에서 다시 출발할 수 있도록 관계 기관이 지혜를 모아달라고 요청했다. 이규연 광주제일고 교장은 이날 입장문을 내고 “어제 광주제일고를 직접 찾아와 사과의 마음을 전달하고 앞으로 새로운 출발을 약속한 배재고 학생, 교직원, 학부모, 총동창회 분들께서는 이제 마음의 짐을 내려놓고 일상에 빠르게 복귀하시길 바란다”고 밝혔다. 이어 대한야구소프트볼협회와 야구 관계자들을 향해 “어제의 용서와 화해의 모습을 고려해 배재고 야구부 학생들이 경기장 내에서 새롭게 출발할 수 있도록 가능한 행정적 역량과 지혜를 모아달라”고 했다. 광주제일고와 총동창회가 잇따라 선처를 요청하면서 배재고가 재심 절차에 나설지도 주목된다. 배재고는 1일 대한야구소프트볼협회로부터 야구부 전체에 대해 6개월 출전정지 처분을 통보받았다. 재심 신청 기한은 8일까지다. 배재고는 현재 재심 신청 여부를 논의하고 있는 것으로 확인됐다. 재심을 신청할 경우 접수 이후 실제 재심의가 이뤄지기까지는 최소 2개월 이상 소요될 것으로 알려졌다. 앞서 이효준 배재고 교장을 비롯한 교직원과 야구부 학생, 지도자, 학부모 등 80여 명은 전날 광주제일고를 방문해 5·18 민주화운동 조롱 응원에 대해 사과했다. 이후 국립5·18민주묘지를 찾아 참배했다.', 'crawl', '이투데이', '2026-07-07 15:00:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707142456_2356110_1200_800.jpg', '2026-07-07 06:04:51', '2026-07-07 18:54:33.464389', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4610, 'https://rss.etoday.co.kr/eto/society_news.xml', 'https://www.etoday.co.kr/news/view/2601114', 'https://www.etoday.co.kr/news/view/2601114', '사회', '‘10조원대 전분당 가격 담합’ 첫 재판…대상 대표 혐의 부인', '국내 식료품 담합 사건 중 역대 최대 규모인 ‘10조원대 전분당 가격 담합’ 사건의 첫 재판에서 임모 대상 대표이사가 공소사...', '▲10조원대 전분 및 당류 가격 담합 협의로 재판에 넘겨진 대상그룹 임모 씨가 7일 서초구 중앙지법에서 열린 첫 공판에 출석하고 있다. 서울중앙지법은 7일 공정거래법 위반 혐의로 기소된 대상·사조CPK·CJ제일제당 법인과 임직원, 전분당협회장 등 총 24명의 첫 공판기일을 진행했다. (연합뉴스) 국내 식료품 담합 사건 중 역대 최대 규모인 ‘10조원대 전분당 가격 담합’ 사건의 첫 재판에서 임모 대상 대표이사가 공소사실을 전면 부인했다. 반면 사조CPK와 CJ제일제당 측은 혐의를 대체로 인정했다. 서울중앙지법 형사3단독 이호선 판사는 7일 독점규제 및 공정거래에 관한 법률 위반 혐의를 받는 대상·사조CPK·CJ제일제당 법인과 대표이사 등 임직원, 전분당협회장 등 총 24명의 첫 공판기일을 열었다. 이날 대상 임 대표 측은 공소사실을 전면 부인했다. 임 대표 변호인은 “사조CPK, CJ제일제당 대표자들과 가격 담합에 관해 협의한 사실이 없다”며 “소속 직원들로부터 담합을 통해 가격이 결정됐다는 사실을 보고받거나 승인한 사실도 없다”고 주장했다. 대상 소속 실무자 일부는 담합 가담 사실 자체는 인정하면서도 임 대표에게 직접 보고하거나 지시를 받은 사실은 없고, 직속 상급자에게만 보고했다며 임 대표와의 공모 관계는 성립하지 않는다고 주장했다. 사조CPK 측은 대부분의 공소사실을 인정하고 반성한다는 입장을 밝혔다. 사조CPK 이모 대표이사는 공소사실을 인정하면서도 2024년 2월 대표 취임 이전에는 관련 업무를 하지 않았고 수사에도 성실히 협조한 점을 양형에 고려해 달라고 요청했다. 일부 퇴직 임직원은 퇴사 이후 범행 부분만 부인했고, 사조CPK 법인도 퇴직 임직원의 퇴사 이후 행위까지 법인 책임으로 귀속되는 부분은 인정하지 않는다고 했다. CJ제일제당 측도 일부 임직원은 담합 가담 사실을 인정하며 반성한다고 밝혔고, 가담 정도가 경미한 점을 참작해 달라고 요청했다. 전분당협회장 A 씨는 대표자 모임을 주선한 사실은 인정하면서도 제품 가격 인상 논의나 공동 대응에 대한 공감대 형성은 없었고, 협회장에게 가격을 결정하거나 승인할 권한도 없다며 공소사실을 전면 부인했다. 앞서 검찰은 이들이 2017년 7월부터 지난해 10월까지 전분당과 그 부산물의 가격을 담합한 혐의로 기소했다. 검찰에 따르면 담합 규모는 약 10조 1520억원으로 국내 식료품 담합 사건 중 역대 최대다. 이 담합으로 전분 가격은 최고 73.4%, 당류 가격은 최고 63.8%까지 인상됐다. 재판부는 다음 공판준비기일을 내달 25일 오전 10시로 지정했다.', 'crawl', '이투데이', '2026-07-07 14:10:00', '중도', 'ready', 'https://img.etoday.co.kr/pto_db/2026/07/20260707134922_2356079_1199_819.jpg', '2026-07-07 06:04:51', '2026-07-07 18:54:38.920293', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4639, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204317', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204317', '정치', '올림픽공원 투표지 재검표하나?…민주 "247만장 수개표 추진 적극 검토"', '한병도 더불어민주당 대표 직무대행 겸 원내대표가 오늘(7일) "(서울 송파구) 올림픽공원 핸드볼 경기장 개표소에 남은 투표용지 247만 장에 대한 재검표와 수개표를 여야 협의를 통해 국조특위에서 추진하는 방안을 적극 검토하겠다"고 밝혔습니다.국회 6·3 지방선거 선관위 투표용지 부족 사태 국정조사특위를 이끄는 윤상현 위원장도 어제 서울 송파구 올림픽공원 핸드볼경기장 개표소 내 남아 있는 투표지 247만 장에 대한 공개 재검표를 여야 협의를 통해 추진하겠다고 밝힌 가운데, 더불어민주당도 찬성 의사를 밝히면서, 곧 재검표가 실시될 수 있을 것이란 전망도 나옵니다.한 원내대표는 오늘 국회에서 열린 원내대책회의에서 선관위 국조..', '↑ 한병도 더불어민주당 대표 직무대행 겸 원내대표 한병도 더불어민주당 대표 직무대행 겸 원내대표가 오늘(7일) "(서울 송파구) 올림픽공원 핸드볼 경기장 개표소에 남은 투표용지 247만 장에 대한 재검표와 수개표를 여야 협의를 통해 국조특위에서 추진하는 방안을 적극 검토하겠다"고 밝혔습니다. 국회 6·3 지방선거 선관위 투표용지 부족 사태 국정조사특위를 이끄는 윤상현 위원장도 어제 서울 송파구 올림픽공원 핸드볼경기장 개표소 내 남아 있는 투표지 247만 장에 대한 공개 재검표를 여야 협의를 통해 추진하겠다고 밝힌 가운데, 더불어민주당도 찬성 의사를 밝히면서, 곧 재검표가 실시될 수 있을 것이란 전망도 나옵니다. 한 원내대표는 오늘 국회에서 열린 원내대책회의에서 선관위 국조특위가 중앙선관위와 서울시 선관위를 찾아 현장 조사에 나설 계획이라고 전하며 "중요한 것은 국민참 정권 침해 진상을 밝히고, 책임자 처벌을 통해 선거사무에 대한 국민의 신뢰를 회복해야 한다"고 말했습니다. "선관위도 책임을 다해야 한다. 국민의힘도 국민참정권을 정쟁으로 몰아가려는 시도를 그만두고, 실체적 진실을 밝히는 데 힘을 모으길 바란다"고 촉구했습니다. [ 정태진 기자 jtj@mbn.co.kr ] (사진 = 연합뉴스)', 'crawl', 'MBN', '2026-07-07 10:48:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:52', '2026-07-07 18:55:42.992803', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4640, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204316', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204316', '정치', '민주 "장동혁, 선관위 특검 황당 궤변…국힘, 추진 의지 있냐"', '더불어민주당이 오늘(6일) 국민의힘을 향해 "선관위 특별검사 추천권을 둘러싼 소모적 공방을 중단하고, ''선관위 특검법'' 논의에 즉각 나서라"고 촉구했습니다.장윤미 민주당 대변인은 오늘 서면 브리핑을 통해 "국민의힘이 특검 추천권을 본인들만 행사해야 한다고 주장하면서 특검법 처리가 한 걸음도 나아가지 못하고 있다"며 이같이 밝혔습니다.장 대변인은 "국민의힘이 과연 선관위 특검법을 실질적으로 추진할 의지가 있는지 의문"이라며 "장동혁 대표는 ''이재명, 더불어민주당, 선관위가 한 배를 타고 있어 민주당이 특검 추천권을 포기 못한다''는 황당한 궤변까지 펼치고 있다"고 주장했습니다."선관위는 1963년 설립된 헌법상 독립기관으로..', '장윤미 민주당 대변인 "국힘, 공방 중단하고 선관위 특검 논의 즉각 나서라" ↑ 장윤미 더불어민주당 대변인 더불어민주당이 오늘(6일) 국민의힘을 향해 "선관위 특별검사 추천권을 둘러싼 소모적 공방을 중단하고, ''선관위 특검법'' 논의에 즉각 나서라"고 촉구했습니다. 장윤미 민주당 대변인은 오늘 서면 브리핑을 통해 "국민의힘이 특검 추천권을 본인들만 행사해야 한다고 주장하면서 특검법 처리가 한 걸음도 나아가지 못하고 있다"며 이같이 밝혔습니다. 장 대변인은 "국민의힘이 과연 선관위 특검법을 실질적으로 추진할 의지가 있는지 의문"이라며 "장동혁 대표는 ''이재명, 더불어민주당, 선관위가 한 배를 타고 있어 민주당이 특검 추천권을 포기 못한다''는 황당한 궤변까지 펼치고 있다"고 주장했습니다. "선관위는 1963년 설립된 헌법상 독립기관으로, 국회·정부·법원과 동등한 지위를 갖는데, 민주당 ''한 배'' 운운하는 건 삼권분립의 원칙을 의도적으로 훼손하는 반헌법적 주장"이란 설명입니다. 장 대변인은 "무엇보다 민주당은 특검 추천권을 직접 행사하겠다고 주장한 바 없다"며 "선관위는 행정부의 관리·감독 대상이 아닌 만큼, 특정 정당이 추천권을 독점하는 것은 어떠한 명분도 갖기 어렵다"고 말했습니다. "오히려 이해당사자인 정치권이 아닌, 객관성과 중립성을 담보할 수 있는 제3의 기관이 특검을 추천하는 것이 합리적"이라고 반 박에 나섰습니다. 장 대변인은 "이러한 취지를 왜곡하는 국민의힘의 태도는 특검을 실질적으로 추진하기보다 정치적 구호로 활용하려는 의도로 비칠 수밖에 없다"며 "국민의힘은 정쟁을 중단하고, 사태의 근본적 해결을 위해 책임 있는 자세로 논의에 임하기 바란다"고 덧붙였습니다. [ 정태진 기자 jtj@mbn.co.kr ] (사진 = MBN)', 'crawl', 'MBN', '2026-07-07 10:30:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:52', '2026-07-07 18:55:45.195962', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4642, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204301', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204301', '정치', '선관위 "잠실 개표소 검증에 9시간·5천만원 예상"', '중앙선거관리위원회는 오늘(7일) 송파구 잠실 올림픽공원 개표소에 보관 중인 6·3 지방선거 투표용지를 이송하기 전 검증하는 데 약 9시간이 소요되며, 비용은 5천만원가량 들 것으로 추산했습니다.중앙선관위는 이날 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위의 2차 현장조사에서 투표지 이송방안을 보고하며 이같이 밝혔습니다.중앙선관위는 먼저 "투표지 등을 임시공간에 장기간 보관함에 따른 국민적 불안감 및 의혹을 해소하고, 올림픽공원 핸드볼경기장 본연의 기능을 할 수 있도록 원상복구 할 필요성이 있다"고 밝혔습니다.현재 잠실 개표소에 보관된 투표지는 서울시장 선거 총 37매, 송파구의회의원 마선거구 총 25만매, 잠실..', '↑ 국회 ''제9회 전국동시지방선거 투표용지 부족 사태 등 국민 참정권 침해 진상규명 및 선거관리 개혁을 위한 국정조사 특별위원회'' 위원들이 2일 현장 조사를 위해 서울 송파구 올림픽공원 핸드볼경기장 개표소로 진입하고 있다. / 사진=연합뉴스 중앙선거관리위원회는 오늘(7일) 송파구 잠실 올림픽공원 개표소에 보관 중인 6·3 지방선거 투표용지를 이송하기 전 검증하는 데 약 9시간이 소요되며, 비용은 5천만원가량 들 것으로 추산했습니다. 중앙선관위는 이날 국회 6·3 지방선거 투표용지 부족 사태 국정조사특위의 2차 현장조사에서 투표지 이송방안을 보고하며 이같이 밝혔습니다. 중앙선관위는 먼저 "투표지 등을 임시공간에 장기간 보관함에 따른 국민적 불안감 및 의혹을 해소하고, 올림픽공원 핸드볼경기장 본연의 기능을 할 수 있도록 원상복구 할 필요성이 있다"고 밝혔습니다. 현재 잠실 개표소에 보관된 투표지는 서울시장 선거 총 37매, 송파구의회의원 마선거구 총 25만매, 잠실7동 총 4만매 등 총 247만매입니다. 앞서 국조특위가 지난 2일 올림픽공원을 찾아 현장을 확인한 바 있습니다. 중앙선관위는 이송 전 투표지 육안 재확인과 정당·후보자별 분류 및 확인 등 검증을 하려면 인력 440명, 예산 5천만원이 필요하고 총 9시간이 소요될 것으로 보고했습니다. 투표지 이송장소로는 중앙선관위 과천청사를 꼽으며 그 이유로 송파구선관위 청사는 동일 건물 내 유치원과 산후조리원이 입주해있고, 건물 앞 집회가 장기화하면 시민 불편이 극심해질 것을 꼽았습니다. 중앙선관위 과천청사는 출입 통제가 용이하고, 워낙 집회가 수시로 발생하는 장소라 경찰 협조로 경비도 가능해 추가 혼란을 최소화할 수 있다는 게 중앙선관위 판단입니다. 중앙선관위는 투표지 이송 방안에 대해선 국회 원내정당별 추천자 각 1명 참관하에, 차량에 적재 후 중앙선관위로 이송하겠다고 밝혔습니다. 차량 적재 및 이송과정을 촬영하고, 이송 차량에는 참관인과 경찰관이 동승해야 한다고도 덧붙였습니다. 이송 후에는 출입구에 이송 참관인이 서명한 특수봉인지를 부착하고 내부와 출입구에 CCTV를 설치해 상시 녹화하겠다는 계획도 밝혔습니다. 아울러 중앙선관위는 이송 전 별도의 검증 등 사전 조치가 필요하다고도 강조했습니다. 다만 현행 법규상 선관위 자체 직권 재검표는 법적 근거가 없어, 해당 투표지가 선거 당일 사용한 투표지라는 무결성을 입증하려면 국조특위 의결을 거쳐 투표지 검증을 해야 할 필요성이 있다고 설명했습니다. 국조특위는 이날 중앙선관위와 서울시선관위를 대상으로 2차 현장조사를 벌인 후 오는 14일과 22일 청문회를 거쳐 잠정적으로 결과보고서를 채택할 계획입니다. [정유진 디지털뉴스부 인턴기자 kittyjeongann@gmail.com]', 'crawl', 'MBN', '2026-07-07 10:14:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:52', '2026-07-07 18:55:48.906101', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4645, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204280', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204280', '정치', '''감기약 발언''에 김민석 "국힘서 얘기한 줄…대장동 보는 것 같다"', '더불어민주당 대표 선거 출마를 선언한 김민석 전 총리는 12·3 비상계엄 당시 자신이 국회의 계엄 해제 표결에 불참한 점을 두고 친청(친정청래)계가 공세를 펴는 데 대해 "무슨 꼭 대장동 때를 보는 것 같다"고 꼬집었습니다.김 전 총리는 오늘(7일) 오전 KBS1 라디오 ''전격시사''에서 해당 비판에 대해 "이성윤 최고위원이 말씀하셨던데 저는 ''국민의힘에서 누가 얘기를 하나''라고 생각했다"며 이같이 밝혔습니다. ''계엄 해제 표결 불참''에 대한 친청계의 공세를 과거 국민의힘 등이 대장동 사건으로 이재명 대통령을 비판하던 것에 빗댄 것으로 보입니다.앞서 김 전 총리는 2024년에 12·3 비상계엄 사태 이전부터 계엄 선포 가..', '↑ 김민석 전 총리 /사진=연합뉴스 더불어민주당 대표 선거 출마를 선언한 김민석 전 총리는 12·3 비상계엄 당시 자신이 국회의 계엄 해제 표결에 불참한 점을 두고 친청(친정청래)계가 공세를 펴는 데 대해 "무슨 꼭 대장동 때를 보는 것 같다"고 꼬집었습니다. 김 전 총리는 오늘(7일) 오전 KBS1 라디오 ''전격시사''에서 해당 비판에 대해 "이성윤 최고위원이 말씀하셨던데 저는 ''국민의힘에서 누가 얘기를 하나''라고 생각했다"며 이같이 밝혔습니다. ''계엄 해제 표결 불참''에 대한 친청계의 공세를 과거 국민의힘 등이 대장동 사건으로 이재명 대통령을 비판하던 것에 빗댄 것으로 보입니다. 앞서 김 전 총리는 2024년에 12·3 비상계엄 사태 이전부터 계엄 선포 가능성을 거론했으나 실제 계엄 사태가 발생했을 당시 국회의 계엄 해제 표결에는 불참했습니다. 그는 이후 당시 감기약을 먹고 잤다고 해명한 바 있습니다. 이를 두고 친청계 이성윤 의원은 어제(6일) "감기약을 드시고 주무셨다고 하는데 약 성분이 무엇인가. 자는 사람은 깨울 수 있어도 자는 척하는 사람은 깨울 수 없다고 하 던데 그런가"라고 주장했습니다. 이에 김 전 총리는 이날 "표결하는 시점에 국회 안에 있었고, 표결 직후에 본회의장에 착석했다"라고 말한 뒤 "이 의원이 말한 게 ''계엄과 관련한 전화를 받고 왜 거기(국회)에 오지 않았냐''(는 것)"이라며 "허위사실에 의한 명예훼손"이라고 했습니다. [김나연 디지털뉴스 기자 kim.nayeon@mbn.co.kr]', 'crawl', 'MBN', '2026-07-07 09:35:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:52', '2026-07-07 18:55:54.340024', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4646, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204278', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204278', '정치', '김민석, 친청계 ''감기약 발언''에 "대장동 때 보는 듯...그런 식으로 정치하면 어려워질 것"', '더불어민주당 당대표 선거에 출마한 김민석 전 국무총리가 오늘(7일) 친청계(친정청래)의 ''계엄 해제 표결 불참'' 의혹 제기와 관련해 "무슨 대장동 때를 보는 것 같다"고 날을 세웠습니다. 김 전 총리는 오늘 KBS 라디오 ''전격시사''에 출연해 "이성윤 최고위원이 말씀하셨던데, 저는 ''국민의힘에서 누가 얘기하나'' 생각했다"며 이같이 밝혔습니다. 이 의원은 김 전 총리의 출마 선언 직후인 어제 자신의 소셜미디어에 "계엄 해제 국회 표결에 왜 불참했나, 감기약 먹고 잤다는데 그 감기약 성분이 무엇인가, 민주당 의원과 계엄 선포 직전 통화 했다는데 그럼 즉시 국회로 달려와야 하지 않았느냐"라며 의혹을 제기한 바 있습니다.이에 ..', '↑ 김민석 전 국무총리 더불어민주당 당대표 선거에 출마한 김민석 전 국무총리가 오늘(7일) 친청계(친정청래)의 ''계엄 해제 표결 불참'' 의혹 제기와 관련해 "무슨 대장동 때를 보는 것 같다"고 날을 세웠습니다. 김 전 총리는 오늘 KBS 라디오 ''전격시사''에 출연해 "이성윤 최고위원이 말씀하셨던데, 저는 ''국민의힘에서 누가 얘기하나'' 생각했다"며 이같이 밝혔습니다. 이 의원은 김 전 총리의 출마 선언 직후인 어제 자신의 소셜미디어에 "계엄 해제 국회 표결에 왜 불참했나, 감기약 먹고 잤다는데 그 감기약 성분이 무엇인가, 민주당 의원과 계엄 선포 직전 통화 했다는데 그럼 즉시 국회로 달려와야 하지 않았느냐"라며 의혹을 제기한 바 있습니다. 이에 대해 김 전 총리는 "일단 이 의원이 말씀하신 게 허위사실"이라면서 "''계엄 관련 전화를 듣고 왜 거기 안 왔냐'' (이런 얘기는) 허위사실에 의한 명예훼손"이라고 주장했습니다. "이 시점에서 그렇 게 얘기하셔서 걱정하고 있다"며 "''저런 식으로 정치를 하면 좀 어려워질 텐데'' 이렇게 생각하고 있다"고 덧붙였습니다. 김 전 총리의 출마 선언 직후 친청계로 분류되는 이성윤·한민수·최민희 의원이 연달아 김 전 총리를 저격했고, 반면 친명계 강득구·이건태 의원 등은 김 전 총리 엄호에 나섰습니다. [ 정태진 기자 jtj@mbn.co.kr ]', 'crawl', 'MBN', '2026-07-07 09:48:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:52', '2026-07-07 18:55:58.390922', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4647, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204259', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204259', '정치', '이 대통령, 튀르키예 출국해 ''방산외교'' 시작…트럼프도 만날까', '이재명 대통령이 오늘(7일) 서울공항을 통해 북대서양조약기구(NATO·나토) 정상회의가 열리는 튀르키예 앙카라로 출국했습니다.정부에서는 윤호중 행정안전부 장관이, 더불어민주당에서는 한병도 대표 직무대행 겸 원내대표가, 청와대에서는 강훈식 대통령 비서실장과 홍익표 정무수석이 이 대통령의 출국길을 배웅했습니다.이 대통령은 출국에 앞서 엑스(X·옛 트위터)를 통해 "지난달 주요 7개국(G7) 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 넓혀 가려 한다"고 밝혔습니다.마르크 뤼터 나토 사무총장이 최근 한국의 방위산업 기반을 ''환상적''이라고 평가했다는 사실을 거론하면서 "전쟁의 폐허를 딛고 ..', '나토 정상회의 이어 몽골 순방 차 이날 출국 "국민께 자부심 안겨드리도록 이번 순방도 최선" ↑ 북대서양조약기구(NATO·나토) 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령이 오늘(7일) 성남 서울공항에서 환송 나온 살리 무랏 타메르 주한 튀르키예 대사와 인사하고 있다. / 사진=연합뉴스 이재명 대통령이 오늘(7일) 서울공항을 통해 북대서양조약기구(NATO·나토) 정상회의가 열리는 튀르키예 앙카라로 출국했습니다. 정부에서는 윤호중 행정안전부 장관이, 더불어민주당에서는 한병도 대표 직무대행 겸 원내대표가, 청와대에서는 강훈식 대통령 비서실장과 홍익표 정무수석이 이 대통령의 출국길을 배웅했습니다. 이 대통령은 출국에 앞서 엑스(X·옛 트위터)를 통해 "지난달 주요 7개국(G7) 정상회의에 이어 이번에는 나토 무대에서 세계 평화와 안보를 위한 대한민국의 역할을 넓혀 가려 한다"고 밝혔습니다. 마르크 뤼터 나토 사무총장이 최근 한국의 방위산업 기반을 ''환상적''이라고 평가했다는 사실을 거론하면서 "전쟁의 폐허를 딛고 나라를 지키기 위해 흘린 수많은 땀방울이 오늘날 세계가 인정하는 경쟁력이 됐다는 것이 참으로 자랑스럽다"고 언급하기도 했습니다. 그러면서 "오랜 시간 국제사회의 도움을 받던 대한민국은 이제 세계 평화와 안보에 책임 있게 기여하는 나라가 됐다"며 "국민 여러분께 더 큰 자부심을 안겨드릴 수 있도록 이번 순방 역시 최선을 다하겠다"고 다짐했습니다. 이번 일정은 뤼터 사무총장의 초청으로 성사된 것으로, 취임 후 첫 나토 정상회의 참석입니다. ↑ 북대서양조약기구(NATO·나토) 정상회의 참석과 몽골 국빈 방문을 위해 출국하는 이재명 대통령 부부가 오늘(7일) 성남 서울공항에서 환송객들을 향해 인사하고 있다. / 사진=연합뉴스 이 대통령은 이날 오후 앙카라에 도착, 뤼터 사무총장과 함께 일본, 호주, 뉴질랜드 등 인도·태평양 파트너국, 이른바 IP4 국가 대표들과의 소인수회담에 참석합니다. 이후 정상회의 공식 행사 중 하나인 나토 방위산업포럼에 참석, ''공동의 가치, 더욱 강한 산업기반''을 주제로 한 세션에서 기조발언을 합니다. 저녁에는 레제프 타이이프 에르도안 튀르키예 대통령 내외가 주최하는 공식 환영 만찬에 참석합니다. 이번 참석은 지난달 주요 7개국(G7) 정상회의에 이어 한국 외교의 지평을 더욱 넓히는 동시에, 특히 세계 국방비의 55%를 차지하는 최대 방산시장인 나토 동맹국들을 상대로 방산협력을 본격 추진한다는 의미가 있다고 청와대는 설명했습니다. 특히 도널드 트럼프 미국 대통령 역시 나토 정상회의 참석을 위해 튀르키예를 방문할 예정인 만큼, 이 대통령과 현지에서 대면할 것인지에도 관심이 쏠리고 있습니다. 이 대통령은 내일(8일)까지 튀르키예에 머무른 뒤 모레(9일)부터는 몽골에서 국빈방문 일정을 소화합니다. [정유진 디지털뉴스부 인턴기자 kittyjeongann@gmail.com]', 'crawl', 'MBN', '2026-07-07 08:58:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:52', '2026-07-07 18:56:00.069745', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4650, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204241', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204241', '정치', '"광주 군 공항 부지에 조성"…호남 반도체 클러스터에 "국운 걸린 경쟁"', '【 앵커멘트 】 청와대는 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했습니다. 이재명 대통령은 행정 절차를 최소화해 최대한 속도를 내라고 강조했습니다. 야당을 향해서도 협조는 못해도 방해는 하지 말라고 뼈있는 말을 남겼습니다. 선한빛 기자가 보도합니다. 【 기자 】 이재명 대통령이 속전속결로 호남권 반도체 클러스터 부지를 선정했습니다. ▶ 인터뷰 : 강훈식 / 대통령 비서실장- "광주 군 공항 지역은 약 250만 평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있습니다." 광주 도심과 KTX역이 인접해 인력 확보와..', '【 앵커멘트 】 청와대는 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했습니다. 이재명 대통령은 행정 절차를 최소화해 최대한 속도를 내라고 강조했습니다. 야당을 향해서도 협조는 못해도 방해는 하지 말라고 뼈있는 말을 남겼습니다. 선한빛 기자가 보도합니다. 【 기자 】 이재명 대통령이 속전속결로 호남권 반도체 클러스터 부지를 선정했습니다. ▶ 인터뷰 : 강훈식 / 대통령 비서실장 - "광주 군 공항 지역은 약 250만 평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있습니다." 광주 도심과 KTX역이 인접해 인력 확보와 정주 여건이 좋고, 물류 접근성이 우수한 점도 선정 이유였습니다. 이 대통령은 호남권 반도체 관련 민관합동 점검회의에서도 ''속도전''을 당부했습니다. ▶ 인터뷰 : 이재명 / 대통령 - "특히 행정 절차가 문제인데, 이 행정 절차 지연으로 투자 집행이 늦어지는 일이 절대로 있어서는 안 되겠습니다." 용인 산단의 경우 부지 확정부터 착공까지 6년이 걸렸다며, 더 빠른 진행이 가능하도록 필요한 행정절차는 병행 추진하라고 했습니다. 전력과 용수도 기다리지 말고 "선제적으로 확보"하라고 지시했습니다. ''호남 특혜''와 ''사업 불가능''을 주장하는 야권에도 작심 발언을 했습니다. ▶ 인터뷰 : 이재명 / 대통령 - "불가능하다는 전제로 비난하든지, 가능하다는 전제로 불균형을 지적하든지 둘 중에 하나만 하면 좋겠어요." ▶ 스탠딩 : 선한빛 / 기자 - "이 대통령은 매달 민관합동 점검회의를 통해 기업의 투자 계획이 실제 완공으로 이어질 수 있도록 직접 챙기겠다는 입장입니다.MBN 뉴스 선한빛입니다." 영상취재 : 이우진, 문진웅 기자 영상편집 : 김경준 그래픽 : 이은재', 'crawl', 'MBN', '2026-07-07 07:42:00', '보수', 'ready', 'https://www.mbn.co.kr/player/videojs/png/ic_caution.png', '2026-07-07 06:04:52', '2026-07-07 18:56:06.027487', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4655, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204218', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204218', '정치', '칼 빼든 감사원, 선관위 예산 들여다본다…국회도 오늘 현장조사', '【 앵커멘트 】 감사원과 국회가 동시에 선관위를 겨냥했습니다. 감사원은 중앙선관위 등을 대상으로 회계 검사에 착수했고, 국회 국정조사특위는 오늘(7일) 현장 조사에 나섭니다. 정태진 기자가 취재했습니다.【 기자 】 감사원이 선관위 회계를 들여다보기 시작했습니다. 감사 대상은 지방선거 투표용지 부족 사태와 관련된 예산과 집행 내역입니다. 헌법재판소 결정으로 직무 감찰이 막힌 감사원이 2022년 이후 4년 만에 회계 검사에 착수한 겁니다. 감사원은 통상보다 서너 배 많은 42명을 투입했습니다. 국회도 선관위 현장 조사에 나섭니다. 국조특위는 오늘 중앙선관위와 서울시 선관위를 찾습니다.▶ 윤상현 / 국회 투표..', '【 앵커멘트 】 감사원과 국회가 동시에 선관위를 겨냥했습니다. 감사원은 중앙선관위 등을 대상으로 회계 검사에 착수했고, 국회 국정조사특위는 오늘(7일) 현장 조사에 나섭니다. 정태진 기자가 취재했습니다. 【 기자 】 감사원이 선관위 회계를 들여다보기 시작했습니다. 감사 대상은 지방선거 투표용지 부족 사태와 관련된 예산과 집행 내역입니다. 헌법재판소 결정으로 직무 감찰이 막힌 감사원이 2022년 이후 4년 만에 회계 검사에 착수한 겁니다. 감사원은 통상보다 서너 배 많은 42명을 투입했습니다. 국회도 선관위 현장 조사에 나섭니다. 국조특위는 오늘 중앙선관위와 서울시 선관위를 찾습니다. ▶ 윤상현 / 국회 투표용지 부족사태 국정조사특별위원장 (MBN 통화) - "선거관리위원회는 한마디로 총체적인 무능과 총체적 불신의 결정판입니다. 제대로 된 감사가 없었기 때문입니다." 선관위 특검 추천 방식을 둘러싼 여야의 공방도 이어졌습니다. ▶ 한병도 / 더불어민주당 대표 직무대행 겸 원내대표 - "신속한 특검 도입에 있어 가장 큰 장애물은 바로 국민 참정권마저 정쟁의 도구로 삼으려는 국민의힘의 몽니입니다." ▶ 장동혁 / 국민의힘 대표 - "선관위를 이 지경으로 만든 것이 민주당입니다. 침대 특검으로 버틴다면 결국 정권 몰락의 속도만 높아질 것입니다." ▶ 스탠딩 : 정태진 / 기자 - "여야 모두 선관위 특검 도입에는 공감하고 있습니다. 다만 민주당은 ''제3자 추천''을, 국민의힘은 ''여당 추천 후보 배제''를 고수하고 있어 특검 출범까지 적잖은 진통이 예상됩니다." MBN뉴스 정태진입니다. [ 정태진 기자 jtj@mbn.co.kr ] 영상취재 : 김 원 기자 영상편집 : 이주호 그래픽 : 최지훈', 'crawl', 'MBN', '2026-07-07 07:00:00', '보수', 'ready', 'https://www.mbn.co.kr/player/videojs/png/ic_caution.png', '2026-07-07 06:04:52', '2026-07-07 18:56:15.466675', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4661, 'https://www.mbn.co.kr/rss/politics/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204187', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00006&news_seq_no=5204187', '정치', '"광주 군 공항 부지에 조성"…호남 반도체 클러스터에 "국운 걸린 경쟁"', '【 앵커멘트 】 청와대는 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했습니다. 이재명 대통령은 행정 절차를 최소화해 최대한 속도를 내라고 강조했습니다. 야당을 향해서도 협조는 못해도 방해는 하지 말라고 뼈있는 말을 남겼습니다. 선한빛 기자가 보도합니다. 【 기자 】 이재명 대통령이 속전속결로 호남권 반도체 클러스터 부지를 선정했습니다. ▶ 인터뷰 : 강훈식 / 대통령 비서실장- "광주 군 공항 지역은 약 250만 평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있습니다." 광주 도심과 KTX역이 인접해 인력 확보와..', '【 앵커멘트 】 청와대는 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했습니다. 이재명 대통령은 행정 절차를 최소화해 최대한 속도를 내라고 강조했습니다. 야당을 향해서도 협조는 못해도 방해는 하지 말라고 뼈있는 말을 남겼습니다. 선한빛 기자가 보도합니다. 【 기자 】 이재명 대통령이 속전속결로 호남권 반도체 클러스터 부지를 선정했습니다. ▶ 인터뷰 : 강훈식 / 대통령 비서실장 - "광주 군 공항 지역은 약 250만 평 규모의 부지 확보가 가능하고, 공항 특성상 이미 평탄화가 완료되어 있는 만큼 부지 공사 기간을 최소화할 수 있다는 장점이 있습니다." 광주 도심과 KTX역이 인접해 인력 확보와 정주 여건이 좋고, 물류 접근성이 우수한 점도 선정 이유였습니다. 이 대통령은 호남권 반도체 관련 민관합동 점검회의에서도 ''속도전''을 당부했습니다. ▶ 인터뷰 : 이재명 / 대통령 - "특히 행정 절차가 문제인데, 이 행정 절차 지연으로 투자 집행이 늦어지는 일이 절대로 있어서는 안 되겠습니다." 용인 산단의 경우 부지 확정부터 착공까지 6년이 걸렸다며, 더 빠른 진행이 가능하도록 필요한 행정절차는 병행 추진하라고 했습니다. 전력과 용수도 기다리지 말고 "선제적으로 확보"하라고 지시했습니다. ''호남 특혜''와 ''사업 불가능''을 주장하는 야권에도 작심 발언을 했습니다. ▶ 인터뷰 : 이재명 / 대통령 - "불가능하다는 전제로 비난하든지, 가능하다는 전제로 불균형을 지적하든지 둘 중에 하나만 하면 좋겠어요." ▶ 스탠딩 : 선한빛 / 기자 - "이 대통령은 매달 민관합동 점검회의를 통해 기업의 투자 계획이 실제 완공으로 이어질 수 있도록 직접 챙기겠다는 입장입니다.MBN 뉴스 선한빛입니다." 영상취재 : 이우진, 문진웅 기자 영상편집 : 김경준 그래픽 : 이은재', 'crawl', 'MBN', '2026-07-06 19:00:00', '보수', 'ready', 'https://www.mbn.co.kr/player/videojs/png/ic_caution.png', '2026-07-07 06:04:52', '2026-07-07 18:56:26.465226', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4693, 'https://www.mbn.co.kr/rss/economy/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00003&news_seq_no=5203940', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00003&news_seq_no=5203940', '경제', '홈플러스, 결국 파산하나…2주 안에 자금 확보 못 하면 ''공중분해''', '법원의 회생절차 폐지 결정으로 인해, 홈플러스가 파산 절차에 들어갈 가능성이 커졌습니다. 홈플러스가 14일 안에 2천억 원 규모의 자금 조달 방안을 마련해 즉시항고를 제기하지 못할 경우, 법원의 결정은 확정돼 홈플러스는 법정관리 대신 공중분해 후 매각이라는 시나리오를 밟게 됩니다.오늘(5일) 유통업계에 따르면, 홈플러스가 대주주인 MBK파트너스와 최대 채권자인 메리츠금융그룹으로부터 자금 조달에 실패하면 법원에 파산을 신청할 전망입니다.이후 법원이 홈플러스에 파산을 선고하고, 자산을 채권자들에 배당하는 청산 절차가 진행됩니다.법원이 파산 관재인을 선임하면 관재인이 회사 재산을 채권자들에게 배당하는 방식입니다.홈플러스 자가..', '메리츠, 점포 62개 독자 처분해 원리금 1조 3천억 회수 전망 점포 부지의 용도를 변경해 매각하는 방안 유력…동대문점이 선례 ↑ 인수자 못 찾아 파산 수순 밟는 홈플러스 / 사진=연합뉴스 법원의 회생절차 폐지 결정으로 인해, 홈플러스가 파산 절차에 들어갈 가능성이 커졌습니다. 홈플러스가 14일 안에 2천억 원 규모의 자금 조달 방안을 마련해 즉시항고를 제기하지 못할 경우, 법원의 결정은 확정돼 홈플러스는 법정관리 대신 공중분해 후 매각이라는 시나리오를 밟게 됩니다. 오늘(5일) 유통업계에 따르면, 홈플러스가 대주주인 MBK파트너스와 최대 채권자인 메리츠금융그룹으로부터 자금 조달에 실패하면 법원에 파산을 신청할 전망입니다. 이후 법원이 홈플러스에 파산을 선고하고, 자산을 채권자들에 배당하는 청산 절차가 진행됩니다. 법원이 파산 관재인을 선임하면 관재인이 회사 재산을 채권자들에게 배당하는 방식입니다. 홈플러스 자가 점포 62개는 메리츠에 신탁 담보로 잡혀 있습니다. 신탁 담보는 파산재단의 일반적인 경매 절차에 포함되지 않고 담보권을 가진 채권자가 독자적으로 처분할 수 있습니다. 메리츠는 지난 2024년 홈플러스의 부동산과 유형자산을 신탁자산으로 받고 홈플러스에 선순위 대출 1조 3천억 원을 내어 줬습니다. 현 상황에 메리츠는 담보로 잡은 점포들을 처분하며 대출 원리금을 회수할 것으로 보입니다. 대형마트가 폐점하면 경쟁사가 해당 점포를 인수할 수도 있지만, 오프라인 대형마트 업계의 침체로 이마트와 롯데마트와 같은 대형 업체들이 인수전에 뛰어들 가능성은 작습니다. 한 대형마트 관계자는 "인수할 만큼 매력적인 점포는 이미 모두 팔려 남아있지 않다"며 "남은 홈플러스 매장은 현재의 업황을 고려할 때 매수하기 위해 적극적으로 나설 정도는 아니다"라고 짚었습니다. 결국 점포 부지를 주상복합·물류센터·오피스 등으로 용도 변경해 매각하는 방안이 가장 유력하다는 게 시장의 평가입니다. MBK는 회생절차 개시 전 ''알짜'' 점포 중 하나인 동대문점을 매각했는데, 현재 이 자리에는 지상 49층 규모의 공동 주택과 복합 시설을 짓는 사업이 진행 중입니다. 부동산 업황 역시 좋지 못하다는 점을 고려할 때 이 같은 청산 과정에도 시간이 걸릴 전망입니다. 다만, 홈플러스가 14일 안에 자금을 확보해 즉시항고하는 길은 여전히 남아 있습니다. MBK와 메리츠는 추가 지원금 2천억 원을 두고 입장차를 전혀 좁히지 못하고 있는 상황입니다. 당장 일자리를 잃게 된 노조는 정부 차원의 적극적인 개입을 촉구하고 있습니다. 마트노조는 "정부는 모든 긴급 조치를 통해 홈플러스 회생 방안을 마련해 달라"며 "홈플러스가 청산 절차로 향하게 되면 수십만의 일자리와 지역경제가 무너질 것"이라고 주장했습니다. [현서경 디지털뉴스부 인턴기자 seokyung0322@gmail.com]', 'crawl', 'MBN', '2026-07-05 16:22:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:53', '2026-07-07 18:57:31.062885', NULL);
