INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4710, 'https://www.mbn.co.kr/rss/society/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00009&news_seq_no=5204309', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00009&news_seq_no=5204309', '사회', '검찰, ''장윤기 부친과 유착 의혹'' 광주 광산경찰서 압수수색', '경찰관 비위 사건의 직접 수사권을 가진 검찰이 ''여고생 살해범'' 장윤기(23) 아버지와 수사팀 간 유착 의혹 등을 들여다보는 직접 수사에 착수했습니다.오늘(7일) 광주지검은 장윤기 사건을 담당했던 광주 광산경찰서에 수사관을 보내 압수수색 영장을 집행하고 있습니다.검찰은 형사과 담당팀 관계자 등 다수 경찰관을 공무상비밀누설, 증거인멸 등 혐의로 입건했습니다.입건된 경찰관들은 지난 5월 5일 장윤기를 긴급체포한 뒤 검찰 송치까지 수사 과정에서 케이블타이·리얼돌·차량(SUV) 등 주요 증거물을 확보하지 않고, 현직 경찰인 장윤기 아버지에게 압수수색·구속영장 내용 등 수사 상황을 누설한 혐의를 받습니다.검찰은 해당 경찰관들의 ..', '직접 수사 착수…경찰 자체 수사와 별도로 진행 ↑ ''여고생 살해범'' 장윤기 / 사진=연합뉴스 경찰관 비위 사건의 직접 수사권을 가진 검찰이 ''여고생 살해범'' 장윤기(23) 아버지와 수사팀 간 유착 의혹 등을 들여다보는 직접 수사에 착수했습니다. 오늘(7일) 광주지검은 장윤기 사건을 담당했던 광주 광산경찰서에 수사관을 보내 압수수색 영장을 집행하고 있습니다. 검찰은 형사과 담당팀 관계자 등 다수 경찰관을 공무상비밀누설, 증거인멸 등 혐의로 입건했습니다. 입건된 경찰관들은 지난 5월 5일 장윤기를 긴급체포한 뒤 검찰 송치까지 수사 과정에서 케이블타이·리얼돌·차량(SUV) 등 주요 증거물을 확보하지 않고, 현직 경찰인 장윤기 아버지에게 압수수색·구속영장 내용 등 수사 상황을 누설한 혐의를 받습니다. 검찰은 해당 경찰관들의 주거지도 압수수색하고 있습니다. ↑ 오늘(7일) 전남광주통합특별시 광산구 광산경찰서에서 광주지검 수사관들이 압수수색을 하고 있다. 검찰은 중대성 등을 고려해 경찰의 자체 비위 수사와 별도로 이번 사안을 직접 수사하기로 했습니다. 장윤기 사건 담당 팀장을 전날 증거인멸 혐의로 긴급체포한 경찰은 수사 주체를 광주경찰청 전담팀에서 국가수사본부로 격상해 이날 인력을 광주로 파견하기로 했습니다. 경찰관이 저지른 범죄 행위는 검찰, 경찰이 각각 별도로 착수할 수 있습니다. [민현지 디지털뉴스부 인턴기자 localminn@gmail.com]', 'crawl', 'MBN', '2026-07-07 10:34:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:53', '2026-07-07 18:58:17.371608', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4725, 'https://www.mbn.co.kr/rss/international/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5204323', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5204323', '국제', '베네수엘라 지진 참사, ''11일 만에 구조된 어린이'' 보도는 오보', '베네수엘라 연쇄 강진으로 인한 사망자가 3천535명으로 늘어난 가운데, 구조에 대한 기대가 맞물린 오보가 이어지고 있습니다.특히 현지 유력 일간 엘나시오날은 전날 밤 9시경 라과이라주 카라바예다에서 구조대가 어린이 등 4명을 구조했다고 보도했으나, 이는 사실이 아닌 것으로 확인됐습니다.해당 내용은 소셜미디어를 통해 ''지진 11일 만에 구조된 어린이''라는 설명과 함께 빠르게 퍼졌지만, 엘나시오날은 구조 영상이 최근 발견된 게 아닌 이전 구조 장면이었다고 정정했습니다.베네수엘라 당국도 구조 대원들이 현재까지 6천462명을 구조했으며, 이 수치는 지난 2일 이후 변동이 없다고 설명했습니다.정부는 육군과 보안군 2만 9천567..', '↑ 베네수엘라 지진 피해 구조 현장 (사진=연합뉴스) 베네수엘라 연쇄 강진으로 인한 사망자가 3천535명으로 늘어난 가운데, 구조에 대한 기대가 맞물린 오보가 이어지고 있습니다. 특히 현지 유력 일간 엘나시오날은 전날 밤 9시경 라과이라주 카라바예다에서 구조대가 어린이 등 4명을 구조했다고 보도했으나, 이는 사실이 아닌 것으로 확인됐습니다. 해당 내용은 소셜미디어를 통해 ''지진 11일 만에 구조된 어린이''라는 설명과 함께 빠르게 퍼졌지만, 엘나시오날은 구조 영상이 최근 발견된 게 아닌 이전 구조 장면이었다고 정정했습니다. 베네수엘라 당국도 구조 대원들이 현재까지 6천462명을 구조했으며, 이 수치는 지난 2일 이후 변동이 없다고 설명했습니다. 정부는 육군과 보안군 2만 9천567명을 투입했으며, 이들은 현재 자원봉사자 2만 7천930명과 함께 구조·복구 작업을 진행하고 있습니다. 수만 명이 구조 작업을 벌이고 있지만 지진이 발생한 지 열흘이 넘게 지난만큼 매몰자들의 생환 가능성은 크게 줄어든 상태입니다. 호르헤 로드리게스 베네수엘라 국회의장은 현지 시각 6일 부상자는 6천740명, 이재민은 1만 7천854명이 집계됐다고 밝혔습니다. [ 강재묵 기자 mook@mk.co.kr ]', 'crawl', 'MBN', '2026-07-07 09:51:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:53', '2026-07-07 18:58:47.735102', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4729, 'https://www.mbn.co.kr/rss/international/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5204267', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5204267', '국제', '베네수 지진 사상자 2만명 육박…매몰자 생환 가능성 희박', '베네수엘라 연쇄 강진이 발생한 지 12일이 지난 가운데 사망자 수가 3,500명을 넘어선 것으로 집계됐습니다.현지 시간 지난달 24일 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3,535명으로 늘었다고 호르헤 로드리게스 국회의장이 6일 밝혔습니다.이는 전날보다 193명 늘어난 수치입니다.부상자 수치는 전날과 변동 없는 1만 6,740명이며, 이재민은 1만 7,854명으로 집계됐습니다.로드리게스 의장은 피해를 본 건물은 856채이며, 붕괴한 건물은 총 190채라고 설명했습니다.정부가 투입한 육군 및 보안군 2만 9,567명은 자원봉사자 2만 7,930명과 함께 구조·복구 작업을 진행 중입니다.그러나 지진이 발생한 지 ..', '사망 3천500명, 부상 1만 6천여명…이재민 1만8천여명 ↑ 베네수엘라 구조 현장 / 사진=AP=연합뉴스 베네수엘라 연쇄 강진이 발생한 지 12일이 지난 가운데 사망자 수가 3,500명을 넘어선 것으로 집계됐습니다. 현지 시간 지난달 24일 발생한 베네수엘라 연쇄 지진으로 인한 사망자가 3,535명으로 늘었다고 호르헤 로드리게스 국회의장이 6일 밝혔습니다. 이는 전날보다 193명 늘어난 수치입니다. 부상자 수치는 전날과 변동 없는 1만 6,740명이며, 이재민은 1만 7,854명으로 집계됐습니다. 로드리게스 의장은 피해를 본 건물은 856채이며, 붕괴한 건물은 총 190채라고 설명했습니다. 정부가 투입한 육군 및 보안군 2만 9,567명은 자원봉사자 2만 7,930명과 함께 구조·복구 작업을 진행 중입니다. 그러나 지진이 발생한 지 열흘이 넘으면서 매몰자들의 생환 가능성은 크게 줄어든 상태입니다. 구조에 대한 기대가 큰 탓에 오보도 나왔습니다. 소셜미디어(SNS) 등을 통해 알려졌던 지진 11일 만에 어린이 등 4명 구조 소식은 현지 언론 의 오보인 것으로 확인됐습니다. 이날 현지 유력 일간 엘나시오날은 전날 밤 9시쯤 라과이라주 카라바예다에서 구조대가 어린이 등 4명을 구조했다고 보도했으나, 이는 사실이 아니라고 바로잡았습니다. 엘나시오날은 해당 영상이 최근 발견된 게 아닌 이전에 있었던 구조 장면이라고 설명했습니다. [김나연 디지털뉴스 기자 kim.nayeon@mbn.co.kr]', 'crawl', 'MBN', '2026-07-07 09:00:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:53', '2026-07-07 18:58:55.25072', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4742, 'https://www.mbn.co.kr/rss/international/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5204033', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5204033', '국제', '부친 하메네이 장례식도 불참…이란 후계자, 건강이상설 증폭', '이란 최고지도자 자리를 승계한 아야톨라 세예드 모즈타바 하메네이가 부친의 장례식에 모습을 드러내지 않자, 그의 건강 상태와 권력 장악력을 둘러싼 의문이 커지고 있다고 로이터 통신 등 외신들이 현지 시간 5일 보도했습니다.외신에 따르면 이날 테헤란에서 열린 아야톨라 세예드 알리 하메네이 전 최고지도자의 장례 기도에서는 모스타파, 마수드, 메이삼 등 하메네이의 다른 세 아들이 관 옆에 서서 기도를 올렸지만, 최고지도자를 승계한 차남 모즈타바는 끝내 나타나지 않았습니다.이란 국영TV는 세 형제가 모즈타바 없이 부친과 다른 가족 4명의 관 곁에서 기도하는 모습을 중계했습니다.하메네이와 그의 일부 가족은 지난 2월 28일 미국과..', '다른 세 아들은 관 앞에서 추모 기도 미·이스라엘 암살 우려로 불참했단 관측도 ↑ 하메네이의 막내아들 메이삼(왼쪽에서 세 번째), 셋째아들 마수드(가운데), 장남 모스타파(오른쪽에서 두 번째) / 사진=AFP, 연합뉴스 이란 최고지도자 자리를 승계한 아야톨라 세예드 모즈타바 하메네이가 부친의 장례식에 모습을 드러내지 않자, 그의 건강 상태와 권력 장악력을 둘러싼 의문이 커지고 있다고 로이터 통신 등 외신들이 현지 시간 5일 보도했습니다. 외신에 따르면 이날 테헤란에서 열린 아야톨라 세예드 알리 하메네이 전 최고지도자의 장례 기도에서는 모스타파, 마수드, 메이삼 등 하메네이의 다른 세 아들이 관 옆에 서서 기도를 올렸지만, 최고지도자를 승계한 차남 모즈타바는 끝내 나타나지 않았습니다. 이란 국영TV는 세 형제가 모즈타바 없이 부친과 다른 가족 4명의 관 곁에서 기도하는 모습을 중계했습니다. 하메네이와 그의 일부 가족은 지난 2월 28일 미국과 이스라엘이 이란을 공격하며 시작된 전쟁 첫날 공습으로 숨졌습니다. 모즈타바는 당시 공격으로 얼굴을 다치고 다리에 중상을 입은 것으로 알려졌습니다. 모즈타바는 이후 지금까지 공식 석상에 모습을 드러내지 않고 있습니다. ↑ 하메네이 장례식에서 눈물을 흘리고 있는 여성 / 사진=AP, 연합뉴스 장례식에 참석한 일부 추모객은 새 최고지도자가 장례식에도 등장하지 않자 실망감을 감추지 못했습니다. 이란 타스님 통신은 한 젊은 여성이 "기도가 시작되기 직전까지도 모즈타바가 직접 나오기를 바랐다. 그것이 우리의 유일한 소원이었다"고 말했다고 전했습니다. 전문가들 사이에서는 모즈타바가 미국이나 이스라엘의 암살 시도를 우려해 공개 석상에 모습을 드러내지 않고 있다는 관측도 나옵니다. 이란 당국은 국민 결속을 과시하기 위해 미국의 건국 250주년 기념일이기도 한 4일부터 대규모 국가장 형식의 장례 일정을 진행하고 있습니다. 현지 시각 5일에는 군인과 신학생, 일반 시민 등 수만 명이 테헤란 내 대형 예배 장소인 이맘호메이니 대(大) 모살라를 찾아 조문했습니다. ↑ 트럼프에 대한 복수를 촉구하는 팻말을 든 이란 시민 / 사진=AP, 연합뉴스 이들은 미국과 이스라엘에 대한 복수를 촉구하는 구호를 외치고 국기를 흔들었습니다. 영국 일간 가디언은 ''도널드 트럼프를 죽이라''는 구호도 잇따랐다고 보도했습니다. 시인 모하마드 라술리는 송별식 기도 직전 열린 시 낭송에서 "이제 세상은 트럼프에게 더 이상 좋은 곳이 아니다"며 "우리 이맘(최고지도자)을 죽인 사람을 왜 우리가 죽이지 말아야 하는가. 그렇게 하지 않는다면 그것이야말로 수치일 것"이라고 말했습니다. 국영 언론은 당초 오후 9시까지 예정됐던 장례 행사가 참석자가 몰리면서 오후 10시까지 연장됐다고 전했습니다. 이란 지하철 당국은 4일 밤부터 5일 아침까지 약 700만 건의 승차가 이뤄졌다고 밝혔습니다. 이번 장례 일정은 9일까지 이어지며, 아야톨라 하메네이의 고향이자 시아파 성지인 이란 북동부 마슈하드에 시신이 안장될 예정입니다. ↑ 하메네이를 추모하고 있는 이란 시민들 / 사진=AP, 연합뉴스 [민현지 디지털뉴스부 인턴기자 localminn@gmail.com]', 'crawl', 'MBN', '2026-07-06 09:34:00', '보수', 'ready', 'https://img.mbn.co.kr/newmbn/white.PNG', '2026-07-07 06:04:53', '2026-07-07 18:59:22.069919', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4745, 'https://www.mbn.co.kr/rss/international/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5203992', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5203992', '국제', '하메네이 장례식 ''반미 집회'' 방불…한국 불참 이유는?', '【 앵커멘트 】 지난 주말 시작된 하메네이 전 이란 최고지도자의 장례식은 거대한 반미 집회를 연상케 했습니다. 우리나라도 현지 공관을 통해 조문할 예정이었지만, 이란 측이 돌연 참석 거부를 통보한 것으로 파악됐습니다. 이동연 기자가 보도합니다.【 기자 】 검은 옷을 입은 추모 인파가 이란 수도 테헤란 광장을 가득 메웠습니다. ''트럼프를 죽여라''라고 적힌 팻말이 곳곳에서 눈에 띕니다. 지난 2월 28일 미국과 이스라엘의 공습으로 숨진 알리 하메네이 전 이란 최고지도자의 장례식은 거대한 반미 집회를 방불케 했습니다.▶ 인터뷰 : 모하마드 라술리 / 종교 시인- "당신들의 피에 맹세컨대, 트럼프를 죽이는 것은 우리..', '【 앵커멘트 】 지난 주말 시작된 하메네이 전 이란 최고지도자의 장례식은 거대한 반미 집회를 연상케 했습니다. 우리나라도 현지 공관을 통해 조문할 예정이었지만, 이란 측이 돌연 참석 거부를 통보한 것으로 파악됐습니다. 이동연 기자가 보도합니다. 【 기자 】 검은 옷을 입은 추모 인파가 이란 수도 테헤란 광장을 가득 메웠습니다. ''트럼프를 죽여라''라고 적힌 팻말이 곳곳에서 눈에 띕니다. 지난 2월 28일 미국과 이스라엘의 공습으로 숨진 알리 하메네이 전 이란 최고지도자의 장례식은 거대한 반미 집회를 방불케 했습니다. ▶ 인터뷰 : 모하마드 라술리 / 종교 시인 - "당신들의 피에 맹세컨대, 트럼프를 죽이는 것은 우리의 의무다." 하메네이 후계자인 아들 모즈타바가 여전히 모습을 드러내지 않는 가운데, 나머지 아들 3명은 공개적으로 애도를 표했습니다. 트럼프 미국 대통령은 추모 행렬을 두고 "우는 사람들을 보고 놀랐다"며 "가짜 눈물일 수 있다"고 말했습니다. ▶ 인터뷰 : 도널드 트럼프 / 미국 대통령 (현지 시각 3일) - "이란은 화해하고 싶어 안달이 났어요. (하메네이 전 최고지도자) 장례식 때문에 일주일 휴가를 준 것은 우리가 친절해서 그런 것입니다." 이번 하메네이 장례식에는 중국과 러시아 등 30여 개국 고위 인사가 대거 참석했습니다. 우리나라도 애초 조문단을 보낼 예정이었지만, 이란 측이 장소 사정 등을 이유로 돌연 초청을 취소한 것으로 알려졌습니다. 고위 인사가 아닌 대사급 조문은 받지 않겠다는 취지로 풀이됩니다. 엿새간 이어지는 장례 일정에 따라 하메네이의 시신은 오늘(6일) 테헤란을 떠난 뒤 오는 9일 고향 마슈하드에 안장될 예정입니다. 미국과 이란은 장례 일정이 모두 끝난 뒤인 오는 11일 파키스탄에서 후속 협상에 나설 것이란 전망이 나옵니다. MBN뉴스 이동연입니다. [lee.dongyeon@mbn.co.kr] 영상편집 : 최형찬 그 래 픽 : 박경희', 'crawl', 'MBN', '2026-07-06 07:00:00', '보수', 'ready', 'https://www.mbn.co.kr/player/videojs/png/ic_caution.png', '2026-07-07 06:04:53', '2026-07-07 18:59:27.542324', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4747, 'https://www.mbn.co.kr/rss/international/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5203984', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5203984', '국제', '[굿모닝월드] 불꽃놀이만 볼 줄 알았는데', '지난 주말, 미국 전역이 독립기념일 250주년을 맞아 성대한 축제로 들썩였습니다. 무려 85만 발의 폭죽이 밤하늘을 수놓으며 화려한 볼거리를 선사했는데요. 하지만, 관람객들의 시선을 사로잡은 건 화려한 불꽃놀이뿐만이 아니었습니다. 수도 워싱턴 DC에서는 기념탑 너머로 불꽃과 함께 거대한 번개가 동시에 번쩍였고, 뉴욕에서는 불꽃이 튀면서 브루클린 다리에 불이 붙는 일촉즉발의 상황이 벌어지기도 했는데요. 다행히 다친 사람은 없었지만, 축제 현장이 자칫 대형 화재로 이어질 뻔한 아찔한 순간이었습니다. 지금까지 굿모닝월드였습니다. 영상편집 : 한남선 화면출처 : 인스타그램 @yuphoric_, @meru_..', '<불꽃놀이만 볼 줄 알았는데> 지난 주말, 미국 전역이 독립기념일 250주년을 맞아 성대한 축제로 들썩였습니다. 무려 85만 발의 폭죽이 밤하늘을 수놓으며 화려한 볼거리를 선사했는데요. 하지만, 관람객들의 시선을 사로잡은 건 화려한 불꽃놀이뿐만이 아니었습니다. 수도 워싱턴 DC에서는 기념탑 너머로 불꽃과 함께 거대한 번개가 동시에 번쩍였고, 뉴욕에서는 불꽃이 튀면서 브루클린 다리에 불이 붙는 일촉즉발의 상황이 벌어지기도 했는데요. 다행히 다친 사람은 없었지만, 축제 현장이 자칫 대형 화재로 이어질 뻔한 아찔한 순간이었습니다. 지금까지 굿모닝월드였습니다. 영상편집 : 한남선 화면출처 : 인스타그램 @yuphoric_, @meru_nyc #굿모닝월드 #한혜원아나운서 #이동연기자 #미국 #독립기념일 #250주년 #불꽃놀이 #폭죽 #번개 #화재', 'crawl', 'MBN', '2026-07-06 07:00:00', '보수', 'ready', 'https://www.mbn.co.kr/player/videojs/png/ic_caution.png', '2026-07-07 06:04:53', '2026-07-07 18:59:31.277583', NULL);
INSERT INTO public.articles (id, feed_url, guid, link, category, title, summary, content, content_source, publisher, published_at, bias_type, status, article_image_url, created_at, updated_at, core_content) OVERRIDING SYSTEM VALUE VALUES (4749, 'https://www.mbn.co.kr/rss/international/', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5203963', 'https://www.mbn.co.kr/pages/news/newsView.php?category=mbn00008&news_seq_no=5203963', '국제', '트럼프 "공산주의 위협 암처럼 즉시 제거해야"…250주년 기념 연설에서 또 강조', '【 앵커멘트 】 이런 가운데 트럼프 대통령이 미국 독립 기념 250주년 연설에서 공산주의자가 암과 같다며 번지기 전에 즉시 제거해야 한다고 주장했습니다. 어제(4일)에 이어 이틀째 공산주의를 언급한 건데, 지지층 결집을 노린 걸로 풀이됩니다. 이상협 기자가 보도합니다.【 기자 】 연단에 오른 트럼프 미국 대통령이 공산주의의 위험을 경고합니다.▶ 인터뷰 : 도널드 트럼프 / 미국 대통령- "우리는 공산주의 위협을 마치 암처럼, 시작되기 전에 즉시 제거하고 싶습니다." 어제(4일) 러시모어산 연설에서 공산주의가 미국에서 부상하고 있다고 주장한 것에 이어 미국 독립 250주년 기념 연설에서도 공산주의 위협을 또 강조..', '【 앵커멘트 】 이런 가운데 트럼프 대통령이 미국 독립 기념 250주년 연설에서 공산주의자가 암과 같다며 번지기 전에 즉시 제거해야 한다고 주장했습니다. 어제(4일)에 이어 이틀째 공산주의를 언급한 건데, 지지층 결집을 노린 걸로 풀이됩니다. 이상협 기자가 보도합니다. 【 기자 】 연단에 오른 트럼프 미국 대통령이 공산주의의 위험을 경고합니다. ▶ 인터뷰 : 도널드 트럼프 / 미국 대통령 - "우리는 공산주의 위협을 마치 암처럼, 시작되기 전에 즉시 제거하고 싶습니다." 어제(4일) 러시모어산 연설에서 공산주의가 미국에서 부상하고 있다고 주장한 것에 이어 미국 독립 250주년 기념 연설에서도 공산주의 위협을 또 강조한 겁니다. ▶ 인터뷰 : 도널드 트럼프 / 미국 대통령 - "우리는 우리나라에 공산주의자를 원하지 않습니다. 공산주의는 결코 성공한 적이 없고 앞으로도 성공할 수 없습니다." 오는 11월 중간선거를 앞두고 민주당 등 자신의 반대 진영을 ''공산주의자''로 규정하고, 지지층 결집을 호소한 것으로 풀이됩니다. 트럼프 대통령 연설은 폭풍 예보로 예정 시간보다 약 1시간 늦게 시작해 40분간 이어졌습니다. 85만 발의 폭죽이 투입된 독립 기념 불꽃놀이도 지연돼 현지 시각 자정에서야 시작할 수 있었습니다. 날씨 탓에 미국 전역에서 독립 기념행사가 취소되거나 지연되는 사례가 속출했습니다. 섭씨 38도가 넘는 폭염으로 독립 기념 행진 중 가장 큰 규모인 워싱턴 D.C. 행진을 비롯해 미국 각지에서 행진 행사가 취소됐습니다. MBN뉴스 이상협입니다. [lee.sanghyub@mbn.co.kr] 영상편집 : 이주호', 'crawl', 'MBN', '2026-07-05 19:30:00', '보수', 'ready', 'https://www.mbn.co.kr/player/videojs/png/ic_caution.png', '2026-07-07 06:04:53', '2026-07-07 18:59:35.14601', NULL);
